def _safe_filename(s: str) -> str:
    """Make a string safe to use as a filename (Windows-friendly)."""
    s = (s or "").strip()
    s = re.sub(r'[\\/:*?\"<>|]+', "_", s)
    s = re.sub(r"\s+", " ", s).strip()
    s = s.replace(" ", "_")
    return s[:120] if len(s) > 120 else s


