@st.cache_data(show_spinner=False)
def _load_customer_store_map() -> Dict[str, List[Dict[str, str]]]:
    """Load cms_id -> store list mapping from exported customer_profiles.csv."""
    try:
        base_dir = pathlib.Path(__file__).resolve().parent
        # Preferred: auto-exported customer profiles
        csv_path = base_dir / "DocMate_DATA" / "exports" / "customer_profile" / "customer_profiles.csv"
        # Support user-provided singular filename too
        if not csv_path.exists():
            alt = base_dir / "DocMate_DATA" / "exports" / "customer_profile" / "customer_profile.csv"
            csv_path = alt if alt.exists() else csv_path
        if not csv_path.exists():
            return {}
        raw = csv_path.read_text(encoding="utf-8", errors="ignore")
    except Exception:
        return {}

    # Tolerate files where entire rows are quoted: "a,b,c"
    lines = []
    for line in raw.splitlines():
        ln = line.strip()
        if ln.startswith('"') and ln.endswith('"') and "," in ln:
            ln = ln[1:-1]
        lines.append(ln)
    data = "\n".join(lines)

    out: Dict[str, List[Dict[str, str]]] = {}
    try:
        reader = csv.DictReader(io.StringIO(data))
    except Exception:
        return {}

    for row in reader:
        if not row:
            continue
        cms = (
            row.get("cms_customer_id")
            or row.get("cms_id")
            or row.get("CMS_ID")
            or row.get("cmsid")
            or ""
        ).strip().upper()
        store_id = (row.get("store_id") or row.get("STORE_ID") or row.get("storeid") or "").strip()
        store_name = (
            row.get("trading_name")
            or row.get("store_name")
            or row.get("STORE_NAME")
            or row.get("store")
            or ""
        ).strip()
        mobile_cms_id = (
            row.get("mobile_cms_id")
            or row.get("MOBILE_CMS_ID")
            or row.get("mobilecmsid")
            or ""
        ).strip().upper()
        if not cms or not store_name:
            continue
        out.setdefault(cms, []).append(
            {"store_id": store_id, "store_name": store_name, "mobile_cms_id": mobile_cms_id}
        )

    # Deduplicate while preserving order
    for cms_id, rows in list(out.items()):
        seen = set()
        deduped = []
        for r in rows:
            key = (r.get("store_id") or "", r.get("store_name") or "")
            if key in seen:
                continue
            seen.add(key)
            deduped.append(r)
        out[cms_id] = deduped

    return out


def _get_store_options_for_cms(cms_id: str) -> List[Dict[str, str]]:
    if not cms_id:
        return []
    return _load_customer_store_map().get(cms_id.strip().upper(), [])


def _parse_simple_yaml(text: str) -> Dict[str, str]:
    data: Dict[str, str] = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if ":" not in line:
            continue
        key, val = line.split(":", 1)
        key = key.strip()
        val = val.strip().strip('"').strip("'")
        data[key] = val
    return data


def _read_customer_db_cred() -> Dict[str, str]:
    try:
        cred_path = pathlib.Path(__file__).resolve().parent / "customer_db_cred.yaml"
        if not cred_path.exists():
            return {}
        return _parse_simple_yaml(cred_path.read_text(encoding="utf-8", errors="ignore"))
    except Exception:
        return {}


def _read_dynamics_db_cred() -> Dict[str, str]:
    return _v18_dynamics.read_credentials(pathlib.Path(__file__).resolve().parent, _parse_simple_yaml)


def _write_customer_db_cred(patch: Dict[str, str]) -> Tuple[bool, str]:
    """Update customer_db_cred.yaml with provided keys (preserve existing fields)."""
    try:
        cred_path = pathlib.Path(__file__).resolve().parent / "customer_db_cred.yaml"
        current = _read_customer_db_cred()
        current.update({k: str(v) for k, v in (patch or {}).items() if v is not None})
        lines = [
            f"server : {current.get('server','')}",
            f"port : {current.get('port','')}",
            f"database : \"{current.get('database','')}\"",
            f"username : \"{current.get('username','')}\"",
            f"password : \"{current.get('password','')}\"",
            f"driver: \"{current.get('driver','ODBC Driver 17 for SQL Server')}\"",
        ]
        cred_path.write_text("\n".join(lines) + "\n", encoding="utf-8")
        return True, str(cred_path)
    except Exception as e:
        return False, str(e)


def _fetch_store_db_config(cms_id: str, store_id: str) -> Optional[Dict[str, Any]]:
    cms = (cms_id or "").strip()
    sid = (store_id or "").strip()
    if not cms or not sid:
        return None
    url = f"https://vbr.subango.com/api/storeip/{cms}/{sid}"
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            body = resp.read().decode("utf-8", errors="ignore")
        data = json.loads(body)
        if isinstance(data, list) and data:
            return data[0]
        if isinstance(data, dict):
            return data
    except Exception as e:
        try:
            _log_event(f"WARNING store API fetch failed: {e}")
        except Exception:
            pass
    return None


