def _build_conn_str_from_cred(cfg: Dict[str, str]) -> str:
    server = (cfg.get("server", ".") or ".").strip()
    port = (cfg.get("port") or "").strip()
    if port and ("," not in server) and (":" not in server):
        server = f"{server},{port}"
    database = cfg.get("database", "")
    username = cfg.get("username", "")
    password = cfg.get("password", "")
    driver = cfg.get("driver", "ODBC Driver 17 for SQL Server")
    encrypt = (cfg.get("encrypt") or "no").strip().lower()
    trust_cert = (cfg.get("trust_server_certificate") or "yes").strip().lower()
    return (
        f"DRIVER={{{driver}}};"
        f"SERVER={server};"
        f"DATABASE={database};"
        f"UID={username};"
        f"PWD={password};"
        f"Encrypt={encrypt};"
        f"TrustServerCertificate={trust_cert};"
    )


def _test_sqlserver_connection() -> Tuple[bool, str]:
    cfg = _read_customer_db_cred()
    if not cfg:
        return False, "customer_db_cred.yaml not found or empty"
    try:
        import pyodbc
        conn_str = _build_conn_str_from_cred(cfg)
        conn = pyodbc.connect(conn_str, timeout=5)
        conn.close()
        return True, "Connection successful"
    except Exception as e:
        return False, f"Connection failed: {e}"

