def _coerce_table_number(value: Any) -> Any:
    text = str(value or "").strip()
    if not text:
        return ""
    sign = -1.0 if text.endswith("-") else 1.0
    text = text.rstrip("-").strip()
    m = re.search(r"-?\d+(?:\.\d+)?", text)
    if not m:
        return ""
    try:
        return sign * float(m.group(0))
    except Exception:
        return ""


def _normalize_purchase_table_ocr_lines(ocr_lines: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    page_dims: Dict[int, Tuple[float, float]] = {}
    prepared: List[Tuple[Dict[str, Any], Tuple[float, float, float, float]]] = []

    for line in list(ocr_lines or []):
        if not isinstance(line, dict):
            continue
        bbox = line.get("bbox")
        text = str(line.get("text") or "").strip()
        if not text or not bbox:
            continue
        page = int(_coerce_table_number(line.get("page")) or 1)

        if isinstance(bbox, dict):
            left = _safe_float(bbox.get("left"), default=0.0)
            top = _safe_float(bbox.get("top"), default=0.0)
            right = _safe_float(bbox.get("right"), default=0.0)
            bottom = _safe_float(bbox.get("bottom"), default=0.0)
            if bool(bbox.get("normalized")) and 0.0 <= left <= 1.0 and 0.0 <= right <= 1.0:
                prepared.append((line, (left, top, right, bottom)))
                page_w = _safe_float(bbox.get("page_width"), default=0.0)
                page_h = _safe_float(bbox.get("page_height"), default=0.0)
                if page_w > 0 and page_h > 0:
                    prev_w, prev_h = page_dims.get(page, (0.0, 0.0))
                    page_dims[page] = (max(prev_w, page_w), max(prev_h, page_h))
                continue

        bbox_tuple = _ix_bbox_to_tuple(bbox)
        if not bbox_tuple:
            continue
        x0, y0, x1, y1 = bbox_tuple
        prepared.append((line, (x0, y0, x1, y1)))
        prev_w, prev_h = page_dims.get(page, (0.0, 0.0))
        declared_w = _safe_float(line.get("page_width"), default=0.0)
        declared_h = _safe_float(line.get("page_height"), default=0.0)
        page_dims[page] = (
            max(prev_w, declared_w, x1),
            max(prev_h, declared_h, y1),
        )

    normalized_lines: List[Dict[str, Any]] = []
    for line, coords in prepared:
        page = int(_coerce_table_number(line.get("page")) or 1)
        bbox = line.get("bbox")
        if isinstance(bbox, dict):
            left = _safe_float(bbox.get("left"), default=0.0)
            top = _safe_float(bbox.get("top"), default=0.0)
            right = _safe_float(bbox.get("right"), default=0.0)
            bottom = _safe_float(bbox.get("bottom"), default=0.0)
            if bool(bbox.get("normalized")) and 0.0 <= left <= 1.0 and 0.0 <= right <= 1.0:
                page_w = _safe_float(bbox.get("page_width"), default=page_dims.get(page, (0.0, 0.0))[0])
                page_h = _safe_float(bbox.get("page_height"), default=page_dims.get(page, (0.0, 0.0))[1])
                normalized_lines.append(
                    {
                        "text": str(line.get("text") or ""),
                        "page": page,
                        "bbox": {
                            "left": left,
                            "top": top,
                            "right": right,
                            "bottom": bottom,
                            "page_width": page_w,
                            "page_height": page_h,
                            "normalized": True,
                        },
                    }
                )
                continue

        page_w, page_h = page_dims.get(page, (0.0, 0.0))
        x0, y0, x1, y1 = coords
        if page_w <= 0:
            page_w = max(x1, 1.0)
        if page_h <= 0:
            page_h = max(y1, 1.0)
        normalized_lines.append(
            {
                "text": str(line.get("text") or ""),
                "page": page,
                "bbox": {
                    "left": max(0.0, min(1.0, x0 / page_w)),
                    "top": max(0.0, min(1.0, y0 / page_h)),
                    "right": max(0.0, min(1.0, x1 / page_w)),
                    "bottom": max(0.0, min(1.0, y1 / page_h)),
                    "page_width": page_w,
                    "page_height": page_h,
                    "normalized": True,
                },
            }
        )
    return normalized_lines


def _segment_purchase_table_token_lines(token_lines: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    by_page: Dict[int, List[Dict[str, Any]]] = {}
    for line in list(token_lines or []):
        if not isinstance(line, dict):
            continue
        text = str(line.get("text") or "").strip()
        bbox = line.get("bbox")
        page = int(_coerce_table_number(line.get("page")) or 1)
        if not text or not isinstance(bbox, dict):
            continue
        by_page.setdefault(page, []).append(line)

    segmented: List[Dict[str, Any]] = []
    row_tol = 0.0065
    base_gap = 0.012

    for page, lines in by_page.items():
        rows: List[List[Dict[str, Any]]] = []
        for line in sorted(
            lines,
            key=lambda item: (
                (_safe_float((item.get("bbox") or {}).get("top")) + _safe_float((item.get("bbox") or {}).get("bottom"))) / 2.0,
                _safe_float((item.get("bbox") or {}).get("left")),
            ),
        ):
            bbox = line.get("bbox") or {}
            y = (_safe_float(bbox.get("top")) + _safe_float(bbox.get("bottom"))) / 2.0
            if not rows:
                rows.append([line])
                continue
            prev = rows[-1]
            prev_y = sum(
                (_safe_float((item.get("bbox") or {}).get("top")) + _safe_float((item.get("bbox") or {}).get("bottom"))) / 2.0
                for item in prev
            ) / max(len(prev), 1)
            if abs(y - prev_y) <= row_tol:
                rows[-1].append(line)
            else:
                rows.append([line])

        for row in rows:
            parts: List[List[Dict[str, Any]]] = []
            current: List[Dict[str, Any]] = []
            prev_right: Optional[float] = None
            prev_height = 0.0
            for token in sorted(row, key=lambda item: _safe_float((item.get("bbox") or {}).get("left"))):
                bbox = token.get("bbox") or {}
                left = _safe_float(bbox.get("left"))
                right = _safe_float(bbox.get("right"))
                top = _safe_float(bbox.get("top"))
                bottom = _safe_float(bbox.get("bottom"))
                height = max(0.0, bottom - top)
                if not current:
                    current = [token]
                    prev_right = right
                    prev_height = height
                    continue
                gap = left - float(prev_right or 0.0)
                join_gap = max(base_gap, prev_height * 0.6, height * 0.6)
                if gap <= join_gap:
                    current.append(token)
                else:
                    parts.append(current)
                    current = [token]
                prev_right = right
                prev_height = max(prev_height, height)
            if current:
                parts.append(current)

            for part in parts:
                xs = [_safe_float((item.get("bbox") or {}).get("left")) for item in part]
                ys = [_safe_float((item.get("bbox") or {}).get("top")) for item in part]
                x1s = [_safe_float((item.get("bbox") or {}).get("right")) for item in part]
                y1s = [_safe_float((item.get("bbox") or {}).get("bottom")) for item in part]
                text = " ".join(str(item.get("text") or "").strip() for item in part if str(item.get("text") or "").strip()).strip()
                if not text:
                    continue
                bbox0 = part[0].get("bbox") or {}
                segmented.append(
                    {
                        "text": text,
                        "page": page,
                        "bbox": {
                            "left": min(xs),
                            "top": min(ys),
                            "right": max(x1s),
                            "bottom": max(y1s),
                            "page_width": _safe_float(bbox0.get("page_width"), default=0.0),
                            "page_height": _safe_float(bbox0.get("page_height"), default=0.0),
                            "normalized": True,
                        },
                    }
                )
    return segmented


def _build_google_style_purchase_payload(
    *,
    source_file: str,
    mime_type: str,
    raw_text: str,
    ocr_lines: List[Dict[str, Any]],
) -> Dict[str, Any]:
    lines_by_page: Dict[int, List[Dict[str, Any]]] = {}
    for line in list(ocr_lines or []):
        if not isinstance(line, dict):
            continue
        text = str(line.get("text") or "").strip()
        bbox = line.get("bbox") or {}
        page = int(_coerce_table_number(line.get("page")) or 1)
        if not text or not isinstance(bbox, dict):
            continue
        lines_by_page.setdefault(page, []).append(line)

    pages: List[Dict[str, Any]] = []
    ordered_page_texts: List[str] = []
    ordered_lines: List[Dict[str, Any]] = []

    for page in sorted(lines_by_page):
        page_lines = sorted(
            lines_by_page[page],
            key=lambda item: (
                (_safe_float((item.get("bbox") or {}).get("top")) + _safe_float((item.get("bbox") or {}).get("bottom"))) / 2.0,
                _safe_float((item.get("bbox") or {}).get("left")),
            ),
        )
        ordered_lines.extend(page_lines)
        line_texts = [str(line.get("text") or "").strip() for line in page_lines if str(line.get("text") or "").strip()]
        page_text = "\n".join(line_texts).strip()
        ordered_page_texts.extend(line_texts)
        sample_bbox = (page_lines[0].get("bbox") or {}) if page_lines else {}
        pages.append(
            {
                "page": page,
                "width": _safe_float(sample_bbox.get("page_width"), default=0.0),
                "height": _safe_float(sample_bbox.get("page_height"), default=0.0),
                "line_count": len(line_texts),
                "line_text": page_text,
            }
        )

    line_text = "\n".join(ordered_page_texts).strip()
    return {
        "source_file": source_file,
        "mime_type": mime_type or "application/pdf",
        "page_count": len(pages),
        "raw_text": raw_text or line_text,
        "line_text": line_text or raw_text,
        "pages": pages,
        "ocr_lines": ordered_lines,
    }


def _looks_like_valid_purchase_table_rows(rows: List[Dict[str, Any]]) -> bool:
    valid_rows = [row for row in list(rows or []) if isinstance(row, dict)]
    if not valid_rows:
        return False

    numeric_qty_re = re.compile(r"^-?\d+(?:\.\d+)?-?$")
    complete = 0
    blank_code = 0
    bad_qty = 0
    for row in valid_rows:
        code = str(row.get("code") or "").strip()
        desc = str(row.get("description") or "").strip()
        case_pack = str(row.get("Case Pack") or "").strip()
        unit_size = str(row.get("Unit Size") or "").strip()
        qty = str(row.get("Quantity") or "").strip()
        total_net = str(row.get("Total/Net") or "").strip()
        unit_price = str(row.get("Unit Price") or "").strip()
        if not code:
            blank_code += 1
        if code and desc and (case_pack or unit_size) and numeric_qty_re.match(qty) and (total_net or unit_price):
            complete += 1
        if qty and not numeric_qty_re.match(qty):
            bad_qty += 1

    total = len(valid_rows)
    return (complete / total) >= 0.45 and (blank_code / total) <= 0.25 and (bad_qty / total) <= 0.25


def _purchase_table_payload_from_result(res: Dict[str, Any]) -> Dict[str, Any]:
    raw_text = (
        str(res.get("confidence_raw_text") or "").strip()
        or ((str(res.get("text") or "") + "\n" + str(res.get("text_hint") or "")).strip())
    )
    cache_key = str(res.get("ocr_cache_key") or "").strip()
    ocr_lines = list(res.get("ocr_lines_snapshot") or [])
    if not ocr_lines:
        ocr_lines = _OCR_LINES_CACHE.get(cache_key) or []
    ocr_lines = _normalize_purchase_table_ocr_lines(ocr_lines)
    if not ocr_lines:
        token_lines = list(res.get("ocr_token_lines_snapshot") or [])
        if not token_lines:
            token_lines = _OCR_TOKEN_LINES_CACHE.get(cache_key) or []
        if token_lines:
            ocr_lines = _segment_purchase_table_token_lines(_normalize_purchase_table_ocr_lines(token_lines))
    return _build_google_style_purchase_payload(
        source_file=str(res.get("file") or ""),
        mime_type=str(res.get("mime") or "application/pdf"),
        raw_text=raw_text,
        ocr_lines=ocr_lines,
    )


def _template_training_text_from_result(res: Dict[str, Any], file_name: str = "") -> str:
    """Assemble all local text sources that can teach/test a supplier template."""
    if not isinstance(res, dict):
        return str(file_name or "")
    parts: List[str] = []
    for key in ("confidence_raw_text", "debug_text", "text", "text_hint", "line_text"):
        value = str(res.get(key) or "").strip()
        if value:
            parts.append(value)

    cache_key = str(res.get("ocr_cache_key") or "").strip()
    for snapshot_key, cache in (
        ("ocr_lines_snapshot", _OCR_LINES_CACHE),
        ("ocr_token_lines_snapshot", _OCR_TOKEN_LINES_CACHE),
    ):
        ocr_lines = list(res.get(snapshot_key) or [])
        if not ocr_lines and cache_key:
            ocr_lines = list(cache.get(cache_key) or [])
        try:
            line_text = _text_from_ocr_lines(_normalize_purchase_table_ocr_lines(ocr_lines))
        except Exception:
            line_text = ""
        if line_text:
            parts.append(line_text)

    if file_name or res.get("file"):
        parts.append(str(file_name or res.get("file") or ""))

    deduped: List[str] = []
    seen: set[str] = set()
    for part in parts:
        txt = str(part or "").strip()
        if not txt:
            continue
        key = re.sub(r"\s+", " ", txt[:2000]).casefold()
        if key in seen:
            continue
        seen.add(key)
        deduped.append(txt)
    return "\n".join(deduped).strip()


def _purchase_table_payload_looks_corrupt(payload: Optional[Dict[str, Any]]) -> bool:
    if not isinstance(payload, dict):
        return True
    raw_text = str(payload.get("raw_text") or "")
    line_text = str(payload.get("line_text") or "")
    source_file = str(payload.get("source_file") or payload.get("file_name") or "")
    suspect_markers = (".mv", '"page.mv_', '"line.mv_', '"top": 0.mv', '"processor": {.mv')
    hay = "\n".join([source_file, raw_text[:4000], line_text[:4000]])
    return any(marker in hay for marker in suspect_markers)


def _purchase_table_payload_from_debug_dump(res: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    file_name = os.path.basename(str(res.get("file") or "").strip())
    if not file_name:
        return None

    debug_dir = Path("DocMate_DATA") / "debug"
    if not debug_dir.is_dir():
        return None

    try:
        candidates = sorted(debug_dir.rglob("*.json"))
    except Exception:
        return None

    for candidate in candidates:
        try:
            payload = json.loads(candidate.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(payload, dict):
            continue
        source_file = os.path.basename(str(payload.get("source_file") or payload.get("file_name") or "").strip())
        if source_file != file_name:
            continue
        ocr_lines = _normalize_purchase_table_ocr_lines(list(payload.get("ocr_lines") or []))
        if not ocr_lines:
            continue
        raw_text = str(payload.get("raw_text") or "")
        built = _build_google_style_purchase_payload(
            source_file=str(res.get("file") or ""),
            mime_type=str(res.get("mime") or "application/pdf"),
            raw_text=raw_text,
            ocr_lines=ocr_lines,
        )
        if _purchase_table_payload_looks_corrupt(built):
            continue
        return built
    return None


def _purchase_table_payload_from_gdocai_ocr(res: Dict[str, Any], settings: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if not _gdocai_is_configured(settings):
        return None
    processor_id = _gdocai_ocr_processor_id(settings)
    if not processor_id:
        return None
    file_bytes = res.get("file_bytes")
    if not isinstance(file_bytes, (bytes, bytearray)) or not file_bytes:
        return None

    extractor = GoogleDocumentAIOcrExtractor(
        project_id=str(_gdocai_setting(settings, "gdocai_project_id", "document_ai_project_id") or "").strip(),
        location=str(_gdocai_setting(settings, "gdocai_location", "document_ai_location") or "").strip(),
        processor_id=processor_id,
        credentials_json=_gdocai_credentials_json(settings),
    )
    if not extractor.is_available():
        return None

    ocr_result = extractor.extract_text(
        bytes(file_bytes),
        mime_type=str(res.get("mime") or "application/pdf"),
        file_name=str(res.get("file") or ""),
        doc_text=str(res.get("confidence_raw_text") or res.get("text") or ""),
    )
    ocr_lines = _normalize_purchase_table_ocr_lines(list((ocr_result or {}).get("ocr_lines") or []))
    if not ocr_lines:
        return None
    segmented_lines = _segment_purchase_table_token_lines(ocr_lines)
    if segmented_lines:
        ocr_lines = segmented_lines
    return _build_google_style_purchase_payload(
        source_file=str(res.get("file") or ""),
        mime_type=str(res.get("mime") or "application/pdf"),
        raw_text=str((ocr_result or {}).get("raw_text") or res.get("confidence_raw_text") or ""),
        ocr_lines=ocr_lines,
    )


def _map_purchase_table_rows_to_app_items(rows: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    mapped: List[Dict[str, Any]] = []
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        qty_value = _coerce_table_number(row.get("Quantity"))
        line_net_value = _coerce_table_number(row.get("Total/Net"))
        mapped.append(
            {
                "lineNo": _coerce_table_number(row.get("line_no")) or (len(mapped) + 1),
                "code": str(row.get("code") or "").strip(),
                "description": str(row.get("description") or "").strip(),
                "rowTag": "",
                "pmp": str(row.get("pmp") or "").strip(),
                "casePack": _coerce_table_number(row.get("Case Pack")),
                "unitSize": str(row.get("Unit Size") or "").strip(),
                "qty": qty_value,
                "totalUnits": _coerce_table_number(row.get("Total units")),
                "unitPrice": _coerce_table_number(row.get("Unit Price")),
                "lineNet": line_net_value,
                "vatCode": str(row.get("VAT code") or "").strip(),
                "vatRate": _coerce_table_number(row.get("VAT %")),
                "vatAmount": _coerce_table_number(row.get("VAT Amount")),
                "lineGross": _coerce_table_number(row.get("Gross")),
                "stdRrp": _coerce_table_number(row.get("Std RRP")),
                "por": str(row.get("por") or "").strip(),
                "isVoid": bool((qty_value != "" and float(qty_value) < 0) or (line_net_value != "" and float(line_net_value) < 0)),
            }
        )
    return mapped


def _booker_engine_rows(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    try:
        response = _booker_engine_build_response(payload or {})
    except Exception:
        return []
    rows: List[Dict[str, Any]] = []
    for item in list(response.get("line_items") or []):
        if not isinstance(item, dict):
            continue
        rows.append(
            {
                "line_no": item.get("line_no"),
                "page": item.get("page"),
                "code": str(item.get("code") or "").strip(),
                "description": str(item.get("description") or "").strip(),
                "pmp": str(item.get("pmp") or "").strip(),
                "Case Pack": item.get("case_pack"),
                "Unit Size": str(item.get("unit_size") or "").strip(),
                "Quantity": item.get("quantity"),
                "Total units": item.get("total_units"),
                "Unit Price": item.get("unit_price"),
                "Total/Net": item.get("total_net"),
                "VAT code": str(item.get("vat_code") or "").strip(),
                "VAT %": item.get("vat_percent"),
                "VAT Amount": item.get("vat_amount"),
                "Gross": item.get("gross"),
                "Std RRP": item.get("std_rrp"),
                "por": str(item.get("por") or "").strip(),
            }
        )
    return rows


def _booker_engine_header(payload: Dict[str, Any]) -> Dict[str, Any]:
    try:
        response = _booker_engine_build_response(payload or {})
    except Exception:
        return {}

    line_items = list(response.get("line_items") or [])

    def _sum_field(key: str) -> float:
        total = 0.0
        for item in line_items:
            if isinstance(item, dict):
                total += _safe_float(item.get(key))
        return round(total, 2)

    hay = "\n".join(
        [
            str((payload or {}).get("raw_text") or ""),
            str((payload or {}).get("line_text") or ""),
        ]
    )
    gross_total = round(_safe_float(response.get("invoice_total")), 2)
    vat_total = 0.0
    net_total = 0.0

    collapsed_hay = re.sub(r"\s+", " ", hay or " ").strip()
    footer_match = re.search(
        r"\bTOTALS?\s*:\s*GOODS\s+([0-9,]+\.[0-9]{2})"
        r".{0,500}?\bVAT\s+([0-9,]+\.[0-9]{2})"
        r".{0,160}?\bINVOICE\s+TOTAL\s+([0-9,]+\.[0-9]{2})\b",
        collapsed_hay,
        flags=re.I,
    )
    if footer_match:
        net_total = round(_safe_float(footer_match.group(1)), 2)
        vat_total = round(_safe_float(footer_match.group(2)), 2)
        gross_total = round(_safe_float(footer_match.group(3)), 2)

    vat_matches = re.findall(
        r"\bVAT\b\s*[:\-]?\s*([0-9]+\.[0-9]{2})(?=\s*(?:[-]{3,}|INVOICE\s+TOTAL|$))",
        hay,
        flags=re.I,
    )
    if vat_total <= 0 and vat_matches:
        try:
            vat_total = round(float(vat_matches[-1]), 2)
        except Exception:
            vat_total = 0.0

    if net_total <= 0 and gross_total > 0 and vat_total > 0:
        net_total = round(gross_total - vat_total, 2)

    if net_total <= 0:
        goods_matches = re.findall(r"TOTALS?\s*:\s*GOODS\s*([0-9]+\.[0-9]{2})", hay, flags=re.I)
        if goods_matches:
            try:
                net_total = round(float(goods_matches[-1]), 2)
            except Exception:
                net_total = 0.0

    if net_total <= 0:
        net_total = round(_sum_field("total_net"), 2)
    if vat_total <= 0:
        vat_total = round(_sum_field("vat_amount"), 2)
    if gross_total <= 0:
        gross_total = round(_sum_field("gross"), 2)
    if gross_total <= 0 and net_total > 0:
        gross_total = round(net_total + vat_total, 2)

    return {
        "supplierName": "Booker",
        "invoiceNumber": str(response.get("invoice_number") or "").strip(),
        "invoiceDate": str(response.get("invoice_date") or "").strip(),
        "totalNet": net_total,
        "totalVat": vat_total,
        "totalGross": gross_total,
    }


def _booker_expected_item_count(payload: Dict[str, Any]) -> int:
    hay = "\n".join(
        [
            str((payload or {}).get("raw_text") or ""),
            str((payload or {}).get("line_text") or ""),
        ]
    )
    matches = re.findall(r"\bTOTAL\s+ITEMS?\s*[:\-]?\s*(\d{1,4})\b", hay, flags=re.I)
    if not matches:
        return 0
    try:
        return int(matches[-1])
    except Exception:
        return 0


def _booker_expected_qty_match(expected_qty: float, mapped_qty: float, row_count: int = 0) -> Tuple[bool, float, str]:
    """Compare Booker footer case quantity with mapped quantity.

    Scanned Booker footers often lose the decimal point, e.g. 48.8 becomes 488.
    Treat that as a match and ignore clearly implausible footer quantities so a
    valid rebuilt OCR table is not rejected.
    """
    expected = _safe_float(expected_qty)
    mapped = _safe_float(mapped_qty)
    rows = int(row_count or 0)
    if expected <= 0 or mapped <= 0:
        return True, expected, "not_available"
    if abs(mapped - expected) <= 0.05:
        return True, expected, "exact"
    expected_decimal = round(expected / 10.0, 2)
    if expected >= 100 and abs(mapped - expected_decimal) <= 0.25:
        return True, expected_decimal, "decimal_dropped"
    if rows > 0 and expected > max(250.0, float(rows * 8)):
        return True, expected, "implausible_ignored"
    return False, expected, "mismatch"


def _purchase_rows_totals(rows: List[Dict[str, Any]]) -> Dict[str, float]:
    net = 0.0
    vat = 0.0
    gross = 0.0
    qty = 0.0
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        net += _safe_float(row.get("Total/Net"))
        vat += _safe_float(row.get("VAT Amount"))
        gross += _safe_float(row.get("Gross"))
        qty += _safe_float(row.get("Quantity"))
    return {"net": round(net, 2), "vat": round(vat, 2), "gross": round(gross, 2), "qty": round(qty, 2)}


def _purchase_items_header_error(header: Dict[str, Any], items: List[Dict[str, Any]]) -> float:
    if not items:
        return float("inf")
    try:
        line_net = round(sum(_safe_float(i.get("lineNet")) for i in items if isinstance(i, dict)), 2)
        line_vat = round(sum(_effective_line_vat(i) for i in items if isinstance(i, dict)), 2)
        line_gross = round(sum(_effective_line_gross(i) for i in items if isinstance(i, dict)), 2)
        header_net = round(_safe_float((header or {}).get("totalNet")), 2)
        header_vat = round(_safe_float((header or {}).get("totalVat")), 2)
        header_gross = round(_safe_float((header or {}).get("totalGross")), 2)
        err = 0.0
        if header_net > 0:
            err += abs(line_net - header_net)
        if header_vat > 0:
            err += abs(line_vat - header_vat)
        if header_gross > 0:
            err += abs(line_gross - header_gross)
        return round(err, 2)
    except Exception:
        return float("inf")


def _booker_purchase_rows_score(rows: List[Dict[str, Any]], header: Dict[str, Any], expected_items: int) -> float:
    totals = _purchase_rows_totals(rows)
    score = 0.0
    header_net = round(_safe_float((header or {}).get("totalNet")), 2)
    header_vat = round(_safe_float((header or {}).get("totalVat")), 2)
    header_gross = round(_safe_float((header or {}).get("totalGross")), 2)
    if header_net > 0:
        score += abs(totals["net"] - header_net)
    if header_vat > 0:
        score += abs(totals["vat"] - header_vat)
    if header_gross > 0:
        score += abs(totals["gross"] - header_gross)
    # Booker footer "TOTAL ITEMS" is total case quantity, not product-row count.
    # For scanned invoices OCR can drop the decimal point (48.8 -> 488), so this
    # signal must never dominate financial reconciliation when ranking parsers.
    if expected_items > 0:
        qty_ok, expected_qty_normalized, qty_reason = _booker_expected_qty_match(
            expected_items,
            totals["qty"],
            len(rows or []),
        )
        if qty_reason in {"exact", "decimal_dropped", "mismatch"}:
            score += min(abs(totals["qty"] - expected_qty_normalized), 20.0) * (0.5 if qty_ok else 1.0)
    return round(score, 4)


def _booker_best_purchase_rows(payload: Dict[str, Any]) -> Tuple[List[Dict[str, Any]], str, Dict[str, Any]]:
    header = _booker_engine_header(payload)
    expected_items = _booker_expected_item_count(payload)

    candidates: List[Tuple[str, List[Dict[str, Any]]]] = []
    engine_rows = _booker_engine_rows(payload)
    if engine_rows:
        candidates.append(("booker_invoice_engine", engine_rows))

    try:
        supplier, purchase_rows = _purchase_table_build_rows(payload or {})
    except Exception:
        supplier, purchase_rows = "", []
    if supplier == "BOOKER" and purchase_rows:
        candidates.append(("purchase_table_build_rows", purchase_rows))

    best_name = ""
    best_rows: List[Dict[str, Any]] = []
    best_score = float("inf")
    audits = []
    for name, rows in candidates:
        if not _looks_like_valid_purchase_table_rows(rows):
            audits.append({"engine": name, "rows": len(rows or []), "valid": False})
            continue
        score = _booker_purchase_rows_score(rows, header, expected_items)
        totals = _purchase_rows_totals(rows)
        audits.append(
            {
                "engine": name,
                "rows": len(rows or []),
                "valid": True,
                "score": score,
                "net": totals["net"],
                "vat": totals["vat"],
                "gross": totals["gross"],
                "qty": totals["qty"],
            }
        )
        if score < best_score:
            best_name = name
            best_rows = rows
            best_score = score

    meta = {
        "expected_items": expected_items,
        "selected": best_name,
        "candidates": audits,
    }
    if not best_rows and engine_rows:
        best_name = "booker_invoice_engine"
        best_rows = engine_rows
        meta["selected"] = best_name
    return best_rows, best_name, meta


def _apply_booker_header_override(
    header: Dict[str, Any],
    override_header: Dict[str, Any],
    items: List[Dict[str, Any]],
) -> Dict[str, Any]:
    if not header or not override_header:
        return header

    current = {
        "totalNet": round(_safe_float(header.get("totalNet")), 2),
        "totalVat": round(_safe_float(header.get("totalVat")), 2),
        "totalGross": round(_safe_float(header.get("totalGross")), 2),
    }
    candidate = {
        "totalNet": round(_safe_float(override_header.get("totalNet")), 2),
        "totalVat": round(_safe_float(override_header.get("totalVat")), 2),
        "totalGross": round(_safe_float(override_header.get("totalGross")), 2),
    }
    if candidate["totalGross"] <= 0:
        return header

    calc_net = round(sum(_safe_float(i.get("lineNet")) for i in (items or [])), 2)
    calc_vat = round(sum(_effective_line_vat(i) for i in (items or [])), 2)
    calc_gross = round(sum(_effective_line_gross(i) for i in (items or [])), 2)

    current_matches_lines = (
        abs(current["totalNet"] - calc_net) <= 1.0
        and abs(current["totalVat"] - calc_vat) <= 1.0
        and abs(current["totalGross"] - calc_gross) <= 1.0
    )
    candidate_self_consistent = abs((candidate["totalNet"] + candidate["totalVat"]) - candidate["totalGross"]) <= 0.5
    should_override = candidate_self_consistent and (
        current["totalGross"] <= 0
        or abs(current["totalGross"] - candidate["totalGross"]) > 1.0
        or abs(current["totalVat"] - candidate["totalVat"]) > 1.0
        or abs(current["totalNet"] - candidate["totalNet"]) > 1.0
        or current_matches_lines
    )
    if not should_override:
        return header

    for key in ("invoiceNumber", "invoiceDate"):
        value = str(override_header.get(key) or "").strip()
        if value:
            header[key] = value
    if not str(header.get("supplierName") or "").strip():
        header["supplierName"] = str(override_header.get("supplierName") or "").strip()
    header["totalNet"] = candidate["totalNet"]
    header["totalVat"] = candidate["totalVat"]
    header["totalGross"] = candidate["totalGross"]
    header["_booker_header_override_used"] = True
    return header


def _purchase_table_override(
    res: Dict[str, Any],
    settings: Dict[str, Any],
    *,
    force: bool = False,
) -> Tuple[List[Dict[str, Any]], bool]:
    audit: Dict[str, Any] = {
        "eligible": False,
        "used": False,
        "reason": "",
        "score": 0,
        "review_threshold": int(settings.get("auto_confidence_review_threshold", 65) or 65),
        "blockers": [],
        "source_file": str(res.get("file") or ""),
        "ocr_cache_key_present": bool(str(res.get("ocr_cache_key") or "").strip()),
        "ocr_lines_count": 0,
        "row_count": 0,
        "mapped_count": 0,
        "supplier": "",
        "error": "",
        "payload_source": "",
    }
    if not _is_purchase_like_doc_type(str(res.get("doc_type") or "")):
        audit["reason"] = "doc_type_not_purchase_invoice"
        res["_purchase_table_audit"] = audit
        return [], False
    conf = res.get("confidence") or {}
    score = int(conf.get("score") or 0)
    blockers = list(conf.get("blockers") or [])
    review_threshold = audit["review_threshold"]
    audit["score"] = score
    audit["blockers"] = blockers
    if (not force) and score >= review_threshold and not blockers:
        audit["reason"] = "confidence_not_low"
        res["_purchase_table_audit"] = audit
        return [], False
    audit["eligible"] = True
    if force:
        audit["reason"] = "forced_rebuild_requested"
    cached = res.get("_purchase_table_override_items")
    cached_rows = res.get("_purchase_table_override_rows")
    cached_version = int(_coerce_table_number(res.get("_purchase_table_override_version")) or 0)
    cached_valid = (
        isinstance(cached, list)
        and bool(cached)
        and cached_version == _PURCHASE_TABLE_OVERRIDE_VERSION
        and _looks_like_valid_purchase_table_rows(list(cached_rows or []))
    )
    if isinstance(cached, list) and cached and not cached_valid:
        audit["reason"] = "cached_invalid_retry"
    elif isinstance(cached, list) and not cached and isinstance(cached_rows, list) and not cached_rows:
        audit["reason"] = "cached_empty_retry"
    try:
        payload_candidates: List[Tuple[str, Dict[str, Any]]] = []
        payload_from_result = _purchase_table_payload_from_result(res)
        if payload_from_result and not _purchase_table_payload_looks_corrupt(payload_from_result):
            payload_candidates.append(("app_ocr_cache", payload_from_result))
        payload_from_gdocai = _purchase_table_payload_from_gdocai_ocr(res, settings)
        if payload_from_gdocai and not _purchase_table_payload_looks_corrupt(payload_from_gdocai):
            payload_candidates.append(("gdocai_ocr", payload_from_gdocai))
        payload_from_debug_dump = _purchase_table_payload_from_debug_dump(res)
        if payload_from_debug_dump:
            payload_candidates.append(("debug_ocr_dump", payload_from_debug_dump))

        last_rows: List[Dict[str, Any]] = []
        last_mapped: List[Dict[str, Any]] = []
        last_supplier = ""
        last_source = ""

        for payload_source, payload in payload_candidates:
            audit["payload_source"] = payload_source
            audit["ocr_lines_count"] = len(payload.get("ocr_lines") or [])
            audit["ocr_token_lines_count"] = len(
                list(res.get("ocr_token_lines_snapshot") or []) or (_OCR_TOKEN_LINES_CACHE.get(str(res.get("ocr_cache_key") or "").strip()) or [])
            )
            audit["raw_text_len"] = len(str(payload.get("raw_text") or ""))
            audit["line_text_len"] = len(str(payload.get("line_text") or ""))
            audit["raw_text_preview"] = str(payload.get("raw_text") or "")[:1500]
            audit["line_text_preview"] = str(payload.get("line_text") or "")[:1500]
            audit["ocr_lines_sample"] = list(payload.get("ocr_lines") or [])[:20]
            supplier_guess = _purchase_table_detect_supplier_family(payload)
            if supplier_guess == "BOOKER":
                rows, selected_booker_engine, booker_selection_meta = _booker_best_purchase_rows(payload)
                res["_purchase_table_override_header"] = _booker_engine_header(payload)
                _supplier = supplier_guess
                audit["supplier_engine"] = selected_booker_engine or "booker_invoice_engine"
                audit["booker_selection"] = booker_selection_meta
            else:
                _supplier, rows = _purchase_table_build_rows(payload)
                res["_purchase_table_override_header"] = {}
                audit["supplier_engine"] = "purchase_table_build_rows"
            mapped = _map_purchase_table_rows_to_app_items(rows)
            mapped = _normalise_promo_quantities(mapped)
            if _supplier == "BOOKER":
                try:
                    mapped = _booker_split_items_with_embedded_codes(mapped)
                except Exception:
                    pass
                try:
                    mapped = _attach_row_text_from_ocr(mapped, list(payload.get("ocr_lines") or []))
                    mapped = _booker_fix_pack_size_from_rawrow(mapped)
                    mapped = _booker_fix_qty_price_from_rawrow(mapped)
                    mapped = _booker_fix_qty_price_from_text(
                        mapped,
                        "\n".join(
                            [
                                str(payload.get("line_text") or ""),
                                str(payload.get("raw_text") or ""),
                            ]
                        ),
                    )
                    mapped = _booker_fix_single_qty_unit_price(mapped)
                    mapped = _booker_fix_vat_from_rawrow(mapped)
                    mapped = _booker_fix_std_por_from_rawrow(mapped)
                    mapped = _normalise_promo_quantities(mapped)
                except Exception:
                    pass
            rows_valid = _looks_like_valid_purchase_table_rows(rows)
            last_rows = rows
            last_mapped = mapped
            last_supplier = _supplier
            last_source = payload_source
            expected_booker_items = _booker_expected_item_count(payload) if _supplier == "BOOKER" else 0
            mapped_qty = round(sum(_safe_float(it.get("qty")) for it in mapped if isinstance(it, dict)), 2)
            mapped_net = round(sum(_safe_float(it.get("lineNet")) for it in mapped if isinstance(it, dict)), 2)
            header_net = round(_safe_float((res.get("header") or {}).get("totalNet")), 2)
            override_header_net = round(_safe_float((res.get("_purchase_table_override_header") or {}).get("totalNet")), 2)
            booker_header_net = header_net if header_net > 0 else override_header_net
            expected_qty_ok, expected_qty_normalized, expected_qty_reason = _booker_expected_qty_match(
                expected_booker_items,
                mapped_qty,
                len(rows or []),
            )
            if (
                _supplier == "BOOKER"
                and mapped
                and expected_booker_items > 0
                and expected_qty_ok
                and (booker_header_net <= 0 or abs(mapped_net - booker_header_net) <= 0.05)
            ):
                rows_valid = True
            audit["supplier"] = _supplier
            audit["row_count"] = len(rows)
            audit["rows_valid"] = rows_valid
            audit["mapped_count"] = len(mapped)
            if mapped and rows_valid:
                current_items_for_compare = list(res.get("items") or [])
                current_header_error = _purchase_items_header_error(res.get("header") or {}, current_items_for_compare)
                mapped_header_error = _purchase_items_header_error(res.get("header") or {}, mapped)
                audit["current_header_error"] = current_header_error
                audit["mapped_header_error"] = mapped_header_error
                # Never replace an already reconciled supplier-specific parse
                # with a weaker generic OCR-table rebuild. This applies to all
                # suppliers, including A F Blakemore, not only Booker.
                if (
                    current_items_for_compare
                    and current_header_error <= 1.0
                    and mapped_header_error > current_header_error + 1.0
                ):
                    audit["used"] = False
                    audit["reason"] = "existing_items_reconcile_better"
                    res["_purchase_table_override_items"] = []
                    res["_purchase_table_override_rows"] = rows
                    res["_purchase_table_override_version"] = _PURCHASE_TABLE_OVERRIDE_VERSION
                    res["_purchase_table_audit"] = audit
                    return current_items_for_compare, False
                if expected_booker_items > 0:
                    audit["expected_case_qty"] = expected_booker_items
                    audit["expected_case_qty_normalized"] = expected_qty_normalized
                    audit["expected_case_qty_reason"] = expected_qty_reason
                    audit["mapped_case_qty"] = mapped_qty
                    if not expected_qty_ok:
                        audit["reason"] = "rebuilt_rows_qty_mismatch_retry"
                        continue
                audit["used"] = True
                audit["reason"] = "rebuilt_rows_used_forced" if force else "rebuilt_rows_used"
                res["_purchase_table_override_items"] = mapped
                res["_purchase_table_override_rows"] = rows
                res["_purchase_table_override_version"] = _PURCHASE_TABLE_OVERRIDE_VERSION
                res["_purchase_table_audit"] = audit
                return mapped, True

        audit["supplier"] = last_supplier
        audit["row_count"] = len(last_rows)
        audit["mapped_count"] = len(last_mapped)
        audit["payload_source"] = last_source or audit.get("payload_source") or ""
        if cached_valid:
            audit["reason"] = "cached_result"
            audit["mapped_count"] = len(cached)
            audit["row_count"] = len(res.get("_purchase_table_override_rows") or [])
            audit["used"] = True
            res["_purchase_table_audit"] = audit
            return cached, True
        audit["used"] = False
        audit["reason"] = "rebuilt_rows_invalid" if last_mapped else "no_rows_built"
        res["_purchase_table_override_items"] = last_mapped
        res["_purchase_table_override_rows"] = last_rows
        res["_purchase_table_override_version"] = _PURCHASE_TABLE_OVERRIDE_VERSION
        res["_purchase_table_audit"] = audit
        return last_mapped, False
    except Exception as e:
        try:
            _log_event(f"Low-confidence purchase-table override failed: {e}", file_name=str(res.get('file') or ''))
        except Exception:
            pass
        if cached_valid:
            audit["reason"] = "cached_result_after_exception"
            audit["mapped_count"] = len(cached)
            audit["row_count"] = len(res.get("_purchase_table_override_rows") or [])
            audit["used"] = True
            audit["error"] = str(e)
            res["_purchase_table_audit"] = audit
            return cached, True
        audit["reason"] = "exception"
        audit["error"] = str(e)
        res["_purchase_table_override_items"] = []
        res["_purchase_table_override_rows"] = []
        res["_purchase_table_override_header"] = {}
        res["_purchase_table_override_version"] = _PURCHASE_TABLE_OVERRIDE_VERSION
        res["_purchase_table_audit"] = audit
        return [], False


def _purchase_table_items_fingerprint(items: List[Dict[str, Any]]) -> List[Tuple[str, str, float, float, float]]:
    out: List[Tuple[str, str, float, float, float]] = []
    for it in (items or []):
        if not isinstance(it, dict):
            continue
        out.append(
            (
                re.sub(r"\D+", "", str(it.get("code") or "")),
                str(it.get("description") or "").strip().upper(),
                round(_safe_float(it.get("qty")), 3),
                round(_safe_float(it.get("unitPrice")), 2),
                round(_safe_float(it.get("lineNet")), 2),
            )
        )
    return out


def _purchase_table_override_needs_resync(
    current_items: List[Dict[str, Any]],
    override_items: List[Dict[str, Any]],
) -> bool:
    """Detect when UI/reporting drifted away from already-accepted purchase-table rows."""
    current_fp = _purchase_table_items_fingerprint(current_items)
    override_fp = _purchase_table_items_fingerprint(override_items)
    if not override_fp:
        return False
    if not current_fp:
        return True
    if len(current_fp) != len(override_fp):
        return True
    if current_fp == override_fp:
        return False
    current_net = round(sum(row[4] for row in current_fp), 2)
    override_net = round(sum(row[4] for row in override_fp), 2)
    if abs(current_net - override_net) > 0.05:
        return True
    mismatch_count = sum(1 for a, b in zip(current_fp, override_fp) if a != b)
    return mismatch_count > max(2, len(override_fp) // 10)

def _bytes_to_image(data: bytes):
    """Convert raw bytes to a PIL Image (used for previews)."""
    try:
        from PIL import Image  # pillow is a dependency of pdf2image/image handling
        img = Image.open(io.BytesIO(data))
        # Force-load to avoid lazy fp issues with closed BytesIO
        try:
            img.load()
        except Exception:
            pass
        return img
    except Exception:
        return None


def _ddmmyyyy_to_iso(s: str) -> str:
    """Convert common UK date formats to ISO yyyy-mm-dd.

    Accepts: dd/mm/yy, dd/mm/yyyy, dd-mm-yy, dd-mm-yyyy
    Returns original string if parsing fails.
    """
    if not s:
        return s
    t = str(s).strip()
    for fmt in ("%d/%m/%y", "%d/%m/%Y", "%d-%m-%y", "%d-%m-%Y"):
        try:
            return datetime.strptime(t, fmt).strftime("%Y-%m-%d")
        except Exception:
            pass
    return t




def _clean_booker_customer_name(nm: str) -> str:
    """Booker 'CUSTOMER <no> <name>' lines sometimes have PO/Customer PO appended.
    This strips common PO suffix patterns without damaging genuine business names.
    """
    if not nm:
        return nm
    s = str(nm).strip()
    # Remove trailing PO suffixes like 'PO 12345', 'P/O NO 12345', 'PO NUMBER: 12345'
    s = re.sub(r"\s+P\s*/\s*O\s*(?:NUMBER|NO\.?|#)?\s*[:\-]?\s*[A-Z0-9\-\/]{3,}.*$", "", s, flags=re.I)
    s = re.sub(r"\s+PO\s*(?:NUMBER|NO\.?|#)?\s*[:\-]?\s*[A-Z0-9\-\/]{3,}.*$", "", s, flags=re.I)
    # If still contains an obvious ' PO ' token near the end followed by digits, trim from there
    m = re.search(r"\s+PO\s+[0-9]{3,}\s*$", s, flags=re.I)
    if m:
        s = s[: m.start()].strip()
    return s.strip(" -:|\t")



def _booker_extract_customer_name(extracted_text: str) -> str:
    """Best-effort Booker customer-name extraction from OCR/text layer.

    AUTO/Local parsing can miss customerName. This function:
    - Searches for 'Customer' anchors and captures inline/next-line values
    - Cleans common OCR separators (|) and removes trailing 'Customer'
    - Removes PO number suffixes and other obvious non-name fragments
    """
    t = extracted_text or ""
    if not t.strip():
        return ""
    lines = [ln.strip() for ln in t.splitlines()]

    def _bad_line(s: str) -> bool:
        if not s:
            return True
        up = s.upper().strip()
        if up.replace("*", "").strip() == "COPY":
            return True
        if re.search(r"\b(INVOICE|DATE|TIME|NUMBER|TOTAL|VAT|NET|GROSS|DELIVERY|PO|P\.O\.?|PAGE)\b", up):
            return True
        return False

    # 1) Direct 'Customer: <name>' or 'Customer <no> <name>' style
    for ln in lines:
        if re.search(r"\bCUSTOMER\b", ln, flags=re.I):
            m = re.search(r"\bCUSTOMER\b\s*(?:NAME)?\s*[:\-]?\s*(.{3,120})$", ln, flags=re.I)
            if m:
                cand = _clean_booker_customer_name(m.group(1).strip())
                # If it's only a number, treat as a number-only line and try next line
                if cand and not re.fullmatch(r"\d{4,}", cand):
                    return cand

            # Pattern: CUSTOMER <no> <name...>
            m2 = re.search(r"\bCUSTOMER\b\s+(\d{4,})\s+(.{2,80})$", ln, flags=re.I)
            if m2:
                cand = _clean_booker_customer_name(m2.group(2).strip())
                if cand:
                    return cand

    # 2) 'Customer <number>' line followed by name on next line(s)
    for i, ln in enumerate(lines):
        if re.search(r"\bCUSTOMER\b", ln, flags=re.I):
            m = re.search(r"\bCUSTOMER\b\s+(\d{4,})\s*$", ln, flags=re.I)
            if m:
                for j in range(1, 5):
                    if i + j >= len(lines):
                        break
                    nxt = (lines[i + j] or "").strip()
                    if _bad_line(nxt):
                        continue
                    cand = _clean_booker_customer_name(nxt)
                    if cand:
                        return cand

    # 3) 'Customer' line followed by name on next line(s)
    for i, ln in enumerate(lines):
        if re.fullmatch(r"\s*CUSTOMER\s*(?:NAME)?\s*[:\-]?\s*", ln, flags=re.I) or re.fullmatch(r"\s*CUSTOMER\s*(?:NAME)?\s*", ln, flags=re.I):
            for j in range(1, 5):
                if i + j >= len(lines):
                    break
                nxt = (lines[i + j] or "").strip()
                if _bad_line(nxt):
                    continue
                cand = _clean_booker_customer_name(nxt)
                if cand:
                    return cand

    # 4) Heuristic: first strong Mr/Mrs/Ms line (avoid address lines)
    for ln in lines:
        if re.search(r"\b(MR|MRS|MS|MISS)\b", ln, flags=re.I) and re.search(r"[A-Z]", ln):
            if re.search(r"\b(ROAD|STREET|AVENUE|LANE|LTD|LIMITED|UNIT|POSTCODE)\b", ln, flags=re.I):
                continue
            cand = _clean_booker_customer_name(ln)
            if cand:
                return cand

    return ""


def _booker_autofill_customer_name(header: Dict[str, Any], extracted_text: str, template_hit: Optional[Dict[str, Any]] = None) -> None:
    """Autofill Booker customer name reliably.

    Priority:
    1) Keep an already-good extracted header value.
    2) Try OCR/text-layer extraction heuristics.
    3) Fall back to supplier template default_customer_name (learned from Admin edits).
    """
    try:
        cn = _collapse_spaces(str(header.get("customerName") or "").replace("|", " ").strip())
    except Exception:
        cn = str(header.get("customerName") or "").strip()

    bad = (not cn) or (cn.lower() == "customer") or bool(re.search(r"\bcustomer\b\s*$", cn, flags=re.I))
    bad = bad or ("|" in cn)

    # If header contains 'CUSTOMER NO' etc without the actual name, treat as bad
    if not bad and re.search(r"\bNO\b\s*[:\-]?\s*\d{3,}", cn, flags=re.I) and not re.search(r"\b(MR|MRS|MS|MISS)\b", cn, flags=re.I):
        bad = True

    if bad:
        txt = extracted_text or ""
        cand = ""

        # A) Capture from the first title-based segment on a line containing CUSTOMER
        if txt:
            for ln in [x.strip() for x in txt.splitlines() if x.strip()]:
                if re.search(r"\bCUSTOMER\b", ln, flags=re.I):
                    m = re.search(r"\b(MR|MRS|MS|MISS)\b\s+(.{2,80})$", ln, flags=re.I)
                    if m:
                        cand = (m.group(1) + " " + m.group(2)).strip()
                        break

        # A2) Booker OCR often splits title and surname across lines:
        if not cand and txt:
            lines = [ln.strip() for ln in txt.splitlines() if ln.strip()]
            for i, ln in enumerate(lines):
                if re.search(r"^CUSTOMER\s+\d+\s*$", ln, flags=re.I):
                    # collect next 1-3 lines until PO/DATE/TIME/TILL
                    parts = []
                    for j in range(i + 1, min(i + 4, len(lines))):
                        seg = lines[j].strip()
                        if re.search(r"\bPO\b|\bPO\s*NUMBER\b|\bP/O\b|\bDATE\b|\bTIME\b|\bTILL\b|\bOPERATOR\b", seg, flags=re.I):
                            break
                        parts.append(seg)
                    if parts:
                        cand = " ".join(parts).strip()
                        break
                    # Pattern: CUSTOMER <no> <name...>
                    m2 = re.search(r"\bCUSTOMER\b\s+\d+\s+(.{2,80})$", ln, flags=re.I)
                    if m2:
                        cand = m2.group(1).strip()
                        break

        # B) Original extractor (covers 'Customer: <name>' and next-line cases)
        if not cand and txt:
            cand = _booker_extract_customer_name(txt)

        # C) Look for 'DELIVER TO' / 'ACCOUNT NAME' style anchors (some Booker layouts)
        if not cand and txt:
            lines = [ln.strip() for ln in txt.splitlines()]
            anchors = ("DELIVER TO", "DELIVERED TO", "ACCOUNT NAME", "ACCOUNT", "SITE")
            for i, ln in enumerate(lines):
                if any(a in ln.upper() for a in anchors):
                    # capture anything after ':' on same line
                    m = re.search(r":\s*(.{3,90})$", ln)
                    if m and not re.search(r"\b(INVOICE|DATE|NUMBER|TOTAL|VAT|NET|GROSS)\b", m.group(1), flags=re.I):
                        cand = m.group(1).strip()
                        break
                    # else check next non-empty line
                    for j in range(1, 4):
                        if i + j >= len(lines):
                            break
                        nxt = (lines[i + j] or "").strip()
                        if not nxt:
                            continue
                        if re.search(r"\b(INVOICE|DATE|NUMBER|TOTAL|VAT|NET|GROSS|DELIVERY|PO|P\.O\.)\b", nxt, flags=re.I):
                            continue
                        cand = nxt
                        break
                if cand:
                    break

        # D) Booker OCR often splits title and surname across lines:
        #    "MR" / "M" / "GANESAMOORTHY"
        if not cand and txt:
            lines = [ln.strip() for ln in txt.splitlines() if ln.strip()]
            for i, ln in enumerate(lines):
                if ln.upper() in ("MR", "MRS", "MS", "MISS"):
                    parts = [ln.upper()]
                    # collect next 1-3 lines as name parts (skip obvious address/labels)
                    for j in range(1, 4):
                        if i + j >= len(lines):
                            break
                        nxt = lines[i + j].strip()
                        if not nxt:
                            continue
                        if re.search(r"\b(INVOICE|DATE|NUMBER|TOTAL|VAT|NET|GROSS|DELIVERY|PO|P\.O\.?|TEL|TEL:|FAX|TILL|OPERATOR)\b", nxt, flags=re.I):
                            break
                        # stop if it looks like an address line
                        if re.search(r"\b(ROAD|STREET|AVENUE|LANE|UNIT|EST|IND|POSTCODE|KENT|SURREY)\b", nxt, flags=re.I):
                            break
                        parts.append(nxt)
                    if len(parts) >= 2:
                        cand = " ".join(parts)
                        break

        cand = _clean_booker_customer_name(_collapse_spaces(str(cand).replace("|", " ").strip()))
        # remove trailing 'Customer' word if OCR stuck it on the end
        cand = re.sub(r"\s+CUSTOMER\s*$", "", cand, flags=re.I).strip()

        # E) Explicit Booker store name: "U SAVE"
        if (not cand) and txt and ("U SAVE" in txt.upper()):
            cand = "U SAVE"

        # F) Fallback to "Customer <number>" if a customer number is present
        if not cand and txt:
            m_cust = re.search(r"\bCUSTOMER\s+(\d{4,})\b", txt, flags=re.I)
            if m_cust:
                cand = f"Customer {m_cust.group(1)}"

        # D) Template default customer name fallback (learned from admin edit)
        if not cand:
            try:
                cfg = (template_hit or {}).get("config") or {}
                dc = _collapse_spaces(str(cfg.get("default_customer_name") or "").strip())
                if dc:
                    cand = dc
            except Exception:
                pass

        if cand:
            # Guard: avoid PO NUMBER artifacts
            if re.search(r"\bPO\b|\bPO\s*NUMBER\b|\bP/O\b", cand, flags=re.I):
                cand = ""
        if cand:
            header["customerName"] = cand
            header["customer_name"] = cand
    else:
        header["customerName"] = _clean_booker_customer_name(cn)
        header["customer_name"] = _clean_booker_customer_name(cn)


def _normalise_supplier_name(name: str) -> str:
    s = str(name or "").strip()
    if not s:
        return s
    s = re.sub(r"\s+", " ", s).strip()
    s_u = s.upper()
    if "BOOKER" in s_u:
        return "Booker"
    return s


def _booker_like_header_fallback(text: str) -> Dict[str, Any]:
    """Lightweight Booker-like header parser used as a fallback for missing fields."""
    t = text or ""
    if not t.strip():
        return {}
    def _pick(patterns: List[str]) -> str:
        for p in patterns:
            m = re.search(p, t, flags=re.I)
            if m:
                return (m.group(1) or "").strip()
        return ""

    supplier = _pick([
        r"\bSupplier\b\s*[:\-]\s*(.+)",
        r"\bFrom\b\s*[:\-]\s*(.+)",
    ])
    if not supplier and re.search(r"\bBOOKER\b", t, flags=re.I):
        supplier = "Booker"
    supplier = _normalise_supplier_name(supplier)

    lines = [ln.strip() for ln in t.splitlines() if (ln or "").strip()]

    customer = _pick([
        r"\bCustomer\b\s*[:\-]\s*(.+)",
        r"\bBill\s*To\b\s*[:\-]\s*(.+)",
        r"\bShip\s*To\b\s*[:\-]\s*(.+)",
        r"\bSold\s*To\b\s*[:\-]\s*(.+)",
    ])
    if not customer:
        for i, ln in enumerate(lines):
            if ln.upper().startswith("CUSTOMER "):
                m = re.match(r"^CUSTOMER\s+\d+\s+(.*)$", ln.strip(), flags=re.I)
                if m and m.group(1).strip():
                    nm = m.group(1).strip()
                    nm = re.split(r"\bCUSTOMER\s*PO\b|\bPO\s*NUMBER\b|\bP/O\b", nm, flags=re.I)[0].strip()
                    customer = nm.title() if nm.isupper() else nm
                    break
                # If only customer number on this line, try next lines for title/name (skip PO/DATE/TIME/TILL)
                cand_parts: List[str] = []
                for j in range(i + 1, min(i + 6, len(lines))):
                    seg = lines[j].strip()
                    if not seg:
                        continue
                    if re.search(r"\bPO\b|\bPO\s*NUMBER\b|\bP/O\b|\bDATE\b|\bTIME\b|\bTILL\b|\bOPERATOR\b", seg, flags=re.I):
                        break
                    # Avoid catching another CUSTOMER line
                    if seg.upper().startswith("CUSTOMER "):
                        break
                    cand_parts.append(seg)
                cand = " ".join(cand_parts).strip()
                if cand:
                    customer = cand.title() if cand.isupper() else cand
                break
    # Guard: ignore PO number artifacts
    if customer and re.search(r"\bPO\b|\bPO\s*NUMBER\b|\bP/O\b", customer, flags=re.I):
        customer = ""

    doc_no = _pick([
        r"\bInvoice\s*(?:No|Number)?\b\s*[:\-]\s*([A-Z0-9\-\/]+)",
        r"\bCredit\s*(?:No|Number|Note\s*No|Note\s*Number)?\b\s*[:\-]\s*([A-Z0-9\-\/]+)",
        r"\bDocument\s*No\b\s*[:\-]\s*([A-Z0-9\-\/]+)",
        r"\bInvoice\s*Number\b[\s:\-#]{0,10}([A-Z0-9\-\/]{4,})",
        r"\bInvoice\s*No\b[\s:\-#]{0,10}([A-Z0-9\-\/]{4,})",
        r"\bCredit\s*Number\b[\s:\-#]{0,10}([A-Z0-9\-\/]{4,})",
        r"\bCredit\s*No\b[\s:\-#]{0,10}([A-Z0-9\-\/]{4,})",
        r"\bINVOICE\b[^\n\r]{0,60}\b([0-9]{5,})\b",
    ])
    if not doc_no:
        for i, ln in enumerate(lines):
            if re.search(r"\b(?:INVOICE|CREDIT)\s*(?:NUMBER|NO)\b", ln, flags=re.I):
                m = re.search(r"\b(?:INVOICE|CREDIT)\s*(?:NUMBER|NO)\b[^A-Z0-9]*([A-Z0-9\-\/]{4,})", ln, flags=re.I)
                if m:
                    doc_no = m.group(1).strip()
                    break
                # use next non-empty line
                for j in range(i + 1, min(i + 4, len(lines))):
                    m2 = re.search(r"\b([A-Z0-9\-\/]{4,})\b", lines[j], flags=re.I)
                    if m2:
                        doc_no = m2.group(1).strip()
                        break
            if doc_no:
                break

    doc_date = _pick([
        r"\b([0-9]{4}-[0-9]{2}-[0-9]{2})\b",
        r"\bInvoice\s*Date\b\s*[:\-]?\s*([0-9]{1,2}\s*[\/\-]\s*[0-9]{1,2}\s*[\/\-]\s*[0-9]{2,4})",
        r"\bCredit\s*Date\b\s*[:\-]?\s*([0-9]{1,2}\s*[\/\-]\s*[0-9]{1,2}\s*[\/\-]\s*[0-9]{2,4})",
        r"\bDate\b\s*[:\-]?\s*([0-9]{1,2}\s*[\/\-]\s*[0-9]{1,2}\s*[\/\-]\s*[0-9]{2,4})",
        r"\b(?:Issue\s*Date|Invoice\s*Date|Credit\s*Date|Date)\b\s*[:\-]?\s*([A-Za-z]{3,9}\.?\s+[0-9]{1,2},?\s+[0-9]{4})",
    ])
    if not doc_date:
        for i, ln in enumerate(lines):
            if re.search(r"\b(?:INVOICE\s*DATE|CREDIT\s*DATE|DATE)\b", ln, flags=re.I):
                m = re.search(r"\b(?:INVOICE\s*DATE|CREDIT\s*DATE|DATE)\b[^0-9]*([0-9]{1,2}[\/\-][0-9]{1,2}[\/\-][0-9]{2,4})", ln, flags=re.I)
                if m:
                    doc_date = m.group(1).strip()
                    break
                for j in range(i + 1, min(i + 3, len(lines))):
                    m2 = re.search(r"\b([0-9]{1,2}[\/\-][0-9]{1,2}[\/\-][0-9]{2,4})\b", lines[j])
                    if m2:
                        doc_date = m2.group(1).strip()
                        break
            if doc_date:
                break
    doc_date = _normalise_invoice_date_str(doc_date or "")

    def _money_from_lines(label_pats: List[str]) -> float:
        lines = [ln for ln in t.splitlines() if (ln or "").strip()]
        candidates: List[str] = []
        for ln in lines:
            for pat in label_pats:
                m = re.search(pat, ln, flags=re.I)
                if m:
                    candidates.append((m.group(1) or "").strip())
        if not candidates:
            return 0.0
        s = candidates[-1].replace(",", "").replace("Â£", "").replace("$", "").strip()
        try:
            return float(re.findall(r"-?\d+(?:\.\d+)?", s)[0])
        except Exception:
            return 0.0

    # Booker photos often misread line-items as totals. Keep totals conservative:
    # only accept explicit "TOTAL ..." labels (no SUB-TOTAL or SAVINGS).
    ex = _money_from_lines([
        r"\bTOTAL\s*EX\s*VAT\b\s*[:\-]?\s*([Ã‚Â£$]?\s*[0-9,]+(?:\.[0-9]{2})?)",
        r"\bNET\b\s*TOTAL\b\s*[:\-]?\s*([Ã‚Â£$]?\s*[0-9,]+(?:\.[0-9]{2})?)",
    ])
    vat = _money_from_lines([
        r"\bTOTAL\s*VAT\b\s*[:\-]?\s*([Ã‚Â£$]?\s*[0-9,]+(?:\.[0-9]{2})?)",
        r"\bVAT\s*TOTAL\b\s*[:\-]?\s*([Ã‚Â£$]?\s*[0-9,]+(?:\.[0-9]{2})?)",
    ])
    inc = _money_from_lines([
        r"\bINVOICE\s*TOTAL\b\s*[:\-]?\s*([Ã‚Â£$]?\s*[0-9,]+(?:\.[0-9]{2})?)",
        r"\bTOTAL\s*DUE\b\s*[:\-]?\s*([Ã‚Â£$]?\s*[0-9,]+(?:\.[0-9]{2})?)",
        r"\bAMOUNT\s*DUE\b\s*[:\-]?\s*([Ã‚Â£$]?\s*[0-9,]+(?:\.[0-9]{2})?)",
    ])
    if ex > 0.0 and vat > 0.0 and inc <= 0.0:
        inc = round(ex + vat, 2)

    cur = "GBP" if "Â£" in t else ("USD" if "$" in t else "GBP")

    return {
        "supplier_name": supplier,
        "customer_name": customer,
        "doc_number": doc_no,
        "doc_date": doc_date,
        "total_ex_vat": ex,
        "total_vat": vat,
        "total_inc_vat": inc,
        "currency": cur,
    }


def _guess_supplier_from_filename(filename: str) -> str:
    """Lightweight supplier guesser based on filename (used as a fallback)."""
    f = (filename or "").lower()
    if "booker" in f:
        return "BOOKER"
    if "parfett" in f:
        return "PARFETTS"
    if "dwg" in f or "drinks" in f or "wholesale group" in f:
        return "DWG"
    return ""


def _default_supplier_max_pages_map() -> Dict[str, int]:
    return {
        "BOOKER": 4,
        "PARFETTS": 6,
        "DHAMECHA": 12,
    }


def _coerce_supplier_max_pages_map(settings: Dict[str, Any]) -> Dict[str, int]:
    raw = {}
    try:
        raw = settings.get("supplier_max_pages", {}) or {}
    except Exception:
        raw = {}
    if isinstance(raw, str):
        try:
            raw = json.loads(raw)
        except Exception:
            raw = {}
    if not isinstance(raw, dict):
        raw = {}

    merged: Dict[str, int] = {}
    for k, v in _default_supplier_max_pages_map().items():
        try:
            merged[str(k).strip().upper()] = max(1, min(int(v), 50))
        except Exception:
            pass

    legacy_keys = {
        "BOOKER": settings.get("booker_max_pages", 4),
        "PARFETTS": settings.get("parfetts_max_pages", 6),
        "DHAMECHA": settings.get("dhamecha_max_pages", 12),
    }
    for k, v in legacy_keys.items():
        try:
            merged[str(k).strip().upper()] = max(1, min(int(v), 50))
        except Exception:
            pass

    for k, v in raw.items():
        key = str(k or "").strip().upper()
        if not key:
            continue
        try:
            merged[key] = max(1, min(int(v), 50))
        except Exception:
            continue
    return merged


def _supplier_max_pages_override(settings: Dict[str, Any], supplier_hint: str) -> Optional[int]:
    hint = str(supplier_hint or "").upper()
    if not hint:
        return None
    supplier_pages = _coerce_supplier_max_pages_map(settings)
    for key in sorted(supplier_pages.keys(), key=len, reverse=True):
        if key and key in hint:
            try:
                return int(supplier_pages[key])
            except Exception:
                continue
    return None



