def _sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def _cache_key_for_ocr(
    file_bytes: bytes,
    mime: str,
    engine: str,
    dpi: int,
    max_pages: int,
    force_pdf: bool,
    extra: str = "",
) -> str:
    """Stable cache key for OCR results (used by st.cache_data)."""
    h = _sha256_bytes(file_bytes)
    extra_s = (extra or "").strip()
    if extra_s:
        return f"{h}|{mime}|{(engine or '').lower()}|{int(dpi)}|{int(max_pages)}|{1 if force_pdf else 0}|{extra_s}"
    return f"{h}|{mime}|{(engine or '').lower()}|{int(dpi)}|{int(max_pages)}|{1 if force_pdf else 0}"


def _safe_eval_arith(expr: str) -> float | None:
    """Safely evaluate a simple arithmetic expression like '=57.98+11.60'.
    Allowed: digits, spaces, + - * / ( ) and decimal points.
    """
    expr = (expr or "").strip()
    if not expr:
        return None
    if expr.startswith("="):
        expr = expr[1:].strip()
    if not expr:
        return None
    if not re.fullmatch(r"[0-9\.\+\-\*\/\(\)\s]+", expr):
        return None

    try:
        node = ast.parse(expr, mode="eval")
    except Exception:
        return None

    def _eval(n):
        if isinstance(n, ast.Expression):
            return _eval(n.body)
        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):
            return float(n.value)
        if isinstance(n, ast.Num):
            return float(n.n)
        if isinstance(n, ast.UnaryOp) and isinstance(n.op, (ast.UAdd, ast.USub)):
            v = _eval(n.operand)
            return v if isinstance(n.op, ast.UAdd) else -v
        if isinstance(n, ast.BinOp) and isinstance(n.op, (ast.Add, ast.Sub, ast.Mult, ast.Div)):
            a = _eval(n.left)
            b = _eval(n.right)
            if isinstance(n.op, ast.Add):
                return a + b
            if isinstance(n.op, ast.Sub):
                return a - b
            if isinstance(n.op, ast.Mult):
                return a * b
            if isinstance(n.op, ast.Div):
                return float("nan") if b == 0 else (a / b)
        raise ValueError("disallowed")

    try:
        v = float(_eval(node))
        if math.isnan(v) or math.isinf(v):
            return None
        return v
    except Exception:
        return None


def _safe_float(x: object, default: float = 0.0) -> float:
    """Parse a value to float safely.

    - Treat None/blank as default
    - Treat NaN/Inf as default (prevents NaN propagation into totals/breakdowns)
    - Supports simple arithmetic formulas from the UI editor (e.g. '=57.98+11.60')
    - Extracts the first numeric token from strings (handles '', ',', '%' and OCR noise)
    """
    if x is None:
        return default

    # Fast path for numeric types (including numpy floats)
    if isinstance(x, (int, float)):
        try:
            v = float(x)
            if math.isnan(v) or math.isinf(v):
                return default
            return v
        except Exception:
            return default

    # Allow simple formula entry from the UI editor, e.g. '=57.98+11.60'
    if isinstance(x, str):
        s = x.strip()
        if not s or s.lower() in ("none", "null", "nan"):
            return default

        if s.startswith("=") or (re.search(r"[\+\*\/\(\)]", s) and re.search(r"\d", s)):
            v = _safe_eval_arith(s)
            if v is not None:
                # _safe_eval_arith already guards NaN/Inf
                return v

        # Normalise common symbols then extract first numeric token. Some Booker
        # void rows print trailing-minus values such as "22.29-".
        s = s.replace(",", "").replace("", "").replace("%", "")
        trailing_negative = bool(re.search(r"\d(?:\.\d+)?\s*-$", s))
        m = re.search(r"-?\d+(?:\.\d+)?", s)
        if not m:
            return default
        try:
            v = float(m.group(0))
            if trailing_negative and v > 0:
                v = -v
            if math.isnan(v) or math.isinf(v):
                return default
            return v
        except Exception:
            return default

    try:
        v = float(str(x))
        if math.isnan(v) or math.isinf(v):
            return default
        return v
    except Exception:
        return default


_FREE_DESC_GUARD_RE = re.compile(
    r"\b(SUGAR|ALCOHOL|FAT|GLUTEN|DAIRY|LACTOSE|CAFFEINE|CAFFEIN|CHOL(?:ESTEROL)?|NUT|SOY|SOYA|WHEAT|EGG|GELATIN|MEAT|MSG|GMO)\s+FREE\b",
    re.IGNORECASE,
)
_FREE_FROM_RE = re.compile(r"\bFREE\s+FROM\b", re.IGNORECASE)
_PROMO_LINE_RE = re.compile(
    r"\b(BUY\s*ANY|BUY\s*\d+|BUY\d+|MULTI\s*BUY|MULTIBUY|MULTI-BUY|PROMO|PROMOTION|DEAL|OFFER|SAVE|SAVING|"
    r"DISC(?:OUNT)?|GET\s*\d+(?:\s+\S+){0,3}\s+FREE|BUY\b.*\bFREE)\b",
    re.IGNORECASE,
)
_PROMO_STATEMENT_RE = re.compile(
    r"\b(SPEND\s*&\s*SAVE\s+STATEMENT|SPEND\s+AT\s+THIS\s+BRANCH|"
    r"TOBACCO\s+SPEND|NON[-\s]?TOBACCO\s+SPEND|TOTAL\s+SPEND|"
    r"TERMS\s*&\s*CONDITIONS\s+APPLY|STATEMENT\s+.*\bSPEND)\b",
    re.IGNORECASE,
)


def _has_free_token(text: str) -> bool:
    return bool(re.search(r"\b(FREE|FOC)\b", (text or "").upper()))


def _is_free_marker(desc: str, raw_txt: str = "", unit_price: object = None, line_net: object = None) -> bool:
    """Detect real FREE/FOC line markers without tripping on 'SUGAR FREE' style descriptions."""
    if not (_has_free_token(desc) or _has_free_token(raw_txt)):
        return False
    # If description clearly indicates a product attribute (e.g., SUGAR FREE), avoid marking as free.
    if _FREE_DESC_GUARD_RE.search(desc or "") or _FREE_FROM_RE.search(desc or ""):
        # Only allow if prices are zero (true free item)
        if _safe_float(unit_price, 0.0) > 0 or _safe_float(line_net, 0.0) > 0:
            return False
    # If prices are non-zero, do not treat as free
    if _safe_float(unit_price, 0.0) > 0 or _safe_float(line_net, 0.0) > 0:
        return False
    return True


def _is_promo_line_item(item: Dict[str, Any]) -> bool:
    if not isinstance(item, dict):
        return False
    code = str(item.get("code") or "").strip().upper()
    row_tag = str(item.get("rowTag") or "").strip().upper()
    desc = str(item.get("description") or "")
    raw = str(item.get("rawRow") or item.get("raw") or "")
    has_promo_text = bool(_PROMO_LINE_RE.search(desc) or _PROMO_LINE_RE.search(raw))
    has_discount_value = _safe_float(item.get("lineNet"), 0.0) < 0 or _safe_float(item.get("unitPrice"), 0.0) < 0
    if code == "PROMO":
        return True
    if row_tag == "PROMO":
        return has_promo_text or has_discount_value
    return has_promo_text


def _is_promo_statement_line(item: Dict[str, Any]) -> bool:
    if not isinstance(item, dict):
        return False
    text = " ".join(
        str(item.get(k) or "")
        for k in ("code", "description", "Description", "rawRow", "raw")
    )
    return bool(_PROMO_STATEMENT_RE.search(text))


def _normalise_promo_quantities(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Promo/discount rows affect value only; they must not increase case quantity."""
    out: List[Dict[str, Any]] = []
    for it in items or []:
        if not isinstance(it, dict):
            continue
        if _is_promo_statement_line(it):
            continue
        if not _is_promo_line_item(it):
            if str(it.get("rowTag") or "").strip().upper() == "PROMO":
                it["rowTag"] = ""
            out.append(it)
            continue
        it["casePack"] = 0
        it["unitSize"] = 0
        it["qty"] = 0.0
        it["totalUnits"] = 0.0
        it["unitPrice"] = 0.0
        it["stdRrp"] = 0.0
        it["por"] = 0.0
        if not str(it.get("rowTag") or "").strip():
            it["rowTag"] = "PROMO"
        out.append(it)
    return out


def _looks_like_number(s: str) -> bool:
    """Loose numeric detector for OCR tokens (supports currency and trailing P)."""
    if s is None:
        return False
    t = str(s).strip()
    if not t:
        return False
    t = t.replace("Ã‚Â£", "").replace("Â£", "").replace(",", "").replace("P", "")
    return bool(re.fullmatch(r"[-+]?\d+(?:\.\d+)?", t))




# -------------------------
# Formatting / HTML helpers
# -------------------------

import html


def _preview_enrich_items(items: List[Dict[str, Any]], vat_map: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Preview-only enrichment so the Template Test grid and VAT summary reconcile.

    - Applies vat_map (code -> rate) if vatCode present
    - Derives vatCode from vatRate if missing (best-effort, using inverse of vat_map)
    - Derives vatAmount and lineGross if missing
    """
    if not items:
        return items

    # Build inverse mapping: rate -> preferred code
    inverse: Dict[float, str] = {}
    if isinstance(vat_map, dict) and vat_map:
        # Preference order for UK suppliers
        pref = ["A", "B", "R", "Z", "S", "E"]
        # Normalise vat_map keys/values
        norm = {}
        for k, v in vat_map.items():
            try:
                kk = str(k).strip().upper()
                vv = float(v)
                norm[kk] = vv
            except Exception:
                continue
        for code in pref:
            if code in norm:
                inverse.setdefault(norm[code], code)
        # Add any remaining codes deterministically
        for code, rate in sorted(norm.items(), key=lambda x: x[0]):
            inverse.setdefault(rate, code)

        vat_map = norm  # use normalised map

    for it in items:
        try:
            code = (it.get("vatCode") or it.get("vat_code") or "")
            code = str(code).strip().upper() if code is not None else ""
            rate = _safe_float(it.get("vatRate") if "vatRate" in it else it.get("vat_rate"), default=0.0)
            net = _safe_float(it.get("lineNet") if "lineNet" in it else it.get("line_net"), default=0.0)

            # If we have a code but no/zero rate, apply template map
            if code and (rate == 0.0) and isinstance(vat_map, dict) and code in vat_map:
                rate = float(vat_map.get(code, 0.0))

            # If no code but rate present, derive best-effort code from inverse map
            if (not code) and rate and inverse:
                code = inverse.get(float(rate), "")

            it["vatCode"] = code if code else (it.get("vatCode") or None)
            it["vatRate"] = rate if rate else (it.get("vatRate") or 0.0)

            vat_amount_raw = it.get("vatAmount")
            vat_amount = None if vat_amount_raw is None else _safe_float(vat_amount_raw, default=0.0)
            if vat_amount_raw is None:
                vat_amount = round(net * rate / 100.0, 2) if (net and rate) else 0.0
            it["vatAmount"] = vat_amount

            gross_raw = it.get("lineGross")
            gross = None if gross_raw is None else _safe_float(gross_raw, default=0.0)
            if gross_raw is None:
                gross = round(net + vat_amount, 2)
            it["lineGross"] = gross

        except Exception:
            # Never break preview rendering because of one row
            continue

    return items

def _fill_header_totals_from_items(header: Dict[str, Any], items: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Fill missing header totals from line items (non-destructive)."""
    if not header or not items:
        return header

    try:
        net_sum = round(sum(_safe_float(i.get("lineNet")) for i in items), 2)
        vat_sum = round(sum(_safe_float(i.get("vatAmount")) for i in items), 2)
        gross_sum = round(sum(_safe_float(i.get("lineGross")) for i in items), 2)
    except Exception:
        return header

    if net_sum <= 0 and vat_sum <= 0 and gross_sum <= 0:
        return header

    if _safe_float(header.get("totalNet")) <= 0 and net_sum > 0:
        header["totalNet"] = net_sum
    if _safe_float(header.get("totalVat")) <= 0 and vat_sum > 0:
        header["totalVat"] = vat_sum
    if _safe_float(header.get("totalGross")) <= 0:
        if gross_sum > 0:
            header["totalGross"] = gross_sum
        else:
            net_v = _safe_float(header.get("totalNet"))
            vat_v = _safe_float(header.get("totalVat"))
            if net_v > 0 or vat_v > 0:
                header["totalGross"] = round(net_v + vat_v, 2)

    return _repair_implausible_header_total_set(header)


def _repair_implausible_header_total_set(header: Dict[str, Any]) -> Dict[str, Any]:
    """Fix impossible header total combinations without using line items.

    Common OCR/model failure: totalGross is copied into totalVat, e.g.
    Net=89.00, VAT=106.80, Gross=106.80. In that case VAT must be Gross-Net.
    """
    if not isinstance(header, dict):
        return header
    try:
        net = round(_safe_float(header.get("totalNet")), 2)
        vat = round(_safe_float(header.get("totalVat")), 2)
        gross = round(_safe_float(header.get("totalGross")), 2)
    except Exception:
        return header
    if net <= 0 or gross <= 0:
        return header

    derived_vat = round(gross - net, 2)
    if derived_vat < 0:
        return header

    if abs(gross - net) <= 0.02 and vat > 0 and abs(vat - net) <= 0.02:
        header["totalVat"] = 0.0
        return header

    if abs(gross - net) <= 0.02 and vat > 0:
        header["totalGross"] = round(net + vat, 2)
        return header

    vat_is_gross = vat > 0 and abs(vat - gross) <= 0.02 and gross > net
    vat_too_large = vat > max(net * 0.35, derived_vat + 2.0) and gross > net
    arithmetic_bad = abs((net + vat) - gross) > 0.5
    derived_rate_ok = derived_vat == 0.0 or 0.0 <= (derived_vat / max(net, 0.01)) <= 0.30
    if derived_rate_ok and arithmetic_bad and (vat_is_gross or vat_too_large):
        header["totalVat"] = derived_vat
    return header


def _extract_summary_charges_totals(text: str) -> Dict[str, float]:
    """Extract totals from invoices that print a Summary of Charges table.

    Example layout:
        Summary of Charges
        Amount  VAT  Total
        Licence Fees  171.00  34.20  205.20
        Service Fees   91.15  18.23  109.38
        TOTAL         262.15  52.43  314.58
    """
    raw = str(text or "")
    if not re.search(r"\bSummary\s+of\s+Charges\b", raw, flags=re.I):
        return {}
    if not re.search(r"\bAmount\b.{0,80}\bVAT\b.{0,80}\bTotal\b", re.sub(r"\s+", " ", raw), flags=re.I):
        return {}

    lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in raw.splitlines()]
    lines = [ln.strip() for ln in lines if ln and ln.strip()]
    if not lines:
        return {}

    def _money_values(value: str) -> List[float]:
        out: List[float] = []
        for tok in re.findall(r"-?\d[\d,]*\.\d{2}", str(value or "").replace("\u00a3", " ").replace("£", " ")):
            try:
                out.append(float(tok.replace(",", "")))
            except Exception:
                continue
        return out

    summary_idx = 0
    for idx, line in enumerate(lines):
        if re.search(r"\bSummary\s+of\s+Charges\b", line, flags=re.I):
            summary_idx = idx
            break

    best: Dict[str, float] = {}
    for idx in range(summary_idx, min(len(lines), summary_idx + 80)):
        line = lines[idx]
        line_stripped = line.strip()
        if line_stripped != "TOTAL" and not re.match(r"^\s*TOTAL\s+[-£\u00a3\d]", line_stripped):
            continue
        nearby = " ".join(lines[idx: min(len(lines), idx + 5)])
        nums = _money_values(nearby)
        if len(nums) >= 3:
            net, vat, gross = nums[0], nums[1], nums[2]
            if net > 0 and vat >= 0 and gross > 0 and abs((net + vat) - gross) <= 0.05:
                best = {"totalNet": round(net, 2), "totalVat": round(vat, 2), "totalGross": round(gross, 2)}
                break

    if best:
        return best

    for idx in range(summary_idx, min(len(lines), summary_idx + 120)):
        if not re.match(r"^\s*Grand\s+Total\b", lines[idx], flags=re.I):
            continue
        nearby = " ".join(lines[idx: min(len(lines), idx + 5)])
        nums = _money_values(nearby)
        if len(nums) >= 2:
            net, vat = nums[0], nums[1]
            if net > 0 and vat >= 0:
                return {"totalNet": round(net, 2), "totalVat": round(vat, 2), "totalGross": round(net + vat, 2)}
    return {}


def _repair_summary_charges_header_totals(header: Dict[str, Any], text: str) -> Dict[str, Any]:
    if not isinstance(header, dict):
        return header
    totals = _extract_summary_charges_totals(text or "")
    if not totals:
        return header
    parsed_net = round(_safe_float(totals.get("totalNet")), 2)
    parsed_vat = round(_safe_float(totals.get("totalVat")), 2)
    parsed_gross = round(_safe_float(totals.get("totalGross")), 2)
    if parsed_net <= 0 or parsed_gross <= 0:
        return header

    cur_net = round(_safe_float(header.get("totalNet")), 2)
    cur_vat = round(_safe_float(header.get("totalVat")), 2)
    cur_gross = round(_safe_float(header.get("totalGross")), 2)
    current_bad = (
        cur_net <= 0
        or cur_gross <= 0
        or abs((cur_net + cur_vat) - cur_gross) > 0.05
        or (cur_vat > 0 and cur_gross > 0 and abs(cur_vat - cur_gross) <= 0.02)
        or abs(cur_net - parsed_net) > 0.05
        or abs(cur_vat - parsed_vat) > 0.05
        or abs(cur_gross - parsed_gross) > 0.05
    )
    if current_bad:
        header["totalNet"] = parsed_net
        header["totalVat"] = parsed_vat
        header["totalGross"] = parsed_gross
    return header


def _repair_header_totals_from_items(header: Dict[str, Any], items: List[Dict[str, Any]], raw_text: str = "") -> Dict[str, Any]:
    """Repair implausible extracted header totals using reconciled line items.

    Intended for scanned PDFs where OCR captures VAT correctly but truncates
    net/gross totals in the invoice footer.
    """
    if not header or not items:
        return header
    try:
        net_sum = round(sum(_safe_float(i.get("lineNet")) for i in items), 2)
        vat_sum = round(sum(_safe_float(i.get("vatAmount")) for i in items), 2)
        gross_sum = round(sum(_safe_float(i.get("lineGross")) for i in items), 2)
        hdr_net = round(_safe_float(header.get("totalNet")), 2)
        hdr_vat = round(_safe_float(header.get("totalVat")), 2)
        hdr_gross = round(_safe_float(header.get("totalGross")), 2)
    except Exception:
        return header

    if net_sum <= 0 and vat_sum <= 0 and gross_sum <= 0:
        return header

    diff_net = round(net_sum - hdr_net, 2)
    diff_gross = round(gross_sum - hdr_gross, 2)
    vat_matches_items = abs(vat_sum - hdr_vat) <= 0.1 if hdr_vat > 0 and vat_sum > 0 else False
    same_gap = abs(diff_net - diff_gross) <= 0.2 and abs(diff_net) > 1.0
    implausible_header = (
        (hdr_vat > 0 and hdr_net > 0 and hdr_vat > (hdr_net * 0.5))
        or (hdr_gross > 0 and hdr_gross < hdr_vat)
        or (hdr_gross > 0 and hdr_net > 0 and abs((hdr_net + hdr_vat) - hdr_gross) <= 0.2 and same_gap and vat_matches_items)
    )

    # Extra confidence: footer totals are often missing or weak in scanned OCR text.
    raw_has_totals = bool(re.search(r"(TOTAL\s+VAT|TOTAL\s+DUE|INVOICE\s+TOTAL|NET\s+TOTAL|TOTAL\s+EX\s+VAT)", str(raw_text or ""), flags=re.I))

    if vat_matches_items and same_gap and (implausible_header or not raw_has_totals):
        header["totalNet"] = net_sum
        header["totalVat"] = vat_sum
        header["totalGross"] = gross_sum if gross_sum > 0 else round(net_sum + vat_sum, 2)
        return _repair_implausible_header_total_set(header)

    return _repair_implausible_header_total_set(header)


def _repair_dhamecha_header_totals(header: Dict[str, Any], items: List[Dict[str, Any]], raw_text: str = "") -> Dict[str, Any]:
    return _dhamecha_module_repair_header(header, items, raw_text)


def _dhamecha_reduce_duplicate_rows_to_header(
    items: List[Dict[str, Any]],
    header: Dict[str, Any],
    raw_text: str = "",
) -> List[Dict[str, Any]]:
    return _dhamecha_module_reduce_duplicates(items, header, raw_text)


def _norm_pack_tokens(s: str) -> str:
    """Normalise pack/size tokens like '6*1.5 lt' -> '6X1.5LT' and '1.5 lt' -> '1.5LT'."""
    # Fix OCR: "1t" -> "LT" (e.g., "1.51t" -> "1.5LT")
    s = re.sub(r"(\d+(?:\.\d+)?)1t\b", r"\1LT", s, flags=re.IGNORECASE)
    s = re.sub(r"\b1t\b", r"LT", s, flags=re.IGNORECASE)
    s = re.sub(
        r"(\d+(?:\.\d+)?)\s*[*xX]\s*(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
        r"\1X\2\3",
        s,
        flags=re.IGNORECASE,
    )
    s = re.sub(
        r"(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
        r"\1\2",
        s,
        flags=re.IGNORECASE,
    )
    return s

def _split_pack_size_token(tok: str) -> Tuple[Optional[int], str]:
    """Split combined pack/size tokens like '6X1.5LT' -> (6, '1.5LT')."""
    t = (tok or "").strip().upper()
    m = re.fullmatch(r"(\d+)[X*](\d+(?:\.\d+)?)(ML|L|LTR|LT|CL|G|KG|PK)", t)
    if not m:
        return None, ""
    try:
        pack = int(m.group(1))
    except Exception:
        pack = None
    return pack, f"{m.group(2)}{m.group(3)}"

def _fix_pack_size_from_description(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Extract trailing pack/size tokens from description when OCR placed them there."""
    if not items:
        return items

    def _is_size(tok: str) -> bool:
        t = (tok or "").strip().upper()
        if re.fullmatch(r"\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?S", t):
            return True
        if re.fullmatch(r"\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?(ROLL|ROLLS)", t):
            return True
        return False

    def _is_pm(tok: str) -> bool:
        return bool(re.fullmatch(r"PM\d+", (tok or "").strip().upper()))

    for it in items:
        try:
            cp = _safe_float(it.get("casePack"), default=0.0)
            us = str(it.get("unitSize") or "").strip()
            if (cp and cp > 0) and us:
                continue

            desc = str(it.get("description") or "").strip()
            desc = _norm_pack_tokens(desc)
            if not desc:
                continue

            toks = desc.split()
            if len(toks) < 2:
                continue

            last = toks[-1]
            prev = toks[-2] if len(toks) >= 2 else ""
            pm = toks[-3] if len(toks) >= 3 else ""

            if _is_size(last):
                pack_tok, size_tok = _split_pack_size_token(last)
                if pack_tok:
                    it["casePack"] = int(pack_tok)
                    it["unitSize"] = size_tok
                    cut = -1
                    if _is_pm(prev):
                        cut = -2
                    it["description"] = " ".join(toks[:cut]).strip()
                else:
                    try:
                        prev_v = float(prev)
                    except Exception:
                        prev_v = None
                    if prev_v is not None and abs(prev_v - round(prev_v)) < 1e-6:
                        it["casePack"] = int(prev_v)
                        it["unitSize"] = last
                        cut = -2
                        if _is_pm(pm):
                            cut = -3
                        it["description"] = " ".join(toks[:cut]).strip()
            # Update totalUnits if possible
            try:
                cp2 = _safe_float(it.get("casePack"), default=0.0)
                qty = _safe_float(it.get("qty"), default=0.0)
                if cp2 > 0 and qty > 0:
                    it["totalUnits"] = float(cp2) * float(qty)
            except Exception:
                pass
        except Exception:
            continue

    return items

def _booker_fix_pack_size_from_rawrow(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Booker-specific: override pack/size from rawRow when description parsing misassigns it."""
    if not items:
        return items

    def _is_size(tok: str) -> bool:
        t = (tok or "").strip().upper()
        if re.fullmatch(r"\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?S", t):
            return True
        if re.fullmatch(r"\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?(ROLL|ROLLS)", t):
            return True
        return False

    def _last_pack_size_from_line(line: str) -> Tuple[Optional[int], str]:
        toks = _norm_pack_tokens(line or "").split()
        last_pack = None
        last_size = ""
        for i in range(len(toks) - 1):
            a = toks[i]
            b = toks[i + 1]
            if _is_size(b):
                pack_tok, size_tok = _split_pack_size_token(b)
                if pack_tok:
                    last_pack = int(pack_tok)
                    last_size = size_tok
                    continue
                try:
                    v = float(a)
                except Exception:
                    v = None
                if v is not None and abs(v - round(v)) < 1e-6:
                    last_pack = int(v)
                    last_size = b
        return last_pack, last_size

    def _raw_for_item(it: Dict[str, Any]) -> str:
        raw = str(it.get("rawRow") or it.get("raw") or "").strip()
        code = re.sub(r"\D+", "", str(it.get("code") or ""))
        if raw and code:
            m = re.search(rf"\b{re.escape(code)}\b", raw)
            if m:
                tail = raw[m.start():].strip()
                next_code = re.search(r"\s+\d{5,7}\b", tail[len(code):])
                if next_code:
                    tail = tail[: len(code) + next_code.start()].strip()
                return tail
        return raw

    for it in items:
        try:
            if bool(it.get("isFree")) and _safe_float(it.get("unitPrice"), 0.0) == 0.0 and _safe_float(it.get("lineNet"), 0.0) == 0.0:
                continue
            raw_txt = _norm_pack_tokens(_raw_for_item(it))
            if _is_free_marker(str(it.get("description") or ""), raw_txt, it.get("unitPrice"), it.get("lineNet")):
                continue
            raw = _raw_for_item(it)
            if not raw:
                continue
            cp = _safe_float(it.get("casePack"), default=0.0)
            us = str(it.get("unitSize") or "").strip()
            # Only override when current unit size is missing or clearly not a size token
            if (cp and cp > 0) and us and _is_size(us):
                continue
            pack, size = _last_pack_size_from_line(raw)
            if pack and size:
                it["casePack"] = int(pack)
                it["unitSize"] = size
                # Update totalUnits if possible
                try:
                    qty = _safe_float(it.get("qty"), default=0.0)
                    if qty > 0:
                        it["totalUnits"] = float(pack) * float(qty)
                except Exception:
                    pass
        except Exception:
            continue

    return items

def _booker_fix_qty_price_from_rawrow(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Booker-specific: override qty/unitPrice/lineNet from rawRow when misaligned."""
    if not items:
        return items

    def _is_size(tok: str) -> bool:
        t = (tok or "").strip().upper()
        if re.fullmatch(r"\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?S", t):
            return True
        if re.fullmatch(r"\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?(ROLL|ROLLS)", t):
            return True
        return False

    def _looks_like_vat(tok: str) -> bool:
        t = BookerCombinedRowParser._norm_vat_code(tok)
        return bool(re.fullmatch(r"(A|B|C|Z|Z/A|R)", t))

    def _raw_for_item(it: Dict[str, Any]) -> str:
        raw = str(it.get("rawRow") or it.get("raw") or "").strip()
        code = re.sub(r"\D+", "", str(it.get("code") or ""))
        if raw and code:
            m = re.search(rf"\b{re.escape(code)}\b", raw)
            if m:
                tail = raw[m.start():].strip()
                next_code = re.search(r"\s+\d{5,7}\b", tail[len(code):])
                if next_code:
                    tail = tail[: len(code) + next_code.start()].strip()
                return tail
        return raw

    for it in items:
        try:
            if bool(it.get("isFree")) and _safe_float(it.get("unitPrice"), 0.0) == 0.0 and _safe_float(it.get("lineNet"), 0.0) == 0.0:
                continue
            raw_txt = _norm_pack_tokens(_raw_for_item(it))
            if _is_free_marker(str(it.get("description") or ""), raw_txt, it.get("unitPrice"), it.get("lineNet")):
                continue
            raw = raw_txt.strip()
            if not raw:
                continue
            toks = raw.split()
            # find last pack/size pair
            size_idx = None
            for i in range(len(toks) - 1, 0, -1):
                if _is_size(toks[i]):
                    pack_tok, _size_tok = _split_pack_size_token(toks[i])
                    if pack_tok:
                        size_idx = i
                        break
                    try:
                        v = float(toks[i - 1])
                    except Exception:
                        v = None
                    if v is not None and abs(v - round(v)) < 1e-6:
                        size_idx = i
                        break
            if size_idx is None:
                continue
            # qty is first numeric token after size
            qty_idx = None
            qty_val = None
            for j in range(size_idx + 1, len(toks)):
                v = BookerCombinedRowParser._as_float_strict(toks[j])
                if v is not None:
                    qty_idx = j
                    qty_val = float(v)
                    break
            if qty_idx is None:
                continue

            # price/value numbers after qty (skip flags and VAT code tokens)
            nums_after: List[float] = []
            for j in range(qty_idx + 1, len(toks)):
                if _looks_like_vat(toks[j]):
                    break
                v = BookerCombinedRowParser._as_float_strict(toks[j])
                if v is not None:
                    nums_after.append(float(v))

            if qty_val is not None:
                it["qty"] = float(qty_val)

            if nums_after:
                it["unitPrice"] = float(nums_after[0])
                if len(nums_after) >= 2:
                    it["lineNet"] = float(nums_after[1])
                else:
                    # derive lineNet when only one number is available
                    try:
                        it["lineNet"] = round(float(it["qty"]) * float(it["unitPrice"]), 2)
                    except Exception:
                        pass

            # Sanity: Booker qty is typically integer and small; fix if it looks like price/POR
            try:
                qv = float(it.get("qty") or 0.0)
                q_sign = -1.0 if qv < 0 else 1.0
                q_abs = abs(qv)
                q_int_like = abs(q_abs - round(q_abs)) < 1e-6
                suspect_qty = (not q_int_like) or (q_abs > 200)
                # If raw row contains %, a non-integer qty is often POR (e.g. 46.1%)
                if ("%" in raw) and (q_abs > 10) and (not q_int_like):
                    suspect_qty = True

                if suspect_qty:
                    unit_price = _safe_float(it.get("unitPrice"), default=0.0)
                    line_net = _safe_float(it.get("lineNet"), default=0.0)
                    qty_fix = None
                    if unit_price > 0 and line_net > 0:
                        qty_fix = line_net / unit_price
                    if qty_fix is not None and 0 < qty_fix <= 200:
                        if abs(qty_fix - round(qty_fix)) < 0.2:
                            it["qty"] = round(float(qty_fix)) * q_sign
                        else:
                            it["qty"] = round(float(qty_fix), 3) * q_sign
                    else:
                        it["qty"] = 1.0 * q_sign
            except Exception:
                pass

            # Update totalUnits if possible
            try:
                cp = _safe_float(it.get("casePack"), default=0.0)
                if cp > 0 and _safe_float(it.get("qty")) > 0:
                    it["totalUnits"] = float(cp) * float(it.get("qty"))
            except Exception:
                pass
        except Exception:
            continue

    return items


def _booker_fix_qty_price_from_text(items: List[Dict[str, Any]], text: str) -> List[Dict[str, Any]]:
    """Booker-specific: recover qty/unitPrice/lineNet from OCR/text lines when rawRow is missing."""
    if not items or not text:
        return items

    # Normalise lines similar to BookerCombinedRowParser
    lines = [BookerCombinedRowParser._normalise_line(ln) for ln in (text or "").splitlines() if (ln or "").strip()]
    if not lines:
        return items

    # Build quick lookup by code (both raw and no-leading-zero)
    by_code: Dict[str, Dict[str, Any]] = {}
    for it in items:
        try:
            if bool(it.get("isFree")) and _safe_float(it.get("unitPrice"), 0.0) == 0.0 and _safe_float(it.get("lineNet"), 0.0) == 0.0:
                continue
            raw_txt = _norm_pack_tokens(str(it.get("rawRow") or it.get("raw") or ""))
            if _is_free_marker(str(it.get("description") or ""), raw_txt, it.get("unitPrice"), it.get("lineNet")):
                continue
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if not code:
                continue
            by_code[code] = it
            by_code[code.lstrip("0") or code] = it
        except Exception:
            continue

    parser = BookerCombinedRowParser()
    for ln in lines:
        toks = ln.split()
        if not toks:
            continue
        code_positions = [
            (idx, re.sub(r"\D+", "", tok))
            for idx, tok in enumerate(toks)
            if BookerCombinedRowParser._is_code(tok)
        ]
        if not code_positions:
            continue

        for pos_idx, (idx, code_tok) in enumerate(code_positions):
            if not code_tok:
                continue
            code_norm = code_tok.lstrip("0") or code_tok
            target = by_code.get(code_tok) or by_code.get(code_norm)
            if not target:
                continue

            next_idx = code_positions[pos_idx + 1][0] if pos_idx + 1 < len(code_positions) else len(toks)
            segment = " ".join(toks[idx:next_idx]).strip()
            cand_lines = [segment]
            if pos_idx == 0:
                cand_lines.append(ln)

            parsed = None
            for cl in cand_lines:
                try:
                    out = parser.parse(cl)
                except Exception:
                    out = []
                if out:
                    for it2 in out:
                        code2 = re.sub(r"\D+", "", str(it2.get("code") or ""))
                        if code2 and (code2 == code_tok or (code2.lstrip("0") or code2) == code_norm):
                            parsed = it2
                            break
                if parsed:
                    break

            if parsed:
                try:
                    # Only override if parsed looks sane
                    qty = _safe_float(parsed.get("qty"))
                    unit_price = _safe_float(parsed.get("unitPrice"))
                    line_net = _safe_float(parsed.get("lineNet"))
                    if qty and unit_price and line_net:
                        target["qty"] = qty
                        target["unitPrice"] = unit_price
                        target["lineNet"] = line_net
                        try:
                            cp = _safe_float(target.get("casePack"), default=0.0)
                            if cp > 0:
                                target["totalUnits"] = float(cp) * float(qty)
                        except Exception:
                            pass
                        for k in ("vatCode", "vatRate", "vatAmount", "lineGross", "stdRrp", "por"):
                            if parsed.get(k) not in (None, ""):
                                target[k] = parsed.get(k)
                except Exception:
                    continue

    return items

def _booker_fix_vat_from_rawrow(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Booker-specific: fix VAT code/rate/amount using rawRow text.

    Prevents single-letter tokens in descriptions (e.g. 'C Chip') from becoming VAT codes.
    """
    if not items:
        return items
    for it in items:
        try:
            raw = _fix_pm_code(str(it.get("rawRow") or it.get("raw") or "")).strip()
            if raw:
                # Prefer VAT code near the end followed by numeric tokens (STD RRP / POR)
                raw_u = raw.upper().replace("Â©", "C").replace("Â¢", "C")
                m = re.search(r"\b([ABZRC](?:/A)?)[\.,]?\b\s+([0-9]+(?:\.\d+)?)\s+([0-9]+(?:\.\d+)?)(?:%|\b)", raw_u)
                if m:
                    vc = BookerCombinedRowParser._norm_vat_code(m.group(1))
                    it["vatCode"] = vc
                    try:
                        it["vatRate"] = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vc, it.get("vatRate") or 0.0))
                    except Exception:
                        pass
                elif not str(it.get("vatCode") or "").strip():
                    # Fallback: last VAT code token in the raw row
                    toks = re.split(r"\s+", raw_u)
                    for t in reversed(toks):
                        vc = BookerCombinedRowParser._norm_vat_code(t)
                        if vc in ("A", "B", "C", "Z", "Z/A", "R"):
                            it["vatCode"] = vc
                            try:
                                it["vatRate"] = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vc, it.get("vatRate") or 0.0))
                            except Exception:
                                pass
                            break
            # If vatAmount is out of scale, recompute from lineNet + vatRate
            ln = _safe_float(it.get("lineNet"))
            vr = _safe_float(it.get("vatRate"))
            va = _safe_float(it.get("vatAmount"))
            if ln != 0 and vr >= 0:
                expected = round(float(ln) * float(vr) / 100.0, 2)
                # If missing or clearly wrong vs expected (e.g., OCR drift like 20.9 on 9.79 net)
                if va == 0 or abs(va - expected) > max(0.2, abs(expected) * 0.6) or abs(va) > max(abs(ln) * 0.6, 10.0):
                    it["vatAmount"] = expected
                    it["lineGross"] = round(float(ln) + float(it.get("vatAmount") or 0.0), 2)
        except Exception:
            continue
    return items

def _booker_fix_std_por_from_rawrow(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Booker-specific: backfill stdRrp / por from rawRow text when missing."""
    if not items:
        return items
    for it in items:
        try:
            if _safe_float(it.get("stdRrp"), default=0.0) > 0 and _safe_float(it.get("por"), default=0.0) > 0:
                continue
            raw = str(it.get("rawRow") or it.get("raw") or "").strip()
            if not raw:
                continue
            toks = raw.replace("%", " %").split()
            # locate VAT code token, then parse numbers after it
            vat_idx = None
            for i, t in enumerate(toks):
                if BookerCombinedRowParser._norm_vat_code(t) in ("A", "B", "C", "Z", "Z/A", "R"):
                    vat_idx = i
                    break
            if vat_idx is None:
                continue
            scan = toks[vat_idx + 1 :]
            std_rrp = None
            por = None
            for t in scan:
                if "%" in t:
                    v = _safe_float(t.replace("%", ""), default=None)
                    if v is not None:
                        por = float(v)
                        break
            # first numeric after VAT code is usually std RRP
            for t in scan:
                v = _safe_float(t, default=None)
                if v is not None:
                    std_rrp = float(v)
                    break
            # Ignore values that look like item codes
            if std_rrp is not None and (std_rrp >= 1000 or re.fullmatch(r"\d{5,7}", str(int(std_rrp)))):
                std_rrp = None
            if std_rrp is not None and _safe_float(it.get("stdRrp"), default=0.0) <= 0:
                it["stdRrp"] = float(std_rrp)
            if por is not None and _safe_float(it.get("por"), default=0.0) <= 0:
                it["por"] = float(por)
        except Exception:
            continue
    return items


def _booker_description_quality(desc: str) -> int:
    s = str(desc or "").strip()
    if not s:
        return 0
    alpha_tokens = re.findall(r"[A-Za-z]{2,}", s)
    long_alpha_tokens = [t for t in alpha_tokens if len(t) >= 3]
    score = len(long_alpha_tokens) * 3 + len(alpha_tokens)
    if re.search(r"[A-Za-z]{4,}", s):
        score += 2
    if re.search(r"\bPM\d+\b", s.upper()):
        score += 2
    if re.fullmatch(r"[:;\.,\-\|/\\\s]+", s):
        score = 0
    return score


def _booker_is_fragment_item(it: Dict[str, Any]) -> bool:
    try:
        desc = str(it.get("description") or "").strip()
        raw = str(it.get("rawRow") or it.get("raw") or "").strip()
        case_pack = _safe_float(it.get("casePack"), 0.0)
        unit_size = str(it.get("unitSize") or "").strip()
        unit_price = _safe_float(it.get("unitPrice"), 0.0)
        line_net = _safe_float(it.get("lineNet"), 0.0)
        std_rrp = _safe_float(it.get("stdRrp"), 0.0)
        por = _safe_float(it.get("por"), 0.0)
        qscore = _booker_description_quality(desc)
        has_meaningful_desc = qscore >= 4
        has_economics = any(v > 0 for v in (case_pack, unit_price, line_net, std_rrp, por)) or bool(unit_size)
        if has_meaningful_desc:
            return False
        if re.fullmatch(r"[:;\.,\-\|/\\\s]+", desc or ""):
            return True
        if not desc and not raw:
            return True
        if not has_economics and qscore <= 1:
            return True
        if desc and qscore <= 1 and len(re.sub(r"[^A-Za-z]", "", desc)) <= 2 and not has_economics:
            return True
    except Exception:
        return False
    return False


def _booker_cleanup_fragment_items(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Remove or suppress obviously broken Booker OCR fragments before showing the grid."""
    if not items:
        return items
    keep: List[Dict[str, Any]] = []
    best_by_code: Dict[str, Tuple[int, int]] = {}

    def _item_score(it: Dict[str, Any]) -> int:
        try:
            desc = str(it.get("description") or "").strip()
            raw = str(it.get("rawRow") or it.get("raw") or "").strip()
            score = _booker_description_quality(desc)
            if raw:
                score += 1
            if _safe_float(it.get("casePack"), 0.0) > 0:
                score += 2
            if str(it.get("unitSize") or "").strip():
                score += 2
            if abs(_safe_float(it.get("unitPrice"), 0.0)) > 0:
                score += 2
            if abs(_safe_float(it.get("lineNet"), 0.0)) > 0:
                score += 2
            if abs(_safe_float(it.get("stdRrp"), 0.0)) > 0:
                score += 1
            if abs(_safe_float(it.get("por"), 0.0)) > 0:
                score += 1
            return score
        except Exception:
            return 0

    # Pass 1: drop clearly broken fragments
    for it in items:
        if not isinstance(it, dict):
            continue
        if _booker_is_fragment_item(it):
            continue
        keep.append(it)

    # Pass 2: if same code appears multiple times, suppress low-quality duplicates
    for idx, it in enumerate(keep):
        try:
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if not code:
                continue
            score = _item_score(it)
            prev = best_by_code.get(code)
            if prev is None or score > prev[1]:
                best_by_code[code] = (idx, score)
        except Exception:
            continue

    out: List[Dict[str, Any]] = []
    seen_dup_counts: Dict[str, int] = {}
    for idx, it in enumerate(keep):
        try:
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if not code:
                out.append(it)
                continue
            seen_dup_counts[code] = seen_dup_counts.get(code, 0) + 1
            dup_total = sum(1 for x in keep if re.sub(r"\D+", "", str(x.get("code") or "")) == code)
            if dup_total <= 1:
                out.append(it)
                continue
            best_idx = best_by_code.get(code, (idx, 0))[0]
            if idx == best_idx:
                out.append(it)
                continue
            # Preserve extra rows only if they have meaningful content and differ materially.
            if _booker_description_quality(str(it.get("description") or "")) >= 6 and not _booker_is_fragment_item(it):
                out.append(it)
        except Exception:
            out.append(it)
    return out

def _booker_vat_code_map_from_text(text: str) -> Dict[str, str]:
    """Build a map of item code -> VAT code from Booker OCR/text blocks."""
    if not text:
        return {}
    lines = [BookerCombinedRowParser._normalise_line(ln) for ln in (text or "").splitlines() if (ln or "").strip()]
    vat_map: Dict[str, str] = {}

    def _is_code_line(ln: str) -> Optional[str]:
        m = re.match(r"^\s*(\d{5,7})\b", ln or "")
        return m.group(1) if m else None

    def _is_stop(ln: str) -> bool:
        up = (ln or "").upper()
        return any(k in up for k in ("SUB-TOTAL", "TOTAL ITEMS", "TOTALS", "INVOICE TOTAL", "SAVING", "PROMOTION", "RATE ", "NETT"))

    i = 0
    while i < len(lines):
        code = _is_code_line(lines[i])
        if not code:
            i += 1
            continue
        # scan forward until next code or stop
        j = i
        found = None
        while j < len(lines):
            if j > i and _is_code_line(lines[j]):
                break
            if _is_stop(lines[j]):
                break
            toks = re.split(r"\s+", lines[j])
            for t in toks:
                vc = BookerCombinedRowParser._norm_vat_code(t)
                if vc in ("A", "B", "C", "Z", "Z/A", "R"):
                    found = vc
                    break
            if found:
                break
            j += 1
        if found:
            vat_map[code] = found
        i = i + 1
    return vat_map

def _booker_parse_code_blocks_simple(text: str) -> List[Dict[str, Any]]:
    """Simple Booker fallback: parse code blocks from OCR/text when rows are stacked."""
    if not text:
        return []
    lines = [BookerCombinedRowParser._normalise_line(ln) for ln in (text or "").splitlines() if (ln or "").strip()]

    def _is_code_line(ln: str) -> Optional[str]:
        m = re.match(r"^\s*(\d{5,7})\b", ln or "")
        return m.group(1) if m else None

    def _is_stop(ln: str) -> bool:
        up = (ln or "").upper()
        return any(k in up for k in ("SUB-TOTAL", "TOTAL ITEMS", "TOTALS", "INVOICE TOTAL", "SAVING", "PROMOTION", "RATE ", "NETT"))

    def _unit_size_token(tok: str) -> bool:
        t = tok.strip().upper()
        if re.fullmatch(r"\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S|ROLL|ROLLS)", t):
            return True
        if re.fullmatch(r"\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S|ROLL|ROLLS)", t):
            return True
        return False

    out: List[Dict[str, Any]] = []
    i = 0
    while i < len(lines):
        code = _is_code_line(lines[i])
        if not code:
            i += 1
            continue
        # collect block lines until next code or stop
        block = []
        j = i
        while j < len(lines):
            if j > i and _is_code_line(lines[j]):
                break
            if _is_stop(lines[j]):
                break
            block.append(lines[j])
            j += 1

        # description is the remainder of the code line
        code_line = block[0] if block else lines[i]
        toks = code_line.split()
        desc = _fix_pm_code(" ".join(toks[1:]).strip())

        case_pack = 0
        unit_size = ""
        qty = None
        unit_price = None
        line_net = None
        vat_code = ""
        std_rrp = 0.0
        por = 0.0

        for ln in block[1:]:
            toks = ln.split()
            if len(toks) >= 2 and case_pack == 0:
                try:
                    v = float(toks[0])
                except Exception:
                    v = None
                if v is not None and abs(v - round(v)) < 1e-6 and _unit_size_token(toks[1]):
                    case_pack = int(v)
                    unit_size = toks[1]
                    continue
            if qty is None and re.fullmatch(r"-?\d+(?:\.\d+)?", ln.strip()):
                try:
                    qty = float(ln.strip())
                    continue
                except Exception:
                    pass
            if unit_price is None and re.search(r"\d+\.\d{2}", ln) and not re.search(r"[A-Za-z]", ln):
                try:
                    unit_price = float(ln.strip())
                    continue
                except Exception:
                    pass
            if line_net is None and re.fullmatch(r"\d+\.\d{2}", ln.strip()):
                try:
                    line_net = float(ln.strip())
                    continue
                except Exception:
                    pass
            # VAT code single-letter line
            vc = BookerCombinedRowParser._norm_vat_code(ln.strip())
            if not vat_code and vc in ("A", "B", "C", "Z", "Z/A", "R"):
                vat_code = vc
                continue
            # RRP / POR line
            if re.search(r"\d+\.\d{2}\s+\d+(?:\.\d+)?%?", ln):
                parts = ln.split()
                try:
                    std_rrp = float(parts[0])
                except Exception:
                    pass
                for p in parts[1:]:
                    if "%" in p:
                        try:
                            por = float(p.replace("%", ""))
                        except Exception:
                            pass
                        break

        if qty is None:
            qty = 1.0
        if unit_price is None and line_net is not None and qty:
            unit_price = round(float(line_net) / float(qty), 2)
        if line_net is None and unit_price is not None and qty:
            line_net = round(float(unit_price) * float(qty), 2)
        vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
        vat_amount = round(float(line_net or 0.0) * (vat_rate / 100.0), 2)
        line_gross = round(float(line_net or 0.0) + float(vat_amount), 2)

        out.append({
            "lineNo": None,
            "code": code,
            "description": desc,
            "casePack": int(case_pack or 0),
            "unitSize": unit_size,
            "qty": float(qty or 0.0),
            "totalUnits": float(case_pack or 0) * float(qty or 0.0),
            "unitPrice": float(unit_price or 0.0),
            "lineNet": float(line_net or 0.0),
            "vatCode": vat_code,
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amount),
            "lineGross": float(line_gross),
            "stdRrp": float(std_rrp or 0.0),
            "por": float(por or 0.0),
        })

        i = j if j > i else i + 1
    return out


def _booker_parse_code_anchored_blocks(text: str) -> List[Dict[str, Any]]:
    """Booker OCR fallback that treats each product code line as a hard row anchor.

    This is specifically for OCR streams where one incomplete product line is followed
    immediately by the next product code before qty/price/value fields appear.
    """
    if not text:
        return []

    lines = [BookerCombinedRowParser._normalise_line(ln) for ln in str(text or "").splitlines() if str(ln or "").strip()]

    def _is_code_line(ln: str) -> Optional[str]:
        m = re.match(r"^\s*(\d{5,7})\b", ln or "")
        return m.group(1) if m else None

    def _is_stop(ln: str) -> bool:
        up = str(ln or "").upper()
        return any(k in up for k in ("SUB-TOTAL", "TOTAL ITEMS", "TOTALS", "INVOICE TOTAL", "SAVING", "PROMOTION", "RATE ", "NETT"))

    def _is_noise(ln: str) -> bool:
        up = str(ln or "").upper().strip()
        if up in ("VOID NOTE", "/CONT", "AV8 HSY", "AIVD"):
            return True
        return any(k in up for k in ("REGISTERED OFFICE", "VAT NUMBER", "ALCOHOL WHOLESALE", "BRANCH ", "CUSTOMER ", "DATE ", "TIME ", "OPERATOR ", "TEL:", "FAX:"))

    def _pack_line(ln: str) -> Tuple[int, str]:
        s = str(ln or "").strip()
        m = re.match(r"^(\d+)\s+([A-Z0-9./]+)$", s, flags=re.I)
        if not m:
            return 0, ""
        pack = int(m.group(1))
        size = m.group(2)
        if len(size) < 2:
            return 0, ""
        return pack, size

    def _qty_line(ln: str) -> Optional[float]:
        s = str(ln or "").strip()
        if re.fullmatch(r"-?\d+(?:\.\d+)?-?", s):
            neg = s.endswith("-")
            core = s[:-1] if neg else s
            try:
                v = float(core)
                return -v if neg else v
            except Exception:
                return None
        return None

    def _price_line(ln: str) -> Optional[float]:
        s = str(ln or "").strip()
        m = re.match(r"^(-?\d+\.\d{2})\s*(?:P|SL|S/L|SK|SH|SI|S1)?$", s, flags=re.I)
        if not m:
            return None
        try:
            return float(m.group(1))
        except Exception:
            return None

    def _value_vat_line(ln: str) -> Tuple[Optional[float], str]:
        s = str(ln or "").strip()
        m = re.match(r"^(-?\d+\.\d{2}-?)\s*([A-Z/]+)?$", s, flags=re.I)
        if not m:
            return None, ""
        num = m.group(1)
        neg = num.endswith("-")
        core = num[:-1] if neg else num
        try:
            value = float(core)
            if neg:
                value = -value
        except Exception:
            value = None
        vat_code = BookerCombinedRowParser._norm_vat_code(m.group(2) or "")
        return value, vat_code if vat_code in ("A", "B", "C", "Z", "Z/A", "R") else ""

    def _rrp_por_line(ln: str) -> Tuple[float, float]:
        s = str(ln or "").strip()
        m = re.match(r"^(\d+\.\d{2})\s+(\d+(?:\.\d+)?)%$", s)
        if not m:
            return 0.0, 0.0
        try:
            return float(m.group(1)), float(m.group(2))
        except Exception:
            return 0.0, 0.0

    filtered: List[str] = []
    seen_code = False
    for ln in lines:
        up = str(ln or "").upper().strip()
        if _is_stop(ln):
            if seen_code:
                break
            continue
        if _is_noise(ln):
            continue
        if up.startswith("CODE ") or ("CODE" in up and "DESCRIPTION" in up and "PACK" in up):
            continue
        if ("VALUE" in up and "VAT" in up and "RRP" in up and "POR" in up):
            continue
        filtered.append(ln)
        if _is_code_line(ln):
            seen_code = True

    def _split_tail_groups(tail_lines: List[str]) -> List[List[str]]:
        groups: List[List[str]] = []
        cur: List[str] = []
        seen_pack = False
        seen_qty = False
        seen_price = False
        seen_value = False
        seen_rrp = False

        def _flush() -> None:
            nonlocal cur, seen_pack, seen_qty, seen_price, seen_value, seen_rrp
            if cur:
                groups.append(cur)
            cur = []
            seen_pack = False
            seen_qty = False
            seen_price = False
            seen_value = False
            seen_rrp = False

        for ln in tail_lines:
            if _is_noise(ln):
                continue
            pack, _size = _pack_line(ln)
            qv = _qty_line(ln)
            pv = _price_line(ln)
            nv, _vc = _value_vat_line(ln)
            rrp, _porv = _rrp_por_line(ln)

            if pack > 0 and seen_pack and (seen_value or seen_rrp or seen_price):
                _flush()

            cur.append(ln)
            if pack > 0:
                seen_pack = True
            elif qv is not None:
                seen_qty = True
            elif pv is not None:
                seen_price = True
            elif nv is not None or BookerCombinedRowParser._norm_vat_code(str(ln or "").strip()) in ("A", "B", "C", "Z", "Z/A", "R"):
                seen_value = True
            elif rrp > 0.0:
                seen_rrp = True

            if seen_pack and seen_qty and (seen_value or seen_rrp):
                _flush()

        _flush()
        return groups

    blocks: List[Tuple[str, str, List[str]]] = []
    i = 0
    while i < len(filtered):
        code = _is_code_line(filtered[i])
        if not code:
            i += 1
            continue

        anchors: List[Tuple[str, str]] = []
        while i < len(filtered):
            code = _is_code_line(filtered[i])
            if not code:
                break
            toks = filtered[i].split()
            anchors.append((code, _fix_pm_code(" ".join(toks[1:]).strip())))
            i += 1

        tail: List[str] = []
        while i < len(filtered) and not _is_code_line(filtered[i]) and not _is_stop(filtered[i]):
            tail.append(filtered[i])
            i += 1

        tail_groups = _split_tail_groups(tail) if tail else []
        if tail_groups:
            for idx, (anchor_code, anchor_desc) in enumerate(anchors):
                group_tail = tail_groups[idx] if idx < len(tail_groups) else []
                blocks.append((anchor_code, anchor_desc, group_tail))
        else:
            for anchor_code, anchor_desc in anchors:
                blocks.append((anchor_code, anchor_desc, []))

    out: List[Dict[str, Any]] = []
    for code, desc, tail in blocks:
        case_pack = 0
        unit_size = ""
        qty = None
        unit_price = None
        line_net = None
        vat_code = ""
        std_rrp = 0.0
        por = 0.0
        free_hit = False

        for ln in tail:
            if not case_pack:
                pack, size = _pack_line(ln)
                if pack > 0 and size:
                    case_pack = pack
                    unit_size = size
                    continue
            if qty is None:
                qv = _qty_line(ln)
                if qv is not None:
                    qty = qv
                    continue
            if unit_price is None:
                pv = _price_line(ln)
                if pv is not None:
                    unit_price = pv
                    continue
            if line_net is None or not vat_code:
                nv, vc = _value_vat_line(ln)
                if nv is not None:
                    if line_net is None:
                        line_net = nv
                    if vc and not vat_code:
                        vat_code = vc
                    continue
            if not vat_code:
                vc = BookerCombinedRowParser._norm_vat_code(str(ln or "").strip())
                if vc in ("A", "B", "C", "Z", "Z/A", "R"):
                    vat_code = vc
                    continue
            if std_rrp <= 0.0 or por <= 0.0:
                rrp, por_v = _rrp_por_line(ln)
                if rrp > 0.0:
                    std_rrp = rrp
                    por = por_v
                    continue
            if re.search(r"\b(FREE|FOC)\b", str(ln or ""), flags=re.I):
                free_hit = True

        if qty is None:
            qty = 1.0
        if unit_price is None and line_net is not None and qty:
            try:
                unit_price = round(float(line_net) / float(qty), 2)
            except Exception:
                unit_price = None
        if line_net is None and unit_price is not None and qty:
            try:
                line_net = round(float(unit_price) * float(qty), 2)
            except Exception:
                line_net = None
        if free_hit and line_net is None:
            line_net = 0.0
        vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
        vat_amount = round(float(line_net or 0.0) * (vat_rate / 100.0), 2)
        line_gross = round(float(line_net or 0.0) + float(vat_amount), 2)

        out.append({
            "lineNo": None,
            "code": code,
            "description": desc,
            "casePack": int(case_pack or 0),
            "unitSize": unit_size,
            "qty": float(qty or 0.0),
            "totalUnits": float(case_pack or 0) * float(qty or 0.0),
            "unitPrice": float(unit_price or 0.0),
            "lineNet": float(line_net or 0.0),
            "vatCode": vat_code,
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amount),
            "lineGross": float(line_gross),
            "stdRrp": float(std_rrp or 0.0),
            "por": float(por or 0.0),
        })

    return out

def _booker_merge_std_por_from_stack(items: List[Dict[str, Any]], stack_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Backfill stdRrp/por from stacked text-layer parse (by code) without overwriting good values."""
    if not items or not stack_items:
        return items
    by_code: Dict[str, List[Dict[str, Any]]] = {}
    for s in stack_items:
        code = re.sub(r"\D+", "", str(s.get("code") or ""))
        if not code:
            continue
        by_code.setdefault(code, []).append(s)
    for it in items:
        try:
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if not code or code not in by_code:
                continue
            cur_std = _safe_float(it.get("stdRrp"), default=0.0)
            cur_por = _safe_float(it.get("por"), default=0.0)
            if cur_std > 0 and cur_por > 0:
                continue
            # choose first candidate with any std/por
            for cand in by_code.get(code, []):
                c_std = _safe_float(cand.get("stdRrp"), default=0.0)
                c_por = _safe_float(cand.get("por"), default=0.0)
                if c_std is not None and (c_std >= 1000 or re.fullmatch(r"\d{5,7}", str(int(c_std)))):
                    c_std = 0.0
                if cur_std <= 0 and c_std > 0:
                    it["stdRrp"] = float(c_std)
                if cur_por <= 0 and c_por > 0:
                    it["por"] = float(c_por)
                if _safe_float(it.get("stdRrp"), default=0.0) > 0 and _safe_float(it.get("por"), default=0.0) > 0:
                    break
        except Exception:
            continue
    return items

def _booker_attach_rawrow_from_text(items: List[Dict[str, Any]], text: str) -> List[Dict[str, Any]]:
    """Attach rawRow for Booker from PDF text layer when OCR row text is unavailable."""
    if not items or not text:
        return items
    lines = []
    for ln in (text or "").splitlines():
        s = _fix_pm_code((ln or "").strip())
        if not s:
            continue
        up = s.upper()
        if ("CODE" in up and "DESCRIPTION" in up and ("QTY" in up or "PACK" in up)):
            continue
        if any(k in up for k in ("SUB-TOTAL", "TOTAL ITEMS", "INVOICE TOTAL", "TOTALS", "RATE ", "SAVING DETAILS")):
            continue
        if up.strip() == "VOID NOTE":
            continue
        if re.match(r"^\d{5,7}\b", s):
            lines.append(s)

    if not lines:
        return items

    code_rows: Dict[str, List[str]] = {}
    for ln in lines:
        m = re.match(r"^(\d{5,7})\b", ln)
        if not m:
            continue
        code_rows.setdefault(m.group(1), []).append(ln)

    used = set()
    for it in items:
        try:
            if it.get("rawRow"):
                continue
            code = re.sub(r"[^0-9]+", "", str(it.get("code") or ""))
            if not code:
                continue
            # Prefer line that contains a description fragment
            desc = str(it.get("description") or "").strip()
            desc = _norm_pack_tokens(desc)
            dfrag = desc[:10].upper() if desc else ""
            chosen = None
            if code_rows.get(code):
                if dfrag:
                    for idx, ln in enumerate(code_rows[code]):
                        if dfrag in ln.upper():
                            chosen = code_rows[code].pop(idx)
                            break
                if chosen is None:
                    chosen = code_rows[code].pop(0)
            if chosen:
                it["rawRow"] = _fix_pm_code(chosen)
        except Exception:
            continue

    return items

def _booker_fix_misaligned_items(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Fix common Booker OCR misalignment where qty shifts to code and unitPrice shifts to casePack."""
    if not items:
        return items
    for it in items:
        try:
            code = str(it.get("code") or "").strip()
            qty = _safe_float(it.get("qty"))
            unit_price = _safe_float(it.get("unitPrice"))
            line_net = _safe_float(it.get("lineNet"))
            case_pack = _safe_float(it.get("casePack"))
            # If qty mirrors code and looks huge, likely shifted
            if code.isdigit() and qty == float(code) and qty > 999:
                it["qty"] = 1.0
                # If unitPrice equals casePack or is tiny vs lineNet, replace with lineNet
                if case_pack and unit_price == case_pack and line_net > 0:
                    it["unitPrice"] = float(line_net)
                elif line_net > 0 and (unit_price <= 0 or line_net > unit_price * 2):
                    it["unitPrice"] = float(line_net)
            # If qty missing but lineNet present and unitPrice equals casePack, set qty=1 and unitPrice=lineNet
            if (qty <= 0 or qty != qty) and line_net > 0 and case_pack and unit_price == case_pack:
                it["qty"] = 1.0
                it["unitPrice"] = float(line_net)
            # If qty erroneously copied from casePack but lineNet matches unitPrice, force qty=1
            if qty and case_pack and abs(qty - case_pack) < 1e-9 and unit_price > 0 and line_net > 0:
                if abs(line_net - unit_price) < 0.01:
                    it["qty"] = 1.0
                    # Keep unitPrice as lineNet for consistency when qty=1
                    it["unitPrice"] = float(line_net)
            # If qty==casePack but lineNet doesn't match qty*unitPrice, likely pack/price misread
            if qty and case_pack and abs(qty - case_pack) < 1e-9 and line_net > 0:
                expected = (unit_price or 0.0) * float(qty)
                if (unit_price <= 0.0) or (abs(line_net - expected) > max(0.5, line_net * 0.2)):
                    it["qty"] = 1.0
                    it["unitPrice"] = float(line_net)
        except Exception:
            continue
    return items


def _fix_qty_outliers(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Fix obviously mis-read quantities (e.g., qty becomes a large item code)."""
    if not items:
        return items
    for it in items:
        try:
            qty = _safe_float(it.get("qty"), default=0.0)
            if not qty:
                continue
            sign = -1.0 if qty < 0 else 1.0
            qty_abs = abs(qty)
            if qty_abs < 1000:
                # Additional fix: Booker POR% sometimes lands in qty
                raw = str(it.get("rawRow") or it.get("raw") or "")
                if "%" in raw and qty_abs >= 10:
                    unit_price = _safe_float(it.get("unitPrice"), default=0.0)
                    line_net = _safe_float(it.get("lineNet"), default=0.0)
                    if unit_price > 0 and line_net > 0:
                        q2 = line_net / unit_price
                        if 0 < q2 <= 200:
                            it["qty"] = round(float(q2)) * sign if abs(q2 - round(q2)) < 0.2 else round(float(q2), 3) * sign
                continue

            code = str(it.get("code") or "").strip()
            unit_price = _safe_float(it.get("unitPrice"), default=0.0)
            line_net = _safe_float(it.get("lineNet"), default=0.0)
            line_gross = _safe_float(it.get("lineGross"), default=0.0)

            # If qty mirrors a numeric code and is very large, likely shifted
            if code.isdigit() and qty_abs == float(code) and qty_abs > 999:
                it["qty"] = 1.0 * sign
                if line_net > 0 and (unit_price <= 0 or abs(line_net - unit_price) < 0.01):
                    it["unitPrice"] = float(line_net)
                continue

            # If unit price and line total exist, derive qty from them when qty is implausible
            expected = None
            if unit_price > 0 and line_net > 0:
                expected = line_net / unit_price
            elif unit_price > 0 and line_gross > 0:
                expected = line_gross / unit_price

            if expected and 0 < expected < 1000:
                if abs(qty_abs - expected) > max(2.0, expected * 0.5):
                    it["qty"] = round(float(expected), 3) * sign
                    if line_net <= 0 and unit_price > 0:
                        it["lineNet"] = round(float(it["qty"]) * float(unit_price), 2)
                    continue

            # If qty is huge but lineNet ~= unitPrice, treat qty as 1
            if unit_price > 0 and line_net > 0 and abs(line_net - unit_price) < max(0.02, line_net * 0.01):
                it["qty"] = 1.0 * sign
        except Exception:
            continue
    return items


def _booker_fix_single_qty_unit_price(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """For Booker qty-1 lines, unit price should match the printed line value."""
    if not items:
        return items
    for it in items:
        try:
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if not re.fullmatch(r"\d{5,7}", code or ""):
                continue
            qty = _safe_float(it.get("qty"), default=0.0)
            unit_price = _safe_float(it.get("unitPrice"), default=0.0)
            line_net = _safe_float(it.get("lineNet"), default=0.0)
            if abs(qty - 1.0) <= 0.001 and line_net > 0 and abs(unit_price - line_net) > 0.01:
                it["unitPrice"] = float(line_net)
        except Exception:
            continue
    return items


def _booker_parse_text_layer_stack(text: str) -> List[Dict[str, Any]]:
    """Parse Booker stacked text-layer where pack/qty/price/value/VAT are on separate lines."""
    if not text:
        return []

    def _norm_line(s: str) -> str:
        s = (s or "").replace("\t", " ").replace("Ã‚Â£", " ").strip()
        s = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", s)
        s = _norm_pack_tokens(s)
        # Normalise pack/size tokens: "6*1.5 lt" -> "6X1.5LT", "1.5 lt" -> "1.5LT"
        s = re.sub(
            r"(\d+(?:\.\d+)?)\s*[*xX]\s*(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
            r"\1X\2\3",
            s,
            flags=re.IGNORECASE,
        )
        s = re.sub(
            r"(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
            r"\1\2",
            s,
            flags=re.IGNORECASE,
        )
        s = re.sub(r"\s+", " ", s)
        return s.strip()

    def _is_code_line(s: str) -> bool:
        return bool(re.match(r"^\s*\d{5,7}\b", s))

    def _unit_size_token(tok: str) -> bool:
        t = (tok or "").strip().upper()
        if re.fullmatch(r"\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S)", t):
            return True
        if re.fullmatch(r"\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?(ROLL|ROLLS)", t):
            return True
        if re.fullmatch(r"\d+PK", t):
            return True
        return False

    def _looks_like_vat(tok: str) -> bool:
        t = BookerCombinedRowParser._norm_vat_code(tok)
        return bool(re.fullmatch(r"(A|B|C|Z|Z/A|R)", t))

    def _as_int(tok: str) -> Optional[int]:
        try:
            v = float(tok)
            if abs(v - round(v)) < 1e-6:
                return int(v)
        except Exception:
            return None
        return None

    def _as_float(tok: str) -> Optional[float]:
        if tok is None:
            return None
        t = str(tok).strip().replace(",", "")
        if t.endswith("-") and len(t) > 1:
            t = "-" + t[:-1]
        t = t.replace("%", "")
        if t.upper() in ("FREE", "FOC"):
            return 0.0
        if not re.fullmatch(r"-?\d+(?:\.\d+)?", t):
            return None
        try:
            return float(t)
        except Exception:
            return None

    # Filter lines
    raw_lines = [ _norm_line(ln) for ln in (text or "").splitlines() if (ln or "").strip() ]
    lines = []
    seen_code_line = False
    for ln in raw_lines:
        up = ln.upper()
        # If we've already seen item lines, stop at totals to avoid capturing invoice totals as line values.
        if any(k in up for k in ("TOTAL ITEMS", "TOTALS:", "INVOICE TOTAL", "RATE ", "GOODS", "NETT")):
            if seen_code_line:
                break
            # otherwise skip header/footer totals noise
            continue
        # Stop at trailing blocks/footers that come after items (prevents picking up summary numbers)
        if seen_code_line and (
            up.strip() in ("STD", "VALUE", "VAT", "RRP", "POR")
            or any(k in up for k in ("DATE", "TIME", "TILL", "OPERATOR"))
            or (up.strip() in ("QTY", "PRICE"))
        ):
            break
        if any(k in up for k in ("SUB-TOTAL", "RATE ", "SAVING", "PROMOTION", "PROMOTIONS")):
            if seen_code_line:
                break
            continue
        # Skip column headers that can appear mid-stream in OCR
        if ("VALUE" in up and "VAT" in up and "RRP" in up and "POR" in up):
            continue
        if up.startswith("CODE ") or ("CODE" in up and "DESCRIPTION" in up and "PACK" in up):
            continue
        if up.strip() == "VOID NOTE":
            continue
        lines.append(ln)
        if _is_code_line(ln):
            seen_code_line = True

    items: List[Dict[str, Any]] = []
    pending_vat_line: Optional[str] = None
    i = 0
    while i < len(lines):
        ln = lines[i]
        if not _is_code_line(ln):
            # Some Booker OCRs place VAT/value line before the code line.
            # Capture it so we can attach to the next item.
            try:
                toks_p = ln.split()
                if any(_looks_like_vat(t) for t in toks_p):
                    pending_vat_line = ln
            except Exception:
                pass
            i += 1
            continue
        toks = ln.split()
        code = ""
        code_idx = None
        for idx, tok in enumerate(toks):
            if re.fullmatch(r"\d{5,7}", tok):
                code = tok
                code_idx = idx
                break
        if not code:
            i += 1
            continue
        desc = _fix_pm_code(" ".join(toks[(code_idx + 1) if code_idx is not None else 1 :]).strip())

        case_pack = 0
        unit_size = ""
        qty = None
        unit_price = None
        line_net = None
        vat_code = ""
        std_rrp = 0.0
        por = 0.0
        free_hit = False

        # If we captured a VAT/value line before this code line, apply it first.
        if pending_vat_line:
            try:
                toks_pre = pending_vat_line.split()
                if any(str(t).strip().upper() in ("FREE", "FOC") for t in toks_pre):
                    free_hit = True
                v_idx = None
                for k in range(len(toks_pre)):
                    if _looks_like_vat(toks_pre[k]):
                        v_idx = k
                        vat_code = BookerCombinedRowParser._norm_vat_code(toks_pre[k])
                        break
                if v_idx is not None:
                    for t in reversed(toks_pre[:v_idx]):
                        v = _as_float(t)
                        if v is not None:
                            line_net = float(v)
                            break
                    for t in toks_pre[v_idx + 1:]:
                        if std_rrp == 0.0:
                            v = _as_float(t)
                            if v is not None:
                                std_rrp = float(v)
                                continue
                        if "%" in t and por == 0.0:
                            v = _as_float(t)
                            if v is not None:
                                por = float(v)
                                break
            except Exception:
                pass
            pending_vat_line = None

        # scan forward until next code or end
        j = i + 1
        last_value_line = None
        pending_vat_code = ""
        while j < len(lines) and not _is_code_line(lines[j]):
            ln2 = lines[j]
            toks2 = ln2.split()
            if any(str(t).strip().upper() in ("FREE", "FOC") for t in toks2):
                free_hit = True
            # pack size: "<int> <unit>"
            if len(toks2) >= 2 and case_pack == 0:
                cp = _as_int(toks2[0])
                if cp is not None and _unit_size_token(toks2[1]):
                    case_pack = int(cp)
                    unit_size = toks2[1]
                    j += 1
                    continue
            # qty: whole-line numeric (allow trailing minus)
            if qty is None:
                qline = ln2.strip()
                if re.fullmatch(r"-?\d+(?:\.\d+)?-?", qline):
                    qv = _as_float(qline)
                    if qv is not None:
                        qty = float(qv)
                        j += 1
                        continue
            # price line: number + optional flag
            if unit_price is None:
                nums = [ _as_float(t) for t in toks2 if _as_float(t) is not None ]
                if nums and any(re.search(r"\d+\.\d{2}", t) for t in toks2):
                    # Skip if VAT token present (handled below)
                    if not any(_looks_like_vat(t) for t in toks2):
                        # If line contains qty + price (e.g., "1 111.41"), capture both
                        decs = [ _as_float(t) for t in toks2 if re.search(r"\d+\.\d{2}", t) ]
                        ints = [ _as_float(t) for t in toks2 if re.fullmatch(r"\d+", t) ]
                        if qty is None and decs and ints:
                            qty = float(ints[0])
                            unit_price = float(decs[0])
                        else:
                            # Prefer the first decimal as price (avoid integer-only tokens)
                            if decs:
                                unit_price = float(decs[0])
                            else:
                                unit_price = float(nums[0])
                        j += 1
                        continue
            # VAT/value line (contains VAT code)
            if any(_looks_like_vat(t) for t in toks2):
                # value is last numeric before VAT code
                v_idx = None
                for k in range(len(toks2)):
                    if _looks_like_vat(toks2[k]):
                        v_idx = k
                        vat_code = BookerCombinedRowParser._norm_vat_code(toks2[k])
                        break
                if v_idx is not None:
                    for t in reversed(toks2[:v_idx]):
                        v = _as_float(t)
                        if v is not None:
                            line_net = float(v)
                            break
                    # after VAT code: std_rrp then por%
                    for t in toks2[v_idx + 1:]:
                        if std_rrp == 0.0:
                            v = _as_float(t)
                            if v is not None:
                                std_rrp = float(v)
                                continue
                        if "%" in t and por == 0.0:
                            v = _as_float(t)
                            if v is not None:
                                por = float(v)
                                break
                # VAT code line sometimes contains only the code; read std_rrp/por from next line
                if v_idx is not None and len(toks2) == 1:
                    pending_vat_code = vat_code
                j += 1
                continue
            # If previous line had only VAT code, parse std_rrp/por from this line
            if pending_vat_code and toks2:
                nums = [ _as_float(t) for t in toks2 if _as_float(t) is not None ]
                if nums and std_rrp == 0.0:
                    std_rrp = float(nums[0])
                if por == 0.0:
                    for t in toks2:
                        if "%" in t:
                            v = _as_float(t)
                            if v is not None:
                                por = float(v)
                                break
                vat_code = pending_vat_code
                pending_vat_code = ""
                j += 1
                continue
            # value-only line
            if len(toks2) == 1:
                v = _as_float(toks2[0])
                if v is not None:
                    last_value_line = float(v)
            j += 1

        # If VAT line didn't include value, use last_value_line
        if line_net is None and last_value_line is not None:
            line_net = float(last_value_line)

        if code and (qty is not None or unit_price is not None or line_net is not None):
            free_final = _is_free_marker(desc, "", unit_price, line_net) or (
                bool(free_hit) and _safe_float(unit_price, 0.0) == 0.0 and _safe_float(line_net, 0.0) == 0.0
            )
            if free_final and "FREE" not in desc.upper():
                desc = f"{desc} FREE".strip()
            vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
            if unit_price is None and line_net is not None and qty not in (None, 0):
                unit_price = float(line_net) / float(qty)
            if line_net is None and unit_price is not None and qty not in (None, 0):
                line_net = round(float(unit_price) * float(qty), 2)
            if qty is None:
                qty = 1.0
            total_units = float(case_pack or 0) * float(qty or 0.0)
            vat_amount = round(float(line_net or 0.0) * (vat_rate / 100.0), 2)
            line_gross = round(float(line_net or 0.0) + float(vat_amount), 2)
            items.append({
                "lineNo": None,
                "code": code,
                "description": desc,
                "casePack": int(case_pack or 0),
                "unitSize": unit_size,
                "qty": float(qty or 0.0),
                "totalUnits": float(total_units),
                "unitPrice": float(unit_price or 0.0),
                "lineNet": float(line_net or 0.0),
                "vatCode": vat_code,
                "vatRate": float(vat_rate),
                "vatAmount": float(vat_amount),
                "lineGross": float(line_gross),
                "stdRrp": float(std_rrp or 0.0),
                "por": float(por or 0.0),
                "isFree": bool(free_final),
            })

        i = j if j > i else i + 1

    return items

def _booker_parse_loose_blocks(text: str) -> List[Dict[str, Any]]:
    """Parse Booker items from loose OCR blocks where line order is unstable."""
    if not text:
        return []

    def _norm_line(s: str) -> str:
        s = (s or "").replace("\t", " ").replace("Ã‚Â£", " ").strip()
        s = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", s)
        s = _norm_pack_tokens(s)
        # Normalise pack/size tokens: "6*1.5 lt" -> "6X1.5LT", "1.5 lt" -> "1.5LT"
        s = re.sub(
            r"(\d+(?:\.\d+)?)\s*[*xX]\s*(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
            r"\1X\2\3",
            s,
            flags=re.IGNORECASE,
        )
        s = re.sub(
            r"(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
            r"\1\2",
            s,
            flags=re.IGNORECASE,
        )
        s = re.sub(r"\s+", " ", s)
        return s.strip()

    def _unit_size_token(tok: str) -> bool:
        t = (tok or "").strip().upper()
        if re.fullmatch(r"\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S)", t):
            return True
        if re.fullmatch(r"\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?(ROLL|ROLLS)", t):
            return True
        return False

    def _looks_like_vat(tok: str) -> bool:
        t = BookerCombinedRowParser._norm_vat_code(tok)
        return bool(re.fullmatch(r"(A|B|C|Z|Z/A|R)", t))

    def _as_float(tok: str) -> Optional[float]:
        if tok is None:
            return None
        t = str(tok).strip().replace(",", "").replace("%", "")
        if t.endswith("-") and len(t) > 1:
            t = "-" + t[:-1]
        if t.upper() in ("FREE", "FOC"):
            return 0.0
        if not re.fullmatch(r"-?\d+(?:\.\d+)?", t):
            return None
        try:
            return float(t)
        except Exception:
            return None

    lines = [_norm_line(ln) for ln in (text or "").splitlines() if (ln or "").strip()]
    blocks: List[List[str]] = []
    cur: List[str] = []
    for ln in lines:
        if re.search(r"\b\d{5,7}\b", ln):
            if cur:
                blocks.append(cur)
            cur = [ln]
        else:
            if cur:
                cur.append(ln)
    if cur:
        blocks.append(cur)

    items: List[Dict[str, Any]] = []
    for blk in blocks:
        blob = " ".join(blk)
        m_code = re.search(r"\b(\d{5,7})\b", blob)
        if not m_code:
            continue
        code = m_code.group(1)
        toks = blob.split()
        # description: tokens after code until first numeric or size token
        desc_parts = []
        seen_code = False
        for t in toks:
            if not seen_code:
                if t == code:
                    seen_code = True
                continue
            if _unit_size_token(t) or re.fullmatch(r"\d+(?:\.\d+)?", t) or _looks_like_vat(t):
                break
            desc_parts.append(t)
        desc = _fix_pm_code(" ".join(desc_parts).strip())
        # Defer FREE marker until we can validate against pricing

        # pack size
        case_pack = 0
        unit_size = ""
        for i in range(len(toks) - 1):
            if _unit_size_token(toks[i + 1]):
                v = _as_float(toks[i])
                if v is not None and abs(v - round(v)) < 1e-6:
                    case_pack = int(v)
                    unit_size = toks[i + 1]
        # VAT code (prefer last)
        vat_code = ""
        for t in reversed(toks):
            if _looks_like_vat(t):
                vat_code = BookerCombinedRowParser._norm_vat_code(t)
                break
        # lineNet: last numeric before VAT code
        line_net = None
        if vat_code:
            try:
                idx = max(i for i, t in enumerate(toks) if t.strip().upper() == vat_code)
                for t in reversed(toks[:idx]):
                    if str(t).strip().upper() in ("FREE", "FOC"):
                        line_net = 0.0
                        break
                    v = _as_float(t)
                    if v is not None:
                        line_net = float(v)
                        break
            except Exception:
                pass
        # qty + unit price: use first qty after pack size
        qty = None
        unit_price = None
        if case_pack and unit_size:
            try:
                i_us = next(i for i, t in enumerate(toks) if t == unit_size)
                for j in range(i_us + 1, len(toks)):
                    v = _as_float(toks[j])
                    if v is not None:
                        qty = float(v)
                        # next decimal is price
                        for k in range(j + 1, len(toks)):
                            v2 = _as_float(toks[k])
                            if v2 is not None and re.search(r"\d+\.\d{2}", toks[k]):
                                unit_price = float(v2)
                                break
                        break
            except Exception:
                pass
        if unit_price is None and line_net is not None and qty not in (None, 0):
            unit_price = round(float(line_net) / float(qty), 2)
        if line_net is None and unit_price is not None and qty not in (None, 0):
            line_net = round(float(unit_price) * float(qty), 2)
        if qty is None:
            qty = 1.0
        vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
        vat_amount = round(float(line_net or 0.0) * (vat_rate / 100.0), 2)
        line_gross = round(float(line_net or 0.0) + float(vat_amount), 2)

        free_final = _is_free_marker(desc, blob, unit_price, line_net)
        if free_final and "FREE" not in desc.upper():
            desc = f"{desc} FREE".strip()

        items.append({
            "lineNo": None,
            "code": code,
            "description": desc,
            "casePack": int(case_pack or 0),
            "unitSize": unit_size,
            "qty": float(qty or 0.0),
            "totalUnits": float(case_pack or 0) * float(qty or 0.0),
            "unitPrice": float(unit_price or 0.0),
            "lineNet": float(line_net or 0.0),
            "vatCode": vat_code,
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amount),
            "lineGross": float(line_gross),
            "isFree": bool(free_final),
        })

    return items


def _booker_desc_key(desc: str) -> str:
    s = re.sub(r"[^A-Z0-9]+", " ", str(desc or "").upper()).strip()
    return " ".join(s.split()[:10])


def _booker_ocr_vat_code_info(tok: str) -> Tuple[str, float]:
    raw = re.sub(r"[^A-Z0-9]", "", str(tok or "").upper())
    if not raw:
        return "", 0.0
    if raw in ("AO", "A0"):
        return "AO", 0.0
    if raw.startswith("A"):
        if len(raw) >= 2 and raw[1] in ("0", "O", "Q", "G", "D"):
            return "AO", 0.0
        return "A1", 20.0
    if raw.startswith("B"):
        return "B", 5.0
    if raw.startswith("Z"):
        return "Z", 0.0
    if raw.startswith("R"):
        return "R", 5.0
    if raw.startswith("C"):
        return "C", 20.0
    return "", 0.0


def _booker_parse_ocr_qty(tok: str) -> float:
    s = str(tok or "").strip().replace(" ", "")
    if not s:
        return 0.0
    s = s.replace("I", "1").replace("l", "1").replace("L", "1")
    if re.fullmatch(r"\d+[.,]000", s):
        try:
            return float(re.split(r"[.,]", s)[0])
        except Exception:
            return 0.0
    if re.fullmatch(r"\d+[.,]\d{3}", s):
        try:
            return float(s.replace(",", "."))
        except Exception:
            return 0.0
    s2 = s.replace(",", "")
    if re.fullmatch(r"\d+(?:\.\d+)?", s2):
        try:
            return float(s2)
        except Exception:
            return 0.0
    return 0.0


def _booker_ocr_money(tok: str) -> float:
    s = str(tok or "").strip()
    if not s:
        return 0.0
    s = s.replace("£", "").replace("�", "").replace("O", "0") if re.fullmatch(r"[0-9O,.\-]+", s) else s
    if re.fullmatch(r"\d{1,3}(?:,\d{3})+\.\d{2}", s):
        try:
            return float(s.replace(",", ""))
        except Exception:
            return 0.0
    if re.fullmatch(r"\d+,\d{2}", s):
        try:
            return float(s.replace(",", "."))
        except Exception:
            return 0.0
    s2 = s.replace(",", "")
    if re.fullmatch(r"-?\d+(?:\.\d+)?", s2):
        try:
            return float(s2)
        except Exception:
            return 0.0
    return 0.0


def _booker_parse_missing_ocr_line(line: str, next_qty_line: str = "") -> Optional[Dict[str, Any]]:
    line = re.sub(r"\b(M\d{3})\s+(\d{3})\b", r"\1\2", str(line or ""), flags=re.I)
    line = re.sub(r"\s+", " ", line).strip()
    if not line:
        return None

    m_code = re.match(r"^\s*M\s*(\d{3})\s*(\d{3})\b", line, flags=re.I)
    if m_code:
        code = f"{m_code.group(1)}{m_code.group(2)}"
    else:
        m_code = re.match(r"^\s*M(\d{6})\b", line, flags=re.I)
        if not m_code:
            return None
        code = m_code.group(1)

    toks = line.split()
    if toks:
        toks[0] = f"M{code}"
    start = 1
    if start < len(toks) and re.fullmatch(r"N[/A-Z0-9]+", toks[start].upper()):
        start += 1

    net_idx = None
    for idx in range(len(toks) - 1, start - 1, -1):
        if _booker_ocr_money(toks[idx]) > 0:
            net_idx = idx
            break
    if net_idx is None:
        return None

    vat_idx = None
    vat_code = ""
    vat_rate = 0.0
    for idx in range(net_idx - 1, start - 1, -1):
        vc, vr = _booker_ocr_vat_code_info(toks[idx])
        if vc:
            vat_idx = idx
            vat_code = vc
            vat_rate = vr
            break
    if vat_idx is None:
        return None

    prefix = toks[start:vat_idx]
    numeric_tail: List[str] = []
    j = len(prefix) - 1
    while j >= 0:
        tk = prefix[j]
        if _booker_parse_ocr_qty(tk) > 0 or _booker_ocr_money(tk) > 0:
            numeric_tail.insert(0, tk)
            j -= 1
            continue
        break
    if len(numeric_tail) < 2:
        return None

    desc = _collapse_spaces(" ".join(prefix[: len(prefix) - len(numeric_tail)])).strip(" -:\t")
    pack = str(numeric_tail[0] or "").strip()
    unit_price = _booker_ocr_money(numeric_tail[1])
    qty = _booker_parse_ocr_qty(numeric_tail[2]) if len(numeric_tail) >= 3 else 0.0
    line_net = _booker_ocr_money(toks[net_idx])
    if qty <= 0 and re.fullmatch(r"\s*\d+[.,]\d{3}\s*", str(next_qty_line or "")):
        qty = _booker_parse_ocr_qty(next_qty_line)
    if qty <= 0 and unit_price > 0 and line_net > 0:
        ratio = line_net / unit_price
        if abs(ratio - round(ratio)) <= 0.05:
            qty = float(round(ratio))
    if qty <= 0:
        qty = 1.0

    if not desc or unit_price <= 0 or line_net <= 0:
        return None

    vat_amount = round(float(line_net) * (float(vat_rate) / 100.0), 2) if vat_rate > 0 else 0.0
    line_gross = round(float(line_net) + float(vat_amount), 2)
    return {
        "code": code,
        "description": desc,
        "casePack": pack,
        "unitSize": "",
        "qty": float(qty),
        "unitPrice": float(unit_price),
        "lineNet": float(line_net),
        "vatCode": vat_code,
        "vatRate": float(vat_rate),
        "vatAmount": float(vat_amount),
        "lineGross": float(line_gross),
        "stdRrp": 0.0,
        "por": 0.0,
        "pmp": "",
    }


def _booker_salvage_missing_ocr_items(text: str, existing_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    lines = (text or "").splitlines()
    if not lines:
        return []

    existing_keys = set()
    for it in existing_items or []:
        code = re.sub(r"\D+", "", str(it.get("code") or ""))
        if not code:
            continue
        key = (code, round(_safe_float(it.get("lineNet")), 2), _booker_desc_key(it.get("description") or ""))
        existing_keys.add(key)

    out: List[Dict[str, Any]] = []
    seen_new = set()
    qty_only = re.compile(r"^\s*\d+[.,]\d{3}\s*$")
    code_line = re.compile(r"^\s*M\s*\d{3}\s*\d{3}\b|^\s*M\d{6}\b", re.I)

    i = 0
    while i < len(lines):
        line = lines[i]
        next_line = lines[i + 1].strip() if i + 1 < len(lines) else ""
        if not code_line.match(str(line or "")):
            i += 1
            continue
        row = _booker_parse_missing_ocr_line(line, next_line)
        if row:
            key = (
                re.sub(r"\D+", "", str(row.get("code") or "")),
                round(_safe_float(row.get("lineNet")), 2),
                _booker_desc_key(row.get("description") or ""),
            )
            if key not in existing_keys and key not in seen_new:
                seen_new.add(key)
                out.append(row)
                if qty_only.match(next_line):
                    i += 1
        i += 1
    return out


def _booker_merge_salvage_if_better(text: str, header: Dict[str, Any], items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    salvage_items = _booker_salvage_missing_ocr_items(text or "", items or [])
    if not salvage_items:
        return items

    target_net = _safe_float((header or {}).get("totalNet"))
    if target_net <= 0.0:
        gross = _safe_float((header or {}).get("totalGross"))
        vat = _safe_float((header or {}).get("totalVat"))
        if gross > 0.0:
            target_net = round(gross - vat, 2)

    base_items = list(items or [])
    base_net = round(sum(_safe_float(x.get("lineNet")) for x in base_items), 2)
    merged_items = base_items + list(salvage_items)
    merged_net = round(sum(_safe_float(x.get("lineNet")) for x in merged_items), 2)

    if target_net > 0.0:
        if abs(merged_net - target_net) >= abs(base_net - target_net):
            return items
    elif merged_net <= base_net:
        return items

    for idx, it in enumerate(merged_items, start=1):
        try:
            it["lineNo"] = idx
        except Exception:
            continue
    return merged_items


def _booker_expected_total_from_text(text: str) -> int:
    try:
        src = str(text or "")
        if not src.strip():
            return 0

        # First handle the simple inline form: "TOTAL ITEMS: 44"
        m = re.search(r"TOTAL\s+ITEMS\s*:\s*(\d+)", src, flags=re.I)
        if m:
            return int(m.group(1))

        # Google OCR often splits Booker totals across multiple lines:
        #   TOTAL ITEMS:
        #   RATE
        #   A: 0.00
        #   B:20.00
        #   :
        #   257.20
        #   EXC.VAT
        #   44
        #   GOODS
        # Search a short window after the TOTAL ITEMS marker and prefer
        # an integer that sits near GOODS/EXC.VAT rather than VAT rates.
        lines = [str(ln or "").strip() for ln in src.splitlines()]
        total_item_line_idxs = [idx for idx, ln in enumerate(lines) if re.search(r"\bTOTAL\s+ITEMS\b", ln, flags=re.I)]
        for start_idx in reversed(total_item_line_idxs):
            window = lines[start_idx : min(len(lines), start_idx + 14)]
            for idx, ln in enumerate(window):
                if re.fullmatch(r"\d{1,4}", ln):
                    prev_ln = window[idx - 1].upper() if idx > 0 else ""
                    next_ln = window[idx + 1].upper() if (idx + 1) < len(window) else ""
                    if any(tok in prev_ln for tok in ("EXC.VAT", "GOODS", "ITEMS")) or any(tok in next_ln for tok in ("GOODS", "MULT", "NETT", "TOTALS")):
                        return int(ln)

            # Fallback: choose the last plain integer in the local window.
            plain_ints = [int(ln) for ln in window if re.fullmatch(r"\d{1,4}", ln)]
            if plain_ints:
                return plain_ints[-1]
        return 0
    except Exception:
        return 0


def _booker_candidate_noise_score(item: Dict[str, Any]) -> Tuple[int, int, float]:
    desc = str((item or {}).get("description") or "").strip().upper()
    code = re.sub(r"\D+", "", str((item or {}).get("code") or ""))
    qty = _safe_float((item or {}).get("qty"))
    line_net = abs(_safe_float((item or {}).get("lineNet")))
    noise = 0
    if not code:
        noise += 6
    if not desc:
        noise += 6
    if len(desc) <= 3:
        noise += 4
    if any(tok in desc for tok in ("VOID", "NOTE", "TEL", "FAX", "REGISTERED", "EQUITY HOUSE", "VAT NUMBER")):
        noise += 8
    if desc.count(" ") < 1:
        noise += 2
    if qty <= 0:
        noise += 2
    return (noise, 0 if code else 1, line_net)


def _booker_is_obvious_noise_row(item: Dict[str, Any]) -> bool:
    row = dict(item or {})
    desc = str(row.get("description") or "").strip().upper()
    code = re.sub(r"\D+", "", str(row.get("code") or ""))
    case_pack = _safe_float(row.get("casePack"))
    qty = _safe_float(row.get("qty"))
    unit_price = _safe_float(row.get("unitPrice"))
    line_net = _safe_float(row.get("lineNet"))
    vat_amount = _safe_float(row.get("vatAmount"))
    line_gross = _safe_float(row.get("lineGross"))
    moneyish = max(abs(unit_price), abs(line_net), abs(vat_amount), abs(line_gross))

    if not desc and not code:
        return True

    # If the parser kept only a numeric fragment from a header/contact line
    # and recovered no product text or money fields, it is not a real item.
    if not desc and code and moneyish <= 0.01 and case_pack <= 0 and qty in (0.0, 1.0):
        return True

    if any(tok in desc for tok in (
        "FAX",
        "TEL",
        "TELEPHONE",
        "REGISTERED OFFICE",
        "REGISTERED IN ENGLAND",
        "VAT NUMBER",
        "ALCOHOL WHOLESALE REGISTRATION",
        "CUSTOMER PO NUMBER",
        "OPERATOR",
        "SELFSCAN",
        "PAGE 0",
    )):
        return True

    # Header contact lines can leak into candidate rows with a phone fragment as a fake code.
    if desc in {"FAX:", "TEL:", "TELEPHONE:"}:
        return True
    if code and len(code) >= 7 and moneyish <= 0.01 and case_pack <= 0 and qty in (0.0, 1.0):
        if ":" in desc or any(tok in desc for tok in ("FAX", "TEL", "PHONE")):
            return True

    return False


def _booker_prune_google_candidate_rows(text: str, header: Dict[str, Any], items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    rows = [dict(it) for it in (items or []) if isinstance(it, dict)]
    if not rows:
        return rows

    rows = [row for row in rows if not _booker_is_obvious_noise_row(row)]
    if not rows:
        return rows

    expected_total = _booker_expected_total_from_text(text)
    target_net = _safe_float((header or {}).get("totalNet"))
    if target_net <= 0:
        gross = _safe_float((header or {}).get("totalGross"))
        vat = _safe_float((header or {}).get("totalVat"))
        if gross > 0:
            target_net = round(gross - vat, 2)

    # Remove exact-ish duplicates first.
    deduped: List[Dict[str, Any]] = []
    seen = set()
    for row in rows:
        key = (
            re.sub(r"\D+", "", str(row.get("code") or "")),
            _booker_desc_key(row.get("description") or ""),
            round(_safe_float(row.get("lineNet")), 2),
            round(_safe_float(row.get("qty")), 3),
        )
        if key in seen:
            continue
        seen.add(key)
        deduped.append(row)
    rows = deduped

    if expected_total > 0 and len(rows) > expected_total:
        while len(rows) > expected_total:
            best_idx = None
            best_key = None
            for idx, row in enumerate(rows):
                candidate = rows[:idx] + rows[idx + 1 :]
                diff_after = _candidate_diff(_gdocai_header_for_items(header or {}, {}, candidate), candidate)
                noise_key = _booker_candidate_noise_score(row)
                rank = (diff_after, noise_key[0], noise_key[1], noise_key[2])
                if best_key is None or rank < best_key:
                    best_key = rank
                    best_idx = idx
            if best_idx is None:
                break
            rows.pop(best_idx)

    if target_net > 0 and len(rows) >= 2:
        improved = True
        while improved and len(rows) > max(expected_total or 0, 1):
            improved = False
            base_diff = abs(round(sum(_safe_float(r.get("lineNet")) for r in rows), 2) - target_net)
            removable_idx = None
            removable_diff = base_diff
            removable_rank = None
            for idx, row in enumerate(rows):
                candidate = rows[:idx] + rows[idx + 1 :]
                cand_net = round(sum(_safe_float(r.get("lineNet")) for r in candidate), 2)
                cand_diff = abs(cand_net - target_net)
                noise_key = _booker_candidate_noise_score(row)
                rank = (cand_diff, noise_key[0], noise_key[1], noise_key[2])
                if cand_diff + 0.01 < removable_diff and (removable_rank is None or rank < removable_rank):
                    removable_idx = idx
                    removable_diff = cand_diff
                    removable_rank = rank
            if removable_idx is not None:
                rows.pop(removable_idx)
                improved = True

    for idx, row in enumerate(rows, start=1):
        row["lineNo"] = idx
    return rows


def _booker_prepare_google_ocr_items(text: str, header: Dict[str, Any], items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    rows = [dict(it) for it in (items or []) if isinstance(it, dict)]
    if not rows:
        return rows
    try:
        rows = _booker_attach_rawrow_from_text(rows, text or "")
    except Exception:
        pass
    try:
        rows = _booker_fix_pack_size_from_rawrow(rows)
    except Exception:
        pass
    try:
        rows = _booker_fix_qty_price_from_rawrow(rows)
    except Exception:
        pass
    try:
        rows = _booker_fix_qty_price_from_text(rows, text or "")
    except Exception:
        pass
    try:
        rows = _booker_fix_vat_from_rawrow(rows)
    except Exception:
        pass
    try:
        rows = _booker_fix_std_por_from_rawrow(rows)
    except Exception:
        pass
    try:
        rows = _booker_fix_misaligned_items(rows)
    except Exception:
        pass
    try:
        rows = _fix_qty_outliers(rows)
    except Exception:
        pass
    try:
        rows = _booker_cleanup_fragment_items(rows)
    except Exception:
        pass
    try:
        rows = _booker_fix_free_lines(rows)
    except Exception:
        pass
    try:
        rows = _booker_merge_salvage_if_better(text or "", header or {}, rows)
    except Exception:
        pass
    try:
        rows = _booker_prune_google_candidate_rows(text or "", header or {}, rows)
    except Exception:
        pass
    for idx, row in enumerate(rows, start=1):
        row["lineNo"] = idx
    return rows


def _booker_google_ocr_candidate_score(text: str, header: Dict[str, Any], items: List[Dict[str, Any]]) -> Tuple[float, float, int, int]:
    rows = list(items or [])
    expected_total = _booker_expected_total_from_text(text)
    count_penalty = float(abs(len(rows) - expected_total)) if expected_total > 0 else 0.0
    diff = _candidate_diff(header or {}, rows)
    corrupt_penalty = 1 if _booker_items_look_corrupt(rows) else 0
    return (count_penalty, diff, corrupt_penalty, -len(rows))


def _booker_hybrid_local_skeleton_with_google(local_items: List[Dict[str, Any]], google_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    local_rows = [dict(it) for it in (local_items or []) if isinstance(it, dict)]
    google_rows = [dict(it) for it in (google_items or []) if isinstance(it, dict)]
    if not local_rows or not google_rows:
        return local_rows

    google_by_code: Dict[str, List[int]] = {}
    google_by_desc: Dict[str, List[int]] = {}
    for idx, row in enumerate(google_rows):
        code = re.sub(r"\D+", "", str(row.get("code") or ""))
        desc_key = _booker_desc_key(row.get("description") or "")
        if code:
            google_by_code.setdefault(code, []).append(idx)
        if desc_key:
            google_by_desc.setdefault(desc_key, []).append(idx)

    used: set = set()
    seq_idx = 0

    def _take_idx(candidates: List[int]) -> Optional[int]:
        for idx in candidates:
            if idx not in used:
                used.add(idx)
                return idx
        return None

    merged: List[Dict[str, Any]] = []
    value_keys = ("code", "description", "casePack", "unitSize", "qty", "totalUnits", "unitPrice", "lineNet", "vatCode", "vatRate", "vatAmount", "lineGross", "stdRrp", "por")
    for local_row in local_rows:
        match_idx = None
        code = re.sub(r"\D+", "", str(local_row.get("code") or ""))
        desc_key = _booker_desc_key(local_row.get("description") or "")
        if code:
            match_idx = _take_idx(google_by_code.get(code, []))
        if match_idx is None and desc_key:
            match_idx = _take_idx(google_by_desc.get(desc_key, []))
        if match_idx is None:
            while seq_idx < len(google_rows) and seq_idx in used:
                seq_idx += 1
            if seq_idx < len(google_rows):
                match_idx = seq_idx
                used.add(match_idx)
                seq_idx += 1

        row = dict(local_row)
        if match_idx is not None:
            grow = google_rows[match_idx]
            for key in value_keys:
                gv = grow.get(key)
                if key in ("code", "description", "unitSize", "vatCode"):
                    if str(gv or "").strip():
                        row[key] = gv
                else:
                    if _safe_float(gv) > 0.0 or (key in ("qty", "lineNet", "vatAmount", "lineGross") and gv is not None):
                        row[key] = gv
        merged.append(row)

    for idx, row in enumerate(merged, start=1):
        row["lineNo"] = idx
    return merged


def _booker_parse_google_ocr_fallback(text: str, header: Dict[str, Any]) -> Tuple[str, List[Dict[str, Any]]]:
    src = str(text or "")
    if not src.strip():
        return "", []

    candidates: List[Tuple[str, List[Dict[str, Any]]]] = []

    try:
        stack_items = _booker_parse_text_layer_stack(src)
        stack_items = _booker_prepare_google_ocr_items(src, header or {}, stack_items)
        if stack_items:
            candidates.append(("stacked", stack_items))
    except Exception:
        pass

    try:
        anchored_items = _booker_parse_code_anchored_blocks(src)
        anchored_items = _booker_prepare_google_ocr_items(src, header or {}, anchored_items)
        if anchored_items:
            candidates.append(("anchored_blocks", anchored_items))
    except Exception:
        pass

    try:
        code_items = _booker_parse_code_blocks_simple(src)
        code_items = _booker_prepare_google_ocr_items(src, header or {}, code_items)
        if code_items:
            candidates.append(("code_blocks", code_items))
    except Exception:
        pass

    try:
        row_text = _booker_build_rowified_text(src)
        row_items = BookerCombinedRowParser().parse(row_text) if row_text else []
        row_items = _booker_prepare_google_ocr_items(src, header or {}, row_items)
        if row_items:
            candidates.append(("rowified", row_items))
    except Exception:
        pass

    try:
        loose_items = _booker_parse_loose_blocks(src)
        loose_items = _booker_prepare_google_ocr_items(src, header or {}, loose_items)
        if loose_items:
            candidates.append(("loose_blocks", loose_items))
    except Exception:
        pass

    if not candidates:
        return "", []

    scored: List[Tuple[Tuple[float, float, int, int], str, List[Dict[str, Any]]]] = []
    for label, rows in candidates:
        scored.append((_booker_google_ocr_candidate_score(src, header or {}, rows), label, rows))
    scored.sort(key=lambda t: t[0])
    best = scored[0]
    return best[1], best[2]

def _attach_row_text_from_ocr(items: List[Dict[str, Any]], ocr_lines: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Attach row-level OCR text to each item (best-effort).

    Uses OCR line boxes to group into rows, then matches rows to items by code or position.
    """
    if not items or not ocr_lines:
        return items
    try:
        groups = _ix_group_lines_by_row(ocr_lines, y_tol=12.0)
        rows: List[str] = []
        for _page, g in groups:
            try:
                txt = str(_ix_row_text(g) or "").strip()
            except Exception:
                txt = ""
            if txt:
                rows.append(txt)
        if not rows:
            return items

        # Filter obvious headers/totals
        filtered: List[str] = []
        for txt in rows:
            up = txt.upper()
            if ("CODE" in up and "DESCRIPTION" in up and ("QTY" in up or "PACK" in up)):
                continue
            if any(k in up for k in ("TOTAL ITEMS", "INVOICE TOTAL", "TOTALS", "SUB-TOTAL", "RATE ")):
                continue
            filtered.append(txt)
        if not filtered:
            filtered = rows

        # If counts line up, map by position
        if len(filtered) == len(items):
            for it, txt in zip(items, filtered):
                if not it.get("rawRow"):
                    it["rawRow"] = txt
            return items

        # Map rows by code occurrence
        code_rows: Dict[str, List[str]] = {}
        for txt in filtered:
            for m in re.finditer(r"\b\d{5,7}\b", txt):
                code_rows.setdefault(m.group(0), []).append(txt)

        used_idx: set[int] = set()
        for it in items:
            if it.get("rawRow"):
                continue
            code = re.sub(r"[^0-9]+", "", str(it.get("code") or ""))
            if code and code_rows.get(code):
                it["rawRow"] = code_rows[code].pop(0)
                continue
            # Fallback: match by description fragment
            desc = str(it.get("description") or "").strip()
            desc = _norm_pack_tokens(desc)
            if desc:
                dfrag = desc[:10].upper()
                for i, r in enumerate(filtered):
                    if i in used_idx:
                        continue
                    if dfrag and dfrag in r.upper():
                        it["rawRow"] = r
                        used_idx.add(i)
                        break
        return items
    except Exception:
        return items

def _escape_html(s: str) -> str:
    """HTML-escape for safe embedding in st.markdown(unsafe_allow_html=True)."""
    return html.escape(s, quote=True)


def _fmt_money(v, places: int = 2) -> str:
    """Format a numeric value as money with fixed decimals. Returns "0.00" if blank."""
    x = _safe_float(v)
    if x is None:
        x = 0.0
    try:
        return f"{x:.{places}f}"
    except Exception:
        return f"{float(x):.{places}f}"
def _safe_eval_arith(expr: str) -> float | None:
    """Safely evaluate simple arithmetic expressions like '57.98+11.60'.

    Allowed: numbers, + - * /, parentheses, whitespace.
    Returns None if expression is not safe/valid.
    """
    import ast, operator as _op
    if expr is None:
        return None
    s = str(expr).strip()
    if not s:
        return None
    # Strip leading '=' and common currency symbols/commas
    if s.startswith("="):
        s = s[1:].strip()
    s = s.replace("", "").replace(",", "").strip()
    # Quick allowlist of characters
    if not re.fullmatch(r"[0-9\.\+\-\*\/\(\)\s]+", s):
        return None

    # AST safety
    try:
        node = ast.parse(s, mode="eval")
    except Exception:
        return None

    allowed_nodes = (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Num, ast.Constant,
                     ast.Add, ast.Sub, ast.Mult, ast.Div, ast.USub, ast.UAdd, ast.Load,
                     ast.Pow, ast.Mod, ast.FloorDiv, ast.Call, ast.Name)
    # Disallow Call/Name explicitly (keep allowlist simple)
    for n in ast.walk(node):
        if isinstance(n, (ast.Call, ast.Name, ast.Attribute, ast.Subscript, ast.Lambda, ast.Dict, ast.List, ast.Tuple)):
            return None
        if not isinstance(n, allowed_nodes):
            return None
        # Disallow operators other than + - * /
        if isinstance(n, (ast.Pow, ast.Mod, ast.FloorDiv)):
            return None

    ops = {ast.Add: _op.add, ast.Sub: _op.sub, ast.Mult: _op.mul, ast.Div: _op.truediv,
           ast.UAdd: lambda a: a, ast.USub: _op.neg}

    def _eval(n):
        if isinstance(n, ast.Expression):
            return _eval(n.body)
        if isinstance(n, ast.Constant):
            if isinstance(n.value, (int, float)):
                return float(n.value)
            return None
        if isinstance(n, ast.Num):  # py<3.8
            return float(n.n)
        if isinstance(n, ast.UnaryOp):
            fn = ops.get(type(n.op))
            val = _eval(n.operand)
            if fn is None or val is None:
                return None
            return fn(val)
        if isinstance(n, ast.BinOp):
            fn = ops.get(type(n.op))
            left = _eval(n.left)
            right = _eval(n.right)
            if fn is None or left is None or right is None:
                return None
            try:
                return fn(left, right)
            except Exception:
                return None
        return None

    return _eval(node)

def _maybe_number_from_editor(val):
    """Convert editor values to float, supporting simple '=a+b' formulas."""
    if val is None:
        return None
    if isinstance(val, (int, float)):
        return float(val)
    if isinstance(val, str):
        s = val.strip()
        if not s:
            return None
        # Try arithmetic evaluation if it looks like a formula
        if s.startswith("=") or any(ch in s for ch in "+-*/()"):
            v = _safe_eval_arith(s)
            if v is not None:
                return v
        # Fallback: regular float parsing
        try:
            return float(s.replace("","").replace(",",""))
        except Exception:
            return None
    return None


def _is_empty(v: object) -> bool:
    if v is None:
        return True
    if isinstance(v, str) and v.strip().lower() in ("", "none", "nan", "null"):
        return True
    return False


def _effective_line_gross(it: dict) -> float:
    """Return a robust gross amount even if lineGross is missing/incorrect."""
    net = _safe_float(it.get("lineNet"))
    vat = _safe_float(it.get("vatAmount"))
    gross = _safe_float(it.get("lineGross"))
    # Treat "gross == net" as missing gross if VAT exists (common supplier print/AI quirk).
    if (gross == 0 and net != 0) or (abs(gross - net) < 0.01 and abs(vat) > 0.01):
        return round(net + vat, 2)
    return gross


def _effective_line_vat(it: dict) -> float:
    net = _safe_float(it.get("lineNet"))
    vat = _safe_float(it.get("vatAmount"))
    rate = _safe_float(it.get("vatRate"))
    if vat == 0 and net != 0 and rate != 0:
        return round(net * (rate / 100.0), 2)
    return vat


def _normalise_items_for_persistence(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Persist the same effective VAT/gross values that the UI reconciliation uses."""
    out: List[Dict[str, Any]] = []
    for it in _normalise_promo_quantities(list(items or [])):
        if not isinstance(it, dict):
            continue
        row = dict(it)
        rate = _normalise_vat_rate(row.get("vatRate"))
        if rate:
            row["vatRate"] = rate
        row["vatAmount"] = _effective_line_vat(row)
        row["lineGross"] = _effective_line_gross(row)

        if _is_empty(row.get("totalUnits")):
            qty = _safe_float(row.get("qty"))
            case_pack = _safe_float(row.get("casePack"))
            if qty and case_pack:
                row["totalUnits"] = round(qty * case_pack, 2)
        out.append(row)
    return _normalise_promo_quantities(out)


def _effective_db_line_vat(it: Dict[str, Any]) -> float:
    net = _safe_float(it.get("line_net"))
    vat = _safe_float(it.get("vat_amount"))
    rate = _normalise_vat_rate(it.get("vat_rate"))
    if vat == 0 and net != 0 and rate != 0:
        return round(net * (rate / 100.0), 2)
    return vat


def _effective_db_line_gross(it: Dict[str, Any]) -> float:
    net = _safe_float(it.get("line_net"))
    vat = _effective_db_line_vat(it)
    gross = _safe_float(it.get("line_gross"))
    if (gross == 0 and net != 0) or (abs(gross - net) < 0.01 and abs(vat) > 0.01):
        return round(net + vat, 2)
    return gross


def _normalise_vat_rate(v: Any) -> float:
    """Normalise VAT rate so 0.2 becomes 20.0, keep 20 as 20."""
    r = _safe_float(v)
    if 0 < r < 1.0:
        r = r * 100.0
    return round(r, 4)



def _derive_vat_map_from_items(items: List[Dict[str, Any]]) -> Dict[str, float]:
    """Derive a VAT code -> rate (%) mapping from line items.

    Uses vatCode+vatRate if present; otherwise falls back to vatAmount/lineNet.
    """
    vat_map: Dict[str, float] = {}
    if not items:
        return vat_map
    for it in items:
        code = str(it.get("vatCode") or "").strip()
        if not code:
            continue
        rate = _safe_float(it.get("vatRate"))
        # Fallback: derive % from amounts if rate missing/zero
        if (rate is None) or (rate == 0.0 and it.get("vatRate") in (None, "", 0, 0.0)):
            net = _safe_float(it.get("lineNet"))
            vat = _safe_float(it.get("vatAmount"))
            if net and net > 0 and vat is not None:
                rate = round((vat / net) * 100.0, 2)
        if rate is None:
            continue
        # Prefer a non-zero rate if we already captured 0
        if code not in vat_map or (vat_map.get(code, 0.0) == 0.0 and rate > 0.0):
            vat_map[code] = float(rate)
    return vat_map


def _recalc_items(items: list[dict]) -> list[dict]:
    """Recalculate derived fields after edits (and normalise gross/net/vat consistency)."""
    out = []
    for it in _normalise_promo_quantities(list(items or [])):
        it = dict(it or {})
        # Normalise key fields
        qty = _safe_float(it.get("qty"), 0.0)
        case_pack = _safe_float(it.get("casePack"), 0.0)
        unit_price = _safe_float(it.get("unitPrice"), 0.0)
        row_sign = -1.0 if (qty < 0 or bool(it.get("isVoid"))) else 1.0

        # VAT rate normalisation
        vat_rate = _normalise_vat_rate(it.get("vatRate"))
        if vat_rate is None:
            vat_rate = 0.0
        it["vatRate"] = vat_rate

        # totalUnits
        total_units = _safe_float(it.get("totalUnits"), 0.0)
        if case_pack > 0 and qty > 0:
            expected_units = case_pack * qty
            # Repair obviously wrong totals (OCR/LLM sometimes injects huge values)
            if total_units <= 0 or abs(total_units - expected_units) > max(1.0, expected_units * 0.5):
                total_units = expected_units
        elif case_pack > 0 and qty < 0:
            expected_units = case_pack * qty
            if total_units == 0 or abs(abs(total_units) - abs(expected_units)) > max(1.0, abs(expected_units) * 0.5):
                total_units = expected_units
        if row_sign < 0 and total_units > 0:
            total_units = -abs(total_units)
        it["totalUnits"] = total_units

        # Amounts (capture what user may have entered)
        has_line_net = not _is_empty(it.get("lineNet"))
        has_vat_amt = not _is_empty(it.get("vatAmount"))
        has_line_gross = not _is_empty(it.get("lineGross"))

        line_net = _safe_float(it.get("lineNet"), 0.0)
        vat_amount = _safe_float(it.get("vatAmount"), 0.0)
        line_gross = _safe_float(it.get("lineGross"), 0.0)

        # If lineNet is blank, try compute from qty & unitPrice. Preserve an
        # explicit 0.00 line amount; some credit memos show a unit price but a
        # zero posting amount after discount/credit application.
        if (not has_line_net) and qty > 0 and unit_price > 0:
            line_net = round(qty * unit_price, 2)
            it["lineNet"] = line_net
            has_line_net = True
        # If unitPrice looks like the line total (common OCR swap) and qty > 1, fix it
        if qty > 1 and line_net > 0 and (unit_price == 0 or abs(unit_price - line_net) < 0.01):
            unit_price = round(line_net / qty, 2)
            it["unitPrice"] = unit_price

        expected_vat = round(line_net * (vat_rate / 100.0), 2) if line_net != 0 and vat_rate != 0 else vat_amount
        vat_implausible = (
            has_vat_amt
            and vat_rate != 0
            and abs(vat_amount - expected_vat) > max(0.05, abs(expected_vat) * 0.10)
            and abs(vat_amount) > max(abs(line_net) * 0.50, 1.0)
        )
        if vat_implausible:
            vat_amount = expected_vat
            it["vatAmount"] = vat_amount

        # Infer missing amount from the other two where possible
        if has_line_net and has_vat_amt:
            line_gross = round(line_net + vat_amount, 2)
            it["lineGross"] = line_gross
            has_line_gross = True
        elif has_line_net and has_line_gross and not has_vat_amt and line_gross != 0:
            vat_amount = round(line_gross - line_net, 2)
            it["vatAmount"] = vat_amount
            has_vat_amt = True
        elif has_vat_amt and has_line_gross and not has_line_net and line_gross != 0:
            line_net = round(line_gross - vat_amount, 2)
            it["lineNet"] = line_net
            has_line_net = True

        # If VAT still missing, compute from rate
        if (not has_vat_amt or vat_amount == 0) and line_net != 0 and vat_rate != 0:
            vat_amount = round(line_net * (vat_rate / 100.0), 2)
            it["vatAmount"] = vat_amount
            has_vat_amt = True

        # If gross still missing or equals net but VAT exists, compute
        line_gross = _safe_float(it.get("lineGross"), 0.0)
        if (not has_line_gross or line_gross == 0) and line_net != 0:
            line_gross = round(line_net + vat_amount, 2)
            it["lineGross"] = line_gross
            has_line_gross = True
        else:
            # Fix common issue: gross captured as net (missing VAT)
            if abs(line_gross - line_net) < 0.01 and abs(vat_amount) > 0.01:
                it["lineGross"] = round(line_net + vat_amount, 2)

        # Return/void lines must carry negative financial amounts even if OCR captured
        # the qty as negative but left net/vat/gross positive.
        if row_sign < 0:
            if line_net != 0:
                line_net = -abs(line_net)
                it["lineNet"] = line_net
            if vat_amount != 0:
                vat_amount = -abs(vat_amount)
                it["vatAmount"] = vat_amount
            line_gross = _safe_float(it.get("lineGross"), 0.0)
            if line_gross != 0:
                line_gross = -abs(line_gross)
                it["lineGross"] = line_gross

        # unitCost (per stock unit)
        unit_cost = _safe_float(it.get("unitCost"), 0.0)
        if unit_cost == 0 and total_units > 0 and line_net > 0:
            unit_cost = round(line_net / total_units, 4)
        it["unitCost"] = unit_cost

        # POR (%) from stdRrp (inc VAT) when available
        std_rrp_inc = _safe_float(it.get("stdRrp"), 0.0)
        # DWG safeguard: convert pence-based RRP (e.g. 70 from "PM 70P") into pounds.
        try:
            desc_txt = str(it.get("description") or "")
            if std_rrp_inc >= 10 and std_rrp_inc <= 99 and abs(std_rrp_inc - round(std_rrp_inc)) < 0.001:
                if re.search(r"\bPM\b|\bPMP\b", desc_txt, flags=re.IGNORECASE) or re.search(r"\b\d{2}\s*P\b", desc_txt, flags=re.IGNORECASE):
                    std_rrp_inc = round(std_rrp_inc / 100.0, 2)
                    it["stdRrp"] = std_rrp_inc
        except Exception:
            pass

        por = _safe_float(it.get("por"), 0.0)
        # Only compute POR if it's missing/zero; keep extracted POR when present.
        if por <= 0 and std_rrp_inc > 0 and unit_cost > 0 and vat_rate >= 0:
            sell_ex = std_rrp_inc / (1.0 + (vat_rate / 100.0)) if vat_rate else std_rrp_inc
            if sell_ex > 0:
                por = (sell_ex - unit_cost) / sell_ex * 100.0
                por = round(por, 1)
        it["por"] = por

        out.append(it)
    return _normalise_promo_quantities(out)


def _repair_teacher_invoice_level_vat(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
) -> Tuple[List[Dict[str, Any]], bool]:
    """Reconcile reviewed teacher rows when VAT is only printed at invoice level."""
    rows = [dict(it) for it in (items or []) if isinstance(it, dict)]
    if not rows:
        return rows, False
    header_net = round(_safe_float((header or {}).get("totalNet")), 2)
    header_vat = round(_safe_float((header or {}).get("totalVat")), 2)
    header_gross = round(_safe_float((header or {}).get("totalGross")), 2)
    if header_gross <= 0 or abs(header_vat) <= 0.005:
        return rows, False

    sum_net = round(sum(_safe_float(it.get("lineNet")) for it in rows), 2)
    sum_vat = round(sum(_safe_float(it.get("vatAmount")) for it in rows), 2)
    sum_gross = round(sum(_safe_float(it.get("lineGross")) for it in rows), 2)
    if abs(sum_gross) <= 0.005:
        sum_gross = round(sum_net + sum_vat, 2)
        for it in rows:
            if abs(_safe_float(it.get("lineGross"))) <= 0.005:
                it["lineGross"] = round(_safe_float(it.get("lineNet")) + _safe_float(it.get("vatAmount")), 2)

    missing_vat_shape = (
        abs(sum_gross - header_gross) <= 0.05
        and abs(sum_vat) <= 0.05
        and abs(sum_net - header_gross) <= 0.05
        and abs((sum_net - header_net) - header_vat) <= 0.10
    )
    if not missing_vat_shape:
        return rows, False

    candidate_idxs = [
        idx for idx, it in enumerate(rows)
        if abs(_safe_float(it.get("lineGross"))) > 0.005
        and not bool(it.get("_reconOnly"))
        and not bool(it.get("isVoid"))
    ]
    has_positive = any(_safe_float(rows[idx].get("lineGross")) > 0.005 for idx in candidate_idxs)
    has_negative = any(_safe_float(rows[idx].get("lineGross")) < -0.005 for idx in candidate_idxs)
    if has_positive and has_negative and abs(round(sum(_safe_float(rows[idx].get("lineGross")) for idx in candidate_idxs), 2)) > 0.005:
        taxable_idxs = candidate_idxs
        allocation_mode = "signed_gross"
    else:
        taxable_idxs = [
            idx for idx in candidate_idxs
            if _safe_float(rows[idx].get("lineGross")) > 0.005
        ]
        allocation_mode = "positive_gross"
    if not taxable_idxs:
        taxable_idxs = candidate_idxs
        allocation_mode = "absolute_gross"
    if not taxable_idxs:
        return rows, False

    if allocation_mode == "signed_gross":
        basis_total = round(sum(_safe_float(rows[idx].get("lineGross")) for idx in taxable_idxs), 2)
    else:
        basis_total = round(sum(abs(_safe_float(rows[idx].get("lineGross"))) for idx in taxable_idxs), 2)
    if abs(basis_total) <= 0.005:
        return rows, False

    allocated = 0.0
    for pos, idx in enumerate(taxable_idxs):
        row = rows[idx]
        gross = round(_safe_float(row.get("lineGross")), 2)
        if pos == len(taxable_idxs) - 1:
            vat = round(header_vat - allocated, 2)
        else:
            basis_value = gross if allocation_mode == "signed_gross" else abs(gross)
            vat = round(header_vat * (basis_value / basis_total), 2)
            allocated = round(allocated + vat, 2)
        if gross < 0 and allocation_mode != "signed_gross":
            vat = -abs(vat)
        row["vatAmount"] = vat
        row["lineNet"] = round(gross - vat, 2)
        row["lineGross"] = gross
        if abs(_safe_float(row.get("lineNet"))) > 0.005:
            row["vatRate"] = round((vat / _safe_float(row.get("lineNet"))) * 100.0, 2)
        row["_teacher_invoice_level_vat"] = True
        row["_teacher_vat_allocation_mode"] = allocation_mode

    repaired_vat = round(sum(_safe_float(it.get("vatAmount")) for it in rows), 2)
    repaired_net = round(sum(_safe_float(it.get("lineNet")) for it in rows), 2)
    repaired_gross = round(sum(_safe_float(it.get("lineGross")) for it in rows), 2)
    ok = (
        abs(repaired_net - header_net) <= 0.05
        and abs(repaired_vat - header_vat) <= 0.05
        and abs(repaired_gross - header_gross) <= 0.05
    )
    return rows, bool(ok)


def _raw_text_prints_zero_vat(raw_text: str) -> bool:
    """True when the invoice text explicitly prints VAT as zero."""
    txt = str(raw_text or "")
    if not txt.strip():
        return False
    if re.search(r"(?im)^\s*VAT\s*:\s*(?:Reverse\s+Charge\s*)?0(?:\.00)?\s*$", txt):
        return True
    if re.search(r"(?im)\bVAT\s*:\s*Reverse\s+Charge\s+0(?:\.00)?\b", txt):
        return True
    if re.search(r"(?im)\bTotal\s+VAT\b[^0-9\-]{0,30}0(?:\.00)?\b", txt):
        return True
    return False


def _normalise_teacher_header_from_raw_text(header: Dict[str, Any], raw_text: str) -> Dict[str, Any]:
    """Trust explicit printed zero VAT over model-inferred VAT during template learning."""
    out = dict(header or {})
    if not _raw_text_prints_zero_vat(raw_text or ""):
        return out
    gross = round(_safe_float(out.get("totalGross")), 2)
    net = round(_safe_float(out.get("totalNet")), 2)
    vat = round(_safe_float(out.get("totalVat")), 2)
    if gross > 0 and (vat != 0.0 or abs((net + vat) - gross) > 0.05):
        out["totalVat"] = 0.0
        out["totalNet"] = gross
        out["_teacher_header_zero_vat_from_text"] = True
    elif vat != 0.0:
        out["totalVat"] = 0.0
        out["_teacher_header_zero_vat_from_text"] = True
    return out


def _recalc_items_tesseract(items: list[dict]) -> list[dict]:
    """Tesseract-only recalc using the v1.06 logic (more conservative)."""
    out = []
    for it in _normalise_promo_quantities(list(items or [])):
        it = dict(it or {})
        # Normalise key fields
        qty = _safe_float(it.get("qty"), 0.0)
        case_pack = _safe_float(it.get("casePack"), 0.0)
        unit_price = _safe_float(it.get("unitPrice"), 0.0)

        # VAT rate normalisation
        vat_rate = _normalise_vat_rate(it.get("vatRate"))
        if vat_rate is None:
            vat_rate = 0.0
        it["vatRate"] = vat_rate

        # totalUnits
        total_units = _safe_float(it.get("totalUnits"), 0.0)
        if total_units == 0 and case_pack > 0 and qty > 0:
            total_units = case_pack * qty
        it["totalUnits"] = total_units

        # Amounts (capture what user may have entered)
        has_line_net = not _is_empty(it.get("lineNet"))
        has_vat_amt = not _is_empty(it.get("vatAmount"))
        has_line_gross = not _is_empty(it.get("lineGross"))

        line_net = _safe_float(it.get("lineNet"), 0.0)
        vat_amount = _safe_float(it.get("vatAmount"), 0.0)
        line_gross = _safe_float(it.get("lineGross"), 0.0)

        # If lineNet is blank, try compute from qty & unitPrice. Preserve an
        # explicit 0.00 line amount from supplier credit/discount rows.
        if (not has_line_net) and qty > 0 and unit_price > 0:
            line_net = round(qty * unit_price, 2)
            it["lineNet"] = line_net
            has_line_net = True

        expected_vat = round(line_net * (vat_rate / 100.0), 2) if line_net != 0 and vat_rate != 0 else vat_amount
        vat_implausible = (
            has_vat_amt
            and vat_rate != 0
            and abs(vat_amount - expected_vat) > max(0.05, abs(expected_vat) * 0.10)
            and abs(vat_amount) > max(abs(line_net) * 0.50, 1.0)
        )
        if vat_implausible:
            vat_amount = expected_vat
            it["vatAmount"] = vat_amount

        # Infer missing amount from the other two where possible
        if has_line_net and has_vat_amt:
            line_gross = round(line_net + vat_amount, 2)
            it["lineGross"] = line_gross
            has_line_gross = True
        elif has_line_net and has_line_gross and not has_vat_amt and line_gross != 0:
            vat_amount = round(line_gross - line_net, 2)
            it["vatAmount"] = vat_amount
            has_vat_amt = True
        elif has_vat_amt and has_line_gross and not has_line_net and line_gross != 0:
            line_net = round(line_gross - vat_amount, 2)
            it["lineNet"] = line_net
            has_line_net = True

        # If VAT still missing, compute from rate
        if (not has_vat_amt or vat_amount == 0) and line_net != 0 and vat_rate != 0:
            vat_amount = round(line_net * (vat_rate / 100.0), 2)
            it["vatAmount"] = vat_amount
            has_vat_amt = True

        # If gross still missing or equals net but VAT exists, compute
        line_gross = _safe_float(it.get("lineGross"), 0.0)
        if (not has_line_gross or line_gross == 0) and line_net != 0:
            line_gross = round(line_net + vat_amount, 2)
            it["lineGross"] = line_gross
            has_line_gross = True
        else:
            # Fix common issue: gross captured as net (missing VAT)
            if abs(line_gross - line_net) < 0.01 and abs(vat_amount) > 0.01:
                it["lineGross"] = round(line_net + vat_amount, 2)

        # unitCost (per stock unit)
        unit_cost = _safe_float(it.get("unitCost"), 0.0)
        if unit_cost == 0 and total_units > 0 and line_net > 0:
            unit_cost = round(line_net / total_units, 4)
        it["unitCost"] = unit_cost

        # POR (%) from stdRrp (inc VAT) when available
        std_rrp_inc = _safe_float(it.get("stdRrp"), 0.0)
        # DWG safeguard: convert pence-based RRP (e.g. 70 from "PM 70P") into pounds.
        try:
            desc_txt = str(it.get("description") or "")
            if std_rrp_inc >= 10 and std_rrp_inc <= 99 and abs(std_rrp_inc - round(std_rrp_inc)) < 0.001:
                if re.search(r"\bPM\b|\bPMP\b", desc_txt, flags=re.IGNORECASE) or re.search(r"\b\d{2}\s*P\b", desc_txt, flags=re.IGNORECASE):
                    std_rrp_inc = round(std_rrp_inc / 100.0, 2)
                    it["stdRrp"] = std_rrp_inc
        except Exception:
            pass

        por = _safe_float(it.get("por"), 0.0)
        if std_rrp_inc > 0 and unit_cost > 0 and vat_rate >= 0:
            sell_ex = std_rrp_inc / (1.0 + (vat_rate / 100.0)) if vat_rate else std_rrp_inc
            if sell_ex > 0:
                por = (sell_ex - unit_cost) / sell_ex * 100.0
                por = round(por, 1)
            it["por"] = por
        else:
            it["por"] = por

        out.append(it)
    return _normalise_promo_quantities(out)


def _recalc_items_for_engine(items: list[dict], engine: str) -> list[dict]:
    eng = (engine or "").lower().strip()
    if eng in ("tesseract", "local_tesseract"):
        return _recalc_items_tesseract(items)
    return _recalc_items(items)
def _calc_vat_breakdown_from_items(
    items: List[Dict[str, Any]],
    supplier_hint: str = "",
    header_vat: float = 0.0,
) -> List[Dict[str, Any]]:
    """Group calculated VAT breakdown from line items."""
    by_code: Dict[str, Dict[str, float]] = {}
    for it in (items or []):
        code = str(it.get("vatCode") or "").strip().upper() or "UNK"
        net = _safe_float(it.get("lineNet"))
        vat = _safe_float(it.get("vatAmount"))
        gross = _safe_float(it.get("lineGross"))
        # Avoid polluting the breakdown with an empty UNK row (common after manual edits)
        if code == "UNK" and net == 0.0 and vat == 0.0 and gross == 0.0:
            continue
        if (gross == 0 and net != 0) or (abs(gross - net) < 0.01 and abs(vat) > 0.01):
            gross = net + vat
        if code not in by_code:
            by_code[code] = {"net": 0.0, "vat": 0.0, "gross": 0.0}
        by_code[code]["net"] += net
        by_code[code]["vat"] += vat
        by_code[code]["gross"] += gross

    supplier_u = str(supplier_hint or "").upper()
    use_gross_minus_vat_net = "BOOKER" in supplier_u
    use_band_rounding = ("DHAMECHA" in supplier_u) and not use_gross_minus_vat_net
    rows: List[Dict[str, Any]] = []
    for code, agg in by_code.items():
        vat_amount = round(agg["vat"], 2)
        gross_amount = round(agg["gross"], 2)
        net_amount = round(agg["net"], 2)
        if use_band_rounding:
            rate = {"A": 20.0, "B": 5.0, "R": 5.0, "Z": 0.0}.get(code)
            if rate is not None:
                vat_amount = round(agg["net"] * rate / 100.0, 2)
                gross_amount = round(agg["net"] + vat_amount, 2)
                net_amount = round(agg["net"], 2)
        elif use_gross_minus_vat_net and abs(gross_amount) > 0.0001:
            net_amount = round(gross_amount - vat_amount, 2)
        rows.append(
            {
                "vatCode": code,
                "netAmount": net_amount,
                "vatAmount": vat_amount,
                "grossAmount": gross_amount,
                "_source": "calculated",
            }
        )
    return rows


def _generate_pdf_report_bytes(
    file_name: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    reconciliation: Dict[str, Any],
    recon_notes: List[str],
) -> bytes:
    """
    Generate a printable PDF report (A4 landscape) for the processed invoice.

    IMPORTANT:
    - Requires 'reportlab' to be installed on the runtime machine.
    - If reportlab is missing, we raise a clear error so the UI can show guidance
      (and fall back to HTML report download).
    """
    try:
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.lib import colors
        from reportlab.lib.units import mm
    except Exception as e:
        raise RuntimeError("PDF engine not available. Please install 'reportlab' (pip install reportlab).") from e

    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf,
        pagesize=landscape(A4),
        leftMargin=12 * mm,
        rightMargin=12 * mm,
        topMargin=10 * mm,
        bottomMargin=10 * mm,
        title="DocMate Invoice Audit Report",
        author="Visual Business Retail Ltd",
    )

    styles = getSampleStyleSheet()
    story: List[Any] = []

    from reportlab.lib.enums import TA_CENTER
    # Report heading
    release_date_disp = APP_DATE
    try:
        release_date_disp = datetime.strptime(str(APP_DATE), "%Y-%m-%d").strftime("%d/%m/%Y")
    except Exception:
        pass

    title_style = styles["Title"]
    title_style.alignment = TA_CENTER
    small_style = styles["BodyText"]
    small_style.alignment = TA_CENTER

    story.append(Paragraph("<b>DocMate Invoice Audit Report</b>", title_style))
    story.append(Paragraph(f"<b>Version:</b> {APP_VERSION} | <b>Release Date:</b> {release_date_disp}", small_style))
    story.append(Spacer(1, 6))

    supplier = str(header.get("supplierName") or "")
    story.append(Paragraph(f"DocMate Invoice Report for Supplier: <b>{supplier}</b> - Doc. File Name: <b>{file_name}</b>", styles["BodyText"]))
    story.append(Spacer(1, 8))

    customer = str(header.get("customerName") or "")
    inv_no = str(header.get("invoiceNumber") or "")
    inv_date = str(header.get("invoiceDate") or "")
    # Keep date only (strip any time component)
    if " " in inv_date:
        inv_date = inv_date.split(" ")[0]
    if "T" in inv_date:
        inv_date = inv_date.split("T")[0]

    # Totals: captured header vs calculated from items (after any edits)
    calc_items = _recalc_items(items)
    net_calc = round(sum(_safe_float(i.get("lineNet")) for i in calc_items), 2)
    vat_calc = round(sum(_safe_float(i.get("vatAmount")) for i in calc_items), 2)
    gross_calc = round(sum(_safe_float(i.get("lineGross")) for i in calc_items), 2)

    net_hdr = round(_safe_float(header.get("totalNet")), 2)
    vat_hdr = round(_safe_float(header.get("totalVat")), 2)
    gross_hdr = round(_safe_float(header.get("totalGross")), 2)
    skip_reconciliation = bool((reconciliation or {}).get("skipReconciliation"))

    if skip_reconciliation:
        summary_data = [
            ["Supplier", supplier, "Customer", customer],
            ["Invoice Date", inv_date, "Invoice Number", inv_no],
            ["Net", f"{net_hdr:,.2f}", "VAT", f"{vat_hdr:,.2f}"],
            ["Gross", f"{gross_hdr:,.2f}", "Extraction Mode", "Header Only"],
        ]
    else:
        summary_data = [
            ["Supplier", supplier, "Customer", customer],
            ["Invoice Date", inv_date, "Invoice Number", inv_no],
            ["Header Net", f"{net_hdr:,.2f}", "Line Net", f"{net_calc:,.2f}"],
            ["Header VAT", f"{vat_hdr:,.2f}", "Line VAT", f"{vat_calc:,.2f}"],
            ["Header Gross", f"{gross_hdr:,.2f}", "Line Gross", f"{gross_calc:,.2f}"],
        ]
    t = Table(summary_data, colWidths=[28*mm, 70*mm, 28*mm, 70*mm])
    t.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, 1), colors.whitesmoke),
                ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
                ("ALIGN", (0, 0), (-1, -1), "LEFT"),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ("FONTNAME", (0, 2), (-1, -1), "Helvetica"),
                ("FONTSIZE", (0, 0), (-1, -1), 9),
                ("VALIGN", (0, 0), (-1, -1), "MIDDLE"),
            ]
        )
    )
    story.append(t)
    story.append(Spacer(1, 8))

    if not skip_reconciliation:
        # Reconciliation
        story.append(Paragraph("<b>Reconciliation</b>", styles["Heading2"]))
        recon_rows = [
            ["Check", "Line Items", "Header", "Diff", "Status"],
            ["Net", f"{net_calc:,.2f}", f"{net_hdr:,.2f}", f"{(net_calc-net_hdr):,.2f}", str(reconciliation.get("netStatus") or "")],
            ["VAT", f"{vat_calc:,.2f}", f"{vat_hdr:,.2f}", f"{(vat_calc-vat_hdr):,.2f}", str(reconciliation.get("vatStatus") or "")],
            ["Gross", f"{gross_calc:,.2f}", f"{gross_hdr:,.2f}", f"{(gross_calc-gross_hdr):,.2f}", str(reconciliation.get("grossStatus") or "")],
        ]
        rt = Table(recon_rows, colWidths=[18*mm, 28*mm, 28*mm, 22*mm, 20*mm])
        rt.setStyle(
            TableStyle(
                [
                    ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
                    ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
                    ("ALIGN", (0, 0), (-1, -1), "LEFT"),
                    ("LEFTPADDING", (0, 0), (-1, -1), 6),
                    ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                    ("FONTSIZE", (0, 0), (-1, -1), 9),
                    ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ]
            )
        )
        story.append(rt)

        if recon_notes:
            story.append(Spacer(1, 6))
            notes_txt = "<br/>".join([f"- {str(n)}" for n in recon_notes])
            story.append(Paragraph(f"<b>Notes</b><br/>{notes_txt}", styles["BodyText"]))

        story.append(Spacer(1, 10))

    # VAT Breakdown (calculated)
    story.append(Paragraph("<b>VAT Breakdown (calculated from line items)</b>", styles["Heading2"]))
    vat_rows = _calc_vat_breakdown_from_items(calc_items)
    vat_table = [["VAT Code", "Net", "VAT", "Gross"]]
    for r in vat_rows:
        vat_table.append([
            str(r.get("vatCode") or ""),
            f'{_safe_float(r.get("netAmount")):,.2f}',
            f'{_safe_float(r.get("vatAmount")):,.2f}',
            f'{_safe_float(r.get("grossAmount")):,.2f}',
        ])
    vt = Table(vat_table, colWidths=[24*mm, 26*mm, 26*mm, 26*mm])
    vt.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
                ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
                ("ALIGN", (0, 0), (-1, -1), "LEFT"),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("FONTSIZE", (0, 0), (-1, -1), 9),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
            ]
        )
    )
    story.append(vt)
    story.append(Spacer(1, 10))

    # Line items table (truncate description for PDF width)
    story.append(Paragraph("<b>Line Items</b>", styles["Heading2"]))
    cols = ["lineNo","code","description","casePack","unitSize","qty","totalUnits","unitPrice","lineNet","vatCode","vatRate","vatAmount","lineGross"]
    table_rows = [cols]
    for it in calc_items:
        desc = str(it.get("description") or "")
        if len(desc) > 60:
            desc = desc[:57] + "..."
        row = [
            str(it.get("lineNo") or ""),
            str(it.get("code") or ""),
            desc,
            str(it.get("casePack") or ""),
            str(it.get("unitSize") or ""),
            f'{_safe_float(it.get("qty")):g}',
            f'{_safe_float(it.get("totalUnits")):g}',
            f'{_safe_float(it.get("unitPrice")):,.2f}',
            f'{_safe_float(it.get("lineNet")):,.2f}',
            str(it.get("vatCode") or ""),
            f'{_safe_float(it.get("vatRate")):g}',
            f'{_safe_float(it.get("vatAmount")):,.2f}',
            f'{_safe_float(it.get("lineGross")):,.2f}',
        ]
        table_rows.append(row)


    # Totals row (calculated fields)
    tot_qty = round(sum(_safe_float(i.get("qty")) for i in calc_items), 3)
    tot_units = round(sum(_safe_float(i.get("totalUnits")) for i in calc_items), 3)
    tot_net = round(sum(_safe_float(i.get("lineNet")) for i in calc_items), 2)
    tot_vat = round(sum(_safe_float(i.get("vatAmount")) for i in calc_items), 2)
    tot_gross = round(sum(_safe_float(i.get("lineGross")) for i in calc_items), 2)

    total_row = ["", "", "TOTAL", "", "", f"{tot_qty:g}", f"{tot_units:g}", "", f"{tot_net:,.2f}", "", "", f"{tot_vat:,.2f}", f"{tot_gross:,.2f}"]
    table_rows.append(total_row)

    lt = Table(table_rows, repeatRows=1)
    lt.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, 0), colors.lightgrey),
                ("GRID", (0, 0), (-1, -1), 0.25, colors.grey),
                ("ALIGN", (0, 0), (-1, -1), "LEFT"),
                ("LEFTPADDING", (0, 0), (-1, -1), 6),
                ("RIGHTPADDING", (0, 0), (-1, -1), 6),
                ("FONTSIZE", (0, 0), (-1, -1), 8),
                ("FONTNAME", (0, 0), (-1, 0), "Helvetica-Bold"),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("BACKGROUND", (0, -1), (-1, -1), colors.whitesmoke),
                ("FONTNAME", (0, -1), (-1, -1), "Helvetica-Bold"),
                ("LINEABOVE", (0, -1), (-1, -1), 0.6, colors.black),
            ]
        )
    )
    story.append(lt)

    # Footer
    def _footer(canvas, doc_obj):
        canvas.saveState()
        canvas.setFont("Helvetica", 8)
        canvas.drawString(12*mm, 7*mm, "Generated by DocMate (Visual Business Retail Ltd) - compatible with DocMate Registers and VBR Cloud Reporting.")
        canvas.drawRightString(285*mm, 7*mm, f"Page {doc_obj.page}")
        canvas.restoreState()

    doc.build(story, onFirstPage=_footer, onLaterPages=_footer)

    pdf_bytes = buf.getvalue()
    # Guard: never allow empty/near-empty PDF to be downloaded
    if not pdf_bytes or len(pdf_bytes) < 500:
        raise RuntimeError("PDF generation produced empty output.")
    return pdf_bytes


