STOP_WORDS = {"LTD", "LIMITED", "PLC", "LLP", "CO", "COMPANY", "INC", "INCORPORATED", "THE"}

def _db_has_booker_supplier_template() -> bool:
    try:
        row = _db_fetchone("SELECT template_id FROM supplier_templates WHERE UPPER(TRIM(parser_type))='BOOKER' LIMIT 1")
        return bool(row)
    except Exception:
        return False



def _supplier_acronym(supplier_name: str) -> str:
    s = (supplier_name or "").upper()
    if "BOOKER" in s:
        return "BKL"
    if "DRINKS WHOLESALE" in s or "DWG" in s:
        return "DWG"
    words = re.findall(r"[A-Z0-9]+", s)
    core = [w for w in words if w and w not in STOP_WORDS]
    if core:
        acr = "".join([w[0] for w in core])[:3]
    else:
        acr = re.sub(r"[^A-Z0-9]", "", s)[:3] or "SUP"
    return acr.ljust(3, "X")


def _customer_acronym(customer_name: str) -> str:
    s = (customer_name or "").upper()
    # Common: Fresher Kingston (for purchase)  but for customer templates, create from name
    words = re.findall(r"[A-Z0-9]+", s)
    core = [w for w in words if w and w not in STOP_WORDS]
    if core:
        acr = "".join([w[0] for w in core])[:3]
    else:
        acr = re.sub(r"[^A-Z0-9]", "", s)[:3] or "CST"
    return acr.ljust(3, "X")


def _next_display_id(prefix: str, yyyymmdd: str, table: str) -> str:
    # Format: PREFIXYYYYMMDD-01
    patt = f"{prefix}{yyyymmdd}-"
    rows = _db_fetchall(f"SELECT display_id FROM {table} WHERE display_id LIKE ?", (patt + "%",))
    used = set([(r.get("display_id") if isinstance(r, dict) else r[0]) for r in rows if (r.get("display_id") if isinstance(r, dict) else r[0])])
    i = 1
    while True:
        cand = f"{patt}{i:02d}"
        if cand not in used:
            return cand
        i += 1


def _template_keywords(name: str, extra: Optional[List[str]] = None) -> List[str]:
    out = []
    seen = set()
    if name:
        out.append(name.strip())
        out.append(re.sub(r"\s+", " ", name.strip().upper()))
        # add tokenised bits
        toks = re.findall(r"[A-Z0-9]+", name.upper())
        out.extend(list(dict.fromkeys(toks))[:8])
    if extra:
        for e in extra:
            e = (e or "").strip()
            if e:
                out.append(e)
    # de-dup, keep order
    dedup = []
    for k in out:
        k2 = k.strip()
        if not k2:
            continue
        if k2.lower() in seen:
            continue
        seen.add(k2.lower())
        dedup.append(k2)
    return dedup


def _template_score(doc_text: str, keywords: List[str]) -> int:
    """Score a template match against document text.

    We deliberately:
    - ignore very short keywords (<4 chars) to reduce false matches
    - ignore common invoice stop-words
    - keep simple 'contains' matching for speed (AUTO mode)

    This makes templates resilient when invoice numbers change (typical case),
    while still matching reliably on supplier/customer identifiers.
    """
    txt = (doc_text or '').upper()
    score = 0
    for kw in (keywords or []):
        if not kw:
            continue
        k = str(kw).strip().upper()
        if len(k) < 4:
            continue
        if k in {'LTD.', 'LIMITED.'}:
            k = k.replace('.', '')
        if k in {
            'LTD', 'LIMITED', 'INVOICE', 'VAT', 'TOTAL', 'NET', 'GROSS', 'AMOUNT',
            'DATE', 'NUMBER', 'SUPPLIER', 'CUSTOMER', 'TAX', 'GOODS', 'DISCOUNT', 'DELIVERY'
        }:
            continue
        if k and (k in txt):
            score += 1
    return score


