def _template_read_json_session(key: str, default: Any) -> Any:
    try:
        raw = st.session_state.get(key)
        if raw in (None, ""):
            return copy.deepcopy(default)
        if isinstance(raw, str):
            parsed = json.loads(raw)
        else:
            parsed = copy.deepcopy(raw)
        return parsed if parsed is not None else copy.deepcopy(default)
    except Exception:
        return copy.deepcopy(default)


def _template_write_json_session(key: str, value: Any) -> None:
    try:
        st.session_state[key] = json.dumps(value, ensure_ascii=False, indent=2, default=str)
    except Exception:
        st.session_state[key] = value


def _template_extra_field_label(field: str) -> str:
    s = re.sub(r"[_\-]+", " ", str(field or "").strip())
    s = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", s)
    return _collapse_spaces(s).title() if s else ""


def _template_extra_header_candidates(header: Dict[str, Any]) -> List[Dict[str, str]]:
    rows: List[Dict[str, str]] = []
    for key, value in (header or {}).items():
        field = str(key or "").strip()
        if not field or field.startswith("_") or field in _STANDARD_HEADER_EDITOR_FIELDS:
            continue
        if isinstance(value, (dict, list)):
            continue
        text = _collapse_spaces(str(value or "").strip())
        if not text:
            continue
        rows.append({"field": field, "label": _template_extra_field_label(field), "value": text})
    return rows


def _template_extra_line_candidates(items: List[Dict[str, Any]]) -> List[Dict[str, str]]:
    seen: set[str] = set()
    rows: List[Dict[str, str]] = []
    for item in items or []:
        if not isinstance(item, dict):
            continue
        for key, value in item.items():
            field = str(key or "").strip()
            if not field or field.startswith("_") or field in _CORE_LINE_FIELDS or field in seen:
                continue
            if isinstance(value, (dict, list)):
                continue
            text = _collapse_spaces(str(value or "").strip())
            if not text:
                continue
            seen.add(field)
            rows.append({"field": field, "label": _template_extra_field_label(field), "sample": text})
    return rows


def _template_apply_extra_mapping_selection(
    *,
    field: str,
    label: str,
    target: str,
    mapping_key: str,
    selected_key: str = "",
) -> None:
    field = str(field or "").strip()
    label = _collapse_spaces(str(label or field or "").strip())
    target = "header" if str(target or "").lower().startswith("header") else "line"
    if not field:
        return
    mappings = _template_read_json_session(mapping_key, {"header": {}, "line": {}})
    if not isinstance(mappings, dict):
        mappings = {"header": {}, "line": {}}
    bucket = mappings.setdefault(target, {})
    if not isinstance(bucket, dict):
        bucket = {}
        mappings[target] = bucket
    aliases = _normalise_template_alias_values(bucket.get(field) or [])
    for alias in [label, field]:
        if alias and _template_alias_key(alias) not in {_template_alias_key(x) for x in aliases}:
            aliases.append(alias)
    bucket[field] = aliases
    _template_write_json_session(mapping_key, mappings)
    if selected_key:
        selected = _template_read_json_session(selected_key, [])
        if not isinstance(selected, list):
            selected = []
        if field not in selected:
            selected.append(field)
        _template_write_json_session(selected_key, selected)
    st.session_state[f"{mapping_key}_version"] = int(st.session_state.get(f"{mapping_key}_version", 0) or 0) + 1


def _template_patch_saved_extra_mappings(template_id: str, mapping_key: str) -> int:
    template_id = str(template_id or "").strip()
    if not template_id:
        return 0
    mappings = _template_read_json_session(mapping_key, {"header": {}, "line": {}})
    if not isinstance(mappings, dict):
        return 0
    patch: Dict[str, Any] = {}
    total = 0
    for target, defaults, cfg_key in (
        ("header", _template_default_header_aliases(), "header_aliases"),
        ("line", _template_default_line_aliases(), "line_aliases"),
    ):
        learned = mappings.get(target)
        if not isinstance(learned, dict):
            continue
        cleaned = {
            str(field).strip(): _normalise_template_alias_values(aliases)
            for field, aliases in learned.items()
            if str(field).strip() and _normalise_template_alias_values(aliases)
        }
        if not cleaned:
            continue
        total += len(cleaned)
        patch[cfg_key] = _template_merge_alias_config(patch.get(cfg_key), cleaned, defaults)
    if patch:
        row = _db_fetchone("SELECT config_json FROM supplier_templates WHERE template_id=?", (template_id,))
        cfg: Dict[str, Any] = {}
        if row:
            try:
                cfg = json.loads(row.get("config_json") or "{}")
            except Exception:
                cfg = {}
        if not isinstance(cfg, dict):
            cfg = {}
        for cfg_key, defaults in (("header_aliases", _template_default_header_aliases()), ("line_aliases", _template_default_line_aliases())):
            if cfg_key in patch:
                cfg[cfg_key] = _template_merge_alias_config(cfg.get(cfg_key), patch[cfg_key], defaults)
        _db_patch_supplier_template_config(template_id, cfg)
    return total


def _normalise_template_alias_values(values: Any) -> List[str]:
    raw_values: List[str] = []
    if isinstance(values, str):
        raw_values = [v.strip() for v in re.split(r"[\r\n,]+", values) if str(v).strip()]
    elif isinstance(values, list):
        raw_values = [str(v).strip() for v in values if str(v).strip()]
    out: List[str] = []
    seen_keys: set[str] = set()
    for value in raw_values:
        key = value.casefold()
        if key in seen_keys:
            continue
        seen_keys.add(key)
        out.append(value)
    return out


def _normalise_template_alias_config(raw: Any, defaults: Optional[Dict[str, List[str]]] = None) -> Dict[str, List[str]]:
    out: Dict[str, List[str]] = {}
    for field, aliases in (defaults or {}).items():
        out[str(field)] = _normalise_template_alias_values(aliases)
    if not isinstance(raw, dict):
        return out
    for field, aliases in raw.items():
        field_name = str(field or "").strip()
        if not field_name:
            continue
        out[field_name] = _filter_template_aliases(field_name, _normalise_template_alias_values(aliases))
    return out


def _template_alias_looks_bad(field: str, alias: str) -> bool:
    alias = _collapse_spaces(str(alias or "").strip())
    if not alias:
        return True
    alias_u = alias.upper()
    alias_l = alias.lower()
    if len(alias) < 3:
        return True
    if len(alias) > 60:
        return True
    if alias_u in {"INVOICE", "DOCUMENT", "TAX", "NO", "NUMBER", "INV"}:
        return True
    if alias_u == "DATE" and field != "invoiceDate":
        return True
    if re.search(r"\b(IBAN|BIC|SWIFT|TERMS?|CONDITIONS?|ARTICLE|OBLIGATIONS?|WEBSITE|ALGORITHMS?|CIRCUMSTANCES|SUBSTITUTE|ORDERING CUSTOMER)\b", alias_u):
        return True
    if re.search(r"\b[A-Z]{2}\d{2}\s?\d{3,}\b", alias_u):
        return True
    if re.fullmatch(r"[A-Z]{2,6}[-/ ]?\d{3,}", alias_u):
        return True
    if field == "supplierName" and any(x in alias_l for x in ("www", "http", "condition", "article", "customer sends", "receipt of that payment")):
        return True
    if field == "supplierName" and re.search(r"\b(INVOICE|CUSTOMER|BILL\s*TO|SOLD\s*TO|ACCOUNT|PO|ORDER|DATE|NUMBER)\b", alias_u):
        return True
    if field == "customerName" and re.search(r"\b(SUPPLIER|VENDOR|SOLD\s*BY|FROM|INVOICE\s*(NO|NUMBER)?|DATE|TOTAL)\b", alias_u):
        return True
    if field in ("invoiceNumber", "invoiceDate") and re.search(r"\b(IBAN|BANK|ACCOUNT|CVO-|INV\d)", alias_u):
        return True
    if field == "totalGross" and re.search(r"\b(SUB\s*TOTAL|SUBTOTAL|WITHOUT\s+TAX|EX\s*VAT|EXCLUDING)\b", alias_u):
        return True
    if field == "totalNet" and re.search(r"\b(TOTAL\s+INC|INCL\.?\s*VAT|INCLUDING\s+VAT|AMOUNT\s+DUE|BALANCE)\b", alias_u):
        return True
    return False


def _filter_template_aliases(field: str, aliases: List[str]) -> List[str]:
    out: List[str] = []
    seen = set()
    for alias in aliases or []:
        alias = _collapse_spaces(str(alias or "").strip())
        if _template_alias_looks_bad(field, alias):
            continue
        key = _template_alias_key(alias)
        if key and key not in seen:
            out.append(alias)
            seen.add(key)
    return out


def _template_alias_config_to_grid_rows(alias_cfg: Any, defaults: Dict[str, List[str]]) -> List[Dict[str, str]]:
    cfg = _normalise_template_alias_config(alias_cfg, defaults)
    rows: List[Dict[str, str]] = []
    for field in cfg:
        aliases = _normalise_template_alias_values(cfg.get(field) or [])
        rows.append(
            {
                "DocMate Field": str(field),
                "Supplier Labels / Column Headings": ", ".join(aliases),
            }
        )
    return rows


def _template_alias_config_without_defaults(alias_cfg: Any, defaults: Dict[str, List[str]]) -> Dict[str, List[str]]:
    cfg = _normalise_template_alias_config(alias_cfg, {})
    default_cfg = {
        str(field): _normalise_template_alias_values(aliases)
        for field, aliases in (defaults or {}).items()
    }
    out: Dict[str, List[str]] = {}
    for field, aliases in cfg.items():
        default_keys = {_template_alias_key(alias) for alias in (default_cfg.get(field) or [])}
        kept = [
            alias
            for alias in _normalise_template_alias_values(aliases)
            if _template_alias_key(alias) not in default_keys
            and not _template_alias_looks_bad(field, alias)
        ]
        if kept:
            out[field] = kept
    return out


def _template_alias_grid_rows_to_config(rows: Any, defaults: Dict[str, List[str]]) -> Dict[str, List[str]]:
    cfg = _normalise_template_alias_config({}, defaults)
    records: List[Dict[str, Any]] = []
    try:
        if pd is not None and hasattr(rows, "to_dict"):
            records = rows.to_dict(orient="records")
        elif isinstance(rows, list):
            records = [r for r in rows if isinstance(r, dict)]
    except Exception:
        records = []
    for row in records:
        field = str(row.get("DocMate Field") or row.get("field") or "").strip()
        labels = row.get("Supplier Labels / Column Headings")
        if not field:
            continue
        cfg[field] = _normalise_template_alias_values(labels)
    return cfg


def _template_alias_grid_rows_to_visible_config(rows: Any) -> Dict[str, List[str]]:
    cfg: Dict[str, List[str]] = {}
    records: List[Dict[str, Any]] = []
    try:
        if pd is not None and hasattr(rows, "to_dict"):
            records = rows.to_dict(orient="records")
        elif isinstance(rows, list):
            records = [r for r in rows if isinstance(r, dict)]
    except Exception:
        records = []
    for row in records:
        field = str(row.get("DocMate Field") or row.get("field") or "").strip()
        labels = _normalise_template_alias_values(row.get("Supplier Labels / Column Headings"))
        labels = [label for label in labels if not _template_alias_looks_bad(field, label)]
        if field and labels:
            cfg[field] = labels
    return cfg


def _render_template_alias_mapping_editor(
    *,
    label: str,
    alias_cfg: Any,
    defaults: Dict[str, List[str]],
    key: str,
    height: int = 260,
    include_default_aliases: bool = True,
    field_options: Optional[List[str]] = None,
) -> Dict[str, List[str]]:
    display_defaults = defaults if include_default_aliases else {}
    rows = _template_alias_config_to_grid_rows(alias_cfg, display_defaults)
    st.markdown(f"**{label}**")
    if pd is None:
        text_key = f"{key}_fallback"
        text_value = st.text_area(
            f"{label} JSON",
            value=json.dumps(_normalise_template_alias_config(alias_cfg, display_defaults), indent=2),
            key=text_key,
            height=height,
        )
        try:
            parsed = json.loads(text_value or "{}")
            return _normalise_template_alias_config(parsed, display_defaults)
        except Exception:
            st.warning(f"{label} JSON is invalid; defaults are being used.")
            return _normalise_template_alias_config(alias_cfg, display_defaults)

    df = pd.DataFrame(rows)
    options = list(field_options or defaults.keys())
    options.extend(sorted([x for x in _normalise_template_alias_config(alias_cfg, display_defaults).keys() if x not in options]))
    edited = st.data_editor(
        df,
        key=key,
        hide_index=True,
        width="stretch",
        height=height,
        num_rows="dynamic",
        column_config={
            "DocMate Field": st.column_config.SelectboxColumn(
                "DocMate Field",
                options=list(dict.fromkeys([x for x in options if x])),
                required=True,
            ),
            "Supplier Labels / Column Headings": st.column_config.TextColumn(
                "Supplier Labels / Column Headings",
                help="Comma-separated labels from the supplier invoice, for example Document No, Tax Point Date, Total Ex VAT.",
            ),
        },
    )
    if include_default_aliases:
        return _template_alias_grid_rows_to_config(edited, display_defaults)
    return _template_alias_grid_rows_to_visible_config(edited)


def _template_append_alias_to_session_config(session_key: str, field: str, value: str, defaults: Dict[str, List[str]]) -> None:
    field = str(field or "").strip()
    value = _collapse_spaces(str(value or "").strip())
    if not field or not value:
        return
    try:
        cfg_raw = json.loads(st.session_state.get(session_key) or "{}")
    except Exception:
        cfg_raw = {}
    cfg = _normalise_template_alias_config(cfg_raw, defaults)
    aliases = cfg.get(field, [])
    seen = {_template_alias_key(x) for x in aliases}
    key = _template_alias_key(value)
    if key and key not in seen:
        aliases.append(value)
    cfg[field] = aliases
    st.session_state[session_key] = json.dumps(cfg, indent=2)
    st.session_state[f"{session_key}_version"] = int(st.session_state.get(f"{session_key}_version", 0) or 0) + 1


def _template_append_field_region_to_session_config(
    session_key: str,
    *,
    field: str,
    target_type: str,
    text: str,
    page: int,
    bbox: Any,
    source: str,
) -> None:
    text = _collapse_spaces(str(text or "").strip())
    if not session_key or not field or not text:
        return
    try:
        cfg = json.loads(st.session_state.get(session_key) or "{}")
    except Exception:
        cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}
    key = "header" if str(target_type).lower().startswith("header") else "line"
    bucket = cfg.setdefault(key, {})
    if not isinstance(bucket, dict):
        bucket = {}
        cfg[key] = bucket
    entries = bucket.setdefault(field, [])
    if not isinstance(entries, list):
        entries = []
    entry = {
        "text": text,
        "page": int(page or 1),
        "bbox": bbox,
        "source": source,
    }
    dedupe_key = json.dumps(entry, sort_keys=True, default=str)
    existing = {json.dumps(x, sort_keys=True, default=str) for x in entries if isinstance(x, dict)}
    if dedupe_key not in existing:
        entries.append(entry)
    bucket[field] = entries
    st.session_state[session_key] = json.dumps(cfg, indent=2, ensure_ascii=False)
    st.session_state[f"{session_key}_version"] = int(st.session_state.get(f"{session_key}_version", 0) or 0) + 1


def _ocr_bbox_to_image_rect(line: Dict[str, Any], image_width: int, image_height: int) -> Optional[Tuple[int, int, int, int]]:
    bbox = (line or {}).get("bbox")
    if not bbox:
        return None
    try:
        if isinstance(bbox, dict):
            left = _safe_float(bbox.get("left"))
            top = _safe_float(bbox.get("top"))
            right = _safe_float(bbox.get("right"))
            bottom = _safe_float(bbox.get("bottom"))
            if bool(bbox.get("normalized")) or (0 <= left <= 1 and 0 <= right <= 1 and 0 <= top <= 1 and 0 <= bottom <= 1):
                x0, y0, x1, y1 = left * image_width, top * image_height, right * image_width, bottom * image_height
            else:
                page_w = _safe_float(bbox.get("page_width") or (line or {}).get("page_width"), default=0.0)
                page_h = _safe_float(bbox.get("page_height") or (line or {}).get("page_height"), default=0.0)
                sx = image_width / page_w if page_w > 0 else 1.0
                sy = image_height / page_h if page_h > 0 else 1.0
                x0, y0, x1, y1 = left * sx, top * sy, right * sx, bottom * sy
        elif isinstance(bbox, (list, tuple)) and len(bbox) >= 4:
            x0, y0, x1, y1 = [float(x) for x in bbox[:4]]
            page_w = _safe_float((line or {}).get("page_width"), default=0.0)
            page_h = _safe_float((line or {}).get("page_height"), default=0.0)
            if page_w > 0 and page_h > 0:
                x0, x1 = x0 * image_width / page_w, x1 * image_width / page_w
                y0, y1 = y0 * image_height / page_h, y1 * image_height / page_h
            elif 0 <= x0 <= 1 and 0 <= x1 <= 1 and 0 <= y0 <= 1 and 0 <= y1 <= 1:
                x0, x1 = x0 * image_width, x1 * image_width
                y0, y1 = y0 * image_height, y1 * image_height
        else:
            return None
        x0, x1 = sorted([int(round(x0)), int(round(x1))])
        y0, y1 = sorted([int(round(y0)), int(round(y1))])
        x0 = max(0, min(image_width - 1, x0))
        x1 = max(0, min(image_width - 1, x1))
        y0 = max(0, min(image_height - 1, y0))
        y1 = max(0, min(image_height - 1, y1))
        if x1 <= x0 or y1 <= y0:
            return None
        return x0, y0, x1, y1
    except Exception:
        return None


def _ocr_bbox_center(line: Dict[str, Any]) -> Tuple[float, float]:
    bbox = (line or {}).get("bbox") or {}
    if isinstance(bbox, dict):
        left = _safe_float(bbox.get("left"), default=0.0)
        top = _safe_float(bbox.get("top"), default=0.0)
        right = _safe_float(bbox.get("right"), default=left)
        bottom = _safe_float(bbox.get("bottom"), default=top)
        return ((left + right) / 2.0, (top + bottom) / 2.0)
    if isinstance(bbox, (list, tuple)) and len(bbox) >= 4:
        try:
            x0, y0, x1, y1 = [float(x) for x in bbox[:4]]
            return ((x0 + x1) / 2.0, (y0 + y1) / 2.0)
        except Exception:
            return (0.0, 0.0)
    return (0.0, 0.0)


def _reconstruct_invoice_rows_from_ocr_lines(page_lines: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    rows: List[List[Dict[str, Any]]] = []
    ordered = sorted(
        [ln for ln in page_lines or [] if str((ln or {}).get("text") or "").strip()],
        key=lambda ln: (_ocr_bbox_center(ln)[1], _ocr_bbox_center(ln)[0]),
    )
    for line in ordered:
        _x, y = _ocr_bbox_center(line)
        placed = False
        for row in rows:
            avg_y = sum(_ocr_bbox_center(x)[1] for x in row) / max(len(row), 1)
            if abs(y - avg_y) <= 0.009:
                row.append(line)
                placed = True
                break
        if not placed:
            rows.append([line])

    rebuilt: List[Dict[str, Any]] = []
    for row_no, row in enumerate(rows, start=1):
        row_sorted = sorted(row, key=lambda ln: _ocr_bbox_center(ln)[0])
        texts = [_collapse_spaces(str(ln.get("text") or "")) for ln in row_sorted]
        texts = [txt for txt in texts if txt]
        if not texts:
            continue
        bboxes = [ln.get("bbox") for ln in row_sorted if ln.get("bbox")]
        rebuilt.append(
            {
                "row": row_no,
                "text": " | ".join(texts),
                "plain_text": " ".join(texts),
                "line_count": len(row_sorted),
                "page": int((row_sorted[0] or {}).get("page") or 1),
                "bbox": bboxes[0] if len(bboxes) == 1 else bboxes,
            }
        )
    return rebuilt


def _render_invoice_ocr_box_mapper(
    *,
    res: Dict[str, Any],
    header_alias_key: str,
    line_alias_key: str,
    field_regions_key: str = "",
    widget_key: str,
) -> None:
    if Image is None:
        st.info("Image rendering is not available on this environment.")
        return
    file_bytes = res.get("file_bytes") or b""
    mime = str(res.get("mime") or "")
    ocr_lines = list(res.get("ocr_lines_snapshot") or [])
    if not ocr_lines:
        ck = str(res.get("ocr_cache_key") or "").strip()
        if ck:
            ocr_lines = list(_OCR_LINES_CACHE.get(ck) or [])
    ocr_lines = _normalize_purchase_table_ocr_lines(ocr_lines)
    if not file_bytes or not ocr_lines:
        st.info("No OCR bounding boxes are available for this invoice. Process with OCR or Document AI first.")
        return

    pages = sorted({int((ln or {}).get("page") or 1) for ln in ocr_lines})
    page_no = st.selectbox("Invoice page", options=pages, index=0, key=f"{widget_key}_page")
    image = None
    try:
        if mime == "application/pdf":
            rendered = _pdf_render_selected_pages(bytes(file_bytes), [int(page_no)], dpi=160)
            image = rendered.get(int(page_no))
        else:
            image = Image.open(io.BytesIO(bytes(file_bytes))).convert("RGB")
    except Exception:
        image = None
    if image is None:
        st.info("Could not render this invoice page for mapping.")
        return

    page_lines = [
        ln for ln in ocr_lines
        if int((ln or {}).get("page") or 1) == int(page_no)
        and str((ln or {}).get("text") or "").strip()
    ]
    page_lines = sorted(
        page_lines,
        key=lambda ln: (
            _safe_float(((ln.get("bbox") or {}) if isinstance(ln.get("bbox"), dict) else {}).get("top"), default=0.0),
            _safe_float(((ln.get("bbox") or {}) if isinstance(ln.get("bbox"), dict) else {}).get("left"), default=0.0),
        ),
    )
    try:
        from PIL import ImageDraw, ImageFont  # type: ignore
        preview = image.copy().convert("RGB")
        draw = ImageDraw.Draw(preview)
        try:
            font = ImageFont.load_default()
        except Exception:
            font = None
        numbered: List[Tuple[int, Dict[str, Any], Tuple[int, int, int, int]]] = []
        for idx, ln in enumerate(page_lines[:250], start=1):
            rect = _ocr_bbox_to_image_rect(ln, preview.width, preview.height)
            if not rect:
                continue
            numbered.append((idx, ln, rect))
            x0, y0, x1, y1 = rect
            draw.rectangle([x0, y0, x1, y1], outline=(230, 81, 0), width=2)
            label = str(idx)
            lx, ly = x0, max(0, y0 - 12)
            draw.rectangle([lx, ly, lx + 22, ly + 12], fill=(230, 81, 0))
            draw.text((lx + 2, ly), label, fill=(255, 255, 255), font=font)
    except Exception:
        preview = image
        numbered = []

    st.image(preview, caption="Current invoice OCR boxes", use_container_width=True)
    if not numbered:
        st.info("No drawable OCR boxes found on this page.")
        return

    reconstructed_rows = _reconstruct_invoice_rows_from_ocr_lines(page_lines)
    if reconstructed_rows:
        with st.expander("Reconstructed invoice rows from OCR", expanded=True):
            if pd is not None:
                st.dataframe(
                    pd.DataFrame(
                        [
                            {
                                "row": row.get("row"),
                                "text": row.get("text"),
                                "line_count": row.get("line_count"),
                            }
                            for row in reconstructed_rows[:120]
                        ]
                    ),
                    hide_index=True,
                    width="stretch",
                )
            else:
                st.code("\n".join(f"{row.get('row')}: {row.get('text')}" for row in reconstructed_rows[:120]))

    target_type = st.radio("Map selected text to", ["Header field", "Line column"], horizontal=True, key=f"{widget_key}_target_type")
    if target_type == "Header field":
        target_field = st.selectbox("Target DocMate field", options=list(_template_default_header_aliases().keys()), key=f"{widget_key}_target_header")
        target_session_key = header_alias_key
        defaults = _template_default_header_aliases()
    else:
        target_field = st.selectbox("Target DocMate field", options=list(_template_default_line_aliases().keys()), key=f"{widget_key}_target_line")
        target_session_key = line_alias_key
        defaults = _template_default_line_aliases()

    source_mode = st.radio("Select from", ["OCR boxes", "Reconstructed rows"], horizontal=True, key=f"{widget_key}_source_mode")
    filter_text = st.text_input("Filter OCR text", value="", key=f"{widget_key}_filter")
    st.caption("Select invoice text, choose the DocMate target field, then add it to the template mapping.")

    if source_mode == "Reconstructed rows" and reconstructed_rows:
        row_options: Dict[str, Dict[str, Any]] = {}
        for row in reconstructed_rows[:160]:
            text = _collapse_spaces(str(row.get("text") or ""))
            if filter_text and filter_text.lower() not in text.lower():
                continue
            row_options[f"Row {row.get('row')}: {text[:180]}"] = row
        selected_row_labels = st.multiselect(
            "OCR reconstructed rows",
            options=list(row_options.keys()),
            key=f"{widget_key}_selected_rows",
        )
        selected_rows = [row_options[label] for label in selected_row_labels if label in row_options]
        selected_text = " ".join(_collapse_spaces(str(row.get("plain_text") or row.get("text") or "")) for row in selected_rows).strip()
        selected_bbox = [row.get("bbox") for row in selected_rows if row.get("bbox")]
        if selected_text:
            st.text_area("Selected text", value=selected_text, height=90, key=f"{widget_key}_selected_row_text")
        if st.button("Add selected row text to field mapping", disabled=not selected_text, key=f"{widget_key}_add_rows"):
            _template_append_alias_to_session_config(target_session_key, target_field, selected_text, defaults)
            if field_regions_key:
                _template_append_field_region_to_session_config(
                    field_regions_key,
                    field=target_field,
                    target_type=target_type,
                    text=selected_text,
                    page=int(page_no),
                    bbox=selected_bbox,
                    source="reconstructed_row",
                )
            st.success(f"Mapped selected row text to {target_field}.")
            st.rerun()
        return

    if source_mode == "Reconstructed rows" and not reconstructed_rows:
        st.info("No reconstructed rows were available. Use OCR boxes instead.")

    shown = 0
    box_options: Dict[str, Tuple[int, Dict[str, Any]]] = {}
    for idx, ln, _rect in numbered:
        text = _collapse_spaces(str(ln.get("text") or ""))
        if filter_text and filter_text.lower() not in text.lower():
            continue
        shown += 1
        box_options[f"{idx}: {text[:180]}"] = (idx, ln)
        if shown >= 80:
            break
    selected_box_labels = st.multiselect(
        "OCR boxes",
        options=list(box_options.keys()),
        key=f"{widget_key}_selected_boxes",
    )
    selected_boxes = [box_options[label] for label in selected_box_labels if label in box_options]
    selected_text = " ".join(_collapse_spaces(str(ln.get("text") or "")) for _idx, ln in selected_boxes).strip()
    selected_bbox = [ln.get("bbox") for _idx, ln in selected_boxes if ln.get("bbox")]
    if selected_text:
        st.text_area("Selected text", value=selected_text, height=90, key=f"{widget_key}_selected_box_text")
    if shown >= 80:
        st.caption("Showing first 80 matching OCR boxes. Use the filter to narrow the list.")
    if st.button("Add selected OCR box text to field mapping", disabled=not selected_text, key=f"{widget_key}_add_boxes"):
        _template_append_alias_to_session_config(target_session_key, target_field, selected_text, defaults)
        if field_regions_key:
            _template_append_field_region_to_session_config(
                field_regions_key,
                field=target_field,
                target_type=target_type,
                text=selected_text,
                page=int(page_no),
                bbox=selected_bbox,
                source="ocr_box",
            )
        st.success(f"Mapped selected OCR text to {target_field}.")
        st.rerun()


def _template_alias_key(s: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(s or "").strip().lower())


def _template_money_from_text(text: str) -> float:
    nums = re.findall(r"-?\d[\d,]*\.\d{2}", str(text or ""))
    if not nums:
        return 0.0
    try:
        return float(nums[-1].replace(",", ""))
    except Exception:
        return 0.0


def _template_clean_header_alias_value(field: str, text: str) -> Any:
    raw = _collapse_spaces(str(text or "").replace("|", " ").strip(" \t:-"))
    if not raw:
        return ""
    if field in {"supplierName", "customerName"}:
        cleaned = raw.strip(" ,;")
        if len(cleaned) > 120:
            cleaned = cleaned[:120].strip()
        return cleaned
    if field == "invoiceNumber":
        blocked = {
            "INVOICE", "INV", "NUMBER", "NO", "DOCUMENT", "DOC", "REFERENCE",
            "ORDER", "CUSTOMER", "SUPPLIER", "DATE",
        }
        tokens = re.findall(r"\b[A-Z0-9][A-Z0-9\-\/]{2,}\b", raw, flags=re.I)
        for token in tokens:
            cleaned = token.strip(" .,:;#-")
            if cleaned.upper() in blocked:
                continue
            if re.search(r"\d", cleaned):
                return cleaned
        return ""
    if field == "invoiceDate":
        val = _normalise_invoice_date_str(raw)
        if val:
            return val
        m = re.search(r"\b\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4}\b|\b\d{4}-\d{2}-\d{2}\b", raw)
        return _normalise_invoice_date_str(m.group(0)) if m else ""
    if field in {"totalNet", "totalVat", "totalGross"}:
        return _template_money_from_text(raw)
    return raw


def _template_header_value_is_placeholder(field: str, value: Any) -> bool:
    text = _collapse_spaces(str(value or "").replace("|", " ").strip())
    if not text:
        return True
    up = text.upper()
    compact = re.sub(r"[^A-Z0-9]+", "", up)
    if field == "supplierName":
        if compact in {"NA", "NAN", "NONE", "NULL", "SUPPLIER", "SUPPLIERNAME", "INVOICE", "ORDERINVOICE"}:
            return True
        if re.fullmatch(r"(ORDER\s+)?INVOICE(?:\s*\(.*\))?", up):
            return True
        if len(text) > 80:
            return True
        if re.search(r"\b(ORDERING\s+CUSTOMER|TRANSPORT|TRANSIT|CONVELIO\s+ISSUES|ISSUES\s+OR\s+ARRANGES|MOST\s+SUITABLE|TERMS?\s+AND\s+CONDITIONS|ARTICLE)\b", up):
            return True
    if field == "invoiceNumber":
        if compact in {"NA", "NAN", "NONE", "NULL", "INVOICE", "INVOICENUMBER", "INVOICENO", "DOCUMENTNO", "REFERENCE"}:
            return True
        if not re.search(r"\d", text):
            return True
    if field == "customerName":
        if compact in {"NA", "NAN", "NONE", "NULL", "CUSTOMER", "CUSTOMERNAME", "REFERENCENUMBER"}:
            return True
        if "@" in text:
            return True
        if re.search(r"\b(REFERENCE\s+NUMBER|ESTIMATED\s+TRANSIT|INVOICE|SUPPLIER|ORDER\s+INVOICE|TRANSPORT|ORDERING\s+CUSTOMER)\b", up):
            return True
    return False


def _template_header_value_is_missing(field: str, value: Any) -> bool:
    return _template_header_value_is_placeholder(field, value)


def _template_header_value_should_replace_from_alias(field: str, current: Any, candidate: Any) -> bool:
    if _template_header_value_is_missing(field, current):
        return True
    cand = str(candidate or "").strip()
    cur = str(current or "").strip()
    if not cand or cand.casefold() == cur.casefold():
        return False
    if field == "invoiceNumber":
        cur_compact = re.sub(r"[^A-Z0-9]+", "", cur.upper())
        cand_compact = re.sub(r"[^A-Z0-9]+", "", cand.upper())
        if not cur_compact or not cand_compact:
            return False
        if cand_compact.endswith(cur_compact) or cur_compact.endswith(cand_compact):
            return len(cand_compact) > len(cur_compact)
        cur_letters = len(re.findall(r"[A-Z]", cur_compact))
        cand_letters = len(re.findall(r"[A-Z]", cand_compact))
        if len(cand_compact) >= len(cur_compact) and cand_letters > cur_letters:
            return True
    if field == "invoiceDate":
        cand_date = _normalise_invoice_date_str(cand)
        cur_date = _normalise_invoice_date_str(cur)
        if cand_date and (not cur_date or len(cur) > 24):
            return True
    return False


def _template_supplier_value_should_use_match(current: Any, template_supplier: str) -> bool:
    current_text = _normalise_supplier_name(str(current or "").strip())
    template_text = _normalise_supplier_name(str(template_supplier or "").strip())
    if not template_text:
        return False
    if not current_text or _template_header_value_is_placeholder("supplierName", current_text):
        return True
    if current_text.casefold() == template_text.casefold():
        return False
    current_up = current_text.upper()
    generic_markers = (
        "SALES INVOICE",
        "SALES - INVOICE",
        "INVOICE",
        "TAX INVOICE",
        "ORDER INVOICE",
        "PURCHASE INVOICE",
        "CREDIT NOTE",
    )
    if current_up in generic_markers:
        return True
    if re.fullmatch(r"(SALES|TAX|PURCHASE|ORDER)\s*[- ]?\s*INVOICE", current_up):
        return True
    return False


def _template_header_total_is_suspicious(field: str, header: Dict[str, Any]) -> bool:
    if field not in {"totalNet", "totalVat", "totalGross"} or not isinstance(header, dict):
        return False
    net = round(_safe_float(header.get("totalNet")), 2)
    vat = round(_safe_float(header.get("totalVat")), 2)
    gross = round(_safe_float(header.get("totalGross")), 2)
    if field == "totalVat" and vat > 0 and net > 0 and gross > 0:
        return abs(vat - net) <= 0.01 and abs(gross - net) <= 0.01
    return False


def _extract_labelled_value_from_lines(text: str, labels: List[str]) -> str:
    lines = [_collapse_spaces(str(ln or "").replace("|", " ")).strip() for ln in str(text or "").splitlines()]
    lines = [ln for ln in lines if ln]
    label_patterns = [re.compile(rf"^\s*{re.escape(label)}\s*[:#-]?\s*(.*)$", flags=re.I) for label in labels]
    known_label_re = re.compile(
        r"^(invoice\s+number|invoice\s+date|due\s+date|convelio\s+order|customer\s+reference|estimated\s+transit|invoice\s+to|shipment\s+route|supplier|customer)\b",
        flags=re.I,
    )
    for idx, line in enumerate(lines):
        for pat in label_patterns:
            m = pat.match(line)
            if not m:
                continue
            same_line = _collapse_spaces(m.group(1) or "").strip(" :#-\t")
            if same_line and not known_label_re.match(same_line):
                return same_line
            for nxt in lines[idx + 1: idx + 5]:
                candidate = _collapse_spaces(nxt).strip(" :#-\t")
                if not candidate:
                    continue
                if known_label_re.match(candidate):
                    break
                return candidate
    return ""


def _repair_dynamics_convelio_header(header: Dict[str, Any], text: str, file_name: str = "") -> Dict[str, Any]:
    """Final header repair for Convelio Dynamics invoices.

    The generic OCR/template flow can confuse the page title, address postcode,
    and terms text with real header values. This parser only trusts explicit
    Convelio label/value pairs from the invoice header area.
    """
    if not isinstance(header, dict):
        header = {}
    hay = "\n".join([str(text or ""), str(file_name or "")])
    if not re.search(r"\bCONVELIO\b|hello@convelio\.com|www\.convelio\.com", hay, flags=re.I):
        return header

    header["supplierName"] = "Convelio"

    inv_no_raw = _extract_labelled_value_from_lines(hay, ["Invoice number", "Invoice no", "Inv no"])
    inv_no = _template_clean_header_alias_value("invoiceNumber", inv_no_raw)
    if not inv_no:
        m = re.search(r"\bINV[A-Z0-9]*[-/]\d[A-Z0-9\-\/]*\b", hay, flags=re.I)
        inv_no = m.group(0).strip() if m else ""
    if inv_no and not _template_header_value_is_placeholder("invoiceNumber", inv_no):
        header["invoiceNumber"] = inv_no

    inv_date_raw = _extract_labelled_value_from_lines(hay, ["Invoice date"])
    inv_date = _normalise_invoice_date_str(inv_date_raw) or _template_clean_header_alias_value("invoiceDate", inv_date_raw)
    if inv_date:
        header["invoiceDate"] = inv_date

    due_date_raw = _extract_labelled_value_from_lines(hay, ["Due date"])
    due_date = _normalise_invoice_date_str(due_date_raw)
    if due_date:
        header["paymentDueDate"] = due_date

    convelio_order = _extract_labelled_value_from_lines(hay, ["Convelio Order n°", "Convelio Order no", "Convelio Order"])
    m_order = re.search(r"\bCVO[-_/]?[A-Z0-9]+\b", convelio_order or "", flags=re.I)
    if not m_order:
        m_order = re.search(r"\bCVO[-_/]?[A-Z0-9]+\b", hay, flags=re.I)
    if convelio_order or m_order:
        header["orderNumber"] = (m_order.group(0).strip() if m_order else convelio_order.strip())

    customer_ref = _extract_labelled_value_from_lines(hay, ["Customer Reference number", "Customer reference", "Reference number"])
    if customer_ref:
        m_ref = re.search(r"\bTIC[_\-A-Z0-9]+\b", customer_ref, flags=re.I)
        header["customerPONumber"] = (m_ref.group(0).strip() if m_ref else customer_ref.strip())

    current_customer = str(header.get("customerName") or header.get("customer_name") or "").strip()
    if _template_header_value_is_placeholder("customerName", current_customer):
        header["customerName"] = ""
        header["customer_name"] = ""

    return header


def _extract_header_value_from_aliases(text: str, field: str, aliases: List[str]) -> Any:
    lines = [str(ln or "").strip() for ln in str(text or "").splitlines()]
    lines = [ln for ln in lines if ln]
    for idx, line in enumerate(lines):
        for alias in aliases or []:
            alias_txt = str(alias or "").strip()
            if not alias_txt:
                continue
            alias_re = re.escape(alias_txt)
            if field == "invoiceDate" and re.search(r"\b(DUE|PAYMENT|DELIVERY|SHIP|DESPATCH|DISPATCH)\s+DATE\b", line, flags=re.I):
                continue
            if field in {"totalNet", "totalVat", "totalGross"}:
                if re.search(rf"\b{alias_re}\b", line, flags=re.I):
                    # Do not treat table column headers as labels for the next row.
                    # In layouts such as "Summary of Charges / Amount VAT Total",
                    # the next row is often a charge row, not the invoice total.
                    if re.search(r"\bAmount\b", line, flags=re.I) and re.search(r"\bVAT\b", line, flags=re.I) and re.search(r"\bTotal\b", line, flags=re.I):
                        continue
                    money = _template_money_from_text(line)
                    if money > 0:
                        return money
                    exact_label = bool(re.fullmatch(rf"\s*{alias_re}\s*[:#-]?\s*", line, flags=re.I))
                    if exact_label and idx + 1 < len(lines):
                        money = _template_money_from_text(lines[idx + 1])
                        if money > 0:
                            return money
                continue
            m = re.search(rf"(?:^|\b){alias_re}\b\s*[:#-]?\s*(.*)$", line, flags=re.I)
            if m:
                candidate = m.group(1).strip()
                if not candidate.strip(" .,:;#-") and idx + 1 < len(lines):
                    candidate = lines[idx + 1]
                value = _template_clean_header_alias_value(field, candidate)
                if value not in ("", 0.0):
                    return value
            if field == "invoiceDate" and re.search(rf"\b{alias_re}\b", line, flags=re.I):
                value = _template_clean_header_alias_value(field, line)
                if value:
                    return value
    if field == "invoiceNumber":
        for pattern in (
            r"\bINV[A-Z0-9]*[-/]\d[A-Z0-9\-\/]*\b",
            r"\bINVOICE\s*(?:NO\.?|NUMBER|#)?\s*[:#-]?\s*([A-Z0-9][A-Z0-9\-\/]*\d[A-Z0-9\-\/]*)\b",
            r"\b(?:DOC|DOCUMENT|REFERENCE|REF)\s*(?:NO\.?|NUMBER|#)?\s*[:#-]?\s*([A-Z0-9][A-Z0-9\-\/]*\d[A-Z0-9\-\/]*)\b",
        ):
            m = re.search(pattern, str(text or ""), flags=re.I)
            if not m:
                continue
            candidate = m.group(1) if m.lastindex else m.group(0)
            value = _template_clean_header_alias_value(field, candidate)
            if value and not _template_header_value_is_placeholder(field, value):
                return value
    return "" if field not in {"totalNet", "totalVat", "totalGross"} else 0.0


def _apply_template_header_aliases(header: Dict[str, Any], text: str, alias_cfg: Any, *, force: bool = False) -> Dict[str, Any]:
    if not isinstance(header, dict):
        return header
    aliases = _normalise_template_alias_config(alias_cfg, _template_default_header_aliases())
    hint_text = str(text or "")
    if not hint_text.strip():
        return header
    for field, field_aliases in aliases.items():
        if field in {"totalNet", "totalVat", "totalGross"}:
            if (not force) and _safe_float(header.get(field)) > 0 and not _template_header_total_is_suspicious(field, header):
                continue
        else:
            if (not force) and field not in {"invoiceNumber", "invoiceDate"} and not _template_header_value_is_missing(field, header.get(field)):
                continue
        value = _extract_header_value_from_aliases(hint_text, field, field_aliases)
        if field in {"totalNet", "totalVat", "totalGross"}:
            if _safe_float(value) > 0:
                header[field] = round(float(_safe_float(value)), 2)
        elif value and not _template_header_value_is_placeholder(field, value) and (force or _template_header_value_should_replace_from_alias(field, header.get(field), value)):
            header[field] = value
            if field == "customerName" and not str(header.get("customer_name") or "").strip():
                header["customer_name"] = str(value)
    header = _repair_summary_charges_header_totals(header, hint_text)
    return _repair_implausible_header_total_set(header)


def _template_invoice_number_pattern_from_value(value: Any) -> Dict[str, Any]:
    """Learn a supplier-specific invoice-number shape without saving one fixed invoice number."""
    text = _collapse_spaces(str(value or "").strip()).upper()
    compact = re.sub(r"[^A-Z0-9]+", "", text)
    m = re.fullmatch(r"([A-Z]{2,12})(\d{2,10})", compact)
    if not m:
        return {}
    prefix, digits = m.group(1), m.group(2)
    return {
        "prefix": prefix,
        "digit_width": len(digits),
    }


def _template_apply_invoice_number_pattern(header: Dict[str, Any], cfg: Dict[str, Any]) -> Dict[str, Any]:
    """Repair local OCR invoice-number mistakes using a reviewed supplier pattern.

    Example learned from reviewed value LRK0003:
    local OCR value "INvoice-3" -> "LRK0003".
    """
    if not isinstance(header, dict) or not isinstance(cfg, dict):
        return header
    rules = cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}
    pattern = rules.get("invoice_number_pattern") if isinstance(rules.get("invoice_number_pattern"), dict) else {}
    if not pattern:
        for example_key in ("header_trained_examples", "trained_examples"):
            examples = cfg.get(example_key)
            if not isinstance(examples, list):
                continue
            for example in reversed(examples):
                if not isinstance(example, dict):
                    continue
                pattern = _template_invoice_number_pattern_from_value(example.get("invoiceNumber"))
                if pattern:
                    break
            if pattern:
                break
    prefix = re.sub(r"[^A-Z0-9]+", "", str(pattern.get("prefix") or "").upper())
    width = int(pattern.get("digit_width") or 0)
    if not prefix or width <= 0:
        return header
    current = str(header.get("invoiceNumber") or "").strip()
    if not current:
        return header
    compact = re.sub(r"[^A-Z0-9]+", "", current.upper())
    if compact.startswith(prefix) and re.search(r"\d", compact):
        header["invoiceNumber"] = compact
        return header
    if not re.search(r"\b(INV|INVOICE|VOICE)\b", current, flags=re.I) and not re.search(r"^[A-Z]{0,4}[-/# ]?\d{1,6}$", current.strip(), flags=re.I):
        return header
    digit_groups = re.findall(r"\d+", current)
    if not digit_groups:
        return header
    suffix = digit_groups[-1]
    if len(suffix) > width:
        return header
    try:
        num = int(suffix)
    except Exception:
        return header
    if num < 0:
        return header
    header["invoiceNumber"] = f"{prefix}{num:0{width}d}"
    return header


def _template_trusted_header_values_from_header(header: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(header, dict):
        return {}
    out: Dict[str, Any] = {}
    supplier = _normalise_supplier_name(str(header.get("supplierName") or "").strip())
    customer = _collapse_spaces(str(header.get("customerName") or header.get("customer_name") or "").strip())
    currency = _collapse_spaces(str(header.get("currency") or "").strip()).upper()
    if supplier and not _template_header_value_is_placeholder("supplierName", supplier):
        out["supplierName"] = supplier
    if customer and not _template_header_value_is_placeholder("customerName", customer):
        out["customerName"] = customer
    if currency:
        out["currency"] = currency
    return out


def _template_reviewed_header_values_from_header(header: Dict[str, Any]) -> Dict[str, Any]:
    """Reviewed/Gemini header values used as a teacher target for local retests.

    These values are not fixed defaults for future invoices; they protect the
    current reviewed extraction while local DocTR/template rules are being tested.
    """
    if not isinstance(header, dict):
        return {}
    out = _template_trusted_header_values_from_header(header)
    inv_no = str(header.get("invoiceNumber") or "").strip()
    inv_date = _normalise_invoice_date_str(header.get("invoiceDate") or "") or str(header.get("invoiceDate") or "").strip()
    if inv_no and not _template_header_value_is_placeholder("invoiceNumber", inv_no):
        out["invoiceNumber"] = inv_no
    if inv_date:
        out["invoiceDate"] = inv_date
    net = round(_safe_float(header.get("totalNet")), 2)
    vat = round(_safe_float(header.get("totalVat")), 2)
    gross = round(_safe_float(header.get("totalGross")), 2)
    if net > 0 and gross > 0 and abs((net + vat) - gross) <= 0.05:
        out["totalNet"] = net
        out["totalVat"] = vat
        out["totalGross"] = gross
    return out


def _apply_reviewed_header_teacher_values(header: Dict[str, Any], teacher_header: Dict[str, Any]) -> Dict[str, Any]:
    """Keep reviewed/Gemini header values authoritative during template retests."""
    if not isinstance(header, dict) or not isinstance(teacher_header, dict):
        return header
    teacher = _template_reviewed_header_values_from_header(teacher_header)
    if not teacher:
        return header
    for field in ("supplierName", "customerName", "currency", "invoiceNumber", "invoiceDate"):
        value = teacher.get(field)
        if value not in (None, ""):
            header[field] = value
            if field == "customerName":
                header["customer_name"] = str(value)
    if all(k in teacher for k in ("totalNet", "totalVat", "totalGross")):
        header["totalNet"] = teacher["totalNet"]
        header["totalVat"] = teacher["totalVat"]
        header["totalGross"] = teacher["totalGross"]
    return _repair_implausible_header_total_set(header)


def _apply_template_trusted_header_values(header: Dict[str, Any], template_hit: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    if not isinstance(header, dict) or not isinstance(template_hit, dict):
        return header
    cfg = template_hit.get("config") or {}
    if not isinstance(cfg, dict):
        return header
    trusted = cfg.get("trusted_header_values")
    if not isinstance(trusted, dict):
        trusted = {}
    template_supplier = _template_supplier_name_from_hit(template_hit)
    if template_supplier:
        trusted = {**trusted, "supplierName": template_supplier}
    for field in ("supplierName", "customerName", "currency"):
        value = str(trusted.get(field) or "").strip()
        if not value:
            continue
        if field == "supplierName":
            value = _normalise_supplier_name(value)
            if _template_header_value_is_placeholder("supplierName", value):
                continue
            current = str(header.get("supplierName") or "").strip()
            current_key = _template_supplier_key(current)
            value_key = _template_supplier_key(value)
            should_replace = (
                not current
                or _template_header_value_is_placeholder("supplierName", current)
                or (value_key and value_key not in current_key and current_key not in value_key)
            )
            if should_replace:
                header["supplierName"] = value
        elif field == "customerName":
            if _template_header_value_is_placeholder("customerName", value):
                continue
            current = str(header.get("customerName") or header.get("customer_name") or "").strip()
            cur_up = current.upper()
            suspicious = (
                not current
                or _template_header_value_is_placeholder("customerName", current)
                or len(current) < 4
                or re.search(r"\b(WHICH\s+THEY\s+RELATE|TERMS?|CONDITIONS?|INVOICE|SUPPLIER|CUSTOMER|ADDRESS)\b", cur_up)
            )
            if suspicious or value.upper() not in cur_up:
                header["customerName"] = value
                header["customer_name"] = value
        elif field == "currency":
            if value and not str(header.get("currency") or "").strip():
                header["currency"] = value.upper()
    return header


def _apply_template_line_aliases(items: List[Dict[str, Any]], alias_cfg: Any) -> List[Dict[str, Any]]:
    if not items:
        return items
    aliases = _normalise_template_alias_config(alias_cfg, _template_default_line_aliases())
    alias_to_field: Dict[str, str] = {}
    for field, field_aliases in aliases.items():
        alias_to_field[_template_alias_key(field)] = field
        for alias in field_aliases or []:
            alias_to_field[_template_alias_key(alias)] = field
    out: List[Dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            continue
        item2 = dict(item)
        for key, value in list(item.items()):
            field = alias_to_field.get(_template_alias_key(key))
            if not field:
                continue
            if field not in item2 or _is_empty(item2.get(field)):
                item2[field] = value
        out.append(item2)
    return out






def _template_signature_supplier(payload: Dict[str, Any]) -> str:
    """Stable signature for supplier template payload to detect no-op saves."""
    try:
        supplier_name = (payload.get("supplier_name") or "").strip()
        parser_type = (payload.get("parser_type") or "GENERIC").strip().upper()
        vat = (payload.get("vat_number") or "").strip()
        awrs = (payload.get("awrs_number") or "").strip()
        display_id = (payload.get("display_id") or "").strip()
        requires_cloud = 1 if int(payload.get("requires_cloud") or 0) == 1 else 0
        cfg = payload.get("config") or {}
        if not isinstance(cfg, dict):
            cfg = {}
        # normalise keywords
        kws = payload.get("match_keywords") or []
        if not isinstance(kws, list):
            kws = []
        kws_n = [str(x).strip().upper() for x in kws if str(x).strip()]
        kws_n = sorted(list(dict.fromkeys(kws_n)))
        norm = {
            "supplier_name": supplier_name.strip().upper(),
            "parser_type": parser_type,
            "vat_number": vat,
            "awrs_number": awrs,
            "display_id": display_id,
            "requires_cloud": requires_cloud,
            "match_keywords": kws_n,
            "config": cfg,
        }
        blob = json.dumps(norm, sort_keys=True, ensure_ascii=False)
        return _sha256_bytes(blob.encode("utf-8"))
    except Exception:
        return ""

def _diff_template_fields(old_sig_payload: Dict[str, Any], new_sig_payload: Dict[str, Any]) -> List[str]:
    diffs = []
    try:
        for k in ("vat_number", "awrs_number", "requires_cloud", "match_keywords", "config"):
            if old_sig_payload.get(k) != new_sig_payload.get(k):
                diffs.append(k)
    except Exception:
        pass
    return diffs

def _db_upsert_supplier_template_checked(payload: Dict[str, Any]) -> Tuple[str, bool, List[str]]:
    """Upsert supplier template but skip if identical. Returns (template_id, saved, notes)."""
    supplier_name = (payload.get("supplier_name") or "").strip()
    parser_type = (payload.get("parser_type") or "GENERIC").strip().upper()
    if (
        not GENERIC_TEMPLATE_TRAINING_ENABLED
        and parser_type not in DEDICATED_SUPPLIER_PARSER_TYPES
    ):
        raise RuntimeError(
            "Generic supplier template training has been retired; "
            "only dedicated Booker, Dhamecha, Parfetts and DWG parser configurations are allowed."
        )

    existing = _db_fetchone(
        "SELECT * FROM supplier_templates WHERE UPPER(TRIM(supplier_name))=? AND UPPER(TRIM(parser_type))=?",
        (supplier_name.upper(), parser_type),
    )
    existing_d = dict(existing) if existing else None

    # Build comparable normalised payloads
    def _norm_from_row(row: Dict[str, Any]) -> Dict[str, Any]:
        cfg = {}
        try:
            cfg = json.loads(row.get("config_json") or "{}")
        except Exception:
            cfg = {}
        kws = []
        try:
            kws = json.loads(row.get("match_keywords_json") or "[]")
        except Exception:
            kws = []
        return {
            "vat_number": (row.get("vat_number") or "").strip(),
            "awrs_number": (row.get("awrs_number") or "").strip(),
            "requires_cloud": 1 if int(row.get("requires_cloud") or 0) == 1 else 0,
            "match_keywords": sorted(list(dict.fromkeys([str(x).strip().upper() for x in (kws or []) if str(x).strip()]))),
            "config": cfg if isinstance(cfg, dict) else {},
        }

    new_norm = {
        "vat_number": (payload.get("vat_number") or "").strip(),
        "awrs_number": (payload.get("awrs_number") or "").strip(),
        "requires_cloud": 1 if int(payload.get("requires_cloud") or 0) == 1 else 0,
        "match_keywords": sorted(list(dict.fromkeys([str(x).strip().upper() for x in (payload.get("match_keywords") or []) if str(x).strip()]))),
        "config": (payload.get("config") or {}) if isinstance(payload.get("config") or {}, dict) else {},
    }

    if existing_d:
        old_norm = _norm_from_row(existing_d)
        if json.dumps(old_norm, sort_keys=True, ensure_ascii=False) == json.dumps(new_norm, sort_keys=True, ensure_ascii=False):
            tpl_id = (existing_d.get("template_id") or "").strip()
            disp = (existing_d.get("display_id") or "").strip()
            notes = [f"Template unchanged  not saved (existing: {disp or tpl_id})."]
            return (tpl_id, False, notes)

    tpl_id = _db_upsert_supplier_template(payload)
    return (tpl_id, True, [])

def _db_upsert_supplier_template(payload: Dict[str, Any]) -> str:
    """Create/update supplier template and return template_id.

    Rules:
    - One template per (supplier_name, parser_type) unless template_id explicitly provided.
    - If display_id is empty and a matching template exists, keep existing display_id (prevents duplicates).
    """
    supplier_name = (payload.get("supplier_name") or "").strip()
    parser_type = (payload.get("parser_type") or "GENERIC").strip().upper()
    now = _uk_now_iso()

    template_id = (payload.get("template_id") or "").strip()
    existing: Optional[Dict[str, Any]] = None

    if template_id:
        row = _db_fetchone("SELECT * FROM supplier_templates WHERE template_id=?", (template_id,))
        existing = dict(row) if row else None
    else:
        row = _db_fetchone(
            "SELECT * FROM supplier_templates WHERE UPPER(TRIM(supplier_name))=? AND UPPER(TRIM(parser_type))=?",
            (supplier_name.upper(), parser_type),
        )
        existing = dict(row) if row else None
        if existing:
            template_id = (existing.get("template_id") or "").strip()
        # Dedupe: keep one template per supplier+parser_type
        if template_id:
            _db_exec(
                "DELETE FROM supplier_templates WHERE UPPER(TRIM(supplier_name))=? AND UPPER(TRIM(parser_type))=? AND template_id<>?",
                (supplier_name.upper(), parser_type, template_id),
            )

    if not template_id:
        template_id = _sha256_bytes(f"SUP|{supplier_name}|{time.time()}".encode("utf-8"))[:24]

    created = (payload.get("created_at") or (existing.get("created_at") if existing else "") or now)

    vat = (payload.get("vat_number") or (existing.get("vat_number") if existing else "") or "").strip()
    awrs = (payload.get("awrs_number") or (existing.get("awrs_number") if existing else "") or "").strip()
    requires_cloud = 1 if int(payload.get("requires_cloud") or (existing.get("requires_cloud") if existing else 0) or 0) == 1 else 0

    cfg = payload.get("config")
    if cfg is None:
        cfg = {}
        if existing and existing.get("config_json"):
            try:
                cfg = json.loads(existing.get("config_json") or "{}")
            except Exception:
                cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}

    keywords = payload.get("match_keywords")
    if not isinstance(keywords, list):
        if existing and existing.get("match_keywords_json"):
            try:
                keywords = json.loads(existing.get("match_keywords_json") or "[]")
            except Exception:
                keywords = None
        if not isinstance(keywords, list):
            keywords = _template_keywords(supplier_name, [vat, awrs])

    display_id = (payload.get("display_id") or "").strip()
    if not display_id and existing:
        display_id = (existing.get("display_id") or "").strip()

    if not display_id:
        yyyymmdd = re.sub(r"[^0-9]", "", now[:10])
        if len(yyyymmdd) != 8:
            yyyymmdd = datetime.utcnow().strftime("%Y%m%d")
        prefix = _supplier_acronym(supplier_name)
        display_id = _next_display_id(prefix, yyyymmdd, "supplier_templates")

    row2 = _db_fetchone("SELECT template_id FROM supplier_templates WHERE display_id=?", (display_id,))
    row2_tid = str((dict(row2).get("template_id") if row2 else "") or "").strip()
    if row2_tid and row2_tid != template_id:
        raise ValueError(f"Display ID already exists: {display_id}")

    _db_exec(
        """INSERT OR REPLACE INTO supplier_templates(
            template_id, display_id, supplier_name, vat_number, awrs_number,
            match_keywords_json, parser_type, requires_cloud, config_json,
            created_at, updated_at
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
        (
            template_id,
            display_id,
            supplier_name,
            vat,
            awrs,
            json.dumps(keywords),
            parser_type,
            requires_cloud,
            json.dumps(cfg),
            created,
            now,
        ),
    )
    return template_id




def _db_patch_supplier_template_config(template_id: str, patch: Dict[str, Any]) -> None:
    """Patch (merge) config_json for a supplier template and bump updated_at.

    Used to 'learn' default values such as Booker default_customer_name from Admin header edits.
    """
    if not template_id:
        return
    try:
        row = _db_fetchone("SELECT config_json FROM supplier_templates WHERE template_id=?", (template_id,))
        cfg = {}
        if row:
            try:
                cfg = json.loads((dict(row).get("config_json") or "{}"))
            except Exception:
                cfg = {}
        if not isinstance(cfg, dict):
            cfg = {}
        for k, v in (patch or {}).items():
            cfg[k] = v
        _db_exec(
            "UPDATE supplier_templates SET config_json=?, updated_at=? WHERE template_id=?",
            (json.dumps(cfg, ensure_ascii=False), _uk_now_iso(), template_id),
        )
    except Exception:
        return


def _template_merge_alias_config(base: Any, learned: Dict[str, List[str]], defaults: Dict[str, List[str]]) -> Dict[str, List[str]]:
    merged = _normalise_template_alias_config(base, defaults)
    for field, aliases in (learned or {}).items():
        field_name = str(field or "").strip()
        if not field_name:
            continue
        existing = merged.get(field_name, [])
        seen = {_template_alias_key(x) for x in existing}
        for alias in _normalise_template_alias_values(aliases):
            if _template_alias_looks_bad(field_name, alias):
                continue
            key = _template_alias_key(alias)
            if key and key not in seen:
                existing.append(alias)
                seen.add(key)
        merged[field_name] = _filter_template_aliases(field_name, existing)
    return merged


def _template_money_alias_pattern(value: Any) -> str:
    amount = abs(_safe_float(value))
    if amount <= 0:
        return ""
    whole, frac = f"{amount:.2f}".split(".")
    grouped = f"{int(whole):,}.{frac}"
    plain = f"{int(whole)}.{frac}"
    return rf"(?:{re.escape(grouped)}|{re.escape(plain)})"


def _template_learn_header_aliases_from_text(header: Dict[str, Any], raw_text: str) -> Dict[str, List[str]]:
    """Infer label aliases by finding corrected values in OCR/text lines.

    Example: if the corrected invoice number is INV123 and the line says
    "Document No: INV123", learn "Document No" as an alias for invoiceNumber.
    """
    learned: Dict[str, List[str]] = {}
    if not isinstance(header, dict) or not str(raw_text or "").strip():
        return learned

    lines = [_collapse_spaces(str(ln or "").replace("|", " ")).strip() for ln in str(raw_text or "").splitlines()]
    lines = [ln for ln in lines if ln]
    label_re = re.compile(r"^[A-Za-z][A-Za-z0-9 /#&().%-]{1,48}$")
    default_header_aliases = _template_default_header_aliases()

    def add_alias(field: str, alias: str) -> None:
        alias = _collapse_spaces(str(alias or "").strip(" :-#|.,\t"))
        if not alias or len(alias) < 2 or len(alias) > 50:
            return
        if _template_alias_looks_bad(field, alias):
            return
        if not label_re.match(alias):
            return
        if _template_alias_key(alias) == _template_alias_key(str(header.get(field) or "")):
            return
        learned.setdefault(field, [])
        if _template_alias_key(alias) not in {_template_alias_key(x) for x in learned[field]}:
            learned[field].append(alias)

    def _matching_label_in_context(field: str, context: str) -> str:
        context_u = _collapse_spaces(str(context or "")).upper()
        if not context_u:
            return ""
        aliases = list(default_header_aliases.get(field) or [])
        aliases.sort(key=lambda value: (len(str(value or "").split()), len(str(value or ""))), reverse=True)
        for alias in aliases:
            alias_text = _collapse_spaces(str(alias or ""))
            if not alias_text:
                continue
            pattern = r"(?<![A-Z0-9])" + re.escape(alias_text.upper()).replace(r"\ ", r"\s+") + r"(?![A-Z0-9])"
            if re.search(pattern, context_u, flags=re.I):
                return alias_text
        return ""

    def _line_contains_candidate(field: str, line: str, candidate: str) -> int:
        idx = str(line or "").lower().find(str(candidate or "").lower())
        if idx >= 0:
            return idx
        if field == "supplierName" and _template_supplier_keys_likely_same(line, candidate):
            return 0
        return -1

    for field in ("invoiceNumber", "invoiceDate", "customerName", "supplierName", "customerNo", "customerPONumber", "accountNumber"):
        value = str(header.get(field) or "").strip()
        if not value or len(value) < 3:
            continue
        candidates = [value]
        if field == "invoiceDate":
            norm = _normalise_invoice_date_str(value)
            if norm:
                candidates.extend([norm, norm.replace("-", "/"), norm.replace("-", " ")])
        for line_no, line in enumerate(lines[:250]):
            for candidate in candidates:
                idx = _line_contains_candidate(field, line, str(candidate))
                if idx < 0:
                    continue
                if idx > 0:
                    alias = line[:idx]
                    alias = re.sub(r"\b(invoice|tax|document)?\s*$", lambda m: m.group(0), alias, flags=re.I)
                    add_alias(field, alias)
                for prev_line in reversed(lines[max(0, line_no - 3):line_no]):
                    label = _matching_label_in_context(field, prev_line)
                    if label:
                        add_alias(field, label)
                        break

    for field in ("totalNet", "totalVat", "totalGross"):
        money_pat = _template_money_alias_pattern(header.get(field))
        if not money_pat:
            continue
        for line in lines[-180:]:
            m = re.search(money_pat, line)
            if not m or m.start() <= 0:
                continue
            alias = re.sub(r"[£$€]|\bGBP\b|\bEUR\b|\bUSD\b", " ", line[:m.start()], flags=re.I)
            alias_u = alias.upper()
            if field == "totalGross" and re.search(r"\b(SUB\s*TOTAL|SUBTOTAL|WITHOUT\s+TAX|EX\s*VAT|EXCLUDING)\b", alias_u):
                continue
            if field == "totalNet" and re.search(r"\b(TOTAL\s+INC|INCL\.?\s*VAT|INCLUDING\s+VAT|AMOUNT\s+DUE|BALANCE)\b", alias_u):
                continue
            if field == "totalVat" and not re.search(r"\b(VAT|TAX)\b", alias_u):
                continue
            add_alias(field, alias)

    # Second pass for label-above-value total layouts:
    # Net | VAT | Gross
    # 2500.00 | 0.00 | 2500.00
    for field in ("totalNet", "totalVat", "totalGross"):
        money_pat = _template_money_alias_pattern(header.get(field))
        if not money_pat:
            continue
        for line_no, line in enumerate(lines[-180:], start=max(0, len(lines) - 180)):
            if not re.search(money_pat, line):
                continue
            for prev_line in reversed(lines[max(0, line_no - 3):line_no]):
                label = _matching_label_in_context(field, prev_line)
                if label:
                    add_alias(field, label)
                    break

    return learned


def _template_header_aliases_for_review(
    header: Dict[str, Any],
    raw_text: str,
    existing_template: Optional[Dict[str, Any]] = None,
) -> Tuple[Dict[str, List[str]], Dict[str, List[str]]]:
    """Build editable header-label mapping for template training review."""
    existing_cfg: Dict[str, Any] = {}
    if isinstance(existing_template, dict):
        if isinstance(existing_template.get("config"), dict):
            existing_cfg = copy.deepcopy(existing_template.get("config") or {})
        elif existing_template.get("config_json"):
            try:
                parsed = json.loads(existing_template.get("config_json") or "{}")
                existing_cfg = parsed if isinstance(parsed, dict) else {}
            except Exception:
                existing_cfg = {}
    learned = _template_learn_header_aliases_from_text(header or {}, raw_text or "")
    merged = _template_merge_alias_config(
        (existing_cfg.get("header_aliases") if isinstance(existing_cfg, dict) else None),
        learned,
        _template_default_header_aliases(),
    )
    return merged, learned


def _template_learn_header_aliases_from_ocr_layout(
    header: Dict[str, Any],
    ocr_lines: Any,
) -> Dict[str, List[str]]:
    """Infer header aliases from spatial OCR labels above/near values."""
    learned: Dict[str, List[str]] = {}
    if not isinstance(header, dict) or not ocr_lines:
        return learned
    try:
        lines = _normalize_purchase_table_ocr_lines(list(ocr_lines or []))
    except Exception:
        lines = list(ocr_lines or [])
    positioned: List[Dict[str, Any]] = []
    for ln in lines or []:
        if not isinstance(ln, dict):
            continue
        text = _collapse_spaces(str(ln.get("text") or ""))
        bbox = _ix_bbox_to_tuple(ln.get("bbox"))
        if not text or not bbox:
            continue
        x0, y0, x1, y1 = bbox
        positioned.append(
            {
                "text": text,
                "page": int(ln.get("page") or 1),
                "x0": float(x0),
                "y0": float(y0),
                "x1": float(x1),
                "y1": float(y1),
                "cx": (float(x0) + float(x1)) / 2.0,
                "cy": (float(y0) + float(y1)) / 2.0,
            }
        )
    if not positioned:
        return learned

    label_map = {
        "supplierName": ["SUPPLIER", "SUPPLIER NAME", "VENDOR", "FROM"],
        "customerName": ["INVOICE TO", "BILL TO", "CUSTOMER", "CUSTOMER NAME"],
        "customerNo": ["CUSTOMER NO", "CUSTOMER NUMBER", "ACCOUNT NO", "ACCOUNT NUMBER", "ACCOUNT REF"],
        "customerPONumber": ["CUSTOMER PO", "CUSTOMER PO NUMBER", "PO NUMBER", "PURCHASE ORDER", "YOUR ORDER NO"],
        "accountNumber": ["ACCOUNT NO", "ACCOUNT NUMBER", "ACCOUNT REF"],
        "invoiceNumber": ["INVOICE NO", "INVOICE NUMBER", "INVOICE #", "INV NO", "DOCUMENT NO"],
        "invoiceDate": ["INVOICE DATE", "DATE", "DOCUMENT DATE", "TAX POINT DATE"],
        "totalNet": ["NET", "NET AMOUNT", "TOTAL EX VAT", "NET TOTAL"],
        "totalVat": ["VAT", "VAT AMOUNT", "TOTAL VAT", "TAX"],
        "totalGross": ["GROSS", "INVOICE TOTAL", "TOTAL", "AMOUNT DUE", "TOTAL DUE"],
    }

    def _value_candidates(field: str, value: str) -> List[str]:
        out = [str(value or "").strip()]
        if field == "invoiceDate":
            norm = _normalise_invoice_date_str(value)
            if norm:
                out.extend([norm, norm.replace("-", "/"), norm.replace("-", " ")])
        return [x for x in dict.fromkeys(out) if x]

    def _value_matches(field: str, text: str, value: str) -> bool:
        text_norm = _collapse_spaces(str(text or ""))
        for candidate in _value_candidates(field, value):
            if candidate.lower() in text_norm.lower():
                return True
            if field == "invoiceDate":
                cand_norm = _normalise_invoice_date_str(candidate)
                text_date = _normalise_invoice_date_str(text_norm)
                if cand_norm and text_date and cand_norm == text_date:
                    return True
            if field == "supplierName" and _template_supplier_keys_likely_same(text_norm, candidate):
                return True
        if field in ("totalNet", "totalVat", "totalGross"):
            money_pat = _template_money_alias_pattern(value)
            return bool(money_pat and re.search(money_pat, text_norm))
        return False

    def _label_matches(label_text: str, wanted: str) -> bool:
        label_u = re.sub(r"[^A-Z0-9#]+", " ", str(label_text or "").upper()).strip()
        wanted_u = re.sub(r"[^A-Z0-9#]+", " ", str(wanted or "").upper()).strip()
        if not label_u or not wanted_u:
            return False
        return bool(re.search(r"(?<![A-Z0-9#])" + re.escape(wanted_u).replace(r"\ ", r"\s+") + r"(?![A-Z0-9#])", label_u))

    for field, labels in label_map.items():
        value = str((header or {}).get(field) or "").strip()
        if not value:
            continue
        value_lines = [ln for ln in positioned if _value_matches(field, str(ln.get("text") or ""), value)]
        if not value_lines:
            continue
        for value_ln in value_lines[:3]:
            candidates: List[Tuple[float, str]] = []
            for label_ln in positioned:
                if int(label_ln.get("page") or 1) != int(value_ln.get("page") or 1):
                    continue
                if float(label_ln.get("y1") or 0) > float(value_ln.get("y0") or 0) + 4:
                    continue
                vertical_gap = float(value_ln.get("y0") or 0) - float(label_ln.get("y1") or 0)
                if vertical_gap < -2 or vertical_gap > 140:
                    continue
                x_overlap = max(
                    0.0,
                    min(float(label_ln.get("x1") or 0), float(value_ln.get("x1") or 0))
                    - max(float(label_ln.get("x0") or 0), float(value_ln.get("x0") or 0)),
                )
                label_w = max(1.0, float(label_ln.get("x1") or 0) - float(label_ln.get("x0") or 0))
                same_column = bool(x_overlap / label_w >= 0.25 or abs(float(label_ln.get("cx") or 0) - float(value_ln.get("cx") or 0)) <= max(80.0, label_w))
                if not same_column:
                    continue
                for label in labels:
                    if _label_matches(str(label_ln.get("text") or ""), label):
                        candidates.append((vertical_gap + abs(float(label_ln.get("cx") or 0) - float(value_ln.get("cx") or 0)) * 0.02, label))
                        break
            if candidates:
                candidates.sort(key=lambda item: item[0])
                best_label = candidates[0][1]
                if not _template_alias_looks_bad(field, best_label):
                    learned.setdefault(field, [])
                    if _template_alias_key(best_label) not in {_template_alias_key(x) for x in learned[field]}:
                        learned[field].append(best_label)
                break
    return learned


def _template_line_schema_from_items(items: List[Dict[str, Any]]) -> Dict[str, Any]:
    items = _template_training_items(items)
    fields = [
        "code", "barcode", "description", "qty", "casePack", "unitSize", "unitPrice",
        "lineNet", "vatCode", "vatRate", "vatAmount", "lineGross", "stdRrp",
    ]
    counts: Dict[str, int] = {field: 0 for field in fields}
    total = 0
    for item in items or []:
        if not isinstance(item, dict):
            continue
        total += 1
        for field in fields:
            if not _is_empty(item.get(field)):
                counts[field] += 1
    return {
        "line_count": total,
        "populated_fields": {field: count for field, count in counts.items() if count > 0},
    }


def _template_training_items(items: Any) -> List[Dict[str, Any]]:
    rows = _ensure_line_numbers(items)
    out: List[Dict[str, Any]] = []
    for it in rows or []:
        if not isinstance(it, dict):
            continue
        has_identity = bool(str(it.get("code") or "").strip() or str(it.get("description") or "").strip())
        has_value = any(abs(_safe_float(it.get(k))) > 0.0001 for k in ("qty", "unitPrice", "lineNet", "vatRate", "vatAmount", "lineGross"))
        if has_identity or has_value:
            out.append(dict(it))
    return _ensure_line_numbers(out)


def _template_agent_number_spans(text: str) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    number_re = re.compile(
        r"(?<![A-Z0-9])-?\d(?:[\d\s\u00a0.,]*\d)?\s*(?:%|€|£|\$|EUR|GBP|USD)?(?![A-Z0-9])",
        flags=re.I,
    )
    for m in number_re.finditer(str(text or "")):
        raw = m.group(0)
        raw_clean = raw.strip()
        if not re.search(r"\d", raw_clean):
            continue
        if re.search(r"%\s*$", raw_clean):
            val = _parse_locale_money_amount(re.sub(r"%\s*$", "", raw_clean))
        else:
            val = _parse_locale_money_amount(raw_clean)
        if val == 0.0 and not re.search(r"(^|[^\d])0+(?:[,.]0+)?(?:\s*[%€£$])?$", raw_clean):
            continue
        out.append({
            "raw": raw_clean,
            "value": val,
            "start": m.start(),
            "end": m.end(),
            "is_percent": bool(re.search(r"%\s*$", raw_clean)),
            "is_money": bool(re.search(r"(€|£|\$|\bEUR\b|\bGBP\b|\bUSD\b)", raw_clean, flags=re.I)),
        })
    return out


def _template_agent_value_matches(a: Any, b: Any) -> bool:
    av = _safe_float(a)
    bv = _safe_float(b)
    return abs(av - bv) <= 0.015


def _template_agent_code_regex(codes: List[str]) -> str:
    all_codes = [str(c or "").strip() for c in codes if str(c or "").strip()]
    cleaned = [c for c in all_codes if len(c) >= 3]
    if not cleaned:
        return r"[A-Z0-9][A-Z0-9\-\/]{2,}" if any(len(c) >= 3 for c in all_codes) else ""
    slash_codes = [c for c in cleaned if re.fullmatch(r"\d{4,}/\d+", c)]
    if slash_codes and len(slash_codes) >= max(1, int(len(cleaned) * 0.6)):
        lengths = [len(c.split("/", 1)[0]) for c in slash_codes]
        suffix_lengths = [len(c.split("/", 1)[1]) for c in slash_codes]
        return rf"\d{{{min(lengths)},{max(lengths)}}}/\d{{{min(suffix_lengths)},{max(suffix_lengths)}}}"
    if all(re.fullmatch(r"\d+", c) for c in cleaned):
        lengths = [len(c) for c in cleaned]
        return rf"\d{{{min(lengths)},{max(lengths)}}}"
    if all(re.fullmatch(r"[A-Z0-9]+", c, flags=re.I) for c in cleaned):
        lengths = [len(c) for c in cleaned]
        return rf"[A-Z0-9]{{{min(lengths)},{max(lengths)}}}"
    return r"[A-Z0-9][A-Z0-9\-\/]{2,}"


def _template_agent_marker_regex(line: str) -> str:
    text = _collapse_spaces(str(line or "").strip())
    if not text:
        return ""
    tokens = re.findall(r"[A-Z0-9]{3,}", text.upper())
    useful = [
        tok for tok in tokens
        if tok not in {"THE", "AND", "FOR", "WITH", "THIS", "THAT", "INVOICE", "CUSTOMER", "SUPPLIER"}
    ]
    if not useful:
        return ""
    return r".*".join(re.escape(tok) for tok in useful[:8])


def _template_agent_learn_table_region(lines: List[str], matched_line_indices: List[int]) -> Dict[str, Any]:
    if not lines or not matched_line_indices:
        return {}
    first = max(0, min(matched_line_indices))
    last = min(len(lines) - 1, max(matched_line_indices))
    region: Dict[str, Any] = {
        "line_index_min": max(0, first - 3),
        "line_index_max": min(len(lines) - 1, last + 8),
    }

    header_marker_re = re.compile(
        r"\b(description|details?|service|item|product|qty|quantity|unit|price|rate|net|vat|tax|gross|amount|charge)\b",
        flags=re.I,
    )
    blocked_re = re.compile(r"\b(invoice\s+number|invoice\s+date|customer\s+name|supplier\s+name|bill\s+to|ship\s+to)\b", flags=re.I)
    for idx in range(first - 1, max(-1, first - 18), -1):
        line = lines[idx]
        if blocked_re.search(line):
            continue
        if header_marker_re.search(line):
            marker = _template_agent_marker_regex(line)
            if marker:
                region["start_after_regex"] = marker
                region["start_after_sample"] = line[:160]
                break

    stop_re = re.compile(
        r"\b(sub\s*total|subtotal|total\s+net|total\s+vat|vat\s+total|invoice\s+total|amount\s+due|balance\s+due|grand\s+total|payment|bank)\b",
        flags=re.I,
    )
    for idx in range(last + 1, min(len(lines), last + 30)):
        line = lines[idx]
        if stop_re.search(line):
            marker = _template_agent_marker_regex(line)
            if marker:
                region["stop_before_regex"] = marker
                region["stop_before_sample"] = line[:160]
                break
    return region


def _learn_template_agent_from_corrections(items: List[Dict[str, Any]], raw_text: str) -> Dict[str, Any]:
    """Learn a simple same-layout invoice row parser from corrected line items."""
    items = _template_training_items(items)
    if not items or not str(raw_text or "").strip():
        return {}
    lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in str(raw_text or "").splitlines()]
    lines = [ln for ln in lines if ln]
    indexed_lines = list(enumerate(lines))
    fields = ["qty", "unitPrice", "lineNet", "vatRate", "vatAmount", "lineGross"]
    field_votes: Dict[str, Dict[int, int]] = {field: {} for field in fields}
    codes: List[str] = []
    description_anchors: List[List[str]] = []
    matched_rows = 0
    matched_line_indices: List[int] = []
    min_number_count: Optional[int] = None
    row_window_lines = 1

    for item in items or []:
        if not isinstance(item, dict):
            continue
        code = str(item.get("code") or item.get("supplierCode") or "").strip()
        desc_hint = str(item.get("description") or "").strip()
        desc_words = [w for w in re.findall(r"[A-Z0-9]{3,}", desc_hint.upper())[:6]]
        code_re = None
        if len(code) >= 3:
            code_re = re.compile(rf"(?<![A-Z0-9]){re.escape(code)}(?![A-Z0-9])", flags=re.I)
            candidates = [(idx, ln) for idx, ln in indexed_lines if code_re.search(ln)]
        else:
            candidates = []
            if len(desc_words) >= 1:
                scored = []
                for idx, ln in indexed_lines:
                    up_ln = ln.upper()
                    score = sum(1 for w in desc_words if w in up_ln)
                    if score >= min(2, len(desc_words)):
                        scored.append((score, idx, ln))
                candidates = [(idx, ln) for _score, idx, ln in sorted(scored, key=lambda x: x[0], reverse=True)]
        if not candidates:
            continue
        if desc_words:
            scored = []
            for idx, ln in candidates:
                score = sum(1 for w in desc_words if w in ln.upper())
                scored.append((score, idx, ln))
            candidates = [(idx, ln) for _score, idx, ln in sorted(scored, key=lambda x: x[0], reverse=True)]
        line_idx, line = candidates[0]
        if code_re is not None:
            m_code = code_re.search(line)
            if not m_code:
                continue
            after = line[m_code.end():]
        else:
            after = line
        numbers = _template_agent_number_spans(after)
        used_window = 1
        if not numbers:
            for window in (2, 3, 4):
                window_text = " ".join(lines[line_idx : line_idx + window])
                if code_re is not None:
                    m_window_code = code_re.search(window_text)
                    if not m_window_code:
                        continue
                    after = window_text[m_window_code.end():]
                else:
                    after = window_text
                numbers = _template_agent_number_spans(after)
                if numbers:
                    used_window = window
                    break
        if not numbers:
            continue
        matched_rows += 1
        matched_line_indices.append(int(line_idx))
        row_window_lines = max(row_window_lines, used_window)
        if code:
            codes.append(code)
        elif desc_words:
            description_anchors.append(desc_words[:4])
        matched_numeric_fields = 0
        for field in fields:
            value = item.get(field)
            if _safe_float(value) == 0 and field not in {"qty", "vatRate", "vatAmount"}:
                continue
            for idx, num in enumerate(numbers):
                if _template_agent_value_matches(value, num.get("value")):
                    from_end = len(numbers) - 1 - idx
                    field_votes[field][from_end] = field_votes[field].get(from_end, 0) + 1
                    matched_numeric_fields += 1
                    break
        if matched_numeric_fields > 0:
            min_number_count = matched_numeric_fields if min_number_count is None else min(min_number_count, matched_numeric_fields)

    if matched_rows <= 0:
        return {}
    numeric_fields_from_end: Dict[str, int] = {}
    for field, votes in field_votes.items():
        if not votes:
            continue
        best_from_end, best_count = sorted(votes.items(), key=lambda kv: (kv[1], -kv[0]), reverse=True)[0]
        if best_count >= max(1, min(2, matched_rows)):
            numeric_fields_from_end[field] = int(best_from_end)

    if not numeric_fields_from_end:
        return {}
    learned_region = _template_agent_learn_table_region(lines, matched_line_indices)
    code_coverage = len(codes) / max(1, matched_rows)
    return {
        "enabled": True,
        "version": 1,
        "code_regex": _template_agent_code_regex(codes) if codes else "",
        "description_anchors": description_anchors,
        "allow_missing_code": bool(description_anchors),
        "generic_description_rows": bool(code_coverage < 0.35 and matched_rows >= 2),
        "numeric_fields_from_end": numeric_fields_from_end,
        "min_number_count": int(min_number_count or max(1, len(numeric_fields_from_end))),
        "row_window_lines": int(row_window_lines),
        "table_region": learned_region,
        "trained_rows": int(matched_rows),
        "trained_at": _uk_now_iso(),
    }


def _template_agent_clean_description(after_code: str, numbers: List[Dict[str, Any]]) -> str:
    text = str(after_code or "")
    if numbers:
        text = text[: int(numbers[0].get("start") or 0)]
    text = re.sub(r"\s+", " ", text.replace("|", " ")).strip(" -:;,\t")
    return text[:180].strip()


def _template_crop_description_to_reviewed_anchor(description: Any, cfg: Any) -> str:
    """Remove OCR text merged to the left of a learned description anchor."""
    text = _collapse_spaces(str(description or "")).strip(" -:;,\t")
    if not text or not isinstance(cfg, dict):
        return text
    agent = cfg.get("template_agent") if isinstance(cfg.get("template_agent"), dict) else {}
    anchor_groups = agent.get("description_anchors") if isinstance(agent.get("description_anchors"), list) else []
    upper = text.upper()
    best_start: Optional[int] = None
    for group in anchor_groups:
        if not isinstance(group, list):
            continue
        words = [str(word or "").strip().upper() for word in group if len(str(word or "").strip()) >= 3]
        positions = [upper.find(word) for word in words if upper.find(word) >= 0]
        if words and len(positions) >= min(3, len(words)):
            start = min(positions)
            best_start = start if best_start is None else min(best_start, start)
    if best_start is not None and best_start > 0:
        text = text[best_start:].strip(" -:;,\t")
    return text[:220]


_TABLE_PROFILE_LABELS: Dict[str, List[str]] = {
    "description": ["libelle", "libellé", "description", "designation", "désignation", "details", "item", "product", "service"],
    "qty": ["qte", "qté", "qty", "quantity", "quantite", "quantité"],
    "unitSize": ["unite", "unité", "unit", "uom"],
    "unitPrice": ["pu ht", "prix unitaire", "unit price", "price", "rate"],
    "discount": ["rem", "remise", "discount"],
    "lineNet": ["montant ht", "amount ht", "net amount", "line net", "total ht", "amount"],
    "vatCode": ["vat code", "tax code"],
    "vatRate": ["tva", "vat", "tax"],
}

_TEMPLATE_CHARGE_SECTION_LABEL_RE = re.compile(
    r"\b(surcharge|surcharges|charges?|delivery\s+charges?|service\s+charges?)\b",
    flags=re.I,
)

_TEMPLATE_CHARGE_ROW_LABEL_RE = re.compile(
    r"\b(fuel(?:\s+and\s+energy)?\s+charge|energy\s+charge|carriage\s+charge|"
    r"delivery\s+charge|service\s+charge|surcharge|freight|shipping|handling)\b",
    flags=re.I,
)


def _template_table_normalise_label(value: Any) -> str:
    text = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    return _collapse_spaces(text).lower()


def _template_table_detect_header(lines: List[str]) -> Tuple[int, Dict[str, int], str]:
    best_idx = -1
    best_fields: Dict[str, int] = {}
    best_score = 0
    for idx, line in enumerate(lines or []):
        norm = _template_table_normalise_label(line)
        if not norm:
            continue
        found: Dict[str, int] = {}
        for field, aliases in _TABLE_PROFILE_LABELS.items():
            positions = []
            for alias in aliases:
                pos = norm.find(_template_table_normalise_label(alias))
                if pos >= 0:
                    positions.append(pos)
            if positions:
                found[field] = min(positions)
        if "vatCode" in found and "vatRate" in found and not re.search(
            r"\b(vat\s*%|vat\s+rate|tax\s*%|tax\s+rate|tva\s*%)\b",
            norm,
            flags=re.I,
        ):
            found.pop("vatRate", None)
        score = len(found)
        if "description" in found and ("qty" in found or "lineNet" in found):
            score += 2
        if score > best_score:
            best_score = score
            best_idx = idx
            best_fields = found
    if best_score < 3:
        return -1, {}, ""
    return best_idx, best_fields, lines[best_idx]


def _template_charge_section_rules_from_text_and_items(items: List[Dict[str, Any]], raw_text: str) -> List[Dict[str, Any]]:
    """Learn secondary charge-table sections, e.g. Parcel rows plus Surcharge rows."""
    teacher_items = _template_training_items(items)
    raw_lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in str(raw_text or "").splitlines()]
    lines = [ln for ln in raw_lines if ln]
    if not teacher_items or not lines:
        return []
    charge_teacher = [
        it for it in teacher_items
        if _TEMPLATE_CHARGE_ROW_LABEL_RE.search(str(it.get("description") or ""))
        or str(it.get("rowTag") or "").strip().upper() in {"RECON", "CHARGE", "SURCHARGE"}
        or bool(it.get("_reconOnly"))
    ]
    if not charge_teacher:
        return []
    rules: List[Dict[str, Any]] = []
    for idx, line in enumerate(lines):
        if not _TEMPLATE_CHARGE_SECTION_LABEL_RE.search(line):
            continue
        norm_line = _template_table_normalise_label(line)
        if re.search(r"\b(collection|consignment|reference|parcel|weight)\b", norm_line, flags=re.I):
            continue
        is_section_heading = bool(re.fullmatch(r"(surcharge|surcharges|charges?|delivery charges?|service charges?)", norm_line, flags=re.I))
        is_charge_table_header = bool(
            "surcharge" in norm_line
            and "amount" in norm_line
            and ("description" in norm_line or "code" in norm_line)
        )
        if not (is_section_heading or is_charge_table_header):
            continue
        # Prefer a real section heading, not a row description.
        if _TEMPLATE_CHARGE_ROW_LABEL_RE.search(line) and len(_template_agent_number_spans(line)) >= 1:
            continue
        end_idx = len(lines)
        for j in range(idx + 1, len(lines)):
            nline = _template_table_normalise_label(lines[j])
            if re.search(r"\b(total|subtotal|vat\s+summary|tax\s+summary|invoice\s+total|amount\s+due)\b", nline, flags=re.I):
                end_idx = j
                break
            if j > idx + 1 and re.search(r"^[A-Z][A-Za-z /&-]{2,40}$", lines[j]) and not _TEMPLATE_CHARGE_ROW_LABEL_RE.search(lines[j]):
                end_idx = j
                break
        matched = 0
        for it in charge_teacher:
            desc_words = [w for w in re.findall(r"[A-Z0-9]{3,}", str(it.get("description") or "").upper())[:5]]
            line_net = round(_safe_float(it.get("lineNet")), 2)
            for row_idx in range(idx + 1, end_idx):
                up = lines[row_idx].upper()
                desc_ok = bool(desc_words and sum(1 for w in desc_words if w in up) >= min(2, len(desc_words)))
                nums = _template_agent_number_spans(lines[row_idx])
                amount_ok = bool(line_net > 0 and any(_template_agent_value_matches(line_net, n.get("value")) for n in nums))
                if desc_ok or amount_ok:
                    matched += 1
                    break
        if matched <= 0:
            continue
        rules.append(
            {
                "name": _collapse_spaces(line)[:80] or "Charge section",
                "enabled": True,
                "start_after_sample": line[:220],
                "start_after_regex": _template_agent_marker_regex(line),
                "stop_before_sample": lines[end_idx][:220] if 0 <= end_idx < len(lines) else "",
                "stop_before_regex": _template_agent_marker_regex(lines[end_idx]) if 0 <= end_idx < len(lines) else "",
                "matched_rows": int(matched),
                "row_type": "charge",
                "quantity": 0,
                "line_net_from": "last_number",
                "vat_code_from": "token_before_amount",
                "description_from": "between_code_and_amount",
                "learned_at": _uk_now_iso(),
            }
        )
    return rules[:5]


def _extract_items_with_charge_sections(text: str, cfg: Any) -> List[Dict[str, Any]]:
    """Extract charge rows from configured secondary sections such as 'Surcharge'."""
    if not isinstance(cfg, dict):
        return []
    rules = cfg.get("charge_sections")
    if not isinstance(rules, list):
        profile = cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}
        rules = profile.get("charge_sections") if isinstance(profile.get("charge_sections"), list) else []
    if not rules:
        return []
    raw_lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in str(text or "").splitlines()]
    lines = [ln for ln in raw_lines if ln]
    if not lines:
        return []
    out: List[Dict[str, Any]] = []
    seen: set[Tuple[str, float]] = set()
    for rule in rules:
        if not isinstance(rule, dict) or not bool(rule.get("enabled", True)):
            continue
        row_label_re = _TEMPLATE_CHARGE_ROW_LABEL_RE
        custom_row_pat = str(rule.get("row_label_regex") or "").strip()
        use_custom_row_label = False
        if custom_row_pat:
            try:
                row_label_re = re.compile(custom_row_pat, flags=re.I)
                use_custom_row_label = True
            except Exception:
                row_label_re = _TEMPLATE_CHARGE_ROW_LABEL_RE
        start_idx = 0
        end_idx = len(lines)
        start_pat = str(rule.get("start_after_regex") or "").strip()
        stop_pat = str(rule.get("stop_before_regex") or "").strip()
        if start_pat:
            try:
                start_re = re.compile(start_pat, flags=re.I)
                for idx, line in enumerate(lines):
                    if start_re.search(line):
                        start_idx = idx + 1
                        break
            except Exception:
                start_idx = 0
        if stop_pat:
            try:
                stop_re = re.compile(stop_pat, flags=re.I)
                for idx in range(start_idx, len(lines)):
                    norm_stop = _template_table_normalise_label(lines[idx])
                    is_charge_header = bool(
                        "amount" in norm_stop
                        and ("description" in norm_stop or "code" in norm_stop)
                    )
                    if is_charge_header:
                        continue
                    if stop_re.search(lines[idx]):
                        end_idx = idx
                        break
            except Exception:
                end_idx = len(lines)
        if start_idx >= end_idx:
            continue
        for line in lines[start_idx:end_idx]:
            if not line:
                continue
            norm = _template_table_normalise_label(line)
            if re.search(r"\b(code|description|surcharge\s+rate|vat\s+code|amount|total|subtotal)\b", norm, flags=re.I):
                continue
            if not row_label_re.search(line):
                continue
            nums = _template_agent_number_spans(line)
            value_nums = [n for n in nums if not n.get("is_percent")]
            if not value_nums:
                continue
            amount_span = value_nums[-1]
            amount = round(_safe_float(amount_span.get("value")), 2)
            if amount <= 0:
                continue
            before_amount = _collapse_spaces(line[: int(amount_span.get("start") or 0)])
            vat_code = ""
            m_vat = re.search(r"\b([A-Z])\s*$", before_amount)
            if m_vat:
                vat_code = m_vat.group(1).upper()
                before_amount = _collapse_spaces(before_amount[: m_vat.start()])
            rate = 0.0
            pct = [n for n in nums if n.get("is_percent")]
            if pct:
                if not vat_code:
                    rate = _safe_float(pct[-1].get("value"))
                before_amount = _collapse_spaces(before_amount[: int(pct[-1].get("start") or len(before_amount))])
            desc = before_amount
            m_code = re.match(r"^\s*([A-Z0-9]{1,8})\s+(.+)$", desc)
            code = "CHARGE"
            if m_code:
                code = m_code.group(1).upper()
                desc = _collapse_spaces(m_code.group(2))
            label = row_label_re.search(desc)
            if label and not use_custom_row_label:
                desc = _collapse_spaces(label.group(0)).title()
            if not desc:
                continue
            key = (desc.upper(), amount)
            if key in seen:
                continue
            seen.add(key)
            vat_rate = _normalise_vat_rate(rate)
            try:
                if vat_code and _safe_float(vat_rate) == 0.0:
                    vat_map_cfg = cfg.get("vat_map") if isinstance(cfg.get("vat_map"), dict) else {}
                    if not vat_map_cfg:
                        vat_map_cfg = VAT_MAPPING_DEFAULT
                    if isinstance(vat_map_cfg, dict):
                        for k, v in vat_map_cfg.items():
                            if str(k or "").strip().upper() == vat_code:
                                vat_rate = _normalise_vat_rate(v)
                                break
            except Exception:
                pass
            out.append(
                {
                    "lineNo": None,
                    "code": code,
                    "description": desc,
                    "casePack": 0,
                    "unitSize": "",
                    "qty": 0.0,
                    "totalUnits": 0.0,
                    "unitPrice": float(amount),
                    "lineNet": float(amount),
                    "vatCode": vat_code,
                    "vatRate": vat_rate,
                    "vatAmount": round(float(amount) * _safe_float(vat_rate) / 100.0, 2) if vat_rate else 0.0,
                    "lineGross": round(float(amount) + (round(float(amount) * _safe_float(vat_rate) / 100.0, 2) if vat_rate else 0.0), 2),
                    "stdRrp": 0.0,
                    "por": 0.0,
                    "isVoid": False,
                    "rowTag": "CHARGE",
                    "_reconOnly": True,
                    "rawRow": line,
                }
            )
    return out


def _template_table_profile_from_text_and_items(items: List[Dict[str, Any]], raw_text: str) -> Dict[str, Any]:
    """Learn a lightweight supplier table profile from OCR text plus reviewed rows."""
    teacher_items = _template_training_items(items)
    lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in str(raw_text or "").splitlines()]
    lines = [ln for ln in lines if ln]
    if not teacher_items or not lines:
        return {}
    header_idx, header_fields, header_sample = _template_table_detect_header(lines)
    if header_idx < 0:
        return {}

    ordered_fields = [
        field
        for field, _pos in sorted(header_fields.items(), key=lambda kv: kv[1])
        if field in {"description", "qty", "unitSize", "unitPrice", "discount", "lineNet", "vatCode", "vatRate"}
    ]
    if "description" not in ordered_fields:
        ordered_fields.insert(0, "description")
    if "lineNet" not in ordered_fields:
        ordered_fields.append("lineNet")

    stop_idx = len(lines)
    stop_re = re.compile(
        r"\b(detail\s+de\s+la\s+tva|d[eé]tail\s+de\s+la\s+tva|vat\s+detail|tax\s+detail|"
        r"reglement|r[eè]glement|payment|bank|coordonnees|coordonn[eé]es|total\s+ttc|total\s+ht\s+net)\b",
        flags=re.I,
    )
    for idx in range(header_idx + 1, len(lines)):
        if stop_re.search(_template_table_normalise_label(lines[idx])):
            stop_idx = idx
            break

    matched_rows = 0
    matched_indices: List[int] = []
    for item in teacher_items:
        desc_words = [w for w in re.findall(r"[A-Z0-9]{3,}", str(item.get("description") or "").upper())[:5]]
        line_net = _safe_float(item.get("lineNet"))
        if not desc_words and line_net <= 0:
            continue
        for idx in range(header_idx + 1, stop_idx):
            up = lines[idx].upper()
            desc_ok = bool(desc_words and sum(1 for w in desc_words if w in up) >= min(2, len(desc_words)))
            nums = _template_agent_number_spans(lines[idx])
            amount_ok = bool(line_net > 0 and any(_template_agent_value_matches(line_net, n.get("value")) for n in nums))
            if desc_ok or amount_ok:
                matched_rows += 1
                matched_indices.append(idx)
                break

    if matched_rows <= 0:
        return {}

    footer_labels = []
    if re.search(r"\b(frais\s+de\s+port|livraison|transport|delivery|freight|shipping|carriage)\b", str(raw_text or ""), flags=re.I):
        footer_labels.extend(["Frais de port HT", "Livraison", "Transport", "Delivery", "Freight", "Shipping"])
    charge_sections = _template_charge_section_rules_from_text_and_items(teacher_items, raw_text)

    return {
        "enabled": True,
        "version": 1,
        "header_sample": header_sample[:220],
        "header_fields": ordered_fields,
        "start_after_sample": header_sample[:220],
        "start_after_regex": _template_agent_marker_regex(header_sample),
        "stop_before_sample": lines[stop_idx][:220] if 0 <= stop_idx < len(lines) else "",
        "stop_before_regex": _template_agent_marker_regex(lines[stop_idx]) if 0 <= stop_idx < len(lines) else "",
        "line_index_min": header_idx + 1,
        "line_index_max": max(header_idx + 1, stop_idx - 1),
        "matched_rows": int(matched_rows),
        "matched_line_indices": matched_indices[:20],
        "columns": {field: {"order": idx} for idx, field in enumerate(ordered_fields)},
        "footer_charge_labels": footer_labels,
        "charge_sections": charge_sections,
        "allow_missing_code": True,
        "allow_plain_numeric_amounts": True,
        "learned_at": _uk_now_iso(),
    }


def _template_table_profile_bounds(lines: List[str], profile: Dict[str, Any]) -> Tuple[int, int]:
    start_idx = 0
    end_idx = len(lines)
    start_pat = str(profile.get("start_after_regex") or "").strip()
    stop_pat = str(profile.get("stop_before_regex") or "").strip()
    start_matched = False
    stop_matched = False
    if start_pat:
        try:
            start_re = re.compile(start_pat, flags=re.I)
            for idx, line in enumerate(lines):
                if start_re.search(line):
                    start_idx = idx + 1
                    start_matched = True
                    break
        except Exception:
            start_idx = 0
    if (not start_matched) and profile.get("line_index_min") is not None:
        try:
            start_idx = max(0, min(int(profile.get("line_index_min") or 0), len(lines)))
        except Exception:
            start_idx = 0
    if stop_pat:
        try:
            stop_re = re.compile(stop_pat, flags=re.I)
            for idx in range(start_idx, len(lines)):
                if stop_re.search(lines[idx]):
                    end_idx = idx
                    stop_matched = True
                    break
        except Exception:
            end_idx = len(lines)
    if (not stop_matched) and profile.get("line_index_max") is not None:
        try:
            end_idx = min(len(lines), int(profile.get("line_index_max") or len(lines)) + 1)
        except Exception:
            end_idx = len(lines)
    return start_idx, max(start_idx, end_idx)


def _extract_items_with_table_profile(text: str, cfg: Any) -> List[Dict[str, Any]]:
    if not isinstance(cfg, dict):
        return []
    profile = cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}
    if not profile or not bool(profile.get("enabled", True)):
        return []
    fields = [str(x) for x in (profile.get("header_fields") or []) if str(x)]
    profile_order_fields: List[str] = []
    if isinstance(profile.get("columns"), list):
        column_fields = [
            str(col.get("field") or "").strip()
            for col in (profile.get("columns") or [])
            if isinstance(col, dict) and str(col.get("field") or "").strip()
        ]
        profile_order_fields = column_fields
        fields = list(dict.fromkeys([*fields, *column_fields]))
    if isinstance(profile.get("columns"), dict):
        try:
            column_fields = [
                str(field)
                for field, _meta in sorted(
                    profile.get("columns").items(),
                    key=lambda kv: int((kv[1] or {}).get("order") or 0) if isinstance(kv[1], dict) else 0,
                )
                if str(field)
            ]
        except Exception:
            column_fields = [str(field) for field in profile.get("columns").keys() if str(field)]
        profile_order_fields = column_fields
        fields = list(dict.fromkeys([*fields, *column_fields]))
    if "description" not in fields or "lineNet" not in fields:
        return []
    rules = cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}
    allow_plain_numeric_amounts = bool(
        profile.get("allow_plain_numeric_amounts")
        or profile.get("matched_rows")
        or rules.get("allow_plain_numeric_amounts")
    )
    raw_lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in str(text or "").splitlines()]
    raw_lines = [ln for ln in raw_lines if ln]
    if not raw_lines:
        return []
    start_idx, end_idx = _template_table_profile_bounds(raw_lines, profile)
    skip_re = re.compile(
        r"\b(invoice|facture|customer|client|supplier|fournisseur|subtotal|total\b|total\s+ttc|total\s+ht|"
        r"tva|vat|payment|reglement|r[eè]glement|bank|coordonnees|coordonn[eé]es)\b",
        flags=re.I,
    )
    headerish_re = re.compile(
        r"\b(page|due\s+date|invoice\s+date|invoice\s+number|sold[-\s]*to|bill[-\s]*to|"
        r"service\s+usage\s+address|visual\s+business\s+retail|kingston|surrey|london|"
        r"cambridge\s+road|united\s+kingdom|vat\s+id|order\s+details|billing\s+summary|"
        r"customer\s+po|order\s+number|billing\s+period)\b",
        flags=re.I,
    )
    items: List[Dict[str, Any]] = []
    seen: set[Tuple[str, float]] = set()
    for idx in range(start_idx, end_idx):
        line = raw_lines[idx]
        if not line or skip_re.search(_template_table_normalise_label(line)):
            continue
        if headerish_re.search(line):
            continue
        nums = _template_agent_number_spans(line)
        value_nums = [n for n in nums if not (n.get("is_percent") and _safe_float(n.get("value")) == 0 and len(nums) <= 1)]
        has_money_value = any(bool(n.get("is_money")) for n in value_nums) or bool(re.search(r"[€£$]|\b(EUR|GBP|USD)\b", line, flags=re.I))
        if len(value_nums) < 2 or (not has_money_value and not allow_plain_numeric_amounts):
            # Continuation text belongs to the previous row description.
            if items and not _GENERIC_CHARGE_LABEL_RE.search(line):
                extra = _collapse_spaces(line)
                if extra and extra.upper() not in items[-1]["description"].upper():
                    items[-1]["description"] = _collapse_spaces(f"{items[-1]['description']} {extra}")[:240]
            continue
        first_num_start = int(value_nums[0].get("start") or 0)
        desc = _collapse_spaces(line[:first_num_start]).strip(" -:;,\t")
        item: Dict[str, Any] = {
            "lineNo": len(items) + 1,
            "code": "",
            "description": desc[:220],
            "casePack": "",
            "unitSize": "",
            "vatCode": "",
            "isVoid": False,
            "rawRow": line,
        }

        # Assign common supplier table fields from the right side so optional
        # unit/discount columns do not break amount extraction.
        remaining = list(value_nums)
        qty_span = None
        unit_price_span = None
        line_net_span = None
        numeric_order_source = profile_order_fields or fields
        profile_numeric_fields = [
            field
            for field in numeric_order_source
            if field in {"qty", "unitPrice", "discount", "lineNet", "vatRate", "vatAmount", "lineGross"}
        ]
        if len(profile_numeric_fields) >= 2 and len(value_nums) >= len(profile_numeric_fields):
            profile_spans = list(value_nums)[-len(profile_numeric_fields):]
            for field, span in zip(profile_numeric_fields, profile_spans):
                value = round(_safe_float(span.get("value")), 4)
                if field == "qty":
                    item["qty"] = value
                    qty_span = span
                elif field == "unitPrice":
                    item["unitPrice"] = value
                    unit_price_span = span
                elif field == "discount":
                    item["discount"] = value
                elif field == "lineNet":
                    item["lineNet"] = round(value, 2)
                    line_net_span = span
                elif field == "vatRate":
                    item["vatRate"] = _normalise_vat_rate(value)
                elif field == "vatAmount":
                    item["vatAmount"] = round(value, 2)
                    item["_template_vatAmount_explicit"] = round(value, 2)
                elif field == "lineGross":
                    item["lineGross"] = round(value, 2)
                    item["_template_lineGross_explicit"] = round(value, 2)
            remaining = []
        if any(field == "vatRate" for field in fields) and remaining and remaining[-1].get("is_percent"):
            item["vatRate"] = _safe_float(remaining[-1].get("value"))
            remaining = remaining[:-1]
        if remaining:
            line_net_span = remaining[-1]
            item["lineNet"] = round(_safe_float(line_net_span.get("value")), 2)
            remaining = remaining[:-1]
        try:
            if line_net_span is not None and not str(item.get("vatCode") or "").strip():
                prev_end = 0
                if remaining:
                    prev_end = int(remaining[-1].get("end") or 0)
                before_amount = _collapse_spaces(line[prev_end:int(line_net_span.get("start") or 0)])
                m_vat_code = re.search(r"\b([A-Z](?:/[A-Z])?)\b\s*$", before_amount.upper())
                if m_vat_code:
                    item["vatCode"] = m_vat_code.group(1)
        except Exception:
            pass
        if "discount" in fields and remaining and remaining[-1].get("is_percent"):
            item["discount"] = _safe_float(remaining[-1].get("value"))
            remaining = remaining[:-1]
        if remaining:
            unit_price_span = remaining[-1]
            item["unitPrice"] = round(_safe_float(unit_price_span.get("value")), 4)
            remaining = remaining[:-1]
        if remaining:
            qty_span = remaining[-1]
            item["qty"] = round(_safe_float(qty_span.get("value")), 4)
            remaining = remaining[:-1]
        if qty_span is not None:
            desc = _collapse_spaces(line[: int(qty_span.get("start") or first_num_start)]).strip(" -:;,\t")
            item["description"] = desc[:220]
        item["description"] = _template_crop_description_to_reviewed_anchor(item.get("description"), cfg)
        if not item.get("description"):
            continue
        if "vatRate" not in item:
            item["vatRate"] = 0.0
        # Unit text is the token between quantity and unit price where present.
        try:
            if qty_span is not None and unit_price_span is not None:
                qty_end = int(qty_span.get("end") or 0)
                price_start = int(unit_price_span.get("start") or 0)
                unit_txt = _collapse_spaces(line[qty_end:price_start])
                unit_txt = re.sub(r"^[^\w]+|[^\w]+$", "", unit_txt)
                if unit_txt and len(unit_txt) <= 20:
                    item["unitSize"] = unit_txt
        except Exception:
            pass
        line_net = _safe_float(item.get("lineNet"))
        vat_rate = _normalise_vat_rate(item.get("vatRate"))
        try:
            vat_code_for_map = str(item.get("vatCode") or "").strip().upper()
            vat_map_cfg = cfg.get("vat_map") if isinstance(cfg.get("vat_map"), dict) else {}
            if not vat_map_cfg:
                vat_map_cfg = VAT_MAPPING_DEFAULT
            if vat_code_for_map and _safe_float(vat_rate) == 0.0 and isinstance(vat_map_cfg, dict):
                for k, v in vat_map_cfg.items():
                    if str(k or "").strip().upper() == vat_code_for_map:
                        vat_rate = _normalise_vat_rate(v)
                        break
        except Exception:
            pass
        item["vatRate"] = vat_rate
        item["vatAmount"] = round(line_net * vat_rate / 100.0, 2) if line_net and vat_rate else 0.0
        item["lineGross"] = round(line_net + _safe_float(item.get("vatAmount")), 2)
        if line_net <= 0:
            continue
        key = (item["description"].upper(), round(line_net, 2))
        if key in seen:
            continue
        seen.add(key)
        items.append(item)
    # Training text can contain several OCR representations of the same page.
    # If the first repeated header produces an empty bounded section, retry the
    # whole text. Financial reconciliation in the caller remains the safety gate.
    if not items and (start_idx > 0 or end_idx < len(raw_lines)):
        fallback_cfg = copy.deepcopy(cfg)
        fallback_profile = copy.deepcopy(profile)
        for key in (
            "start_after_regex",
            "stop_before_regex",
            "line_index_min",
            "line_index_max",
        ):
            fallback_profile.pop(key, None)
        fallback_cfg["table_profile"] = fallback_profile
        return _extract_items_with_table_profile(text, fallback_cfg)

    charge_items = _extract_items_with_charge_sections(text, cfg)
    if charge_items:
        existing = {
            (
                str(it.get("description") or "").strip().upper(),
                round(_safe_float(it.get("lineNet")), 2),
            )
            for it in items
        }
        for ch in charge_items:
            key = (
                str(ch.get("description") or "").strip().upper(),
                round(_safe_float(ch.get("lineNet")), 2),
            )
            if key not in existing:
                items.append(ch)
                existing.add(key)
    return _ensure_line_numbers(items) if items else []


def _extract_items_with_trained_template_agent(text: str, cfg: Any) -> List[Dict[str, Any]]:
    if not isinstance(cfg, dict):
        return []
    table_items = _extract_items_with_table_profile(text or "", cfg)
    table_items_have_regular_rows = any(
        not (bool(it.get("_reconOnly")) or str(it.get("rowTag") or "").strip().upper() in {"RECON", "CHARGE", "SURCHARGE"})
        for it in (table_items or [])
        if isinstance(it, dict)
    )
    if table_items and table_items_have_regular_rows:
        return _apply_template_vat_code_from_text(table_items, text or "", cfg)
    charge_items = _extract_items_with_charge_sections(text or "", cfg)
    agent = cfg.get("template_agent") if isinstance(cfg.get("template_agent"), dict) else {}
    if not agent or not bool(agent.get("enabled", True)):
        return _apply_template_vat_code_from_text(_ensure_line_numbers(charge_items), text or "", cfg) if charge_items else []
    code_regex = str(agent.get("code_regex") or "").strip()
    description_anchors = agent.get("description_anchors") or []
    allow_missing_code = bool(agent.get("allow_missing_code")) and isinstance(description_anchors, list)
    generic_description_rows = bool(agent.get("generic_description_rows"))
    numeric_fields_from_end = agent.get("numeric_fields_from_end") or {}
    if (not code_regex and not allow_missing_code and not generic_description_rows) or not isinstance(numeric_fields_from_end, dict):
        return []
    code_re = None
    try:
        if code_regex:
            code_re = re.compile(rf"(?<![A-Z0-9])({code_regex})(?![A-Z0-9])", flags=re.I)
    except Exception:
        return []
    min_number_count = max(1, int(agent.get("min_number_count") or 1))
    try:
        row_window_lines = max(1, min(4, int(agent.get("row_window_lines") or 1)))
    except Exception:
        row_window_lines = 1
    skip_re = re.compile(r"\b(invoice|customer|supplier|subtotal|total|vat|amount due|balance due)\b", flags=re.I)
    items: List[Dict[str, Any]] = []
    seen: set[Tuple[str, str, float]] = set()
    raw_lines = [_collapse_spaces(str(raw_line or "").replace("|", " ")) for raw_line in str(text or "").splitlines()]
    raw_lines = [ln for ln in raw_lines if ln]
    start_idx = 0
    end_idx = len(raw_lines)
    region = agent.get("table_region") if isinstance(agent.get("table_region"), dict) else {}
    if isinstance(region, dict) and raw_lines:
        start_pat = str(region.get("start_after_regex") or "").strip()
        stop_pat = str(region.get("stop_before_regex") or "").strip()
        if start_pat:
            try:
                start_re = re.compile(start_pat, flags=re.I)
                for idx, raw_line in enumerate(raw_lines):
                    if start_re.search(raw_line):
                        start_idx = idx + 1
                        break
            except Exception:
                start_idx = 0
        elif region.get("line_index_min") is not None:
            try:
                learned_min = int(region.get("line_index_min") or 0)
                # Use learned absolute line bounds only when the document text is
                # roughly similar length; marker matching is preferred above.
                if len(raw_lines) >= learned_min + 3:
                    start_idx = max(0, min(learned_min, len(raw_lines) - 1))
            except Exception:
                start_idx = 0
        if stop_pat:
            try:
                stop_re = re.compile(stop_pat, flags=re.I)
                for idx in range(start_idx, len(raw_lines)):
                    if stop_re.search(raw_lines[idx]):
                        end_idx = idx
                        break
            except Exception:
                end_idx = len(raw_lines)
        elif region.get("line_index_max") is not None:
            try:
                learned_max = int(region.get("line_index_max") or len(raw_lines))
                if learned_max > start_idx:
                    end_idx = min(len(raw_lines), learned_max + 1)
            except Exception:
                end_idx = len(raw_lines)

    for line_idx in range(start_idx, end_idx):
        line = raw_lines[line_idx]
        if not line or skip_re.search(line):
            continue
        code = ""
        after = line
        if code_re is not None:
            m_code = code_re.search(line)
            if not m_code:
                continue
            code = m_code.group(1).strip()
            after = line[m_code.end():]
        elif allow_missing_code:
            up_line = line.upper()
            anchor_match = False
            anchor_start: Optional[int] = None
            for anchors in description_anchors:
                if not isinstance(anchors, list):
                    continue
                usable = [str(a or "").upper() for a in anchors if len(str(a or "").strip()) >= 3]
                if usable and sum(1 for a in usable if a in up_line) >= min(3, len(usable)):
                    anchor_match = True
                    positions = [up_line.find(a) for a in usable if up_line.find(a) >= 0]
                    if positions:
                        anchor_start = min(positions)
                    break
            if not anchor_match:
                continue
            # The OCR row can be merged with payment/address text on its left.
            # Start at the reviewed description anchor so that a teacher row
            # such as "CHARGES" does not learn "Due on Receipt ... CHARGES".
            if anchor_start is not None and anchor_start > 0:
                after = line[anchor_start:]
        elif generic_description_rows:
            if len(re.findall(r"[A-Z]{3,}", line.upper())) < 1:
                continue
        numbers = _template_agent_number_spans(after)
        if len(numbers) < min_number_count and row_window_lines > 1:
            window_text = " ".join(raw_lines[line_idx : line_idx + row_window_lines])
            if code_re is not None:
                m_window_code = code_re.search(window_text)
                if not m_window_code:
                    continue
                after = window_text[m_window_code.end():]
            else:
                after = window_text
            numbers = _template_agent_number_spans(after)
        if len(numbers) < min_number_count:
            continue
        item: Dict[str, Any] = {
            "lineNo": len(items) + 1,
            "code": code,
            "description": _template_agent_clean_description(after, numbers),
            "casePack": "",
            "unitSize": "",
            "vatCode": "",
            "isVoid": False,
            "rawRow": line,
        }
        assigned_spans: Dict[str, Dict[str, Any]] = {}
        for field, from_end_raw in numeric_fields_from_end.items():
            try:
                from_end = int(from_end_raw)
            except Exception:
                continue
            idx = len(numbers) - 1 - from_end
            if 0 <= idx < len(numbers):
                assigned_spans[str(field)] = numbers[idx]
                value = round(float(numbers[idx]["value"]), 4)
                item[str(field)] = value
                if str(field) in ("vatAmount", "lineGross"):
                    item[f"_template_{field}_explicit"] = value
        desc_cut_starts = [
            int(assigned_spans[field].get("start") or 0)
            for field in ("qty", "unitPrice", "lineNet", "vatRate", "vatAmount", "lineGross")
            if isinstance(assigned_spans.get(field), dict)
        ]
        if desc_cut_starts:
            desc_end = min([x for x in desc_cut_starts if x > 0] or desc_cut_starts)
            desc_candidate = _collapse_spaces(after[:desc_end]).strip(" -:;,\t")
            if desc_candidate:
                item["description"] = desc_candidate[:220]
        if not item.get("description"):
            continue
        qty = _safe_float(item.get("qty"))
        unit_price = _safe_float(item.get("unitPrice"))
        line_net = _safe_float(item.get("lineNet"))
        if line_net <= 0 and qty and unit_price:
            item["lineNet"] = round(qty * unit_price, 2)
            line_net = _safe_float(item.get("lineNet"))
        vat_rate = _safe_float(item.get("vatRate"))
        if "vatAmount" not in numeric_fields_from_end and _safe_float(item.get("vatAmount")) <= 0 and line_net and vat_rate:
            item["vatAmount"] = round(line_net * vat_rate / 100.0, 2)
        if _safe_float(item.get("lineGross")) <= 0 and line_net:
            item["lineGross"] = round(line_net + _safe_float(item.get("vatAmount")), 2)
        key = (code.upper(), item["description"].upper(), round(_safe_float(item.get("lineNet")), 2))
        if key in seen:
            continue
        seen.add(key)
        items.append(item)
    if charge_items:
        existing_charge_keys = {
            (
                str(it.get("description") or "").strip().upper(),
                round(_safe_float(it.get("lineNet")), 2),
            )
            for it in items
        }
        for ch in charge_items:
            key = (
                str(ch.get("description") or "").strip().upper(),
                round(_safe_float(ch.get("lineNet")), 2),
            )
            if key not in existing_charge_keys:
                items.append(ch)
                existing_charge_keys.add(key)
    return _apply_template_vat_code_from_text(_ensure_line_numbers(items), text or "", cfg) if items else []


def _apply_template_vat_code_from_text(items: List[Dict[str, Any]], text: str, cfg: Any) -> List[Dict[str, Any]]:
    """Fill missing vatCode by matching row amount/code to OCR text and reading token before amount."""
    rows = [dict(it) for it in (items or []) if isinstance(it, dict)]
    if not rows or not str(text or "").strip():
        return rows
    cfg = cfg if isinstance(cfg, dict) else {}
    rules = cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}
    enabled = bool(rules.get("vat_code_from_text", True))
    if not enabled:
        return rows
    raw_lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in str(text or "").splitlines()]
    raw_lines = [ln for ln in raw_lines if ln]
    if not raw_lines:
        return rows
    vat_map_cfg = cfg.get("vat_map") if isinstance(cfg.get("vat_map"), dict) else {}
    if not vat_map_cfg:
        vat_map_cfg = VAT_MAPPING_DEFAULT

    def _line_has_item_identity(line: str, item: Dict[str, Any]) -> bool:
        code = re.sub(r"\s+", "", str(item.get("code") or "")).strip()
        if code and code.upper() in re.sub(r"\s+", "", line).upper():
            return True
        desc = str(item.get("description") or "").upper()
        words = [w for w in re.findall(r"[A-Z0-9]{3,}", desc) if w not in {"NEW", "ORDER", "NEXT", "DAY"}][:5]
        if words and sum(1 for w in words if w in line.upper()) >= min(2, len(words)):
            return True
        return False

    for item in rows:
        if not isinstance(item, dict) or str(item.get("vatCode") or "").strip():
            continue
        line_net = round(_safe_float(item.get("lineNet")), 2)
        if line_net <= 0:
            continue
        best_line = ""
        for line in raw_lines:
            nums = _template_agent_number_spans(line)
            amount_match = any(_template_agent_value_matches(line_net, n.get("value")) for n in nums)
            if not amount_match:
                continue
            if _line_has_item_identity(line, item) or not best_line:
                best_line = line
                if _line_has_item_identity(line, item):
                    break
        if not best_line:
            continue
        nums = _template_agent_number_spans(best_line)
        amount_spans = [n for n in nums if _template_agent_value_matches(line_net, n.get("value"))]
        if not amount_spans:
            continue
        amount_span = amount_spans[-1]
        before_amount = _collapse_spaces(best_line[: int(amount_span.get("start") or 0)]).upper()
        m_code = re.search(r"\b([A-Z](?:/[A-Z])?)\b\s*$", before_amount)
        if not m_code:
            continue
        vat_code = m_code.group(1).strip().upper()
        if vat_code in {"AS", "KG", "CR", "CM", "CT", "DY", "RM"}:
            continue
        item["vatCode"] = vat_code
        try:
            for k, v in vat_map_cfg.items():
                if str(k or "").strip().upper() == vat_code:
                    item["vatRate"] = _normalise_vat_rate(v)
                    break
            vat_rate = _normalise_vat_rate(item.get("vatRate"))
            item["vatAmount"] = round(line_net * vat_rate / 100.0, 2) if vat_rate else _safe_float(item.get("vatAmount"))
            item["lineGross"] = round(line_net + _safe_float(item.get("vatAmount")), 2)
            if not item.get("rawRow"):
                item["rawRow"] = best_line
        except Exception:
            pass
    return rows


def _items_need_template_agent(items: List[Dict[str, Any]]) -> bool:
    if not items:
        return True
    usable = 0
    for item in items or []:
        if not isinstance(item, dict):
            continue
        if str(item.get("code") or "").strip() and str(item.get("description") or "").strip() and _safe_float(item.get("lineNet")) > 0:
            usable += 1
    return usable < max(1, min(3, len(items or [])))


def _trained_template_items_are_plausible(
    template_items: List[Dict[str, Any]],
    existing_items: List[Dict[str, Any]],
    cfg: Any,
) -> Tuple[bool, str]:
    """Reject template line output that looks like document header text, not invoice rows."""
    if not template_items:
        return False, "no template line rows were produced"
    if not isinstance(cfg, dict):
        cfg = {}
    agent = cfg.get("template_agent") if isinstance(cfg.get("template_agent"), dict) else {}
    profile = cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}
    rules = cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}
    teacher_output = cfg.get("gemini_teacher_output") if isinstance(cfg.get("gemini_teacher_output"), dict) else {}
    code_regex = str(agent.get("code_regex") or "").strip()
    code_re = None
    if code_regex:
        try:
            code_re = re.compile(rf"^(?:{code_regex})$", flags=re.I)
        except Exception:
            code_re = None
    headerish_re = re.compile(
        r"\b("
        r"overview|account|previous|current\s+balance|visual|business\s+retail|"
        r"invoice|statement|"
        r"customer|supplier|subtotal|total|vat|balance|31st|december|"
        r"page|due\s+date|sold[-\s]*to|bill[-\s]*to|service\s+usage\s+address|"
        r"kingston|surrey|london|cambridge\s+road|united\s+kingdom|billing\s+summary"
        r")\b",
        flags=re.I,
    )
    plausible = 0
    headerish = 0
    extreme_value = 0
    for item in template_items or []:
        if not isinstance(item, dict):
            continue
        code = str(item.get("code") or "").strip()
        desc = str(item.get("description") or "").strip()
        line_net = _safe_float(item.get("lineNet"))
        unit_price = _safe_float(item.get("unitPrice"))
        qty = _safe_float(item.get("qty") or item.get("quantity"))
        code_ok = bool(code and (code_re.match(code) if code_re is not None else len(code) >= 3))
        amount_ok = 0 < line_net < 100000 and (unit_price <= 0 or unit_price < 100000)
        no_code_ok = bool(
            (not code)
            and desc
            and amount_ok
            and (
                bool(agent.get("allow_missing_code"))
                or bool(agent.get("generic_description_rows"))
                or bool(profile.get("allow_missing_code"))
                or bool(rules.get("allow_missing_code"))
                or str(rules.get("line_match_strategy") or "").strip().lower() == "description_anchor"
            )
        )
        service_ok = bool(re.search(r"\b(charge|fuel|carriage|delivery|service|surcharge)\b", desc, flags=re.I) and amount_ok)
        if code_ok and desc and amount_ok:
            plausible += 1
        elif no_code_ok:
            plausible += 1
        elif service_ok:
            plausible += 1
        if headerish_re.search(f"{code} {desc}"):
            headerish += 1
        if abs(line_net) >= 100000 or abs(unit_price) >= 100000:
            extreme_value += 1
    row_count = len(template_items or [])
    teacher_descriptions = [
        _collapse_spaces(str(value or "")).upper()
        for value in (teacher_output.get("descriptions") or [])
        if str(value or "").strip()
    ]
    teacher_row_count = int(teacher_output.get("row_count") or len(teacher_descriptions) or 0)
    if teacher_row_count == 1 and bool(rules.get("preserve_teacher_line_rows")) and row_count != 1:
        return False, f"template produced {row_count} rows but the reviewed teacher output requires 1 row"
    if teacher_descriptions:
        produced_descriptions = [
            _collapse_spaces(str(item.get("description") or "")).upper()
            for item in (template_items or [])
            if isinstance(item, dict)
        ]
        teacher_anchor_found = any(
            reviewed in produced or produced in reviewed
            for reviewed in teacher_descriptions
            for produced in produced_descriptions
            if reviewed and produced
        )
        if not teacher_anchor_found:
            return False, "template line descriptions do not contain the reviewed teacher description anchor"
    if plausible <= 0:
        return False, "template rows did not match trained line-code, description-anchor, or service-charge patterns"
    if row_count >= 5 and plausible < max(2, int(row_count * 0.35)):
        return False, "most template rows look unlike valid invoice lines"
    if row_count >= 5 and headerish >= max(3, int(row_count * 0.35)):
        return False, "template parser captured header/summary text as line rows"
    if row_count >= 5 and extreme_value >= max(2, int(row_count * 0.25)):
        return False, "template parser captured account/date numbers as line amounts"
    if existing_items and row_count > max(len(existing_items) * 3, len(existing_items) + 20):
        return False, "template produced far more rows than the current extraction"
    return True, ""


def _coerce_template_items_to_reviewed_teacher_shape(
    header: Dict[str, Any],
    template_items: List[Dict[str, Any]],
    cfg: Any,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]], bool]:
    """Use reviewed teacher shape to repair over-split local service rows."""
    if not isinstance(header, dict):
        header = {}
    if not isinstance(cfg, dict) or not template_items:
        return header, template_items, False
    rules = cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}
    teacher_output = cfg.get("gemini_teacher_output") if isinstance(cfg.get("gemini_teacher_output"), dict) else {}
    teacher_descriptions = [
        _collapse_spaces(str(value or "")).upper()
        for value in (teacher_output.get("descriptions") or [])
        if str(value or "").strip()
    ]
    teacher_row_count = int(teacher_output.get("row_count") or len(teacher_descriptions) or 0)
    if teacher_row_count != 1 or not bool(rules.get("preserve_teacher_line_rows")):
        return header, template_items, False
    teacher_desc = teacher_descriptions[0] if teacher_descriptions else ""
    blocked_re = re.compile(
        r"\b(invoice|customer|supplier|payment|bank|sort\s*code|account|email|due\s+on\s+receipt|"
        r"bill\s+to|sold\s+to|address|date)\b|@",
        flags=re.I,
    )

    def _amount_has_money_context(item: Dict[str, Any], amount: float) -> bool:
        if amount <= 0:
            return False
        raw = _collapse_spaces(
            " ".join(
                str(x or "")
                for x in (
                    (item or {}).get("rawRow"),
                    (item or {}).get("description"),
                    (item or {}).get("code"),
                )
            )
        )
        # Years are common false positives in invoice headers. Accept a
        # year-sized value only when the OCR row has explicit money formatting.
        if 1900 <= abs(amount) <= 2099:
            amt_i = str(int(round(abs(amount))))
            money_pattern = rf"(£|GBP|\b{re.escape(amt_i)}[,.]\d{{2}}\b)"
            if not re.search(money_pattern, raw, flags=re.I):
                return False
            if re.search(r"\b(invoice\s*(no|number)?|date|tax\s*point)\b", raw, flags=re.I):
                return False
        return True

    def _row_score(item: Dict[str, Any]) -> Tuple[int, int, int, float]:
        desc = _collapse_spaces(str((item or {}).get("description") or "")).upper()
        text = f"{item.get('code') or ''} {desc}"
        anchor_score = 0
        if teacher_desc:
            if teacher_desc in desc or desc in teacher_desc:
                anchor_score = 3
            else:
                anchor_words = [w for w in teacher_desc.split() if len(w) >= 3]
                anchor_score = sum(1 for word in anchor_words if word in desc)
        amount = max(
            abs(_safe_float((item or {}).get("lineNet"))),
            abs(_safe_float((item or {}).get("lineGross"))),
            abs(_safe_float((item or {}).get("unitPrice"))),
        )
        if not _amount_has_money_context(item, amount):
            amount = 0.0
        amount_score = 1 if amount > 0 else 0
        clean_score = 0 if blocked_re.search(text) else 1
        return (anchor_score, amount_score, clean_score, amount)

    candidates = [dict(it) for it in (template_items or []) if isinstance(it, dict)]
    if not candidates:
        return header, template_items, False
    candidates.sort(key=_row_score, reverse=True)
    best = candidates[0]
    best_score = _row_score(best)
    if best_score[0] <= 0 and teacher_desc:
        return header, template_items, False

    row = dict(best)
    row["lineNo"] = 1
    if teacher_desc and not _collapse_spaces(str(row.get("description") or "")).strip():
        row["description"] = teacher_desc.title()
    elif teacher_desc and teacher_desc not in _collapse_spaces(str(row.get("description") or "")).upper():
        row.setdefault("rawRow", str(best.get("rawRow") or best.get("description") or ""))
        row["description"] = teacher_desc.title()

    header_net = round(_safe_float(header.get("totalNet")), 2)
    header_vat = round(_safe_float(header.get("totalVat")), 2)
    header_gross = round(_safe_float(header.get("totalGross")), 2)
    row_net = round(_safe_float(row.get("lineNet")), 2)
    row_vat = round(_safe_float(row.get("vatAmount")), 2)
    row_gross = round(_safe_float(row.get("lineGross")), 2)
    if not _amount_has_money_context(row, row_net):
        row_net = 0.0
        row["lineNet"] = 0.0
    if not _amount_has_money_context(row, row_gross):
        row_gross = 0.0
        row["lineGross"] = 0.0
    if 1900 <= abs(header_net) <= 2099 and header_net == header_gross:
        header_net = 0.0
        header_gross = 0.0
        header["totalNet"] = 0.0
        header["totalGross"] = 0.0
    if row_net <= 0 and header_net > 0:
        row_net = header_net
    if row_vat <= 0 and header_vat > 0:
        row_vat = header_vat
    if row_gross <= 0 and header_gross > 0:
        row_gross = header_gross
    elif row_gross <= 0 and row_net > 0:
        row_gross = round(row_net + row_vat, 2)
    if row_net <= 0 and row_gross > 0 and row_vat <= 0:
        row_net = row_gross

    if row_net > 0:
        row["lineNet"] = row_net
    if row_vat >= 0:
        row["vatAmount"] = row_vat
    if row_gross > 0:
        row["lineGross"] = row_gross
    if _safe_float(row.get("qty")) <= 0:
        row["qty"] = 1.0
    if _safe_float(row.get("unitPrice")) <= 0 and row_net > 0:
        row["unitPrice"] = round(row_net / max(_safe_float(row.get("qty")), 1.0), 4)
    row["_template_teacher_shape_rescue"] = True

    if header_net <= 0 and row_net > 0:
        header["totalNet"] = row_net
    if header_vat <= 0 and row_vat >= 0:
        header["totalVat"] = row_vat
    if header_gross <= 0 and row_gross > 0:
        header["totalGross"] = row_gross
    return header, [row], True


def _template_agent_reconciliation_diff(header: Dict[str, Any], items: List[Dict[str, Any]], text: str = "") -> float:
    try:
        metrics = _calc_metrics(header or {}, _reconciliation_items(header or {}, [dict(it) for it in (items or [])], text or ""))
        return max(
            abs(_safe_float(metrics.get("diff_net"))),
            abs(_safe_float(metrics.get("diff_vat"))),
            abs(_safe_float(metrics.get("diff_gross"))),
        )
    except Exception:
        return 999999.0


def _apply_trained_supplier_template_agent(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    text: str,
    template_hit: Optional[Dict[str, Any]],
) -> Tuple[Dict[str, Any], List[Dict[str, Any]], bool]:
    if not isinstance(template_hit, dict):
        return header, items, False
    cfg = template_hit.get("config") or {}
    if not isinstance(cfg, dict):
        return header, items, False
    header = _apply_template_header_aliases(header if isinstance(header, dict) else {}, text or "", cfg.get("header_aliases"), force=True)
    header = _apply_template_trusted_header_values(header, template_hit)
    header = _template_apply_invoice_number_pattern(header, cfg)
    template_supplier = _template_supplier_name_from_hit(template_hit)
    if _template_supplier_value_should_use_match(header.get("supplierName"), template_supplier):
        header["supplierName"] = template_supplier
    template_items = _extract_items_with_trained_template_agent(text or "", cfg)
    try:
        agent = cfg.get("template_agent") if isinstance(cfg.get("template_agent"), dict) else {}
        profile = cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}
        rules = cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}
        header_net = round(_safe_float((header or {}).get("totalNet")), 2)
        header_vat = round(_safe_float((header or {}).get("totalVat")), 2)
        header_gross = round(_safe_float((header or {}).get("totalGross")), 2)
        single_no_code_header_total_rule = bool(
            rules.get("single_line_no_code_use_header_totals")
            or rules.get("single_line_use_header_totals")
        )
        if not template_items and single_no_code_header_total_rule and header_net > 0:
            raw_lines = [_collapse_spaces(str(ln or "").replace("|", " ")) for ln in str(text or "").splitlines()]
            raw_lines = [ln for ln in raw_lines if ln]
            anchors = agent.get("description_anchors") if isinstance(agent.get("description_anchors"), list) else []
            blocked_re = re.compile(
                r"\b(invoice|subtotal|total|vat|tax|balance|amount\s+due|payment|bank|customer|supplier|bill\s+to|sold\s+to)\b",
                flags=re.I,
            )

            def _anchor_score(line: str) -> int:
                up = line.upper()
                best = 0
                for anchor_group in anchors:
                    if not isinstance(anchor_group, list):
                        continue
                    words = [str(x or "").strip().upper() for x in anchor_group if len(str(x or "").strip()) >= 3]
                    if words:
                        best = max(best, sum(1 for word in words if word in up))
                return best

            candidates: List[Tuple[int, int, str, Optional[Dict[str, Any]]]] = []
            for idx, line in enumerate(raw_lines):
                if not line or blocked_re.search(line):
                    continue
                nums = _template_agent_number_spans(line)
                amount_spans = [
                    num for num in nums
                    if _template_agent_value_matches(header_net, num.get("value"))
                    or (header_gross > 0 and _template_agent_value_matches(header_gross, num.get("value")))
                ]
                score = _anchor_score(line)
                if amount_spans or score > 0:
                    candidates.append((1 if amount_spans else 0, score, line, amount_spans[-1] if amount_spans else None))
            candidates = [cand for cand in candidates if cand[0] or cand[1] >= 1]
            if candidates:
                candidates.sort(key=lambda cand: (cand[0], cand[1], len(cand[2])), reverse=True)
                _has_amount, _score, best_line, amount_span = candidates[0]
                if amount_span is not None:
                    desc = _collapse_spaces(best_line[: int(amount_span.get("start") or 0)]).strip(" -:;,\t")
                else:
                    desc = _collapse_spaces(best_line).strip(" -:;,\t")
                if desc:
                    template_items = [
                        {
                            "lineNo": 1,
                            "code": "",
                            "description": desc[:220],
                            "casePack": "",
                            "unitSize": "",
                            "qty": 1.0,
                            "unitPrice": header_net,
                            "lineNet": header_net,
                            "vatCode": "",
                            "vatRate": 0.0,
                            "vatAmount": header_vat,
                            "lineGross": header_gross if header_gross > 0 else round(header_net + header_vat, 2),
                            "isVoid": False,
                            "rawRow": best_line,
                            "_template_total_rescue": True,
                        }
                    ]
        no_code_total_rescue = bool(
            1 <= len(template_items or []) <= 3
            and header_net > 0
            and abs(header_gross - (header_net + header_vat)) <= 0.05
            and all(
                isinstance(it, dict)
                and not str(it.get("code") or "").strip()
                and str(it.get("description") or "").strip()
                for it in (template_items or [])
            )
            and (
                single_no_code_header_total_rule
            )
        )
        if no_code_total_rescue:
            before_diff = _template_agent_reconciliation_diff(header, template_items or [], text or "")
            if before_diff > max(1.0, header_net * 0.02):
                row = dict(
                    sorted(
                        [it for it in (template_items or []) if isinstance(it, dict)],
                        key=lambda it: len(str(it.get("description") or "")),
                        reverse=True,
                    )[0]
                )
                row["lineNet"] = header_net
                row["vatAmount"] = header_vat
                row["lineGross"] = header_gross if header_gross > 0 else round(header_net + header_vat, 2)
                if _safe_float(row.get("qty")) > 0:
                    row["unitPrice"] = round(header_net / _safe_float(row.get("qty")), 4)
                row["_template_total_rescue"] = True
                template_items = [row]
        try:
            header, template_items, teacher_shape_used = _coerce_template_items_to_reviewed_teacher_shape(
                header,
                template_items or [],
                cfg,
            )
            if teacher_shape_used:
                header["_template_teacher_shape_rescue_used"] = True
        except Exception:
            pass
    except Exception:
        pass
    plausible, reason = _trained_template_items_are_plausible(template_items, items or [], cfg)
    current_diff = _template_agent_reconciliation_diff(header, items or [], text or "") if items else 999999.0
    template_diff = _template_agent_reconciliation_diff(header, template_items or [], text or "") if template_items else 999999.0
    header_total = max(
        abs(_safe_float((header or {}).get("totalNet"))),
        abs(_safe_float((header or {}).get("totalGross"))),
    )
    template_reconciles = bool(
        template_items
        and (
            header_total <= 0
            or template_diff <= max(1.0, header_total * 0.02)
            or (current_diff < 999999.0 and template_diff + 0.05 < current_diff and (current_diff - template_diff) >= 1.0)
        )
    )
    reconciles_better = bool(template_items and plausible and template_diff + 0.05 < current_diff and (current_diff - template_diff) >= 1.0)
    if template_items and plausible and template_reconciles and (_items_need_template_agent(items) or len(template_items) > len(items or []) or reconciles_better):
        items = template_items
        try:
            _fill_header_totals_from_items(header, items)
        except Exception:
            pass
        return header, items, True
    if template_items and not plausible:
        try:
            header["_template_line_reject_reason"] = reason
        except Exception:
            pass
    elif template_items and plausible:
        try:
            if not template_reconciles:
                header["_template_line_reject_reason"] = (
                    f"template produced {len(template_items)} plausible row(s), but they do not reconcile "
                    f"with invoice totals; template diff={template_diff:.2f}, current diff={current_diff:.2f}"
                )
            else:
                header["_template_line_reject_reason"] = (
                    f"template produced {len(template_items)} plausible row(s), but current rows were kept "
                    f"because reconciliation was not better; template diff={template_diff:.2f}, current diff={current_diff:.2f}"
                )
        except Exception:
            pass
    return header, _apply_template_line_aliases(items or [], cfg.get("line_aliases")), False


def _template_supplier_name_from_hit(template_hit: Optional[Dict[str, Any]]) -> str:
    if not isinstance(template_hit, dict):
        return ""
    supplier = _normalise_supplier_name(str(template_hit.get("supplier_name") or "").strip())
    if supplier and not _template_header_value_is_placeholder("supplierName", supplier):
        return supplier
    keywords = template_hit.get("match_keywords")
    if not isinstance(keywords, list):
        try:
            keywords = json.loads(template_hit.get("match_keywords_json") or "[]")
        except Exception:
            keywords = []
    blocked = {
        "ORDER", "INVOICE", "ORDER INVOICE", "REFERENCE", "REFERENCE NUMBER",
        "CUSTOMER", "SUPPLIER", "THE COMPANY",
    }
    for keyword in keywords or []:
        cand = _normalise_supplier_name(str(keyword or "").strip())
        if len(cand) < 3:
            continue
        if cand.upper() in blocked:
            continue
        if "@" in cand or cand.lower().endswith(".pdf"):
            continue
        if _template_header_value_is_placeholder("supplierName", cand):
            continue
        if re.search(r"\b(REFERENCE\s+NUMBER|ESTIMATED\s+TRANSIT|CUSTOMER|SUPPLIER|INVOICE)\b", cand, flags=re.I):
            continue
        return cand
    return supplier if supplier and not _template_header_value_is_placeholder("supplierName", supplier) else ""


def _apply_supplier_template_rules(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    template_hit: Optional[Dict[str, Any]],
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    """Apply conservative per-template rules proposed by the AI template agent."""
    if not isinstance(template_hit, dict):
        return header, items
    cfg = template_hit.get("config") or {}
    if not isinstance(cfg, dict):
        return header, items
    rules = cfg.get("rules") or {}
    if not isinstance(rules, dict):
        return header, items

    header = header if isinstance(header, dict) else {}
    out_items = [dict(it) for it in (items or []) if isinstance(it, dict)]

    trusted = cfg.get("trusted_header_values") if isinstance(cfg.get("trusted_header_values"), dict) else {}
    locale_profile = cfg.get("locale_profile") if isinstance(cfg.get("locale_profile"), dict) else {}
    currency = _normalise_template_currency(
        rules.get("currency")
        or cfg.get("default_currency")
        or trusted.get("currency")
        or locale_profile.get("currency")
    )
    current_currency = _normalise_template_currency(header.get("currency"))
    if currency and (not current_currency or (current_currency == "GBP" and currency != "GBP")):
        header["currency"] = currency

    if bool(rules.get("zero_vat_amount_allowed_with_vat_rate")) or str(rules.get("line_gross_source") or "") == "total_incl_vat":
        net = round(_safe_float(header.get("totalNet")), 2)
        vat = round(_safe_float(header.get("totalVat")), 2)
        gross = round(_safe_float(header.get("totalGross")), 2)
        if net > 0.0 and gross > 0.0 and abs(net - gross) <= 0.01 and abs(vat - net) <= 0.01:
            header["totalVat"] = 0.0

    if bool(rules.get("do_not_create_blank_zero_rows")):
        filtered = []
        for it in out_items:
            has_text = bool(str(it.get("code") or "").strip() or str(it.get("description") or "").strip())
            has_value = any(_safe_float(it.get(k)) != 0.0 for k in ("qty", "unitPrice", "lineNet", "vatAmount", "lineGross"))
            if has_text or has_value:
                filtered.append(it)
        out_items = filtered

    if str(rules.get("invoice_level_vat_allocation") or "") == "allocate_header_vat_to_teacher_gross_rows":
        repaired_items, repaired_ok = _repair_teacher_invoice_level_vat(header, out_items)
        if repaired_ok:
            out_items = repaired_items

    if bool(rules.get("zero_vat_amount_allowed_with_vat_rate")) or bool(rules.get("do_not_recalculate_vat_amount_if_present")):
        header_vat_zero = _safe_float(header.get("totalVat")) == 0.0 and (
            _safe_float(header.get("totalNet")) > 0.0 or _safe_float(header.get("totalGross")) > 0.0
        )
        for it in out_items:
            if "_template_vatAmount_explicit" in it:
                it["vatAmount"] = _safe_float(it.get("_template_vatAmount_explicit"))
            if "_template_lineGross_explicit" in it:
                it["lineGross"] = _safe_float(it.get("_template_lineGross_explicit"))
            if header_vat_zero and _safe_float(it.get("vatRate")) > 0.0 and _safe_float(it.get("lineNet")) > 0.0:
                it["vatAmount"] = 0.0
                if bool(rules.get("line_gross_source") == "total_incl_vat") or _safe_float(it.get("lineGross")) <= 0.0:
                    it["lineGross"] = _safe_float(it.get("lineNet"))
            if _safe_float(it.get("vatAmount")) == 0.0 and _safe_float(it.get("lineNet")) > 0.0:
                if _safe_float(it.get("lineGross")) <= 0.0 or bool(rules.get("line_gross_source") == "total_incl_vat"):
                    it["lineGross"] = _safe_float(it.get("lineNet"))

    return header, _ensure_line_numbers(out_items) if out_items else out_items


def _detect_parser_type_from_supplier(supplier_name: str, existing_parser_type: str = "") -> str:
    existing = str(existing_parser_type or "").strip().upper()
    if existing:
        return existing
    supp = str(supplier_name or "").lower()
    if "booker" in supp:
        return "BOOKER"
    if "parfetts" in supp:
        return "PARFETTS"
    if "dhamecha" in supp:
        return "DHAMECHA"
    if "drinks wholesale group" in supp or "dwg" in supp:
        return "DWG"
    return "GENERIC"


def _train_supplier_header_template_from_corrections(
    *,
    header: Dict[str, Any],
    raw_text: str,
    file_name: str,
    engine_used: str,
    existing_template: Optional[Dict[str, Any]] = None,
    max_pages_pdf: Optional[int] = None,
    header_aliases_override: Optional[Dict[str, List[str]]] = None,
) -> Tuple[str, bool, List[str]]:
    """Create/update only the header-field portion of a supplier template.

    This intentionally does not learn or overwrite line-level parser rules, so
    admins can stabilize supplier header extraction before training items.
    """
    supplier_name = _normalise_supplier_name(str((header or {}).get("supplierName") or "").strip())

    tpl = dict(existing_template or {})
    if not tpl:
        tpl = _find_existing_supplier_template_for_training(raw_text or "", header or {}, file_name or "")

    if _template_header_value_is_placeholder("supplierName", supplier_name):
        supplier_name = _template_supplier_name_from_hit(tpl)
    if not supplier_name:
        supplier_name = _guess_supplier_from_filename(file_name or "")
    supplier_name = _normalise_supplier_name(supplier_name or "")
    if _template_header_value_is_placeholder("supplierName", supplier_name):
        supplier_name = ""
    if not supplier_name:
        raise ValueError("Supplier name is required before training a header template.")

    cfg = {}
    if tpl.get("config"):
        cfg = copy.deepcopy(tpl.get("config") or {})
    elif tpl.get("config_json"):
        try:
            cfg = json.loads(tpl.get("config_json") or "{}")
        except Exception:
            cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}

    parser_type = _detect_parser_type_from_supplier(supplier_name, str(tpl.get("parser_type") or ""))
    learned_header_aliases = _template_learn_header_aliases_from_text(header or {}, raw_text or "")
    reviewed_header_aliases = (
        _normalise_template_alias_config(header_aliases_override, _template_default_header_aliases())
        if isinstance(header_aliases_override, dict)
        else None
    )
    cfg["header_aliases"] = _template_merge_alias_config(
        cfg.get("header_aliases"),
        reviewed_header_aliases or learned_header_aliases,
        _template_default_header_aliases(),
    )
    cfg["trusted_header_values"] = {
        **(cfg.get("trusted_header_values") if isinstance(cfg.get("trusted_header_values"), dict) else {}),
        **_template_trusted_header_values_from_header(header or {}),
    }
    invoice_pattern = _template_invoice_number_pattern_from_value((header or {}).get("invoiceNumber"))
    if invoice_pattern:
        cfg.setdefault("rules", {})
        if isinstance(cfg.get("rules"), dict):
            cfg["rules"]["invoice_number_pattern"] = invoice_pattern

    if max_pages_pdf:
        cfg["max_pages_pdf"] = int(max_pages_pdf)
    if engine_used:
        eng = str(engine_used or "").replace("local_", "").strip()
        if eng and eng not in ("auto", "cloud_gemini"):
            cfg["preferred_local_engine"] = eng
            cfg.pop("preferred_cloud_engine", None)
        elif str(engine_used or "") == "cloud_gemini":
            cfg.setdefault("preferred_local_engine", "doctr")
            if not bool(cfg.get("force_cloud", False)):
                cfg.pop("preferred_cloud_engine", None)
            cfg["training_source_engine"] = "cloud_gemini"

    examples = cfg.get("header_trained_examples")
    if not isinstance(examples, list):
        examples = []
    examples.append(
        {
            "trained_at": _uk_now_iso(),
            "file_name": str(file_name or ""),
            "invoiceNumber": str((header or {}).get("invoiceNumber") or ""),
            "invoiceDate": str((header or {}).get("invoiceDate") or ""),
            "learned_header_aliases": learned_header_aliases,
        }
    )
    cfg["header_trained_examples"] = examples[-20:]
    training_meta = cfg.get("header_training") if isinstance(cfg.get("header_training"), dict) else {}
    training_meta["last_trained_at"] = _uk_now_iso()
    training_meta["training_count"] = int(training_meta.get("training_count") or 0) + 1
    cfg["header_training"] = training_meta

    keywords = []
    try:
        keywords = json.loads(tpl.get("match_keywords_json") or "[]") if tpl.get("match_keywords_json") else list(tpl.get("match_keywords") or [])
    except Exception:
        keywords = []
    keyword_extra = [
        supplier_name,
        str((header or {}).get("customerName") or "").strip(),
        str((header or {}).get("vatRegistrationNumber") or "").strip(),
        str((header or {}).get("invoiceNumber") or "").strip(),
    ]
    keywords.extend(_template_keywords(supplier_name, keyword_extra))
    dedup_keywords: List[str] = []
    seen_kw = set()
    for keyword in keywords:
        kw = _collapse_spaces(str(keyword or "").strip())
        if len(kw) < 3:
            continue
        key = kw.casefold()
        if key in seen_kw:
            continue
        seen_kw.add(key)
        dedup_keywords.append(kw)

    payload = {
        "template_id": str(tpl.get("template_id") or ""),
        "display_id": str(tpl.get("display_id") or ""),
        "supplier_name": supplier_name,
        "parser_type": parser_type,
        "vat_number": str(tpl.get("vat_number") or ""),
        "awrs_number": str(tpl.get("awrs_number") or ""),
        "requires_cloud": 1 if bool(cfg.get("force_cloud", False)) else 0,
        "match_keywords": dedup_keywords,
        "config": _template_enrich_supplier_config(
            cfg,
            supplier_name=supplier_name,
            parser_type=parser_type,
            raw_text=raw_text or "",
            header=header or {},
            items=[],
            doc_type="Purchase Invoice",
            aliases=dedup_keywords,
        ),
        "created_at": str(tpl.get("created_at") or ""),
    }
    tpl_id, saved, notes = _db_upsert_supplier_template_checked(payload)
    learned_count = sum(len(v or []) for v in learned_header_aliases.values())
    reviewed_count = sum(len(v or []) for v in (reviewed_header_aliases or {}).values())
    notes = list(notes or [])
    if reviewed_header_aliases is not None:
        notes.append(
            f"Saved reviewed header mapping with {reviewed_count} label(s); auto-learn suggested {learned_count}. "
            "Line-level template rules were not changed."
        )
    else:
        notes.append(f"Learned {learned_count} header alias(es). Line-level template rules were not changed.")
    return tpl_id, saved, notes


def _train_supplier_template_from_corrections(
    *,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    engine_used: str,
    existing_template: Optional[Dict[str, Any]] = None,
    max_pages_pdf: Optional[int] = None,
    header_aliases_override: Optional[Dict[str, List[str]]] = None,
) -> Tuple[str, bool, List[str]]:
    """Create/update a supplier template from Admin-corrected invoice data."""
    supplier_name = _normalise_supplier_name(str((header or {}).get("supplierName") or "").strip())
    items = _template_training_items(items)

    tpl = dict(existing_template or {})
    if not tpl:
        tpl = _find_existing_supplier_template_for_training(raw_text or "", header or {}, file_name or "")

    if _template_header_value_is_placeholder("supplierName", supplier_name):
        supplier_name = _template_supplier_name_from_hit(tpl)
    if not supplier_name:
        supplier_name = _guess_supplier_from_filename(file_name or "")
    supplier_name = _normalise_supplier_name(supplier_name or "")
    if _template_header_value_is_placeholder("supplierName", supplier_name):
        supplier_name = ""
    if not supplier_name:
        raise ValueError("Supplier name is required before training a template.")

    cfg = {}
    if tpl.get("config"):
        cfg = copy.deepcopy(tpl.get("config") or {})
    elif tpl.get("config_json"):
        try:
            cfg = json.loads(tpl.get("config_json") or "{}")
        except Exception:
            cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}

    parser_type = _detect_parser_type_from_supplier(supplier_name, str(tpl.get("parser_type") or ""))
    learned_header_aliases = _template_learn_header_aliases_from_text(header or {}, raw_text or "")
    reviewed_header_aliases = (
        _normalise_template_alias_config(header_aliases_override, _template_default_header_aliases())
        if isinstance(header_aliases_override, dict)
        else None
    )
    cfg["header_aliases"] = _template_merge_alias_config(
        cfg.get("header_aliases"),
        reviewed_header_aliases or learned_header_aliases,
        _template_default_header_aliases(),
    )
    cfg["trusted_header_values"] = {
        **(cfg.get("trusted_header_values") if isinstance(cfg.get("trusted_header_values"), dict) else {}),
        **_template_trusted_header_values_from_header(header or {}),
    }
    invoice_pattern = _template_invoice_number_pattern_from_value((header or {}).get("invoiceNumber"))
    if invoice_pattern:
        cfg.setdefault("rules", {})
        if isinstance(cfg.get("rules"), dict):
            cfg["rules"]["invoice_number_pattern"] = invoice_pattern
    cfg["line_aliases"] = _template_merge_alias_config(
        cfg.get("line_aliases"),
        {},
        _template_default_line_aliases(),
    )
    # The reviewed grid is authoritative. Persist its no-code row shape for
    # future Gemini calls as well as learning deterministic local rules. This
    # includes a single corrected row (for example "CHARGES"); previously only
    # multi-row grids updated Gemini guidance, so an old merged address/payment
    # description could keep returning after the user trained the correction.
    gemini_teacher_saved = _store_gemini_teacher_output_from_items(cfg, header or {}, items or [])

    old_vat_map = cfg.get("vat_map") or {}
    if isinstance(old_vat_map, str):
        try:
            old_vat_map = json.loads(old_vat_map)
        except Exception:
            old_vat_map = {}
    if not isinstance(old_vat_map, dict):
        old_vat_map = {}
    learned_vat_map = _derive_vat_map_from_items(items or [])
    cfg["vat_map"] = {
        **{str(k).strip().upper(): float(v) for k, v in old_vat_map.items() if str(k).strip()},
        **{str(k).strip().upper(): float(v) for k, v in learned_vat_map.items() if str(k).strip()},
    }
    learned_agent = _learn_template_agent_from_corrections(items or [], raw_text or "")
    if learned_agent:
        cfg["template_agent"] = {
            **(cfg.get("template_agent") if isinstance(cfg.get("template_agent"), dict) else {}),
            **learned_agent,
        }
    learned_table_profile = _template_table_profile_from_text_and_items(items or [], raw_text or "")
    if learned_table_profile:
        cfg["table_profile"] = {
            **(cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}),
            **learned_table_profile,
        }

    if max_pages_pdf:
        cfg["max_pages_pdf"] = int(max_pages_pdf)
    if engine_used:
        eng = str(engine_used or "").replace("local_", "").strip()
        if eng and eng not in ("auto", "cloud_gemini"):
            cfg["preferred_local_engine"] = eng
            cfg.pop("preferred_cloud_engine", None)
        elif str(engine_used or "") == "cloud_gemini":
            cfg.setdefault("preferred_local_engine", "doctr")
            if not bool(cfg.get("force_cloud", False)):
                cfg.pop("preferred_cloud_engine", None)
            cfg["training_source_engine"] = "cloud_gemini"

    examples = cfg.get("trained_examples")
    if not isinstance(examples, list):
        examples = []
    examples.append(
        {
            "trained_at": _uk_now_iso(),
            "file_name": str(file_name or ""),
            "invoiceNumber": str((header or {}).get("invoiceNumber") or ""),
            "invoiceDate": str((header or {}).get("invoiceDate") or ""),
            "line_schema": _template_line_schema_from_items(items or []),
            "learned_header_aliases": learned_header_aliases,
            "learned_template_agent": bool(learned_agent),
            "learned_table_profile": bool(learned_table_profile),
        }
    )
    cfg["trained_examples"] = examples[-20:]
    training_meta = cfg.get("training") if isinstance(cfg.get("training"), dict) else {}
    training_meta["last_trained_at"] = _uk_now_iso()
    training_meta["training_count"] = int(training_meta.get("training_count") or 0) + 1
    cfg["training"] = training_meta

    keywords = []
    try:
        keywords = json.loads(tpl.get("match_keywords_json") or "[]") if tpl.get("match_keywords_json") else list(tpl.get("match_keywords") or [])
    except Exception:
        keywords = []
    keyword_extra = [
        supplier_name,
        str((header or {}).get("customerName") or "").strip(),
        str((header or {}).get("vatRegistrationNumber") or "").strip(),
    ]
    keywords.extend(_template_keywords(supplier_name, keyword_extra))
    dedup_keywords: List[str] = []
    seen_kw = set()
    for keyword in keywords:
        kw = _collapse_spaces(str(keyword or "").strip())
        if len(kw) < 3:
            continue
        key = kw.casefold()
        if key in seen_kw:
            continue
        seen_kw.add(key)
        dedup_keywords.append(kw)

    payload = {
        "template_id": str(tpl.get("template_id") or ""),
        "display_id": str(tpl.get("display_id") or ""),
        "supplier_name": supplier_name,
        "parser_type": parser_type,
        "vat_number": str(tpl.get("vat_number") or ""),
        "awrs_number": str(tpl.get("awrs_number") or ""),
        "requires_cloud": 1 if bool(cfg.get("force_cloud", False)) else 0,
        "match_keywords": dedup_keywords,
        "config": _template_enrich_supplier_config(
            cfg,
            supplier_name=supplier_name,
            parser_type=parser_type,
            raw_text=raw_text or "",
            header=header or {},
            items=items or [],
            doc_type="Purchase Invoice",
            aliases=dedup_keywords,
        ),
        "created_at": str(tpl.get("created_at") or ""),
    }
    tpl_id, saved, notes = _db_upsert_supplier_template_checked(payload)
    learned_count = sum(len(v or []) for v in learned_header_aliases.values())
    reviewed_count = sum(len(v or []) for v in (reviewed_header_aliases or {}).values())
    notes = list(notes or [])
    agent_note = "line parser learned" if learned_agent else "line parser not learned"
    profile_note = "table profile learned" if learned_table_profile else "table profile not learned"
    if reviewed_header_aliases is not None:
        notes.append(
            f"Saved reviewed header mapping with {reviewed_count} label(s); auto-learn suggested {learned_count}. "
            f"Also learned {len(learned_vat_map)} VAT mapping(s), {len(items or [])} line row(s), {agent_note}, {profile_note}."
        )
    else:
        notes.append(f"Learned {learned_count} header alias(es), {len(learned_vat_map)} VAT mapping(s), {len(items or [])} line row(s), {agent_note}, {profile_note}.")
    if gemini_teacher_saved:
        notes.append("Saved the reviewed line grid as Gemini guidance; future Gemini fallback must use these corrected row descriptions.")
    if learned_agent:
        region = learned_agent.get("table_region") if isinstance(learned_agent.get("table_region"), dict) else {}
        if region.get("start_after_sample") or region.get("stop_before_sample"):
            notes.append(
                "Line table region learned"
                + (f"; starts after: {region.get('start_after_sample')}" if region.get("start_after_sample") else "")
                + (f"; stops before: {region.get('stop_before_sample')}" if region.get("stop_before_sample") else "")
            )
    return tpl_id, saved, notes


def _supplier_batch_training_groups(batch: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
    groups: Dict[str, List[Dict[str, Any]]] = {}
    for res in batch or []:
        if not isinstance(res, dict) or res.get("error"):
            continue
        if not _is_purchase_like_doc_type(str(res.get("doc_type") or "")):
            continue
        header = res.get("header") or {}
        supplier = _normalise_supplier_name(str(header.get("supplierName") or "").strip())
        if _template_header_value_is_placeholder("supplierName", supplier):
            supplier = _guess_supplier_from_filename(str(res.get("file") or ""))
        supplier = _normalise_supplier_name(supplier or "")
        if not supplier:
            continue
        groups.setdefault(supplier, []).append(res)
    return groups


def _batch_train_supplier_template_from_results(
    *,
    supplier_name: str,
    results: List[Dict[str, Any]],
    max_pages_pdf: Optional[int] = None,
    require_applied_edits: bool = True,
) -> Tuple[str, bool, List[str]]:
    selected: List[Dict[str, Any]] = []
    for res in results or []:
        if not isinstance(res, dict) or res.get("error"):
            continue
        if not _is_purchase_like_doc_type(str(res.get("doc_type") or "")):
            continue
        if require_applied_edits and not bool(res.get("items_edited")):
            continue
        header = res.get("header") or {}
        sup = _normalise_supplier_name(str(header.get("supplierName") or "").strip())
        if not sup:
            sup = _normalise_supplier_name(_guess_supplier_from_filename(str(res.get("file") or "")) or "")
        if sup.casefold() != _normalise_supplier_name(supplier_name).casefold():
            continue
        if not (res.get("items") or []):
            continue
        selected.append(res)

    if not selected:
        raise ValueError("No matching corrected purchase invoices with line items were found for batch training.")

    base = selected[0]
    base_header = copy.deepcopy(base.get("header") or {})
    base_header["supplierName"] = _normalise_supplier_name(supplier_name)

    merged_items: List[Dict[str, Any]] = []
    raw_parts: List[str] = []
    invoice_numbers: List[str] = []
    for idx, res in enumerate(selected, start=1):
        hdr = res.get("header") or {}
        inv_no = str(hdr.get("invoiceNumber") or "").strip()
        if inv_no:
            invoice_numbers.append(inv_no)
        raw_parts.append(
            "\n".join(
                x
                for x in (
                    f"### TRAINING EXAMPLE {idx}",
                    _template_training_text_from_result(res, str(res.get("file") or "")),
                )
                if str(x or "").strip()
            )
        )
        for it in _template_training_items(copy.deepcopy(res.get("items") or [])):
            if not isinstance(it, dict):
                continue
            it["_training_file"] = str(res.get("file") or "")
            if inv_no:
                it["_training_invoice"] = inv_no
            merged_items.append(it)

    raw_text = "\n\n".join(part for part in raw_parts if str(part or "").strip())
    existing_tpl = _find_existing_supplier_template_for_training(raw_text, base_header, str(base.get("file") or ""))
    tpl_id, saved, notes = _train_supplier_template_from_corrections(
        header=base_header,
        items=_recalc_items(_template_training_items(copy.deepcopy(merged_items))),
        raw_text=raw_text,
        file_name=f"batch:{supplier_name}",
        engine_used="local_doctr",
        existing_template=existing_tpl,
        max_pages_pdf=max_pages_pdf,
    )
    notes = list(notes or [])
    notes.append(
        f"Batch trained from {len(selected)} invoice(s), {len(merged_items)} line row(s), "
        f"{len(set(invoice_numbers))} invoice number(s). Preferred local engine: DocTR."
    )
    return tpl_id, saved, notes


def _evaluate_supplier_template_on_results(
    template: Dict[str, Any],
    results: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    rows: List[Dict[str, Any]] = []
    if not isinstance(template, dict) or not template:
        return rows
    for res in results or []:
        if not isinstance(res, dict) or res.get("error"):
            continue
        if not _is_purchase_like_doc_type(str(res.get("doc_type") or "")):
            continue
        raw_text = _template_training_text_from_result(res, str(res.get("file") or ""))
        try:
            local_data = LocalInvoiceParser.parse(raw_text, str(res.get("doc_type") or "Purchase Invoice"))
        except Exception:
            local_data = {}
        test_header = copy.deepcopy(local_data.get("header") or {})
        test_items = copy.deepcopy(local_data.get("items") or [])
        try:
            test_header, test_items, _template_used = _apply_trained_supplier_template_agent(
                test_header,
                test_items,
                raw_text,
                template,
            )
            test_header, test_items = _apply_supplier_template_rules(test_header, test_items, template)
            test_items = _recalc_items_for_engine(copy.deepcopy(test_items or []), "local_doctr")
            try:
                _fill_header_totals_from_items(test_header, test_items)
            except Exception:
                pass
            test_header = _apply_reviewed_header_teacher_values(test_header, res.get("header") or {})
            conf = _assess_extraction_confidence(
                test_header,
                test_items,
                str(res.get("doc_type") or ""),
                raw_text=raw_text,
                engine_used="local_doctr_template_test",
            )
            rows.append(
                {
                    "file": str(res.get("file") or ""),
                    "invoiceNumber": str(test_header.get("invoiceNumber") or ""),
                    "score": int(conf.get("score") or 0),
                    "bucket": str(conf.get("bucket") or ""),
                    "lineRows": len(test_items or []),
                    "reasons": " ".join(str(x) for x in (conf.get("reasons") or [])[:3]),
                }
            )
        except Exception as e:
            rows.append(
                {
                    "file": str(res.get("file") or ""),
                    "invoiceNumber": "",
                    "score": 0,
                    "bucket": "error",
                    "lineRows": 0,
                    "reasons": repr(e),
                }
            )
    return rows


def _train_local_doctr_template_from_teacher_result(
    *,
    res: Dict[str, Any],
    header: Dict[str, Any],
    edited_items: List[Dict[str, Any]],
    file_name: str,
    doc_type: str,
    settings: Dict[str, Any],
) -> Tuple[str, bool, List[str], Dict[str, Any]]:
    """Use a reviewed cloud/teacher extraction to strengthen the local DocTR template."""
    raw_train_text = _template_training_text_from_result(res, file_name)
    teacher_items = _recalc_items(_template_training_items(copy.deepcopy(edited_items or [])))
    try:
        teacher_items = _append_missing_reconciliation_charge_items(header, teacher_items, raw_train_text)
    except Exception:
        pass
    existing_tpl = _find_existing_supplier_template_for_training(raw_train_text, header, file_name)
    teacher_agent = _learn_template_agent_from_corrections(teacher_items, raw_train_text)
    teacher_table_profile = _template_table_profile_from_text_and_items(teacher_items, raw_train_text)
    tpl_id, saved, notes = _train_supplier_template_from_corrections(
        header=header,
        items=teacher_items,
        raw_text=raw_train_text,
        file_name=file_name,
        engine_used="cloud_gemini",
        existing_template=existing_tpl,
        max_pages_pdf=int((settings or {}).get("ocr_max_pages", 0) or 0) or None,
    )
    # Make the teacher relationship explicit and keep runtime local-first.
    try:
        tpl = _db_get_template("supplier_templates", tpl_id) or {}
        cfg = copy.deepcopy(tpl.get("config") or {})
        if not isinstance(cfg, dict):
            try:
                cfg = json.loads(tpl.get("config_json") or "{}")
            except Exception:
                cfg = {}
        if not isinstance(cfg, dict):
            cfg = {}
        cfg["preferred_local_engine"] = "doctr"
        cfg.pop("preferred_cloud_engine", None)
        cfg["training_source_engine"] = "cloud_gemini"
        teacher_meta = cfg.get("teacher_learning") if isinstance(cfg.get("teacher_learning"), dict) else {}
        examples = teacher_meta.get("examples") if isinstance(teacher_meta.get("examples"), list) else []
        matched_rows = int((teacher_agent or {}).get("trained_rows") or 0)
        table_profile_rows = int((teacher_table_profile or {}).get("matched_rows") or 0)
        examples.append(
            {
                "trained_at": _uk_now_iso(),
                "teacher_engine": str(res.get("engine") or "cloud_gemini"),
                "target_local_engine": "local_doctr",
                "file_name": str(file_name or ""),
                "invoiceNumber": str((header or {}).get("invoiceNumber") or ""),
                "line_rows": len(teacher_items or []),
                "line_rows_matched_to_local_text": matched_rows,
                "line_agent_learned": bool(teacher_agent),
                "table_profile_learned": bool(teacher_table_profile),
                "table_profile_rows_matched": table_profile_rows,
                "reconciliation_diff": _template_agent_reconciliation_diff(header, teacher_items, raw_train_text),
            }
        )
        teacher_meta["examples"] = examples[-20:]
        teacher_meta["last_teacher_engine"] = str(res.get("engine") or "cloud_gemini")
        teacher_meta["target_local_engine"] = "local_doctr"
        teacher_meta["last_trained_at"] = _uk_now_iso()
        teacher_meta["last_reviewed_header"] = _template_reviewed_header_values_from_header(header or {})
        cfg["teacher_learning"] = teacher_meta
        cfg.setdefault("training", {})
        if isinstance(cfg.get("training"), dict):
            cfg["training"]["local_doctr_teacher_promotions"] = int(cfg["training"].get("local_doctr_teacher_promotions") or 0) + 1
        _db_patch_supplier_template_config(tpl_id, cfg)
    except Exception as e:
        notes = list(notes or [])
        notes.append(f"Teacher metadata patch skipped: {e}")

    tpl_after = _db_get_template("supplier_templates", tpl_id) or existing_tpl or {}
    test_header: Dict[str, Any] = {}
    test_items: List[Dict[str, Any]] = []
    template_used = False
    conf: Dict[str, Any] = {"score": 0, "bucket": "not_tested", "reasons": ["Local DocTR template test was not run."]}
    local_diff = 999999.0
    auto_uses_local = False
    line_agent_learned = bool(teacher_agent)
    matched_rows = int((teacher_agent or {}).get("trained_rows") or 0)
    table_profile_learned = bool(teacher_table_profile)
    table_profile_rows = int((teacher_table_profile or {}).get("matched_rows") or 0)
    try:
        local_data = LocalInvoiceParser.parse(raw_train_text, str(doc_type or "Purchase Invoice"))
        test_header = copy.deepcopy(local_data.get("header") or {})
        test_items = copy.deepcopy(local_data.get("items") or [])
        test_header, test_items, template_used = _apply_trained_supplier_template_agent(
            test_header,
            test_items,
            raw_train_text,
            tpl_after,
        )
        test_header, test_items = _apply_supplier_template_rules(test_header, test_items, tpl_after)
        test_items = _recalc_items_for_engine(copy.deepcopy(test_items or []), "local_doctr")
        try:
            _fill_header_totals_from_items(test_header, test_items)
        except Exception:
            pass
        test_header = _apply_reviewed_header_teacher_values(test_header, header or {})
        conf = _assess_extraction_confidence(
            test_header,
            test_items,
            str(doc_type or "Purchase Invoice"),
            raw_text=raw_train_text,
            engine_used="local_doctr_template_test",
        )
        local_diff = _template_agent_reconciliation_diff(test_header or header, test_items, raw_train_text)
        cfg_after = tpl_after.get("config") if isinstance(tpl_after.get("config"), dict) else cfg if "cfg" in locals() else {}
        local_confidence_threshold = int((settings or {}).get("auto_cloud_fallback_threshold", 65) or 65)
        local_reconciliation_limit = max(
            1.0,
            max(
                abs(_safe_float((header or {}).get("totalNet"))),
                abs(_safe_float((header or {}).get("totalGross"))),
            ) * 0.02,
        )
        auto_uses_local = bool(
            template_used
            and bool(test_items)
            and int(conf.get("score") or 0) >= local_confidence_threshold
            and local_diff <= local_reconciliation_limit
            and str((cfg_after or {}).get("preferred_local_engine") or "").strip().lower() == "doctr"
            and not bool((cfg_after or {}).get("force_cloud"))
            and not bool(tpl_after.get("requires_cloud"))
        )
    except Exception as e:
        conf = {"score": 0, "bucket": "error", "reasons": [repr(e)]}

    try:
        _db_patch_supplier_template_config(
            tpl_id,
            {
                "local_learning_verified": bool(auto_uses_local),
                "local_learning_last_score": int(conf.get("score") or 0),
                "local_learning_last_diff": round(float(local_diff), 2) if local_diff < 999999.0 else local_diff,
                "local_learning_verified_at": _uk_now_iso(),
            },
        )
    except Exception as e:
        notes = list(notes or [])
        notes.append(f"Local verification state could not be saved: {e}")

    test_summary = {
        "template_used": bool(template_used),
        "score": int(conf.get("score") or 0),
        "bucket": str(conf.get("bucket") or ""),
        "line_rows": len(test_items or []),
        "teacher_line_rows": len(teacher_items or []),
        "teacher_rows_matched_to_local_text": matched_rows,
        "line_agent_learned": bool(line_agent_learned),
        "table_profile_learned": bool(table_profile_learned),
        "table_profile_rows_matched": int(table_profile_rows),
        "reconciliation_diff": round(float(local_diff or 0.0), 2) if local_diff < 999999.0 else local_diff,
        "auto_uses_local_next": bool(
            auto_uses_local
            and len(test_items or []) > 0
            and local_diff <= max(
                1.0,
                max(
                    abs(_safe_float((header or {}).get("totalNet"))),
                    abs(_safe_float((header or {}).get("totalGross"))),
                ) * 0.02,
            )
        ),
        "preferred_local_engine": "doctr",
        "confidence_reasons": [str(x) for x in (conf.get("reasons") or [])[:4]],
    }
    notes = list(notes or [])
    notes.append("Gemini teacher promoted to local DocTR template: preferred_local_engine=doctr.")
    if table_profile_learned:
        notes.append(
            f"Table profile learned: header='{str(teacher_table_profile.get('header_sample') or '')[:120]}', "
            f"matched_rows={table_profile_rows}."
        )
    if not line_agent_learned and not table_profile_learned:
        notes.append(
            "Header learning saved, but line learning did not lock on: the reviewed rows could not be matched back to local OCR text. "
            "Run local DocTR on the invoice, review the line grid/raw row text, then Teach local DocTR again."
        )
    notes.append(
        "Local DocTR template retest: "
        f"score={test_summary['score']}/100, rows={test_summary['line_rows']}, "
        f"diff={test_summary['reconciliation_diff']}, line_parser_used={test_summary['template_used']}."
    )
    notes.append(
        "Auto next time: "
        + (
            "will try local DocTR first for this matched template."
            if test_summary["auto_uses_local_next"]
            else "local preference is saved, but cloud fallback may still be needed until local line rows are learned."
        )
    )
    return tpl_id, saved, notes, test_summary


def _save_supplier_charge_section_rule(
    *,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str = "",
    doc_type: str = "Purchase Invoice",
    engine_used: str = "",
    section_heading: str,
    row_label_regex: str = "",
    stop_before_regex: str = "",
) -> Tuple[str, bool, List[str]]:
    """Save a user-defined secondary charge/fee section rule into supplier template config."""
    section_heading = _collapse_spaces(section_heading)
    if not section_heading:
        raise ValueError("Section heading is required.")
    if not stop_before_regex:
        stop_before_regex = r"\b(Total|Subtotal|VAT|Invoice Total|Amount Due|Balance Due)\b"
    if not row_label_regex:
        row_label_regex = (
            r"\b(fuel(?:\s+and\s+energy)?\s+charge|energy\s+charge|carriage\s+charge|"
            r"delivery\s+charge|service\s+charge|surcharge|freight|shipping|handling)\b"
        )
    try:
        re.compile(row_label_regex, flags=re.I)
    except Exception as e:
        raise ValueError(f"Invalid row label regex: {e}")
    try:
        re.compile(stop_before_regex, flags=re.I)
    except Exception as e:
        raise ValueError(f"Invalid stop-before regex: {e}")

    tpl = _find_existing_supplier_template_for_training(raw_text, header, file_name)
    notes: List[str] = []
    if not tpl:
        tpl_id, _saved, train_notes = _train_supplier_template_from_corrections(
            header=header,
            items=items,
            raw_text=raw_text,
            file_name=file_name,
            doc_type=doc_type,
            engine_used=engine_used,
        )
        notes.extend(train_notes or [])
        tpl = _db_get_template("supplier_templates", tpl_id) or {}
    if not tpl:
        raise ValueError("No supplier template found or created. Train the supplier template first.")

    cfg = copy.deepcopy(tpl.get("config") or {})
    if not isinstance(cfg, dict):
        try:
            cfg = json.loads(tpl.get("config_json") or "{}")
        except Exception:
            cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}

    rule = {
        "name": section_heading[:80],
        "enabled": True,
        "start_after_sample": section_heading[:220],
        "start_after_regex": rf"^\s*{re.escape(section_heading)}\s*$",
        "stop_before_regex": stop_before_regex,
        "row_label_regex": row_label_regex,
        "row_type": "charge",
        "quantity": 0,
        "line_net_from": "last_number",
        "vat_code_from": "token_before_amount",
        "description_from": "between_code_and_amount",
        "user_defined": True,
        "learned_at": _uk_now_iso(),
    }
    existing_rules = cfg.get("charge_sections") if isinstance(cfg.get("charge_sections"), list) else []
    merged_rules: List[Dict[str, Any]] = []
    replaced = False
    for existing in existing_rules:
        if not isinstance(existing, dict):
            continue
        same_name = str(existing.get("name") or "").strip().lower() == section_heading.lower()
        same_start = str(existing.get("start_after_regex") or "").strip() == rule["start_after_regex"]
        if same_name or same_start:
            merged_rules.append({**existing, **rule})
            replaced = True
        else:
            merged_rules.append(existing)
    if not replaced:
        merged_rules.append(rule)
    cfg["charge_sections"] = merged_rules[-20:]

    profile = cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}
    if isinstance(profile, dict):
        profile_rules = profile.get("charge_sections") if isinstance(profile.get("charge_sections"), list) else []
        profile["charge_sections"] = [r for r in profile_rules if isinstance(r, dict) and str(r.get("name") or "").strip().lower() != section_heading.lower()]
        profile["charge_sections"].append(rule)
        cfg["table_profile"] = profile

    tpl_id = str(tpl.get("template_id") or "").strip()
    _db_patch_supplier_template_config(tpl_id, cfg)
    notes.append(
        f"Saved charge section rule '{section_heading}' to supplier template "
        f"{str(tpl.get('display_id') or tpl_id).strip()}."
    )
    return tpl_id, True, notes


def _gemini_json_for_template_rule(
    *,
    settings: Dict[str, Any],
    instruction: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    doc_type: str,
    existing_template: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Use Gemini to convert a user English instruction into a template config patch."""
    instruction = str(instruction or "").strip()
    if not instruction:
        raise ValueError("Enter an English rule first.")
    api_key = _get_google_api_key(settings or {})
    if not api_key:
        raise ValueError("Gemini API key is not configured.")
    model_name = str((settings or {}).get("gemini_model") or "gemini-3.6-flash")
    existing_cfg = {}
    if isinstance(existing_template, dict):
        existing_cfg = copy.deepcopy(existing_template.get("config") or {})
        if not isinstance(existing_cfg, dict) and existing_template.get("config_json"):
            try:
                existing_cfg = json.loads(existing_template.get("config_json") or "{}")
            except Exception:
                existing_cfg = {}
    if not isinstance(existing_cfg, dict):
        existing_cfg = {}
    compact_items = []
    for it in _template_training_items(items or [])[:30]:
        compact_items.append(
            {
                "description": str(it.get("description") or ""),
                "qty": _safe_float(it.get("qty") or it.get("quantity")),
                "unitPrice": _safe_float(it.get("unitPrice")),
                "discount": _safe_float(it.get("discount")),
                "lineNet": _safe_float(it.get("lineNet")),
                "vatCode": str(it.get("vatCode") or ""),
                "vatRate": _safe_float(it.get("vatRate")),
                "rowTag": str(it.get("rowTag") or ""),
            }
        )
    prompt = f"""
You are DocMate's supplier-template rule assistant.
Convert the user's English extraction instruction into a small JSON patch for a supplier template.

Return JSON only. Do not include markdown.

Allowed top-level keys:
- notes: array of short strings
- gemini_supplier_instructions: array of English instructions to send to Gemini on future extraction for this supplier
- line_aliases: object mapping DocMate line fields to printed column names/aliases
- header_aliases: object mapping DocMate header fields to printed labels/aliases
- table_profile: object. You may include header_fields and columns.
- charge_sections: array of section rules
- rules: object for simple behavior flags

Supported line fields include:
description, code, barcode, qty, unitSize, casePack, unitPrice, discount, lineNet, vatCode, vatRate, vatAmount, lineGross, stdRrp, por.

For extra useful table columns, prefer an existing supported field if it matches, e.g. discount -> discount.
For charge/fee/surcharge sections, use charge_sections rules with:
name, enabled, start_after_regex, stop_before_regex, row_label_regex, row_type, quantity, line_net_from, vat_code_from, description_from.
For invoices where the reviewed line examples prove there is exactly one no-code line item and the printed invoice summary is the reliable source of line totals, set rules.single_line_no_code_use_header_totals=true and rules.line_match_strategy="description_anchor". Use this only when the reviewed line count is one, the row has a description but no product code, and the row total equals the printed invoice total.

Use safe regex. Do not produce broad regex that captures totals, addresses, bank details, payment terms, or page headers.
Do not overwrite existing template config unless the instruction requires it.

User instruction:
{instruction}

Invoice file: {file_name}
Document type: {doc_type}
Supplier: {str((header or {}).get("supplierName") or "")}
Header JSON:
{json.dumps(header or {}, ensure_ascii=False, default=str)[:3000]}

Reviewed line examples:
{json.dumps(compact_items, ensure_ascii=False, default=str)[:5000]}

Existing template config excerpt:
{json.dumps(existing_cfg, ensure_ascii=False, default=str)[:5000]}

OCR/text excerpt:
{str(raw_text or "")[:8000]}
""".strip()

    def _clean_patch(out: Dict[str, Any]) -> Dict[str, Any]:
        if not isinstance(out, dict):
            raise ValueError("Gemini did not return a JSON object.")
        allowed = {"notes", "gemini_supplier_instructions", "line_aliases", "header_aliases", "table_profile", "charge_sections", "rules"}
        patch = {k: copy.deepcopy(v) for k, v in out.items() if k in allowed}
        if isinstance(patch.get("line_aliases"), dict):
            patch["line_aliases"] = _normalise_template_alias_config(patch.get("line_aliases"), _template_default_line_aliases())
        if isinstance(patch.get("header_aliases"), dict):
            patch["header_aliases"] = _normalise_template_alias_config(patch.get("header_aliases"), _template_default_header_aliases())
        if isinstance(patch.get("charge_sections"), list):
            clean_sections = []
            for sec in patch.get("charge_sections") or []:
                if not isinstance(sec, dict):
                    continue
                sec = copy.deepcopy(sec)
                sec.setdefault("enabled", True)
                sec.setdefault("row_type", "charge")
                sec.setdefault("quantity", 0)
                sec.setdefault("line_net_from", "last_number")
                sec.setdefault("vat_code_from", "token_before_amount")
                sec.setdefault("description_from", "between_code_and_amount")
                for regex_key in ("start_after_regex", "stop_before_regex", "row_label_regex"):
                    if str(sec.get(regex_key) or "").strip():
                        re.compile(str(sec.get(regex_key)), flags=re.I)
                clean_sections.append(sec)
            patch["charge_sections"] = clean_sections
        patch.setdefault("notes", [])
        notes = [str(x).strip() for x in (patch.get("notes") or []) if str(x).strip()]
        notes.append("Gemini converted the English rule into a supplier-template JSON patch. Review before saving.")
        patch["notes"] = list(dict.fromkeys(notes))[:10]
        return patch

    last_errors: List[str] = []
    try:
        try:
            from google import genai  # type: ignore
        except Exception:
            import google.genai as genai  # type: ignore
        from google.genai import types  # type: ignore

        try:
            client = genai.Client(api_key=api_key, http_options=types.HttpOptions(api_version="v1"))
        except Exception:
            client = genai.Client(api_key=api_key)
        resolved_model = _resolve_gemini_model_google_genai(client, model_name)
        resp = client.models.generate_content(
            model=resolved_model,
            contents=[prompt],
            config={"temperature": 0},
        )
        return _clean_patch(_parse_json_from_model(getattr(resp, "text", "") or ""))
    except Exception as e:
        last_errors.append(str(e))
        try:
            _log_event(f"Gemini English rule helper google-genai failed: {e}", file_name=file_name)
        except Exception:
            pass

    try:
        import google.generativeai as genai  # type: ignore

        genai.configure(api_key=api_key)
        resolved_model = _resolve_gemini_model_google_generativeai(genai, model_name)
        model = genai.GenerativeModel(resolved_model or model_name)
        resp = model.generate_content([prompt], generation_config={"temperature": 0})
        return _clean_patch(_parse_json_from_model(getattr(resp, "text", "") or ""))
    except Exception as e:
        last_errors.append(str(e))
        try:
            _log_event(f"Gemini English rule helper google-generativeai failed: {e}", file_name=file_name)
        except Exception:
            pass
    raise RuntimeError("Gemini rule suggestion failed: " + " | ".join(last_errors[-2:]))


def _gemini_suggest_header_aliases(
    *,
    settings: Dict[str, Any],
    header: Dict[str, Any],
    raw_text: str,
    file_name: str,
    doc_type: str,
    existing_aliases: Optional[Dict[str, List[str]]] = None,
) -> Dict[str, Any]:
    """Ask Gemini for reviewable header label mappings only."""
    api_key = _get_google_api_key(settings or {})
    if not api_key:
        raise ValueError("Gemini API key is not configured.")
    model_name = str((settings or {}).get("gemini_model") or "gemini-3.6-flash")
    fields = [
        "supplierName",
        "customerName",
        "customerNo",
        "customerPONumber",
        "accountNumber",
        "invoiceNumber",
        "invoiceDate",
        "totalNet",
        "totalVat",
        "totalGross",
    ]
    reviewed_header = {field: (header or {}).get(field) for field in fields if (header or {}).get(field) not in (None, "")}
    prompt = f"""
You are DocMate's supplier header-mapping teacher.

Task: infer the printed invoice labels that map to DocMate header fields.
Return JSON only. Do not include markdown.

Return shape:
{{
  "header_aliases": {{
    "invoiceNumber": ["INVOICE NO"],
    "invoiceDate": ["DATE"],
    "customerName": ["INVOICE TO"]
  }},
  "notes": ["short explanation"]
}}

Rules:
- Return printed labels only, never extracted values.
- Good labels are words printed next to or above the value, e.g. DATE, INVOICE NO, INVOICE TO.
- Do not return generic document title words like INVOICE for supplierName.
- Do not return fragments like "In", "No", "Number" alone.
- Do not map customer labels to supplierName.
- If unsure for a field, omit that field.
- Prefer exact capitalization as printed on the invoice.

Invoice file: {file_name}
Document type: {doc_type}
Reviewed correct header values:
{json.dumps(reviewed_header, ensure_ascii=False, default=str)}

Existing supplier-specific aliases:
{json.dumps(existing_aliases or {}, ensure_ascii=False, default=str)[:3000]}

OCR/text excerpt:
{str(raw_text or "")[:10000]}
""".strip()

    def _clean(out: Dict[str, Any]) -> Dict[str, Any]:
        if not isinstance(out, dict):
            raise ValueError("Gemini did not return a JSON object.")
        aliases_raw = out.get("header_aliases")
        if not isinstance(aliases_raw, dict):
            raise ValueError("Gemini did not return header_aliases.")
        aliases = _template_alias_config_without_defaults(
            _normalise_template_alias_config(aliases_raw, {}),
            _template_default_header_aliases(),
        )
        aliases = {
            field: values
            for field, values in aliases.items()
            if field in fields and values
        }
        notes = [str(x).strip() for x in (out.get("notes") or []) if str(x).strip()] if isinstance(out.get("notes"), list) else []
        return {
            "header_aliases": aliases,
            "notes": notes[:8] or ["Gemini suggested reviewable header label mappings."],
        }

    last_errors: List[str] = []
    try:
        try:
            from google import genai  # type: ignore
        except Exception:
            import google.genai as genai  # type: ignore
        from google.genai import types  # type: ignore

        try:
            client = genai.Client(api_key=api_key, http_options=types.HttpOptions(api_version="v1"))
        except Exception:
            client = genai.Client(api_key=api_key)
        resolved_model = _resolve_gemini_model_google_genai(client, model_name)
        resp = client.models.generate_content(
            model=resolved_model,
            contents=[prompt],
            config={"temperature": 0},
        )
        return _clean(_parse_json_from_model(getattr(resp, "text", "") or ""))
    except Exception as e:
        last_errors.append(str(e))
        try:
            _log_event(f"Gemini header mapping helper google-genai failed: {e}", file_name=file_name)
        except Exception:
            pass

    try:
        import google.generativeai as genai  # type: ignore

        genai.configure(api_key=api_key)
        resolved_model = _resolve_gemini_model_google_generativeai(genai, model_name)
        model = genai.GenerativeModel(resolved_model or model_name)
        resp = model.generate_content([prompt], generation_config={"temperature": 0})
        return _clean(_parse_json_from_model(getattr(resp, "text", "") or ""))
    except Exception as e:
        last_errors.append(str(e))
        try:
            _log_event(f"Gemini header mapping helper google-generativeai failed: {e}", file_name=file_name)
        except Exception:
            pass
    raise RuntimeError("Gemini header mapping suggestion failed: " + " | ".join(last_errors[-2:]))


def _store_gemini_teacher_output_from_items(
    cfg: Dict[str, Any],
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
) -> bool:
    """Persist reviewed no-code output as Gemini teacher guidance."""
    if not isinstance(cfg, dict):
        return False
    teacher_rows = _template_training_items(items or [])
    teacher_no_code_rows = [
        it for it in teacher_rows
        if isinstance(it, dict)
        and str(it.get("description") or "").strip()
        and not str(it.get("code") or "").strip()
    ]
    if not teacher_rows or len(teacher_no_code_rows) != len(teacher_rows):
        return False

    cfg.setdefault("rules", {})
    if not isinstance(cfg.get("rules"), dict):
        cfg["rules"] = {}
    cfg["rules"].pop("single_line_no_code_use_header_totals", None)
    cfg["rules"].pop("single_line_use_header_totals", None)
    cfg["rules"]["allow_missing_code"] = True
    cfg["rules"]["line_match_strategy"] = "description_anchor"
    cfg["rules"]["preserve_teacher_line_rows"] = True

    teacher_fields = sorted(
        {
            str(k)
            for it in teacher_rows
            if isinstance(it, dict)
            for k, v in it.items()
            if str(k or "").strip()
            and v not in (None, "")
            and not str(k).startswith("_")
        }
    )
    teacher_descriptions = [
        _collapse_spaces(str(it.get("description") or ""))[:160]
        for it in teacher_rows[:12]
        if isinstance(it, dict) and str(it.get("description") or "").strip()
    ]
    cfg["gemini_teacher_output"] = {
        "learned_at": _uk_now_iso(),
        "source": "reviewed_line_grid",
        "row_count": len(teacher_rows),
        "no_code_rows": len(teacher_no_code_rows),
        "fields": teacher_fields[:40],
        "descriptions": teacher_descriptions,
        "header_total_net": round(_safe_float((header or {}).get("totalNet")), 2),
        "header_total_vat": round(_safe_float((header or {}).get("totalVat")), 2),
        "header_total_gross": round(_safe_float((header or {}).get("totalGross")), 2),
    }

    existing_instr = cfg.get("gemini_supplier_instructions") if isinstance(cfg.get("gemini_supplier_instructions"), list) else []
    generated_prefix = "For this supplier, preserve the reviewed line structure:"
    existing_instr = [
        str(x).strip()
        for x in existing_instr
        if str(x).strip()
        and not str(x).strip().startswith(generated_prefix)
        and not str(x).strip().startswith("For this supplier, preserve the reviewed Gemini teacher line structure:")
    ]
    row_word = "row" if len(teacher_rows) == 1 else "separate line rows"
    teacher_instruction = (
        f"{generated_prefix} return about {len(teacher_rows)} {row_word} using the reviewed descriptions. "
        "Do not merge payment terms, addresses, email/contact text, or other header text into a line description."
    )
    if len(teacher_rows) > 1:
        teacher_instruction += " Do not collapse reviewed rows into one invoice-total row just to reconcile totals."
    if teacher_descriptions:
        teacher_instruction += " Teacher row description examples: " + " | ".join(teacher_descriptions[:8]) + "."
    cfg["gemini_supplier_instructions"] = list(dict.fromkeys([*existing_instr, teacher_instruction]))[-20:]
    return True


def _supplier_template_payload_from_rule_patch(
    *,
    patch: Dict[str, Any],
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    doc_type: str,
    existing_template: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Merge a reviewed Gemini/user rule patch into a supplier template payload."""
    existing_template = existing_template if isinstance(existing_template, dict) else {}
    supplier_name = _normalise_supplier_name(
        str((header or {}).get("supplierName") or _template_supplier_name_from_hit(existing_template) or _guess_supplier_from_filename(file_name or "") or "").strip()
    )
    if _template_header_value_is_placeholder("supplierName", supplier_name):
        supplier_name = _template_supplier_name_from_hit(existing_template)
    if not supplier_name:
        raise ValueError("Supplier name is required before saving a rule.")

    header = _normalise_teacher_header_from_raw_text(header or {}, raw_text or "")

    cfg = copy.deepcopy(existing_template.get("config") or {})
    if not isinstance(cfg, dict) and existing_template.get("config_json"):
        try:
            cfg = json.loads(existing_template.get("config_json") or "{}")
        except Exception:
            cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}

    items, invoice_level_vat_repaired = _repair_teacher_invoice_level_vat(header or {}, _template_training_items(items or []))
    if invoice_level_vat_repaired:
        cfg.setdefault("rules", {})
        if isinstance(cfg.get("rules"), dict):
            cfg["rules"]["invoice_level_vat_allocation"] = "allocate_header_vat_to_teacher_gross_rows"

    teacher_rows = _template_training_items(items or [])
    teacher_no_code_rows = [
        it for it in teacher_rows
        if isinstance(it, dict)
        and str(it.get("description") or "").strip()
        and not str(it.get("code") or "").strip()
    ]
    if len(teacher_rows) > 1 and len(teacher_no_code_rows) == len(teacher_rows):
        cfg.setdefault("rules", {})
        if isinstance(cfg.get("rules"), dict):
            cfg["rules"].pop("single_line_no_code_use_header_totals", None)
            cfg["rules"].pop("single_line_use_header_totals", None)
            cfg["rules"]["allow_missing_code"] = True
            cfg["rules"]["line_match_strategy"] = "description_anchor"
            cfg["rules"]["preserve_teacher_line_rows"] = True

        teacher_fields = sorted(
            {
                str(k)
                for it in teacher_rows
                if isinstance(it, dict)
                for k, v in it.items()
                if str(k or "").strip()
                and v not in (None, "")
                and not str(k).startswith("_")
            }
        )
        teacher_descriptions = [
            _collapse_spaces(str(it.get("description") or ""))[:160]
            for it in teacher_rows[:12]
            if isinstance(it, dict) and str(it.get("description") or "").strip()
        ]
        cfg["gemini_teacher_output"] = {
            "learned_at": _uk_now_iso(),
            "source": "reviewed_line_grid",
            "row_count": len(teacher_rows),
            "no_code_rows": len(teacher_no_code_rows),
            "fields": teacher_fields[:40],
            "descriptions": teacher_descriptions,
            "header_total_net": round(_safe_float((header or {}).get("totalNet")), 2),
            "header_total_vat": round(_safe_float((header or {}).get("totalVat")), 2),
            "header_total_gross": round(_safe_float((header or {}).get("totalGross")), 2),
        }

    if isinstance(patch.get("header_aliases"), dict):
        cfg["header_aliases"] = _template_merge_alias_config(
            cfg.get("header_aliases"),
            patch.get("header_aliases"),
            _template_default_header_aliases(),
        )
    if isinstance(patch.get("line_aliases"), dict):
        cfg["line_aliases"] = _template_merge_alias_config(
            cfg.get("line_aliases"),
            patch.get("line_aliases"),
            _template_default_line_aliases(),
        )
    if isinstance(patch.get("table_profile"), dict):
        cfg["table_profile"] = {
            **(cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}),
            **copy.deepcopy(patch.get("table_profile") or {}),
        }
        profile = cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}
        if isinstance(profile.get("columns"), list):
            ordered_profile_fields = [
                str(col.get("field") or "").strip()
                for col in (profile.get("columns") or [])
                if isinstance(col, dict) and str(col.get("field") or "").strip()
            ]
            if ordered_profile_fields:
                existing_header_fields = [
                    str(x).strip()
                    for x in (profile.get("header_fields") or [])
                    if str(x).strip()
                ] if isinstance(profile.get("header_fields"), list) else []
                profile["header_fields"] = list(dict.fromkeys([*existing_header_fields, *ordered_profile_fields]))
                profile["columns"] = {field: {"order": idx} for idx, field in enumerate(ordered_profile_fields)}
        if profile:
            profile.setdefault("allow_plain_numeric_amounts", True)
            cfg["table_profile"] = profile
    if isinstance(patch.get("charge_sections"), list):
        existing_sections = cfg.get("charge_sections") if isinstance(cfg.get("charge_sections"), list) else []
        merged_sections: List[Dict[str, Any]] = [copy.deepcopy(s) for s in existing_sections if isinstance(s, dict)]
        for sec in patch.get("charge_sections") or []:
            if not isinstance(sec, dict):
                continue
            name = str(sec.get("name") or sec.get("start_after_sample") or "").strip().lower()
            start_re = str(sec.get("start_after_regex") or "").strip()
            replaced = False
            for idx, existing in enumerate(merged_sections):
                same_name = name and str(existing.get("name") or "").strip().lower() == name
                same_re = start_re and str(existing.get("start_after_regex") or "").strip() == start_re
                if same_name or same_re:
                    merged_sections[idx] = {**existing, **copy.deepcopy(sec)}
                    replaced = True
                    break
            if not replaced:
                merged_sections.append(copy.deepcopy(sec))
        cfg["charge_sections"] = merged_sections[-20:]
    if isinstance(patch.get("rules"), dict):
        cfg["rules"] = {
            **(cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}),
            **copy.deepcopy(patch.get("rules") or {}),
        }
    cfg.setdefault("rules", {})
    if not isinstance(cfg.get("rules"), dict):
        cfg["rules"] = {}
    try:
        trained_items_for_rules = _template_training_items(items or [])
        if len(trained_items_for_rules) == 1:
            one = trained_items_for_rules[0]
            header_net = round(_safe_float((header or {}).get("totalNet")), 2)
            header_gross = round(_safe_float((header or {}).get("totalGross")), 2)
            row_net = round(_safe_float(one.get("lineNet")), 2)
            row_gross = round(_safe_float(one.get("lineGross")), 2)
            if (
                str(one.get("description") or "").strip()
                and not str(one.get("code") or "").strip()
                and (
                    (header_net > 0 and abs(row_net - header_net) <= 0.05)
                    or (header_gross > 0 and abs(row_gross - header_gross) <= 0.05)
                )
            ):
                cfg["rules"]["allow_missing_code"] = True
                cfg["rules"]["line_match_strategy"] = "description_anchor"
                cfg["rules"]["single_line_no_code_use_header_totals"] = True
    except Exception:
        pass
    _store_gemini_teacher_output_from_items(cfg, header or {}, items or [])
    if isinstance(patch.get("gemini_supplier_instructions"), list):
        existing_instr = cfg.get("gemini_supplier_instructions") if isinstance(cfg.get("gemini_supplier_instructions"), list) else []
        instructions = [str(x).strip() for x in [*existing_instr, *patch.get("gemini_supplier_instructions")] if str(x).strip()]
        cfg["gemini_supplier_instructions"] = list(dict.fromkeys(instructions))[-20:]
    if isinstance(cfg.get("gemini_teacher_output"), dict):
        existing_instr = cfg.get("gemini_supplier_instructions") if isinstance(cfg.get("gemini_supplier_instructions"), list) else []
        teacher = cfg.get("gemini_teacher_output") or {}
        descs = [str(x).strip() for x in (teacher.get("descriptions") or []) if str(x).strip()]
        teacher_instruction = (
            "For this supplier, preserve the reviewed Gemini teacher line structure: "
            f"return about {int(teacher.get('row_count') or len(descs) or 0)} separate line rows, "
            "including no-code subscription/change/adjustment rows as separate items. "
            "Do not collapse multiple reviewed rows into one invoice-total row just to reconcile totals."
        )
        if descs:
            teacher_instruction += " Teacher row description examples: " + " | ".join(descs[:8]) + "."
        cfg["gemini_supplier_instructions"] = list(dict.fromkeys([*existing_instr, teacher_instruction]))[-20:]

    learned_agent = _learn_template_agent_from_corrections(items or [], raw_text or "")
    if learned_agent:
        cfg["template_agent"] = {
            **(cfg.get("template_agent") if isinstance(cfg.get("template_agent"), dict) else {}),
            **learned_agent,
        }
    if not isinstance(cfg.get("table_profile"), dict) or not cfg.get("table_profile"):
        learned_table_profile = _template_table_profile_from_text_and_items(items or [], raw_text or "")
        if learned_table_profile:
            cfg["table_profile"] = learned_table_profile
    learned_charge_sections = _template_charge_section_rules_from_text_and_items(items or [], raw_text or "")
    if learned_charge_sections:
        existing_sections = cfg.get("charge_sections") if isinstance(cfg.get("charge_sections"), list) else []
        merged_sections: List[Dict[str, Any]] = [copy.deepcopy(s) for s in existing_sections if isinstance(s, dict)]
        for sec in learned_charge_sections:
            name = str(sec.get("name") or sec.get("start_after_sample") or "").strip().lower()
            start_re = str(sec.get("start_after_regex") or "").strip()
            replaced = False
            for idx, existing in enumerate(merged_sections):
                same_name = name and str(existing.get("name") or "").strip().lower() == name
                same_re = start_re and str(existing.get("start_after_regex") or "").strip() == start_re
                if same_name or same_re:
                    merged_sections[idx] = {**existing, **copy.deepcopy(sec)}
                    replaced = True
                    break
            if not replaced:
                merged_sections.append(copy.deepcopy(sec))
        cfg["charge_sections"] = merged_sections[-20:]

    line_learning_meta = cfg.get("line_learning") if isinstance(cfg.get("line_learning"), dict) else {}
    line_learning_meta.update(
        {
            "last_learned_at": _uk_now_iso(),
            "reviewed_line_rows": len(_template_training_items(items or [])),
            "gemini_teacher_output_rows": int((cfg.get("gemini_teacher_output") or {}).get("row_count") or 0) if isinstance(cfg.get("gemini_teacher_output"), dict) else 0,
            "template_agent_learned": bool(learned_agent),
            "template_agent_rows": int((learned_agent or {}).get("trained_rows") or 0),
            "table_profile_learned": bool(cfg.get("table_profile")),
            "table_profile_rows": int(((cfg.get("table_profile") or {}) if isinstance(cfg.get("table_profile"), dict) else {}).get("matched_rows") or 0),
            "charge_section_rules": len(cfg.get("charge_sections") or []) if isinstance(cfg.get("charge_sections"), list) else 0,
        }
    )
    cfg["line_learning"] = line_learning_meta

    cfg["english_rule_agent"] = {
        "last_suggested_at": _uk_now_iso(),
        "notes": [str(x) for x in (patch.get("notes") or []) if str(x).strip()][:10],
    }

    keywords = []
    try:
        if existing_template.get("match_keywords_json"):
            keywords.extend(json.loads(existing_template.get("match_keywords_json") or "[]") or [])
    except Exception:
        pass
    keywords.extend(_template_keywords(supplier_name, [str((header or {}).get("customerName") or ""), file_name or ""]))
    dedup_keywords = []
    seen_kw = set()
    for keyword in keywords:
        kw = _collapse_spaces(str(keyword or ""))
        if len(kw) < 3:
            continue
        key = kw.casefold()
        if key in seen_kw:
            continue
        seen_kw.add(key)
        dedup_keywords.append(kw)

    parser_type = _detect_parser_type_from_supplier(
        supplier_name,
        str(existing_template.get("parser_type") or "GENERIC"),
    )
    return {
        "template_id": str(existing_template.get("template_id") or ""),
        "display_id": str(existing_template.get("display_id") or ""),
        "supplier_name": supplier_name,
        "parser_type": parser_type,
        "vat_number": str(existing_template.get("vat_number") or ""),
        "awrs_number": str(existing_template.get("awrs_number") or ""),
        "requires_cloud": int(existing_template.get("requires_cloud") or 0),
        "match_keywords": dedup_keywords,
        "config": _template_enrich_supplier_config(
            cfg,
            supplier_name=supplier_name,
            parser_type=parser_type,
            raw_text=raw_text or "",
            header=header or {},
            items=items or [],
            doc_type=doc_type,
            aliases=dedup_keywords,
        ),
        "created_at": str(existing_template.get("created_at") or ""),
    }


def _template_gemini_instruction_text(template_hit: Optional[Dict[str, Any]]) -> str:
    """Return supplier-specific English hints to prepend to Gemini OCR text."""
    if not isinstance(template_hit, dict):
        return ""
    cfg = template_hit.get("config") if isinstance(template_hit.get("config"), dict) else {}
    if not cfg and template_hit.get("config_json"):
        try:
            cfg = json.loads(template_hit.get("config_json") or "{}")
        except Exception:
            cfg = {}
    if not isinstance(cfg, dict):
        return ""
    instructions = cfg.get("gemini_supplier_instructions") if isinstance(cfg.get("gemini_supplier_instructions"), list) else []
    lines = [str(x).strip() for x in instructions if str(x).strip()]
    teacher_output = cfg.get("gemini_teacher_output") if isinstance(cfg.get("gemini_teacher_output"), dict) else {}
    if teacher_output:
        descs = [
            str(x).strip()
            for x in (teacher_output.get("descriptions") or [])
            if str(x).strip()
        ]
        row_count = int(teacher_output.get("row_count") or len(descs) or 0)
        if row_count > 0:
            row_word = "row" if row_count == 1 else "separate line rows"
            teacher_line = (
                f"For this supplier, follow the reviewed output format: return about {row_count} {row_word}. "
                "Keep payment terms, addresses, email/contact text, and other header text out of line descriptions."
            )
            if row_count > 1:
                teacher_line += " Do not merge the reviewed rows into one total line."
            if descs:
                teacher_line += " Example row descriptions: " + " | ".join(descs[:8]) + "."
            lines.append(teacher_line)
    rules = cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}
    if str(rules.get("invoice_level_vat_allocation") or "") == "allocate_header_vat_to_teacher_gross_rows":
        lines.append(
            "For this supplier, VAT may be printed only at invoice/header level while row amounts are visible gross amounts. "
            "When header VAT is non-zero and line VAT is not printed, allocate the header VAT across the line rows so "
            "sum(lineNet), sum(vatAmount), and sum(lineGross) reconcile to the header totals. Do not leave all row VAT amounts as 0."
        )
    charge_sections = cfg.get("charge_sections") if isinstance(cfg.get("charge_sections"), list) else []
    for sec in charge_sections or []:
        if not isinstance(sec, dict):
            continue
        name = str(sec.get("name") or sec.get("start_after_sample") or "").strip()
        if name:
            lines.append(
                f"For this supplier, include rows from the '{name}' section as charge lines when they have an amount."
            )
    line_aliases = cfg.get("line_aliases") if isinstance(cfg.get("line_aliases"), dict) else {}
    discount_aliases = line_aliases.get("discount") if isinstance(line_aliases.get("discount"), list) else []
    if discount_aliases:
        lines.append(
            "For this supplier, capture the printed discount column as item.discount using aliases: "
            + ", ".join(str(x) for x in discount_aliases[:6])
            + "."
        )
    lines = list(dict.fromkeys([ln for ln in lines if ln]))[:12]
    if not lines:
        return ""
    tpl_id = str(template_hit.get("display_id") or template_hit.get("template_id") or "").strip()
    return (
        "Supplier-specific extraction instructions"
        + (f" for template {tpl_id}" if tpl_id else "")
        + ":\n- "
        + "\n- ".join(lines)
    )


def _db_upsert_customer_template(payload: Dict[str, Any]) -> str:
    """Create/update customer template and return template_id.

    Rules:
    - One template per (customer_name, parser_type) unless template_id explicitly provided.
    - If display_id is empty and a matching template exists, keep existing display_id (prevents duplicates).
    """
    customer_name = (payload.get("customer_name") or "").strip()
    parser_type = (payload.get("parser_type") or "GENERIC").strip().upper()
    now = _uk_now_iso()

    template_id = (payload.get("template_id") or "").strip()
    existing: Optional[Dict[str, Any]] = None

    if template_id:
        row = _db_fetchone("SELECT * FROM customer_templates WHERE template_id=?", (template_id,))
        existing = dict(row) if row else None
    else:
        row = _db_fetchone(
            "SELECT * FROM customer_templates WHERE UPPER(TRIM(customer_name))=? AND UPPER(TRIM(parser_type))=?",
            (customer_name.upper(), parser_type),
        )
        existing = dict(row) if row else None
        if existing:
            template_id = (existing.get("template_id") or "").strip()

        # Dedupe: keep one template per customer+parser_type
        if template_id:
            _db_exec(
                "DELETE FROM customer_templates WHERE UPPER(TRIM(customer_name))=? AND UPPER(TRIM(parser_type))=? AND template_id<>?",
                (customer_name.upper(), parser_type, template_id),
            )

    if not template_id:
        template_id = _sha256_bytes(f"CST|{customer_name}|{time.time()}".encode("utf-8"))[:24]

    created = (payload.get("created_at") or (existing.get("created_at") if existing else "") or now)
    requires_cloud = 1 if int(payload.get("requires_cloud") or (existing.get("requires_cloud") if existing else 0) or 0) == 1 else 0

    cfg = payload.get("config")
    if cfg is None:
        cfg = {}
        if existing and existing.get("config_json"):
            try:
                cfg = json.loads(existing.get("config_json") or "{}")
            except Exception:
                cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}

    keywords = payload.get("match_keywords")
    if not isinstance(keywords, list):
        if existing and existing.get("match_keywords_json"):
            try:
                keywords = json.loads(existing.get("match_keywords_json") or "[]")
            except Exception:
                keywords = None
        if not isinstance(keywords, list):
            keywords = _template_keywords(customer_name)

    display_id = (payload.get("display_id") or "").strip()
    if not display_id and existing:
        display_id = (existing.get("display_id") or "").strip()

    if not display_id:
        yyyymmdd = re.sub(r"[^0-9]", "", now[:10])
        if len(yyyymmdd) != 8:
            yyyymmdd = datetime.utcnow().strftime("%Y%m%d")
        prefix = _customer_acronym(customer_name)
        display_id = _next_display_id(prefix, yyyymmdd, "customer_templates")

    row2 = _db_fetchone("SELECT template_id FROM customer_templates WHERE display_id=?", (display_id,))
    row2_tid = str((dict(row2).get("template_id") if row2 else "") or "").strip()
    if row2_tid and row2_tid != template_id:
        raise ValueError(f"Display ID already exists: {display_id}")

    _db_exec(
        """INSERT OR REPLACE INTO customer_templates(
            template_id, display_id, customer_name,
            match_keywords_json, parser_type, requires_cloud, config_json,
            created_at, updated_at
        ) VALUES(?,?,?,?,?,?,?,?,?)""",
        (
            template_id,
            display_id,
            customer_name,
            json.dumps(keywords),
            parser_type,
            requires_cloud,
            json.dumps(cfg),
            created,
            now,
        ),
    )
    return template_id


def _db_delete_template(table: str, identifier: str) -> int:
    """Delete a template by template_id OR display_id. Returns rows deleted."""
    if table not in ("supplier_templates", "customer_templates"):
        return 0
    ident = (identifier or "").strip()
    if not ident:
        return 0
    conn = _db_connect()
    cur = conn.cursor()
    cur.execute(f"DELETE FROM {table} WHERE template_id=? OR display_id=?", (ident, ident))
    conn.commit()
    n = cur.rowcount or 0
    conn.close()
    return n


def _template_sync_sqlserver_module():
    return _sqlserver_cloud or _sqlserver_local or _sqlserver


def _template_sync_sqlserver_connect():
    mod = _template_sync_sqlserver_module()
    if mod is None or not hasattr(mod, "_load_sqlserver_config") or not hasattr(mod, "_connect"):
        raise RuntimeError("SQL Server module/connection helpers are not available.")
    cfg = mod._load_sqlserver_config()  # type: ignore[attr-defined]
    if not cfg:
        raise RuntimeError("SQL Server config is missing.")
    return mod._connect(cfg)  # type: ignore[attr-defined]


def _template_sync_table_names(local_table: str) -> Tuple[str, str, str]:
    if local_table == "supplier_templates":
        return "DocMate_supplier_templates_master", "supplier_name", "supplier_name"
    if local_table == "customer_templates":
        return "DocMate_customer_templates_master", "customer_name", "customer_name"
    raise ValueError("Unsupported template table.")


def _ensure_central_template_table(conn, local_table: str) -> str:
    central_table, local_name_col, central_name_col = _template_sync_table_names(local_table)
    extra_cols = "vat_number NVARCHAR(128) NULL, awrs_number NVARCHAR(128) NULL," if local_table == "supplier_templates" else ""
    sql = f"""
    IF OBJECT_ID(N'dbo.{central_table}', N'U') IS NULL
    BEGIN
        CREATE TABLE dbo.{central_table} (
            template_id NVARCHAR(64) NOT NULL PRIMARY KEY,
            display_id NVARCHAR(128) NULL,
            {central_name_col} NVARCHAR(260) NULL,
            {extra_cols}
            match_keywords_json NVARCHAR(MAX) NULL,
            parser_type NVARCHAR(64) NULL,
            requires_cloud INT NULL,
            config_json NVARCHAR(MAX) NULL,
            created_at NVARCHAR(64) NULL,
            updated_at NVARCHAR(64) NULL,
            approved BIT NOT NULL DEFAULT 1,
            source_site NVARCHAR(128) NULL,
            source_user NVARCHAR(128) NULL,
            synced_at NVARCHAR(64) NULL
        );
    END
    IF COL_LENGTH('dbo.{central_table}', 'approved') IS NULL
        ALTER TABLE dbo.{central_table} ADD approved BIT NOT NULL CONSTRAINT DF_{central_table}_approved DEFAULT 1;
    IF COL_LENGTH('dbo.{central_table}', 'source_site') IS NULL
        ALTER TABLE dbo.{central_table} ADD source_site NVARCHAR(128) NULL;
    IF COL_LENGTH('dbo.{central_table}', 'source_user') IS NULL
        ALTER TABLE dbo.{central_table} ADD source_user NVARCHAR(128) NULL;
    IF COL_LENGTH('dbo.{central_table}', 'synced_at') IS NULL
        ALTER TABLE dbo.{central_table} ADD synced_at NVARCHAR(64) NULL;
    """
    cur = conn.cursor()
    cur.execute(sql)
    conn.commit()
    return central_table


def _template_row_updated_at(row: Dict[str, Any]) -> str:
    return str((row or {}).get("updated_at") or (row or {}).get("created_at") or "")


def _central_push_template_row(conn, local_table: str, row: Dict[str, Any], source_site: str = "") -> Tuple[bool, str]:
    central_table, local_name_col, central_name_col = _template_sync_table_names(local_table)
    now = _uk_now_iso()
    template_id = str(row.get("template_id") or "").strip()
    if not template_id:
        return False, "missing template_id"
    updated_at = _template_row_updated_at(row)
    source_user = str(os.environ.get("USERNAME") or os.environ.get("USER") or "").strip()
    cur = conn.cursor()
    existing = cur.execute(f"SELECT updated_at FROM dbo.{central_table} WHERE template_id=?", (template_id,)).fetchone()
    if existing:
        central_updated = str(getattr(existing, "updated_at", "") or existing[0] or "")
        if central_updated and updated_at and central_updated > updated_at:
            return False, "central newer"
        if local_table == "supplier_templates":
            cur.execute(
                f"""UPDATE dbo.{central_table}
                       SET display_id=?, supplier_name=?, vat_number=?, awrs_number=?, match_keywords_json=?,
                           parser_type=?, requires_cloud=?, config_json=?, created_at=?, updated_at=?,
                           source_site=?, source_user=?, synced_at=?
                     WHERE template_id=?""",
                (
                    row.get("display_id") or "",
                    row.get("supplier_name") or "",
                    row.get("vat_number") or "",
                    row.get("awrs_number") or "",
                    row.get("match_keywords_json") or "[]",
                    row.get("parser_type") or "GENERIC",
                    int(row.get("requires_cloud") or 0),
                    row.get("config_json") or "{}",
                    row.get("created_at") or "",
                    updated_at,
                    source_site,
                    source_user,
                    now,
                    template_id,
                ),
            )
        else:
            cur.execute(
                f"""UPDATE dbo.{central_table}
                       SET display_id=?, customer_name=?, match_keywords_json=?,
                           parser_type=?, requires_cloud=?, config_json=?, created_at=?, updated_at=?,
                           source_site=?, source_user=?, synced_at=?
                     WHERE template_id=?""",
                (
                    row.get("display_id") or "",
                    row.get("customer_name") or "",
                    row.get("match_keywords_json") or "[]",
                    row.get("parser_type") or "GENERIC",
                    int(row.get("requires_cloud") or 0),
                    row.get("config_json") or "{}",
                    row.get("created_at") or "",
                    updated_at,
                    source_site,
                    source_user,
                    now,
                    template_id,
                ),
            )
        return True, "updated"

    if local_table == "supplier_templates":
        cur.execute(
            f"""INSERT INTO dbo.{central_table}
                (template_id, display_id, supplier_name, vat_number, awrs_number, match_keywords_json,
                 parser_type, requires_cloud, config_json, created_at, updated_at, approved,
                 source_site, source_user, synced_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                template_id,
                row.get("display_id") or "",
                row.get("supplier_name") or "",
                row.get("vat_number") or "",
                row.get("awrs_number") or "",
                row.get("match_keywords_json") or "[]",
                row.get("parser_type") or "GENERIC",
                int(row.get("requires_cloud") or 0),
                row.get("config_json") or "{}",
                row.get("created_at") or "",
                updated_at,
                1,
                source_site,
                source_user,
                now,
            ),
        )
    else:
        cur.execute(
            f"""INSERT INTO dbo.{central_table}
                (template_id, display_id, customer_name, match_keywords_json,
                 parser_type, requires_cloud, config_json, created_at, updated_at, approved,
                 source_site, source_user, synced_at)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                template_id,
                row.get("display_id") or "",
                row.get("customer_name") or "",
                row.get("match_keywords_json") or "[]",
                row.get("parser_type") or "GENERIC",
                int(row.get("requires_cloud") or 0),
                row.get("config_json") or "{}",
                row.get("created_at") or "",
                updated_at,
                1,
                source_site,
                source_user,
                now,
            ),
        )
    return True, "inserted"


def _push_templates_to_central(local_table: str, source_site: str = "") -> Dict[str, Any]:
    rows = [dict(r) for r in _db_fetchall(f"SELECT * FROM {local_table}")]
    summary = {"total": len(rows), "pushed": 0, "skipped": 0, "errors": []}
    conn = _template_sync_sqlserver_connect()
    try:
        _ensure_central_template_table(conn, local_table)
        for row in rows:
            try:
                ok, note = _central_push_template_row(conn, local_table, row, source_site=source_site)
                if ok:
                    summary["pushed"] += 1
                else:
                    summary["skipped"] += 1
                    if note:
                        summary["errors"].append(f"{row.get('display_id') or row.get('template_id')}: {note}")
            except Exception as e:
                summary["skipped"] += 1
                summary["errors"].append(f"{row.get('display_id') or row.get('template_id')}: {e}")
        conn.commit()
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return summary


def _pull_templates_from_central(local_table: str, approved_only: bool = True) -> Dict[str, Any]:
    summary = {"total": 0, "pulled": 0, "skipped": 0, "errors": []}
    conn = _template_sync_sqlserver_connect()
    try:
        central_table, local_name_col, central_name_col = _template_sync_table_names(local_table)
        _ensure_central_template_table(conn, local_table)
        where = "WHERE approved=1" if approved_only else ""
        rows = conn.cursor().execute(f"SELECT * FROM dbo.{central_table} {where}").fetchall()
        cols = [col[0] for col in rows.cursor_description] if hasattr(rows, "cursor_description") else []
        if not cols:
            # pyodbc exposes description on the cursor, not on fetched rows.
            cur = conn.cursor()
            cur.execute(f"SELECT * FROM dbo.{central_table} {where}")
            cols = [col[0] for col in cur.description]
            rows = cur.fetchall()
        summary["total"] = len(rows)
        for row in rows:
            data = {cols[i]: row[i] for i in range(len(cols))}
            template_id = str(data.get("template_id") or "").strip()
            if not template_id:
                summary["skipped"] += 1
                continue
            local_existing = _db_fetchone(f"SELECT * FROM {local_table} WHERE template_id=?", (template_id,))
            central_updated = _template_row_updated_at(data)
            if local_existing:
                local_updated = _template_row_updated_at(dict(local_existing))
                if local_updated and central_updated and local_updated > central_updated:
                    summary["skipped"] += 1
                    continue
            try:
                if local_table == "supplier_templates":
                    _db_upsert_supplier_template(
                        {
                            "template_id": template_id,
                            "display_id": data.get("display_id") or "",
                            "supplier_name": data.get("supplier_name") or "",
                            "vat_number": data.get("vat_number") or "",
                            "awrs_number": data.get("awrs_number") or "",
                            "match_keywords": json.loads(data.get("match_keywords_json") or "[]"),
                            "parser_type": data.get("parser_type") or "GENERIC",
                            "requires_cloud": int(data.get("requires_cloud") or 0),
                            "config": json.loads(data.get("config_json") or "{}"),
                            "created_at": data.get("created_at") or "",
                        }
                    )
                else:
                    _db_upsert_customer_template(
                        {
                            "template_id": template_id,
                            "display_id": data.get("display_id") or "",
                            "customer_name": data.get("customer_name") or "",
                            "match_keywords": json.loads(data.get("match_keywords_json") or "[]"),
                            "parser_type": data.get("parser_type") or "GENERIC",
                            "requires_cloud": int(data.get("requires_cloud") or 0),
                            "config": json.loads(data.get("config_json") or "{}"),
                            "created_at": data.get("created_at") or "",
                        }
                    )
                summary["pulled"] += 1
            except Exception as e:
                summary["skipped"] += 1
                summary["errors"].append(f"{template_id}: {e}")
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return summary


def _db_get_template(table: str, template_id: str) -> Optional[Dict[str, Any]]:
    if table not in ("supplier_templates", "customer_templates"):
        return None
    row = _db_fetchone(f"SELECT * FROM {table} WHERE template_id=?", (template_id,))
    if not row:
        return None
    d = dict(row)
    try:
        d["match_keywords"] = json.loads(d.get("match_keywords_json") or "[]")
    except Exception:
        d["match_keywords"] = []
    try:
        d["config"] = json.loads(d.get("config_json") or "{}")
    except Exception:
        d["config"] = {}
    return d


def _db_find_best_template(doc_text: str, table: str, threshold: int | None = None) -> Optional[Dict[str, Any]]:
    if table not in ("supplier_templates", "customer_templates"):
        return None
    rows = _db_fetchall(f"SELECT * FROM {table}")
    if not GENERIC_TEMPLATE_TRAINING_ENABLED:
        if table == "customer_templates":
            return None
        rows = [
            row
            for row in rows
            if str(dict(row).get("parser_type") or "").strip().upper() in DEDICATED_SUPPLIER_PARSER_TYPES
        ]
    # Adaptive threshold: templates should still match when invoice numbers change.
    # If not provided, require 2 strong keyword hits when possible, otherwise 1.
    effective_threshold = threshold
    best: Optional[Tuple[int, Dict[str, Any]]] = None
    for r in rows:
        d = dict(r)
        try:
            kws = json.loads(d.get("match_keywords_json") or "[]")
        except Exception:
            kws = []
        try:
            cfg_match = json.loads(d.get("config_json") or "{}")
        except Exception:
            cfg_match = {}
        if not isinstance(cfg_match, dict):
            cfg_match = {}
        alias_kws = cfg_match.get("supplier_aliases") or []
        anchor_kws = cfg_match.get("layout_anchors") or []
        if not isinstance(alias_kws, list):
            alias_kws = []
        if not isinstance(anchor_kws, list):
            anchor_kws = []
        scope = str(cfg_match.get("template_scope") or "supplier").strip().lower()
        supplier_identity_terms = list(alias_kws or [])
        supplier_identity_terms.extend(
            [
                d.get("supplier_name") or "",
                cfg_match.get("supplier_key") or "",
            ]
        )
        identity_score = _template_score(doc_text, supplier_identity_terms)
        keyword_score = _template_score(doc_text, list(kws or []))
        # Commercial OCR-style routing: supplier-specific templates require
        # supplier identity evidence. Layout anchors only break ties once the
        # vendor has been identified, so Uber training will not hijack Bolt.
        if scope == "supplier" and identity_score <= 0:
            score = 0
        else:
            score = identity_score + min(keyword_score, 3)
        if table == "supplier_templates" and score > 0:
            # Defensive guard for legacy/duplicate rows: a template whose
            # display ID prefix does not match its own supplier name is weaker
            # than a canonical supplier row. This prevents stale rows such as
            # an old typo/alias template from winning just because a short
            # alias like "LRK" appears in the OCR text.
            try:
                if not _template_display_id_matches_supplier(d.get("display_id") or "", d.get("supplier_name") or ""):
                    score -= 2
            except Exception:
                pass
        anchor_score = _template_score(doc_text, list(anchor_kws or []))
        if anchor_score and (scope != "supplier" or identity_score > 0):
            score += min(anchor_score, 3)
        if best is None or score > best[0]:
            best = (score, d)
        # Determine threshold after we see best candidate keyword count
    if best is None:
        return None
    if effective_threshold is None:
        # best[1] is the dict for the best-scoring template; count its usable keywords
        try:
            kws_best = json.loads(best[1].get("match_keywords_json") or "[]")
        except Exception:
            kws_best = []
        kws_best = [k for k in (kws_best or []) if isinstance(k, str) and len(k.strip()) >= 4]
        effective_threshold = 2 if len(kws_best) >= 2 else 1

    if best and best[0] >= int(effective_threshold):
        d = best[1]
        try:
            d["match_keywords"] = json.loads(d.get("match_keywords_json") or "[]")
        except Exception:
            d["match_keywords"] = []
        try:
            d["config"] = json.loads(d.get("config_json") or "{}")
        except Exception:
            d["config"] = {}
        return d
    return None


