# OCR
# -------------------------

@dataclass
class OcrConfig:
    engine: str = "tesseract"  # tesseract/easyocr/doctr
    tesseract_cmd: str = ""
    dpi: int = 250
    max_pages: int = 2
    force_pdf: bool = False
    auto_install: bool = False
    auto_image_tuning: bool = True
    auto_pdf_page_routing: bool = True
    pdf_scanned_char_threshold: int = 50
    pdf_force_ocr_sparse_pages: bool = True
    photo_auto_deskew: bool = True
    photo_rotate_deg: float = 0.0
    photo_contrast: float = 1.0
    photo_brightness: float = 1.0
    photo_sharpness: float = 1.0
    photo_scan_like: bool = False
    doctr_upscale: float = 1.0
    doctr_strong_photo: bool = False

    @classmethod
    def from_dict(cls, d: Any) -> "OcrConfig":
        """Safe constructor from a dict-like object.

        Allows older keys and ignores unknown keys.
        """
        if isinstance(d, cls):
            return d
        if d is None:
            return cls()
        if not isinstance(d, dict):
            try:
                # e.g. dataclasses.asdict output already dict; otherwise best-effort
                d = dict(d)
            except Exception:
                return cls()

        # normalise possible legacy keys
        d2 = dict(d)
        if "max_pages_pdf" in d2 and "max_pages" not in d2:
            d2["max_pages"] = d2.get("max_pages_pdf")

        kwargs = {}
        for f in dataclasses.fields(cls):
            if f.name in d2 and d2[f.name] is not None:
                kwargs[f.name] = d2[f.name]
        return cls(**kwargs)



def _db_find_template_latest_by_parser_type(parser_type: str, table: str = "supplier_templates") -> Optional[Dict[str, Any]]:
    """Return the latest template row for a given parser_type from the chosen table."""
    pt = (parser_type or "").strip().upper()
    if not pt:
        return None
    try:
        row = _db_fetchone(
            f"""SELECT * FROM {table}
                  WHERE UPPER(TRIM(parser_type))=?
                  ORDER BY COALESCE(NULLIF(updated_at,''), NULLIF(created_at,'')) DESC
                  LIMIT 1""",
            (pt,)
        )
        if row:
            r = dict(row)
            try:
                r["config"] = json.loads(r.get("config_json") or "{}")
            except Exception:
                r["config"] = {}
            return r
    except Exception:
        return None
    return None


def _db_find_booker_template_latest() -> Optional[Dict[str, Any]]:
    """Fallback: if keyword matching fails but the document looks like Booker, use latest Booker supplier template.

    NOTE: Some deployments may have NULL updated_at values or legacy rows. This function is intentionally defensive.
    """
    queries = [
        # Preferred: most recently updated (or created) Booker template
        """SELECT * FROM supplier_templates
               WHERE (UPPER(TRIM(supplier_name)) LIKE '%BOOKER%' OR UPPER(TRIM(parser_type))='BOOKER')
               ORDER BY COALESCE(NULLIF(updated_at,''), NULLIF(created_at,'')) DESC
               LIMIT 1""",
        # Fallback: order by created_at
        """SELECT * FROM supplier_templates
               WHERE (UPPER(TRIM(supplier_name)) LIKE '%BOOKER%' OR UPPER(TRIM(parser_type))='BOOKER')
               ORDER BY COALESCE(NULLIF(created_at,''), template_id) DESC
               LIMIT 1""",
        # Last resort: any Booker template
        """SELECT * FROM supplier_templates
               WHERE (UPPER(TRIM(supplier_name)) LIKE '%BOOKER%' OR UPPER(TRIM(parser_type))='BOOKER')
               LIMIT 1""",
    ]
    for q in queries:
        try:
            row = _db_fetchone(q)
            if row:
                r = dict(row)
                try:
                    r["config"] = json.loads(r.get("config_json") or "{}")
                except Exception:
                    r["config"] = {}
                return r
        except Exception:
            continue
    return None


def _ensure_import(module_name: str, pip_name: str, auto_install: bool) -> Tuple[bool, str]:
    try:
        __import__(module_name)
        return True, ""
    except Exception as e:
        if not auto_install:
            return False, f"Missing dependency: {module_name}. Install: pip install {pip_name}"
        # best-effort pip install
        try:
            import subprocess, sys

            subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", pip_name])
            __import__(module_name)
            return True, ""
        except Exception as e2:
            return False, f"Failed to install {pip_name}: {e2}"


def _pdf_text_layer(pdf_bytes: bytes, max_pages: int = 2, progress_cb=None, progress_label: str = "") -> str:
    """Extract embedded PDF text layer with clear page separators.

    Used for fast supplier detection and for the Local OCR / PDF debug text panel.
    """

    def _pdf_text_layer_pdftotext() -> str:
        try:
            import subprocess, tempfile, os
            cap = max(1, int(max_pages or 1))
            parts: List[str] = []
            # Resolve pdftotext executable (PATH or common Windows install)
            exe_candidates = ["pdftotext"]
            try:
                from shutil import which as _which
                if _which("pdftotext") is None:
                    exe_candidates.append(r"C:\\poppler-25.12.0\\Library\\bin\\pdftotext.exe")
            except Exception:
                exe_candidates.append(r"C:\\poppler-25.12.0\\Library\\bin\\pdftotext.exe")
            pdftotext_exe = None
            for ex in exe_candidates:
                try:
                    if ex == "pdftotext" or os.path.exists(ex):
                        pdftotext_exe = ex
                        break
                except Exception:
                    continue
            if not pdftotext_exe:
                return ""
            with tempfile.NamedTemporaryFile(delete=False, suffix=".pdf") as tf:
                tf.write(pdf_bytes or b"")
                tmp_path = tf.name
            try:
                for i in range(1, cap + 1):
                    try:
                        res = subprocess.run(
                            [pdftotext_exe, "-f", str(i), "-l", str(i), "-layout", "-nopgbrk", "-enc", "UTF-8", tmp_path, "-"],
                            capture_output=True, text=True, encoding="utf-8", errors="replace"
                        )
                        page_txt = (res.stdout or "").strip()
                    except Exception:
                        page_txt = ""
                    if callable(progress_cb):
                        try:
                            progress_cb(i, cap, progress_label)
                        except Exception:
                            pass
                    parts.append(f"""===== Page {i}/{cap} =====
{page_txt}""")
            finally:
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass
            return "\n\n".join(parts).strip()
        except Exception:
            return ""

    def _pdf_text_layer_pdfplumber() -> str:
        if pdfplumber is None:
            return ""
        try:
            cap = max(1, int(max_pages or 1))
            parts: List[str] = []
            with pdfplumber.open(io.BytesIO(pdf_bytes or b"")) as pdf:
                total = len(pdf.pages or [])
                captured = min(cap, total) if total > 0 else cap
                for i, page in enumerate(pdf.pages[:cap], start=1):
                    try:
                        # layout=True usually preserves invoice columns better than plain extraction.
                        page_txt = (page.extract_text(layout=True) or "").strip()
                    except Exception:
                        page_txt = ""
                    if callable(progress_cb):
                        try:
                            progress_cb(i, captured, progress_label)
                        except Exception:
                            pass
                    parts.append(f"""===== Page {i}/{captured} =====
{page_txt}""")
            return "\n\n".join(parts).strip()
        except Exception:
            return ""

    def _text_layer_quality_score(text: str) -> Tuple[int, int, int]:
        try:
            lines = [ln.strip() for ln in (text or "").splitlines() if str(ln or "").strip()]
            if not lines:
                return (0, 0, 0)
            code_lines = [ln for ln in lines if re.match(r"\s*\d{5,7}\b", ln)]
            decimal_hits = sum(len(re.findall(r"\d+\.\d{2}", ln)) for ln in lines)
            rich_code_lines = sum(1 for ln in code_lines if len(re.findall(r"\d+\.\d{2}", ln)) >= 2)
            return (rich_code_lines, len(code_lines), decimal_hits)
        except Exception:
            return (0, 0, 0)

    # Prefer pdftotext when available (more reliable column layout for Booker-style tables)
    try:
        pdftxt = _pdf_text_layer_pdftotext()
        if pdftxt:
            return pdftxt
    except Exception:
        pass

    plumber_txt = ""
    try:
        plumber_txt = _pdf_text_layer_pdfplumber()
    except Exception:
        plumber_txt = ""

    if not fitz:
        return plumber_txt
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        try:
            total = int(doc.page_count or 0)
        except Exception:
            total = 0
        cap = max(1, int(max_pages or 1))
        captured = min(cap, total) if total > 0 else cap

        parts: List[str] = []
        for i, page in enumerate(doc):
            if i >= cap:
                break
            try:
                page_txt = (page.get_text("text") or "").strip()
            except Exception:
                page_txt = ""

            if callable(progress_cb):
                try:
                    progress_cb(i+1, captured, progress_label)
                except Exception:
                    pass
            parts.append(f"""===== Page {i+1}/{captured} =====
{page_txt}""")
        doc.close()
        joined = "\n\n".join(parts).strip()
        if joined:
            # If PyMuPDF text is fragmented, prefer a stronger alternate extractor when available.
            try:
                fitz_score = _text_layer_quality_score(joined)
                plumber_score = _text_layer_quality_score(plumber_txt)
                # Prefer pdfplumber when it clearly captures more row/decimal structure.
                if plumber_txt and plumber_score > fitz_score:
                    return plumber_txt
                # If PyMuPDF text is too weak for line parsing, retry a stronger alternate extractor.
                if fitz_score[1] and fitz_score[0] < max(2, fitz_score[1] // 2):
                    alt = _pdf_text_layer_pdftotext()
                    if alt:
                        return alt
                    if plumber_txt:
                        return plumber_txt
            except Exception:
                pass
            return joined
    except Exception:
        pass

    # Fallback when PyMuPDF is present but returns empty text
    if plumber_txt:
        return plumber_txt
    return _pdf_text_layer_pdftotext()


def _pdf_page_count(pdf_bytes: bytes) -> int:

    if not fitz:
        return 0
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        n = doc.page_count
        doc.close()
        return int(n or 0)
    except Exception:
        return 0


def _effective_max_pages(settings: Dict[str, Any], supplier_hint: str, file_bytes: bytes, mime: str, default_pages: int) -> int:
    """Supplier-aware max pages for OCR/PDF text layer.
    - Booker recommended: 4 pages
    - Parfetts (multi-page invoice): 6 pages
    For other suppliers, prefer the real PDF page count when available.
    Falls back to global ocr_max_pages or provided default.
    Caps to actual PDF page count when possible.
    """
    try:
        hint = (supplier_hint or "").upper()
    except Exception:
        hint = ""
    pages = int(default_pages or 1)

    # Template override (supplier_templates.config.max_pages_pdf)
    try:
        if bool(settings.get("supplier_templates_enabled", True)) and hint:
            tpl = _db_find_best_template(hint, table="supplier_templates", threshold=int(settings.get("supplier_template_match_threshold", 3) or 3))
            if tpl:
                cfg = tpl.get("config") or {}
                if isinstance(cfg, dict):
                    mp = cfg.get("max_pages_pdf")
                    if mp is not None and str(mp).strip().isdigit():
                        pages = int(mp)
    except Exception:
        pass
    try:
        supplier_override = _supplier_max_pages_override(settings, hint)
        if _looks_like_booker_delivery_invoice(hint):
            pages = max(int(settings.get("booker_max_pages", 4) or 4), int(default_pages or 1), 10)
        elif supplier_override is not None:
            pages = int(supplier_override)
        else:
            # Non-special suppliers should not be arbitrarily truncated to the
            # default OCR page setting if the PDF is longer. Use the actual page
            # count where possible, while preserving the existing safety cap below.
            if mime == "application/pdf":
                try:
                    pages = int(_pdf_page_count(file_bytes) or 0)
                except Exception:
                    pages = 0
            if pages <= 0:
                pages = int(settings.get("ocr_max_pages", pages) or pages)
    except Exception:
        pass
    pages = max(1, min(int(pages), 50))
    if mime == "application/pdf":
        try:
            n = _pdf_page_count(file_bytes)
            if n and n > 0:
                pages = min(pages, int(n))
        except Exception:
            pass
    return max(1, int(pages))


def _images_to_pdf_bytes(items: List[Dict[str, Any]]) -> bytes:
    """Convert a list of image items into a single multi-page PDF (bytes)."""
    if Image is None:
        raise RuntimeError("Image to PDF conversion requires Pillow.")
    imgs = []
    for it in items:
        try:
            img = Image.open(io.BytesIO(it.get("bytes") or b""))
            try:
                if ImageOps is not None:
                    img = ImageOps.exif_transpose(img)
            except Exception:
                pass
            if img.mode != "RGB":
                img = img.convert("RGB")
            imgs.append(img)
        except Exception as e:
            raise RuntimeError(f"Failed to read image for PDF merge: {e}") from e
    if not imgs:
        return b""
    buf = io.BytesIO()
    try:
        imgs[0].save(buf, format="PDF", save_all=True, append_images=imgs[1:])
    except Exception as e:
        raise RuntimeError(f"Failed to write PDF from images: {e}") from e
    return buf.getvalue()


def _merge_items_to_pdf(items: List[Dict[str, Any]]) -> bytes:
    """Merge multiple upload items (PDFs and/or images) into a single PDF."""
    has_pdf = False
    for it in items:
        nm = (it.get("name") or "").lower()
        mime = (it.get("mime") or "").lower()
        if mime == "application/pdf" or nm.endswith(".pdf"):
            has_pdf = True
            break
    if not fitz:
        if has_pdf:
            raise RuntimeError("PyMuPDF is required to merge PDF pages.")
        return _images_to_pdf_bytes(items)

    out = fitz.open()
    try:
        for it in items:
            name = it.get("name") or ""
            data = it.get("bytes") or b""
            mime = (it.get("mime") or _guess_mime_type(name) or "").lower()
            if mime == "application/pdf" or name.lower().endswith(".pdf"):
                src = fitz.open(stream=data, filetype="pdf")
                out.insert_pdf(src)
                src.close()
            else:
                img_pdf = _images_to_pdf_bytes([it])
                src = fitz.open(stream=img_pdf, filetype="pdf")
                out.insert_pdf(src)
                src.close()
        return out.tobytes()
    finally:
        try:
            out.close()
        except Exception:
            pass


def _group_uploads_for_merge(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Group uploads into candidate multi-page sets based on filename suffixes."""
    page_re = re.compile(r"(?i)(?:[_\\-\\s]*(?:page|pg|p)\\s*\\d+)$")
    num_re = re.compile(r"(?i)(?:[_\\-\\s]+\\d+|\\s*\\(\\d+\\))$")

    labeled: Dict[str, List[Dict[str, Any]]] = {}
    unlabeled: List[Dict[str, Any]] = []
    for it in items:
        base = os.path.splitext(it.get("name") or "")[0].strip()
        m = page_re.search(base)
        if m:
            key = (base[:m.start()] or base).strip() or base
            labeled.setdefault(key, []).append(it)
        else:
            unlabeled.append(it)

    groups: List[Dict[str, Any]] = []
    for key, arr in labeled.items():
        groups.append({"key": key, "items": sorted(arr, key=lambda x: x.get("idx", 0))})

    if unlabeled:
        cand_map: Dict[str, List[Dict[str, Any]]] = {}
        for it in unlabeled:
            base = os.path.splitext(it.get("name") or "")[0].strip()
            m2 = num_re.search(base)
            if m2:
                cand = (base[:m2.start()] or base).strip()
                if cand:
                    cand_map.setdefault(cand, []).append(it)
        used_idx = set()
        for cand, arr in cand_map.items():
            if len(arr) >= 2:
                groups.append({"key": cand, "items": sorted(arr, key=lambda x: x.get("idx", 0))})
                for it in arr:
                    used_idx.add(it.get("idx"))
        for it in sorted(unlabeled, key=lambda x: x.get("idx", 0)):
            if it.get("idx") in used_idx:
                continue
            base = os.path.splitext(it.get("name") or "")[0].strip()
            groups.append({"key": base or (it.get("name") or "").strip(), "items": [it]})

    # Preserve original order by first appearance
    groups.sort(key=lambda g: min(i.get("idx", 0) for i in g.get("items") or [g]))
    return groups


def _resolve_pdftotext_exe() -> Optional[str]:
    try:
        from shutil import which as _which
        found = _which("pdftotext")
        if found:
            return found
    except Exception:
        pass
    candidate = r"C:\\poppler-25.12.0\\Library\\bin\\pdftotext.exe"
    return candidate if os.path.exists(candidate) else None


def _pdf_page_text_single(pdf_bytes: bytes, page_no: int) -> str:
    exe = _resolve_pdftotext_exe()
    if exe:
        try:
            import subprocess
            import tempfile
            with tempfile.NamedTemporaryFile(delete=False, suffix=".pdf") as tf:
                tf.write(pdf_bytes or b"")
                tmp_path = tf.name
            try:
                res = subprocess.run(
                    [exe, "-f", str(page_no), "-l", str(page_no), "-layout", "-nopgbrk", "-enc", "UTF-8", tmp_path, "-"],
                    capture_output=True,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                )
                return (res.stdout or "").strip()
            finally:
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass
        except Exception:
            pass
    if fitz:
        try:
            doc = fitz.open(stream=pdf_bytes, filetype="pdf")
            try:
                page = doc.load_page(max(0, int(page_no) - 1))
                return (page.get_text("text") or "").strip()
            finally:
                doc.close()
        except Exception:
            pass
    return ""


def _pdf_page_texts(pdf_bytes: bytes, max_pages: int = 2) -> List[str]:
    """Best-effort per-page PDF text extraction for scan-vs-text routing."""
    texts: List[str] = []
    try:
        cap = max(1, int(max_pages or 1))
    except Exception:
        cap = 1
    try:
        total = int(_pdf_page_count(pdf_bytes) or 0)
    except Exception:
        total = 0
    pages = min(cap, total) if total > 0 else cap
    for i in range(1, pages + 1):
        try:
            texts.append(_pdf_page_text_single(pdf_bytes, i))
        except Exception:
            texts.append("")
    return texts


def _pdf_text_char_score(text: str) -> int:
    try:
        s = re.sub(r"\s+", "", str(text or ""))
        if not s:
            return 0
        return len(re.findall(r"[A-Za-z0-9]", s))
    except Exception:
        return 0


def _pdf_detect_type_from_pages(page_texts: List[str], threshold: int = 50) -> str:
    """Classify a PDF as digital, scanned, or mixed from per-page text density."""
    if not page_texts:
        return "scanned"
    try:
        scores = [_pdf_text_char_score(t) for t in page_texts]
        sparse = [s < int(threshold or 50) for s in scores]
        if all(sparse):
            return "scanned"
        if any(sparse):
            return "mixed"
        return "digital"
    except Exception:
        return "mixed"


def _pdf_render_selected_pages(pdf_bytes: bytes, page_numbers: List[int], dpi: int = 250, progress_cb=None, progress_label: str = "") -> Dict[int, "Image.Image"]:
    """Render selected 1-based PDF pages to PIL images."""
    if not fitz or Image is None:
        raise RuntimeError("PDF rasterization unavailable. Install PyMuPDF (pymupdf) to enable OCR on PDFs.")
    out: Dict[int, "Image.Image"] = {}
    wanted = [int(p) for p in page_numbers if int(p) > 0]
    if not wanted:
        return out
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        zoom = float(dpi) / 72.0
        mat = fitz.Matrix(zoom, zoom)
        total = len(wanted)
        for idx, page_no in enumerate(wanted, start=1):
            if callable(progress_cb):
                try:
                    progress_cb(idx, total, progress_label)
                except Exception:
                    pass
            page = doc.load_page(page_no - 1)
            pix = page.get_pixmap(matrix=mat, alpha=False)
            out[page_no] = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
        doc.close()
    except Exception as _e:
        raise RuntimeError(f"PDF rasterization failed: {_e}") from _e
    return out


def _split_pdf_self_contained_invoices(item: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Split Dhamecha-style combined PDFs into invoice segments.

    Supports mixed batches where some invoices are 1 page and others span
    multiple pages, separated by blank pages.
    """
    mime = str(item.get("mime") or "").lower()
    if mime != "application/pdf" or not fitz:
        return []
    pdf_bytes = item.get("bytes") or b""
    if not pdf_bytes:
        return []
    try:
        src = fitz.open(stream=pdf_bytes, filetype="pdf")
    except Exception:
        return []
    try:
        total_pages = int(src.page_count or 0)
        if total_pages <= 1:
            return []

        segments: List[Dict[str, Any]] = []
        current_pages: List[int] = []
        current_invoice_no = ""
        current_first_page = 0
        for page_no in range(1, total_pages + 1):
            txt = _pdf_page_text_single(pdf_bytes, page_no)
            text_u = txt.upper()
            if not txt.strip():
                if current_pages:
                    segments.append(
                        {
                            "pages": list(current_pages),
                            "invoice_no": current_invoice_no,
                            "first_page": current_first_page,
                        }
                    )
                    current_pages = []
                    current_invoice_no = ""
                    current_first_page = 0
                continue
            inv_match = re.search(r"\bINVOICE\s*:\s*([A-Z0-9\-\/]+)\b", txt, flags=re.I)
            if not inv_match:
                return []
            invoice_no = (inv_match.group(1) or "").strip()
            looks_dhamecha = _looks_like_dhamecha_invoice(txt) or ("DHAMECHA" in text_u)
            page_match = re.search(r"\bPAGE\s*(\d+)\s*OF\s*(\d+)\b", txt, flags=re.I)
            if not looks_dhamecha or not page_match:
                return []
            page_idx = int(page_match.group(1) or 0)
            page_total = int(page_match.group(2) or 0)
            if page_idx <= 0 or page_total <= 0 or page_idx > page_total:
                return []

            if not current_pages:
                if page_idx != 1:
                    return []
                current_pages = [page_no]
                current_invoice_no = invoice_no
                current_first_page = page_no
                continue

            if invoice_no != current_invoice_no:
                if page_idx != 1:
                    return []
                segments.append(
                    {
                        "pages": list(current_pages),
                        "invoice_no": current_invoice_no,
                        "first_page": current_first_page,
                    }
                )
                current_pages = [page_no]
                current_invoice_no = invoice_no
                current_first_page = page_no
                continue
            if page_idx != (len(current_pages) + 1):
                return []
            current_pages.append(page_no)

        if current_pages:
            segments.append(
                {
                    "pages": list(current_pages),
                    "invoice_no": current_invoice_no,
                    "first_page": current_first_page,
                }
            )

        if len(segments) <= 1:
            return []

        base = os.path.splitext(item.get("name") or "document.pdf")[0].strip() or "document"
        out: List[Dict[str, Any]] = []
        for seq, seg in enumerate(segments, start=1):
            page_numbers = list(seg.get("pages") or [])
            invoice_no = str(seg.get("invoice_no") or "").strip()
            first_page = int(seg.get("first_page") or (page_numbers[0] if page_numbers else 0))
            if not page_numbers or not invoice_no:
                return []
            child = fitz.open()
            try:
                for page_no in page_numbers:
                    child.insert_pdf(src, from_page=page_no - 1, to_page=page_no - 1)
                child_bytes = child.tobytes()
            finally:
                child.close()
            safe_inv = _safe_filename(invoice_no or f"page_{page_no}")
            out.append(
                {
                    "idx": int(item.get("idx", 0)) + (seq / 100.0),
                    "name": f"{_safe_filename(base)}_{safe_inv}.pdf",
                    "bytes": child_bytes,
                    "mime": "application/pdf",
                    "split_from": item.get("name") or "",
                    "source_names": [item.get("name") or ""],
                    "source_page": first_page,
                    "source_pages": page_numbers,
                    "detected_invoice_number": invoice_no,
                }
            )
        return out
    except Exception:
        return []
    finally:
        try:
            src.close()
        except Exception:
            pass


def _prepare_docs_for_processing(items: List[Dict[str, Any]], combine_multi: bool) -> Tuple[List[Dict[str, Any]], List[str]]:
    """Return processing docs list (possibly merged) and warnings."""
    warns: List[str] = []
    prepared_items: List[Dict[str, Any]] = []
    for it in items or []:
        split_docs = _split_pdf_self_contained_invoices(it)
        if split_docs:
            prepared_items.extend(split_docs)
            try:
                warns.append(f"Split '{it.get('name') or 'PDF'}' into {len(split_docs)} separate invoice documents.")
            except Exception:
                pass
        else:
            prepared_items.append(it)

    if not combine_multi or len(prepared_items) <= 1:
        return prepared_items, warns

    # Combine all uploads into one multi-page document (single extraction)
    try:
        merged_pdf = _merge_items_to_pdf(prepared_items)
        base = os.path.splitext(prepared_items[0].get("name") or "merged")[0].strip() if prepared_items else "merged"
        merged_name = _safe_filename(base or "merged") + "_merged.pdf"
        out = [
            {
                "idx": 0,
                "name": merged_name,
                "bytes": merged_pdf,
                "mime": "application/pdf",
                "merged": True,
                "source_names": [gi.get("name") for gi in prepared_items],
            }
        ]
        return out, warns
    except Exception as e:
        warns.append(f"Could not merge all pages. Processing pages individually. ({e})")
        return prepared_items, warns


def _email_html_to_text(html: str) -> str:
    text = re.sub(r"(?is)<(script|style).*?>.*?</\1>", " ", html or "")
    text = re.sub(r"(?i)<br\s*/?>", "\n", text)
    text = re.sub(r"(?i)</p\s*>", "\n", text)
    text = re.sub(r"(?s)<[^>]+>", " ", text)
    text = unescape(text)
    return "\n".join(_collapse_spaces(line) for line in text.splitlines() if line.strip())


def _email_attachment_score(att: Dict[str, Any]) -> int:
    name = str(att.get("name") or "")
    name_u = name.upper()
    mime = str(att.get("mime") or "").lower()
    size = len(att.get("bytes") or b"")
    is_pdf = name_u.endswith(".PDF") or mime == "application/pdf"
    is_image = mime.startswith("image/") or name_u.endswith((".PNG", ".JPG", ".JPEG"))
    if not is_pdf and not is_image:
        return -100000
    if is_image and re.fullmatch(r"IMAGE\d+\.(PNG|JPG|JPEG)", name_u):
        return -100000
    if is_image and size < 100000:
        return -100000
    score = min(size // 1024, 20000)
    if is_pdf:
        score += 50000
    if re.search(r"\b(INVOICE|INV|BILL|RECEIPT|STATEMENT)\b", name_u):
        score += 15000
    if re.search(r"\b(LOGO|SIGNATURE|BANNER|ICON)\b", name_u):
        score -= 30000
    return score


def _extract_email_upload_item(item: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], str]:
    name = str(item.get("name") or "email.eml")
    data = item.get("bytes") or b""
    try:
        msg = BytesParser(policy=policy.default).parsebytes(data)
    except Exception as e:
        return None, f"Could not read email file {name}: {e}"

    text_parts: List[str] = []
    html_parts: List[str] = []
    attachments: List[Dict[str, Any]] = []
    for part in msg.walk():
        ctype = (part.get_content_type() or "").lower()
        disp = (part.get_content_disposition() or "").lower()
        fn = part.get_filename() or ""
        if fn or disp == "attachment":
            payload = part.get_payload(decode=True) or b""
            if payload:
                mime = ctype if ctype and ctype != "application/octet-stream" else _guess_mime_type(fn, payload)
                attachments.append({"name": fn or "attachment", "mime": mime, "bytes": payload})
            continue
        if ctype == "text/plain":
            try:
                text_parts.append(str(part.get_content() or ""))
            except Exception:
                pass
        elif ctype == "text/html":
            try:
                html_parts.append(_email_html_to_text(str(part.get_content() or "")))
            except Exception:
                pass

    ranked = sorted(attachments, key=_email_attachment_score, reverse=True)
    selected = ranked[0] if ranked and _email_attachment_score(ranked[0]) > 0 else None
    if not selected:
        return None, f"No invoice PDF/image attachment found in email {name}."

    body = "\n\n".join(p for p in text_parts if p.strip())
    if not body.strip():
        body = "\n\n".join(p for p in html_parts if p.strip())
    subject = str(msg.get("subject") or "")
    sender = str(msg.get("from") or "")
    email_context = (
        f"Email File: {name}\n"
        f"Email Subject: {subject}\n"
        f"Email From: {sender}\n"
        f"Selected invoice attachment: {selected.get('name') or ''}\n\n"
        f"{body}"
    ).strip()
    return {
        "idx": item.get("idx", 0),
        "name": str(selected.get("name") or name),
        "bytes": selected.get("bytes") or b"",
        "mime": selected.get("mime") or _guess_mime_type(str(selected.get("name") or ""), selected.get("bytes") or b""),
        "source_email_name": name,
        "email_context": email_context,
    }, ""


def _expand_email_upload_items(items: List[Dict[str, Any]]) -> Tuple[List[Dict[str, Any]], List[str]]:
    out: List[Dict[str, Any]] = []
    warns: List[str] = []
    for item in items or []:
        name = str(item.get("name") or "")
        mime = str(item.get("mime") or _guess_mime_type(name, item.get("bytes") or b"") or "").lower()
        if name.lower().endswith(".eml") or mime == "message/rfc822":
            extracted, warn = _extract_email_upload_item(item)
            if warn:
                warns.append(warn)
            if extracted:
                out.append(extracted)
            continue
        out.append(item)
    return out, warns


def _pdf_to_images(pdf_bytes: bytes, dpi: int = 250, max_pages: int = 2, progress_cb=None, progress_label: str = "") -> List["Image.Image"]:
    """Render PDF pages to PIL images (for OCR), with optional per-page progress callback."""
    if not fitz or Image is None:
        raise RuntimeError("PDF rasterization unavailable. Install PyMuPDF (pymupdf) to enable OCR on PDFs.")
    try:
        doc = fitz.open(stream=pdf_bytes, filetype="pdf")
        try:
            total_pages = int(doc.page_count or 0)
        except Exception:
            total_pages = 0
        cap = max(1, int(max_pages or 1))
        captured = min(cap, total_pages) if total_pages > 0 else cap

        imgs: List["Image.Image"] = []
        zoom = float(dpi) / 72.0
        mat = fitz.Matrix(zoom, zoom)

        for i, page in enumerate(doc):
            if i >= cap:
                break
            if callable(progress_cb):
                try:
                    progress_cb(i + 1, captured, progress_label)
                except Exception:
                    pass

            pix = page.get_pixmap(matrix=mat, alpha=False)
            img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
            imgs.append(img)

        doc.close()
        return imgs
    except Exception as _e:
        raise RuntimeError(f"PDF rasterization failed: {_e}") from _e


def _prep_img(img):
    """Lightweight image pre-processing to improve OCR stability.

    Safe for all suppliers (Booker/Parfetts etc.). Keeps behaviour minimal:
    - Correct orientation (EXIF) when available
    - Convert to grayscale
    - Auto-contrast
    - Upscale small pages for better character recognition
    """
    try:
        if img is None:
            return img
        # PIL may be optional; if missing, return as-is
        if Image is None:
            return img
        if ImageOps is not None:
            try:
                img = ImageOps.exif_transpose(img)
            except Exception:
                pass
        # Normalise mode
        try:
            if img.mode not in ("RGB", "L"):
                img = img.convert("RGB")
        except Exception:
            pass
        # Grayscale + contrast
        try:
            img = img.convert("L")
        except Exception:
            pass
        if ImageOps is not None:
            try:
                img = ImageOps.autocontrast(img)
            except Exception:
                pass
        # Upscale small images (helps OCR engines)
        try:
            w, h = img.size
            if max(w, h) < 1600:
                img = img.resize((w * 2, h * 2))
        except Exception:
            pass
        return img
    except Exception:
        return img


def _prep_img_photo(img):
    """Pre-process phone photos: crop to document if possible, then normalize."""
    try:
        if img is None or Image is None:
            return img
        # Correct EXIF orientation and ensure RGB
        try:
            if ImageOps is not None:
                img = ImageOps.exif_transpose(img)
        except Exception:
            pass
        try:
            if img.mode != "RGB":
                img = img.convert("RGB")
        except Exception:
            pass

        # Try to detect and deskew the document region (OpenCV if available)
        try:
            import numpy as _np  # type: ignore
            import cv2  # type: ignore

            arr = _np.asarray(img)
            h0, w0 = arr.shape[:2]
            scale = 1.0
            if max(h0, w0) > 1800:
                scale = 1800.0 / float(max(h0, w0))
                arr = cv2.resize(arr, (int(w0 * scale), int(h0 * scale)))

            gray = cv2.cvtColor(arr, cv2.COLOR_RGB2GRAY)
            blur = cv2.GaussianBlur(gray, (5, 5), 0)
            edges = cv2.Canny(blur, 50, 150)
            cnts, _ = cv2.findContours(edges, cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE)
            cnts = sorted(cnts, key=cv2.contourArea, reverse=True)[:12]
            doc = None
            best_score = 0.0
            for c in cnts:
                area = cv2.contourArea(c)
                if area <= 0:
                    continue
                peri = cv2.arcLength(c, True)
                approx = cv2.approxPolyDP(c, 0.02 * peri, True)
                if len(approx) != 4:
                    continue
                pts_c = approx.reshape(4, 2).astype("float32")
                # Prefer A4-like aspect ratio (portrait or landscape)
                try:
                    x_min, y_min = pts_c.min(axis=0)
                    x_max, y_max = pts_c.max(axis=0)
                    w_box = max(1.0, float(x_max - x_min))
                    h_box = max(1.0, float(y_max - y_min))
                    aspect = h_box / w_box if h_box >= w_box else w_box / h_box
                except Exception:
                    aspect = 1.41
                aspect_score = max(0.0, 1.0 - (abs(aspect - 1.41) / 0.8))
                score = float(area) * (0.6 + 0.4 * aspect_score)
                if score > best_score:
                    best_score = score
                    doc = approx
            if doc is not None:
                pts = doc.reshape(4, 2).astype("float32")

                def _order(pts_in):
                    s = pts_in.sum(axis=1)
                    diff = _np.diff(pts_in, axis=1)
                    out = _np.zeros((4, 2), dtype="float32")
                    out[0] = pts_in[_np.argmin(s)]   # top-left
                    out[2] = pts_in[_np.argmax(s)]   # bottom-right
                    out[1] = pts_in[_np.argmin(diff)]  # top-right
                    out[3] = pts_in[_np.argmax(diff)]  # bottom-left
                    return out

                rect = _order(pts)
                # Scale back to original coordinates
                rect /= float(scale)

                (tl, tr, br, bl) = rect
                widthA = _np.linalg.norm(br - bl)
                widthB = _np.linalg.norm(tr - tl)
                heightA = _np.linalg.norm(tr - br)
                heightB = _np.linalg.norm(tl - bl)
                maxW = int(max(widthA, widthB))
                maxH = int(max(heightA, heightB))

                dst = _np.array([[0, 0], [maxW - 1, 0], [maxW - 1, maxH - 1], [0, maxH - 1]], dtype="float32")
                M = cv2.getPerspectiveTransform(rect, dst)
                warped = cv2.warpPerspective(_np.asarray(img), M, (maxW, maxH))
                img = Image.fromarray(warped)
        except Exception:
            pass

        # Light normalization after crop (prefer CV2 if available)
        try:
            img = img.convert("L")
        except Exception:
            pass
        try:
            import numpy as _np  # type: ignore
            import cv2  # type: ignore

            arr = _np.asarray(img)
            if arr.ndim == 3:
                arr = cv2.cvtColor(arr, cv2.COLOR_RGB2GRAY)
            # CLAHE improves low-contrast phone photos without crushing highlights
            clahe = cv2.createCLAHE(clipLimit=2.0, tileGridSize=(8, 8))
            arr = clahe.apply(arr)
            # Mild denoise + sharpen
            arr = cv2.bilateralFilter(arr, d=5, sigmaColor=50, sigmaSpace=50)
            kernel = _np.array([[0, -1, 0], [-1, 5, -1], [0, -1, 0]], dtype="float32")
            arr = cv2.filter2D(arr, -1, kernel)
            img = Image.fromarray(arr)
        except Exception:
            if ImageOps is not None:
                try:
                    img = ImageOps.autocontrast(img)
                except Exception:
                    pass

        # Upscale small images (helps OCR engines with small text)
        try:
            w, h = img.size
            if max(w, h) < 2000:
                img = img.resize((w * 2, h * 2))
        except Exception:
            pass
        return img
    except Exception:
        return img


def _prep_img_photo_strong(img):
    """Stronger pre-processing for challenging phone photos."""
    try:
        img = _prep_img_photo(img)
        if img is None or Image is None:
            return img
        try:
            import numpy as _np  # type: ignore
            import cv2  # type: ignore

            arr = _np.asarray(img)
            if arr.ndim == 3:
                arr = cv2.cvtColor(arr, cv2.COLOR_RGB2GRAY)
            # Adaptive thresholding can recover faint text on glossy paper
            arr = cv2.adaptiveThreshold(
                arr, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY, 31, 7
            )
            arr = cv2.medianBlur(arr, 3)
            img = Image.fromarray(arr)
        except Exception:
            pass
        return img
    except Exception:
        return img


def _looks_like_bad_doc_crop(src_img, out_img) -> bool:
    """Detect failed document-detect warps that collapse the page into a strip."""
    try:
        if src_img is None or out_img is None or not hasattr(src_img, "size") or not hasattr(out_img, "size"):
            return False
        sw, sh = src_img.size
        ow, oh = out_img.size
        if min(sw, sh, ow, oh) <= 0:
            return False
        src_area = float(sw * sh)
        out_area = float(ow * oh)
        src_aspect = float(sw) / float(sh) if sh else 0.0
        out_aspect = float(ow) / float(oh) if oh else 0.0
        width_ratio = float(ow) / float(sw) if sw else 1.0
        area_ratio = out_area / src_area if src_area else 1.0
        if width_ratio < 0.38:
            return True
        if area_ratio < 0.22:
            return True
        if src_aspect >= 0.45 and out_aspect < 0.30:
            return True
    except Exception:
        return False
    return False


def _prep_img_photo_safe(img):
    """Run phone-photo preprocessing, but fall back if document detection over-crops."""
    try:
        if img is None or Image is None:
            return img
        src = img
        try:
            if ImageOps is not None:
                src = ImageOps.exif_transpose(src)
        except Exception:
            pass
        try:
            if src.mode != "RGB":
                src = src.convert("RGB")
        except Exception:
            pass
        out = _prep_img_photo(src)
        if _looks_like_bad_doc_crop(src, out):
            return src
        return out
    except Exception:
        return img


def _crop_booker_items_region(img, top: float = 0.20, bottom: float = 0.85, side: float = 0.03):
    """Crop the likely line-items region for Booker invoices (phone photos)."""
    try:
        if img is None or Image is None:
            return img
        w, h = img.size
        if w < 200 or h < 200:
            return img
        # Heuristic: skip header/top and footer/bottom
        y0 = int(h * max(0.0, min(0.6, top)))
        y1 = int(h * max(0.4, min(1.0, bottom)))
        # Narrow sides slightly to avoid margins and header stamps
        x0 = int(w * max(0.0, min(0.2, side)))
        x1 = int(w * (1.0 - max(0.0, min(0.2, side))))
        if y1 <= y0 or x1 <= x0:
            return img
        return img.crop((x0, y0, x1, y1))
    except Exception:
        return img


def _photo_adjustments_from_settings(settings: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "photo_auto_deskew": bool(settings.get("booker_photo_auto_deskew", True)),
        "photo_rotate_deg": float(settings.get("booker_photo_rotate_deg", 0.0) or 0.0),
        "photo_contrast": float(settings.get("booker_photo_contrast", 1.0) or 1.0),
        "photo_brightness": float(settings.get("booker_photo_brightness", 1.0) or 1.0),
        "photo_sharpness": float(settings.get("booker_photo_sharpness", 1.0) or 1.0),
        "photo_scan_like": bool(settings.get("booker_photo_scan_like", False)),
    }


def _photo_adjustment_cache_key(settings: Dict[str, Any]) -> str:
    try:
        cfg = _photo_adjustments_from_settings(settings)
        parts = [
            f"deskew={1 if cfg.get('photo_auto_deskew') else 0}",
            f"rot={round(float(cfg.get('photo_rotate_deg', 0.0)), 2)}",
            f"con={round(float(cfg.get('photo_contrast', 1.0)), 2)}",
            f"bri={round(float(cfg.get('photo_brightness', 1.0)), 2)}",
            f"sha={round(float(cfg.get('photo_sharpness', 1.0)), 2)}",
            f"scan={1 if cfg.get('photo_scan_like') else 0}",
            f"dups={round(float(settings.get('doctr_upscale', 1.0) or 1.0), 2)}",
            f"dsp={1 if settings.get('doctr_strong_photo', False) else 0}",
        ]
        return "photo:" + "|".join(parts)
    except Exception:
        return ""


def _apply_photo_adjustments(img, cfg_or_dict):
    """Apply manual photo adjustments (rotate/contrast/brightness/sharpness/scan-like)."""
    try:
        if img is None or Image is None:
            return img
        if isinstance(cfg_or_dict, dict):
            cfg = cfg_or_dict
        else:
            cfg = dataclasses.asdict(cfg_or_dict)

        angle = float(cfg.get("photo_rotate_deg", 0.0) or 0.0)
        contrast = float(cfg.get("photo_contrast", 1.0) or 1.0)
        brightness = float(cfg.get("photo_brightness", 1.0) or 1.0)
        sharpness = float(cfg.get("photo_sharpness", 1.0) or 1.0)
        scan_like = bool(cfg.get("photo_scan_like", False))

        out = img
        try:
            if angle:
                try:
                    out = out.rotate(angle, expand=True, fillcolor="white")
                except Exception:
                    out = out.rotate(angle, expand=True)
        except Exception:
            pass

        try:
            if ImageEnhance is not None:
                if brightness and abs(brightness - 1.0) >= 0.01:
                    out = ImageEnhance.Brightness(out).enhance(brightness)
                if contrast and abs(contrast - 1.0) >= 0.01:
                    out = ImageEnhance.Contrast(out).enhance(contrast)
                if sharpness and abs(sharpness - 1.0) >= 0.01:
                    out = ImageEnhance.Sharpness(out).enhance(sharpness)
        except Exception:
            pass

        if scan_like:
            try:
                out = out.convert("L")
            except Exception:
                pass
            try:
                if ImageOps is not None:
                    out = ImageOps.autocontrast(out)
            except Exception:
                pass
        return out
    except Exception:
        return img


def _attach_photo_settings(cfg: OcrConfig, settings: Dict[str, Any]) -> OcrConfig:
    try:
        adj = _photo_adjustments_from_settings(settings)
        cfg.auto_image_tuning = bool(settings.get("auto_image_ocr_tuning", True))
        cfg.photo_auto_deskew = bool(adj.get("photo_auto_deskew", True))
        cfg.photo_rotate_deg = float(adj.get("photo_rotate_deg", 0.0) or 0.0)
        cfg.photo_contrast = float(adj.get("photo_contrast", 1.0) or 1.0)
        cfg.photo_brightness = float(adj.get("photo_brightness", 1.0) or 1.0)
        cfg.photo_sharpness = float(adj.get("photo_sharpness", 1.0) or 1.0)
        cfg.photo_scan_like = bool(adj.get("photo_scan_like", False))
        cfg.doctr_upscale = float(settings.get("doctr_upscale", 1.0) or 1.0)
        cfg.doctr_strong_photo = bool(settings.get("doctr_strong_photo", False))
    except Exception:
        pass
    return cfg


def _auto_tune_ocr_cfg_for_image(img, cfg: OcrConfig) -> OcrConfig:
    """Use image characteristics to tune OCR settings automatically."""
    try:
        if img is None or Image is None or not bool(getattr(cfg, "auto_image_tuning", True)):
            return cfg
        tuned = OcrConfig.from_dict(dataclasses.asdict(cfg))
        arr = None
        try:
            import numpy as _np  # type: ignore
            arr = _np.asarray(img.convert("L"))
        except Exception:
            arr = None
        try:
            w, h = img.size
            max_dim = max(int(w or 0), int(h or 0))
        except Exception:
            max_dim = 0
        mean = 0.0
        std = 0.0
        edge_density = 0.0
        blur_score = 999.0
        if arr is not None and getattr(arr, "size", 0):
            try:
                mean = float(arr.mean())
                std = float(arr.std())
            except Exception:
                pass
            try:
                import cv2  # type: ignore
                edges = cv2.Canny(arr, 80, 180)
                edge_density = float((edges > 0).mean())
                blur_score = float(cv2.Laplacian(arr, cv2.CV_64F).var())
            except Exception:
                pass
        if 0 < max_dim < 1100:
            tuned.doctr_upscale = max(float(tuned.doctr_upscale or 1.0), 1.9)
        elif max_dim < 1600:
            tuned.doctr_upscale = max(float(tuned.doctr_upscale or 1.0), 1.5)
        elif max_dim < 2200:
            tuned.doctr_upscale = max(float(tuned.doctr_upscale or 1.0), 1.2)
        if std < 42.0:
            tuned.photo_contrast = max(float(tuned.photo_contrast or 1.0), 1.15)
            tuned.photo_sharpness = max(float(tuned.photo_sharpness or 1.0), 1.12)
        if mean > 182.0 and std < 58.0:
            tuned.photo_scan_like = True
        if mean < 95.0:
            tuned.photo_brightness = max(float(tuned.photo_brightness or 1.0), 1.08)
            tuned.photo_contrast = max(float(tuned.photo_contrast or 1.0), 1.12)
        if std < 30.0 or edge_density < 0.012 or blur_score < 65.0:
            tuned.doctr_strong_photo = True
            tuned.photo_scan_like = True
            tuned.photo_sharpness = max(float(tuned.photo_sharpness or 1.0), 1.18)
        if std > 62.0 and edge_density > 0.05 and blur_score > 120.0:
            tuned.doctr_strong_photo = False
        return tuned
    except Exception:
        return cfg


def _load_external_ocr_preprocessor():
    """Lazy-load the standalone OCR image preprocessor module."""
    cached = getattr(_load_external_ocr_preprocessor, "_cached", None)
    if cached is not None:
        return cached
    try:
        from ocr_image_processor import OCRImagePreprocessor, PreprocessConfig  # type: ignore
        cached = (OCRImagePreprocessor, PreprocessConfig)
    except Exception:
        cached = (None, None)
    _load_external_ocr_preprocessor._cached = cached  # type: ignore[attr-defined]
    return cached


def _advanced_ocr_image_preprocess(img, cfg: Optional[OcrConfig] = None, strong: bool = False):
    """Use the standalone OCR image processor when available, else keep existing preprocessing."""
    try:
        if img is None or Image is None:
            return img
        OCRImagePreprocessor, PreprocessConfig = _load_external_ocr_preprocessor()
        if OCRImagePreprocessor is None or PreprocessConfig is None:
            return img
        deskew_enabled = bool(getattr(cfg, "photo_auto_deskew", True))
        perspective_enabled = bool(strong and deskew_enabled)
        try:
            doctr_upscale = float(getattr(cfg, "doctr_upscale", 1.0) or 1.0)
        except Exception:
            doctr_upscale = 1.0
        base_min_size = 1000 if not strong else 1400
        min_size = int(max(base_min_size, min(2600.0, base_min_size * max(1.0, doctr_upscale))))
        proc_cfg = PreprocessConfig(
            fix_exif_rotation=True,
            deskew=deskew_enabled,
            deskew_max_angle=15.0,
            deskew_method="projection",
            perspective_correction=perspective_enabled,
            binarize=True,
            binarize_method="adaptive" if strong else "sauvola",
            denoise=True,
            denoise_strength=12 if strong else 10,
            output_colormode="L",
            min_image_size=min_size,
            max_image_size=4000,
        )
        result = OCRImagePreprocessor(proc_cfg).process(img)
        out = getattr(result, "pil_image", None)
        if _looks_like_bad_doc_crop(img, out):
            return img
        return out if out is not None else img
    except Exception:
        return img


def _is_poor_ocr(text: str) -> bool:
    t = (text or "").strip()
    if len(t) >= 80:
        return False
    lines = [ln for ln in t.splitlines() if ln.strip()]
    return len(lines) < 3


def _count_code_lines(text: str) -> int:
    try:
        return len(re.findall(r"(?m)^\s*\d{5,7}\b", text or ""))
    except Exception:
        return 0


def _group_tokens_to_lines(tokens: List[Tuple[float, float, str, float]]) -> List[str]:
    """Group (x,y,text,height) tokens into ordered text lines."""
    if not tokens:
        return []
    try:
        heights = [h for _, _, _, h in tokens if h and h > 0]
        if heights:
            heights.sort()
            med_h = heights[len(heights) // 2]
            line_tol = max(12.0, float(med_h) * 0.6)
        else:
            line_tol = 12.0
    except Exception:
        line_tol = 12.0

    tokens.sort(key=lambda t: (t[1], t[0]))
    lines: List[str] = []
    line_bucket: List[Tuple[float, str]] = []
    line_y: Optional[float] = None

    for y, x, txt, _h in tokens:
        if line_y is None:
            line_y = y
            line_bucket = [(x, txt)]
            continue
        if abs(y - line_y) <= line_tol:
            line_bucket.append((x, txt))
            line_y = (line_y * 0.7) + (y * 0.3)
        else:
            line_bucket.sort(key=lambda t: t[0])
            line = " ".join([t for _, t in line_bucket if t])
            if line:
                lines.append(line)
            line_bucket = [(x, txt)]
            line_y = y

    if line_bucket:
        line_bucket.sort(key=lambda t: t[0])
        line = " ".join([t for _, t in line_bucket if t])
        if line:
            lines.append(line)
    return lines


def _deskew_cv2(img):
    try:
        import numpy as _np  # type: ignore
        import cv2  # type: ignore
    except Exception:
        return img
    try:
        if Image is not None and isinstance(img, Image.Image):
            arr = _np.asarray(img.convert("L"))
        else:
            arr = _np.asarray(img)
            if arr.ndim == 3:
                arr = arr[:, :, 0]
        if arr.size < 5000:
            return img
        _th = cv2.threshold(arr, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)[1]
        coords = _np.column_stack(_np.where(_th > 0))
        if coords.shape[0] < 20:
            return img
        angle = cv2.minAreaRect(coords)[-1]
        if angle < -45:
            angle = -(90 + angle)
        else:
            angle = -angle
        (h, w) = arr.shape[:2]
        center = (w // 2, h // 2)
        m = cv2.getRotationMatrix2D(center, angle, 1.0)
        rotated = cv2.warpAffine(arr, m, (w, h), flags=cv2.INTER_CUBIC, borderMode=cv2.BORDER_REPLICATE)
        return Image.fromarray(rotated) if Image is not None else rotated
    except Exception:
        return img


def _prep_img_strong(img):
    """Stronger pre-processing for skew/noisy scans (used as OCR fallback)."""
    try:
        if img is None:
            return img
        if Image is None:
            return img
        img = _prep_img(img)
        img = _deskew_cv2(img)
        try:
            img = img.convert("L")
        except Exception:
            pass
        if ImageFilter is not None:
            try:
                img = img.filter(ImageFilter.MedianFilter(size=3))
            except Exception:
                pass
            try:
                img = img.filter(ImageFilter.UnsharpMask(radius=1, percent=150, threshold=3))
            except Exception:
                pass
        if ImageEnhance is not None:
            try:
                img = ImageEnhance.Contrast(img).enhance(1.5)
            except Exception:
                pass
        try:
            img = img.point(lambda x: 0 if x < 160 else 255, mode="1").convert("L")
        except Exception:
            pass
        if ImageOps is not None:
            try:
                img = ImageOps.autocontrast(img)
            except Exception:
                pass
        return img
    except Exception:
        return img


def _tesseract_ocr_image(img, tesseract_cmd: str = "", page_idx: int = 1):
    """Run Tesseract on a single image and return (text, ocr_lines)."""
    try:
        ok, err = _ensure_import("pytesseract", "pytesseract", auto_install=False)
        if not ok:
            return "", []
        import pytesseract  # type: ignore

        if tesseract_cmd:
            pytesseract.pytesseract.tesseract_cmd = tesseract_cmd
        config = "--oem 3 --psm 6 -c preserve_interword_spaces=1"
        img_used = _prep_img(img)
        txt = pytesseract.image_to_string(img_used, lang="eng", config=config)
        if _is_poor_ocr(txt):
            try:
                # Stronger photo pre-processing + optional extra upscale
                img2 = _advanced_ocr_image_preprocess(img, cfg=OcrConfig(), strong=True)
                img2 = _prep_img_photo_strong(img2)
                try:
                    if Image is not None and hasattr(img2, "size"):
                        w, h = img2.size
                        if max(w, h) < 2400:
                            scale = min(3.0, 5000.0 / float(max(w, h)))
                            if scale > 1.05:
                                img2 = img2.resize((int(w * scale), int(h * scale)), Image.LANCZOS)
                except Exception:
                    pass
                # Try alternate PSM modes to recover text on dense receipts
                configs = [
                    config,
                    "--oem 3 --psm 4 -c preserve_interword_spaces=1",
                    "--oem 3 --psm 11 -c preserve_interword_spaces=1",
                ]
                best_txt = txt or ""
                best_img = img_used
                for cfg_try in configs:
                    try:
                        t_try = pytesseract.image_to_string(img2, lang="eng", config=cfg_try)
                        if len((t_try or "").strip()) > len((best_txt or "").strip()):
                            best_txt = t_try
                            best_img = img2
                    except Exception:
                        pass
                if len((best_txt or "").strip()) > len((txt or "").strip()):
                    img_used = best_img
                    txt = best_txt
            except Exception:
                pass

        ocr_lines: List[Dict[str, Any]] = []
        try:
            data = pytesseract.image_to_data(img_used, lang="eng", config=config, output_type=pytesseract.Output.DICT)
            tokens: List[Tuple[float, float, float, float, str]] = []
            n = len(data.get("text", []))
            for i in range(n):
                t = str(data["text"][i] or "").strip()
                if not t:
                    continue
                try:
                    conf = float(data.get("conf", [])[i])
                    if conf < 0:
                        continue
                except Exception:
                    pass
                x = float(data.get("left", [])[i] or 0)
                y = float(data.get("top", [])[i] or 0)
                w = float(data.get("width", [])[i] or 0)
                h = float(data.get("height", [])[i] or 0)
                tokens.append((x, y, w, h, t))
            if tokens:
                heights = sorted([h for _, _, _, h, _ in tokens if h > 0])
                line_tol = max(12.0, float(heights[len(heights) // 2]) * 0.6) if heights else 12.0
                tokens.sort(key=lambda t: (t[1], t[0]))
                line_bucket: List[Tuple[float, float, float, float, str]] = []
                line_y: Optional[float] = None

                def _flush_line(bucket):
                    if not bucket:
                        return
                    bucket.sort(key=lambda t: t[0])
                    xs = [b[0] for b in bucket]
                    ys = [b[1] for b in bucket]
                    x1s = [b[0] + b[2] for b in bucket]
                    y1s = [b[1] + b[3] for b in bucket]
                    line_txt = " ".join([b[4] for b in bucket if b[4]])
                    if line_txt:
                        ocr_lines.append({
                            "text": line_txt,
                            "bbox": [min(xs), min(ys), max(x1s), max(y1s)],
                            "page": int(page_idx),
                        })

                for x, y, w, h, t in tokens:
                    if line_y is None:
                        line_y = y
                        line_bucket = [(x, y, w, h, t)]
                        continue
                    if abs(y - line_y) <= line_tol:
                        line_bucket.append((x, y, w, h, t))
                        line_y = (line_y * 0.7) + (y * 0.3)
                    else:
                        _flush_line(line_bucket)
                        line_bucket = [(x, y, w, h, t)]
                        line_y = y
                _flush_line(line_bucket)
        except Exception:
            pass

        return txt or "", ocr_lines
    except Exception:
        return "", []


def _scanfallback_first_match(pattern: str, text: str, group: int = 1) -> Optional[str]:
    try:
        m = re.search(pattern, text or "", re.IGNORECASE | re.MULTILINE)
        return m.group(group).strip() if m else None
    except Exception:
        return None


def _scanfallback_clean_amount(amount: str) -> str:
    s = str(amount or "").strip()
    if s.count(",") == 1 and "." not in s:
        return s.replace(",", ".").replace("..", ".").strip()
    return s.replace(",", "").strip()


def _scanfallback_clean_vatcode(vatcode: str) -> str:
    v = str(vatcode or "").strip().upper()
    return {"4": "A", "ES": "E"}.get(v, v)


def _scanfallback_clean_text(value: Optional[str]) -> Optional[str]:
    if value is None:
        return None
    value = str(value).replace("\ufffd", "").replace("\u2018", "").replace("\u2019", "")
    return re.sub(r"\s+", " ", value).strip(" .:-")


def _scanfallback_final_totals_from_summary(text: str) -> Dict[str, str]:
    total_goods = _scanfallback_first_match(r"Total\s+Goods\s*:?\s*[;:\s\u00a3GBP]*([\d,.]+)", text)
    vat_matches = re.findall(r"(?<!incl\s)\bVAT\s*:?\s*[\s\u00a3GBP]*([\d,.]+)", text or "", re.IGNORECASE)
    vat = vat_matches[-1] if vat_matches else None
    total_incl_vat = _scanfallback_first_match(r"Total\s+incl\s+VAT\s*:?\s*[\s\u00a3GBP]*([\d,.]+)", text)
    if total_goods and vat and total_incl_vat:
        return {
            "total_goods": _scanfallback_clean_amount(total_goods),
            "vat": _scanfallback_clean_amount(vat),
            "total_incl_vat": _scanfallback_clean_amount(total_incl_vat),
        }

    booker_totals = re.search(
        r"Total\s+Net\s+Value\s+([\d,.-]+)\s+Total\s+VAT\s+([\d,.-]+)\s+Total\s+([\d,.-]+)",
        text or "",
        re.IGNORECASE,
    )
    if booker_totals:
        total_goods, vat, total_incl_vat = booker_totals.groups()
        return {
            "total_goods": _scanfallback_clean_amount(total_goods),
            "vat": _scanfallback_clean_amount(vat),
            "total_incl_vat": _scanfallback_clean_amount(total_incl_vat),
        }
    return {}


def _scanfallback_extract_vat_rates(text: str) -> Dict[str, str]:
    rates: Dict[str, str] = {}
    for match in re.finditer(r"^([A-Z])[\t ]+(\d+(?:\.\d+)?)\s+", text or "", re.IGNORECASE | re.MULTILINE):
        code, rate = match.groups()
        rates[code.upper()] = rate
    for match in re.finditer(r"^([A-Z]{1,2})[\t ]+[^\n\r]+?-[\t ]*(\d+(?:\.\d+)?)%", text or "", re.IGNORECASE | re.MULTILINE):
        code, rate = match.groups()
        rates[code.upper()] = rate
    # OCR commonly misreads Dhamecha/UK VAT table values. Snap common codes to expected UK bands.
    defaults = {"A": "20", "B": "5", "Z": "0"}
    for code, expected in defaults.items():
        raw = str(rates.get(code) or "").strip()
        try:
            val = float(raw) if raw else None
        except Exception:
            val = None
        if val is None or abs(val - float(expected)) > 0.5:
            rates[code] = expected
    return rates


def _scanfallback_extract_supplier(text: str) -> Optional[str]:
    if re.search(r"Dhamecha", text or "", re.IGNORECASE):
        return "Dhamecha Foods Limited"
    if re.search(r"Booker", text or "", re.IGNORECASE):
        return "Booker Ltd"
    return _scanfallback_first_match(r"^([A-Z][A-Za-z&.,\s]+(?:Limited|Ltd))\b", text)


def _scanfallback_extract_customer(text: str) -> Optional[str]:
    customer = _scanfallback_first_match(r"\bMrk\.?:\s*([^\n\r]+)", text)
    if customer:
        return _scanfallback_clean_text(customer)
    return _scanfallback_first_match(r"\bCustomer[:\s]+([^\n\r]+)", text)


def _scanfallback_find_invoice_no(text: str) -> Dict[str, Optional[str]]:
    patterns = [
        re.compile(r"\bINVOICE\s+NO\.?\s*[:#-]?\s*([A-Z0-9/-]+)", re.IGNORECASE),
        re.compile(r"\bINVOICE\b\s*[:#-]\s*([A-Z0-9/-]+)", re.IGNORECASE),
        re.compile(r"\bCREDIT\s+NO\.?\s*[:#-]?\s*([A-Z0-9/-]+)", re.IGNORECASE),
        re.compile(r"\bCREDIT\b\s*[:#-]\s*([A-Z0-9/-]+)", re.IGNORECASE),
    ]
    for line_number, line in enumerate((text or "").splitlines(), start=1):
        for pattern in patterns:
            m = pattern.search(line)
            if m:
                value = m.group(1).strip()
                if "/" in value and re.search(r"\d/\d", value):
                    value = value.replace("/", "")
                return {
                    "value": value,
                    "line_number": str(line_number),
                    "line": line.strip(),
                }
    return {"value": None, "line_number": None, "line": None}


def _scanfallback_find_date(text: str):
    date_match = re.search(
        r"(\d{1,2}\s+[A-Za-z]+\s+\d{4}),?\s*(\d{1,2}:\d{2})",
        text or "",
        re.IGNORECASE,
    )
    if not date_match:
        date_match = re.search(r"(\d{1,2}[./-]\d{1,2}[./-]\d{4})", text or "")
    if not date_match:
        date_match = re.search(r"(\d{1,2}[./-]\d{1,2}[./-]\d{2})", text or "")
    return date_match


def _scanfallback_normalise_invoice_date(raw_date: Optional[str]) -> str:
    s = str(raw_date or "").strip()
    if not s:
        return ""
    s2 = re.sub(r"\s+", " ", s)
    for fmt in ("%d %b %Y", "%d %B %Y", "%d.%m.%Y", "%d/%m/%Y", "%d-%m-%Y", "%d.%m.%y", "%d/%m/%y", "%d-%m-%y"):
        try:
            return datetime.strptime(s2, fmt).date().isoformat()
        except Exception:
            pass
    return s


def _scanfallback_extract_header_data(text: str, header_text: str = "") -> Dict[str, Any]:
    date_match = _scanfallback_find_date(header_text) or _scanfallback_find_date(text)
    summary_totals = _scanfallback_final_totals_from_summary(text)
    invoice_no_header = _scanfallback_find_invoice_no(header_text)
    invoice_no_text = _scanfallback_find_invoice_no(text)
    invoice_no = invoice_no_header
    if (not invoice_no["value"]) or (
        invoice_no_text.get("value")
        and len(str(invoice_no_text.get("value") or "")) > len(str(invoice_no_header.get("value") or ""))
    ):
        invoice_no = invoice_no_text
    return {
        "supplierName": _scanfallback_extract_supplier(text) or "",
        "customerName": _scanfallback_extract_customer(text) or "",
        "invoiceDate": _scanfallback_normalise_invoice_date(date_match.group(1).strip() if date_match else ""),
        "invoiceNumber": invoice_no["value"] or "",
        "currency": "GBP",
        "totalNet": _safe_float(summary_totals.get("total_goods")),
        "totalVat": _safe_float(summary_totals.get("vat")),
        "totalGross": _safe_float(summary_totals.get("total_incl_vat")),
    }


def _scanfallback_parse_line_item(line: str, vat_rates: Dict[str, str], description_prefix: Optional[str] = None) -> Optional[Dict[str, Any]]:
    booker_match = re.match(
        r"^([A-Z]\d{6})\s+\S+\s+(.+?)\s+(\S+)\s+(\d+)\s+([\d,.\-]+)\s+([\d,.\-]+)\s+([A-Z0-9]+)\s+([\d,.\-]+)$",
        line.strip(),
        re.IGNORECASE,
    )
    if booker_match:
        code, description, unit_size, case_pack, price, quantity, vatcode, net_value = booker_match.groups()
        if description_prefix:
            description = f"{description_prefix} {description}"
        vatcode = _scanfallback_clean_vatcode(vatcode)
        vat_rate = _safe_float(vat_rates.get(vatcode.upper()))
        line_net = _safe_float(_scanfallback_clean_amount(net_value))
        vat_amount = round(line_net * (vat_rate / 100.0), 2) if vat_rate > 0 else 0.0
        return {
            "lineNo": None,
            "code": code,
            "description": _scanfallback_clean_text(description) or "",
            "casePack": int(_safe_float(case_pack)),
            "unitSize": unit_size,
            "qty": _safe_float(_scanfallback_clean_amount(quantity)),
            "unitPrice": _safe_float(_scanfallback_clean_amount(price)),
            "lineNet": line_net,
            "vatRate": vat_rate,
            "vatAmount": vat_amount,
            "lineGross": round(line_net + vat_amount, 2),
            "stdRrp": 0.0,
            "por": 0.0,
            "vatCode": vatcode.upper(),
        }

    patterns = [
        (
            r"^(\d{5,6})\s+(.+?)\s+(-|:|\.|\d+)\s+(\S+)\s+([\d,.\-]+)\s+([\d,.\-]+)\s+([\d,.\-]+P?)\s+(\S+)\s+([\d.]+%)\s+([A-Z0-9]+)$",
            "full",
        ),
        (
            r"^(\d{5,6})\s+(.+?)\s+(-|:|\.|\d+)\s+(\S+)\s+([\d,.\-]+)\s+([\d,.\-]+)\s+(\S+)\s+([\d.]+%)\s+([A-Z0-9]+)$",
            "missing_ext_price",
        ),
        (
            r"^(\d{5,6})\s+(.+?)\s+(\S+)\s+([\d,.\-]+)\s+([\d,.\-]+)\s+([\d,.\-]+)\s+([\d,.\-]+)\s+([\d.]+%)\s+([A-Z0-9]+)$",
            "missing_case_pack",
        ),
    ]

    match = None
    variant = None
    for pattern, name in patterns:
        match = re.match(pattern, line.strip(), re.IGNORECASE)
        if match:
            variant = name
            break
    if not match:
        return None

    if variant == "full":
        code, description, case_pack, unit_size, quantity, price, ext_price, rrp, por, vatcode = match.groups()
    elif variant == "missing_ext_price":
        code, description, case_pack, unit_size, quantity, price, rrp, por, vatcode = match.groups()
        ext_price = price
    else:
        code, description, unit_size, quantity, price, ext_price, rrp, por, vatcode = match.groups()
        case_pack = ""

    if description_prefix:
        description = f"{description_prefix} {description}"
    vatcode = _scanfallback_clean_vatcode(vatcode)
    vat_rate = _safe_float((vat_rates.get(vatcode.upper()) or str(por or "").replace("%", "")))
    line_net = _safe_float(_scanfallback_clean_amount(ext_price))
    vat_amount = round(line_net * (vat_rate / 100.0), 2) if vat_rate > 0 else 0.0
    return {
        "lineNo": None,
        "code": code,
        "description": _scanfallback_clean_text(description) or "",
        "casePack": int(_safe_float(case_pack)),
        "unitSize": unit_size,
        "qty": _safe_float(_scanfallback_clean_amount(quantity)),
        "unitPrice": _safe_float(_scanfallback_clean_amount(price)),
        "lineNet": line_net,
        "vatRate": vat_rate,
        "vatAmount": vat_amount,
        "lineGross": round(line_net + vat_amount, 2),
        "stdRrp": _safe_float(_scanfallback_clean_amount(rrp)),
        "por": _safe_float(str(por or "").replace("%", "")),
        "vatCode": vatcode.upper(),
    }


def _scanfallback_prev_line_prefix(prev_line: Optional[str]) -> Optional[str]:
    line = _scanfallback_clean_text(prev_line or "")
    if not line:
        return None
    if re.match(r"^\d{5,7}\b", line):
        return None
    if re.search(r"\b(?:ITEM\s*#|PRODUCT DESCRIPTION|UOP|UOS|QTY|PRICE|EXT\.?PRICE|RRP|POR|VAT|TROLLEY|CASES|SINGLES|TOTAL GOODS|TOTAL INCL VAT|INVOICE|DATE/TIME|BUSINESS ID|VAT REG)\b", line, re.IGNORECASE):
        return None
    if not re.search(r"[A-Za-z]", line):
        return None
    if len(line) < 8 or len(line) > 80:
        return None
    return line


def _scanfallback_extract_line_items(text: str) -> List[Dict[str, Any]]:
    vat_rates = _scanfallback_extract_vat_rates(text)
    rows: List[Dict[str, Any]] = []
    description_prefix = None
    in_items_table = False
    prev_nonempty_line: Optional[str] = None
    for raw_line in (text or "").splitlines():
        line = _scanfallback_clean_text(raw_line)
        if not line:
            continue
        upper_line = str(line or "").upper()
        if ("ITEM #" in upper_line or "ITEM#" in upper_line) and ("PRODUCT DESCRIPTION" in upper_line) and ("VAT" in upper_line):
            in_items_table = True
            description_prefix = None
            prev_nonempty_line = line
            continue
        if re.search(r"\b(?:TROLLEY|CASES|SINGLES|ITEMS TOTAL|CODE RATE|VALUE OF GOODS|TOTAL GOODS|TOTAL INCL VAT)\b", line, re.IGNORECASE):
            in_items_table = False
            description_prefix = None
            prev_nonempty_line = line
            continue
        row_prefix = description_prefix
        if not row_prefix and in_items_table:
            row_prefix = _scanfallback_prev_line_prefix(prev_nonempty_line)
        row = _scanfallback_parse_line_item(line, vat_rates, row_prefix)
        if row:
            rows.append(row)
            description_prefix = None
            prev_nonempty_line = line
            continue
        # Scanned invoices sometimes split the description onto the line above the coded row.
        # Keep that line and prepend it to the next parsed item.
        is_prefix_candidate = (
            in_items_table
            and
            not re.match(r"^\d{5,7}\b", line)
            and not re.search(r"\b(?:TROLLEY|CASES|SINGLES|TOTAL|SUB TOTAL|INC\.?\s*VAT|ITEMS TOTAL|CODE RATE|VALUE OF GOODS|INVOICE|DATE/TIME|BUSINESS ID|VAT REG)\b", line, re.IGNORECASE)
            and bool(re.search(r"[A-Za-z]", line))
            and len(re.findall(r"\d", line)) <= 6
            and len(line) >= 8
            and len(line) <= 80
            and not re.search(r"[|]{2,}|[�]{2,}", line)
        )
        if is_prefix_candidate:
            if description_prefix:
                description_prefix = f"{description_prefix} {line}".strip()
            else:
                description_prefix = line
            prev_nonempty_line = line
            continue
        if re.search(r"\b(?:ELFBAR|SKE|LOST\s+MARY|BM6000|KIT|POD|BAR)\b", line, re.IGNORECASE):
            description_prefix = line
        prev_nonempty_line = line
    return rows


def _scanfallback_image_to_cv2(img) -> Any:
    try:
        import numpy as np  # type: ignore
        if Image is not None and hasattr(img, "convert"):
            rgb = img.convert("RGB")
            arr = np.array(rgb)
            return arr[:, :, ::-1].copy()
    except Exception:
        pass
    return None


def _scanfallback_tesseract_image(img, tesseract_cmd: str = "", psm: int = 6) -> str:
    try:
        ok, _ = _ensure_import("pytesseract", "pytesseract", auto_install=False)
        if not ok:
            return ""
        import pytesseract  # type: ignore
        import cv2  # type: ignore
        if tesseract_cmd:
            pytesseract.pytesseract.tesseract_cmd = tesseract_cmd
        img_cv = _scanfallback_image_to_cv2(img)
        if img_cv is None:
            return ""
        gray = cv2.cvtColor(img_cv, cv2.COLOR_BGR2GRAY)
        proc = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)[1]
        return pytesseract.image_to_string(proc, lang="eng", config=f"--oem 3 --psm {int(psm)}")
    except Exception:
        return ""


def _scanfallback_ocr_crop(img, x1: float, y1: float, x2: float, y2: float, psm: int = 6, threshold: bool = False, tesseract_cmd: str = "") -> str:
    try:
        ok, _ = _ensure_import("pytesseract", "pytesseract", auto_install=False)
        if not ok:
            return ""
        import pytesseract  # type: ignore
        import cv2  # type: ignore
        if tesseract_cmd:
            pytesseract.pytesseract.tesseract_cmd = tesseract_cmd
        img_cv = _scanfallback_image_to_cv2(img)
        if img_cv is None:
            return ""
        h, w = img_cv.shape[:2]
        crop = img_cv[int(h * y1):int(h * y2), int(w * x1):int(w * x2)]
        if crop is None or getattr(crop, "size", 0) == 0:
            return ""
        crop = cv2.resize(crop, None, fx=4, fy=4, interpolation=cv2.INTER_CUBIC)
        gray = cv2.cvtColor(crop, cv2.COLOR_BGR2GRAY)
        if threshold:
            gray = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)[1]
        return pytesseract.image_to_string(gray, config=f"--oem 3 --psm {int(psm)}")
    except Exception:
        return ""


def _scanfallback_extract_header_ocr_text(img, tesseract_cmd: str = "") -> str:
    invoice_text = _scanfallback_ocr_crop(img, 0.76, 0.015, 0.97, 0.06, psm=7, tesseract_cmd=tesseract_cmd)
    date_text = _scanfallback_ocr_crop(img, 0.78, 0.045, 0.98, 0.10, psm=6, tesseract_cmd=tesseract_cmd)
    return f"{invoice_text}\n{date_text}".strip()


def _scanfallback_parse_pdf(file_bytes: bytes, max_pages: int = 4, dpi: int = 300, tesseract_cmd: str = "") -> Dict[str, Any]:
    try:
        page_images = _pdf_to_images(file_bytes, dpi=max(250, int(dpi or 300)), max_pages=max(1, int(max_pages or 1)))
    except Exception:
        page_images = []
    if not page_images:
        return {"text": "", "header_text": "", "header": {}, "items": []}
    page_texts: List[str] = []
    for page_number, page_image in enumerate(page_images, start=1):
        page_text = _scanfallback_tesseract_image(page_image, tesseract_cmd=tesseract_cmd, psm=6)
        page_texts.append(f"\n--- Page {page_number} ---\n{page_text}")
    text = "\n".join(page_texts).strip()
    header_text = _scanfallback_extract_header_ocr_text(page_images[0], tesseract_cmd=tesseract_cmd)
    header = _scanfallback_extract_header_data(text, header_text)
    items = _scanfallback_extract_line_items(text)
    return {"text": text, "header_text": header_text, "header": header, "items": items}


def ocr_text_cached(cache_key: str, mime_type: str, cfg_dict: Dict[str, Any], file_bytes: bytes, progress_cb=None, progress_label: str = "") -> str:
    """OCR / PDF text extraction.

    Behaviour:
    - For PDFs, always extracts a text-layer hint (for fallback and for fast-path when not forcing raster OCR).
    - When returning multi-page text (PDF text layer or OCR), inserts clear page separators: "Page N/Total".
    """
    cfg = OcrConfig.from_dict(cfg_dict)
    engine = (cfg.engine or "tesseract").lower().strip()

    # Always pre-load PDF text layer for fallback
    txt_hint = ""
    pdf_page_inputs: List[Dict[str, Any]] = []
    if mime_type == "application/pdf":
        txt_hint = _pdf_text_layer(file_bytes, max_pages=cfg.max_pages, progress_cb=progress_cb, progress_label=progress_label)
        try:
            if bool(getattr(cfg, "auto_pdf_page_routing", True)) and not bool(cfg.force_pdf):
                page_texts = _pdf_page_texts(file_bytes, max_pages=cfg.max_pages)
                pdf_kind = _pdf_detect_type_from_pages(page_texts, threshold=int(getattr(cfg, "pdf_scanned_char_threshold", 50) or 50))
                if pdf_kind == "digital" and page_texts:
                    total = len(page_texts)
                    return "\n\n".join([f"===== Page {i+1}/{total} =====\n{(t or '').strip()}" for i, t in enumerate(page_texts)]).strip()
                if pdf_kind in ("scanned", "mixed"):
                    sparse_pages = []
                    for i, page_text in enumerate(page_texts, start=1):
                        is_sparse = _pdf_text_char_score(page_text) < int(getattr(cfg, "pdf_scanned_char_threshold", 50) or 50)
                        if pdf_kind == "scanned" or bool(getattr(cfg, "pdf_force_ocr_sparse_pages", True) and is_sparse):
                            sparse_pages.append(i)
                    rendered = _pdf_render_selected_pages(
                        file_bytes,
                        sparse_pages if sparse_pages else list(range(1, len(page_texts) + 1)),
                        dpi=cfg.dpi,
                        progress_cb=progress_cb,
                        progress_label=progress_label,
                    )
                    for i, page_text in enumerate(page_texts, start=1):
                        use_ocr = i in rendered
                        pdf_page_inputs.append({
                            "page": i,
                            "source": "ocr" if use_ocr else "text_layer",
                            "text": None if use_ocr else (page_text or ""),
                            "image": rendered.get(i),
                        })
        except Exception:
            pdf_page_inputs = []
        if (not cfg.force_pdf) and txt_hint and len(txt_hint) >= 120 and not pdf_page_inputs:
            return txt_hint

    # Build image list for OCR engines
    if mime_type == "application/pdf":
        if not pdf_page_inputs:
            try:
                imgs = _pdf_to_images(file_bytes, dpi=cfg.dpi, max_pages=cfg.max_pages, progress_cb=progress_cb, progress_label=progress_label)
                pdf_page_inputs = [{"page": i, "source": "ocr", "text": None, "image": img} for i, img in enumerate(imgs, start=1)]
            except Exception:
                if txt_hint:
                    return txt_hint
                raise
    else:
        imgs = [_bytes_to_image(file_bytes)]
        # Photo-specific normalization for phone images (crop/deskew if possible)
        try:
            if imgs and imgs[0] is not None:
                cfg = _auto_tune_ocr_cfg_for_image(imgs[0], cfg)
                img0 = imgs[0]
                if cfg.photo_auto_deskew:
                    img0 = _prep_img_photo_safe(img0)
                else:
                    try:
                        if ImageOps is not None:
                            img0 = ImageOps.exif_transpose(img0)
                    except Exception:
                        pass
                    try:
                        if img0.mode != "RGB":
                            img0 = img0.convert("RGB")
                    except Exception:
                        pass
                img0 = _apply_photo_adjustments(img0, cfg)
                img0 = _advanced_ocr_image_preprocess(img0, cfg=cfg, strong=bool(cfg.doctr_strong_photo))
                imgs = [img0]
        except Exception:
            pass
        pdf_page_inputs = [{"page": 1, "source": "ocr", "text": None, "image": imgs[0] if imgs else None}]

    def _apply_page_separators(page_texts: List[str]) -> List[str]:
        if mime_type == "application/pdf" and page_texts:
            total = len(page_texts)
            return [f"===== Page {i+1}/{total} =====\n{(t or '').strip()}" for i, t in enumerate(page_texts)]
        return [(t or '').strip() for t in page_texts]

    if engine == "tesseract":
        ok, err = _ensure_import("pytesseract", "pytesseract", cfg.auto_install)
        if not ok:
            raise RuntimeError(err)
        import pytesseract  # type: ignore

        if cfg.tesseract_cmd:
            pytesseract.pytesseract.tesseract_cmd = cfg.tesseract_cmd
        config = "--oem 3 --psm 6 -c preserve_interword_spaces=1"
        parts: List[str] = []
        ocr_lines: List[Dict[str, Any]] = []
        for entry in pdf_page_inputs:
            page_idx = int(entry.get("page") or 1)
            if entry.get("text") is not None:
                parts.append(str(entry.get("text") or ""))
                continue
            img = entry.get("image")
            if img is None:
                parts.append("")
                continue
            img = _prep_img(img)
            try:
                img_used = img
                txt = pytesseract.image_to_string(img_used, lang="eng", config=config)
                if _is_poor_ocr(txt):
                    try:
                        if mime_type == "application/pdf":
                            img2 = _prep_img_strong(img)
                        else:
                            img2 = _advanced_ocr_image_preprocess(img, cfg=cfg, strong=True)
                            img2 = _prep_img_photo_strong(img2)
                        txt2 = pytesseract.image_to_string(img2, lang="eng", config=config)
                        if len((txt2 or "").strip()) > len((txt or "").strip()):
                            img_used = img2
                            txt = txt2
                    except Exception:
                        pass
                parts.append(txt)
                # Build line boxes for row-level extraction
                try:
                    data = pytesseract.image_to_data(img_used, lang="eng", config=config, output_type=pytesseract.Output.DICT)
                    tokens: List[Tuple[float, float, float, float, str]] = []
                    n = len(data.get("text", []))
                    for i in range(n):
                        t = str(data["text"][i] or "").strip()
                        if not t:
                            continue
                        try:
                            conf = float(data.get("conf", [])[i])
                            if conf < 0:
                                continue
                        except Exception:
                            pass
                        x = float(data.get("left", [])[i] or 0)
                        y = float(data.get("top", [])[i] or 0)
                        w = float(data.get("width", [])[i] or 0)
                        h = float(data.get("height", [])[i] or 0)
                        tokens.append((x, y, w, h, t))
                    if tokens:
                        heights = sorted([h for _, _, _, h, _ in tokens if h > 0])
                        line_tol = max(12.0, float(heights[len(heights) // 2]) * 0.6) if heights else 12.0
                        tokens.sort(key=lambda t: (t[1], t[0]))
                        line_bucket: List[Tuple[float, float, float, float, str]] = []
                        line_y: Optional[float] = None

                        def _flush_line(bucket):
                            if not bucket:
                                return
                            bucket.sort(key=lambda t: t[0])
                            xs = [b[0] for b in bucket]
                            ys = [b[1] for b in bucket]
                            x1s = [b[0] + b[2] for b in bucket]
                            y1s = [b[1] + b[3] for b in bucket]
                            line_txt = " ".join([b[4] for b in bucket if b[4]])
                            if line_txt:
                                ocr_lines.append({
                                    "text": line_txt,
                                    "bbox": [min(xs), min(ys), max(x1s), max(y1s)],
                                    "page": int(page_idx),
                                })

                        for x, y, w, h, t in tokens:
                            if line_y is None:
                                line_y = y
                                line_bucket = [(x, y, w, h, t)]
                                continue
                            if abs(y - line_y) <= line_tol:
                                line_bucket.append((x, y, w, h, t))
                                line_y = (line_y * 0.7) + (y * 0.3)
                            else:
                                _flush_line(line_bucket)
                                line_bucket = [(x, y, w, h, t)]
                                line_y = y
                        _flush_line(line_bucket)
                except Exception:
                    pass
            except Exception as e:
                # If the PDF has a text layer, fall back to it rather than hard-failing
                if txt_hint:
                    return txt_hint
                raise RuntimeError(
                    "Tesseract OCR is not available on this machine. Install the Tesseract engine and/or set the full path in Admin  System Information  OCR Settings."
                ) from e
        try:
            if ocr_lines:
                _OCR_LINES_CACHE[cache_key] = ocr_lines
        except Exception:
            pass
        parts = _apply_page_separators(parts)
        out_txt = "\n\n".join(parts).strip()
        if (mime_type != "application/pdf") and (not out_txt):
            t_cmd_dbg = _normalize_tesseract_path(cfg.tesseract_cmd or "")
            raise RuntimeError(
                f"Tesseract OCR returned no text for this image. "
                f"(tesseract_cmd='{t_cmd_dbg}' path_ok={_tesseract_path_ok(t_cmd_dbg)}) "
                f"Try increasing DocTR/Tesseract upscale, enabling Scan-like, or improve photo clarity."
            )
        return out_txt

    if engine == "easyocr":
        ok, err = _ensure_import("easyocr", "easyocr", cfg.auto_install)
        if not ok:
            raise RuntimeError(err)
        ok2, err2 = _ensure_import("numpy", "numpy", cfg.auto_install)
        if not ok2:
            raise RuntimeError(err2)
        import easyocr  # type: ignore
        import numpy as np  # type: ignore

        # cache the reader
        if not hasattr(ocr_text_cached, "_easy_reader"):
            ocr_text_cached._easy_reader = easyocr.Reader(["en"], gpu=False)  # type: ignore
        reader = ocr_text_cached._easy_reader  # type: ignore
        parts: List[str] = []
        for entry in pdf_page_inputs:
            if entry.get("text") is not None:
                parts.append(str(entry.get("text") or ""))
                continue
            img = entry.get("image")
            if img is None:
                parts.append("")
                continue
            img = _prep_img(img)
            lines = reader.readtext(np.array(img), detail=0)
            txt = "\n".join(lines)
            if _is_poor_ocr(txt):
                try:
                    if mime_type == "application/pdf":
                        img2 = _prep_img_strong(img)
                    else:
                        img2 = _advanced_ocr_image_preprocess(img, cfg=cfg, strong=True)
                        img2 = _prep_img_photo_strong(img2)
                    lines2 = reader.readtext(np.array(img2), detail=0)
                    txt2 = "\n".join(lines2)
                    if len((txt2 or "").strip()) > len((txt or "").strip()):
                        txt = txt2
                except Exception:
                    pass
            parts.append(txt)
        parts = _apply_page_separators(parts)
        return "\n\n".join(parts).strip()

    if engine == "doctr":
        ok, err = _ensure_import("doctr", "python-doctr", cfg.auto_install)
        if not ok:
            raise RuntimeError(err)
        from doctr.io import DocumentFile  # type: ignore
        from doctr.models import ocr_predictor  # type: ignore

        if not hasattr(ocr_text_cached, "_doctr"):
            ocr_text_cached._doctr = ocr_predictor(pretrained=True)  # type: ignore
        predictor = ocr_text_cached._doctr  # type: ignore
        parts: List[str] = []
        ocr_lines: List[Dict[str, Any]] = []
        ocr_token_lines: List[Dict[str, Any]] = []
        last_img = None
        for entry in pdf_page_inputs:
            page_idx = int(entry.get("page") or 1)
            if entry.get("text") is not None:
                parts.append(str(entry.get("text") or ""))
                continue
            img = entry.get("image")
            if img is None:
                parts.append("")
                continue
            last_img = img
            def _doctr_to_text(img_in) -> str:
                # Doctr is picky about input types; ensure numpy HxWx3 uint8
                import numpy as _np  # type: ignore

                if Image is not None and isinstance(img_in, Image.Image):
                    try:
                        img_in = img_in.convert("RGB")
                    except Exception:
                        pass
                    arr = _np.asarray(img_in)
                else:
                    arr = _np.asarray(img_in)

                # Normalize array to HxWx3 uint8
                try:
                    if arr.ndim == 2:
                        arr = _np.stack([arr] * 3, axis=-1)
                    elif arr.ndim == 3 and arr.shape[2] == 1:
                        arr = _np.repeat(arr, 3, axis=2)
                    arr = arr.astype(_np.uint8, copy=False)
                except Exception:
                    pass

                try:
                    doc = DocumentFile.from_images([arr])
                except Exception:
                    # Fallback: encode as PNG bytes
                    try:
                        import io as _io

                        if Image is not None and isinstance(img_in, Image.Image):
                            buf = _io.BytesIO()
                            img_in.convert("RGB").save(buf, format="PNG")
                            doc = DocumentFile.from_images([buf.getvalue()])
                        else:
                            doc = DocumentFile.from_images([arr])
                    except Exception:
                        doc = DocumentFile.from_images([arr])
                res = predictor(doc)
                txt = ""
                # Prefer structural export to preserve line breaks (better for line-item parsing).
                try:
                    exp = res.export()
                    tokens = []
                    line_texts: List[str] = []
                    # Use pixel scale for line grouping (doctr geometry is normalized 0..1)
                    try:
                        if hasattr(img_in, "size"):
                            w_px, h_px = img_in.size
                        elif hasattr(arr, "shape") and len(arr.shape) >= 2:
                            h_px, w_px = float(arr.shape[0]), float(arr.shape[1])
                        else:
                            w_px, h_px = 1.0, 1.0
                    except Exception:
                        w_px, h_px = 1.0, 1.0
                    for page in exp.get("pages", []):
                        for block in page.get("blocks", []):
                            for line in block.get("lines", []):
                                words = line.get("words", []) or []
                                if words:
                                    try:
                                        word_chunks = []
                                        xs = []
                                        ys = []
                                        for w in words:
                                            val = w.get("value", "")
                                            if not val:
                                                continue
                                            geom = w.get("geometry") or line.get("geometry")
                                            if geom and len(geom) == 2:
                                                (x0, y0), (x1, y1) = geom
                                                try:
                                                    ocr_token_lines.append(
                                                        {
                                                            "text": str(val),
                                                            "bbox": [
                                                                float(x0) * float(w_px),
                                                                float(y0) * float(h_px),
                                                                float(x1) * float(w_px),
                                                                float(y1) * float(h_px),
                                                            ],
                                                            "page": int(page_idx),
                                                            "page_width": float(w_px),
                                                            "page_height": float(h_px),
                                                        }
                                                    )
                                                except Exception:
                                                    pass
                                                word_chunks.append((float(x0), str(val)))
                                                y = ((y0 + y1) / 2.0) * float(h_px)
                                                x = float(x0) * float(w_px)
                                                h = (y1 - y0) * float(h_px)
                                                xs.extend([float(x0), float(x1)])
                                                ys.extend([float(y0), float(y1)])
                                            else:
                                                word_chunks.append((0.0, str(val)))
                                                y, x, h = 0.0, 0.0, 0.0
                                            tokens.append((y, x, str(val), h))
                                        if word_chunks:
                                            word_chunks.sort(key=lambda t: t[0])
                                            line_txt = " ".join([t for _, t in word_chunks if t]).strip()
                                            if line_txt:
                                                line_texts.append(line_txt)
                                                try:
                                                    geom_ln = line.get("geometry")
                                                    if geom_ln and len(geom_ln) == 2:
                                                        (lx0, ly0), (lx1, ly1) = geom_ln
                                                        bx0 = float(lx0) * float(w_px)
                                                        by0 = float(ly0) * float(h_px)
                                                        bx1 = float(lx1) * float(w_px)
                                                        by1 = float(ly1) * float(h_px)
                                                        ocr_lines.append({
                                                            "text": line_txt,
                                                            "bbox": [bx0, by0, bx1, by1],
                                                            "page": int(page_idx),
                                                            "page_width": float(w_px),
                                                            "page_height": float(h_px),
                                                        })
                                                    elif xs and ys:
                                                        bx0 = min(xs) * float(w_px)
                                                        by0 = min(ys) * float(h_px)
                                                        bx1 = max(xs) * float(w_px)
                                                        by1 = max(ys) * float(h_px)
                                                        ocr_lines.append({
                                                            "text": line_txt,
                                                            "bbox": [bx0, by0, bx1, by1],
                                                            "page": int(page_idx),
                                                            "page_width": float(w_px),
                                                            "page_height": float(h_px),
                                                        })
                                                except Exception:
                                                    pass
                                    except Exception:
                                        pass
                    if line_texts:
                        txt = "\n".join(line_texts)
                    else:
                        lines = _group_tokens_to_lines(tokens)
                        txt = "\n".join(lines)
                except Exception:
                    try:
                        txt = res.render()
                    except Exception:
                        txt = ""
                return txt or ""

            def _doctr_to_text_render(img_in) -> str:
                try:
                    import numpy as _np  # type: ignore
                    if Image is not None and isinstance(img_in, Image.Image):
                        try:
                            img_in = img_in.convert("RGB")
                        except Exception:
                            pass
                        arr = _np.asarray(img_in)
                    else:
                        arr = _np.asarray(img_in)
                    if arr.ndim == 2:
                        arr = _np.stack([arr] * 3, axis=-1)
                    elif arr.ndim == 3 and arr.shape[2] == 1:
                        arr = _np.repeat(arr, 3, axis=2)
                    arr = arr.astype(_np.uint8, copy=False)
                    doc = DocumentFile.from_images([arr])
                    res = predictor(doc)
                    try:
                        return res.render() or ""
                    except Exception:
                        return ""
                except Exception:
                    return ""

            # For phone photos, optionally apply stronger photo pre-processing before DocTR
            try:
                if mime_type != "application/pdf" and bool(cfg.doctr_strong_photo):
                    img = _advanced_ocr_image_preprocess(img, cfg=cfg, strong=True)
                    img = _prep_img_photo_strong(img)
                else:
                    img = _prep_img(img)
            except Exception:
                img = _prep_img(img)
            # Optional upscaling for DocTR (helps very small text on phone photos)
            try:
                scale = float(cfg.doctr_upscale or 1.0)
                if scale and scale > 1.01 and Image is not None and hasattr(img, "size"):
                    w, h = img.size
                    max_dim = 5000
                    max_scale = max_dim / float(max(w, h)) if max(w, h) > 0 else 1.0
                    use_scale = min(scale, max_scale)
                    if use_scale > 1.01:
                        img = img.resize((int(w * use_scale), int(h * use_scale)), Image.LANCZOS)
            except Exception:
                pass
            chosen_img = img
            page_line_start = len(ocr_lines)
            page_token_start = len(ocr_token_lines)
            txt = _doctr_to_text(img)
            first_line_end = len(ocr_lines)
            first_token_end = len(ocr_token_lines)
            if _is_poor_ocr(txt):
                try:
                    if mime_type != "application/pdf":
                        img2 = _advanced_ocr_image_preprocess(img, cfg=cfg, strong=True)
                        retry_img = _prep_img_photo_strong(img2)
                    else:
                        retry_img = _prep_img_strong(img)
                    txt2 = _doctr_to_text(retry_img)
                    if len((txt2 or "").strip()) > len((txt or "").strip()):
                        txt = txt2
                        chosen_img = retry_img
                        # Keep only boxes produced from the selected retry image.
                        del ocr_lines[page_line_start:first_line_end]
                        del ocr_token_lines[page_token_start:first_token_end]
                    else:
                        # Discard retry boxes; they use a different image geometry.
                        del ocr_lines[first_line_end:]
                        del ocr_token_lines[first_token_end:]
                except Exception:
                    pass
            # If structural export is weak for line items, try render-based text
            try:
                txt_r = _doctr_to_text_render(img)
                if _count_code_lines(txt_r) > _count_code_lines(txt) or (len(txt_r) > len(txt) and _count_code_lines(txt) == 0):
                    txt = txt_r
            except Exception:
                pass
            # If DocTR still yields little on an OCR page, fallback to Tesseract when available.
            if _is_poor_ocr(txt):
                try:
                    t_txt, t_lines = _tesseract_ocr_image(img, tesseract_cmd=str(cfg.tesseract_cmd or ""), page_idx=page_idx)
                    if len((t_txt or "").strip()) > len((txt or "").strip()):
                        txt = t_txt
                        if t_lines:
                            ocr_lines.extend(t_lines)
                except Exception:
                    pass
            try:
                _OCR_PAGE_IMAGE_CACHE.setdefault(cache_key, {})[int(page_idx)] = chosen_img.copy()
            except Exception:
                try:
                    _OCR_PAGE_IMAGE_CACHE.setdefault(cache_key, {})[int(page_idx)] = chosen_img
                except Exception:
                    pass
            parts.append(txt or "")
        try:
            _OCR_LINES_CACHE[cache_key] = ocr_lines
            _OCR_TOKEN_LINES_CACHE[cache_key] = ocr_token_lines
        except Exception:
            pass
        parts = _apply_page_separators(parts)
        out_txt = "\n\n".join(parts).strip()
        # If DocTR yields nothing for a photo, try Tesseract or raise a clear error
        if (mime_type != "application/pdf") and (not out_txt):
            try:
                t_cmd = _normalize_tesseract_path(str(cfg.tesseract_cmd or "").strip())
            except Exception:
                t_cmd = ""
            # Fallback to default path on Windows if config is blank
            if not t_cmd:
                try:
                    t_cmd = r"C:\Program Files\Tesseract-OCR\tesseract.exe"
                except Exception:
                    t_cmd = ""
            if t_cmd and _tesseract_path_ok(t_cmd):
                try:
                    ok_pt, err_pt = _ensure_import("pytesseract", "pytesseract", auto_install=bool(cfg.auto_install))
                    if not ok_pt:
                        raise RuntimeError(f"pytesseract not installed ({err_pt})")
                    fallback_img = last_img
                    if fallback_img is None:
                        for _entry in pdf_page_inputs:
                            if _entry.get("image") is not None:
                                fallback_img = _entry.get("image")
                                break
                    t_txt, t_lines = _tesseract_ocr_image(fallback_img, tesseract_cmd=t_cmd, page_idx=1)
                    if t_txt:
                        if t_lines:
                            _OCR_LINES_CACHE[cache_key] = t_lines
                        return t_txt.strip()
                except Exception:
                    pass
            path_ok = _tesseract_path_ok(t_cmd) if t_cmd else False
            raise RuntimeError(
                f"DocTR OCR returned no text for this image. Set a valid Tesseract path or switch to Local OCR (Tesseract). "
                f"(tesseract_cmd='{t_cmd}' path_ok={path_ok})"
            )
        return out_txt

    raise RuntimeError(f"Unknown OCR engine: {engine}")


# -------------------------
# Booker parsing (fast / robust)
# -------------------------


class BookerCombinedRowParser:
    """Booker line parser (parity + robustness).

    Designed to match the proven behaviour from v1.02.048 while adding:
    - VAT code mapping (B=20%, Z/A=0%, A=0%, R=5%, C=5% by default; overridable via 'VAT mapping JSON' if present in text)
    - Optional FLAG token between unitPrice and value (P / SL / OCR variants)
    - Extract RRP and POR% when present
    - Computes totalUnits = casePack * qty, vatAmount and lineGross
    """

    DEFAULT_VAT_MAP = {
        "B": 20.0,
        "A": 0.0,
        "Z": 0.0,
        "Z/A": 0.0,
        "ZA": 0.0,
        "R": 5.0,
        "C": 5.0,
        "S/A": 20.0,
        "SA": 20.0,
    }

    @staticmethod
    def _normalise_line(line: str) -> str:
        s = (line or "").replace("\t", " ").replace("Â£", " ").strip()
        # Fix OCR symbol confusion for VAT code C
        s = s.replace("Â©", "C").replace("Â¢", "C")
        # Fix split decimals: '111. 41' -> '111.41'
        s = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", s)
        s = _norm_pack_tokens(s)
        # OCR: "1t" -> "LT" (e.g., "1.51t" -> "1.5LT")
        s = re.sub(r"(\d+(?:\.\d+)?)1t\b", r"\1LT", s, flags=re.IGNORECASE)
        s = re.sub(r"\b1t\b", r"LT", s, flags=re.IGNORECASE)
        # Normalise pack/size tokens: "6*1.5 lt" -> "6X1.5LT", "1.5 lt" -> "1.5LT"
        s = re.sub(
            r"(\d+(?:\.\d+)?)\s*[*xX]\s*(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
            r"\1X\2\3",
            s,
            flags=re.IGNORECASE,
        )
        s = re.sub(
            r"(\d+(?:\.\d+)?)\s*(ML|L|LTR|LT|CL|G|KG|PK)\b",
            r"\1\2",
            s,
            flags=re.IGNORECASE,
        )
        # Common OCR swaps for size tokens like 500m1; do not rewrite PM115/PMP179 codes.
        s = re.sub(r"(?<=\d)m1\b", "ml", s, flags=re.IGNORECASE)
        # Normalise spaces
        s = re.sub(r"\s+", " ", s)
        # Normalise common OCR variants of SL flag
        s = s.replace(" Sk ", " SL ").replace(" Sh ", " SL ").replace(" Si ", " SL ").replace(" S1 ", " SL ")
        return s.strip()

    @staticmethod
    def _is_code(tok: str) -> bool:
        raw = (tok or "").strip().upper()
        if re.fullmatch(r"M\d{5,7}", raw):
            return True
        t = re.sub(r"[^0-9]+", "", raw)
        return t.isdigit() and 5 <= len(t) <= 7

    @staticmethod
    def _as_float(tok: str):
        if tok is None:
            return None
        t = str(tok).strip()
        if not t:
            return None
        # Common OCR confusion for QTY = 1 (e.g. "L" / "I")
        if len(t) == 1:
            u = t.upper()
            if u in ("L", "I", "|"):
                return 1.0
            if u == "O":
                return 0.0
        t = t.replace(",", "").replace("%", "")
        if t.endswith("-") and len(t) > 1:
            t = "-" + t[:-1]
        t = re.sub(r"[^0-9.\-]+", "", t)
        if t in ("", "-", ".", "-."):
            return None
        try:
            return float(t)
        except Exception:
            return None

    @staticmethod
    def _as_float_strict(tok: str):
        """Parse numeric tokens only (rejects alphanumeric like '10sach')."""
        if tok is None:
            return None
        t = str(tok).strip()
        if not t:
            return None
        # Allow currency/commas/percent but no letters
        if re.search(r"[A-Za-z]", t):
            return None
        t = t.replace(",", "").replace("%", "")
        # Support trailing minus (e.g., "1-" or "8.19-")
        if t.endswith("-") and len(t) > 1:
            core = t[:-1]
            if re.fullmatch(r"\d+(?:\.\d+)?", core):
                try:
                    return -float(core)
                except Exception:
                    return None
        if not re.fullmatch(r"-?\d+(?:\.\d+)?", t):
            return None
        try:
            return float(t)
        except Exception:
            return None

    @staticmethod
    def _norm_vat_code(tok: str) -> str:
        raw = (tok or "").strip().upper()
        # Common OCR confusions for VAT code C
        raw = raw.replace("Â©", "C").replace("Â¢", "C")
        # If digits are present, don't try to normalise to a VAT code
        if re.search(r"\d", raw):
            return raw.replace(" ", "")
        t = re.sub(r"[^A-Z/]+", "", raw)
        if t in ("ZA", "Z-A", "Z/A"):
            return "Z/A"
        if len(t) == 2 and t[0] in ("A", "B", "C", "Z", "R") and t[1] == "/":
            return t[0]
        if len(t) == 2 and t[1] in ("A", "B", "C", "Z", "R") and t[0] == "/":
            return t[1]
        return t

    @staticmethod
    def _looks_like_vat_code(tok: str) -> bool:
        t = BookerCombinedRowParser._norm_vat_code(tok)
        return bool(re.match(r"^(B|A|Z|Z/A|R|C)$", t))

    @staticmethod
    def _norm_flag(tok: str) -> str:
        t = (tok or "").strip().upper()
        if t in ("SH", "SK", "SI", "S1", "S/L"):
            return "SL"
        if t in ("SL", "P"):
            return t
        return ""

    @staticmethod
    def _unit_size_token(tok: str) -> bool:
        t = (tok or "").strip().upper()
        if re.match(r"^\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)$", t):
            return True
        if re.match(r"^\d+(?:\.\d+)?S$", t):
            return True
        if re.match(r"^\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK)$", t):
            return True
        if re.match(r"^\d+(?:\.\d+)?(ROLL|ROLLS)$", t):
            return True
        return False

    @staticmethod
    def _pm_token(tok: str) -> bool:
        return bool(re.fullmatch(r"PM\d+", (tok or "").strip().upper()))

    @staticmethod
    def _extract_vat_map(text: str) -> Dict[str, float]:
        upper = (text or "").upper()
        upper = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", upper)
        vat_map = dict(BookerCombinedRowParser.DEFAULT_VAT_MAP)
        # Optional pattern: lines like "B: 20.0"
        for m in re.finditer(r"^\s*([A-Z](?:/[A-Z])?)\s*:\s*(\d{1,2}(?:\.\d+)?)\b", upper, flags=re.MULTILINE):
            code = BookerCombinedRowParser._norm_vat_code(m.group(1))
            rate = BookerCombinedRowParser._as_float(m.group(2))
            if rate is not None:
                vat_map[code] = float(rate)
        return vat_map

    def parse(self, text: str) -> List[Dict[str, Any]]:
        txt = (text or "")
        vat_map = self._extract_vat_map(txt)
        lines = [self._normalise_line(ln) for ln in txt.splitlines() if (ln or "").strip()]
        items: List[Dict[str, Any]] = []
        last_vat_code: Optional[str] = None
        promo_re = re.compile(r"\bBUY\s*ANY\b|\bBUY\s*\d+\b|\bBUY\d+\b|\bMULTI\s*BUY\b|\bMULTIBUY\b|\bMULTI-BUY\b|\bPROMO\b|\bPROMOTION\b|\bDEAL\b|\bOFFER\b|\bSAVE\b|\bSAVING\b|\bDISC(?:OUNT)?\b|\bGET\s*\d+(?:\s+\S+){0,3}\s+FREE\b|\bBUY\b.*\bFREE\b", re.IGNORECASE)

        def _promo_amount(ln: str) -> Optional[float]:
            # Capture promo/discount lines like "BUY ANY 3 FOR 15.00 4.47-"
            if not ln:
                return None
            up = ln.upper()
            if not promo_re.search(up):
                return None
            # Extract money-like tokens (supports trailing minus e.g. "4.47-")
            for tok in re.findall(r"-?\d+\.\d{2}-?", ln.replace(",", "")):
                try:
                    if tok.endswith("-") and len(tok) > 1:
                        val = -float(tok[:-1])
                    else:
                        val = float(tok)
                    if val < 0:
                        return val
                except Exception:
                    continue
            return None

        def should_skip(ln_up: str) -> bool:
            if not ln_up:
                return True
            if any(k in ln_up for k in ("SUB-TOTAL", "TOTAL ITEMS", "TOTAL SAVINGS", "SAVING DETAILS", "PROMOTION", "PROMOTIONS", "RATE ", "INVOICE TOTAL", "TOTALS")):
                return True
            if ln_up.startswith("CODE ") or "CODE DESCRIPTION" in ln_up:
                return True
            return False

        for ln in lines:
            up = ln.upper()
            if should_skip(up):
                continue

            toks = ln.split()
            if len(toks) < 7:
                # Promo lines can be short (no item code) but still carry a discount value.
                promo_val = _promo_amount(ln)
                if promo_val is None and promo_re.search(up) and ("FREE" in up):
                    promo_val = 0.0
                if promo_val is not None and (not toks or not self._is_code(toks[0])):
                    vat_code = last_vat_code or "B"
                    vat_rate = float(vat_map.get(vat_code, BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0)))
                    vat_amount = round(promo_val * (vat_rate / 100.0), 2)
                    items.append({
                        "lineNo": None,
                        "code": "PROMO",
                        "description": f"PROMO: {ln.strip()}",
                        "casePack": 0,
                        "unitSize": 0,
                        "qty": 0.0,
                        "totalUnits": 0.0,
                        "unitPrice": 0.0,
                        "flag": "",
                        "lineNet": float(promo_val),
                        "vatCode": vat_code,
                        "vatRate": float(vat_rate),
                        "vatAmount": float(vat_amount),
                        "lineGross": float(round(promo_val + vat_amount, 2)),
                        "stdRrp": 0.0,
                        "por": 0.0,
                        "isVoid": False,
                    })
                continue
            if not self._is_code(toks[0]):
                promo_val = _promo_amount(ln)
                if promo_val is None and promo_re.search(up) and ("FREE" in up):
                    promo_val = 0.0
                if promo_val is not None:
                    vat_code = last_vat_code or "B"
                    vat_rate = float(vat_map.get(vat_code, BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0)))
                    vat_amount = round(promo_val * (vat_rate / 100.0), 2)
                    items.append({
                        "lineNo": None,
                        "code": "PROMO",
                        "description": f"PROMO: {ln.strip()}",
                        "casePack": 0,
                        "unitSize": 0,
                        "qty": 0.0,
                        "totalUnits": 0.0,
                        "unitPrice": 0.0,
                        "flag": "",
                        "lineNet": float(promo_val),
                        "vatCode": vat_code,
                        "vatRate": float(vat_rate),
                        "vatAmount": float(vat_amount),
                        "lineGross": float(round(promo_val + vat_amount, 2)),
                        "stdRrp": 0.0,
                        "por": 0.0,
                        "isVoid": False,
                    })
                continue

            code_val = re.sub(r"[^0-9]+", "", toks[0])

            vat_idx = None
            for i in range(len(toks) - 1, 0, -1):
                if self._looks_like_vat_code(toks[i]):
                    if any(self._as_float(x) is not None for x in toks[i + 1 : i + 3]) or any(self._as_float(x) is not None for x in toks[max(0, i - 3) : i]):
                        vat_idx = i
                        break
            if vat_idx is None:
                continue

            vat_code = self._norm_vat_code(toks[vat_idx])
            vat_rate = float(vat_map.get(vat_code, BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0)))

            por = None
            for j in range(len(toks) - 1, vat_idx, -1):
                if "%" in toks[j]:
                    por = self._as_float(toks[j])
                    break
            if por is None:
                for j in range(len(toks) - 1, vat_idx, -1):
                    v = self._as_float(toks[j])
                    if v is not None:
                        por = float(v)
                        break

            std_rrp = None
            if vat_idx + 1 < len(toks):
                std_rrp = self._as_float(toks[vat_idx + 1])

            value_idx = None
            def _is_free_token(t: str) -> bool:
                u = (t or "").strip().upper().replace(".", "")
                return u in ("FREE", "FOC")
            for j in range(vat_idx - 1, 1, -1):
                if _is_free_token(toks[j]):
                    value_idx = j
                    break
                if self._as_float(toks[j]) is not None:
                    value_idx = j
                    break
            if value_idx is None:
                continue
            if _is_free_token(toks[value_idx]):
                line_net = 0.0
            else:
                line_net = float(self._as_float(toks[value_idx]) or 0.0)

            flag = ""
            scan_left_from = value_idx - 1
            if scan_left_from >= 0:
                f = self._norm_flag(toks[scan_left_from])
                if f:
                    flag = f
                    scan_left_from = value_idx - 2

            unit_price = None
            unit_price_idx = None
            for j in range(scan_left_from, 1, -1):
                v = self._as_float(toks[j])
                if v is not None:
                    unit_price = float(v)
                    unit_price_idx = j
                    break
            if unit_price_idx is None:
                continue

            qty = None
            qty_idx = None
            for j in range(unit_price_idx - 1, 1, -1):
                v = self._as_float(toks[j])
                if v is not None:
                    qty = float(v)
                    qty_idx = j
                    break
            if qty_idx is None:
                continue

            if qty_idx - 2 < 1:
                continue
            case_pack = self._as_float(toks[qty_idx - 2])
            unit_size = toks[qty_idx - 1]
            if case_pack is None:
                continue
            case_pack = int(case_pack)

            # Heuristic: sometimes OCR swaps unit_size and case_pack tokens.
            try:
                unit_size_s = str(unit_size or "").strip()
                case_pack_tok = str(toks[qty_idx - 2] or "").strip()
                if re.fullmatch(r"\d+(?:\.\d+)?", unit_size_s) and re.search(r"(PM\\d+|\\d+\\s*(ML|CL|L|G|KG))", case_pack_tok, flags=re.IGNORECASE):
                    unit_size = case_pack_tok
                    case_pack = int(float(unit_size_s))
            except Exception:
                pass

            desc_tokens = toks[1 : qty_idx - 2]
            if not desc_tokens:
                continue
            description = _fix_pm_code(" ".join(desc_tokens).strip())
            try:
                free_final = _is_free_marker(description, " ".join(toks), unit_price, line_net)
                if free_final and "FREE" not in description.upper():
                    description = f"{description} FREE".strip()
            except Exception:
                free_final = False

            total_units = float(case_pack) * float(qty or 0.0)
            if (line_net <= 0.0) and (qty is not None) and (unit_price is not None):
                line_net = round(float(qty) * float(unit_price), 2)

            is_void = False
            try:
                qv = float(qty or 0.0)
                ln = float(line_net or 0.0)
            except Exception:
                qv = 0.0
                ln = 0.0
            if qv < 0 or ln < 0:
                is_void = True
            if qv < 0 and ln > 0:
                line_net = -abs(ln)
                ln = float(line_net)
            if ln < 0 and qv > 0:
                qty = -abs(qv)
                total_units = float(case_pack) * float(qty or 0.0)
            if unit_price is not None:
                try:
                    if float(unit_price) < 0:
                        unit_price = abs(float(unit_price))
                except Exception:
                    pass

            vat_amount = round(line_net * (vat_rate / 100.0), 2)
            line_gross = round(line_net + vat_amount, 2)

            items.append({
                "lineNo": None,
                "code": code_val,
                "description": description,
                "casePack": int(case_pack),
                "unitSize": unit_size,
                "qty": float(qty or 0.0),
                "totalUnits": float(total_units),
                "unitPrice": float(unit_price or 0.0),
                "flag": flag,
                "lineNet": float(line_net),
                "vatCode": vat_code,
                "vatRate": float(vat_rate),
                "vatAmount": float(vat_amount),
                "lineGross": float(line_gross),
                "stdRrp": float(std_rrp) if std_rrp is not None else 0.0,
                "por": float(por) if por is not None else 0.0,
                "isVoid": is_void,
                "isFree": bool(free_final),
            })
            last_vat_code = vat_code

        try:
            return _booker_split_items_with_embedded_codes(items)
        except Exception:
            return items


def _booker_promo_items_from_text(text: str, default_vat: str = "B") -> List[Dict[str, Any]]:
    """Extract Booker promo/discount lines (e.g., 'BUY ANY ... 4.47-') as negative line items."""
    if not text:
        return []
    items: List[Dict[str, Any]] = []
    pending = ""
    pending_ttl = 0
    pending_idx = None
    promo_re = re.compile(r"\bBUY\s*ANY\b|\bBUY\s*\d+\b|\bBUY\d+\b|\bMULTI\s*BUY\b|\bMULTIBUY\b|\bMULTI-BUY\b|\bPROMO\b|\bPROMOTION\b|\bDEAL\b|\bOFFER\b|\bSAVE\b|\bSAVING\b|\bDISC(?:OUNT)?\b|\bFREE\b|\bGET\s*\d+(?:\s+\S+){0,3}\s+FREE\b|\bBUY\b.*\bFREE\b", re.IGNORECASE)
    skip_re = re.compile(r"\bSAVING\s+DETAILS\b|\bTOTAL\s+SAVINGS\b|\bPROMOTIONS?\s+SAVED\s+YOU\b|\bMULTIBUYS?\s+SAVED\s+YOU\b", re.IGNORECASE)
    for idx, ln in enumerate((text or "").splitlines()):
        if not ln or not ln.strip():
            continue
        up = ln.upper()
        if skip_re.search(up):
            continue
        toks = ln.split()
        # Ignore normal stock rows that happen to contain a price-mark/promo token in the description.
        if toks and BookerCombinedRowParser._is_code(toks[0]):
            pending = ""
            pending_ttl = 0
            pending_idx = None
            continue
        is_promo_line = bool(promo_re.search(up))
        if not is_promo_line and not pending:
            continue
        amt = None
        scan_line = ln
        if pending and not is_promo_line:
            scan_line = f"{pending} {ln}".strip()
        scan_up = scan_line.upper()
        vals = []
        neg_vals = []
        for tok in re.findall(r"-?\d+\.\d{2}-?", scan_line.replace(",", "")):
            try:
                if tok.endswith("-") and len(tok) > 1:
                    v = -float(tok[:-1])
                    neg_vals.append(v)
                else:
                    v = float(tok)
                    if v < 0:
                        neg_vals.append(v)
                vals.append(v)
            except Exception:
                continue
        if neg_vals:
            amt = neg_vals[0]
        elif vals:
            # If this looks like a "BUY ... FOR 15.00" line without explicit discount, defer to next line.
            if is_promo_line and re.search(r"\bBUY\b", scan_up) and "FOR" in scan_up and ("CR" not in scan_up) and ("CREDIT" not in scan_up) and ("LESS" not in scan_up):
                amt = None
            else:
                # Treat as discount only when context strongly implies it.
                if pending or ("CR" in scan_up) or ("CREDIT" in scan_up) or ("LESS" in scan_up) or re.search(r"\bDISC(?:OUNT)?\b|\bSAVE\b|\bSAVING\b", scan_up):
                    amt = -abs(vals[0])
        if amt is None:
            if is_promo_line:
                if re.search(r"\bBUY\s*\d+\b|\bBUY\d+\b", up) and ("FREE" in up):
                    amt = 0.0
                else:
                    pending = ln
                    pending_idx = idx
                    pending_ttl = 3
            elif pending_ttl > 0:
                pending_ttl -= 1
                if pending_ttl <= 0:
                    pending = ""
                    pending_idx = None
            if amt is None:
                continue
        if pending and not is_promo_line:
            ln = f"{pending} {ln}".strip()
            pending = ""
            pending_ttl = 0
            promo_idx = pending_idx
            pending_idx = None
        else:
            promo_idx = idx
        vat_code = default_vat
        try:
            for t in (scan_line or ln).split():
                vc = BookerCombinedRowParser._norm_vat_code(t)
                if re.fullmatch(r"(A|B|C|Z|Z/A|R)", vc):
                    vat_code = vc
                    break
        except Exception:
            pass
        vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
        vat_amount = round(float(amt) * (vat_rate / 100.0), 2)
        items.append({
            "lineNo": None,
            "code": "PROMO",
            "description": f"PROMO: {ln.strip()}",
            "casePack": 0,
            "unitSize": "",
            "qty": 0.0,
            "totalUnits": 0.0,
            "unitPrice": 0.0,
            "lineNet": float(amt),
            "vatCode": vat_code,
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amount),
            "lineGross": float(round(float(amt) + float(vat_amount), 2)),
            "stdRrp": 0.0,
            "por": 0.0,
            "isVoid": False,
            "rowTag": "PROMO",
            "_promoLineIdx": int(promo_idx) if promo_idx is not None else None,
        })
    return _normalise_promo_quantities(items)


def _booker_delivery_fee_items_from_text(text: str, default_vat: str = "B") -> List[Dict[str, Any]]:
    """Extract Booker delivery/service fee rows from stacked footer sections."""
    if not text:
        return []
    lines = [BookerCombinedRowParser._normalise_line(ln) for ln in str(text or "").splitlines() if str(ln or "").strip()]
    if not lines:
        return []
    out: List[Dict[str, Any]] = []
    seen = set()
    desc_re = re.compile(r"\b(PICKING|DELIVERY|HANDLING|CARRIAGE|SERVICE)\b", re.I)
    start = 0
    for idx, ln in enumerate(lines):
        if re.search(r"\bDELIVERY\s+FEES\b|\bSERVICE\s+FEES\b|\bCHARGES\b", ln, flags=re.I):
            start = idx
            break

    i = start
    while i < len(lines):
        ln = lines[i]
        if re.search(r"\bTOTAL\s+ITEMS\b|\bRATE\b|\bTOTALS?\b|\bINVOICE\s+TOTAL\b", ln, flags=re.I):
            break
        m = re.match(r"^\s*(\d{5,7})\s+(.+?)\s*$", ln)
        if not m or not desc_re.search(m.group(2) or ""):
            i += 1
            continue
        code = m.group(1).strip()
        desc = _collapse_spaces(m.group(2).strip())
        qty = 1.0
        unit_price = 0.0
        line_net = 0.0
        vat_code = default_vat
        j = i + 1
        values: List[float] = []
        while j < min(len(lines), i + 8):
            tok = lines[j].strip()
            if re.match(r"^\d{5,7}\s+", tok) or re.search(r"\bTOTAL\s+ITEMS\b|\bRATE\b|\bTOTALS?\b", tok, flags=re.I):
                break
            vc = BookerCombinedRowParser._norm_vat_code(tok)
            if re.fullmatch(r"(A|B|C|Z|Z/A|R)", vc):
                vat_code = vc
                j += 1
                break
            val = BookerCombinedRowParser._as_float_strict(tok)
            if val is not None:
                values.append(float(val))
            j += 1
        if len(values) >= 3:
            qty, unit_price, line_net = values[0], values[1], values[2]
        elif len(values) >= 2:
            unit_price, line_net = values[0], values[1]
        elif len(values) == 1:
            unit_price = line_net = values[0]
        if line_net <= 0:
            i += 1
            continue
        vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
        vat_amount = round(float(line_net) * vat_rate / 100.0, 2)
        key = (code, desc.upper(), round(line_net, 2), vat_code)
        if key not in seen:
            seen.add(key)
            out.append({
                "lineNo": None,
                "code": code,
                "description": desc,
                "casePack": 0,
                "unitSize": "",
                "qty": float(qty or 1.0),
                "totalUnits": 0.0,
                "unitPrice": float(unit_price or line_net),
                "lineNet": float(line_net),
                "vatCode": vat_code,
                "vatRate": float(vat_rate),
                "vatAmount": float(vat_amount),
                "lineGross": float(round(float(line_net) + vat_amount, 2)),
                "stdRrp": 0.0,
                "por": 0.0,
                "isVoid": False,
                "_reconOnly": True,
            })
        i = max(j, i + 1)
    return out


_GENERIC_CHARGE_LABEL_RE = re.compile(
    r"\b("
    r"FRAIS\s+DE\s+PORT|PORT\s+HT|TRANSPORT|LIVRAISON|EXPEDITION|"
    r"DELIVERY(?:\s+CHARGE)?|FREIGHT|CARRIAGE|SHIPPING|HANDLING|SERVICE\s+CHARGE|"
    r"FUEL(?:\s+AND\s+ENERGY)?\s+CHARGE|ENERGY\s+CHARGE|SURCHARGE"
    r")\b",
    re.IGNORECASE,
)


def _parse_locale_money_amount(value: Any) -> float:
    """Parse invoice money tokens including EU formats such as '1 200,00 EUR'."""
    raw = str(value or "").strip()
    if not raw:
        return 0.0
    s = raw.replace("\u00a0", " ")
    s = re.sub(r"(?i)\b(EUR|GBP|USD|CHF|CAD|AUD|NZD)\b", "", s)
    s = re.sub(r"[€£$]", "", s)
    s = re.sub(r"\s+", "", s)
    s = re.sub(r"[^0-9,\.\-+]", "", s)
    if not s or s in {"-", "+", ".", ","}:
        return 0.0
    negative = s.startswith("-") or s.endswith("-")
    s = s.strip("+-")
    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    elif "," in s:
        if re.search(r",\d{1,2}$", s):
            s = s.replace(".", "").replace(",", ".")
        else:
            s = s.replace(",", "")
    else:
        s = s.replace(",", "")
    try:
        amount = float(s)
    except Exception:
        return 0.0
    if negative and amount > 0:
        amount = -amount
    return amount


def _money_amounts_from_text_line(line: str) -> List[float]:
    money_re = re.compile(
        r"(?:[€£$]\s*)?[-+]?\d[\d\s\u00a0.,]*\d(?:\s*(?:€|£|\$|EUR|GBP|USD|CHF|CAD|AUD|NZD))?",
        re.IGNORECASE,
    )
    amounts: List[float] = []
    for match in money_re.finditer(str(line or "")):
        token = match.group(0)
        if re.search(r"%\s*$", token):
            continue
        amount = _parse_locale_money_amount(token)
        if amount != 0.0:
            amounts.append(float(amount))
    return amounts


def _generic_reconciliation_charge_items_from_text(
    text: str,
    header: Optional[Dict[str, Any]] = None,
    items: Optional[List[Dict[str, Any]]] = None,
) -> List[Dict[str, Any]]:
    """Extract invoice-level delivery/transport charges when they explain a total mismatch."""
    if not str(text or "").strip():
        return []
    current_items = [dict(it) for it in (items or []) if isinstance(it, dict)]
    hdr_net = round(_safe_float((header or {}).get("totalNet")), 2)
    hdr_vat = round(_safe_float((header or {}).get("totalVat")), 2)
    hdr_gross = round(_safe_float((header or {}).get("totalGross")), 2)
    item_net = round(sum(_safe_float(it.get("lineNet")) for it in current_items), 2)
    item_gross = round(sum(_effective_line_gross(it) for it in current_items), 2)
    net_residual = round(hdr_net - item_net, 2)
    gross_residual = round(hdr_gross - item_gross, 2)
    if abs(net_residual) <= 0.05 and abs(gross_residual) <= 0.05:
        return []

    out: List[Dict[str, Any]] = []
    seen = set()
    for raw_line in str(text or "").splitlines():
        line = _collapse_spaces(raw_line)
        if not line or not _GENERIC_CHARGE_LABEL_RE.search(line):
            continue
        upper = line.upper()
        if re.search(r"\b(TOTAL|TVA|VAT|TAX|BASE|SUBTOTAL|SOUS[-\s]?TOTAL)\b", upper) and not re.search(r"\b(FRAIS\s+DE\s+PORT|PORT\s+HT|DELIVERY|FREIGHT|CARRIAGE|SHIPPING|TRANSPORT|LIVRAISON)\b", upper):
            continue
        amounts = _money_amounts_from_text_line(line)
        if not amounts:
            continue
        amount = round(float(amounts[-1]), 2)
        if abs(amount) <= 0.05:
            continue
        explains_net = abs(abs(net_residual) - abs(amount)) <= 0.10
        explains_gross = abs(abs(gross_residual) - abs(amount)) <= 0.10
        # Only add generic charge rows when the printed charge explains the
        # reconciliation gap. This prevents footer text from becoming duplicate
        # lines when Gemini/local OCR already extracted the charge.
        if not (explains_net or explains_gross):
            continue
        vat_amount = 0.0
        vat_rate = 0.0
        if hdr_vat > 0 and not explains_gross:
            vat_amount = round(gross_residual - net_residual, 2)
            if abs(vat_amount) > 0.05 and amount:
                vat_rate = round((vat_amount / amount) * 100.0, 2)
        desc = "Transport / delivery charge"
        label_match = _GENERIC_CHARGE_LABEL_RE.search(line)
        if label_match:
            desc = _collapse_spaces(label_match.group(0)).title()
        key = (desc.upper(), amount)
        if key in seen:
            continue
        seen.add(key)
        out.append({
            "lineNo": None,
            "code": "TRANSPORT",
            "description": desc,
            "casePack": 0,
            "unitSize": "",
            "qty": 0.0,
            "totalUnits": 0.0,
            "unitPrice": float(amount),
            "lineNet": float(amount),
            "vatCode": "Z" if hdr_vat <= 0 else "",
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amount),
            "lineGross": float(round(amount + vat_amount, 2)),
            "stdRrp": 0.0,
            "por": 0.0,
            "isVoid": False,
            "rowTag": "RECON",
            "_reconOnly": True,
        })
    return out


def _append_missing_reconciliation_charge_items(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    text: str = "",
) -> List[Dict[str, Any]]:
    out = [dict(it) for it in (items or []) if isinstance(it, dict)]
    extras = _generic_reconciliation_charge_items_from_text(text or "", header, out)
    if not extras:
        return out
    existing = {
        (
            str(it.get("code") or "").strip().upper(),
            round(_safe_float(it.get("lineNet")), 2),
            str(it.get("description") or "").strip().upper(),
        )
        for it in out
    }
    for extra in extras:
        key = (
            str(extra.get("code") or "").strip().upper(),
            round(_safe_float(extra.get("lineNet")), 2),
            str(extra.get("description") or "").strip().upper(),
        )
        if key not in existing:
            out.append(extra)
            existing.add(key)
    return _ensure_line_numbers(out)


def _booker_invoice_details_text(text: str) -> str:
    """Return Booker text from the real invoice table onward.

    Booker invoices can print SUBSTITUTION DETAILS before INVOICE DETAILS using
    the same CODE/DESCRIPTION/PACK/QTY headings. Parsing the full text can then
    treat unavailable/substitute rows as charged invoice rows.
    """
    src = str(text or "")
    if not src.strip():
        return src
    matches = list(re.finditer(r"(?im)^\s*INVOICE\s+DETAILS\s*$", src))
    if matches:
        return src[matches[-1].start():]
    # OCR sometimes drops the separator line but keeps the first real table
    # header after substitution blocks.
    header_matches = list(
        re.finditer(
            r"(?is)^\s*STD\s*\n\s*CODE\s*\n\s*DESCRIPTION\s*\n\s*PACK\s+SIZE\s*\n\s*QTY\s*\n\s*PRICE\s*\n\s*VALUE\s*\n\s*VAT\s*\n\s*RRP\s*\n\s*POR\s*$",
            src,
            flags=re.M,
        )
    )
    if header_matches:
        return src[header_matches[-1].start():]
    return src


def _booker_prune_non_invoice_detail_rows(items: List[Dict[str, Any]], text: str = "") -> List[Dict[str, Any]]:
    if not items:
        return items
    out: List[Dict[str, Any]] = []
    promo_re = re.compile(
        r"\bBUY\s*ANY\b|\bBUY\s*\d+\b|\bBUY\d+\b|\bMULTI\s*BUY\b|\bMULTIBUY\b|\bMULTI-BUY\b|\bPROMO\b|\bPROMOTION\b|\bDEAL\b|\bOFFER\b|\bSAVE\b|\bSAVING\b|\bDISC(?:OUNT)?\b|\bGET\s*\d+(?:\s+\S+){0,3}\s+FREE\b|\bBUY\b.*\bFREE\b",
        re.IGNORECASE,
    )
    for it in items or []:
        if not isinstance(it, dict):
            continue
        row = dict(it)
        code = str(row.get("code") or "").strip().upper()
        desc = str(row.get("description") or "").strip()
        raw = str(row.get("rawRow") or row.get("raw") or "").strip()
        is_promo = code == "PROMO" or bool(promo_re.search(desc)) or bool(promo_re.search(raw))
        is_recon_only = bool(row.get("_reconOnly"))
        vat_code = str(row.get("vatCode") or "").strip()
        vat_rate = _safe_float(row.get("vatRate"))
        vat_amount = _safe_float(row.get("vatAmount"))
        moneyish = max(
            abs(_safe_float(row.get("unitPrice"))),
            abs(_safe_float(row.get("lineNet"))),
            abs(vat_amount),
            abs(_safe_float(row.get("lineGross"))),
        )
        if moneyish <= 0.0001 and not is_promo and not is_recon_only:
            continue
        if (not vat_code) and abs(vat_rate) <= 0.0001 and abs(vat_amount) <= 0.0001 and not is_promo and not is_recon_only:
            continue
        out.append(row)
    return _ensure_line_numbers(out)


def _booker_finalize_invoice_items(items: List[Dict[str, Any]], text: str = "") -> List[Dict[str, Any]]:
    """Final Booker line set for UI/reconciliation: real invoice rows + promo/fees."""
    src = _booker_invoice_details_text(text or "")
    rows = _booker_prune_non_invoice_detail_rows(list(items or []), src)
    extras = []
    try:
        extras.extend(_booker_promo_items_from_text(src) or [])
    except Exception:
        pass
    try:
        extras.extend(_booker_delivery_fee_items_from_text(src) or [])
    except Exception:
        pass
    if not extras:
        return _ensure_line_numbers(rows)

    existing = {
        (
            str(row.get("code") or "").strip().upper(),
            _booker_desc_key(row.get("description") or ""),
            round(_safe_float(row.get("lineNet")), 2),
            round(_safe_float(row.get("vatAmount")), 2),
        )
        for row in rows
        if isinstance(row, dict)
    }
    for extra in extras:
        if not isinstance(extra, dict):
            continue
        key = (
            str(extra.get("code") or "").strip().upper(),
            _booker_desc_key(extra.get("description") or ""),
            round(_safe_float(extra.get("lineNet")), 2),
            round(_safe_float(extra.get("vatAmount")), 2),
        )
        if key in existing:
            continue
        rows.append(dict(extra))
        existing.add(key)
    return _ensure_line_numbers(rows)


def _booker_reconciliation_only_items_from_text(text: str) -> List[Dict[str, Any]]:
    """Extract Booker non-product charges for reconciliation only.

    These rows help header-vs-line reconciliation but should not be persisted
    as sellable product lines in the invoice lines table.
    """
    if not text:
        return []
    items: List[Dict[str, Any]] = []
    seen = set()
    line_re = re.compile(
        r"^\s*(\d{5,7})\s+(.+?)\s+(\d+(?:\.\d+)?)\s+(\d+\.\d{2})\s+(\d+\.\d{2})\s+([A-Z])\s*$"
    )
    desc_re = re.compile(r"\b(PICKING|DELIVERY|HANDLING|CARRIAGE|SERVICE)\b", re.IGNORECASE)

    for ln in (text or "").splitlines():
        if not ln or not ln.strip():
            continue
        m = line_re.match(ln.rstrip())
        if not m:
            continue
        code, desc, qty_s, price_s, value_s, vat_code = m.groups()
        if not desc_re.search(desc or ""):
            continue
        key = (code, desc.strip().upper(), value_s, vat_code.upper())
        if key in seen:
            continue
        seen.add(key)
        qty = _safe_float(qty_s)
        unit_price = _safe_float(price_s)
        line_net = _safe_float(value_s)
        vat_code = vat_code.upper().strip()
        vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
        vat_amount = round(line_net * (vat_rate / 100.0), 2)
        line_gross = round(line_net + vat_amount, 2)
        items.append({
            "lineNo": None,
            "code": code,
            "description": _collapse_spaces(desc),
            "casePack": 0,
            "unitSize": "",
            "qty": qty,
            "totalUnits": 0.0,
            "unitPrice": unit_price,
            "lineNet": line_net,
            "vatCode": vat_code,
            "vatRate": vat_rate,
            "vatAmount": vat_amount,
            "lineGross": line_gross,
            "stdRrp": 0.0,
            "por": 0.0,
            "isVoid": False,
            "_reconOnly": True,
        })
    return items


def _normalise_dhamecha_line_vat_for_reconciliation(
    items: List[Dict[str, Any]],
    header: Dict[str, Any],
    text: str = "",
) -> List[Dict[str, Any]]:
    return _dhamecha_module_normalize_vat(items, header, text)


def _reconciliation_items(header: Dict[str, Any], items: List[Dict[str, Any]], text: str = "") -> List[Dict[str, Any]]:
    """Return line items plus reconciliation-only adjustments."""
    out = [dict(it) for it in (items or []) if isinstance(it, dict)]
    supplier_u = str((header or {}).get("supplierName") or "").upper()
    text_u = str(text or "").upper()
    if "DHAMECHA" in supplier_u or "DHAMECHA" in text_u or "927135230" in text_u or "XRAW00000102826" in text_u:
        out = _normalise_dhamecha_line_vat_for_reconciliation(out, header, text)

    extras: List[Dict[str, Any]] = []
    if "BOOKER" in supplier_u or "BOOKER" in text_u:
        extras.extend(_booker_reconciliation_only_items_from_text(text or "") or [])
    extras.extend(_generic_reconciliation_charge_items_from_text(text or "", header, out) or [])
    if not extras:
        return out

    existing = {
        (
            str(it.get("code") or "").strip().upper(),
            round(_safe_float(it.get("lineNet")), 2),
            str(it.get("description") or "").strip().upper(),
        )
        for it in out
    }
    for extra in extras:
        key = (
            str(extra.get("code") or "").strip().upper(),
            round(_safe_float(extra.get("lineNet")), 2),
            str(extra.get("description") or "").strip().upper(),
        )
        if key not in existing:
            out.append(extra)
            existing.add(key)
    out = _ensure_line_numbers(out)

    recon_only = [it for it in out if isinstance(it, dict) and bool(it.get("_reconOnly"))]
    if recon_only and _safe_float((header or {}).get("totalVat")) > 0 and _safe_float((header or {}).get("totalGross")) > 0:
        try:
            metrics = _calc_metrics(header, out)
            vat_residual = round(_safe_float(header.get("totalVat")) - _safe_float(metrics.get("sum_vat")), 2)
            gross_residual = round(_safe_float(header.get("totalGross")) - _safe_float(metrics.get("sum_gross")), 2)
            target = recon_only[-1]
            if abs(vat_residual) > 0.0001:
                target["vatAmount"] = round(_safe_float(target.get("vatAmount")) + vat_residual, 2)
            if abs(gross_residual) > 0.0001:
                target["lineGross"] = round(_safe_float(target.get("lineGross")) + gross_residual, 2)
        except Exception:
            pass
    return out

    def parse_split_layout(self, text: str) -> List[Dict[str, Any]]:
        """Handle Booker invoices where the table is split across blocks (seen in some scanned PDFs).

        Pattern example (OCR):
        - Block 1: CODE DESCRIPTION PACK SIZE (no qty/price/value)
        - Block 2: QTY PRICE lines
        - Block 3: VALUE VAT RRP POR lines

        We extract each block as ordered lists and merge by index.
        """
        txt = (text or "")
        txt_fix = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", txt)
        vat_map = self._extract_vat_map(txt_fix)
        lines = [self._normalise_line(ln) for ln in txt_fix.splitlines() if (ln or "").strip()]
        up_all = "\n".join(lines).upper()

        m_total = re.search(r"TOTAL\s+ITEMS\s*:\s*(\d+)", up_all, flags=re.I)
        expected_total = int(m_total.group(1)) if m_total else 0

        # 1) Code/desc/pack/size block
        code_rows: List[Tuple[str, str, int, str]] = []
        in_code = False
        for i_ln, ln in enumerate(lines):
            up = ln.upper()
            if ("CODE" in up and "DESCRIPTION" in up and "PACK" in up and "SIZE" in up and "QTY" not in up):
                in_code = True
                continue
            # Header split across multiple lines: CODE / DESCRIPTION / PACK SIZE
            if up.strip() == "CODE":
                nxt = lines[i_ln + 1].upper() if i_ln + 1 < len(lines) else ""
                nxt2 = lines[i_ln + 2].upper() if i_ln + 2 < len(lines) else ""
                if ("DESCRIPTION" in nxt) and (("PACK" in nxt2 and "SIZE" in nxt2) or ("PACK" in nxt and "SIZE" in nxt)):
                    in_code = True
                    continue
            if in_code:
                if "TOTAL ITEMS" in up:
                    break
                toks = ln.split()
                if not toks:
                    continue
                if not self._is_code(toks[0]):
                    continue

                # Find last integer-like numeric as casePack, followed by unitSize
                pack_idx = None
                for i in range(len(toks) - 2, 0, -1):
                    v = self._as_float(toks[i])
                    if v is not None and abs(v - round(v)) < 1e-6:
                        pack_idx = i
                        break
                case_pack = 0
                unit_size = ""
                if pack_idx is not None and pack_idx + 1 < len(toks):
                    case_pack = int(self._as_float(toks[pack_idx]) or 0)
                    unit_size = toks[pack_idx + 1]
                    desc = _fix_pm_code(" ".join(toks[1:pack_idx]).strip())
                else:
                    # Pack/size sometimes appears on the next line (e.g., "10 20S")
                    desc = _fix_pm_code(" ".join(toks[1:]).strip())
                    for j in range(i_ln + 1, min(i_ln + 3, len(lines))):
                        nxt = lines[j].split()
                        if len(nxt) >= 2:
                            v = self._as_float(nxt[0])
                            if v is not None and abs(v - round(v)) < 1e-6:
                                # accept any alnum unit token with at least one letter (e.g. 20S, 30g, 16pk)
                                if re.search(r"[A-Za-z]", nxt[1]):
                                    case_pack = int(v)
                                    unit_size = nxt[1]
                                    break
                code_val = re.sub(r"[^0-9]+", "", toks[0])

                if not desc:
                    continue

                code_rows.append((code_val, desc, case_pack, unit_size))

                if expected_total and len(code_rows) >= expected_total:
                    # Sometimes the code block is complete and we can stop early
                    break

        # If we didn't detect the split layout, abort
        if not code_rows:
            # Fallback: capture code rows without requiring header detection
            for i_ln, ln in enumerate(lines):
                toks = ln.split()
                if not toks:
                    continue
                if not self._is_code(toks[0]):
                    continue
                code_val = re.sub(r"[^0-9]+", "", toks[0])
                desc = _fix_pm_code(" ".join(toks[1:]).strip())
                case_pack = 0
                unit_size = ""
                # look ahead for pack/size line
                for j in range(i_ln + 1, min(i_ln + 3, len(lines))):
                    nxt = lines[j].split()
                    if len(nxt) >= 2:
                        v = self._as_float(nxt[0])
                        if v is not None and abs(v - round(v)) < 1e-6 and re.search(r"[A-Za-z]", nxt[1]):
                            case_pack = int(v)
                            unit_size = nxt[1]
                            break
                if desc:
                    code_rows.append((code_val, desc, case_pack, unit_size))
                if expected_total and len(code_rows) >= expected_total:
                    break
            if not code_rows:
                return []

        # 2) Qty/Price block (usually after a header line containing both QTY and PRICE)
        qty_price: List[Tuple[float, float]] = []
        in_qp = False
        pending_qty = None
        for i_ln, ln in enumerate(lines):
            up = ln.upper()
            if ("QTY" in up and "PRICE" in up):
                in_qp = True
                continue
            # Header split across lines: QTY then PRICE
            if up.strip() == "QTY":
                nxt = lines[i_ln + 1].upper() if i_ln + 1 < len(lines) else ""
                if "PRICE" in nxt:
                    in_qp = True
                    continue
            if not in_qp:
                continue
            # Stop when we reach the next block
            if ("VALUE" in up and "VAT" in up) or up.startswith("STD") or ("VALUE" in up and "RRP" in up):
                break

            # Extract numbers from the line
            nums = re.findall(r"-?\d+(?:\.\d+)?", ln.replace(",", ""))
            if not nums:
                continue
            # Skip lines that look like full rows (code/desc/pack/value) rather than just qty+price
            try:
                toks_ln = ln.split()
                if any(self._is_code(t) for t in toks_ln):
                    continue
                if any(self._looks_like_vat_code(t) for t in toks_ln):
                    continue
                if len(nums) > 2 and re.search(r"[A-Za-z]", ln):
                    continue
            except Exception:
                pass
            # Some OCRs split qty and price onto separate lines; merge sequential numbers.
            for n in nums:
                try:
                    v = float(n)
                except Exception:
                    continue
                if pending_qty is None:
                    pending_qty = v
                else:
                    qty_price.append((float(pending_qty), float(v)))
                    pending_qty = None

            if expected_total and len(qty_price) >= expected_total:
                break

        # 3) Value/VAT/RRP/POR block (pattern scan)
        value_rows: List[Tuple[float, str, float, float]] = []
        in_v = False
        saw_std = False
        tokens_v: List[str] = []
        for ln in lines:
            up = ln.upper()
            if up.strip() == "STD" or ("STD" in up and "RRP" in up):
                saw_std = True
                in_v = True
                continue
            if ("VALUE" in up and "VAT" in up and "RRP" in up) or up.strip() == "VALUE":
                if saw_std or not in_v:
                    in_v = True
                continue
            if not in_v:
                continue
            if any(k in up for k in ("TOTALS", "INVOICE TOTAL", "PLEASE DO NOT", "RATE ", "NETT")):
                break
            # Skip VAT summary lines like "B:20.00 628.07"
            if re.search(r"\b[A-Z]{1}/?A?:\s*\d+(?:\.\d+)?", up) and re.search(r"\d+\.\d+", up):
                continue
            tokens_v.extend([t for t in re.split(r"\s+", ln) if t.strip()])

        def _is_vat_tok(t: str) -> bool:
            return self._looks_like_vat_code(t)

        def _num_tok(t: str) -> Optional[float]:
            return self._as_float(t)

        i = 0
        while i < len(tokens_v):
            # Skip VAT summary tokens like "B:20.00"
            if re.fullmatch(r"[A-Z]{1}/?A?:\d+(?:\.\d+)?", tokens_v[i], flags=re.I):
                i += 1
                continue
            val = _num_tok(tokens_v[i])
            if val is None or val < 0.5:
                i += 1
                continue
            # pattern: value, VAT code, rrp, por(%)
            if i + 3 < len(tokens_v) and _is_vat_tok(tokens_v[i + 1]):
                vat_code = self._norm_vat_code(tokens_v[i + 1])
                rrp = _num_tok(tokens_v[i + 2]) or 0.0
                por_tok = tokens_v[i + 3]
                por = _num_tok(por_tok) or 0.0
                if "%" in por_tok and por > 0:
                    value_rows.append((float(val), vat_code, float(rrp), float(por)))
                    i += 4
                    continue
            # fallback: search forward for VAT code then next two nums and optional %
            vat_code = ""
            std_rrp = 0.0
            por = 0.0
            j = i + 1
            while j < len(tokens_v) and j <= i + 3:
                if _is_vat_tok(tokens_v[j]):
                    vat_code = self._norm_vat_code(tokens_v[j])
                    j += 1
                    break
                j += 1
            if not vat_code:
                i += 1
                continue
            # rrp: next numeric
            while j < len(tokens_v):
                v = _num_tok(tokens_v[j])
                if v is not None:
                    std_rrp = float(v)
                    j += 1
                    break
                j += 1
            # por: next percent or numeric
            while j < len(tokens_v):
                if "%" in tokens_v[j]:
                    v = _num_tok(tokens_v[j])
                    por = float(v or 0.0)
                    j += 1
                    break
                v = _num_tok(tokens_v[j])
                if v is not None:
                    por = float(v)
                    j += 1
                    break
                j += 1
            value_rows.append((float(val), vat_code, float(std_rrp or 0.0), float(por or 0.0)))
            if expected_total and len(value_rows) >= expected_total:
                break
            i = j

        # Merge by index
        n = len(code_rows)
        if expected_total:
            n = min(n, expected_total)
        if qty_price:
            n = min(n, len(qty_price))
        if value_rows:
            n = min(n, len(value_rows))

        if n <= 0:
            return []

        items: List[Dict[str, Any]] = []
        for i in range(n):
            code_val, desc, case_pack, unit_size = code_rows[i]
            qty, unit_price = qty_price[i] if i < len(qty_price) else (1.0, 0.0)
            line_net, vat_code, std_rrp, por = value_rows[i] if i < len(value_rows) else (round(qty * unit_price, 2), "B", 0.0, 0.0)

            vat_rate = float(vat_map.get(vat_code, BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0)))
            # Handle void/refund lines (e.g., VOID NOTE) - keep negatives consistent
            is_void = False
            try:
                qv = float(qty or 0.0)
                ln = float(line_net or 0.0)
            except Exception:
                qv = 0.0
                ln = 0.0
            if qv < 0 or ln < 0:
                is_void = True
            # If qty negative but value positive, flip value negative
            if qv < 0 and ln > 0:
                line_net = -abs(ln)
                ln = float(line_net)
            # If value negative but qty positive, flip qty negative
            if ln < 0 and qv > 0:
                qty = -abs(qv)
                total_units = float(case_pack) * float(qty or 0.0)
            # Unit price should remain positive for display/export
            if unit_price is not None:
                try:
                    if float(unit_price) < 0:
                        unit_price = abs(float(unit_price))
                except Exception:
                    pass

            vat_amount = round(float(line_net) * (vat_rate / 100.0), 2)
            line_gross = round(float(line_net) + float(vat_amount), 2)
            total_units = float(case_pack) * float(qty)

            items.append({
                "lineNo": None,
                "code": code_val,
                "description": desc,
                "casePack": int(case_pack),
                "unitSize": unit_size,
                "qty": float(qty),
                "totalUnits": float(total_units),
                "unitPrice": float(unit_price),
                "flag": "",
                "lineNet": float(line_net),
                "vatCode": vat_code,
                "vatRate": float(vat_rate),
                "vatAmount": float(vat_amount),
                "lineGross": float(line_gross),
                "stdRrp": float(std_rrp),
                "por": float(por),
                "isVoid": is_void,
            })

        return items

    def build_rowified_text(self, text: str) -> str:
        """Rebuild Booker OCR into row-like lines (code desc pack size qty price value vat rrp por)."""
        txt = (text or "")
        txt_fix = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", txt)
        lines = [self._normalise_line(ln) for ln in txt_fix.splitlines() if (ln or "").strip()]
        up_all = "\n".join(lines).upper()

        m_total = re.search(r"TOTAL\s+ITEMS\s*:\s*(\d+)", up_all, flags=re.I)
        expected_total = int(m_total.group(1)) if m_total else 0

        # --- Code/desc/pack/size section ---
        code_rows: List[Tuple[str, str, int, str]] = []
        for i_ln, ln in enumerate(lines):
            toks = ln.split()
            if not toks:
                continue
            if not self._is_code(toks[0]):
                continue
            code_val = re.sub(r"[^0-9]+", "", toks[0])
            desc = _fix_pm_code(" ".join(toks[1:]).strip())
            case_pack = 0
            unit_size = ""
            for j in range(i_ln + 1, min(i_ln + 3, len(lines))):
                nxt = lines[j].split()
                if len(nxt) >= 2:
                    v = self._as_float(nxt[0])
                    if v is not None and abs(v - round(v)) < 1e-6 and re.search(r"[A-Za-z]", nxt[1]):
                        case_pack = int(v)
                        unit_size = nxt[1]
                        break
            if desc:
                code_rows.append((code_val, desc, case_pack, unit_size))
            if expected_total and len(code_rows) >= expected_total:
                break

        # --- Qty/price section ---
        qty_price: List[Tuple[float, float]] = []
        in_qp = False
        pending_qty = None
        for i_ln, ln in enumerate(lines):
            up = ln.upper()
            if ("QTY" in up and "PRICE" in up) or up.strip() == "QTY":
                in_qp = True
                continue
            if not in_qp:
                continue
            if ("VALUE" in up and "VAT" in up) or up.startswith("STD") or ("VALUE" in up and "RRP" in up):
                break
            nums = re.findall(r"-?\d+(?:\.\d+)?", ln.replace(",", ""))
            if not nums:
                continue
            for n in nums:
                try:
                    v = float(n)
                except Exception:
                    continue
                if pending_qty is None:
                    pending_qty = v
                else:
                    qty_price.append((float(pending_qty), float(v)))
                    pending_qty = None
            if expected_total and len(qty_price) >= expected_total:
                break

        # --- Value/vat/rrp/por section ---
        value_rows: List[Tuple[float, str, float, float]] = []
        in_v = False
        saw_std = False
        pending_value: Optional[float] = None
        pending_vat: str = ""
        pending_rrp: float = 0.0
        pending_por: float = 0.0
        for i_ln, ln in enumerate(lines):
            up = ln.upper()
            if up.strip() == "STD" or ("STD" in up and "RRP" in up):
                saw_std = True
                in_v = True
                continue
            if ("VALUE" in up and "VAT" in up and "RRP" in up) or up.strip() == "VALUE":
                # only start if we already passed the STD header, or if there is no STD header
                if saw_std or not in_v:
                    in_v = True
                continue
            if not in_v:
                continue
            if any(k in up for k in ("TOTALS", "INVOICE TOTAL", "PLEASE DO NOT", "RATE ", "NETT")):
                if value_rows:
                    break
                continue
            # Skip VAT summary lines like "B:20.00 628.07"
            if re.search(r"\b[A-Z]{1}/?A?:\s*\d+(?:\.\d+)?", up) and re.search(r"\d+\.\d+", up):
                continue
            toks = ln.split()
            if len(toks) == 1:
                tok = toks[0]
                if self._looks_like_vat_code(tok):
                    pending_vat = self._norm_vat_code(tok)
                elif "%" in tok:
                    v = self._as_float(tok)
                    if v is not None:
                        pending_por = float(v)
                else:
                    v = self._as_float(tok)
                    if v is not None:
                        if pending_value is None:
                            pending_value = float(v)
                        elif pending_rrp == 0.0:
                            pending_rrp = float(v)
                if pending_value is not None and pending_vat:
                    value_rows.append((float(pending_value), pending_vat, float(pending_rrp or 0.0), float(pending_por or 0.0)))
                    pending_value, pending_vat, pending_rrp, pending_por = None, "", 0.0, 0.0
                if expected_total and len(value_rows) >= expected_total:
                    break
                continue
            if len(toks) >= 2:
                value = self._as_float(toks[0])
                if value is None:
                    continue
                vat_code = ""
                std_rrp = 0.0
                por = 0.0
                for t in toks[1:]:
                    if self._looks_like_vat_code(t):
                        vat_code = self._norm_vat_code(t)
                        break
                if not vat_code:
                    continue
                passed_vat = False
                for t in toks[1:]:
                    if not passed_vat:
                        if self._looks_like_vat_code(t):
                            passed_vat = True
                        continue
                    if std_rrp == 0.0:
                        v = self._as_float(t)
                        if v is not None:
                            std_rrp = float(v)
                            continue
                    if "%" in t and por == 0.0:
                        v = self._as_float(t)
                        por = float(v or 0.0)
                value_rows.append((float(value), vat_code, float(std_rrp or 0.0), float(por or 0.0)))
                if expected_total and len(value_rows) >= expected_total:
                    break

        # Merge by index to rowified text
        n = len(code_rows)
        if expected_total:
            n = min(n, expected_total)
        if qty_price:
            n = min(n, len(qty_price))
        if value_rows:
            n = min(n, len(value_rows))

        if n <= 0:
            return ""

        out_lines: List[str] = []
        for i in range(n):
            code_val, desc, case_pack, unit_size = code_rows[i]
            qty, unit_price = qty_price[i] if i < len(qty_price) else (1.0, 0.0)
            line_net, vat_code, std_rrp, por = value_rows[i] if i < len(value_rows) else (round(qty * unit_price, 2), "B", 0.0, 0.0)
            # If qty/price missing, fall back to value as unit price when qty=1
            if (unit_price == 0.0) and (qty in (0.0, 1.0)) and line_net > 0:
                unit_price = float(line_net)
                if qty == 0.0:
                    qty = 1.0
            # If line_net looks like RRP (smaller than unit price), swap with std_rrp when plausible
            try:
                if unit_price > 0 and line_net > 0 and line_net < (unit_price * 0.75):
                    if std_rrp >= unit_price:
                        line_net, std_rrp = std_rrp, line_net
            except Exception:
                pass
            out_lines.append(
                f"{code_val} {desc} {case_pack} {unit_size} {qty} {unit_price:.2f} {line_net:.2f} {vat_code} {std_rrp:.2f} {por:.1f}%"
            )
        return "\n".join(out_lines)


def _booker_build_rowified_text(text: str) -> str:
    """Stable wrapper for Booker rowification.

    The Streamlit runtime has intermittently behaved as if
    `BookerCombinedRowParser.build_rowified_text` is missing even though the
    source file contains it. Route all callers through one helper so the
    Google-text fallback does not depend on that attribute lookup succeeding.
    """
    parser = BookerCombinedRowParser()
    build_fn = getattr(parser, "build_rowified_text", None)
    if callable(build_fn):
        return build_fn(text)

    txt = (text or "")
    txt_fix = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", txt)
    lines = [parser._normalise_line(ln) for ln in txt_fix.splitlines() if (ln or "").strip()]
    up_all = "\n".join(lines).upper()

    m_total = re.search(r"TOTAL\s+ITEMS\s*:\s*(\d+)", up_all, flags=re.I)
    expected_total = int(m_total.group(1)) if m_total else 0

    code_rows: List[Tuple[str, str, int, str]] = []
    for i_ln, ln in enumerate(lines):
        toks = ln.split()
        if not toks or not parser._is_code(toks[0]):
            continue
        code_val = re.sub(r"[^0-9]+", "", toks[0])
        desc = _fix_pm_code(" ".join(toks[1:]).strip())
        case_pack = 0
        unit_size = ""
        for j in range(i_ln + 1, min(i_ln + 3, len(lines))):
            nxt = lines[j].split()
            if len(nxt) >= 2:
                v = parser._as_float(nxt[0])
                if v is not None and abs(v - round(v)) < 1e-6 and re.search(r"[A-Za-z]", nxt[1]):
                    case_pack = int(v)
                    unit_size = nxt[1]
                    break
        if desc:
            code_rows.append((code_val, desc, case_pack, unit_size))
        if expected_total and len(code_rows) >= expected_total:
            break

    qty_price: List[Tuple[float, float]] = []
    in_qp = False
    pending_qty = None
    for ln in lines:
        up = ln.upper()
        if ("QTY" in up and "PRICE" in up) or up.strip() == "QTY":
            in_qp = True
            continue
        if not in_qp:
            continue
        if ("VALUE" in up and "VAT" in up) or up.startswith("STD") or ("VALUE" in up and "RRP" in up):
            break
        nums = re.findall(r"-?\d+(?:\.\d+)?", ln.replace(",", ""))
        if not nums:
            continue
        for n in nums:
            try:
                v = float(n)
            except Exception:
                continue
            if pending_qty is None:
                pending_qty = v
            else:
                qty_price.append((float(pending_qty), float(v)))
                pending_qty = None
        if expected_total and len(qty_price) >= expected_total:
            break

    value_rows: List[Tuple[float, str, float, float]] = []
    in_v = False
    saw_std = False
    pending_value: Optional[float] = None
    pending_vat: str = ""
    pending_rrp: float = 0.0
    pending_por: float = 0.0
    for ln in lines:
        up = ln.upper()
        if up.strip() == "STD" or ("STD" in up and "RRP" in up):
            saw_std = True
            in_v = True
            continue
        if ("VALUE" in up and "VAT" in up and "RRP" in up) or up.strip() == "VALUE":
            if saw_std or not in_v:
                in_v = True
            continue
        if not in_v:
            continue
        if any(k in up for k in ("TOTALS", "INVOICE TOTAL", "PLEASE DO NOT", "RATE ", "NETT")):
            if value_rows:
                break
            continue
        if re.search(r"\b[A-Z]{1}/?A?:\s*\d+(?:\.\d+)?", up) and re.search(r"\d+\.\d+", up):
            continue
        toks = ln.split()
        if len(toks) == 1:
            tok = toks[0]
            if parser._looks_like_vat_code(tok):
                pending_vat = parser._norm_vat_code(tok)
            elif "%" in tok:
                v = parser._as_float(tok)
                if v is not None:
                    pending_por = float(v)
            else:
                v = parser._as_float(tok)
                if v is not None:
                    if pending_value is None:
                        pending_value = float(v)
                    elif pending_rrp == 0.0:
                        pending_rrp = float(v)
            if pending_value is not None and pending_vat:
                value_rows.append((float(pending_value), pending_vat, float(pending_rrp or 0.0), float(pending_por or 0.0)))
                pending_value, pending_vat, pending_rrp, pending_por = None, "", 0.0, 0.0
            if expected_total and len(value_rows) >= expected_total:
                break
            continue
        if len(toks) >= 2:
            value = parser._as_float(toks[0])
            if value is None:
                continue
            vat_code = ""
            std_rrp = 0.0
            por = 0.0
            for t in toks[1:]:
                if parser._looks_like_vat_code(t):
                    vat_code = parser._norm_vat_code(t)
                    break
            if not vat_code:
                continue
            passed_vat = False
            for t in toks[1:]:
                if not passed_vat:
                    if parser._looks_like_vat_code(t):
                        passed_vat = True
                    continue
                if std_rrp == 0.0:
                    v = parser._as_float(t)
                    if v is not None:
                        std_rrp = float(v)
                        continue
                if "%" in t and por == 0.0:
                    v = parser._as_float(t)
                    por = float(v or 0.0)
            value_rows.append((float(value), vat_code, float(std_rrp or 0.0), float(por or 0.0)))
            if expected_total and len(value_rows) >= expected_total:
                break

    n = len(code_rows)
    if expected_total:
        n = min(n, expected_total)
    if qty_price:
        n = min(n, len(qty_price))
    if value_rows:
        n = min(n, len(value_rows))
    if n <= 0:
        return ""

    out_lines: List[str] = []
    for i in range(n):
        code_val, desc, case_pack, unit_size = code_rows[i]
        qty, unit_price = qty_price[i] if i < len(qty_price) else (1.0, 0.0)
        line_net, vat_code, std_rrp, por = value_rows[i] if i < len(value_rows) else (round(qty * unit_price, 2), "B", 0.0, 0.0)
        if (unit_price == 0.0) and (qty in (0.0, 1.0)) and line_net > 0:
            unit_price = float(line_net)
            if qty == 0.0:
                qty = 1.0
        try:
            if unit_price > 0 and line_net > 0 and line_net < (unit_price * 0.75):
                if std_rrp >= unit_price:
                    line_net, std_rrp = std_rrp, line_net
        except Exception:
            pass
        out_lines.append(
            f"{code_val} {desc} {case_pack} {unit_size} {qty} {unit_price:.2f} {line_net:.2f} {vat_code} {std_rrp:.2f} {por:.1f}%"
        )
    return "\n".join(out_lines)

def _booker_parse_stacked_layout(text: str) -> List[Dict[str, Any]]:
    """Stable wrapper for Booker stacked-layout parsing."""
    parser = BookerCombinedRowParser()
    parse_fn = getattr(parser, "parse_stacked_layout", None)
    if callable(parse_fn):
        try:
            return parse_fn(text)
        except Exception:
            pass
    return []

def _booker_parse_stacked_ocr_text(text: str) -> List[Dict[str, Any]]:
    """Parse Booker OCR text where each item is emitted as a vertical stack of lines."""
    parser = BookerCombinedRowParser()
    parse_fn = getattr(parser, "parse_stacked_ocr_text", None)
    if callable(parse_fn):
        try:
            return parse_fn(text)
        except Exception:
            pass

    txt = (text or "")
    txt_fix = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", txt)
    vat_map = parser._extract_vat_map(txt_fix)
    lines = [parser._normalise_line(ln) for ln in txt_fix.splitlines() if (ln or "").strip()]
    items: List[Dict[str, Any]] = []
    pending: List[Dict[str, Any]] = []
    void_next = False

    def _is_code_line(s: str) -> bool:
        toks = s.split()
        return bool(toks and parser._is_code(toks[0]) and len(toks) > 1)

    def _is_pack_line(s: str) -> bool:
        toks = s.split()
        if len(toks) < 2:
            return False
        v = parser._as_float_strict(toks[0])
        if v is None or abs(v - round(v)) > 1e-6:
            return False
        return bool(re.search(r"[A-Za-z]", toks[1]))

    def _is_qty_line(s: str) -> bool:
        return bool(re.fullmatch(r"-?\d+(?:\.\d+)?-?\.?", s.strip()))

    def _is_moneyish(s: str) -> bool:
        return parser._as_float(s) is not None

    def _skip_noise(idx: int) -> int:
        while idx < len(lines):
            up = lines[idx].upper().strip()
            if not up:
                idx += 1
                continue
            if up in {"STD", "CODE", "DESCRIPTION", "PACK SIZE", "QTY", "PRICE", "VALUE", "VAT", "RRP", "POR", "RRP POR"}:
                idx += 1
                continue
            if any(k in up for k in (
                "SUB-TOTAL", "TOTAL ITEMS", "TOTAL SAVINGS", "PROMOTIONS SAVED YOU",
                "CLUB PROMOTIONS SAVED YOU", "INVOICE TOTAL", "PLEASE DO NOT BRING BACK",
                "TRAYS AND KEGS", "SAVING DETAILS", "GOODS", "EXC.VAT", "/CONT", "PAGE 0",
                "BRANCH ", "CUSTOMER ", "DATE ", "TIME ", "RATE", "NETT", "MULT"
            )):
                idx += 1
                continue
            if up in {
                "RETAIL GROCERY", "CHILLED", "CONFECTIONERY", "FROZEN FOOD",
                "WINES SPIRITS BEERS", "FROZEN", "TOBACCO"
            }:
                idx += 1
                continue
            break
        return idx

    i = 0
    while i < len(lines):
        i = _skip_noise(i)
        if i >= len(lines):
            break
        line = lines[i].strip()
        up = line.upper()

        if up == "VOID NOTE":
            void_next = True
            i += 1
            continue

        if _is_code_line(line):
            toks = line.split()
            code_val = re.sub(r"[^0-9]+", "", toks[0])
            desc = _fix_pm_code(" ".join(toks[1:]).strip())
            pending.append({"code": code_val, "description": desc})
            i += 1
            continue

        if not pending or not _is_pack_line(line):
            i += 1
            continue

        current = pending.pop(0)
        pack_toks = line.split()
        case_pack = int(parser._as_float(pack_toks[0]) or 0)
        unit_size = pack_toks[1]

        j = i + 1
        j = _skip_noise(j)
        if j >= len(lines) or not _is_qty_line(lines[j]):
            i += 1
            continue
        qty = float(parser._as_float(lines[j]) or 0.0)

        j += 1
        j = _skip_noise(j)
        if j >= len(lines):
            break
        price_line = lines[j].strip()
        price_toks = price_line.split()
        unit_price = 0.0
        flag = ""
        for tok in price_toks:
            f = parser._norm_flag(tok)
            if f:
                flag = f
                continue
            v = parser._as_float(tok)
            if v is not None:
                unit_price = float(v)
                break
        if unit_price == 0.0 and not _is_moneyish(price_line):
            i += 1
            continue

        j += 1
        j = _skip_noise(j)
        if j >= len(lines):
            break
        value_line = lines[j].strip()
        value_toks = value_line.split()
        line_net = 0.0
        vat_code = ""
        for tok in value_toks:
            if not vat_code and parser._looks_like_vat_code(tok):
                vat_code = parser._norm_vat_code(tok)
                continue
            if parser._as_float(tok) is not None and line_net == 0.0:
                line_net = float(parser._as_float(tok) or 0.0)
        if not vat_code:
            j += 1
            j = _skip_noise(j)
            if j < len(lines) and parser._looks_like_vat_code(lines[j].strip()):
                vat_code = parser._norm_vat_code(lines[j].strip())
            else:
                vat_code = "B"
                j -= 1

        j += 1
        j = _skip_noise(j)
        std_rrp = 0.0
        por = 0.0
        if j < len(lines):
            rrp_line = lines[j].strip()
            if "%" in rrp_line:
                for tok in rrp_line.split():
                    if std_rrp == 0.0 and parser._as_float(tok) is not None:
                        std_rrp = float(parser._as_float(tok) or 0.0)
                        continue
                    if "%" in tok:
                        por = float(parser._as_float(tok) or 0.0)
                j += 1

        vat_rate = float(vat_map.get(vat_code, BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0)))
        if qty < 0 and line_net > 0:
            line_net = -abs(line_net)
        is_void = bool(void_next or qty < 0 or line_net < 0)
        void_next = False
        total_units = float(abs(qty) * case_pack)
        vat_amount = round(float(line_net) * (vat_rate / 100.0), 2)
        line_gross = round(float(line_net) + float(vat_amount), 2)

        items.append({
            "lineNo": None,
            "code": current["code"],
            "description": current["description"],
            "casePack": int(case_pack),
            "unitSize": unit_size,
            "qty": float(qty),
            "totalUnits": float(total_units),
            "unitPrice": float(unit_price),
            "flag": flag,
            "lineNet": float(line_net),
            "vatCode": vat_code,
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amount),
            "lineGross": float(line_gross),
            "stdRrp": float(std_rrp),
            "por": float(por),
            "isVoid": is_void,
        })
        i = j

    return items


# -------------------------
# Parfetts parsing (Purchase Invoice)
# -------------------------

PARFETTS_VAT_MAP_DEFAULT = {
    "A": 20.0,
    "Z": 0.0,
    "R": 5.0,
    "B": 20.0,
}


def _parfetts_vat_breakdown_from_items(items: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Compute Parfetts-style VAT breakdown from line items.

    Returns:
      {
        "rows": [{"vatCode":"A","goodsAmount":2666.88,"vatAmount":533.38}, ...],
        "totalNet": 3033.74,
        "totalVat": 533.38,
        "totalGross": 3567.12
      }
    VAT is calculated at *code-group* level to match Parfetts invoice summary (reduces per-line rounding drift).
    """
    if not items:
        return {"rows": [], "totalNet": 0.0, "totalVat": 0.0, "totalGross": 0.0}

    # Aggregate net by VAT code
    by_code: Dict[str, float] = {}
    rates_by_code: Dict[str, List[float]] = {}
    items_for_metrics = items
    try:
        items_for_metrics = [it for it in items_for_metrics if not (isinstance(it, dict) and it.get("isVoid"))]
    except Exception:
        pass

    for it in items_for_metrics:
        vc = str(it.get("vatCode") or "").strip().upper()
        if not vc:
            continue
        net = _safe_float(it.get("lineNet"))
        by_code[vc] = by_code.get(vc, 0.0) + net
        r = _safe_float(it.get("vatRate"))
        if r > 0:
            rates_by_code.setdefault(vc, []).append(r)

    rows: List[Dict[str, Any]] = []
    for vc, net_sum in by_code.items():
        # Prefer the most common vatRate observed for this code; else fall back to default map
        rate = 0.0
        try:
            lst = rates_by_code.get(vc) or []
            if lst:
                from collections import Counter
                rate = float(Counter([round(x, 2) for x in lst]).most_common(1)[0][0])
            else:
                rate = _safe_float(PARFETTS_VAT_MAP_DEFAULT.get(vc))
        except Exception:
            rate = _safe_float(PARFETTS_VAT_MAP_DEFAULT.get(vc))
        vat_sum = round(float(net_sum) * float(rate) / 100.0, 2)
        rows.append({
            "vatCode": vc,
            "goodsAmount": round(float(net_sum), 2),
            "vatAmount": float(vat_sum),
        })

    # Sort A then Z then others for a familiar Parfetts look
    def _vk(x: str) -> Tuple[int, str]:
        if x == "A":
            return (0, x)
        if x == "Z":
            return (1, x)
        return (2, x)

    rows = sorted(rows, key=lambda r: _vk(str(r.get("vatCode") or "").upper()))

    tot_net = round(sum(_safe_float(r.get("goodsAmount")) for r in rows), 2)
    tot_vat = round(sum(_safe_float(r.get("vatAmount")) for r in rows), 2)
    tot_gross = round(tot_net + tot_vat, 2)
    return {"rows": rows, "totalNet": tot_net, "totalVat": tot_vat, "totalGross": tot_gross}


# ---------------------------
# Generic VAT Breakdown helpers (Booker, DWG, others)
# ---------------------------

def _vat_code_rate_map_for_supplier(supplier_hint: str) -> Dict[str, float]:
    """Supplier-specific VAT code  rate mapping (UK, percent).
    Used to infer vatRate when vatCode exists but vatRate is missing/blank/non-numeric.
    """
    s = (supplier_hint or "").lower()

    # Dhamecha: A=20%, B=5%, Z=0%
    if "dhamecha" in s:
        return {"A": 20.0, "B": 5.0, "Z": 0.0}

    # Booker known: B=20%, R=5%, C=5%, Z=0%, A=0% (per your template guidance).
    if "booker" in s:
        return {"B": 20.0, "R": 5.0, "C": 5.0, "Z": 0.0, "A": 0.0}

    # A F Blakemore / SPAR wholesale invoices: A is zero-rated, B is standard.
    if "blakemore" in s:
        return {"B": 20.0, "R": 5.0, "Z": 0.0, "A": 0.0}

    # DWG common: S/A or S => 20%
    if ("drinks wholesale" in s) or ("dwg" in s):
        return {"S/A": 20.0, "S": 20.0}

    # Default common UK codes (best-effort)
    return {"S": 20.0, "T": 20.0, "A": 20.0, "B": 20.0, "R": 5.0, "Z": 0.0, "E": 0.0, "X": 0.0}



def _nearest_uk_vat_rate(x: float) -> float:
    # Snap an inferred VAT rate to common UK rates (0/5/20).
    try:
        x = float(x)
    except Exception:
        return 0.0
    candidates = [0.0, 5.0, 20.0]
    return min(candidates, key=lambda c: abs(c - x))


def _infer_vat_rate(it: Dict[str, Any], supplier_hint: str) -> float:
    # Infer VAT rate for an item: prefer explicit vatRate, else code mapping, else gross-net.
    vr = _safe_float(it.get("vatRate"))
    # Some Cloud models return VAT as a fraction (e.g. 0.2 for 20%). Normalise to percent.
    if 0 < vr < 1.0:
        vr = vr * 100.0
    if vr > 0:
        return vr
    vc = str(it.get("vatCode") or "").strip().upper()
    m = _vat_code_rate_map_for_supplier(supplier_hint)
    if vc and vc in m:
        return float(m[vc])
    net = _safe_float(it.get("lineNet"))
    gross = _safe_float(it.get("lineGross"))
    if net > 0 and gross > net:
        approx = ((gross - net) / net) * 100.0
        return float(_nearest_uk_vat_rate(approx))
    return 0.0



def _dwg_enrich_header_items(header, items, supplier_hint=""):
    """DWG (Drinks Wholesale Group) normalisation.

    Ensures DWG line-items have:
      - vatCode populated (often appears in vatRate field as 'S/A')
      - vatRate numeric (e.g. S/A => 20.0)
      - vatAmount + lineGross calculated when missing
      - totalUnits calculated when possible (qty * casePack)

    Returns (header, items) always.
    """
    header = header or {}
    items = items or []
    # Metrics-safe list (exclude voids if any)
    items_for_metrics = items
    try:
        items_for_metrics = [it for it in items_for_metrics if not (isinstance(it, dict) and it.get('isVoid'))]
    except Exception:
        pass

    s = f"{supplier_hint or ''} {header.get('supplierName') or ''}"
    s_low = s.lower()
    is_dwg = any(k in s_low for k in [
        "dwg",
        "drinks wholesale",
        "drinks wholesale group",
        "drinkswholesale",
        "drinks wholesale group ltd",
    ])
    if not is_dwg:
        return header, items

    # Default VAT code/rate (DWG invoices are typically single-rate 'S/A' = 20%)
    default_code = None
    default_rate = None
    def _as_float_or_none(v):
            """Parse float but keep None for missing/blank."""
            if v is None:
                return None
            if isinstance(v, str):
                s = v.strip()
                if not s or s.lower() in ("none", "null", "nan"):
                    return None
                s = s.replace(",", "").replace("%", "")
                try:
                    return float(s)
                except Exception:
                    return None
            try:
                return float(v)
            except Exception:
                return None

    if re.search(r"\bS/A\b", s, flags=re.I):
        default_code = "S/A"
        default_rate = 20.0

    # Infer from items if possible
    for it in items_for_metrics:
        if not isinstance(it, dict):
            continue
        vc = it.get("vatCode")
        vr = it.get("vatRate")
        if isinstance(vc, str) and re.search(r"\bS/A\b", vc, flags=re.I):
            default_code, default_rate = "S/A", 20.0
            break
        if isinstance(vr, str) and re.search(r"\bS/A\b", vr, flags=re.I):
            default_code, default_rate = "S/A", 20.0
            break

    hdr_net = _safe_float(header.get("totalNet"))
    hdr_vat = _safe_float(header.get("totalVat"))

    if default_rate is None and hdr_net and hdr_vat and hdr_net != 0:
        # Use header ratio as fallback
        default_rate = (hdr_vat / hdr_net) * 100.0

    if default_code is None:
        if default_rate is not None and abs(default_rate - 20.0) < 0.75:
            default_code = "S/A"
        else:
            default_code = "NA"

    if default_rate is None:
        default_rate = 0.0
    def _extract_std_rrp_from_desc(desc: str) -> Tuple[float, str]:
        """Extract DWG PM/PMP (RRP) from a description string.
    
        Supports both pounds and pence formats seen on DWG invoices, e.g.
          - "PM 2.99" / "PM 2.99"
          - "PMP 2.99" / "PMP2.99"
          - "PM 69P" / "PM 70p" (pence)
          - Occasionally: "2.99 PMP" / "69P PM" (rare OCR ordering)
    
        Returns (rrp, cleaned_description). If not found, rrp=0.0 and description unchanged.
        """
        if not desc:
            return 0.0, ""
        d = str(desc)

        # Fast path: PMP/PM followed by 2-4 digits (e.g. PMP109 => 1.09, PM1299 => 12.99)
        mm = re.search(
            r"(?i)\b(PMP|PM)\s*[:\-]?\s*(?P<amt>[0-9]{2,4})(?:\s*[pP])?\b",
            d,
        )
        if not mm:
            mm = re.search(
                r"(?i)\b(?P<amt>[0-9]{2,4})(?:\s*[pP])?\s*(PMP|PM)\b",
                d,
            )
        if mm:
            raw_amt = (mm.group("amt") or "").strip()
            try:
                price = float(raw_amt) / 100.0
            except Exception:
                price = None
            if price is not None:
                d2 = (d[:mm.start()] + d[mm.end():]).strip()
                d2 = re.sub(r"\b(PMP?|PM)\b\s*$", "", d2, flags=re.IGNORECASE).strip()
                d2 = re.sub(r"\s{2,}", " ", d2)
                return float(round(price, 2)), d2

        # 1) Token then amount (most common). Allow no-space token->amount (e.g. "PM69P") from OCR.
        mm = re.search(
            r"(?<![A-Z0-9])(?P<tok>PMPX|PM)\s*[:\-]X\s*(?:\(\s*)XX\s*(?P<amt>[0-9]+(?:\.[0-9]{1,2})X)(?P<pence>[pP])X(?:\s*\))X",
            d,
            flags=re.IGNORECASE,
        )
        # 2) Amount then token (rare ordering)
        if not mm:
            mm = re.search(
                r"X\s*(?P<amt>[0-9]+(?:\.[0-9]{1,2})X)(?P<pence>[pP])X\s*(?P<tok>PMPX|PM)\b",
                d,
                flags=re.IGNORECASE,
            )
    
        if not mm:
            return 0.0, d.strip()
    
        raw_amt = (mm.group("amt") or "").strip()
        pence_flag = (mm.group("pence") or "").strip()
        match_txt = mm.group(0) or ""
    
        price = None
        try:
            price = float(raw_amt)
        except Exception:
            price = None
        if price is None:
            return 0.0, d.strip()
    
        # Convert pence to pounds when indicated or strongly implied.
        has_decimal = "." in raw_amt
        has_pound = "" in match_txt
        if (pence_flag and not has_decimal) or (not has_decimal and not has_pound and 10 <= price <= 99):
            price = price / 100.0
    
        d2 = (d[:mm.start()] + d[mm.end():]).strip()
        d2 = re.sub(r"\b(PMP?|PM)\b\s*$", "", d2, flags=re.IGNORECASE).strip()
        d2 = re.sub(r"\s{2,}", " ", d2)
        return float(round(price, 2)), d2
    for it in items:
        if not isinstance(it, dict):
            continue
        # --- Normalise key casing from different engines (defensive) ---
        try:
            for k_src, k_dst in [
                ("casepack", "casePack"),
                ("case_pack", "casePack"),
                ("unitsize", "unitSize"),
                ("unit_size", "unitSize"),
                ("totalunits", "totalUnits"),
                ("total_units", "totalUnits"),
                ("stdrrp", "stdRrp"),
                ("std_rrp", "stdRrp"),
                ("vatcode", "vatCode"),
                ("vat_code", "vatCode"),
                ("vatrate", "vatRate"),
                ("vat_rate", "vatRate"),
                ("vatamount", "vatAmount"),
                ("vat_amount", "vatAmount"),
                ("linegross", "lineGross"),
                ("line_gross", "lineGross"),
                ("linen et", "lineNet"),
                ("line_net", "lineNet"),
                ("unitprice", "unitPrice"),
                ("unit_price", "unitPrice"),
            ]:
                if k_src in it and k_dst not in it:
                    it[k_dst] = it.pop(k_src)
        except Exception:
            pass

        # --- Fix DWG Auto description/code when OCR returns combined tokens ---
        try:
            desc0 = str(it.get("description") or "")
            if desc0:
                d = desc0.lstrip("~").strip()

                # If lineNo is duplicated at the start of description, remove it
                ln = it.get("lineNo")
                if ln is not None:
                    try:
                        ln_i = int(float(ln))
                        d = re.sub(rf"^\s*{ln_i}\s+", "", d)
                    except Exception:
                        pass

                # If description starts with a code token (after removing lineNo), pull it into code if code missing
                if not str(it.get("code") or "").strip():
                    mcode = re.match(r"^([A-Za-z0-9][A-Za-z0-9\-]{1,20})\s+(.+)$", d)
                    if mcode:
                        tok = mcode.group(1)
                        # Avoid taking a pack token like 42X200ML as the code
                        if not re.match(r"^\d{1,3}\s*[xX]\s*\d", tok):
                            it["code"] = tok
                            d = mcode.group(2).strip()

                # If description now begins with a pack token, strip & map into fields
                mpack0 = re.match(r"^(\d{1,3})\s*[xX]\s*([0-9]+(?:\.[0-9]+)?)\s*(cl|ml|l|g|kg|oz)\b\s*(.*)$", d, flags=re.IGNORECASE)
                if mpack0:
                    cp_now = _safe_float(it.get("casePack")) or 0.0
                    if cp_now <= 0:
                        it["casePack"] = int(mpack0.group(1))
                    if not (it.get("unitSize") and str(it.get("unitSize")).strip()):
                        it["unitSize"] = f"{mpack0.group(2)}{mpack0.group(3).lower()}"
                    d = (mpack0.group(4) or "").strip()

                it["description"] = _fix_pm_code(re.sub(r"\s{2,}", " ", d).strip())
        except Exception:
            pass


        # Normalise code when Cloud/Local returns prefixed tokens (e.g. "1 WAG3" or "~ 1 REDB-ED22")
        try:
            c = str(it.get("code") or "").strip()
            c = c.lstrip("~").strip()
            mmc = re.match(r"^(\d+)\s+([A-Za-z0-9\-]+)$", c)
            if mmc:
                # Keep qty as-is unless missing; strip the numeric prefix from code
                if not it.get("qty"):
                    try:
                        it["qty"] = float(mmc.group(1))
                    except Exception:
                        pass
                it["code"] = mmc.group(2)
            else:
                # If code empty but description starts with an alnum code token, pick it up
                if not c:
                    d0 = str(it.get("description") or "").strip()
                    d0 = d0.lstrip("~").strip()
                    mmc2 = re.match(r"^([A-Za-z0-9\-]{3,12})\s+(.+)$", d0)
                    if mmc2:
                        it["code"] = mmc2.group(1)
                        it["description"] = mmc2.group(2)
        except Exception:
            pass

        # DWG: extract PM/PMP RRP from description into stdRrp (when missing)
        try:
            if (_safe_float(it.get("stdRrp")) or 0.0) <= 0.0:
                rr, dd = _extract_std_rrp_from_desc(str(it.get("description") or ""))
                if rr and rr > 0:
                    it["stdRrp"] = float(rr)
                    if dd:
                        it["description"] = dd
        except Exception:
            pass

        # Sometimes DWG puts VAT code in vatRate field (e.g. vatRate='S/A')
        vr_raw = it.get("vatRate")
        vc_raw = it.get("vatCode")
        if (not vc_raw) and isinstance(vr_raw, str):
            vr_str = vr_raw.strip()
            if vr_str and len(vr_str) <= 8 and re.search(r"[A-Za-z/]", vr_str):
                it["vatCode"] = vr_str
                vr_raw = None

        if not it.get("vatCode"):
            it["vatCode"] = default_code

        # VAT rate numeric
        rate_val = _as_float_or_none(vr_raw)
        if rate_val is None:
            vc = it.get("vatCode") or ""
            if isinstance(vc, str) and re.search(r"\bS/A\b", vc, flags=re.I):
                rate_val = 20.0
            else:
                rate_val = default_rate
        it["vatRate"] = rate_val if rate_val is not None else 0.0

        # Total units (qty * casePack)
        qty = _safe_float(it.get("qty")) or 0.0
        case_pack = _safe_float(it.get("casePack"))
        # Treat blanks/zero as missing (Cloud sometimes returns 0/0.0)
        if case_pack is None or case_pack <= 0:
            desc = str(it.get("description") or "")
            # Patterns like: 6X20CL, 24x330ml, 12 X 1L, 10x50g
            m = re.search(r"\b(\d{1,3})\s*[xX]\s*([0-9]+(?:\.[0-9]+)?)\s*(cl|ml|l|g|kg|oz)\b", desc, flags=re.IGNORECASE)
            if m:
                case_pack = _safe_float(m.group(1))
                if not (it.get("unitSize") and str(it.get("unitSize")).strip()):
                    it["unitSize"] = f"{m.group(2)}{m.group(3).lower()}"
            else:
                # Fallback: just get the pack count if we can (e.g. 6x something)
                m2 = re.search(r"\b(\d{1,3})\s*[xX]\s*(?=\d)", desc)
                if m2:
                    case_pack = _safe_float(m2.group(1))
            if case_pack is not None and (not it.get("casePack") or str(it.get("casePack")).strip() in ("", "None", "0", "0.0")):
                it["casePack"] = int(case_pack) if abs(case_pack - int(case_pack)) < 1e-9 else case_pack

        if (it.get("totalUnits") in (None, "", 0)) and qty and case_pack:
            tu = qty * case_pack
            it["totalUnits"] = int(tu) if abs(tu - int(tu)) < 1e-9 else tu

        # Ensure lineNet (Gemini sometimes returns 0/None; recompute from unitPrice*qty)
        line_net = _safe_float(it.get("lineNet"))
        unit_price = _safe_float(it.get("unitPrice")) or 0.0
        if (line_net is None) or (line_net == 0 and unit_price > 0 and (qty or 0) > 0):
            if qty:
                line_net = unit_price * qty
            else:
                line_net = unit_price
        it["lineNet"] = round(line_net, 2) if line_net is not None else None

        # VAT amount
        vat_amt = _as_float_or_none(it.get("vatAmount"))
        if (vat_amt is None) or (vat_amt == 0 and (rate_val or 0.0) > 0 and (line_net or 0.0) > 0):
            vat_amt = round((line_net or 0.0) * (rate_val or 0.0) / 100.0, 2)
            it["vatAmount"] = vat_amt

        # Gross
        gross = _as_float_or_none(it.get("lineGross"))
        if (gross is None) or (gross == 0 and (line_net or 0.0) > 0):
            gross = round((line_net or 0.0) + (vat_amt or 0.0), 2)
            it["lineGross"] = gross


        # Compute POR (%) if missing/zero and we have stdRrp + units.
        # POR definition aligned with Booker: (SellingNet - UnitCost) / SellingNet * 100
        try:
            por_val = _as_float_or_none(it.get("por"))
            if por_val is None or por_val == 0:
                rrp_gross = _as_float_or_none(it.get("stdRrp")) or 0.0
                tu = _safe_float(it.get("totalUnits")) or 0.0
                if rrp_gross > 0 and tu > 0:
                    vat_rate = _as_float_or_none(it.get("vatRate")) or 0.0
                    selling_net = rrp_gross / (1.0 + (vat_rate / 100.0)) if vat_rate > 0 else rrp_gross
                    unit_cost = (line_net or 0.0) / tu if tu else 0.0
                    if selling_net > 0:
                        por_calc = ((selling_net - unit_cost) / selling_net) * 100.0
                        if por_calc < 0:
                            por_calc = 0.0
                        it["por"] = round(por_calc, 1)
        except Exception:
            pass

    return header, items


def _dhamecha_parse_vat_code_rate_table(doc_text: str) -> dict[str, float]:
    """Parse Dhamecha VAT code->rate table.

    Handles both formats commonly seen in PDFs/OCR:
      1) Multi-line header:
         Code
         Rate
         A
         20
      2) Single-line rows:
         Code  Rate
         A     20
         B     5
         Z     0
    """
    mapping: dict[str, float] = {}
    lines = [ln.strip() for ln in (doc_text or "").splitlines()]

    # Find table header (either 'Code' then 'Rate' on next line, or 'Code Rate' on one line)
    start_idx = None
    for i, ln in enumerate(lines):
        lo = ln.lower()
        if "code" in lo and "rate" in lo:
            start_idx = i + 1
            break
        # Sometimes header appears as two consecutive lines: 'Code' then 'Rate'
        if lo == "code" and i + 1 < len(lines) and lines[i + 1].strip().lower() == "rate":
            start_idx = i + 2
            break

    if start_idx is None:
        return mapping

    # Parse subsequent lines until we hit a blank run or something clearly outside the table.
    blank_run = 0
    for j in range(start_idx, len(lines)):
        ln = lines[j]
        if not ln:
            blank_run += 1
            if blank_run >= 2:
                break
            continue
        blank_run = 0

        # Single-line row like: 'A 20' or 'A: 20%' or 'A    20.0'
        m = re.match(r'^([A-Z])\s*[:\-]?\s*(\d+(?:\.\d+)?)\s*%?$', ln)
        if m:
            mapping[m.group(1)] = float(m.group(2))
            continue

        # Multi-line variant: code on its own line then rate on next line
        if re.fullmatch(r"[A-Z]", ln) and j + 1 < len(lines):
            nxt = lines[j + 1].strip()
            m2 = re.match(r'^(\d+(?:\.\d+)?)\s*%?$', nxt)
            if m2:
                mapping[ln] = float(m2.group(1))
                continue

        # Stop if we start seeing non-table content
        if len(mapping) >= 1 and re.search(r'(invoice|total|vat|gross|net|amount)', ln, re.I):
            break

    return mapping


def _dhamecha_build_item_map(doc_text: str) -> dict[str, dict]:
    """Build a lightweight map keyed by Dhamecha *Item #* (usually 57 digits).

    Why this exists:
      - Dhamecha invoices have the VAT code (A/B/Z) as a single letter in the last column.
      - Cloud extraction can occasionally mis-read that narrow column.
      - The PDF text layer usually contains the correct VAT code per row; we use it as source-of-truth.

    The function supports two text formats:
      1) PDF text-layer "row" lines (most common): each item row is one line starting with the item #,
         and descriptions may wrap onto the next line(s) where the VAT code appears at the end.
      2) OCR tokenised text: item # appears on its own line, with tokens below it.
    """
    lines = [ln.rstrip() for ln in (doc_text or "").splitlines()]
    out: dict[str, dict] = {}

    def _normalise_compact_row(line: str) -> str:
        s = (line or "").replace("Ã‚Â£", "£").replace("Â£", "£").replace("Ł", "£").strip()
        if not s:
            return ""
        s = re.sub(r"^\s*(\d{3,9})(?=[A-Za-z£])", r"\1 ", s)
        s = re.sub(
            r"(£\d+\.\d{2})(\d+(?:\.\d+)?(?:MM|CM|M|ML|CL|L|LTR|LITR|LITRE|LITRES|G|KG|OZ|LB|PK|PCS|PC|W|'S))\b",
            r"\1 \2",
            s,
            flags=re.IGNORECASE,
        )
        s = re.sub(r"(\d+(?:\.\d+)?)%([A-Z])\b", r"\1% \2", s)
        s = re.sub(r"\s+", " ", s)
        return s.strip()

    def _strip_price_token(tok: str) -> str:
        t = (tok or "").replace("Ã‚Â£", "").replace("Â£", "").replace("Ł", "").strip()
        t = re.sub(r"(?<=\d)[A-Za-z]+$", "", t)
        return t.strip()

    def _extract_size_from_text(desc: str, uop: str = "", uos: str = "") -> str:
        txt = " ".join([str(desc or "").strip(), str(uop or "").strip(), str(uos or "").strip()]).strip()
        m = re.findall(r"(?i)\b(\d+(?:\.\d+)?\s*(?:mm|cm|m|ml|cl|l|ltr|litr|litre|litres|g|kg|oz|lb|pk|pcs|pc|w|'s))\b", txt)
        return _collapse_spaces(m[-1]) if m else ""

    # ---- A) Row-based parse (PDF text layer) ----
    current_code: str | None = None
    for raw in lines:
        ln = _normalise_compact_row((raw or "").strip())
        if not ln:
            continue

        # Start of an item row: 57 digits followed by a space
        m = re.match(r'^(\d{5,7})\s+.+$', ln)
        if m:
            current_code = m.group(1)
            out.setdefault(current_code, {"vatCode": None, "casePack": None})

            toks = ln.split()
            try:
                if len(toks) >= 9:
                    vat_code = BookerCombinedRowParser._norm_vat_code(toks[-1])
                    if re.fullmatch(r"[ABZR]", vat_code):
                        por_idx = None
                        for k in range(len(toks) - 2, max(len(toks) - 6, 1), -1):
                            if "%" in toks[k]:
                                por_idx = k
                                break
                        if por_idx is None:
                            por_idx = len(toks) - 2
                        rrp_idx = por_idx - 1
                        ext_idx = rrp_idx - 1
                        price_idx = ext_idx - 1
                        qty_idx = price_idx - 1
                        uos_idx = qty_idx - 1
                        uop_idx = uos_idx - 1
                        if ext_idx > 1 and qty_idx > 1:
                            qty = _safe_float(_strip_price_token(toks[qty_idx]))
                            unit_price = _safe_float(_strip_price_token(toks[price_idx]))
                            line_net = _safe_float(_strip_price_token(toks[ext_idx]))
                            std_rrp = _safe_float(_strip_price_token(toks[rrp_idx]))
                            por = _safe_float(str(toks[por_idx] or "").replace("%", "").strip())
                            uop_tok = toks[uop_idx] if uop_idx < len(toks) else ""
                            uos_tok = toks[uos_idx] if uos_idx < len(toks) else ""
                            desc = " ".join(toks[1:max(uop_idx, 1)]).strip()
                            desc = re.sub(r"\s*[£Ł]\d+\.\d{2}\b", "", desc).strip()
                            unit_size = _extract_size_from_text(desc, uop_tok, uos_tok)
                            if qty is not None:
                                out[current_code]["qty"] = float(qty)
                            if unit_price is not None:
                                out[current_code]["unitPrice"] = float(unit_price)
                            if line_net is not None:
                                out[current_code]["lineNet"] = float(line_net)
                            if std_rrp is not None:
                                out[current_code]["stdRrp"] = float(std_rrp)
                            if por is not None:
                                out[current_code]["por"] = float(por)
                            if unit_size:
                                out[current_code]["unitSize"] = unit_size
                            if desc:
                                out[current_code]["description"] = _collapse_spaces(desc)
                            cp = _safe_float(uos_tok)
                            if cp and cp > 0:
                                out[current_code]["casePack"] = float(cp)
            except Exception:
                pass

        # VAT code is a single trailing letter A/B/Z (e.g., "... 0% A" or "... 0.0% Z")
        mvat = re.search(r'\s([ABZ])\s*$', ln, flags=re.IGNORECASE)
        if mvat and current_code:
            out.setdefault(current_code, {"vatCode": None, "casePack": None})
            out[current_code]["vatCode"] = mvat.group(1).upper()

            # Try best-effort casePack parse from the same line (not critical for VAT)
            # Common pattern: "... - 24 1 23.99 23.99P ..."
            mcp = re.search(r'\s-\s*(\d+)\s+\d+\s+\d+(?:\.\d+)?\s+\d+\.\d{2}\b', ln)
            if mcp:
                try:
                    out[current_code]["casePack"] = float(mcp.group(1))
                except Exception:
                    pass

            current_code = None  # done with this row (until next item #)

    # ---- B) Token-based parse (PyMuPDF token stream) ----
    # Fallback for text where item # appears on its own line (common with PyMuPDF text extraction).
    if not out:
        lines2 = [ln.strip() for ln in (doc_text or "").splitlines()]
        code_idxs = [i for i, ln in enumerate(lines2) if re.fullmatch(r"\d{5,7}", ln)]

        for k, idx in enumerate(code_idxs):
            code = lines2[idx]
            end = code_idxs[k + 1] if k + 1 < len(code_idxs) else len(lines2)

            # Stop at end-of-item markers so we don't accidentally pick up VAT codes from the footer VAT table.
            stop = end
            for j in range(idx + 1, end):
                lo = (lines2[j] or "").lower()
                if lo.startswith("trolley:") or lo.startswith("items total") or ("code rate" in lo) or lo.startswith("total goods"):
                    stop = j
                    break

            seg = [s for s in lines2[idx:stop] if s]

            # VAT code (A/B/Z) usually appears as a single-letter token immediately after a percentage token (POR column).
            vat_code = None
            for j in range(len(seg) - 1):
                if re.fullmatch(r"\d+(?:\.\d+)?%", seg[j]):
                    cand = (seg[j + 1] or "").strip().upper()
                    if re.fullmatch(r"[ABZ]", cand):
                        vat_code = cand

            # Fallback: last A/B/Z within the *item segment* (not the whole page).
            if not vat_code:
                for s in seg:
                    if re.fullmatch(r"[ABZ]", s, flags=re.IGNORECASE):
                        vat_code = s.upper()

            # Find first float (unit price typically). Use last 2 ints before it as (casePack, qty)
            unit_price_idx = None
            for j, s in enumerate(seg):
                if re.fullmatch(r"\d+\.\d{2}", s):
                    unit_price_idx = j
                    break

            case_pack = None
            if unit_price_idx is not None:
                ints = []
                for t in seg[:unit_price_idx]:
                    if re.fullmatch(r"\d+", t):
                        ints.append(int(t))
                if len(ints) >= 2:
                    case_pack = float(ints[-2])

            out[code] = {"vatCode": vat_code, "casePack": case_pack}
    return out



def _dhamecha_enrich_header_items(header: dict, items: list[dict], doc_text_hint: str = "") -> None:
    """Dhamecha-specific post-processing: VAT code/rate/amount + casePack fixes.

    Goal:
      - Ensure each line has vatCode (A/B/Z), vatRate (20/5/0) and vatAmount consistent with lineNet
      - Improve VAT Breakdown grouping (depends on vatCode)
      - Keep totals aligned for downstream posting into VBR EPOS / Cloud Reporting
    """
    if not items:
        return

    vat_rates = _dhamecha_parse_vat_code_rate_table(doc_text_hint) or {}
    # Fallback default mapping (Dhamecha typical)
    vat_rates = {**{"A": 20.0, "B": 5.0, "Z": 0.0}, **vat_rates}

    item_map = _dhamecha_build_item_map(doc_text_hint) or {}

    # If header totals strongly imply a single VAT rate (e.g. VAT  20% of Net),
    # we can safely correct mis-read vatCode/vatRate on lines that came through as Z/UNK.
    enforce_header_vat = False
    dominant_code = None
    try:
        h_net = _safe_float((header or {}).get("totalNet"))
        h_vat = _safe_float((header or {}).get("totalVat"))
        if h_net > 0:
            hdr_rate = (h_vat / h_net) * 100.0
            snap = _nearest_uk_vat_rate(hdr_rate)
            if abs(hdr_rate - snap) <= 0.35:
                enforce_header_vat = True
                dominant_code = "A" if snap == 20.0 else ("B" if snap == 5.0 else "Z")
    except Exception:
        enforce_header_vat = False
        dominant_code = None

    for it in items:
        if not isinstance(it, dict):
            continue

        code = str(it.get("code") or "").strip()
        is_promo = _is_promo_line_item(it)
        if is_promo:
            it["casePack"] = 0
            it["unitSize"] = 0
            it["qty"] = 0.0
            it["totalUnits"] = 0.0
            it["unitPrice"] = 0.0
            it["stdRrp"] = 0.0
            it["por"] = 0.0
            if not str(it.get("rowTag") or "").strip():
                it["rowTag"] = "PROMO"

        # 1) VAT Code: from item field, or from vatRate when it contains a code, or from OCR item_map
        vc = str(it.get("vatCode") or "").strip().upper()
        vr_raw = it.get("vatRate")

        if not vc:
            if isinstance(vr_raw, str) and re.fullmatch(r"[ABZ]", vr_raw.strip().upper()):
                vc = vr_raw.strip().upper()
            elif code and code in item_map and item_map[code].get("vatCode"):
                vc = str(item_map[code]["vatCode"] or "").strip().upper()

        # If we have an item_map VAT code from the invoice text, prefer it over Cloud guesses
        if code and code in item_map and item_map[code].get("vatCode"):
            map_vc = str(item_map[code].get("vatCode") or "").strip().upper()
            if map_vc in ("A", "B", "Z") and map_vc != vc:
                vc = map_vc

        if vc:
            it["vatCode"] = vc

        # 2) casePack fallback
        if (not is_promo) and (not it.get("casePack") or _safe_float(it.get("casePack")) == 0) and code and code in item_map:
            cp = item_map[code].get("casePack")
            if cp:
                it["casePack"] = cp

        # 2b) Fill missing compact-row values from the Dhamecha text-layer map.
        if (not is_promo) and code and code in item_map:
            src = item_map.get(code) or {}
            if _safe_float(it.get("qty")) == 0 and _safe_float(src.get("qty")) > 0:
                it["qty"] = _safe_float(src.get("qty"))
            if _safe_float(it.get("unitPrice")) == 0 and _safe_float(src.get("unitPrice")) > 0:
                it["unitPrice"] = _safe_float(src.get("unitPrice"))
            if _safe_float(it.get("lineNet")) == 0 and _safe_float(src.get("lineNet")) > 0:
                it["lineNet"] = _safe_float(src.get("lineNet"))
            if _safe_float(it.get("stdRrp")) == 0 and _safe_float(src.get("stdRrp")) > 0:
                it["stdRrp"] = _safe_float(src.get("stdRrp"))
            if _safe_float(it.get("por")) == 0 and _safe_float(src.get("por")) > 0:
                it["por"] = _safe_float(src.get("por"))
            if (not str(it.get("unitSize") or "").strip()) and str(src.get("unitSize") or "").strip():
                it["unitSize"] = str(src.get("unitSize") or "").strip()
            if (not str(it.get("description") or "").strip()) and str(src.get("description") or "").strip():
                it["description"] = str(src.get("description") or "").strip()

        # 3) VAT Rate: normalise numeric; if non-numeric/blank/zero but vatCode exists, use mapping
        vr_norm = _normalise_vat_rate(vr_raw)
        if (vr_norm == 0.0) and vc:
            vr_norm = float(vat_rates.get(vc, 0.0))

        
        # Dhamecha hard-rule:
        # If vatCode exists, vatRate MUST match the supplier's code->rate mapping.
        # This prevents a common local-OCR/AI issue where VAT *amount* (e.g. 7.10, 10.80)
        # is mistakenly placed into the vatRate column.
        if vc and vc in vat_rates:
            expected = float(vat_rates.get(vc, 0.0))
            # If rate is clearly not the expected band, snap to expected (tolerance 0.35%)
            if expected >= 0 and abs(vr_norm - expected) > 0.35:
                vr_norm = expected
        else:
            # If we still don't have a code, but rate looks non-UK, snap to nearest UK VAT band.
            # (Dhamecha invoices in our scope use 0/5/20)
            if vr_norm not in (0.0, 5.0, 20.0) and abs(vr_norm - 0.0) > 0.35 and abs(vr_norm - 5.0) > 0.35 and abs(vr_norm - 20.0) > 0.35:
                vr_norm = _nearest_uk_vat_rate(vr_norm)
# If vatCode missing but vatRate is clear, infer vatCode
        if (not vc) and (abs(vr_norm - 20.0) < 0.01):
            it["vatCode"] = "A"
            vc = "A"
        elif (not vc) and (abs(vr_norm - 5.0) < 0.01):
            it["vatCode"] = "B"
            vc = "B"
        elif (not vc) and (abs(vr_norm - 0.0) < 0.01):
            it["vatCode"] = "Z"
            vc = "Z"

        # Header-driven correction (Dhamecha): if the header implies a single VAT band,
        # upgrade mis-read Z/UNK lines to that band so VAT calculates and reconciliation matches.
        try:
            if enforce_header_vat and dominant_code and ((not vc) or vc in ("UNK", "Z")):
                ln = _safe_float(it.get("lineNet"))
                va = _safe_float(it.get("vatAmount"))
                if dominant_code != "Z" and ln > 0 and abs(va) < 0.01:
                    vc = dominant_code
                    it["vatCode"] = vc
                    vr_norm = float(vat_rates.get(vc, vr_norm))
        except Exception:
            pass

        it["vatRate"] = vr_norm

        # 4) VAT Amount and Gross: enforce consistency when rate > 0
        try:
            line_net = _safe_float(it.get("lineNet"))
            vat_amt = _safe_float(it.get("vatAmount"))
            if line_net > 0 and vr_norm > 0:
                calc_vat = round(line_net * (vr_norm / 100.0), 2)
                # Overwrite if missing/zero OR clearly inconsistent (tolerance 5p)
                if (it.get("vatAmount") is None) or (abs(vat_amt - calc_vat) > 0.05):
                    it["vatAmount"] = calc_vat
                # Ensure gross
                it["lineGross"] = round(line_net + _safe_float(it.get("vatAmount")), 2)
            else:
                # Zero-rated: keep VAT at 0
                if it.get("vatAmount") in (None, "", "0", 0, 0.0):
                    it["vatAmount"] = 0.0
                # Ensure gross at least equals net
                if _safe_float(it.get("lineGross")) == 0 and line_net != 0:
                    it["lineGross"] = round(line_net + _safe_float(it.get("vatAmount")), 2)
        except Exception:
            pass

    # Recalculate derived fields (totalUnits, unitCost, por, etc.)
    items[:] = _recalc_items(items)

    # Final pass: if vatCode still missing but rate is known, infer A/B/Z
    for it in items:
        try:
            vc = str(it.get("vatCode") or "").strip().upper()
            vr = _normalise_vat_rate(it.get("vatRate"))
            if not vc:
                if abs(vr - 20.0) < 0.01:
                    it["vatCode"] = "A"
                elif abs(vr - 5.0) < 0.01:
                    it["vatCode"] = "B"
                elif abs(vr - 0.0) < 0.01:
                    it["vatCode"] = "Z"
        except Exception:
            continue

    items[:] = _recalc_items(items)

    # Supplier name normalisation + totals safety
    if header is not None:
        header.setdefault("supplierName", "Dhamecha Cash & Carry Ltd")
        try:
            if _safe_float(header.get("totalNet")) <= 0:
                header["totalNet"] = round(sum(_safe_float(it.get("lineNet")) for it in items), 2)
            if _safe_float(header.get("totalVat")) <= 0:
                header["totalVat"] = round(sum(_safe_float(it.get("vatAmount")) for it in items), 2)
            if _safe_float(header.get("totalGross")) <= 0:
                header["totalGross"] = round(_safe_float(header.get("totalNet")) + _safe_float(header.get("totalVat")), 2)
        except Exception:
            pass

def _vat_breakdown_from_items(items: List[Dict[str, Any]], supplier_hint: str, header_vat: float = 0.0) -> Dict[str, Any]:
    # Compute VAT breakdown rows (vatCode, goodsAmount, vatAmount) from line items.
    # VAT method is chosen to best match header_vat where available.
    if not items:
        return {"rows": [], "totalNet": 0.0, "totalVat": 0.0, "totalGross": 0.0}

    by_code_net: Dict[str, float] = {}
    by_code_vat_sum: Dict[str, float] = {}
    by_code_rate: Dict[str, float] = {}

    for it in items:
        if not isinstance(it, dict):
            continue
        vc = str(it.get("vatCode") or "").strip().upper() or "NA"
        net = _safe_float(it.get("lineNet"))
        vat_line = _safe_float(it.get("vatAmount"))
        by_code_net[vc] = by_code_net.get(vc, 0.0) + net
        by_code_vat_sum[vc] = by_code_vat_sum.get(vc, 0.0) + vat_line
        r = _infer_vat_rate(it, supplier_hint)
        if vc not in by_code_rate or _safe_float(by_code_rate.get(vc)) == 0.0:
            by_code_rate[vc] = r
        else:
            by_code_rate[vc] = max(_safe_float(by_code_rate.get(vc)), r)

    total_vat_sum = round(sum(by_code_vat_sum.values()), 2)
    total_vat_calc = 0.0
    vat_calc_by_code: Dict[str, float] = {}
    for vc, net in by_code_net.items():
        r = _safe_float(by_code_rate.get(vc))
        vat_c = round(net * r / 100.0, 2)
        vat_calc_by_code[vc] = vat_c
        total_vat_calc += vat_c
    total_vat_calc = round(total_vat_calc, 2)

    # Choose best method (calc vs sum)
    hv = round(_safe_float(header_vat), 2)
    if hv > 0:
        use_calc = abs(hv - total_vat_calc) <= abs(hv - total_vat_sum)
    else:
        use_calc = (total_vat_sum == 0.0)

    rows: List[Dict[str, Any]] = []
    total_net = 0.0
    total_vat = 0.0
    for vc, net in sorted(by_code_net.items(), key=lambda kv: kv[0]):
        net = round(net, 2)
        vat_amt = round(vat_calc_by_code.get(vc, 0.0), 2) if use_calc else round(by_code_vat_sum.get(vc, 0.0), 2)
        total_net += net
        total_vat += vat_amt
        rows.append({"vatCode": vc, "goodsAmount": net, "vatAmount": vat_amt, "_source": "calculated"})

    total_net = round(total_net, 2)
    total_vat = round(total_vat, 2)
    total_gross = round(total_net + total_vat, 2)
    return {"rows": rows, "totalNet": total_net, "totalVat": total_vat, "totalGross": total_gross}


def _ensure_vat_breakdown(header: Dict[str, Any], items: List[Dict[str, Any]], supplier_hint: str) -> None:
    # Ensure header.vatBreakdown exists for consistent Dashboard UI across suppliers.
    try:
        rows = header.get("vatBreakdown")
        if isinstance(rows, list) and rows:
            for r in rows:
                if isinstance(r, dict) and "_source" not in r:
                    r["_source"] = "invoice"
            header["vatBreakdown"] = rows
            return
        if items:
            calc = _vat_breakdown_from_items(items, supplier_hint, header_vat=_safe_float(header.get("totalVat")))
            rows2 = calc.get("rows") or []
            if rows2:
                header["vatBreakdown"] = rows2
    except Exception:
        return



def _extract_parfetts_vat_breakdown(text: str) -> Tuple[float, float, List[Dict[str, Any]]]:
    """
    Extract Parfetts VAT summary box (A/Z) as rows:
      [{"vatCode":"A","goodsAmount":2666.88,"vatAmount":533.38}, ...]
    Returns (net_total, vat_total, rows).

    Robust to PDF text-layer quirks where columns may be split across lines or include pipe characters.
    """
    money_pat = r"[-]X\d{1,3}(?:,\d{3})*(?:\.\d{2})"
    rows: List[Dict[str, Any]] = []
    try:
        block = (text or "")
        block_norm = block.replace("|", " ")
        lines = [ln.strip() for ln in block_norm.splitlines() if ln.strip()]

        # locate VAT summary header region
        start_idx = None
        for i, ln in enumerate(lines):
            u = ln.upper()
            if "VAT CODE" in u:
                start_idx = i
                break
            if u.replace(" ", "") in {"VATCODE", "VATCODEGOODSAMOUNTVATAMOUNT"}:
                start_idx = i
                break
        if start_idx is None:
            return (0.0, 0.0, [])

        window = lines[start_idx : min(len(lines), start_idx + 140)]
        window_text = "\n".join(window)

        # Amounts may appear on same line or split across newline(s)
        pat = re.compile(rf"\b([AZ])\b\s+({money_pat})\s*(?:\n\s*|\s+)({money_pat})", flags=re.I)
        for m in pat.finditer(window_text):
            vc = (m.group(1) or "").strip().upper()
            goods = _safe_float(m.group(2))
            vat = _safe_float(m.group(3))
            if vc in {"A", "Z"}:
                rows.append({"vatCode": vc, "goodsAmount": float(goods), "vatAmount": float(vat)})

        # de-dupe by vatCode (keep first)
        seen = set()
        dedup: List[Dict[str, Any]] = []
        for r in rows:
            vc = (r.get("vatCode") or "").strip().upper()
            if not vc or vc in seen:
                continue
            seen.add(vc)
            dedup.append(r)

        net_total = round(sum(_safe_float(r.get("goodsAmount")) for r in dedup), 2)
        vat_total = round(sum(_safe_float(r.get("vatAmount")) for r in dedup), 2)
        return (net_total, vat_total, dedup)
    except Exception:
        return (0.0, 0.0, [])





def _title_case(s: str) -> str:
    """Lightweight title-casing for names (keeps short acronyms upper-case)."""
    s = (s or "").strip()
    if not s:
        return ""
    words = re.split(r"\s+", s)
    out = []
    for w in words:
        w = w.strip()
        if not w:
            continue
        # Keep acronyms/codes such as UK, VAT, LTD
        if w.isupper() and len(w) <= 4:
            out.append(w)
        else:
            out.append(w[:1].upper() + w[1:].lower() if w.isalpha() else w.title())
    return " ".join(out)

def _parfetts_extract_header(txt: str) -> Dict[str, Any]:
    """
    Parfetts (Aintree) invoice header + totals extraction.

    Totals priority:
      - Prefer VAT summary box (Vat Code table) when available (most reliable)
      - Else use footer totals (supports layouts where labels are stacked then values are stacked)
      - Gross validated against net+vat+delivery to prevent drift (e.g., 533.60 vs 533.38)
    """
    header: Dict[str, Any] = {
        "supplierName": "Parfetts",
        "customerName": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
        "deliveryCharge": 0.0,
        "vatBreakdown": [],
    }

    try:
        t = (txt or "")
        up = t.upper()

        # Invoice number
        m = re.search(r"INVOICE\s*NO\s*[:\s]*([0-9]{6,})", up)
        if m:
            header["invoiceNumber"] = m.group(1).strip()


        # Customer name (Parfetts uses (CR) <NAME> ...; be tolerant to multiple bracketed tags like (DEL)(P))
        customer = ""
        m = re.search(r"(?m)^\s*\(CR\)\s*([^\n\r]{3,120})\s*$", t, flags=re.I)
        if not m:
            m = re.search(r"(?m)^\s*CR\)\s*([^\n\r]{3,120})\s*$", t, flags=re.I)
        if not m:
            m = re.search(r"(?m)^\s*\(CR\s*([^\n\r]{3,120})\s*$", t, flags=re.I)
        if not m:
            m = re.search(r"(?m)^\s*\[CR\]\s*([^\n\r]{3,120})\s*$", t, flags=re.I)
        if m:
            # take the first line after (CR), remove common tags
            customer = m.group(1).strip()
            customer = re.sub(r"\(\s*(?:DEL|P)\s*\)", "", customer, flags=re.I)
            customer = re.sub(r"\s{2,}", " ", customer).strip(" -:|")
        if not customer:
            m = re.search(r"\(CR\)\s*([A-Z0-9&' \-\.]+?)(?:\((?:DEL|P)\)\s*){0,3}(?:\s+\d+\s+[A-Z]|\s+ORDER\s+NO|\s+INVOICE\s+NO|\n)", up)
            if m:
                customer = m.group(1).strip()
        if not customer:
            m = re.search(r"\(CR\)\s*(.{3,120}?)(?:\(\s*DEL\s*\)|\(\s*P\s*\)|TEL\s*:|UNITSIZE|DATE\s+OF\s+ORDER)", up, flags=re.I)
            if m:
                customer = re.sub(r"\(\s*(?:DEL|P)\s*\)", "", m.group(1), flags=re.I).strip(" -:|")
        if customer:
            header["customerName"] = _title_case(customer)

        # Invoice date
        # Prefer explicit "Date of Invoice:" (most reliable), else fallback to the first dd/mm/yyyy time near header, else Date Printed.
        date_str = ""
        m = re.search(r"DATE\s+OF\s+INVOICE[:\s]*([0-9]{2}/[0-9]{2}/[0-9]{4})", up)
        if not m:
            m = re.search(r"DATE\s+OF\s+INVO[1I]CE[:\s]*([0-9]{2}/[0-9]{2}/[0-9]{4})", up)
        if m:
            date_str = m.group(1)
        if not date_str:
            m = re.search(r"\b([0-9]{2}/[0-9]{2}/[0-9]{4})\s+[0-9]{2}:[0-9]{2}:[0-9]{2}\b", t)
            if m:
                date_str = m.group(1)
        if not date_str:
            m = re.search(r"DATE\s+PRINTED[:\s]*([0-9]{2}/[0-9]{2}/[0-9]{4})", up)
            if m:
                date_str = m.group(1)
        if date_str:
            header["invoiceDate"] = _ddmmyyyy_to_iso(date_str)

        money = r"[-]X\d{1,3}(?:,\d{3})*(?:\.\d{2})"

        def _money_after(label_re: str) -> float:
            m2 = re.search(rf"{label_re}(?:\s*[:]X\s*)(?:\n\s*|\s+)*({money})", t, flags=re.I)
            if not m2:
                return 0.0
            return _safe_float(m2.group(1))

        # Basic footer reads (works when value appears after label)
        net_f = _money_after(r"TOTAL\s+GOODS")
        vat_f = _money_after(r"TOTAL\s+VAT")
        gross_f = _money_after(r"TOTAL\s+INVOICE")
        deliv_f = _money_after(r"DELIVERY\s+CHARGE")

        # Handle stacked-label layout: labels first, values afterwards
        if (net_f <= 0 or vat_f <= 0 or gross_f <= 0) and ("TOTAL GOODS" in up and "TOTAL VAT" in up and "TOTAL INVOICE" in up):
            mblk = re.search(r"TOTAL\s+GOODS.*?TOTAL\s+VAT.*?TOTAL\s+INVOICE", up, flags=re.S)
            if mblk:
                tail = t[mblk.end(): mblk.end() + 600]
                nums = [ _safe_float(x) for x in re.findall(money, tail) ]
                # Typical sequence: net, vat, (delivery), gross
                if len(nums) >= 2 and net_f <= 0:
                    net_f = nums[0]
                if len(nums) >= 2 and vat_f <= 0:
                    vat_f = nums[1]
                # delivery might be present as 3rd number if delivery charge line exists
                if "DELIVERY CHARGE" in tail.upper() and len(nums) >= 4:
                    if deliv_f <= 0:
                        deliv_f = nums[2]
                    if gross_f <= 0:
                        gross_f = nums[3]
                else:
                    if gross_f <= 0 and len(nums) >= 3:
                        gross_f = nums[2]

        # VAT summary breakdown (A/Z)  most reliable totals source
        net_v, vat_v, rows_v = _extract_parfetts_vat_breakdown(t)
        if rows_v:
            try:
                for r in rows_v:
                    if isinstance(r, dict) and "_source" not in r:
                        r["_source"] = "invoice"
            except Exception:
                pass
            header["vatBreakdown"] = rows_v

        # Choose totals: prefer VAT breakdown when present
        if rows_v and net_v > 0:
            net = float(net_v)
            vat = float(vat_v)
        else:
            net = float(net_f or 0.0)
            vat = float(vat_f or 0.0)

        delivery = float(deliv_f or 0.0)
        header["deliveryCharge"] = float(round(delivery, 2))

        gross_calc = float(round(net + vat + delivery, 2))
        gross = float(gross_f or 0.0)

        # If footer gross missing or inconsistent, use calculated gross
        if gross <= 0 or abs(gross - gross_calc) > 0.05:
            gross = gross_calc

        header["totalNet"] = float(round(net, 2))
        header["totalVat"] = float(round(vat, 2))
        header["totalGross"] = float(round(gross, 2))

    except Exception:
        pass

    return header





def _parfetts_calc_por(std_rrp: float, vat_rate: float, unit_price_case: float, case_pack: int) -> float:
    try:
        if std_rrp <= 0 or unit_price_case <= 0 or case_pack <= 0:
            return 0.0
        sell_ex_vat = float(std_rrp)
        if vat_rate and vat_rate > 0:
            sell_ex_vat = sell_ex_vat / (1.0 + (float(vat_rate) / 100.0))
        cost_unit = float(unit_price_case) / float(case_pack)
        if sell_ex_vat <= 0:
            return 0.0
        por = ((sell_ex_vat - cost_unit) / sell_ex_vat) * 100.0
        return round(float(por), 2)
    except Exception:
        return 0.0



def _parfetts_unit_size_before(lines: List[str], idx: int, lookback: int = 6) -> str:
    """
    Best-effort unit-size extraction for Parfetts invoices.

    Parfetts PDFs often place a unit-size token (e.g., 440ML, 75CL, 130G, 8PK) a few lines
    *before* the item code. This helper scans upwards a small window to capture it.

    Returns an uppercase token with spaces removed (e.g., "75CL"). If not found, returns "".
    """
    import re
    for k in range(1, lookback + 1):
        j = idx - k
        if j < 0:
            break
        s = (lines[j] or "").strip()
        if not s:
            continue

        # Common liquid/weight sizes: 440ML, 75CL, 1L, 130G, 2KG, 12OZ
        m = re.search(r"\b(\d+(?:\.\d+)?)(?:\s*)(ML|CL|L|G|KG|OZ)\b", s, flags=re.IGNORECASE)
        if m:
            return f"{m.group(1)}{m.group(2).upper()}".replace(" ", "")

        # Packs: 4PK, 8PK, 6PACK
        m = re.search(r"\b(\d+)\s*(PK|PACK)\b", s, flags=re.IGNORECASE)
        if m:
            return f"{m.group(1)}PK"

        # Occasionally appears like "5'S" for gum; keep as-is normalised
        m = re.search(r"\b(\d+)\s*'S\b", s, flags=re.IGNORECASE)
        if m:
            return f"{m.group(1)}S"

    return ""


def _parfetts_clean_compact_description(desc: str, std_rrp: float) -> str:
    d = re.sub(r"\s+", " ", re.sub(r"[^\x20-\x7E]+", "", desc or "")).strip(" -:|")
    d = re.sub(r"^(?:\d{1,2})?[A-Za-z &/]+-\s*", "", d).strip()
    if std_rrp > 0:
        d = re.sub(rf"\b{re.escape(f'{std_rrp:.2f}')}\b\s*$", "", d).strip()
    return d


def _parfetts_clean_department(value: str) -> str:
    dept = re.sub(r"\s+", " ", str(value or "").replace("\xa0", " ")).strip(" -:|")
    dept = re.sub(r"[^A-Za-z0-9 &/]+", "", dept).strip()
    return dept.upper()


def _parfetts_department_heading(line: str) -> str:
    s = re.sub(r"\s+", " ", str(line or "").replace("\xa0", " ")).strip()
    m = re.match(r"^\s*\d{1,4}\s*[-–]\s*(?P<dept>[A-Z][A-Z0-9 &/]{2,})\s*$", s, flags=re.I)
    if not m:
        return ""
    dept = _parfetts_clean_department(m.group("dept"))
    if not dept:
        return ""
    reject = ("ORDER", "INVOICE", "CUSTOMER", "ACCOUNT", "TOTAL", "SUBTOTAL", "PAGE", "VAT")
    if any(tok in dept for tok in reject):
        return ""
    return dept


def _parfetts_attach_departments_from_text(items: List[Dict[str, Any]], txt: str) -> List[Dict[str, Any]]:
    """Attach Parfetts section headings (e.g. HEALTH & BEAUTY) to following item rows."""
    if not items or not txt:
        return items

    code_depts: Dict[str, List[str]] = {}
    ordered_depts: List[str] = []
    current_dept = ""

    for raw in (txt or "").splitlines():
        ln = re.sub(r"\s+", " ", str(raw or "").replace("\xa0", " ")).strip()
        if not ln:
            continue
        dept = _parfetts_department_heading(ln)
        if dept:
            current_dept = dept
            continue
        if not current_dept:
            continue
        up = ln.upper()
        if any(tok in up for tok in ("SUBTOTAL", "TOTAL GOODS", "TOTAL VAT", "TOTAL INVOICE")):
            continue
        if not re.search(r"[A-Z]", ln):
            continue
        m = re.search(r"\b(?P<code>\d{4,7})\b", ln)
        if not m:
            continue
        code = m.group("code")
        code_depts.setdefault(code, []).append(current_dept)
        ordered_depts.append(current_dept)

    if not ordered_depts:
        return items

    fallback_idx = 0
    for it in items:
        if not isinstance(it, dict) or it.get("department"):
            continue
        code = re.sub(r"\D+", "", str(it.get("code") or ""))
        dept = ""
        if code and code_depts.get(code):
            dept = code_depts[code].pop(0)
        elif fallback_idx < len(ordered_depts):
            dept = ordered_depts[fallback_idx]
            fallback_idx += 1
        if dept:
            it["department"] = dept
    return items


def _parse_parfetts_compact_text(txt: str) -> List[Dict[str, Any]]:
    """Parse Parfetts PDF text layers where item rows are joined into long strings.

    Also supports column-preserving text extracted by pdftotext/pdfplumber where each
    item is already on one line with separate qty/size/price columns.
    """
    if not txt:
        return []

    def _parse_columnar_lines(src: str) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        line_no = 1
        row_pat = re.compile(
            r"^\s*(?P<code>\d{4,7})\s+"
            r"(?P<desc>.+?)\s+"
            r"(?P<qty>\d+\.\d{2})\s+"
            # UNIT SIZE can be blank on some Parfetts rows. Make it optional and
            # stop before the sale-unit marker (e.g. '24 x 1', '1 x 8').
            r"(?:(?P<unit>.*?)\s+)?"
            r"(?P<sale_a>\d{1,3})\s*x\s*(?P<sale_b>\d{1,3})\s+"
            r"(?P<qty_ord>\d{1,4})\s+"
            r"(?P<qty_del>\d{1,4})\s+"
            r"(?P<unit_price>\d{1,4}(?:,\d{3})*\.\d{2})\s*(?P<flag>[dDP])?\s+"
            r"(?P<line_net>\d{1,5}(?:,\d{3})*\.\d{2})\s+"
            r"(?P<std_rrp>\d{1,4}\.\d{2})\s+"
            r"(?P<gm>\d{1,3}\.\d{2})\s+"
            r"(?P<vat>[A-Z])\s*$",
            flags=re.I,
        )
        bad_desc_tokens = ("SUBTOTAL", "TOTAL GOODS", "TOTAL VAT", "TOTAL INVOICE", "NOT AVAILABLE")

        for raw in (src or "").splitlines():
            ln = re.sub(r"\s+", " ", str(raw or "").replace("\xa0", " ")).strip()
            if not ln or ln.startswith("="):
                continue
            m = row_pat.match(ln)
            if not m:
                continue
            desc = (m.group("desc") or "").strip()
            if any(tok in desc.upper() for tok in bad_desc_tokens):
                continue

            vat_code = (m.group("vat") or "").strip().upper()
            sale_a = int(m.group("sale_a") or 0)
            sale_b = int(m.group("sale_b") or 0)
            case_pack = sale_a * sale_b
            qty = _safe_float(m.group("qty"))
            unit_price = _safe_float(m.group("unit_price"))
            line_net = _safe_float(m.group("line_net"))
            std_rrp = _safe_float(m.group("std_rrp"))
            vat_rate = float(PARFETTS_VAT_MAP_DEFAULT.get(vat_code, 0.0))
            vat_amount = round(line_net * vat_rate / 100.0, 2) if vat_rate else 0.0
            unit_size = re.sub(r"\s+", "", (m.group("unit") or "")).upper().replace("LT", "LTR")

            out.append({
                "lineNo": line_no,
                "code": (m.group("code") or "").strip(),
                "description": _parfetts_clean_compact_description(desc, std_rrp),
                "casePack": int(case_pack or 0),
                "unitSize": unit_size,
                "qty": float(qty),
                "totalUnits": float(qty * float(case_pack or 0)),
                "unitPrice": float(unit_price),
                "lineNet": float(line_net),
                "vatCode": vat_code,
                "vatRate": float(vat_rate),
                "vatAmount": float(vat_amount),
                "lineGross": float(round(line_net + vat_amount, 2)),
                "stdRrp": float(std_rrp),
                "por": float(_parfetts_calc_por(std_rrp, vat_rate, unit_price, case_pack)),
                "isVoid": False,
            })
            line_no += 1
        return out

    columnar_items = _parfetts_attach_departments_from_text(_parse_columnar_lines(txt), txt)
    if columnar_items:
        return columnar_items

    text = re.sub(r"\s+", " ", txt.replace("\xa0", " ")).strip()
    stop = text.upper().find("TOTAL GOODS")
    if stop > 0:
        text = text[:stop]

    row_pat = re.compile(
        r"(?P<unit>(?:\d+(?:\.\d+)?\s*(?:ML|LTR|LT|CL|G|GM|KG|S|PC|PCS|PK)|\d+'S|CHARGE)\s+)?"
        r"(?P<code>\d{4,7})"
        r"(?P<desc>.{2,120}?)"
        r"(?P<sale_a>\d{1,3})\s*x\s*(?P<sale_b>\d{1,3})\s+"
        r"(?P<qty>\d{1,4})\s+"
        r"(?P<unit_price>\d{1,4}(?:,\d{3})*\.\d{2})(?:\s*[dD])?\s*"
        r"(?P<vat>P?[AZRBX])\s+"
        r"(?P<line_net>\d{1,5}(?:,\d{3})*\.\d{2})\s+"
        r"(?P<qty_ord>\d{1,4})\s+"
        r"(?P<qty_ord_dec>\d{1,4}\.\d{2})\s+"
        r"(?P<std_rrp>\d{1,4}\.\d{2})\s+"
        r"(?P<gm>\d{1,3}\.\d{2})",
        flags=re.I,
    )

    def _valid_match(m: re.Match) -> bool:
        if m.start() > 0 and (text[m.start() - 1].isdigit() or text[m.start() - 1] in ".,"):
            return False
        desc = (m.group("desc") or "").strip()
        up = desc.upper()
        bad_tokens = ("ORDER NO", "DATE OF INVOICE", "CUSTOMER ACCOUNT", "VAT NO", "PAGE ", "SUBTOTAL", "TOTAL GOODS")
        if any(tok in up for tok in bad_tokens):
            return False
        if re.search(r"\b\d{4,7}[A-Z]", desc) or re.search(r"\b\d{4,7}\s+[A-Z]", desc):
            return False
        return True

    items: List[Dict[str, Any]] = []
    pos = 0
    line_no = 1
    while True:
        m = row_pat.search(text, pos)
        if not m:
            break
        if not _valid_match(m):
            pos = m.start() + 1
            continue

        vat_code = (m.group("vat") or "").strip().upper()
        if vat_code.startswith("P") and len(vat_code) == 2:
            vat_code = vat_code[1:]
        sale_a = int(m.group("sale_a") or 0)
        sale_b = int(m.group("sale_b") or 0)
        case_pack = sale_a * sale_b
        qty = _safe_float(m.group("qty"))
        unit_price = _safe_float(m.group("unit_price"))
        line_net = _safe_float(m.group("line_net"))
        std_rrp = _safe_float(m.group("std_rrp"))
        vat_rate = float(PARFETTS_VAT_MAP_DEFAULT.get(vat_code, 0.0))
        vat_amount = round(line_net * vat_rate / 100.0, 2) if vat_rate else 0.0
        unit_size = re.sub(r"\s+", "", (m.group("unit") or "")).upper().replace("LT", "LTR")

        items.append({
            "lineNo": line_no,
            "code": (m.group("code") or "").strip(),
            "description": _parfetts_clean_compact_description(m.group("desc") or "", std_rrp),
            "casePack": int(case_pack or 0),
            "unitSize": unit_size,
            "qty": float(qty),
            "totalUnits": float(qty * float(case_pack or 0)),
            "unitPrice": float(unit_price),
            "lineNet": float(line_net),
            "vatCode": vat_code,
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amount),
            "lineGross": float(round(line_net + vat_amount, 2)),
            "stdRrp": float(std_rrp),
            "por": float(_parfetts_calc_por(std_rrp, vat_rate, unit_price, case_pack)),
            "isVoid": False,
        })
        line_no += 1
        pos = m.end()

    return _parfetts_attach_departments_from_text(items, txt)


def _parse_parfetts_purchase_invoice(txt: str) -> List[Dict[str, Any]]:
    """Deterministic parser for Parfetts purchase invoices.

    Notes:
    - Parfetts uses a 'Sale Unit' style of 'A' then 'x B' (e.g., '6' then 'x 1', or '1' then 'x 6').
      We treat casePack as A*B so totalUnits = qty * casePack reflects true units.
    - Some PDFs split qty and unit price across two lines (qty line then price line), sometimes with a trailing
      letter on the price line (e.g., '7.49 d'). We support both formats.
    """
    lines_raw = [(ln or "").strip() for ln in (txt or "").splitlines()]
    lines = [ln for ln in lines_raw if ln]
    items: List[Dict[str, Any]] = []

    vat_codes = set(["A", "Z", "R", "B", "X"])
    vat_map = PARFETTS_VAT_MAP_DEFAULT

    i = 0
    line_no = 1
    while i < len(lines):
        ln = lines[i]

        # Item code is typically a 4-7 digit line.
        if re.fullmatch(r"\d{4,7}", ln):
            code = ln

            # Unit size: generally appears within the few lines above the code (e.g., 440ML, 75CL, 130G, 8PK).
            unit_size = _parfetts_unit_size_before(lines, i)

            # Description: accumulate until the 'Sale Unit' marker (a number line followed by a line containing 'x').
            desc_parts: List[str] = []
            j = i + 1
            while j < len(lines):
                if re.fullmatch(r"\d{1,4}", lines[j]) and (j + 1) < len(lines) and "x" in lines[j + 1].lower():
                    break
                if re.fullmatch(r"\d{4,7}", lines[j]):
                    break
                if lines[j].lower().startswith("page ") and "of" in lines[j].lower():
                    break
                desc_parts.append(lines[j])
                j += 1

            description = " ".join(desc_parts).strip()

            # Must have sale unit marker
            if not (j < len(lines) and re.fullmatch(r"\d{1,4}", lines[j]) and (j + 1) < len(lines) and "x" in lines[j + 1].lower()):
                i += 1
                continue

            # Sale Unit / casePack: A then 'x B' -> casePack = A*B
            sale_a = int(lines[j])
            mxb = re.search(r"x\s*(\d+)", lines[j + 1], flags=re.I)
            sale_b = int(mxb.group(1)) if mxb else 1
            case_pack = sale_a * sale_b
            j += 2  # skip A and 'x B'

            # Look ahead window (up to 18 lines) for qty/unit price, VAT code, ext price, and RRP/GM.
            k = j
            window: List[str] = []
            while k < len(lines):
                if re.fullmatch(r"\d{4,7}", lines[k]) and window:
                    break
                if lines[k].lower().startswith("subtotal") and window:
                    break
                if lines[k].lower().startswith("page ") and "of" in lines[k].lower():
                    break
                if lines[k].lower().startswith("total ") and window:
                    break
                window.append(lines[k])
                if len(window) >= 18:
                    break
                k += 1

            qty = 0.0
            unit_price = 0.0
            vat_code = ""
            line_net = 0.0
            std_rrp = 0.0

            # Qty + unit price can be either:
            # 1) single line: "2 18.99" (sometimes with trailing letter)
            # 2) split lines: "2" then "18.99" or "18.99 d"
            for w in window:
                mqp = re.match(r"^(\d+)\s+([0-9][0-9,]*\.[0-9]{2})(?:\s*[A-Za-z])?$", w)
                if mqp:
                    qty = float(int(mqp.group(1)))
                    unit_price = _safe_float(mqp.group(2))
                    break

            if qty <= 0.0 and unit_price <= 0.0:
                for idx in range(len(window) - 1):
                    if re.fullmatch(r"\d+", window[idx]) and re.fullmatch(r"[0-9][0-9,]*\.[0-9]{2}(?:\s*[A-Za-z])?$", window[idx + 1]):
                        q = int(window[idx])
                        p = _safe_float(window[idx + 1])
                        if p > 0.0 and 0 <= q < 1000:
                            qty = float(q)
                            unit_price = p
                            break

            # VAT code letter (A/Z/R/B)
            for w in window:
                if re.fullmatch(r"[A-Za-z]", w):
                    wc = w.upper()
                    if wc in vat_codes:
                        vat_code = wc
                        break

            # Ext price / line net: first money value after VAT code (if found) else first money in window.
            start_idx = 0
            if vat_code and vat_code in window:
                start_idx = window.index(vat_code) + 1
            for w in window[start_idx:]:
                if re.fullmatch(r"[0-9][0-9,]*\.[0-9]{2}", w):
                    line_net = _safe_float(w)
                    break

            # RRP/GM line: take first number from last line that contains two money values.
            for w in reversed(window):
                mrrp = re.search(r"([0-9][0-9,]*\.[0-9]{2})\s+([0-9][0-9,]*\.[0-9]{2})", w)
                if mrrp:
                    std_rrp = _safe_float(mrrp.group(1))
                    break

            # If not delivered, zero amounts. (Invoice text says 'you haven't been charged'.)
            if qty <= 0.0:
                unit_price = 0.0
                line_net = 0.0
                if not vat_code:
                    vat_code = "Z"

            vat_rate = float(vat_map.get((vat_code or "").upper(), 0.0))
            vat_amount = round((line_net * vat_rate / 100.0), 2) if vat_rate > 0.0 else 0.0
            line_gross = round(line_net + vat_amount, 2)

            total_units = qty * float(case_pack or 0)

            # Remove trailing RRP token from description if present (e.g., "... 2.50")
            if std_rrp > 0.0 and description:
                parts = description.split()
                if parts and re.fullmatch(r"\d+\.\d{2}", parts[-1]) and abs(_safe_float(parts[-1]) - std_rrp) < 0.001:
                    description = " ".join(parts[:-1]).strip()

            por = _parfetts_calc_por(std_rrp, vat_rate, unit_price, case_pack)

            items.append({
                "lineNo": line_no,
                "code": code,
                "description": description,
                "casePack": int(case_pack or 0),
                "unitSize": unit_size,
                "qty": float(qty),
                "totalUnits": float(total_units),
                "unitPrice": float(unit_price),
                "lineNet": float(line_net),
                "vatCode": vat_code,
                "vatRate": float(vat_rate),
                "vatAmount": float(vat_amount),
                "lineGross": float(line_gross),
                "stdRrp": float(std_rrp),
                "por": float(por),
                "isVoid": False,
            })
            line_no += 1

            i = k
            continue

        i += 1

    items = _parfetts_attach_departments_from_text(items, txt)
    compact_items = _parse_parfetts_compact_text(txt)
    if len(compact_items) > len(items):
        return compact_items

    return items

def _dwg_extract_header(txt: str) -> Dict[str, Any]:
    """
    Drinks Wholesale Group (DWG) header extractor (best-effort from OCR/text).
    """
    t = txt or ""
    header: Dict[str, Any] = {
        "supplierName": "Drinks Wholesale Group Ltd",
        "customerName": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
    }

    # Invoice number
    m = re.search(r"\bInvoice\s*No\s*[:#]?\s*(INV[-\s]*\d{6,})\b", t, flags=re.IGNORECASE)
    if m:
        header["invoiceNumber"] = m.group(1).replace(" ", "").upper()
    else:
        m2 = re.search(r"\bINV[-\s]*\d{6,}\b", t, flags=re.IGNORECASE)
        if m2:
            header["invoiceNumber"] = m2.group(0).replace(" ", "").upper()

    # Date (e.g., 16-Nov-25)
    dm = re.search(r"\bDate\s*[:]?\s*(\d{1,2}-[A-Za-z]{3}-\d{2})\b", t)
    if dm:
        try:
            header["invoiceDate"] = dt.datetime.strptime(dm.group(1), "%d-%b-%y").strftime("%Y-%m-%d")
        except Exception:
            pass

    # Customer: prefer any line containing "FRESHERS" (your main use-case), else first line after "Invoice"
    for ln in t.splitlines():
        s = ln.strip()
        if not s:
            continue
        if "FRESHERS" in s.upper():
            header["customerName"] = s.replace("...", "").strip()
            break

    if not header["customerName"]:
        lines = [l.strip() for l in t.splitlines() if l.strip()]
        try:
            inv_idx = next(i for i,l in enumerate(lines) if l.upper().startswith("INVOICE"))
            for cand in lines[inv_idx+1:inv_idx+10]:
                if cand and not any(x in cand.upper() for x in ["VAT", "COMPANY", "AWRS", "INVOICE", "NO:", "DATE:"]):
                    header["customerName"] = cand
                    break
        except Exception:
            pass

    # Totals (Net/VAT/Gross)
    def _money_after(label_pat: str) -> float:
        try:
            mm = re.search(label_pat, t, flags=re.IGNORECASE)
            if not mm:
                return 0.0
            val = mm.group(1).replace(",", "").strip()
            return float(val)
        except Exception:
            return 0.0

    # Common DWG labels: Net Amount / VAT Amount / Gross Amount
    header["totalNet"] = _money_after(r"\bNet\s*Amount\b[^0-9\n\r]{0,10}X\s*([0-9,]+(?:\.[0-9]{2})X)")
    header["totalVat"] = _money_after(r"\bVAT\s*Amount\b[^0-9\n\r]{0,10}X\s*([0-9,]+(?:\.[0-9]{2})X)")
    header["totalGross"] = _money_after(r"\bGross\s*Amount\b[^0-9\n\r]{0,10}X\s*([0-9,]+(?:\.[0-9]{2})X)")

    # Alternative labels sometimes seen
    if header["totalNet"] <= 0:
        header["totalNet"] = _money_after(r"\bTotal\s*Net\b[^0-9\n\r]{0,10}X\s*([0-9,]+(?:\.[0-9]{2})X)")
    if header["totalVat"] <= 0:
        header["totalVat"] = _money_after(r"\bTotal\s*VAT\b[^0-9\n\r]{0,10}X\s*([0-9,]+(?:\.[0-9]{2})X)")
    if header["totalGross"] <= 0:
        header["totalGross"] = _money_after(r"\bInvoice\s*Total\b[^0-9\n\r]{0,10}X\s*([0-9,]+(?:\.[0-9]{2})X)")

    return header


def _parse_dwg_purchase_invoice(txt: str) -> List[Dict[str, Any]]:
    """
    DWG line parser (local/auto): best-effort extraction from OCR/PDF-text.

    Handles:
      - currency lines with or without ''
      - VAT codes like 'S/A' on the line
      - PM/PMP RRP tokens inside description (stored into stdRrp)
    """
    t = txt or ""
    items: List[Dict[str, Any]] = []

    def _extract_std_rrp_from_desc(desc: str) -> Tuple[float, str]:
        """Extract PM/PMP price from DWG description (supports pence like 'PM 70P')."""
        if not desc:
            return 0.0, ""
        d = str(desc)

        # Fast path: PMP/PM followed by 2-4 digits (e.g. PMP109 => 1.09, PM1299 => 12.99)
        mm = re.search(
            r"(?i)\b(PMP|PM)\s*[:\-]?\s*(?P<amt>[0-9]{2,4})(?:\s*[pP])?\b",
            d,
        )
        if not mm:
            mm = re.search(
                r"(?i)\b(?P<amt>[0-9]{2,4})(?:\s*[pP])?\s*(PMP|PM)\b",
                d,
            )
        if mm:
            raw_amt = (mm.group("amt") or "").strip()
            try:
                price = float(raw_amt) / 100.0
            except Exception:
                price = None
            if price is not None:
                d2 = (d[:mm.start()] + d[mm.end():]).strip()
                d2 = re.sub(r"\b(PMP?|PM)\b\s*$", "", d2, flags=re.IGNORECASE).strip()
                d2 = re.sub(r"\s{2,}", " ", d2)
                return float(round(price, 2)), d2

        mm = re.search(
            r"(?<![A-Z0-9])(?P<tok>PMPX|PM)\s*[:\-]X\s*(?:\(\s*)XX\s*(?P<amt>[0-9]+(?:\.[0-9]{1,2})X)(?P<pence>[pP])X(?:\s*\))X",
            d,
            flags=re.IGNORECASE,
        )
        if not mm:
            mm = re.search(
                r"X\s*(?P<amt>[0-9]+(?:\.[0-9]{1,2})X)(?P<pence>[pP])X\s*(?P<tok>PMPX|PM)\b",
                d,
                flags=re.IGNORECASE,
            )
        if not mm:
            return 0.0, d.strip()

        raw_amt = (mm.group("amt") or "").strip()
        pence_flag = (mm.group("pence") or "").strip()
        match_txt = mm.group(0) or ""

        try:
            price = float(raw_amt)
        except Exception:
            return 0.0, d.strip()

        has_decimal = "." in raw_amt
        has_pound = "" in match_txt
        if (pence_flag and not has_decimal) or (not has_decimal and not has_pound and 10 <= price <= 99):
            price = price / 100.0

        d2 = (d[:mm.start()] + d[mm.end():]).strip()
        d2 = re.sub(r"\s{2,}", " ", d2)
        return float(round(price, 2)), d2.strip()

    def _vat_code_from_line(s: str) -> str:
        if re.search(r"\bS\s*/\s*A\b", s, flags=re.IGNORECASE) or re.search(r"\bS/A\b", s, flags=re.IGNORECASE):
            return "S/A"
        if re.search(r"\bZ\b", s, flags=re.IGNORECASE):
            return "Z"
        if re.search(r"\bA\b", s, flags=re.IGNORECASE):
            return "A"
        # Default for DWG: standard (20%)
        return "S/A"

    for ln in t.splitlines():
        s = ln.strip()
        if not s:
            continue
        if re.search(r"\bTOTAL\b|\bINVOICE\s+TOTAL\b|\bPAGE\b|\bSUBTOTAL\b|\bDELIVERY\b", s, flags=re.IGNORECASE):
            continue

        # Extract money values: with  first, else trailing decimals
        prices: List[float] = []
        if "" in s:
            try:
                prices = [float(x.replace(",", "")) for x in re.findall(r"Â£\s*([0-9]+(?:\.[0-9]{2})?)", s)]
            except Exception:
                prices = []

        if not prices:
            decs = re.findall(r"([0-9]+(?:\.[0-9]{2}))\b", s)
            if len(decs) >= 2 and (
                re.match(r"^\s*\d{4,10}\b", s)
                or re.match(r"^\s*\d+\s+[A-Za-z0-9\-]{3,12}\b", s)
                or re.match(r"^\s*[A-Za-z0-9\-]{3,12}\b", s)
                or re.search(r"\bS/A\b|\bS\s*/\s*A\b|\bVAT\b", s, flags=re.IGNORECASE)
            ):
                try:
                    prices = [float(x.replace(",", "")) for x in decs[-3:]]
                except Exception:
                    prices = []

        if not prices:
            continue

        # Heuristic: last is line net; second last is unit price when present
        line_net = prices[-1]
        unit_price = prices[-2] if len(prices) >= 2 else prices[-1]

        # Qty: try to derive from net/unit price
        qty = 1.0
        if unit_price > 0:
            q = line_net / unit_price
            rq = round(q)
            if abs(q - rq) <= 0.05 and rq > 0:
                qty = float(rq)

        # Leading code / optional leading qty (DWG often uses short alphanumeric codes)
        code_val = ""
        m_code = re.match(r"^\s*(?:(\d+)\s+)?([A-Za-z0-9\-]{3,12})\b\s+(.*)$", s)
        rest = s
        if m_code:
            # If a leading number exists it may be the case quantity; keep derived qty unless missing.
            lead_qty = m_code.group(1)
            if (qty in (0, 0.0, None)) and lead_qty:
                try:
                    qty = float(lead_qty)
                except Exception:
                    pass
            code_val = m_code.group(2)
            rest = m_code.group(3)


        vat_code = _vat_code_from_line(s)
        vat_rate = 20.0 if vat_code.upper().replace(" ", "") in ("S/A", "SA", "S") else 0.0

        # Description cleanup
        desc = rest
        desc = re.sub(r"(Â£\s*[0-9]+(?:\.[0-9]{2})?\s*)+", "", desc).strip()
        desc = re.sub(r"\s+[0-9]+(?:\.[0-9]{2})\b(?:\s+[0-9]+(?:\.[0-9]{2})\b)*\s*$", "", desc).strip()
        desc = re.sub(r"\bS\s*/\s*A\b|\bS/A\b", "", desc, flags=re.IGNORECASE).strip(" -|")

        std_rrp, desc = _extract_std_rrp_from_desc(desc)

        vat_amount = round(line_net * (vat_rate / 100.0), 2)
        line_gross = round(line_net + vat_amount, 2)

        items.append({
            "lineNo": 0,
            "code": code_val,
            "description": desc,
            "casePack": "",
            "unitSize": "",
            "qty": qty,
            "totalUnits": "",
            "unitPrice": round(unit_price, 2),
            "lineNet": round(line_net, 2),
            "vatCode": vat_code,
            "vatRate": vat_rate,
            "vatAmount": vat_amount,
            "lineGross": line_gross,
            "stdRrp": float(std_rrp) if std_rrp else 0.0,
            "por": 0.0,
            "isVoid": False,
        })

    return items


def _fix_por_outliers(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Clamp/clear POR values that are clearly wrong (should be 0-100%)."""
    if not items:
        return items
    for it in items:
        try:
            por = _safe_float(it.get("por"), default=0.0)
            if por < 0 or por > 100:
                it["por"] = 0.0
        except Exception:
            continue
    return items

def _booker_items_look_corrupt(items: List[Dict[str, Any]]) -> bool:
    """Detect obviously corrupted Booker items (e.g., header codes in numeric fields)."""
    if not items:
        return False
    for it in items:
        try:
            code = str(it.get("code") or "").strip()
            case_pack = _safe_float(it.get("casePack"), 0.0)
            qty = _safe_float(it.get("qty"), 0.0)
            total_units = _safe_float(it.get("totalUnits"), 0.0)
            unit_price = _safe_float(it.get("unitPrice"), 0.0)
            line_net = _safe_float(it.get("lineNet"), 0.0)
            # absurd values indicate shifted columns / header bleed
            if (code and not re.fullmatch(r"\d{5,7}", code)) and (case_pack > 0 or unit_price > 0):
                return True
            if abs(case_pack) >= 500 or abs(qty) >= 500 or abs(total_units) >= 50000:
                return True
            if abs(unit_price) >= 500 or abs(line_net) >= 5000:
                return True
        except Exception:
            continue
    return False

def _booker_fix_free_lines(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Normalize FREE/FOC lines so qty/pack/price don't drift and totals reconcile."""
    if not items:
        return items

    def _unit_size_token(tok: str) -> bool:
        t = (tok or "").strip().upper()
        if re.fullmatch(r"\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S)", t):
            return True
        if re.fullmatch(r"\d+[X*]\d+(?:\.\d+)?(ML|L|LTR|LT|CL|G|KG|PK|S)", t):
            return True
        if re.fullmatch(r"\d+(?:\.\d+)?(ROLL|ROLLS)", t):
            return True
        if re.fullmatch(r"\d+PK", t):
            return True
        return False

    def _as_float(tok: str) -> Optional[float]:
        if tok is None:
            return None
        t = str(tok).strip().replace(",", "")
        if t.endswith("-") and len(t) > 1:
            t = "-" + t[:-1]
        if not re.fullmatch(r"-?\d+(?:\.\d+)?", t):
            return None
        try:
            return float(t)
        except Exception:
            return None

    # Build fallback map from non-free items (same code) to recover pack/size
    nonfree_by_code: Dict[str, Dict[str, Any]] = {}
    def _raw_has_free(desc: str, raw_txt: str, unit_price: object, line_net: object) -> bool:
        return _is_free_marker(desc=desc, raw_txt=raw_txt, unit_price=unit_price, line_net=line_net)

    for it in items:
        try:
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if not code:
                continue
            desc = str(it.get("description") or "")
            raw_txt = _norm_pack_tokens(str(it.get("rawRow") or it.get("raw") or ""))
            if _raw_has_free(desc, raw_txt, it.get("unitPrice"), it.get("lineNet")) or (
                bool(it.get("isFree")) and _safe_float(it.get("unitPrice"), 0.0) == 0.0 and _safe_float(it.get("lineNet"), 0.0) == 0.0
            ):
                continue
            if _safe_float(it.get("casePack"), 0.0) > 0 and str(it.get("unitSize") or "").strip():
                nonfree_by_code.setdefault(code, it)
        except Exception:
            continue

    for it in items:
        try:
            desc = str(it.get("description") or "")
            raw_txt = _norm_pack_tokens(str(it.get("rawRow") or it.get("raw") or ""))
            code_txt = str(it.get("code") or "").strip().upper()
            explicit_discount = (
                code_txt == "PROMO"
                and (
                    _safe_float(it.get("lineNet"), 0.0) < 0
                    or bool(re.search(r"\b\d+(?:\.\d{2})-(?=\s|$)|\b-\d+(?:\.\d{2})\b", f"{desc} {raw_txt}"))
                )
            )
            if explicit_discount:
                continue
            if not _raw_has_free(desc, raw_txt, it.get("unitPrice"), it.get("lineNet")) and not (
                bool(it.get("isFree")) and _safe_float(it.get("unitPrice"), 0.0) == 0.0 and _safe_float(it.get("lineNet"), 0.0) == 0.0
            ):
                continue

            # Try to recover pack/size/qty from raw row if present
            if raw_txt:
                toks = raw_txt.replace("Ã‚Â£", " ").split()
                code_idx = None
                for i, t in enumerate(toks):
                    if re.fullmatch(r"\d{5,7}", t):
                        code_idx = i
                        break
                # find pack size token pair
                case_pack = _safe_float(it.get("casePack"), 0.0)
                unit_size = str(it.get("unitSize") or "").strip()
                if code_idx is not None:
                    for j in range(code_idx + 1, len(toks) - 1):
                        # combined pack/size token like 6X1.5LT
                        pack_tok, size_tok = _split_pack_size_token(toks[j])
                        if pack_tok:
                            case_pack = float(pack_tok)
                            unit_size = size_tok
                            qty = None
                            for k in range(j + 1, len(toks)):
                                if toks[k].upper() in ("FREE", "FOC"):
                                    break
                                qv = _as_float(toks[k])
                                if qv is not None and 0 < qv <= 200:
                                    qty = float(qv)
                                    break
                            if qty is not None:
                                it["qty"] = float(qty)
                            it["casePack"] = float(case_pack or 0.0)
                            it["unitSize"] = unit_size
                            break
                        v = _as_float(toks[j])
                        if v is not None and abs(v - round(v)) < 1e-6 and _unit_size_token(toks[j + 1]):
                            case_pack = float(v)
                            unit_size = toks[j + 1]
                            # qty is next numeric after unit_size
                            qty = None
                            for k in range(j + 2, len(toks)):
                                if toks[k].upper() in ("FREE", "FOC"):
                                    break
                                qv = _as_float(toks[k])
                                if qv is not None and 0 < qv <= 200:
                                    qty = float(qv)
                                    break
                            if qty is not None:
                                it["qty"] = float(qty)
                            it["casePack"] = float(case_pack or 0.0)
                            it["unitSize"] = unit_size
                            break

            # Fallback: copy pack/size from a non-free row with same code
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if code and code in nonfree_by_code:
                src = nonfree_by_code[code]
                if not _safe_float(it.get("casePack"), 0.0):
                    it["casePack"] = _safe_float(src.get("casePack"), 0.0)
                if not str(it.get("unitSize") or "").strip():
                    it["unitSize"] = str(src.get("unitSize") or "").strip()

            # Normalize FREE economics
            it["unitPrice"] = 0.0
            it["lineNet"] = 0.0
            it["vatAmount"] = 0.0
            it["lineGross"] = 0.0
            if not str(it.get("vatCode") or "").strip():
                # try to pick VAT code from raw text
                if raw_txt:
                    for t in raw_txt.split():
                        vc = BookerCombinedRowParser._norm_vat_code(t)
                        if re.fullmatch(r"(A|B|C|Z|Z/A|R)", vc):
                            it["vatCode"] = vc
                            break
            vat_code = str(it.get("vatCode") or "B")
            it["vatRate"] = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0))
            if _is_promo_line_item(it):
                it["casePack"] = 0
                it["unitSize"] = 0
                it["qty"] = 0.0
                it["totalUnits"] = 0.0
                it["unitPrice"] = 0.0
                it["stdRrp"] = 0.0
                it["por"] = 0.0
                if not str(it.get("rowTag") or "").strip():
                    it["rowTag"] = "FREE"
                continue
            qv = _safe_float(it.get("qty"), 0.0)
            if not qv or qv > 10:
                it["qty"] = 1.0
            it["totalUnits"] = float(_safe_float(it.get("casePack"), 0.0)) * float(_safe_float(it.get("qty"), 0.0))
        except Exception:
            continue
    return items

_IX_HEADER_WORDS = [
    "description","item","product","qty","quantity","unit","price","net","vat","amount","total","code","pack","size"
]

_IX_STOP_WORDS = [
    "subtotal","sub total","sub-total","grand total","amount due","balance due","total due",
    "vat total","total vat","total payable","invoice total",
    "promotions saved you","total savings","savings",
    "registered in england","registered office","equity house","telephone","tel:","www.","company no","company number"
]

def _ix_contains_any(text: str, words: List[str]) -> bool:
    s = (text or "").lower()
    return any(w in s for w in words)

def _ix_center_x(b):
    x0, y0, x1, y1 = b
    return (x0 + x1) / 2.0

def _ix_bbox_to_tuple(bbox: Any) -> Optional[Tuple[float, float, float, float]]:
    try:
        if isinstance(bbox, dict):
            if isinstance(bbox.get("points"), list) and bbox.get("points"):
                xs = [_safe_float(p.get("x")) for p in list(bbox.get("points") or []) if isinstance(p, dict)]
                ys = [_safe_float(p.get("y")) for p in list(bbox.get("points") or []) if isinstance(p, dict)]
                if xs and ys:
                    left = min(xs)
                    top = min(ys)
                    right = max(xs)
                    bottom = max(ys)
                else:
                    left = _safe_float(bbox.get("left"))
                    top = _safe_float(bbox.get("top"))
                    right = _safe_float(bbox.get("right"))
                    bottom = _safe_float(bbox.get("bottom"))
            else:
                left = _safe_float(bbox.get("left"))
                top = _safe_float(bbox.get("top"))
                right = _safe_float(bbox.get("right"))
                bottom = _safe_float(bbox.get("bottom"))

            if bool(bbox.get("normalized")):
                page_w = _safe_float(bbox.get("page_width"), default=0.0)
                page_h = _safe_float(bbox.get("page_height"), default=0.0)
                if page_w > 0 and page_h > 0:
                    left *= page_w
                    right *= page_w
                    top *= page_h
                    bottom *= page_h
            return (float(left), float(top), float(right), float(bottom))

        if isinstance(bbox, (list, tuple)) and len(bbox) >= 4:
            return tuple(map(float, bbox[:4]))  # type: ignore[return-value]
    except Exception:
        return None
    return None

def _ix_group_lines_by_row(ocr_lines, y_tol: float = 12.0):
    try:
        if _IX_YTOL_OVERRIDE is not None:
            y_tol = float(_IX_YTOL_OVERRIDE)
    except Exception:
        pass
    rows = []
    for ln in ocr_lines:
        text = getattr(ln, "text", None) if not isinstance(ln, dict) else ln.get("text")
        bbox = getattr(ln, "bbox", None) if not isinstance(ln, dict) else ln.get("bbox")
        page = getattr(ln, "page", None) if not isinstance(ln, dict) else ln.get("page", 1)
        if not text or not bbox:
            continue
        bbox_tuple = _ix_bbox_to_tuple(bbox)
        if not bbox_tuple:
            continue
        x0, y0, x1, y1 = bbox_tuple
        rows.append((int(page), y0, x0, x1, y1, str(text).strip()))

    rows.sort(key=lambda r: (r[0], r[1], r[2]))

    groups = []
    cur = []
    cur_key = None
    for page, y0, x0, x1, y1, text in rows:
        if not cur:
            cur = [(x0,y0,x1,y1,text)]
            cur_key = (page, y0)
            continue
        if page == cur_key[0] and abs(y0 - cur_key[1]) <= y_tol:
            cur.append((x0,y0,x1,y1,text))
        else:
            groups.append((cur_key[0], cur))
            cur = [(x0,y0,x1,y1,text)]
            cur_key = (page, y0)
    if cur:
        groups.append((cur_key[0], cur))
    return groups

def _booker_estimate_row_skew(ocr_lines) -> Dict[int, float]:
    """Estimate page skew from Booker item-row anchors.

    Positive slope means right-side row tokens sit lower than left-side code tokens.
    The value is pixels of Y drift per pixel of X.
    """
    by_page: Dict[int, List[Tuple[float, float]]] = {}
    for ln in ocr_lines or []:
        text = getattr(ln, "text", None) if not isinstance(ln, dict) else ln.get("text")
        bbox = getattr(ln, "bbox", None) if not isinstance(ln, dict) else ln.get("bbox")
        page = getattr(ln, "page", None) if not isinstance(ln, dict) else ln.get("page", 1)
        if not text or not bbox:
            continue
        bbox_tuple = _ix_bbox_to_tuple(bbox)
        if not bbox_tuple:
            continue
        x0, y0, x1, y1 = bbox_tuple
        cx = (x0 + x1) / 2.0
        cy = (y0 + y1) / 2.0
        txt = str(text).strip()
        if re.fullmatch(r"\d{5,7}", txt) or re.fullmatch(r"\d+(?:\.\d+)?%?", txt) or re.fullmatch(r"\d+\.\d{2}", txt):
            by_page.setdefault(int(page or 1), []).append((cx, cy))

    slopes: Dict[int, float] = {}
    for page, pts in by_page.items():
        if len(pts) < 12:
            continue
        mean_x = sum(p[0] for p in pts) / len(pts)
        mean_y = sum(p[1] for p in pts) / len(pts)
        denom = sum((x - mean_x) ** 2 for x, _y in pts)
        if denom <= 0:
            continue
        slope = sum((x - mean_x) * (y - mean_y) for x, y in pts) / denom
        # Ignore extreme slopes; they are usually page layout, not scan skew.
        if abs(slope) <= 0.08:
            slopes[page] = float(slope)
    return slopes

def _booker_group_lines_by_row_skew_aware(ocr_lines, y_tol: float = 12.0):
    slopes = _booker_estimate_row_skew(ocr_lines)
    if not slopes:
        return _ix_group_lines_by_row(ocr_lines, y_tol=y_tol)

    rows = []
    for ln in ocr_lines or []:
        text = getattr(ln, "text", None) if not isinstance(ln, dict) else ln.get("text")
        bbox = getattr(ln, "bbox", None) if not isinstance(ln, dict) else ln.get("bbox")
        page = getattr(ln, "page", None) if not isinstance(ln, dict) else ln.get("page", 1)
        if not text or not bbox:
            continue
        bbox_tuple = _ix_bbox_to_tuple(bbox)
        if not bbox_tuple:
            continue
        x0, y0, x1, y1 = bbox_tuple
        page_i = int(page or 1)
        slope = slopes.get(page_i, 0.0)
        y_corr = y0 - (slope * ((x0 + x1) / 2.0))
        rows.append((page_i, y_corr, x0, x1, y0, y1, str(text).strip()))

    rows.sort(key=lambda r: (r[0], r[1], r[2]))
    groups = []
    cur = []
    cur_key = None
    for page, y_corr, x0, x1, y0, y1, text in rows:
        if not cur:
            cur = [(x0, y0, x1, y1, text)]
            cur_key = (page, y_corr)
            continue
        if page == cur_key[0] and abs(y_corr - cur_key[1]) <= y_tol:
            cur.append((x0, y0, x1, y1, text))
            cur_key = (page, (cur_key[1] * 0.75) + (y_corr * 0.25))
        else:
            groups.append((cur_key[0], cur))
            cur = [(x0, y0, x1, y1, text)]
            cur_key = (page, y_corr)
    if cur:
        groups.append((cur_key[0], cur))
    return groups

def _booker_split_items_with_embedded_codes(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    out: List[Dict[str, Any]] = []
    embedded_code_re = re.compile(r"\b(\d{5,7})\b")
    for item in items or []:
        if not isinstance(item, dict):
            continue
        out.append(item)
        desc = str(item.get("description") or "").strip()
        matches = list(embedded_code_re.finditer(desc))
        if not matches:
            continue
        tail_start = None
        for m in matches:
            before = desc[:m.start()].strip()
            after = desc[m.end():].strip()
            if before and after:
                tail_start = m.start()
                break
        if tail_start is None:
            continue
        prefix = desc[:tail_start].strip()
        tail = desc[tail_start:].strip()
        segments = list(embedded_code_re.finditer(tail))
        if not segments:
            continue
        item["description"] = prefix
        for idx, m in enumerate(segments):
            code = m.group(1)
            seg_start = m.end()
            seg_end = segments[idx + 1].start() if idx + 1 < len(segments) else len(tail)
            seg_desc = tail[seg_start:seg_end].strip()
            if not seg_desc:
                continue
            clone = dict(item)
            clone["code"] = code
            clone["description"] = seg_desc
            clone["_splitFromEmbeddedCode"] = True
            out.append(clone)
    for idx, item in enumerate(out, start=1):
        try:
            item["lineNo"] = idx
        except Exception:
            pass
    return out

def _text_from_ocr_lines(ocr_lines) -> str:
    """Rebuild readable text from OCR line boxes (for header salvage)."""
    if not ocr_lines:
        return ""
    groups = _ix_group_lines_by_row(ocr_lines, y_tol=12.0)
    lines: List[str] = []
    for _page, toks in groups:
        toks.sort(key=lambda t: t[0])
        line = " ".join([t[4] for t in toks if t[4]]).strip()
        if line:
            lines.append(line)
    return "\n".join(lines).strip()

def _booker_simple_items_from_ocr_lines(ocr_lines, engine: str = "") -> List[Dict[str, Any]]:
    """Simple Booker line-item extraction from OCR row lines only.

    For Doctr, preserve the stable r10 behavior.
    For Tesseract, use the enhanced merge logic to recover stacked VAT lines.
    """
    if not ocr_lines:
        return []
    eng = (engine or "").lower().strip()
    groups = _booker_group_lines_by_row_skew_aware(ocr_lines, y_tol=12.0)

    # ---- Doctr / default path (r10 behavior) ----
    if eng in ("doctr", "local_doctr", ""):
        lines: List[str] = []
        for _page, toks in groups:
            toks.sort(key=lambda t: t[0])
            line = " ".join([t[4] for t in toks if t[4]]).strip()
            if not line:
                continue
            up = line.upper()
            # Find an item code anywhere in the line
            m = re.search(r"\b(\d{5,7})\b", line)
            if not m:
                continue
            code = m.group(1)
            # Reorder tokens so code starts the line (some OCR lines have values before the code)
            try:
                toks2 = line.split()
                if code in toks2:
                    idx = toks2.index(code)
                    line = " ".join(toks2[idx:] + toks2[:idx]).strip()
            except Exception:
                pass
            # Skip headers/footers/noise ONLY if no code present (we already confirmed a code)
            if any(k in up for k in (
                "TELEPHONE", "TEL", "FAX", "REGISTERED OFFICE",
                "VAT NUMBER", "AWRS", "BRANCH"
            )):
                continue
            lines.append(line)
        if not lines:
            return []
        txt = "\n".join(lines)
        try:
            return _booker_split_items_with_embedded_codes(BookerCombinedRowParser().parse(txt))
        except Exception:
            return []

    # ---- Tesseract path (enhanced merge) ----
    rows: List[str] = []
    for _page, toks in groups:
        toks.sort(key=lambda t: t[0])
        line = " ".join([t[4] for t in toks if t[4]]).strip()
        if not line:
            continue
        up = line.upper()
        # Skip headers/footers/noise
        if any(k in up for k in (
            "TELEPHONE", "TEL", "FAX", "REGISTERED", "BOOKER", "EQUITY HOUSE", "REGISTERED OFFICE",
            "VAT NUMBER", "AWRS", "BRANCH", "INVOICE", "TOTAL", "SUB-TOTAL", "SAVING", "PROMOTION",
            "RATE", "GOODS", "NETT"
        )):
            continue
        rows.append(line)
    if not rows:
        return []

    def _is_vat_only_line(s: str) -> bool:
        toks = [t for t in re.split(r"\s+", (s or "").strip()) if t]
        if len(toks) != 1:
            return False
        vc = BookerCombinedRowParser._norm_vat_code(toks[0])
        return vc in ("A", "B", "C", "Z", "Z/A", "R")

    def _looks_like_rrp_por_line(s: str) -> bool:
        return bool(re.search(r"\d+\.\d{2}\s+\d+(?:\.\d+)?%?", s or ""))

    merged: List[str] = []
    cur: Optional[str] = None
    i = 0
    while i < len(rows):
        ln = rows[i]
        if re.match(r"^\s*\d{5,7}\b", ln):
            if cur:
                merged.append(cur.strip())
            cur = ln
        else:
            if cur:
                cur = f"{cur} {ln}".strip()
        i += 1
    if cur:
        merged.append(cur.strip())

    merged2: List[str] = []
    i = 0
    while i < len(merged):
        ln = merged[i]
        if _is_vat_only_line(ln) and merged2:
            prev = merged2.pop()
            add = ln
            if i + 1 < len(merged) and _looks_like_rrp_por_line(merged[i + 1]):
                add = f"{add} {merged[i + 1]}"
                i += 1
            merged2.append(f"{prev} {add}".strip())
        else:
            merged2.append(ln)
        i += 1

    txt = "\n".join(merged2)
    try:
        items = BookerCombinedRowParser().parse(txt)
        if items and merged2:
            code_to_rows: Dict[str, List[str]] = {}
            for ln in merged2:
                codes = re.findall(r"\b\d{5,7}\b", ln or "")
                if not codes:
                    continue
                for code_raw in codes:
                    code_norm = code_raw.lstrip("0") or code_raw
                    code_to_rows.setdefault(code_raw, []).append(ln)
                    if code_norm != code_raw:
                        code_to_rows.setdefault(code_norm, []).append(ln)
            for it in items:
                try:
                    code = re.sub(r"\D+", "", str(it.get("code") or ""))
                    code_norm = code.lstrip("0") if code else ""
                    row_list = code_to_rows.get(code) or (code_to_rows.get(code_norm) if code_norm else None)
                    if code and row_list:
                        it["rawRow"] = row_list.pop(0)
                        if not it.get("raw"):
                            it["raw"] = it["rawRow"]
                except Exception:
                    continue
    except Exception:
        items = []
    return items

def _ix_row_text(g):
    txt = " ".join([x[4] for x in sorted(g, key=lambda z: z[0])]).strip()
    txt = _fix_vat_code_symbol(txt)
    return _fix_pm_code(txt)

def _fix_vat_code_symbol(s: str) -> str:
    """Fix OCR symbol confusion for VAT code C (Â©/Â¢ -> C)."""
    if not s:
        return s
    return s.replace("Â©", "C").replace("Â¢", "C")

def _fix_pm_code(s: str) -> str:
    """Fix common OCR confusion in Booker promo codes (PM165 -> PML65)."""
    if not s:
        return s
    # Replace PMl/PMI/PM| followed by 2-4 digits with PM1xxxx (e.g., PML65 -> PM165, PML049 -> PM1049)
    s = re.sub(r"\b(PM)[LIL\|]([0-9]{2,4})\b", r"\g<1>1\2", s, flags=re.IGNORECASE)
    # Handle spaced OCR variants like "PM L00" or "PM I19"
    s = re.sub(r"\b(PM)\s*[LIL\|]\s*([0-9]{2,4})\b", r"\g<1>1\2", s, flags=re.IGNORECASE)
    # Handle inline variants without word boundaries (e.g., "OriginalPML00")
    s = re.sub(r"(PM)[LIL\|]([0-9]{2,4})", r"\g<1>1\2", s, flags=re.IGNORECASE)
    s = re.sub(r"(PM)\s*[LIL\|]\s*([0-9]{2,4})", r"\g<1>1\2", s, flags=re.IGNORECASE)
    # Fix PMOxx -> PM0xx when O is used for zero
    s = re.sub(r"\b(PM)O([0-9]{2,4})\b", r"\g<1>0\2", s, flags=re.IGNORECASE)
    s = re.sub(r"(PM)O([0-9]{2,4})", r"\g<1>0\2", s, flags=re.IGNORECASE)
    return s

def _ix_parse_pct(text: str) -> float:
    m = re.search(r"(\d+(?:\.\d+)?)\s*%?", text)
    if not m:
        return 0.0
    try:
        return float(m.group(1))
    except Exception:
        return 0.0

def _ix_has_percent(text: str) -> bool:
    return "%" in (text or "")

def _ix_to_money(tok: str) -> float:
    t = tok.strip().replace(",", "").replace("Ã‚Â£","").replace("$","").replace("Ã¢â€šÂ¬","")
    try:
        return float(t)
    except Exception:
        return 0.0

def _ix_parse_money(text: str) -> float:
    toks = re.findall(r"[Ã‚Â£$Ã¢â€šÂ¬]?\-?\d+(?:\.\d{2})?", text.replace(",", ""))
    if not toks:
        return 0.0
    return _ix_to_money(toks[-1])

def _ix_find_header_columns(groups):
    def _norm_hdr(t: str) -> str:
        return re.sub(r"[^a-z0-9]+", "", (t or "").lower())

    want = {
        "code": ["code", "itemcode", "item#", "itmcode"],
        "description": ["description", "desc", "item", "product"],
        "pack_size": ["packsize", "pack", "size", "casesize", "case", "pk"],
        "qty": ["qty", "quantity", "qnty", "q'ty"],
        "price": ["price", "unitprice", "unit"],
        "value": ["value", "amount", "total", "net"],
        "vat": ["vat", "vatcode", "vat%"],
        "std_rrp": ["stdrrp", "rrp", "std"],
        "por": ["por", "p.o.r", "profit"],
    }

    want_norm = {k: {_norm_hdr(w) for w in v} for k, v in want.items()}

    for page, g in groups:
        toks = [(x0, y0, x1, y1, text) for (x0, y0, x1, y1, text) in sorted(g, key=lambda z: z[0])]
        txt = _ix_row_text(g)
        low = txt.lower()

        hits = 0
        for key, words in want.items():
            if any(w in low for w in words):
                hits += 1
        if hits < 3:
            continue

        centers = {}
        for i, (x0, y0, x1, y1, text) in enumerate(toks):
            t_norm = _norm_hdr(text)
            for key, words_norm in want_norm.items():
                if key in centers:
                    continue
                if t_norm in words_norm and t_norm:
                    centers[key] = _ix_center_x((x0, y0, x1, y1))

            if i + 1 < len(toks):
                nx0, ny0, nx1, ny1, ntext = toks[i + 1]
                n_norm = _norm_hdr(ntext)
                pair = t_norm + n_norm
                if "pack_size" not in centers and pair == "packsize":
                    centers["pack_size"] = _ix_center_x((x0, y0, nx1, ny1))
                if "std_rrp" not in centers and pair in ("stdrrp", "rrpstd"):
                    centers["std_rrp"] = _ix_center_x((x0, y0, nx1, ny1))
                if "price" not in centers and pair == "unitprice":
                    centers["price"] = _ix_center_x((x0, y0, nx1, ny1))

        if len(centers) >= 3:
            return page, centers
    return None, {}

def _ix_assign_to_column(xc: float, centers: Dict[str, float]) -> str:
    best = None
    best_d = 1e9
    for k, cx in centers.items():
        d = abs(xc - cx)
        if d < best_d:
            best_d = d
            best = k
    return best or ""

def _ix_parse_signed_numeric(text: str) -> float:
    s = str(text or "").strip().replace(",", "")
    if not s:
        return 0.0
    if s.endswith("-") and re.fullmatch(r"\d+(?:\.\d+)?-", s):
        try:
            return -float(s[:-1])
        except Exception:
            return 0.0
    if re.fullmatch(r"-?\d+(?:\.\d+)?", s):
        try:
            return float(s)
        except Exception:
            return 0.0
    if len(s) == 1 and s.upper() in ("L", "I", "|"):
        return 1.0
    return 0.0

def _ix_line_mid_x(line: Dict[str, Any]) -> float:
    bbox = dict(line.get("bbox") or {})
    return (_safe_float(bbox.get("left")) + _safe_float(bbox.get("right"))) / 2.0

def _ix_line_mid_y(line: Dict[str, Any]) -> float:
    bbox = dict(line.get("bbox") or {})
    return (_safe_float(bbox.get("top")) + _safe_float(bbox.get("bottom"))) / 2.0

def _ix_line_left(line: Dict[str, Any]) -> float:
    return _safe_float(dict(line.get("bbox") or {}).get("left"))

def _ix_booker_find_exact_headers(page_lines: List[Dict[str, Any]]) -> Optional[Dict[str, Dict[str, Any]]]:
    headers: Dict[str, Dict[str, Any]] = {}
    for line in page_lines:
        text = re.sub(r"\s+", " ", str(line.get("text") or "").upper()).strip()
        if text == "CODE":
            headers["code"] = line
        elif text == "DESCRIPTION":
            headers["description"] = line
        elif text == "PACK SIZE":
            headers["pack_size"] = line
        elif text == "QTY":
            headers["qty"] = line
        elif text == "PRICE":
            headers["price"] = line
        elif text == "VALUE":
            headers["value"] = line
        elif text == "VAT":
            headers["vat"] = line
        elif text in {"RRP POR", "VAT RRP"}:
            headers["rrp_por"] = line
    if len(headers) < 7:
        return None
    if "vat" not in headers and "rrp_por" in headers:
        headers["vat"] = headers["rrp_por"]
    return headers

def _ix_booker_column_ranges(headers: Dict[str, Dict[str, Any]]) -> Dict[str, Tuple[float, float]]:
    order = ["code", "description", "pack_size", "qty", "price", "value", "vat", "rrp_por"]
    centers = [(name, _ix_line_mid_x(line)) for name, line in headers.items() if name in order]
    centers.sort(key=lambda item: item[1])
    if not centers:
        return {}
    boundaries: List[float] = [0.0]
    for idx in range(len(centers) - 1):
        boundaries.append((centers[idx][1] + centers[idx + 1][1]) / 2.0)
    boundaries.append(999999.0)
    ranges: Dict[str, Tuple[float, float]] = {}
    for idx, (name, _) in enumerate(centers):
        ranges[name] = (boundaries[idx], boundaries[idx + 1])
    return ranges

def _ix_booker_assign_column_by_range(x_center: float, ranges: Dict[str, Tuple[float, float]]) -> str:
    order = ["code", "description", "pack_size", "qty", "price", "value", "vat", "rrp_por"]
    for name in order:
        if name not in ranges:
            continue
        left, right = ranges[name]
        if left <= x_center < right:
            return name
    return "rrp_por"

def _ix_booker_is_header_text(text: str) -> bool:
    txt = re.sub(r"\s+", " ", str(text or "").upper()).strip()
    return txt in {"CODE", "DESCRIPTION", "PACK SIZE", "QTY", "PRICE", "VALUE", "VAT", "RRP POR", "VAT RRP"}

def _ix_booker_is_footer_or_noise_row(lines: List[Dict[str, Any]], header_y: float) -> bool:
    merged = re.sub(r"\s+", " ", " ".join(str(line.get("text") or "") for line in lines).upper()).strip()
    if not merged:
        return True
    if any(_ix_booker_is_header_text(str(line.get("text") or "")) for line in lines):
        return True
    row_y = sum(_ix_line_mid_y(line) for line in lines) / max(1, len(lines))
    if row_y <= header_y:
        return True
    if merged.startswith("EXC.VAT") or merged.startswith("/CONT") or merged.startswith("PAGE "):
        return True
    if merged in {"VAT", "STD"} and min(_ix_line_left(line) for line in lines) < 40.0:
        return True
    return False

def _ix_booker_parse_rrp_por(text: str) -> Tuple[float, float]:
    raw = re.sub(r"\s+", " ", str(text or "").strip())
    if not raw:
        return 0.0, 0.0
    money_match = re.search(r"(\d+(?:\.\d{2})?)", raw)
    pct_match = re.search(r"(\d+(?:\.\d+)?)\s*%?", raw[money_match.end():] if money_match else raw)
    std_rrp = float(money_match.group(1)) if money_match else 0.0
    por = 0.0
    if pct_match:
        try:
            por = float(pct_match.group(1))
        except Exception:
            por = 0.0
    return std_rrp, por

def _ix_booker_row_signal(code: str, description: str, qty_text: str, price_text: str, value_text: str) -> bool:
    if re.fullmatch(r"\d{5,7}", str(code or "").strip()):
        return True
    if str(code or "").strip() and str(description or "").strip():
        return True
    return any(str(v or "").strip() for v in (qty_text, price_text, value_text))

def _ix_booker_split_code_description(text: str) -> Tuple[str, str]:
    cleaned = _fix_pm_code(_fix_vat_code_symbol(re.sub(r"\s+", " ", str(text or "").strip())))
    m = re.match(r"^(M?\d{5,7})\s+(.*)$", cleaned, flags=re.IGNORECASE)
    if not m:
        return "", cleaned
    code = re.sub(r"[^A-Z0-9]+", "", m.group(1).upper())
    if code.startswith("M"):
        code = code[1:]
    return code, m.group(2).strip()

def _ix_booker_split_value_vat(value_text: str, vat_text: str) -> Tuple[str, str]:
    value_clean = re.sub(r"\s+", " ", _fix_vat_code_symbol(str(value_text or "").strip()))
    vat_clean = re.sub(r"\s+", " ", _fix_vat_code_symbol(str(vat_text or "").strip()))
    if vat_clean:
        return value_clean, vat_clean
    m = re.match(r"^(.*\S)\s+([ABZRC]|Z/A)$", value_clean, flags=re.IGNORECASE)
    if m:
        return m.group(1).strip(), m.group(2).upper()
    return value_clean, vat_clean

def _ix_booker_pack_fields(pack_text: str) -> Tuple[int, str]:
    cleaned = _norm_pack_tokens(str(pack_text or "").strip())
    toks = [t for t in cleaned.split() if t.strip()]
    if not toks:
        return 0, ""
    case_pack = int(_ix_parse_signed_numeric(toks[0]) or 0)
    unit_size = " ".join(toks[1:]).strip()
    if not unit_size and len(toks) == 1:
        unit_size = toks[0] if BookerCombinedRowParser._unit_size_token(toks[0]) else ""
        if unit_size:
            case_pack = 0
    return case_pack, unit_size

def _ix_booker_is_non_product_candidate(code: str, merged_text: str) -> bool:
    merged = re.sub(r"\s+", " ", str(merged_text or "").upper()).strip()
    if not merged:
        return True
    blocked = (
        "SUB-TOTAL",
        "TOTAL ITEMS",
        "INVOICE TOTAL",
        "PLEASE DO NOT BRING BACK",
        "EMPTY BREAD TRAY",
        "EXC.VAT",
        "NETT",
        "GOODS :",
        "GOODS:",
        "RATE",
        "/CONT",
        "WINES SPIRITS BEERS",
        "RETAIL GROCERY",
        "CHILLED",
    )
    if any(tok in merged for tok in blocked):
        return True
    return not bool(re.fullmatch(r"\d{5,7}", str(code or "").strip()))

def _ix_extract_items_booker_table(ocr_lines) -> List[Dict[str, Any]]:
    groups = _ix_group_lines_by_row(ocr_lines, y_tol=12.0)
    grouped_lines: Dict[int, List[Dict[str, Any]]] = {}
    for page, g in groups:
        page_rows = grouped_lines.setdefault(int(page), [])
        for x0, y0, x1, y1, text in g:
            page_rows.append(
                {
                    "text": str(text).strip(),
                    "bbox": {"left": float(x0), "top": float(y0), "right": float(x1), "bottom": float(y1)},
                    "page": int(page),
                }
            )

    header_page = None
    headers: Optional[Dict[str, Dict[str, Any]]] = None
    for page in sorted(grouped_lines.keys()):
        headers = _ix_booker_find_exact_headers(grouped_lines.get(page, []))
        if headers:
            header_page = page
            break
    if header_page is None or not headers:
        return []
    ranges = _ix_booker_column_ranges(headers)
    header_y = min(_ix_line_mid_y(line) for line in headers.values())

    items: List[Dict[str, Any]] = []
    for page, g in groups:
        if page < header_page:
            continue

        row_lines = [
            {
                "text": str(text).strip(),
                "bbox": {"left": float(x0), "top": float(y0), "right": float(x1), "bottom": float(y1)},
                "page": int(page),
            }
            for x0, y0, x1, y1, text in sorted(g, key=lambda z: z[0])
        ]
        if _ix_booker_is_footer_or_noise_row(row_lines, header_y):
            continue

        col_text: Dict[str, List[str]] = {}
        for line in row_lines:
            xc = _ix_line_mid_x(line)
            col = _ix_booker_assign_column_by_range(xc, ranges)
            col_text.setdefault(col, []).append(str(line.get("text") or "").strip())

        code_text = " ".join(col_text.get("code", [])).strip()
        desc_text = " ".join(col_text.get("description", [])).strip()
        pack_text = " ".join(col_text.get("pack_size", [])).strip()
        qty_text = " ".join(col_text.get("qty", [])).strip()
        price_text = " ".join(col_text.get("price", [])).strip()
        value_text = " ".join(col_text.get("value", [])).strip()
        vat_text = " ".join(col_text.get("vat", [])).strip()
        rrp_por_text = " ".join(col_text.get("rrp_por", [])).strip()

        code, code_desc = _ix_booker_split_code_description(code_text)
        if code:
            description = " ".join([code_desc, desc_text]).strip()
        else:
            code, description = _ix_booker_split_code_description(desc_text)

        value_text, vat_text = _ix_booker_split_value_vat(value_text, vat_text)
        merged_text = " ".join(
            [code, description, pack_text, qty_text, price_text, value_text, vat_text, rrp_por_text]
        ).strip()
        if _ix_booker_is_non_product_candidate(code, merged_text):
            continue
        if not _ix_booker_row_signal(code, description, qty_text, price_text, value_text):
            continue

        qty = _ix_parse_signed_numeric(qty_text)
        unit_price = _ix_parse_money(price_text) if price_text else 0.0
        line_net = _ix_parse_money(value_text) if value_text else 0.0
        if qty < 0 and line_net > 0:
            line_net = -line_net
        case_pack, unit_size = _ix_booker_pack_fields(pack_text)
        std_rrp, por = _ix_booker_parse_rrp_por(rrp_por_text)

        vat_code = BookerCombinedRowParser._norm_vat_code(vat_text)
        if vat_code and vat_code not in ("A", "B", "C", "Z", "Z/A", "R"):
            vat_code = ""
        vat_rate = float(BookerCombinedRowParser.DEFAULT_VAT_MAP.get(vat_code, 0.0)) if vat_code else 0.0
        vat_amount = round(line_net * (vat_rate / 100.0), 2) if line_net and vat_rate else 0.0
        line_gross = round(line_net + vat_amount, 2) if line_net else 0.0

        # Carry-forward: Booker continuation rows (different pack size, same product) have no
        # code or description in the OCR layout. Inherit from the preceding row so they are
        # identifiable rather than appearing with a blank code.
        if not code and not description and items:
            prev = items[-1]
            if prev.get("code"):
                code = prev["code"]
                description = prev.get("description", "")

        items.append(
            {
                "lineNo": len(items) + 1,
                "code": code,
                "description": description,
                "casePack": int(case_pack or 0),
                "unitSize": unit_size,
                "qty": float(qty or 0.0),
                "totalUnits": round(float(qty or 0.0) * float(case_pack or 0.0), 2) if qty and case_pack else 0.0,
                "unitPrice": float(unit_price or 0.0),
                "lineNet": float(line_net or 0.0),
                "vatCode": vat_code,
                "vatRate": float(vat_rate or 0.0),
                "vatAmount": float(vat_amount or 0.0),
                "lineGross": float(line_gross or 0.0),
                "stdRrp": float(std_rrp or 0.0),
                "por": float(por or 0.0),
            }
        )
    return items

def _ix_extract_items_booker(ocr_lines) -> List[Dict[str, Any]]:
    try:
        table_items = _ix_extract_items_booker_table(ocr_lines)
        if table_items:
            return table_items
    except Exception:
        pass

    groups = _ix_group_lines_by_row(ocr_lines, y_tol=12.0)
    header_page, centers = _ix_find_header_columns(groups)
    if not centers:
        return []

    items: List[Dict[str, Any]] = []
    line_no = 0
    prev_incomplete = None

    def _vat_only_from_group(pg_idx: int) -> str:
        if pg_idx < 0 or pg_idx >= len(groups):
            return ""
        page_g, g2 = groups[pg_idx]
        if page_g < header_page:
            return ""
        txt2 = _ix_row_text(g2).strip()
        if not txt2:
            return ""
        # Accept single-token VAT rows (A/B/C/Z/R/Z/A)
        toks2 = [t for t in re.split(r"\s+", txt2) if t.strip()]
        if len(toks2) != 1:
            return ""
        vc = BookerCombinedRowParser._norm_vat_code(toks2[0])
        if vc not in ("A", "B", "C", "Z", "Z/A", "R"):
            return ""
        # Ensure it sits near the VAT column
        if "vat" in centers and g2:
            try:
                xs = [t[0] for t in g2]
                x1s = [t[2] for t in g2]
                xc = (min(xs) + max(x1s)) / 2.0
                if abs(xc - centers["vat"]) > 120:
                    return ""
            except Exception:
                pass
        return vc

    for gi in range(len(groups)):
        page, g = groups[gi]
        if page < header_page:
            continue
        txt = _ix_row_text(g)
        low = txt.lower()
        if _ix_contains_any(low, _IX_STOP_WORDS):
            break

        col_text: Dict[str, List[str]] = {}
        for x0,y0,x1,y1,text in g:
            xc = _ix_center_x((x0,y0,x1,y1))
            col = _ix_assign_to_column(xc, centers)
            col_text.setdefault(col, []).append(text)

        code = " ".join(col_text.get("code", [])).strip()
        desc = " ".join(col_text.get("description", [])).strip()
        pack_size = " ".join(col_text.get("pack_size", [])).strip()
        qty_txt = " ".join(col_text.get("qty", [])).strip()
        price_txt = " ".join(col_text.get("price", [])).strip()
        value_txt = " ".join(col_text.get("value", [])).strip()
        vat_txt = _fix_vat_code_symbol(" ".join(col_text.get("vat", [])).strip())
        std_rrp_txt = " ".join(col_text.get("std_rrp", [])).strip()
        por_txt = " ".join(col_text.get("por", [])).strip()

        qty = _ix_parse_money(qty_txt) if qty_txt else 0.0
        unit_price = _ix_parse_money(price_txt) if price_txt else 0.0
        if value_txt and re.search(r"\b(FREE|FOC)\b", value_txt, flags=re.I):
            line_net = 0.0
        else:
            line_net = _ix_parse_money(value_txt) if value_txt else 0.0
        std_rrp = _ix_parse_money(std_rrp_txt) if std_rrp_txt else 0.0
        por = _ix_parse_pct(por_txt) if por_txt else 0.0

        vat_rate = 0.0
        vat_amount = 0.0
        vat_code = ""
        if vat_txt:
            if re.search(r"[A-Za-z]", vat_txt) and not re.search(r"\d", vat_txt):
                vat_code = BookerCombinedRowParser._norm_vat_code(vat_txt.strip())
            elif _ix_has_percent(vat_txt):
                vat_rate = _ix_parse_pct(vat_txt)
            else:
                vat_amount = _ix_parse_money(vat_txt)

        # If VAT code missing, try to pick it from the next 1-2 OCR rows (often a single-letter line)
        if not vat_code:
            for off in (1, 2):
                vc = _vat_only_from_group(gi + off)
                if vc:
                    vat_code = vc
                    break
        line_gross = 0.0

        if (not vat_code) or (std_rrp <= 0.0) or (por <= 0.0) or (not pack_size):
            toks = [t for t in re.split(r"\s+", txt) if t.strip()]

            def _is_flag(t: str) -> bool:
                return t.strip().upper() in ("P", "SL", "S/L", "SK", "SH", "SI", "S1")

            def _is_vat_code(t: str) -> bool:
                return BookerCombinedRowParser._norm_vat_code(t) in ("B", "A", "Z", "Z/A", "R", "C")

            def _is_unitsize(t: str) -> bool:
                return bool(re.fullmatch(r"\d+(?:\.\d+)?\s*(ML|L|G|KG|CL)", t.strip().upper()))

            def _as_num_strict(t: str) -> float:
                s = (t or "").strip()
                if not re.fullmatch(r"-?\d+(?:\.\d+)?", s):
                    return 0.0
                try:
                    return float(s)
                except Exception:
                    return 0.0

            if por <= 0.0:
                for t in reversed(toks):
                    if "%" in t:
                        por = _ix_parse_pct(t)
                        if por:
                            break
            if por <= 0.0:
                for t in reversed(toks):
                    if re.fullmatch(r"\d+(?:\.\d+)?", t):
                        try:
                            por = float(t)
                            break
                        except Exception:
                            break

            if not vat_code:
                for t in reversed(toks):
                    if _is_vat_code(t):
                        vat_code = BookerCombinedRowParser._norm_vat_code(t)
                        break
            if not vat_code:
                for t in reversed(toks):
                    vc = BookerCombinedRowParser._norm_vat_code(t)
                    if vc in ("B", "A", "Z", "Z/A", "R", "C"):
                        vat_code = vc
                        break

            if std_rrp <= 0.0 and vat_code:
                try:
                    idxs = [i for i, t in enumerate(toks) if BookerCombinedRowParser._norm_vat_code(t) == vat_code]
                    if idxs:
                        i = idxs[-1]
                        for j in range(i + 1, min(i + 4, len(toks))):
                            v = _ix_parse_money(toks[j])
                            if v > 0:
                                std_rrp = v
                                break
                except Exception:
                    pass

            try:
                vat_idx = None
                for i in range(len(toks) - 1, 0, -1):
                    if _is_vat_code(toks[i]):
                        vat_idx = i
                        break
                if vat_idx is not None:
                    value_idx = None
                    for j in range(vat_idx - 1, 1, -1):
                        if _as_num_strict(toks[j]) > 0:
                            value_idx = j
                            break
                    if value_idx is not None and line_net <= 0.0:
                        line_net = _as_num_strict(toks[value_idx])

                    scan_left = value_idx - 1 if value_idx is not None else None
                    if scan_left is not None and scan_left >= 0 and _is_flag(toks[scan_left]):
                        scan_left -= 1

                    if scan_left is not None and scan_left >= 0 and unit_price <= 0.0:
                        for j in range(scan_left, 1, -1):
                            v = _as_num_strict(toks[j])
                            if v > 0:
                                unit_price = v
                                price_idx = j
                                break
                        else:
                            price_idx = None
                    else:
                        price_idx = None

                    if price_idx is not None and qty <= 0.0:
                        for j in range(price_idx - 1, 1, -1):
                            v = _as_num_strict(toks[j])
                            if v > 0:
                                qty = v
                                qty_idx = j
                                break
                        else:
                            qty_idx = None
                    else:
                        qty_idx = None

                    if qty_idx is not None:
                        if qty_idx - 1 >= 0 and _is_unitsize(toks[qty_idx - 1]):
                            unit_size = toks[qty_idx - 1].replace(" ", "")
                        else:
                            unit_size = ""
                    else:
                        unit_size = ""

                    if not pack_size:
                        for t in toks:
                            if re.fullmatch(r"PM\d+", t.upper()):
                                pack_size = t.upper()
                                break
            except Exception:
                pass

        if not pack_size and desc:
            d = desc.upper()
            m = re.search(r"\bPM\d+\b", d)
            if m:
                pack_size = m.group(0)
            else:
                m = re.search(r"\b\d+(?:\.\d+)?\s*(ML|L|G|KG|CL)\b", d)
                if m:
                    pack_size = m.group(0).replace(" ", "")

        if pack_size and desc:
            desc = re.sub(rf"\s*\b{re.escape(pack_size)}\b\s*$", "", desc, flags=re.IGNORECASE).strip()

        if qty and unit_price and (line_net <= 0.0 or abs(line_net - unit_price) < 0.01) and qty > 1:
            line_net = round(float(qty) * float(unit_price), 2)

        has_amounts = (qty > 0 or unit_price > 0 or line_net > 0 or vat_amount > 0 or line_gross > 0)
        if desc and not has_amounts and prev_incomplete is not None:
            prev_incomplete["description"] = (prev_incomplete.get("description","") + " " + desc).strip()
            continue

        if not desc or not has_amounts:
            continue

        line_no += 1
        if line_gross > 0:
            if vat_rate > 0:
                line_net = round(line_gross / (1.0 + (vat_rate / 100.0)), 2)
                vat_amount = round(line_gross - line_net, 2)
            elif vat_amount > 0:
                line_net = round(line_gross - vat_amount, 2)
                if line_net > 0:
                    vat_rate = round((vat_amount / line_net) * 100.0, 2)
        if line_net <= 0 and unit_price and qty:
            line_net = round(unit_price * qty, 2)
            if vat_rate > 0:
                vat_amount = round(line_net * (vat_rate / 100.0), 2)
                if line_gross <= 0:
                    line_gross = round(line_net + vat_amount, 2)
            elif vat_amount > 0:
                if line_gross <= 0:
                    line_gross = round(line_net + vat_amount, 2)
                if line_net > 0 and vat_rate <= 0:
                    vat_rate = round((vat_amount / line_net) * 100.0, 2)
        if line_net <= 0 and line_gross > 0 and vat_rate <= 0 and vat_amount <= 0:
            line_net = line_gross

        item = {
            "lineNo": line_no,
            "page": page,
            "code": code,
            "packSize": pack_size,
            "description": desc,
            "qty": qty,
            "unitPrice": unit_price,
            "lineNet": line_net or 0.0,
            "vatRate": vat_rate or 0.0,
            "vatAmount": vat_amount or 0.0,
            "vatCode": vat_code,
            "lineGross": line_gross or 0.0,
            "stdRrp": std_rrp,
            "por": por,
            "CODE": code,
            "DESCRIPTION": desc,
            "PACK SIZE": pack_size,
            "QTY": qty,
            "PRICE": unit_price,
            "VALUE": line_net or 0.0,
            "VAT": vat_code or (vat_rate or vat_amount),
            "STD RRP": std_rrp,
            "POR": por,
            "raw": txt,
        }
        # Clamp POR to 0-100 (avoid OCR bleed from other columns)
        try:
            if item["por"] < 0 or item["por"] > 100:
                item["por"] = 0.0
                item["POR"] = 0.0
        except Exception:
            pass
        items.append(item)
        prev_incomplete = item

    return items


def _mark_void_items(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Mark void items based on qty/lineNet or VOID markers in raw text."""
    if not items:
        return items
    for it in items:
        try:
            q = _safe_float(it.get("qty"))
            ln = _safe_float(it.get("lineNet"))
            raw = (str(it.get("rawRow") or it.get("raw") or "")).upper()
            if q < 0 or ln < 0 or ("VOID" in raw):
                it["isVoid"] = True
        except Exception:
            continue
    return items

def _dhamecha_parse_purchase_invoice(txt: str) -> Dict[str, Any]:
    """
    Dhamecha purchase invoice parser for Local OCR / PDF text layer.

    This supplier PDF often contains a legal disclaimer at the top which can break naive supplier detection.
    We parse from the PDF text layer when available and fall back to OCR text.
    """
    up = (txt or "").upper()
    header = {
        "supplierName": "Dhamecha Foods Limited",
        "customerName": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
    }
    items: List[Dict[str, Any]] = []

    # Invoice number
    m = re.search(r"(?im)\bINVOICE\s*[:#]?\s*([0-9]{5,10})\b", txt or "")
    if m:
        header["invoiceNumber"] = m.group(1).strip()

    # Date (prefer "16 Jan 2026" style)
    m = re.search(r"(?im)\bDate/Time\s*\n\s*([0-9]{1,2}\s+[A-Za-z]{3}\s+[0-9]{4})", txt or "")
    if not m:
        m = re.search(r"(?im)\b([0-9]{1,2}\s+[A-Za-z]{3}\s+[0-9]{4}),\s*[0-9]{1,2}:[0-9]{2}\b", txt or "")
    if m:
        try:
            dt = datetime.datetime.strptime(m.group(1).strip(), "%d %b %Y")
            header["invoiceDate"] = dt.date().isoformat()
        except Exception:
            header["invoiceDate"] = m.group(1).strip()

    # Totals
    def _money(pat: str) -> float:
        mm = re.search(pat, txt or "", flags=re.I | re.M)
        if not mm:
            return 0.0
        return _safe_float(mm.group(1))

    # These appear near the bottom of the Dhamecha invoice
    header["totalNet"] = _money(r"(?im)\bTotal\s+Goods:\s*[^0-9\-]*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{2})?)")
    header["totalVat"] = _money(r"(?im)^\s*VAT:\s*[^0-9\-]*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{2})?)\s*$")
    header["totalGross"] = _money(r"(?im)\bTotal\s+incl\s+VAT:\s*[^0-9\-]*([0-9]{1,3}(?:,[0-9]{3})*(?:\.[0-9]{2})?)")

    lines = [ (ln or "").replace("\xa0", " ").strip() for ln in (txt or "").splitlines() ]

    # Customer name: capture the trading name line above address (e.g. DAILY DELIGHTS STORE)
    # Look for a likely uppercase business name line followed by a street number.
    m = re.search(r"(?m)\n([A-Z][A-Z0-9 &'\-\/]{3,})\n\s*\d{1,4}\s+[A-Z]", txt or "")
    if m:
        header["customerName"] = _collapse_spaces(m.group(1).strip().title())
    # Dhamecha fallback: capture customer block near the top (often title-case name + ALLCAPS store)
    if not header["customerName"]:
        try:
            def _clean_line(s: str) -> str:
                return _collapse_spaces((s or "").replace("\t", " ")).strip()

            skip_pat = re.compile(
                r"(?i)\b(INVOICE|DATE/TIME|VAT\s*REG|VAT\s*NO|BUSINESS\s*ID|TILL\s*ID|CASHIER\s*ID|TEL|PHONE)\b"
            )
            inv_idx = next((i for i, ln in enumerate(lines) if re.search(r"(?i)\bINVOICE\b", ln)), 0)
            stop_idx = next((i for i, ln in enumerate(lines) if re.search(r"(?i)\bITEM\s*#\b", ln)), min(inv_idx + 15, len(lines)))
            window = lines[inv_idx + 1 : stop_idx]
            cand = []
            for ln in window:
                s = _clean_line(ln)
                if not s:
                    continue
                if skip_pat.search(s):
                    continue
                if "DHAMECHA" in s.upper():
                    continue
                if re.fullmatch(r"[0-9\s\-\.,]+", s):
                    continue
                cand.append(s)
            # Prefer a title-case person name line (has lowercase letters, no digits)
            person = next(
                (c for c in cand if re.search(r"[a-z]", c) and not re.search(r"\d", c) and len(c.split()) >= 2),
                "",
            )
            if person:
                header["customerName"] = _title_case(person)
            else:
                # Fallback: ALLCAPS store name without digits
                store = next((c for c in cand if c.isupper() and not re.search(r"\d", c) and len(c.split()) >= 2), "")
                if store:
                    header["customerName"] = _title_case(store)
                else:
                    # Final fallback: any mixed-case line
                    mixed = next((c for c in cand if re.search(r"[A-Za-z]", c) and not re.search(r"\d", c) and len(c.split()) >= 2), "")
                    if mixed:
                        header["customerName"] = _title_case(mixed)
        except Exception:
            pass

    # Line items: parse lines that start with item number then description + columns ending with POR% and VAT code.
    # The PDF text layer prints items as single lines; OCR may vary but usually keeps tokens.
    # Line items (Dhamecha):
    # The extracted text (PDF text layer OR OCR) often appears as a vertical table:
    #   827873
    #   DESCRIPTION (may be 13 lines)
    #   20's
    #   -
    #   10
    #   1
    #   113.75
    #   113.75P
    #   14.70
    #   7.10%
    #   A
    #
    # So we parse by blocks: itemNo line  find next POR% line  VAT code line.
    vat_map = {"A": 20.0, "B": 5.0, "Z": 0.0, "R": 5.0}

    def _extract_unit_size_from_desc(desc: str) -> str:
        if not desc:
            return ""
        # Pick the last size-like token from description. Dhamecha can print
        # compound pack sizes such as 5x70g as part of the product text.
        m = re.findall(
            r"(?i)\b(\d+\s*x\s*\d+(?:\.\d+)?\s*(?:ml|cl|l|ltr|litr|litre|litres|g|kg|oz|lb|pk|pcs|pc|w|\'s)|"
            r"\d+(?:\.\d+)?\s*(?:ml|cl|l|ltr|litr|litre|litres|g|kg|oz|lb|pk|pcs|pc|w|\'s))\b",
            desc,
        )
        if m:
            return _collapse_spaces(m[-1]).replace(" ", "")
        return ""

    def _strip_unit_size_from_desc(desc: str, unit_size: str) -> str:
        d = _collapse_spaces(desc or "")
        us = _collapse_spaces(unit_size or "")
        if not d or not us:
            return d
        d2 = re.sub(rf"(?i)(?<!\w){re.escape(us)}(?:\*+)?(?!\w)", "", d).strip()
        d2 = re.sub(r"\s{2,}", " ", d2).strip()
        return d2 or d

    def _is_bad_unit_size_token(tok: str) -> bool:
        t = (tok or "").strip().upper()
        return t in ("PROMO", "PROMOTION", "OFFER", "DEAL", "SAVE", "SAVING", "DISC", "DISCOUNT")

    def _normalise_compact_item_row(line: str) -> str:
        """Split compact Dhamecha text-layer rows into parseable tokens."""
        s = (line or "").replace("Ã‚Â£", "£").replace("Â£", "£").replace("Ł", "£").strip()
        if not s:
            return ""
        # Item code often arrives glued to the first word of the description.
        s = re.sub(r"^\s*(\d{5,9})(?=[A-Za-z£])", r"\1 ", s)
        # PMP and unit size can collapse into one token, e.g. "£1.3565g".
        s = re.sub(
            r"(£\d+\.\d{2})(\d+(?:\.\d+)?(?:MM|CM|M|ML|CL|L|LTR|LITR|LITRE|LITRES|G|KG|OZ|LB|PK|PCS|PC|W|'S))\b",
            r"\1 \2",
            s,
            flags=re.IGNORECASE,
        )
        # POR and VAT code can also collapse, e.g. "43.30%A".
        s = re.sub(r"(\d+(?:\.\d+)?)%([A-Z])\b", r"\1% \2", s)
        s = re.sub(r"\s+", " ", s)
        return s.strip()

    def _clean_dhamecha_desc(desc: str) -> str:
        d = _collapse_spaces(str(desc or "")).strip(" -:\t")
        d = re.sub(r"(?i)^(ITEM\s*#?\s*)?PRODUCT\s+DESCRIPTION\s+UOP\s+UOS\s+QTY\s+PRICE.*?\bVAT\b\s*", "", d).strip()
        d = re.sub(r"(?i)^T&S:HL[0-9A-Z\-&/ ]+\s*", "", d).strip()
        d = re.sub(r"\s+", " ", d).strip(" -:\t")
        return d

    def _looks_reasonable_unit_size(tok: str) -> bool:
        t = str(tok or "").strip()
        if not t:
            return False
        if re.fullmatch(r"(?i)\d+(?:\.\d+)?\s*(ml|cl|l|ltr|litr|litre|litres|g|kg|oz|lb|pk|pcs|pc|w|'s)", t):
            return True
        if re.fullmatch(r"\d{1,3}", t):
            return True
        return False

    def _fix_ocr_numeric(x: Any, *, field: str = "") -> float:
        v = _safe_float(x)
        if field in ("unitPrice", "lineNet", "stdRrp") and v > 1000:
            while v > 1000:
                v = v / 100.0
        if field == "por" and v > 100:
            while v > 100:
                v = v / 10.0
        return float(v)

    def _dhamecha_item_quality(it: Dict[str, Any]) -> int:
        desc = _clean_dhamecha_desc(it.get("description") or "")
        score = 0
        if desc:
            score += min(14, len(desc.split()))
        if desc and not re.search(r"(?i)\bITEM\s*#|PRODUCT\s+DESCRIPTION|T&S:HL", desc):
            score += 8
        up = _fix_ocr_numeric(it.get("unitPrice"), field="unitPrice")
        net = _fix_ocr_numeric(it.get("lineNet"), field="lineNet")
        rrp = _fix_ocr_numeric(it.get("stdRrp"), field="stdRrp")
        por = _fix_ocr_numeric(it.get("por"), field="por")
        if 0 < up < 1000:
            score += 8
        if 0 < net < 1000:
            score += 8
        if 0 <= rrp <= 100:
            score += 4
        elif rrp > 200:
            score -= 8
        if 0 <= por <= 100:
            score += 4
        else:
            score -= 8
        vc = str(it.get("vatCode") or "").strip().upper()
        if vc in ("A", "B", "Z", "R"):
            score += 4
        else:
            score -= 10
        if _looks_reasonable_unit_size(it.get("unitSize") or ""):
            score += 3
        return score

    def _dhamecha_desc_key(desc: str) -> str:
        txt = re.sub(r"[^A-Z0-9]+", " ", str(desc or "").upper()).strip()
        txt = re.sub(r"\b\d+(?:MG|ML|CL|L|G|KG|OZ|LB|'S)\b", "", txt)
        return " ".join(txt.split())

    def _dhamecha_desc_similar(a: str, b: str) -> bool:
        ka = _dhamecha_desc_key(a)
        kb = _dhamecha_desc_key(b)
        if not ka or not kb:
            return False
        if ka == kb:
            return True
        if ka in kb or kb in ka:
            short = min(len(ka), len(kb))
            long = max(len(ka), len(kb))
            return short >= 12 and (short / max(long, 1)) >= 0.65
        wa = set(ka.split())
        wb = set(kb.split())
        if not wa or not wb:
            return False
        overlap = len(wa & wb)
        return overlap >= max(2, min(len(wa), len(wb)) - 1)

    def _dedupe_dhamecha_items(raw_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not raw_items:
            return []
        out: List[Dict[str, Any]] = []
        current_key: Optional[Tuple[str, str, float]] = None
        current_best: Optional[Dict[str, Any]] = None
        for src in raw_items:
            if not isinstance(src, dict):
                continue
            it = dict(src)
            it["description"] = _clean_dhamecha_desc(it.get("description") or "")
            unit_size_current = str(it.get("unitSize") or "").strip()
            if _is_bad_unit_size_token(unit_size_current):
                unit_size_current = ""
            unit_size_from_desc = _extract_unit_size_from_desc(it.get("description") or "")
            if not unit_size_current and unit_size_from_desc:
                unit_size_current = unit_size_from_desc
            if unit_size_current:
                it["unitSize"] = unit_size_current
                it["description"] = _strip_unit_size_from_desc(it.get("description") or "", unit_size_current)
            it["unitPrice"] = _fix_ocr_numeric(it.get("unitPrice"), field="unitPrice")
            it["lineNet"] = _fix_ocr_numeric(it.get("lineNet"), field="lineNet")
            it["stdRrp"] = _fix_ocr_numeric(it.get("stdRrp"), field="stdRrp")
            it["por"] = _fix_ocr_numeric(it.get("por"), field="por")
            it["vatRate"] = float(vat_map.get(str(it.get("vatCode") or "").strip().upper(), _normalise_vat_rate(it.get("vatRate")) or 20.0))
            try:
                it["vatAmount"] = round(_safe_float(it.get("lineNet")) * (_safe_float(it.get("vatRate")) / 100.0), 2)
                it["lineGross"] = round(_safe_float(it.get("lineNet")) + _safe_float(it.get("vatAmount")), 2)
            except Exception:
                pass
            code = re.sub(r"\D+", "", str(it.get("code") or ""))
            if not code:
                continue
            desc_key = re.sub(r"[^A-Z0-9]+", " ", str(it.get("description") or "").upper()).strip()
            desc_key = " ".join(desc_key.split()[:8])
            line_net = round(_safe_float(it.get("lineNet")), 2)
            key = (code, desc_key, line_net)
            if current_key is None:
                current_key = key
                current_best = it
                continue
            if key == current_key:
                if current_best is None or _dhamecha_item_quality(it) > _dhamecha_item_quality(current_best):
                    current_best = it
                continue
            if current_best is not None:
                out.append(dict(current_best))
            current_key = key
            current_best = it
        if current_best is not None:
            out.append(dict(current_best))
        for idx, row in enumerate(out, start=1):
            row["lineNo"] = idx
        return out

    def _dedupe_dhamecha_item_clusters(raw_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        """Collapse OCR echo rows while keeping legitimate distinct products."""
        if not raw_items:
            return []
        normalised = _normalise_dhamecha_items(raw_items)
        out: List[Dict[str, Any]] = []
        i = 0
        while i < len(normalised):
            best = dict(normalised[i])
            j = i + 1
            while j < len(normalised):
                cur = normalised[j]
                prev = normalised[j - 1]
                code_a = re.sub(r"\D+", "", str(best.get("code") or ""))
                code_b = re.sub(r"\D+", "", str(cur.get("code") or ""))
                if not code_a or code_a != code_b:
                    break
                if not _dhamecha_desc_similar(best.get("description") or "", cur.get("description") or ""):
                    break
                if round(_safe_float(best.get("qty")), 3) != round(_safe_float(cur.get("qty")), 3):
                    break
                if round(_fix_ocr_numeric(best.get("unitPrice"), field="unitPrice"), 2) != round(_fix_ocr_numeric(cur.get("unitPrice"), field="unitPrice"), 2):
                    break
                if round(_fix_ocr_numeric(best.get("lineNet"), field="lineNet"), 2) != round(_fix_ocr_numeric(cur.get("lineNet"), field="lineNet"), 2):
                    break
                # Only collapse tight OCR clusters, not distant repeated purchases.
                if (j - i) > 2 and re.sub(r"\D+", "", str(prev.get("code") or "")) != code_a:
                    break
                if _dhamecha_item_quality(cur) > _dhamecha_item_quality(best):
                    best = dict(cur)
                j += 1
            out.append(best)
            i = j
        for idx, row in enumerate(out, start=1):
            row["lineNo"] = idx
        return out

    def _normalise_dhamecha_items(raw_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        out: List[Dict[str, Any]] = []
        for idx, src in enumerate(raw_items or [], start=1):
            if not isinstance(src, dict):
                continue
            it = dict(src)
            it["description"] = _clean_dhamecha_desc(it.get("description") or "")
            it["unitPrice"] = _fix_ocr_numeric(it.get("unitPrice"), field="unitPrice")
            it["lineNet"] = _fix_ocr_numeric(it.get("lineNet"), field="lineNet")
            it["stdRrp"] = _fix_ocr_numeric(it.get("stdRrp"), field="stdRrp")
            it["por"] = _fix_ocr_numeric(it.get("por"), field="por")
            it["vatRate"] = float(vat_map.get(str(it.get("vatCode") or "").strip().upper(), _normalise_vat_rate(it.get("vatRate")) or 20.0))
            try:
                it["vatAmount"] = round(_safe_float(it.get("lineNet")) * (_safe_float(it.get("vatRate")) / 100.0), 2)
                it["lineGross"] = round(_safe_float(it.get("lineNet")) + _safe_float(it.get("vatAmount")), 2)
            except Exception:
                pass
            it["lineNo"] = idx
            out.append(it)
        return out

    # --- Horizontal table parser (preferred when PDF text layer keeps rows on one line) ---
    def _parse_horizontal_rows(_lines: List[str]) -> List[Dict[str, Any]]:
        start = -1
        for idx, ln in enumerate(_lines):
            u = (ln or "").upper()
            if "ITEM" in u and "PRODUCT" in u and "VAT" in u and "VALUE" in u:
                start = idx + 1
                break
        if start < 0:
            # OCR sometimes misses the header row; fall back to scanning all lines
            start = 0
        out: List[Dict[str, Any]] = []

        def _looks_like_vat_code(tok: str) -> bool:
            t = BookerCombinedRowParser._norm_vat_code(tok or "")
            return bool(re.fullmatch(r"[A-Z]{1,2}", t))

        def _strip_price(tok: str) -> str:
            t = (tok or "").replace("Ã‚Â£", "").replace("Â£", "").replace("Ł", "").strip()
            t = re.sub(r"(?<=\d)[A-Za-z]+$", "", t)
            return t.strip()

        def _strip_header_noise(desc: str) -> str:
            if not desc:
                return desc
            # Remove embedded table header tokens sometimes prefixed before the real description.
            d = desc.strip()
            d2 = re.sub(
                r"(?i)^(ITEM\s*#?\s*)?PRODUCT\s+DESCRIPTION\s+UOP\s+UOS\s+QTY\s+PRICE.*?\bVAT\b\s+",
                "",
                d,
            ).strip()
            if d2 != d:
                return d2
            u = d.upper()
            header_hits = all(k in u for k in ("ITEM", "PRODUCT", "DESCRIPTION", "UOP", "UOS", "QTY", "PRICE"))
            if header_hits and "VAT" in u:
                idx = u.rfind("VAT")
                if idx >= 0:
                    tail = d[idx + 3 :].strip(" -:\t")
                    if tail:
                        return tail
            return d

        def _strip_desc_noise_tokens(desc: str) -> str:
            if not desc:
                return desc
            toks = desc.split()
            cleaned = []
            for t in toks:
                # Drop standalone numeric noise tokens (e.g., product codes like 1411/2716)
                if re.fullmatch(r"\d{3,}", t):
                    continue
                # Dhamecha rows can leak PMP tokens into the description when text compacts.
                if re.fullmatch(r"[£Ł]\d+\.\d{2}", t):
                    continue
                cleaned.append(t)
            return " ".join(cleaned).strip()


        def _is_desc_continuation_line(s: str) -> bool:
            if not s:
                return False
            u = s.upper().strip()
            if not u:
                return False
            if u.startswith(("TROLLEY:", "CASES:", "SINGLES:", "TOTAL:", "SUB TOTAL:", "INC. VAT:", "ITEMS TOTAL:", "CODE", "RATE", "VALUE OF GOODS", "TOTAL GOODS:", "VAT:", "TOTAL INCL")):
                return False
            if re.fullmatch(r"\d{3,9}", s.split()[0]) if s.split() else False:
                return False
            # Avoid lines that look like full numeric rows
            if len(re.findall(r"\d+\.\d{2}", s)) >= 2:
                return False
            return True

        def _should_prepend_prev_desc(curr_desc: str) -> bool:
            d = (curr_desc or "").strip()
            if not d:
                return True
            # Only prepend if the current description is very short/weak.
            if len(d.split()) <= 3:
                return True
            if not re.search(r"[A-Za-z]", d):
                return True
            if re.fullmatch(
                r"(?i)\d+(?:\.\d+)?\s*(ml|cl|l|ltr|litr|litre|litres|g|kg|oz|lb|pk|pcs|pc|w|'s)",
                d,
            ):
                return True
            return False

        def _should_append_next_desc(next_desc: str) -> bool:
            n = (next_desc or "").strip()
            if not n:
                return False
            # Append short, likely continuation fragments (e.g., "PEANUTS")
            if len(n.split()) <= 2:
                return True
            # Allow small word-only tails (e.g., "MIX", "PEANUTS", "ORIGINAL")
            if re.search(r"[A-Za-z]", n) and not re.search(r"\d", n) and len(n.split()) <= 3:
                return True
            return False

        def _parse_promo_continuation_line(s: str, base_row: Dict[str, Any]) -> Optional[Dict[str, Any]]:
            raw = _collapse_spaces((s or "").replace("Ã‚Â£", "£").replace("Â£", "£").replace("Ł", "£")).strip()
            if not raw:
                return None
            up = raw.upper()
            if up.startswith(("TROLLEY:", "CASES:", "SINGLES:", "TOTAL:", "SUB TOTAL:", "INC. VAT:", "ITEMS TOTAL:", "CODE", "RATE", "VALUE OF GOODS", "TOTAL GOODS:", "VAT:", "TOTAL INCL")):
                return None
            if re.fullmatch(r"\d{3,9}", raw.split()[0]) if raw.split() else False:
                return None
            if len(re.findall(r"-?\d+\.\d{2}", raw)) > 1:
                return None
            promo_hint = (
                up.startswith("T&S:")
                or "FREE" in up
                or "BUY" in up
                or "GET" in up
                or "PROMO" in up
                or "OFFER" in up
                or "DEAL" in up
                or "SAVE" in up
                or "DISC" in up
            )
            amt_match = re.search(r"(-\d+\.\d{2}|\d+\.\d{2}-)\s*$", raw)
            if not promo_hint or not amt_match:
                return None
            amount_txt = amt_match.group(1).strip()
            amount = _safe_float(amount_txt.replace(",", ""))
            if amount_txt.endswith("-") and amount >= 0:
                amount = -amount
            if amount >= 0:
                amount = -abs(amount)
            desc = raw[: amt_match.start()].strip(" -:\t")
            desc = re.sub(r"(?i)^T&S:HL[0-9A-Z\-]+\s*", "", desc).strip()
            desc = _collapse_spaces(desc).strip(" -:\t") or "PROMO"
            vat_code = str(base_row.get("vatCode") or "").strip().upper()
            vat_rate = float(vat_map.get(vat_code, _normalise_vat_rate(base_row.get("vatRate")) or 20.0))
            vat_amount = round(amount * (vat_rate / 100.0), 2) if vat_rate > 0 else 0.0
            promo_code = str(base_row.get("code") or "").strip() or "PROMO"
            return {
                "lineNo": len(out) + 1,
                "code": promo_code,
                "description": f"PROMO: {desc}",
                "casePack": 0,
                "unitSize": 0,
                "qty": 0.0,
                "totalUnits": 0.0,
                "unitPrice": float(amount),
                "lineNet": round(float(amount), 2),
                "vatRate": float(vat_rate),
                "vatAmount": float(vat_amount),
                "lineGross": round(float(amount) + float(vat_amount), 2),
                "stdRrp": 0.0,
                "por": 0.0,
                "vatCode": vat_code or "A",
                "rowTag": "PROMO",
                "pmp": "",
            }

        def _parse_promo_at(line_idx: int, base_row: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], int]:
            if line_idx < 0 or line_idx >= len(_lines):
                return None, 0
            promo_src = (_lines[line_idx] or "").strip()
            promo_row = _parse_promo_continuation_line(promo_src, base_row)
            if promo_row:
                return promo_row, 1
            if line_idx + 1 >= len(_lines):
                return None, 0
            amount_src = (_lines[line_idx + 1] or "").strip()
            if not re.fullmatch(r"(?:-\d+\.\d{2}|\d+\.\d{2}-)", amount_src):
                return None, 0
            promo_row = _parse_promo_continuation_line(f"{promo_src} {amount_src}", base_row)
            return (promo_row, 2) if promo_row else (None, 0)

        def _parse_row_line(line: str) -> Optional[Dict[str, Any]]:
            line = _normalise_compact_item_row(line)
            toks = (line or "").split()
            if len(toks) < 8:
                return None
            if not re.fullmatch(r"\d{3,9}", toks[0]):
                return None
            vat_code = BookerCombinedRowParser._norm_vat_code(toks[-1])
            if not _looks_like_vat_code(vat_code):
                return None
            # Expected columns from the end:
            # ... UOP UOS Qty Price Ext RRP POR VAT
            # But OCR is noisy; detect POR by % and walk back.
            por_idx = None
            for k in range(len(toks) - 2, max(len(toks) - 6, 1), -1):
                if "%" in toks[k]:
                    por_idx = k
                    break
            if por_idx is None:
                por_idx = len(toks) - 2
            rrp_idx = por_idx - 1
            ext_idx = rrp_idx - 1
            price_idx = ext_idx - 1
            qty_idx = price_idx - 1
            uos_idx = qty_idx - 1
            uop_idx = uos_idx - 1

            if ext_idx <= 1 or qty_idx <= 1:
                return None

            por_tok = toks[por_idx] if por_idx < len(toks) else ""
            rrp_tok = toks[rrp_idx] if rrp_idx < len(toks) else ""
            ext_tok = toks[ext_idx] if ext_idx < len(toks) else ""
            unit_tok = toks[price_idx] if price_idx < len(toks) else ""
            qty_tok = toks[qty_idx] if qty_idx < len(toks) else ""
            uos_tok = toks[uos_idx] if uos_idx < len(toks) else ""
            uop_tok = toks[uop_idx] if uop_idx < len(toks) else ""

            if not _looks_like_number(_strip_price(ext_tok)):
                return None
            if not _looks_like_number(_strip_price(qty_tok)):
                return None

            line_net = _safe_float(_strip_price(ext_tok))
            qty = _safe_float(_strip_price(qty_tok))
            unit_price = _safe_float(_strip_price(unit_tok)) if _looks_like_number(_strip_price(unit_tok)) else 0.0
            std_rrp = _safe_float(_strip_price(rrp_tok)) if _looks_like_number(_strip_price(rrp_tok)) else 0.0
            por = _safe_float((por_tok or "").replace("%", "").strip()) if por_tok else 0.0
            desc_end = max(uop_idx, 1)
            desc = _strip_header_noise(" ".join(toks[1:desc_end]).strip())
            desc = _strip_desc_noise_tokens(desc)

            def _looks_like_size_token(tok: str) -> bool:
                if not tok:
                    return False
                return bool(re.search(r"(?i)\b\d+(?:\.\d+)?\s*(ml|cl|l|ltr|litr|litre|litres|g|kg|oz|lb)\b", tok))

            # Prefer size from description; else prefer UOP if it looks like a size, then UOS if it looks like a size.
            unit_size = _extract_unit_size_from_desc(desc)
            if not unit_size:
                if _looks_like_size_token(uop_tok):
                    unit_size = _collapse_spaces(uop_tok).strip()
                elif _looks_like_size_token(uos_tok):
                    unit_size = _collapse_spaces(uos_tok).strip()
                else:
                    unit_size = ""
            if _is_bad_unit_size_token(unit_size):
                unit_size = _extract_unit_size_from_desc(desc)
            desc = _strip_unit_size_from_desc(desc, unit_size)
            case_pack = ""
            try:
                uos_n = _safe_float(uos_tok)
                uop_n = None
                if re.fullmatch(r"\d+\s*x", (uos_tok or "").lower()):
                    uos_n = _safe_float(re.sub(r"\D+", "", uos_tok))
                if re.fullmatch(r"\d+\s*x", (uop_tok or "").lower()):
                    uop_n = _safe_float(re.sub(r"\D+", "", uop_tok))
                elif re.fullmatch(r"\d+(?:\.\d+)?", (uop_tok or "")) and not _looks_like_size_token(uop_tok):
                    uop_n = _safe_float(uop_tok)
                if uos_n and _looks_like_size_token(uop_tok):
                    case_pack = str(int(uos_n))
                elif uop_n and uos_n:
                    case_pack = str(int(uop_n * uos_n))
                elif uos_n:
                    case_pack = str(int(uos_n))
            except Exception:
                pass
            if not desc:
                desc = "Item"
            vat_rate = float(vat_map.get(vat_code, 20.0))
            vat_amount = round(line_net * (vat_rate / 100.0), 2) if vat_rate > 0 else 0.0
            return {
                "lineNo": len(out) + 1,
                "code": toks[0],
                "description": _collapse_spaces(desc),
                "casePack": case_pack,
                "unitSize": unit_size,
                "qty": qty,
                "unitPrice": unit_price,
                "lineNet": round(line_net, 2),
                "vatRate": vat_rate,
                "vatAmount": vat_amount,
                "lineGross": round(line_net + vat_amount, 2),
                "stdRrp": float(std_rrp),
                "por": float(por),
                "vatCode": vat_code,
                "pmp": f"{float(std_rrp):.2f}" if std_rrp and float(std_rrp) > 0 else "",
            }

        i = start
        while i < len(_lines):
            ln = _normalise_compact_item_row(_lines[i])
            if not (ln or "").strip():
                i += 1
                continue
            u = ln.upper()
            if "TOTAL GOODS" in u or "VALUE OF GOODS" in u or u.strip().startswith("VAT:") or "TOTAL INCL VAT" in u:
                i += 1
                continue
            # If the line starts with an item code but is split, stitch until VAT code appears.
            if re.fullmatch(r"\d{3,9}", (ln or "").split()[0]) if (ln or "").split() else False:
                buf = ln.strip()
                j = i + 1
                while j < len(_lines):
                    nxt = _normalise_compact_item_row(_lines[j])
                    if not nxt:
                        j += 1
                        continue
                    # If we already have a VAT code at the end of the buffer, do not append further lines.
                    try:
                        last_tok = buf.split()[-1]
                        if _looks_like_vat_code(last_tok):
                            break
                    except Exception:
                        pass
                    # Stop if next line starts with another item code or totals
                    if re.fullmatch(r"\d{3,9}", nxt.split()[0]) if nxt.split() else False:
                        break
                    if "TOTAL GOODS" in nxt.upper() or "VALUE OF GOODS" in nxt.upper() or nxt.upper().startswith("VAT:") or "TOTAL INCL VAT" in nxt.upper():
                        break
                    # Append continuation
                    buf = (buf + " " + nxt).strip()
                    j += 1
                    # Early exit if last token now looks like VAT code
                    try:
                        last_tok = buf.split()[-1]
                        if _looks_like_vat_code(last_tok):
                            break
                    except Exception:
                        pass
                row = _parse_row_line(buf)
                if row:
                    # Also attach nearby description-only lines (before/after), common in Dhamecha
                    try:
                        prev = (_lines[i - 1] or "").strip() if i - 1 >= 0 else ""
                        if _is_desc_continuation_line(prev) and _should_prepend_prev_desc(row.get("description") or ""):
                            row["description"] = _collapse_spaces(prev + " " + (row.get("description") or ""))
                    except Exception:
                        pass
                    try:
                        nxt2 = (_lines[j] or "").strip() if j < len(_lines) else ""
                        if _is_desc_continuation_line(nxt2) and _should_append_next_desc(nxt2):
                            # Only append if the next line is not an item code.
                            if not (nxt2.split() and re.fullmatch(r"\d{3,9}", nxt2.split()[0])):
                                row["description"] = _collapse_spaces((row.get("description") or "") + " " + nxt2)
                    except Exception:
                        pass
                    # Re-evaluate unit size after description augmentation
                    try:
                        row["unitSize"] = _extract_unit_size_from_desc(row.get("description") or "") or row.get("unitSize")
                    except Exception:
                        pass
                    out.append(row)
                    try:
                        promo_row, promo_lines = _parse_promo_at(j, row)
                        if promo_row:
                            out.append(promo_row)
                            j += promo_lines
                    except Exception:
                        pass
                    i = j
                    continue
            # Fallback: parse the line as-is if possible
            row = _parse_row_line(ln)
            if row:
                try:
                    prev = (_lines[i - 1] or "").strip() if i - 1 >= 0 else ""
                    if _is_desc_continuation_line(prev) and _should_prepend_prev_desc(row.get("description") or ""):
                        row["description"] = _collapse_spaces(prev + " " + (row.get("description") or ""))
                    nxt2 = (_lines[i + 1] or "").strip() if i + 1 < len(_lines) else ""
                    if _is_desc_continuation_line(nxt2) and _should_append_next_desc(nxt2):
                        if not (nxt2.split() and re.fullmatch(r"\d{3,9}", nxt2.split()[0])):
                            row["description"] = _collapse_spaces((row.get("description") or "") + " " + nxt2)
                    row["unitSize"] = _extract_unit_size_from_desc(row.get("description") or "") or row.get("unitSize")
                except Exception:
                    pass
                out.append(row)
                try:
                    promo_row, promo_lines = _parse_promo_at(i + 1, row)
                    if promo_row:
                        out.append(promo_row)
                        i += promo_lines
                except Exception:
                    pass
            i += 1
        return out

    def _append_missing_dhamecha_promos(_lines: List[str], parsed_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        out = list(parsed_items or [])
        existing = {
            (
                re.sub(r"\s+", " ", str(it.get("description") or "").replace("PROMO:", "").strip().upper()),
                round(_safe_float(it.get("lineNet")), 2),
            )
            for it in out
            if str(it.get("description") or "").upper().startswith("PROMO:")
        }
        last_code = ""
        for raw_line in _lines:
            raw = _collapse_spaces((raw_line or "").replace("Ã‚Â£", "£").replace("Â£", "£").replace("Ł", "£")).strip()
            if not raw:
                continue
            code_match = re.match(r"^(\d{3,9})\b", raw)
            if code_match:
                last_code = code_match.group(1)
                continue
            up = raw.upper()
            if not (
                up.startswith("T&S:")
                or " BUY " in f" {up} "
                or " FREE" in up
                or " PROMO" in up
                or " OFFER" in up
                or " DEAL" in up
            ):
                continue
            amount_match = re.search(r"(-\d+\.\d{2}|\d+\.\d{2}-)\s*$", raw)
            if not amount_match:
                continue
            amount_txt = amount_match.group(1)
            amount = _safe_float(amount_txt.replace(",", ""))
            if amount_txt.endswith("-") and amount >= 0:
                amount = -amount
            if amount >= 0:
                amount = -abs(amount)
            desc = raw[: amount_match.start()].strip(" -:\t")
            desc = re.sub(r"(?i)^T&S:HL[0-9A-Z\-]+\s*", "", desc).strip()
            desc = _collapse_spaces(desc).strip(" -:\t") or "PROMO"
            key = (desc.upper(), round(float(amount), 2))
            if key in existing:
                continue
            base_idx = next(
                (idx for idx in range(len(out) - 1, -1, -1) if str(out[idx].get("code") or "").strip() == last_code),
                -1,
            )
            if base_idx < 0:
                continue
            base_row = out[base_idx]
            vat_code = str(base_row.get("vatCode") or "").strip().upper()
            vat_rate = float(vat_map.get(vat_code, _normalise_vat_rate(base_row.get("vatRate")) or 20.0))
            vat_amount = round(float(amount) * (vat_rate / 100.0), 2) if vat_rate > 0 else 0.0
            out.insert(
                base_idx + 1,
                {
                    "lineNo": 0,
                    "code": last_code or "PROMO",
                    "description": f"PROMO: {desc}",
                    "casePack": 0,
                    "unitSize": 0,
                    "qty": 0.0,
                    "totalUnits": 0.0,
                    "unitPrice": float(amount),
                    "lineNet": round(float(amount), 2),
                    "vatRate": float(vat_rate),
                    "vatAmount": float(vat_amount),
                    "lineGross": round(float(amount) + float(vat_amount), 2),
                    "stdRrp": 0.0,
                    "por": 0.0,
                    "vatCode": vat_code or "A",
                    "rowTag": "PROMO",
                    "pmp": "",
                },
            )
            existing.add(key)
        for idx, row in enumerate(out, start=1):
            row["lineNo"] = idx
        return out

    try:
        items = _parse_horizontal_rows(lines)
    except Exception:
        items = []

    # If horizontal parse succeeded, return immediately with header and items.
    if items:
        items = _append_missing_dhamecha_promos(lines, items)
        items = _normalise_dhamecha_items(items)
        items = _normalise_promo_quantities(items)
        # If totals missing, infer from items (but keep extracted totals if present)
        if _safe_float(header.get("totalNet")) <= 0:
            header["totalNet"] = round(sum(_safe_float(it.get("lineNet")) for it in items), 2)
        if _safe_float(header.get("totalVat")) <= 0:
            header["totalVat"] = round(sum(_safe_float(it.get("vatAmount")) for it in items), 2)
        if _safe_float(header.get("totalGross")) <= 0:
            header["totalGross"] = round(sum(_safe_float(it.get("lineGross")) for it in items), 2)
        return {"header": header, "items": items}

    # --- Vertical/stacked table parser (fallback) ---

    n = len(lines)
    i = 0

    def _strip_money_token(s: str) -> float:
        return _safe_float((s or "").replace("", "").replace("P", "").strip())

    def _is_skip_line(s: str) -> bool:
        sl = (s or "").strip().lower()
        if not sl:
            return True
        return sl.startswith((
            "trolley:", "cases:", "singles:", "total:", "sub total:", "inc. vat:",
            "items total:", "code", "rate", "value of goods", "total goods:", "vat:", "total incl",
            "this invoice", "please note", "title in the goods", "page "
        ))

    while i < n:
        s = lines[i]
        if _is_skip_line(s):
            i += 1
            continue

        if not re.fullmatch(r"\d{5,7}", s):
            i += 1
            continue

        item_no = s
        # Look ahead for a POR% line (ends with %) within the next 25 lines.
        por_idx = None
        for j in range(i + 1, min(i + 26, n)):
            sj = lines[j]
            if _is_skip_line(sj):
                continue
            if re.fullmatch(r"\d+(?:\.\d+)?%", sj):
                por_idx = j
                break
        if por_idx is None or por_idx + 1 >= n:
            i += 1
            continue

        vat_code = BookerCombinedRowParser._norm_vat_code(lines[por_idx + 1].strip())
        if vat_code not in vat_map and not re.fullmatch(r"[A-Z]{1,3}", vat_code):
            i += 1
            continue

        # We expect: ... UOP, UOS, Qty, Price, Ext, RRP, POR%, VAT
        # Therefore indices:
        #   uop = por_idx - 6
        #   uos = por_idx - 5
        #   qty = por_idx - 4
        #   unit = por_idx - 3
        #   ext = por_idx - 2
        #   rrp = por_idx - 1
        try:
            uop = lines[por_idx - 6].strip()
            uos = lines[por_idx - 5].strip()
            qty = _safe_float(lines[por_idx - 4].strip())
            unit = _strip_money_token(lines[por_idx - 3].strip())
            ext = _strip_money_token(lines[por_idx - 2].strip())
            rrp = _strip_money_token(lines[por_idx - 1].strip())
            por = _safe_float(lines[por_idx].replace("%", "").strip())
        except Exception:
            i += 1
            continue

        # Description is everything between item_no and uop (may be multi-line)
        desc_lines = []
        for k in range(i + 1, por_idx - 6):
            if _is_skip_line(lines[k]):
                continue
            desc_lines.append(lines[k])
        # Include a previous continuation line if present (Dhamecha often wraps before code line)
        try:
            prev = lines[i - 1] if i - 1 >= 0 else ""
            if prev and (not _is_skip_line(prev)) and (not re.fullmatch(r"\d{3,9}", prev.strip())):
                # avoid swallowing totals
                if not re.search(r"(TOTAL GOODS|TOTAL INCL VAT|VAT:)", prev, flags=re.I):
                    desc_lines.insert(0, prev)
        except Exception:
            pass
        # Include a following continuation line if present
        try:
            nxt = lines[por_idx + 2] if por_idx + 2 < n else ""
            if nxt and (not _is_skip_line(nxt)) and (not re.fullmatch(r"\d{3,9}", nxt.strip())):
                if not re.search(r"(TOTAL GOODS|TOTAL INCL VAT|VAT:)", nxt, flags=re.I):
                    desc_lines.append(nxt)
        except Exception:
            pass
        desc = _collapse_spaces(" ".join(desc_lines)).strip()

        vat_rate = float(vat_map.get(vat_code, 20.0))
        line_net = float(ext)
        vat_amt = _round2(line_net * (vat_rate / 100.0))
        line_gross = _round2(line_net + vat_amt)

        unit_size = _extract_unit_size_from_desc(desc) or _collapse_spaces(f"{uop} {uos}").strip()
        case_pack = ""
        try:
            uos_n = _safe_float(uos)
            uop_n = None
            if re.fullmatch(r"\d+\s*x", (uop or "").lower()):
                uop_n = _safe_float(re.sub(r"\D+", "", uop))
            elif re.fullmatch(r"\d+(?:\.\d+)?", (uop or "")):
                uop_n = _safe_float(uop)
            if uop_n and uos_n:
                case_pack = str(int(uop_n * uos_n))
            elif uos_n:
                case_pack = str(int(uos_n))
        except Exception:
            pass

        items.append({
            "lineNo": len(items) + 1,
            "code": item_no,
            "description": desc,
            "casePack": case_pack,
            "unitSize": unit_size,
            "qty": float(qty),
            "unitPrice": float(unit),
            "lineNet": float(line_net),
            "vatRate": float(vat_rate),
            "vatAmount": float(vat_amt),
            "lineGross": float(line_gross),
            "stdRrp": float(rrp),
            "por": float(por),
            "vatCode": vat_code,
            "pmp": f"{float(rrp):.2f}" if rrp and float(rrp) > 0 else "",
        })

        # Move index past this block to avoid double counting
        i = por_idx + 2
    # --- Loose OCR parser (last resort) ---
    if not items:
        def _looks_like_vat_code(tok: str) -> bool:
            t = BookerCombinedRowParser._norm_vat_code(tok or "")
            return bool(re.fullmatch(r"[A-Z]{1,2}", t))

        def _strip_price(tok: str) -> str:
            return (tok or "").replace("Ã‚Â£", "").replace("Â£", "").replace("P", "").strip()

        def _is_totals_line(s: str) -> bool:
            u = (s or "").upper()
            return ("TOTAL GOODS" in u) or ("VALUE OF GOODS" in u) or u.strip().startswith("VAT:") or ("TOTAL INCL VAT" in u)

        i = 0
        while i < n:
            ln = lines[i]
            if _is_skip_line(ln) or _is_totals_line(ln):
                i += 1
                continue
            ln = _normalise_compact_item_row(ln)
            toks = (ln or "").split()
            if not toks or not re.fullmatch(r"\d{3,9}", toks[0]):
                i += 1
                continue

            # Stitch continuation lines until we see a VAT code at the end or next item code
            buf = ln.strip()
            j = i + 1
            while j < n:
                nxt = _normalise_compact_item_row(lines[j])
                if not nxt:
                    j += 1
                    continue
                if _is_totals_line(nxt):
                    break
                if re.fullmatch(r"\d{3,9}", nxt.split()[0]) if nxt.split() else False:
                    break
                buf = (buf + " " + nxt).strip()
                try:
                    last_tok = buf.split()[-1]
                    if _looks_like_vat_code(last_tok):
                        break
                except Exception:
                    pass
                j += 1

            toks2 = buf.split()
            if len(toks2) >= 6 and re.fullmatch(r"\d{3,9}", toks2[0]):
                vat_code = BookerCombinedRowParser._norm_vat_code(toks2[-1])
                if _looks_like_vat_code(vat_code):
                    # try to locate POR token (has %)
                    por_idx = None
                    for k in range(len(toks2) - 2, max(len(toks2) - 7, 1), -1):
                        if "%" in toks2[k]:
                            por_idx = k
                            break
                    if por_idx is None:
                        por_idx = len(toks2) - 2
                    rrp_idx = por_idx - 1
                    ext_idx = rrp_idx - 1
                    price_idx = ext_idx - 1
                    qty_idx = price_idx - 1
                    uos_idx = qty_idx - 1
                    uop_idx = uos_idx - 1
                    if ext_idx > 1 and qty_idx > 1 and _looks_like_number(_strip_price(toks2[ext_idx])):
                        qty = _safe_float(_strip_price(toks2[qty_idx]))
                        unit_price = _safe_float(_strip_price(toks2[price_idx]))
                        line_net = _safe_float(_strip_price(toks2[ext_idx]))
                        std_rrp = _safe_float(_strip_price(toks2[rrp_idx])) if rrp_idx > 0 else 0.0
                        por = _safe_float((toks2[por_idx] or "").replace("%", "")) if por_idx > 0 else 0.0
                        uop_tok = toks2[uop_idx] if uop_idx > 0 else ""
                        uos_tok = toks2[uos_idx] if uos_idx > 0 else ""
                        desc = " ".join(toks2[1:max(uop_idx, 1)]).strip()
                        unit_size = _extract_unit_size_from_desc(desc) or _collapse_spaces(f"{uop_tok} {uos_tok}").strip()
                        case_pack = ""
                        try:
                            uos_n = _safe_float(uos_tok)
                            if uop_tok and uop_tok not in ("-",):
                                m = re.fullmatch(r"(\d+)\s*x", uop_tok.lower())
                                if m and uos_n > 0:
                                    case_pack = str(int(float(m.group(1)) * uos_n))
                            elif uos_n > 0:
                                case_pack = str(int(uos_n))
                        except Exception:
                            pass
                        vat_rate = float(vat_map.get(vat_code, 20.0))
                        vat_amount = round(line_net * (vat_rate / 100.0), 2) if vat_rate > 0 else 0.0
                        items.append({
                            "lineNo": len(items) + 1,
                            "code": toks2[0],
                            "description": _collapse_spaces(desc),
                            "casePack": case_pack,
                            "unitSize": unit_size,
                            "qty": float(qty),
                            "unitPrice": float(unit_price),
                            "lineNet": float(line_net),
                            "vatRate": float(vat_rate),
                            "vatAmount": float(vat_amount),
                            "lineGross": float(_round2(line_net + vat_amount)),
                            "stdRrp": float(std_rrp),
                            "por": float(por),
                            "vatCode": vat_code,
                            "pmp": f"{float(std_rrp):.2f}" if std_rrp and float(std_rrp) > 0 else "",
                        })

            i = j if j > i else i + 1

# Normalise and dedupe OCR-noisy Dhamecha rows before totals reconciliation
# If totals are missing but we have items, compute totals
    items = _normalise_dhamecha_items(items)
    items = _normalise_promo_quantities(items)
    if items and float(header.get("totalNet") or 0.0) <= 0.0:
        net = sum(_safe_float(it.get("lineNet")) for it in items)
        vat = sum(_safe_float(it.get("vatAmount")) for it in items)
        header["totalNet"] = _round2(net)
        header["totalVat"] = _round2(vat)
        header["totalGross"] = _round2(net + vat)

    return {"header": header, "items": items}


def _expense_find_next_value(lines: List[str], label_pattern: str, start: int = 0) -> str:
    pat = re.compile(label_pattern, flags=re.I)
    for i in range(start, len(lines)):
        if pat.search(lines[i] or ""):
            for j in range(i + 1, min(len(lines), i + 8)):
                val = (lines[j] or "").strip()
                if val:
                    return val
    return ""


def _expense_money_from_text(s: str) -> float:
    if not s:
        return 0.0
    m = re.search(r"[-+]?\s*(?:GBP|STG)?\s*[\xA3Ł]?\s*([0-9][0-9,]*(?:\.[0-9]{1,2})?)", str(s), flags=re.I)
    if not m:
        return 0.0
    return _safe_float((m.group(1) or "").replace(",", ""))


def _expense_money_after_label(lines: List[str], label_pattern: str) -> float:
    pat = re.compile(label_pattern, flags=re.I)
    for i, ln in enumerate(lines):
        s = ln or ""
        if not pat.search(s):
            continue
        tail = pat.sub("", s, count=1)
        if "%" in tail:
            nums = re.findall(r"[0-9][0-9,]*(?:\.[0-9]{1,2})?", tail)
            if len(nums) >= 2:
                return _safe_float(nums[-1].replace(",", ""))
        else:
            inline = _expense_money_from_text(tail)
            if inline > 0:
                return inline
        for j in range(i + 1, min(len(lines), i + 8)):
            val = _expense_money_from_text(lines[j] or "")
            if val > 0:
                return val
    return 0.0


def _expense_money_after_exact_line(lines: List[str], exact_text: str) -> float:
    target = (exact_text or "").strip().upper()
    for i, ln in enumerate(lines):
        current = (ln or "").strip()
        current_u = current.upper()
        pos = current_u.find(target)
        if pos >= 0 and current_u != target:
            inline = _expense_money_from_text(current[pos + len(exact_text):])
            if inline > 0:
                return inline
        if current_u != target:
            continue
        for j in range(i + 1, min(len(lines), i + 8)):
            val = _expense_money_from_text(lines[j] or "")
            if val > 0:
                return val
    return 0.0


def _expense_normalise_date(s: str) -> str:
    s = (s or "").strip()
    if not s:
        return ""
    m_any = re.search(r"\b([0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4})\b", s)
    if m_any:
        s = m_any.group(1)
    norm = _normalise_invoice_date_str(s)
    if norm and norm != s:
        return norm
    m = re.match(r"^([0-3]?\d)[/\-]([01]?\d)[/\-](\d{2})$", s)
    if m:
        dd, mm, yy = int(m.group(1)), int(m.group(2)), int(m.group(3))
        yyyy = 2000 + yy if yy < 70 else 1900 + yy
        try:
            return dt.date(yyyy, mm, dd).isoformat()
        except Exception:
            return s
    return norm or s


def _utility_clean_value(s: str) -> str:
    s = _collapse_spaces(str(s or "").replace("|", " ").strip())
    s = re.sub(r"^[\s:;\-#]+", "", s).strip()
    return s


def _dedupe_repeated_party_name(s: str) -> str:
    s = _collapse_spaces(str(s or "").replace("|", " ").strip())
    if not s:
        return ""
    # Collapse exact repeated company/person phrases captured from adjacent OCR blocks.
    pats = [
        r"^(.{3,120}?\b(?:LIMITED|LTD|PLC|LLP)\b)(?:\s+\1){1,}$",
        r"^([A-Z][A-Za-z]+(?:\s+[A-Z][A-Za-z]+){1,5})(?:\s+\1){1,}$",
    ]
    for pat in pats:
        m = re.match(pat, s, flags=re.I)
        if m:
            return _collapse_spaces(m.group(1))
    # If the same long token sequence appears multiple times, keep the first occurrence.
    toks = s.split()
    for size in range(min(8, len(toks) // 2), 1, -1):
        phrase = " ".join(toks[:size])
        if len(phrase) < 12:
            continue
        rebuilt = (" " + s + " ").count(" " + phrase + " ")
        if rebuilt >= 2:
            return phrase
    return s


def _utility_is_label_or_noise(s: str) -> bool:
    u = _collapse_spaces(str(s or "")).upper()
    if not u:
        return True
    noise_bits = (
        "CONTACT US", "QUESTIONS ABOUT YOUR BILL", "WE'RE AVAILABLE",
        "MON TO FRI", "SIDE ", "PAGE ", "THIS IS A VAT INVOICE",
        "VAT REGISTRATION", "YOUR ACCOUNT", "NEW CHARGES", "SINCE YOUR",
    )
    if any(bit in u for bit in noise_bits):
        return True
    if re.fullmatch(r"PAGE(?:\s+\d+)?", u, flags=re.I):
        return True
    label_bits = (
        "BILL DATE", "BILL NUMBER", "INVOICE DATE", "INVOICE NUMBER",
        "ACCOUNT NUMBER", "CUSTOMER NUMBER", "CONTRACT NUMBER",
        "SITE ADDRESS", "SUPPLY ADDRESS", "BILLING PERIOD",
        "TOTAL AMOUNT DUE", "AMOUNT DUE", "TOTAL CHARGES", "VAT",
    )
    return any(re.fullmatch(rf"{re.escape(bit)}\s*:?", u, flags=re.I) for bit in label_bits)


def _utility_find_value(
    lines: List[str],
    label_patterns: List[str],
    *,
    value_pattern: str = "",
    max_next: int = 8,
) -> str:
    compiled = [re.compile(p, flags=re.I) for p in label_patterns]
    val_re = re.compile(value_pattern, flags=re.I) if value_pattern else None
    for i, ln in enumerate(lines):
        s = ln or ""
        for pat in compiled:
            m = pat.search(s)
            if not m:
                continue
            tail = _utility_clean_value(s[m.end():])
            if tail:
                if val_re:
                    mv = val_re.search(tail)
                    if mv:
                        return _utility_clean_value(mv.group(1) if mv.groups() else mv.group(0))
                elif not _utility_is_label_or_noise(tail):
                    return tail
            for j in range(i + 1, min(len(lines), i + 1 + max_next)):
                cand = _utility_clean_value(lines[j] or "")
                if not cand or _utility_is_label_or_noise(cand):
                    continue
                if val_re:
                    mv = val_re.search(cand)
                    if mv:
                        return _utility_clean_value(mv.group(1) if mv.groups() else mv.group(0))
                    continue
                return cand
    return ""


def _utility_money_after_label(lines: List[str], label_patterns: List[str]) -> float:
    for pat in label_patterns:
        val = _expense_money_after_label(lines, pat)
        if val > 0:
            return val
    return 0.0


def _utility_infer_supplier(raw: str, lines: List[str]) -> str:
    up = (raw or "").upper()
    known = [
        ("Biffa Waste Services Limited", ("BIFFA WASTE SERVICES", "BIFFA")),
        ("British Gas Business", ("YOUR BUSINESS ELECTRICITY BILL", "YOUR FIXED PRICE ENERGY PLAN", "ZERO CARBON ELECTRICITY", "0333 009 5778", "684 9667 62")),
        ("EDF Energy", ("EDF ENERGY", "EDF ENERGY CUSTOMERS", "EDF BUSINESS")),
        ("E.ON Next", ("E.ON NEXT", "EON NEXT", "E.ON ENERGY")),
        ("SSE Energy Solutions", ("SSE ENERGY", "SSE BUSINESS", "SSE AIRTRICITY")),
        ("ScottishPower", ("SCOTTISHPOWER", "SCOTTISH POWER")),
        ("Yu Energy", ("YU ENERGY", "YÜ ENERGY")),
        ("Opus Energy", ("OPUS ENERGY",)),
        ("TotalEnergies Gas & Power", ("TOTALENERGIES GAS", "TOTALENERGIES POWER")),
        ("Corona Energy", ("CORONA ENERGY",)),
        ("Water Plus", ("WATER PLUS",)),
        ("Castle Water", ("CASTLE WATER",)),
        ("Thames Water", ("THAMES WATER",)),
        ("BT", (" BT PLC", "BRITISH TELECOMMUNICATIONS", "BT BUSINESS")),
        ("Vodafone", ("VODAFONE",)),
        ("O2", ("O2 BUSINESS", "TELEFONICA UK")),
        ("DPD Local", ("DPD LOCAL", "INVOICE FROM DPD")),
        ("Microsoft", ("MICROSOFT 365", "OFFICE 365", "MICROSOFT INVOICE", "MICROSOFT")),
        ("Vonage UK", ("VONAGE UK", "VONAGE")),
        ("Smart Payment Technologies", ("SMART PAYMENT TECHNOLOGIES", "BILL_VISU")),
        ("Varlink", ("VARLINK",)),
    ]
    for name, needles in known:
        if any(n in up for n in needles):
            return name

    for ln in lines[:50]:
        s = _utility_clean_value(ln)
        if not s or _utility_is_label_or_noise(s):
            continue
        if re.search(r"\b(ENERGY|ELECTRIC|GAS|WATER|WASTE|TELECOM|BROADBAND|UTILITIES|UTILITY)\b", s, flags=re.I):
            return s[:100]
    for ln in lines[:25]:
        s = _utility_clean_value(ln)
        if re.search(r"\b(LIMITED|LTD|PLC)\b", s, flags=re.I) and not re.search(r"\b(FRESH|STORE|SHOP|RETAIL|FOODS?)\b", s, flags=re.I):
            return s[:100]
    return ""


def _utility_extract_address_after_label(lines: List[str], label_patterns: List[str], stop_patterns: List[str], max_lines: int = 8) -> str:
    labels = [re.compile(p, flags=re.I) for p in label_patterns]
    stops = [re.compile(p, flags=re.I) for p in stop_patterns]
    for i, ln in enumerate(lines):
        if not any(p.search(ln or "") for p in labels):
            continue
        first = ""
        for p in labels:
            m = p.search(ln or "")
            if m:
                tail_raw = (ln or "")[m.end():]
                # PDF text extraction often preserves right-column content after a wide gap.
                tail_raw = re.split(r"\s{2,}", tail_raw.strip(), maxsplit=1)[0]
                first = _utility_clean_value(tail_raw)
                break
        out = []
        if first and not _utility_is_label_or_noise(first):
            out.append(first)
        for j in range(i + 1, min(len(lines), i + 1 + max_lines)):
            cand = _utility_clean_value(lines[j] or "")
            if not cand:
                continue
            if any(p.search(cand) for p in stops) or _utility_is_label_or_noise(cand):
                break
            out.append(cand)
        if out:
            return "\n".join(out).strip()
    return ""


def _utility_extract_customer_block(lines: List[str], supplier_name: str) -> Tuple[str, str]:
    stop_re = re.compile(
        r"^(BILL DATE|BILL NUMBER|INVOICE|ACCOUNT NUMBER|CONTACT US|SITE ADDRESS|SUPPLY ADDRESS|BILLING PERIOD|YOUR BUSINESS|YOUR ACCOUNT|TOTAL)\b",
        flags=re.I,
    )
    supplier_u = (supplier_name or "").upper()
    for i, ln in enumerate(lines[:70]):
        s = _utility_clean_value(ln)
        if not s or _utility_is_label_or_noise(s) or (supplier_u and supplier_u in s.upper()):
            continue
        if not re.search(r"\b(LTD|LIMITED|PLC|LLP|RETAIL|SHOP|STORE|FRESH|FOODS?)\b", s, flags=re.I):
            continue
        block = [s]
        for j in range(i + 1, min(len(lines), i + 7)):
            cand = _utility_clean_value(lines[j] or "")
            if not cand or stop_re.search(cand) or _utility_is_label_or_noise(cand):
                break
            if re.search(r"\b(QUESTIONS|AVAILABLE|PHONE|EMAIL|WWW\.|HTTP|MON TO FRI)\b", cand, flags=re.I):
                break
            block.append(cand)
        return block[0], "\n".join(block)
    return "", ""


def _utility_type_from_text(raw: str) -> str:
    up = (raw or "").upper()
    if "ELECTRICITY" in up:
        return "Electricity"
    if re.search(r"\bGAS\b", up):
        return "Gas"
    if "WATER" in up:
        return "Water"
    if "WASTE" in up or "REFUSE" in up:
        return "Waste"
    if "BROADBAND" in up or "TELECOM" in up or "PHONE" in up:
        return "Telecom"
    return "Utilities"


def _parse_dpd_local_header(raw: str) -> Optional[Dict[str, Any]]:
    up = (raw or "").upper()
    if ("DPD LOCAL" not in up) and ("INVOICE FROM DPD" not in up):
        return None

    header: Dict[str, Any] = {
        "supplierName": "DPD Local",
        "customerName": "",
        "companyName": "N/A",
        "tradingName": "",
        "customerNo": "",
        "customerPONumber": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
        "extractionMode": "Utility Header Agent",
        "utilityType": "Courier",
    }

    m_inv = re.search(r"\bInvoice\s+Number[:\s]*([0-9]{5,})\b", raw, flags=re.I)
    if m_inv:
        header["invoiceNumber"] = m_inv.group(1).strip()

    m_acc = re.search(r"\b(?:Overview\s+for\s+)?Account\s+([0-9]{4,})\b", raw, flags=re.I)
    if m_acc:
        account_no = m_acc.group(1).strip()
        header["customerNo"] = account_no
        header["accountNumber"] = account_no

    m_date = re.search(r"\bInvoice\s+Date[:\s]*([0-3]?\d\s+[A-Za-z]{3,9}\s+[0-9]{4})\b", raw, flags=re.I)
    if not m_date:
        m_date = re.search(
            r"\bOverview\s+for\s+Account\s+[0-9]{4,}\s+([0-3]?\d(?:st|nd|rd|th)?\s+[A-Za-z]{3,9}\s+[0-9]{4})\b",
            raw,
            flags=re.I,
        )
    if m_date:
        date_txt = re.sub(r"(?<=\d)(st|nd|rd|th)\b", "", m_date.group(1).strip(), flags=re.I)
        header["invoiceDate"] = _expense_normalise_date(date_txt)

    m_customer = re.search(
        r"\bOverview\s+for\s+Account\s+[0-9]{4,}\s+[0-3]?\d(?:st|nd|rd|th)?\s+[A-Za-z]{3,9}\s+[0-9]{4}\s+(.+?)\s+Your\s+contact\s+is:",
        raw,
        flags=re.I | re.S,
    )
    if m_customer:
        block = [ln.strip() for ln in m_customer.group(1).splitlines() if ln.strip()]
        if block:
            header["customerName"] = block[0]
            if len(block) > 1:
                header["billToAddress"] = "\n".join(block)

    def _dpd_extract_totals(section_text: str) -> Tuple[float, float, float]:
        nums = re.findall(r"(?<!\d)([0-9][0-9,]*\.\d{2})(?!\d)", section_text or "")
        vals = [_safe_float(x.replace(",", "")) for x in nums]
        if len(vals) >= 3:
            net_v, vat_v, gross_v = vals[-3], vals[-2], vals[-1]
            if gross_v >= net_v and gross_v >= vat_v:
                return net_v, vat_v, gross_v
        return 0.0, 0.0, 0.0

    m_vat_analysis = re.search(
        r"\bVAT\s+Analysis\b([\s\S]{0,1200}?)\bThis\s+invoice\s+amount\b",
        raw,
        flags=re.I,
    )
    if m_vat_analysis:
        net_v, vat_v, gross_v = _dpd_extract_totals(m_vat_analysis.group(1))
        if gross_v > 0:
            header["totalNet"] = net_v
            header["totalVat"] = vat_v
            header["totalGross"] = gross_v

    if header["totalGross"] <= 0:
        m_total = re.search(
            r"\bInvoice\s+Total\b([\s\S]{0,500}?)\bStatement\s+of\s+Account\b",
            raw,
            flags=re.I,
        )
        if m_total:
            net_v, vat_v, gross_v = _dpd_extract_totals(m_total.group(1))
            if gross_v > 0:
                header["totalNet"] = net_v
                header["totalVat"] = vat_v
                header["totalGross"] = gross_v

    m_due = re.search(r"\bPayment\s+Due[:\s]*([0-3]?\d\s+[A-Za-z]{3,9}\s+[0-9]{4})\b", raw, flags=re.I)
    if m_due:
        header["paymentDueDate"] = _expense_normalise_date(m_due.group(1).strip())

    m_vrn = re.search(r"\bVat\s+Number[:\s]*([A-Z]{2}\s*[0-9 ]{6,})\b", raw, flags=re.I)
    if m_vrn:
        header["vatRegistrationNumber"] = _utility_clean_value(m_vrn.group(1))

    return {"header": header, "items": []}


def _parse_google_workspace_header(raw: str) -> Optional[Dict[str, Any]]:
    up = (raw or "").upper()
    if ("GOOGLE WORKSPACE" not in up) and ("GOOGLE CLOUD EMEA" not in up):
        return None
    lines = [(ln or "").replace("\xa0", " ").strip() for ln in raw.splitlines()]
    lines = [ln for ln in lines if ln]

    header: Dict[str, Any] = {
        "supplierName": "Google Cloud EMEA Limited",
        "customerName": "",
        "companyName": "N/A",
        "tradingName": "",
        "customerNo": "",
        "customerPONumber": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
        "extractionMode": "Utility Header Agent",
        "utilityType": "Software",
    }

    m_supplier = re.search(r"^\s*(Google Cloud EMEA Limited)\s*$", raw, flags=re.I | re.M)
    if m_supplier:
        header["supplierName"] = _collapse_spaces(m_supplier.group(1))

    m_inv = re.search(r"\bInvoice number:\s*([0-9]{5,})\b", raw, flags=re.I)
    if not m_inv:
        m_inv = re.search(r"\bInvoice number\b[\s.\u2026]*([0-9]{5,})\b", raw, flags=re.I)
    if m_inv:
        header["invoiceNumber"] = m_inv.group(1).strip()

    m_date = re.search(r"\bInvoice date\b[\s.\u2026]*([A-Za-z]{3,9}\s+\d{1,2},\s+\d{4})\b", raw, flags=re.I)
    if m_date:
        date_txt = _collapse_spaces(m_date.group(1))
        for fmt in ("%b %d, %Y", "%B %d, %Y"):
            try:
                header["invoiceDate"] = dt.datetime.strptime(date_txt, fmt).date().isoformat()
                break
            except Exception:
                pass

    m_domain = re.search(r"\bDomain name\b[\s.\u2026]*([A-Za-z0-9.-]+\.[A-Za-z]{2,})\b", raw, flags=re.I)
    if m_domain:
        header["customerName"] = m_domain.group(1).strip()
        header["domainName"] = header["customerName"]

    m_billing = re.search(r"\bBilling ID\b[\s.\u2026]*([0-9-]{8,})\b", raw, flags=re.I)
    if m_billing:
        header["accountNumber"] = m_billing.group(1).strip()
        header["customerNo"] = header["accountNumber"]

    m_bill_to = re.search(
        r"\bBill to\b\s+(.+?)\s+\bDetails\b",
        raw,
        flags=re.I | re.S,
    )
    if m_bill_to:
        block = [ln.strip() for ln in m_bill_to.group(1).splitlines() if ln.strip()]
        if block:
            header["billToAddress"] = "\n".join(block)
            if not header.get("customerName"):
                header["customerName"] = block[0]

    summary_start = 0
    for i, ln in enumerate(lines):
        if re.search(r"^\s*Summary\s+for\b", ln, flags=re.I):
            summary_start = i
            break
    money_lines = lines[summary_start:] if summary_start < len(lines) else lines
    header["totalNet"] = _expense_money_after_exact_line(money_lines, "Subtotal in GBP")
    header["totalVat"] = _expense_money_after_exact_line(money_lines, "VAT (0%)")
    header["totalGross"] = _expense_money_after_exact_line(money_lines, "Total in GBP")

    m_vrn = re.search(r"\bVAT number:\s*([A-Z0-9]+)\b", raw, flags=re.I)
    if m_vrn:
        header["vatRegistrationNumber"] = m_vrn.group(1).strip()

    return {"header": header, "items": []}


def _parse_microsoft_invoice_header(raw: str) -> Optional[Dict[str, Any]]:
    up = (raw or "").upper()
    if ("MICROSOFT" not in up) and ("OFFICE 365" not in up):
        return None

    lines = [(ln or "").replace("\xa0", " ").strip() for ln in raw.splitlines()]
    lines = [ln for ln in lines if ln]

    header: Dict[str, Any] = {
        "supplierName": "Microsoft",
        "customerName": "",
        "companyName": "N/A",
        "tradingName": "",
        "customerNo": "",
        "customerPONumber": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
        "extractionMode": "Utility Header Agent",
        "utilityType": "Software",
    }

    m_inv = re.search(r"\bInvoice Number:\s*([A-Z0-9\-]+)\b", raw, flags=re.I)
    if m_inv:
        header["invoiceNumber"] = m_inv.group(1).strip()

    m_date = re.search(r"\bInvoice Date:\s*([0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4})\b", raw, flags=re.I)
    if m_date:
        header["invoiceDate"] = _expense_normalise_date(m_date.group(1).strip())

    m_due = re.search(r"\bDue Date:\s*([0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4})\b", raw, flags=re.I)
    if m_due:
        header["paymentDueDate"] = _expense_normalise_date(m_due.group(1).strip())

    if not header.get("invoiceNumber"):
        m_bill_no = re.search(r"\bBilling Number\b\s+([A-Z0-9\-]+)\b", raw, flags=re.I)
        if m_bill_no:
            header["invoiceNumber"] = m_bill_no.group(1).strip()

    def _ms_block(start_pat: str, stop_pats: List[str], max_lines: int = 8) -> List[str]:
        start_idx = -1
        for i, ln in enumerate(lines):
            if re.search(start_pat, ln, flags=re.I):
                start_idx = i
                break
        if start_idx < 0:
            return []
        out: List[str] = []
        for j in range(start_idx + 1, min(len(lines), start_idx + 1 + max_lines)):
            cand = (lines[j] or "").strip()
            if not cand:
                continue
            if any(re.search(p, cand, flags=re.I) for p in stop_pats):
                break
            out.append(cand)
        return out

    sold_block = _ms_block(
        r"^\s*Sold[\s\-]*To\s*$",
        [r"^\s*Bill[\s\-]*To\s*$", r"^\s*Service\s+Usage\s+Address\s*$", r"^\s*VAT\s+ID\s*:"],
    )
    if sold_block:
        for ln in sold_block:
            if re.search(r"\b(LIMITED|LTD|PLC|LLP)\b", ln, flags=re.I):
                header["customerName"] = ln
                break
        if not header.get("customerName"):
            header["customerName"] = sold_block[0]
        header["siteAddress"] = "\n".join(sold_block)

    bill_block = _ms_block(
        r"^\s*Bill[\s\-]*To\s*$",
        [r"^\s*Service\s+Usage\s+Address\s*$", r"^\s*VAT\s+ID\s*:", r"^\s*Order\s+Details\s*$"],
    )
    if bill_block:
        header["billToAddress"] = "\n".join(bill_block)
        if not header.get("customerName"):
            for ln in bill_block:
                if re.search(r"\b(LIMITED|LTD|PLC|LLP)\b", ln, flags=re.I):
                    header["customerName"] = ln
                    break
            if not header.get("customerName"):
                header["customerName"] = bill_block[0]

    if not header.get("customerName"):
        m_profile = re.search(r"\bBilling Profile\b\s+(.+?)\s+\bBilling Number\b", raw, flags=re.I | re.S)
        if m_profile:
            block = [ln.strip() for ln in m_profile.group(1).splitlines() if ln.strip()]
            for ln in block:
                if re.search(r"\b(MICROSOFT|VAT\s+REG|READING|THAMES\s+VALLEY|UK)\b", ln, flags=re.I):
                    continue
                header["customerName"] = ln
                break

    if not header.get("customerName"):
        # OCR can lose the Sold-To/Bill-To block boundaries. Fall back to the first
        # customer-like company/person line after the invoice header, while excluding
        # known supplier/address noise.
        start_idx = 0
        for i, ln in enumerate(lines):
            if re.search(r"^\s*(Sold[\s\-]*To|Bill[\s\-]*To|Invoice Date:|Due Date:)\b", ln, flags=re.I):
                start_idx = i
                break
        stop_pats = (
            r"^\s*Service\s+Usage\s+Address\s*$",
            r"^\s*Order\s+Details\s*$",
            r"^\s*VAT\s+ID\s*:",
        )
        for j in range(start_idx, min(len(lines), start_idx + 20)):
            cand = (lines[j] or "").strip().rstrip(",")
            if not cand:
                continue
            if any(re.search(p, cand, flags=re.I) for p in stop_pats):
                break
            if re.search(r"\b(MICROSOFT|VAT\s+REG|READING|THAMES\s+VALLEY|LEOPARDSTOWN|DUBLIN|IRELAND|UK)\b", cand, flags=re.I):
                continue
            if re.search(r"\b(INVOICE|DUE DATE|BILL-TO|BILL TO|SOLD-TO|SOLD TO|ACCOUNT|ORDER DETAILS)\b", cand, flags=re.I):
                continue
            if re.search(r"\b(LIMITED|LTD|PLC|LLP)\b", cand, flags=re.I):
                header["customerName"] = cand
                break
            if not header.get("customerName") and re.search(r"^[A-Z][A-Za-z]+(?:\s+[A-Z][A-Za-z]+){1,4}$", cand):
                header["customerName"] = cand

    if header.get("customerName"):
        header["customerName"] = _dedupe_repeated_party_name(header.get("customerName"))

    m_vat_id = re.search(r"\bVAT ID:\s*([A-Z0-9]+)\b", raw, flags=re.I)
    if m_vat_id:
        header["vatRegistrationNumber"] = m_vat_id.group(1).strip()

    billing_start = 0
    for i, ln in enumerate(lines):
        if re.search(r"^\s*Billing Summary\s*$", ln, flags=re.I):
            billing_start = i
            break
    money_lines = lines[billing_start:] if billing_start < len(lines) else lines

    def _money_after_text(label: str) -> float:
        return _expense_money_after_exact_line(money_lines, label)

    # Page 1 summary block
    charges = _money_after_text("Charges:")
    discounts = _money_after_text("Discounts:")
    credits = _money_after_text("Credits:")
    total_v = _money_after_text("Total:")
    if total_v > 0:
        header["totalGross"] = total_v
        header["totalVat"] = 0.0
        net_v = charges - discounts - credits
        header["totalNet"] = round(net_v if net_v > 0 else total_v, 2)

    # Page 2 fallback
    if header["totalGross"] <= 0:
        subtotal_v = _money_after_text("Subtotal")
        total_v2 = _money_after_text("Total")
        vat_v = _money_after_text("VAT")
        if total_v2 > 0:
            header["totalNet"] = subtotal_v if subtotal_v > 0 else total_v2
            header["totalVat"] = vat_v
            header["totalGross"] = total_v2

    # Azure/Microsoft cloud billing layout:
    # Billing Summary -> Charges / Subtotal / Tax / Total (including Tax)
    if (
        ("TOTAL (INCLUDING TAX)" in up or "TAX AMOUNT" in up)
        and (
            header["totalVat"] <= 0
            or header["totalGross"] <= 0
            or not header.get("customerName")
        )
    ):
        if not header.get("customerName"):
            m_profile2 = re.search(r"\bBilling Profile\b\s+(.+?)\s+\bSold To\b", raw, flags=re.I | re.S)
            if m_profile2:
                block = [ln.strip() for ln in m_profile2.group(1).splitlines() if ln.strip()]
                for ln in block:
                    if re.search(r"\b(MICROSOFT|VAT\s+REG|READING|THAMES\s+VALLEY|UK)\b", ln, flags=re.I):
                        continue
                    header["customerName"] = ln
                    break

        if header["totalNet"] <= 0:
            m_net = re.search(r"\bTotal\s+\(excluding\s+Tax\)\b\s*([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
            if m_net:
                header["totalNet"] = _safe_float(m_net.group(1).replace(",", ""))
        if header["totalNet"] <= 0:
            m_net2 = re.search(r"\bCharges\b\s*([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
            if m_net2:
                header["totalNet"] = _safe_float(m_net2.group(1).replace(",", ""))

        m_vat2 = re.search(r"\bTax\s+Amount\b\s*([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
        if not m_vat2:
            m_vat2 = re.search(r"\bTax\b\s*([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
        if m_vat2:
            header["totalVat"] = _safe_float(m_vat2.group(1).replace(",", ""))

        m_gross2 = re.search(r"\bTotal\s+\(including\s+Tax\)\b\s*(?:GBP\s+)?([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
        if m_gross2:
            header["totalGross"] = _safe_float(m_gross2.group(1).replace(",", ""))

        if header["totalGross"] <= 0 and header["totalNet"] > 0:
            header["totalGross"] = round(header["totalNet"] + header["totalVat"], 2)

    # Final Microsoft guard:
    # If OCR/secondary extraction injects a VAT registration number as tax,
    # trust arithmetic from invoice totals instead.
    if header["totalGross"] > 0 and header["totalNet"] > 0:
        implied_vat = round(float(header["totalGross"]) - float(header["totalNet"]), 2)
        current_vat = _safe_float(header.get("totalVat"))
        if implied_vat >= 0:
            if current_vat <= 0:
                header["totalVat"] = implied_vat
            elif current_vat > (header["totalGross"] * 0.5):
                header["totalVat"] = implied_vat
            elif abs((header["totalNet"] + current_vat) - header["totalGross"]) > 0.05:
                header["totalVat"] = implied_vat

    return {"header": header, "items": []}


def _parse_vonage_invoice_header(raw: str) -> Optional[Dict[str, Any]]:
    up = (raw or "").upper()
    if "VONAGE" not in up:
        return None
    lines = [(ln or "").replace("\xa0", " ").strip() for ln in raw.splitlines()]
    lines = [ln for ln in lines if ln]

    header: Dict[str, Any] = {
        "supplierName": "Vonage UK",
        "customerName": "",
        "companyName": "N/A",
        "tradingName": "",
        "customerNo": "",
        "customerPONumber": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
        "extractionMode": "Utility Header Agent",
        "utilityType": "Telecom",
    }

    m_inv = re.search(r"\bInvoice Number\b\s+([0-9]{4,})\b", raw, flags=re.I)
    if m_inv:
        header["invoiceNumber"] = m_inv.group(1).strip()

    m_date = re.search(r"\bInvoice Date\b\s+([0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4})\b", raw, flags=re.I)
    if m_date:
        header["invoiceDate"] = _expense_normalise_date(m_date.group(1).strip())

    m_acc = re.search(r"\bAccount\b\s+([A-Z0-9\-]{4,})\b", raw, flags=re.I)
    if m_acc:
        header["accountNumber"] = m_acc.group(1).strip()
        header["customerNo"] = header["accountNumber"]

    m_customer = re.search(
        r"\bInvoice Date\b\s+[0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4}\s+Account\b\s+[A-Z0-9\-]{4,}\s+(.+?)\s+Vonage Business Limited",
        raw,
        flags=re.I | re.S,
    )
    if m_customer:
        block = [ln.strip().rstrip(",") for ln in m_customer.group(1).splitlines() if ln.strip()]
        if block:
            header["customerName"] = block[0]
            header["billToAddress"] = "\n".join(block)

    call_v = _expense_money_after_exact_line(lines, "Total Call Charges")
    service_v = _expense_money_after_exact_line(lines, "Total Service Charges")
    if call_v > 0 or service_v > 0:
        header["totalNet"] = round(call_v + service_v, 2)
    if header["totalNet"] <= 0:
        header["totalNet"] = _expense_money_after_exact_line(lines, "Total Charges")

    header["totalVat"] = _expense_money_after_label(lines, r"^\s*VAT\s*\([^)]+\)\s*$")
    header["totalGross"] = _expense_money_after_exact_line(lines, "Total Amount Due")

    if header["totalGross"] > 0 and header["totalNet"] > 0:
        implied_vat = round(float(header["totalGross"]) - float(header["totalNet"]), 2)
        if header["totalVat"] <= 0 or abs((header["totalNet"] + header["totalVat"]) - header["totalGross"]) > 0.05:
            header["totalVat"] = implied_vat
    if header["totalGross"] <= 0 and header["totalNet"] > 0:
        header["totalGross"] = round(float(header["totalNet"]) + float(header["totalVat"]), 2)

    m_vrn = re.search(r"\bVAT number:\s*([A-Z]{2}\s*[0-9 ]{6,})", raw, flags=re.I)
    if m_vrn:
        header["vatRegistrationNumber"] = _utility_clean_value(m_vrn.group(1))

    return {"header": header, "items": []}


def _parse_smart_payment_invoice_header(raw: str) -> Optional[Dict[str, Any]]:
    up = (raw or "").upper()
    if ("SMART PAYMENT TECHNOLOGIES" not in up) and ("BILL_VISU" not in up):
        return None

    header: Dict[str, Any] = {
        "supplierName": "Smart Payment Technologies",
        "customerName": "",
        "companyName": "N/A",
        "tradingName": "",
        "customerNo": "",
        "customerPONumber": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
        "extractionMode": "Utility Header Agent",
        "utilityType": "Software",
    }

    m_customer = re.search(
        r"\bInvoice\b\s+([A-Z][A-Z\s&.,\-]{5,})\s+ENDEAVOUR HOUSE",
        raw,
        flags=re.I,
    )
    if m_customer:
        header["customerName"] = _collapse_spaces(m_customer.group(1)).strip(" ,")

    m_inv = re.search(r"\bInvoice\s+No\.\s*:\s*[\r\n]+(?:.*[\r\n]+){0,8}?(\d{8})\b", raw, flags=re.I)
    if not m_inv:
        m_inv = re.search(r"(?m)^\s*(\d{8})\s*$", raw)
    if m_inv:
        header["invoiceNumber"] = m_inv.group(1).strip()
    if not header.get("invoiceNumber"):
        nums8 = re.findall(r"\b(\d{8})\b", raw)
        if nums8:
            try:
                from collections import Counter
                common_num, common_count = Counter(nums8).most_common(1)[0]
                if common_count >= 2:
                    header["invoiceNumber"] = common_num.strip()
            except Exception:
                pass

    m_date = re.search(r"(?m)^\s*(30\/09\/2025|[0-3]?\d\/[01]?\d\/20\d{2})\s*$", raw)
    if m_date:
        header["invoiceDate"] = _expense_normalise_date(m_date.group(1).strip())

    m_acc = re.search(r"\bCustomer Ref\b[\s\S]{0,200}?([A-Z0-9][A-Z0-9 _&.\-]{3,40})\s+Description\b", raw, flags=re.I)
    if m_acc:
        header["accountNumber"] = _collapse_spaces(m_acc.group(1)).strip(" ,")
        header["customerNo"] = header["accountNumber"]

    # Prefer the summary footer page with explicit totals.
    m_net = re.search(r"\bSub\s*Total\b\s*([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
    m_vat = re.search(r"\bVAT\s*\(20\.00%\)\b\s*([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
    m_gross = re.search(r"\bTotal\s+GBP\b\s*([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
    if m_net:
        header["totalNet"] = _safe_float(m_net.group(1).replace(",", ""))
    if m_vat:
        header["totalVat"] = _safe_float(m_vat.group(1).replace(",", ""))
    if m_gross:
        header["totalGross"] = _safe_float(m_gross.group(1).replace(",", ""))

    if header["totalGross"] > 0 and header["totalNet"] > 0:
        implied_vat = round(float(header["totalGross"]) - float(header["totalNet"]), 2)
        if header["totalVat"] <= 0 or abs((header["totalNet"] + header["totalVat"]) - header["totalGross"]) > 0.05:
            header["totalVat"] = implied_vat
    if header["totalGross"] <= 0 and header["totalNet"] > 0:
        header["totalGross"] = round(float(header["totalNet"]) + float(header["totalVat"]), 2)

    m_vrn = re.search(r"\bVAT\s+No\s*:\s*([0-9]{6,})\b", raw, flags=re.I)
    if m_vrn:
        header["vatRegistrationNumber"] = m_vrn.group(1).strip()

    return {"header": header, "items": []}


def _parse_expense_utility_bill(txt: str) -> Dict[str, Any]:
    """
    Local expense/utility bill parser.

    Handles utility bill header/totals from the PDF text layer.
    Expense/utility bills are intentionally header-only; do not create
    synthetic line rows from totals or service descriptions.
    """
    raw = _strip_page_markers(txt or "")
    lines = [(ln or "").replace("\xa0", " ").strip() for ln in raw.splitlines()]
    lines = [ln for ln in lines if ln]
    up = raw.upper()

    dpd_fast = _parse_dpd_local_header(raw)
    if dpd_fast is not None:
        return dpd_fast

    google_fast = _parse_google_workspace_header(raw)
    if google_fast is not None:
        return google_fast

    microsoft_fast = _parse_microsoft_invoice_header(raw)
    if microsoft_fast is not None:
        return microsoft_fast

    vonage_fast = _parse_vonage_invoice_header(raw)
    if vonage_fast is not None:
        return vonage_fast

    smartpay_fast = _parse_smart_payment_invoice_header(raw)
    if smartpay_fast is not None:
        return smartpay_fast

    header: Dict[str, Any] = {
        "supplierName": "",
        "customerName": "",
        "companyName": "N/A",
        "tradingName": "",
        "customerNo": "",
        "customerPONumber": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
    }

    header["extractionMode"] = "Utility Header Agent"
    header["utilityType"] = _utility_type_from_text(raw)

    header["invoiceNumber"] = _utility_find_value(
        lines,
        [
            r"\b(?:Invoice|Bill|Statement)\s*(?:Number|No\.?|#)\b",
            r"\b(?:Invoice|Bill|Statement)\s*Ref(?:erence)?\b",
            r"\bDocument\s*(?:Number|No\.?)\b",
        ],
        value_pattern=r"([A-Z0-9\-\/]*\d[A-Z0-9\-\/]{3,})",
    )
    header["invoiceDate"] = _expense_normalise_date(
        _utility_find_value(
            lines,
            [
                r"\b(?:Invoice|Bill|Statement)\s*Date\b",
                r"\bDate\s+of\s+(?:Invoice|Bill|Issue)\b",
                r"\bIssue\s*Date\b",
                r"\bTax\s*Point\b",
            ],
            value_pattern=r"([0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4}|[0-3]?\d\s+[A-Za-z]{3,9}\s+[0-9]{2,4})",
        )
    )
    account_no = _utility_find_value(
        lines,
        [
            r"\bAccount\s*(?:Number|No\.?|#)\b",
            r"\bCustomer\s*(?:Number|No\.?|Ref(?:erence)?)\b",
            r"\bClient\s*(?:Number|No\.?|Ref(?:erence)?)\b",
        ],
        value_pattern=r"([A-Z0-9\*\/\-]*\d[A-Z0-9\*\/\-]{3,})",
    )
    contract_no = _utility_find_value(
        lines,
        [r"\bContract\s*(?:Number|No\.?|#)\b", r"\bAgreement\s*(?:Number|No\.?|#)\b"],
        value_pattern=r"([A-Z0-9][A-Z0-9\-\/]{3,})",
    )

    if not header["invoiceNumber"]:
        m = re.search(r"\b(?:Invoice|Bill|Statement)\s+(?:Number|No\.?|#)\b[\s\S]{0,160}?\b([A-Z0-9\-\/]*\d[A-Z0-9\-\/]{4,})\b", raw, flags=re.I)
        if m:
            header["invoiceNumber"] = m.group(1).strip()
    if not header["invoiceNumber"]:
        for pat in (
            r"\bInvoice\s+([A-Z0-9\-\/]*\d[A-Z0-9\-\/]{4,})\s+from\b",
            r"\b(?:Microsoft\s+)?invoice\s+([A-Z0-9\-\/]*\d[A-Z0-9\-\/]{4,})\s+is\s+ready\b",
            r"\b(INV-[A-Z0-9\-\/]*\d[A-Z0-9\-\/]{3,})\b",
        ):
            m = re.search(pat, raw, flags=re.I)
            if m:
                header["invoiceNumber"] = m.group(1).strip()
                break
    if not header["invoiceDate"]:
        m = re.search(r"\b(?:Invoice|Bill|Statement)\s+Date\b[\s\S]{0,180}?\b([0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4}|[0-3]?\d\s+[A-Za-z]{3,9}\s+[0-9]{2,4})\b", raw, flags=re.I)
        if m:
            header["invoiceDate"] = _expense_normalise_date(m.group(1).strip())
    if not account_no:
        m = re.search(r"\bAccount\s+Number\b[\s\S]{0,180}?\b([A-Z][A-Z0-9*\/\-]{4,})\b", raw, flags=re.I)
        if m:
            account_no = m.group(1).strip()
    if not contract_no:
        m = re.search(r"\bContract\s+Number\b[\s\S]{0,100}?\b([0-9]{4,})\b", raw, flags=re.I)
        if m:
            contract_no = m.group(1).strip()
    if account_no:
        header["customerNo"] = account_no
        header["accountNumber"] = account_no
    if contract_no:
        header["contractNumber"] = contract_no

    header["supplierName"] = _utility_infer_supplier(raw, lines)

    # Customer and address blocks vary widely across utilities.
    try:
        bill_to = _utility_extract_address_after_label(
            lines,
            [r"\b(?:Bill\s*To|Invoice\s*To|Customer\s*Address|Billing\s*Address)\b"],
            [r"\b(?:Invoice|Bill|Statement)\s*(?:Date|Number)\b", r"\bAccount\s*(?:Number|No)\b", r"\bSite\s*Address\b", r"\bSupply\s*Address\b", r"\bTotal\b"],
        )
        if bill_to:
            header["billToAddress"] = bill_to
            header["customerName"] = bill_to.splitlines()[0].strip()
        if not header.get("customerName"):
            cust_name, cust_block = _utility_extract_customer_block(lines, header.get("supplierName") or "")
            if cust_name:
                header["customerName"] = cust_name
                header["billToAddress"] = cust_block
    except Exception:
        pass

    try:
        site_addr = _utility_extract_address_after_label(
            lines,
            [r"\b(?:Site|Supply|Service|Premises|Meter)\s*Address\b"],
            [r"\bBilling\s*Period\b", r"\bBill\s*Period\b", r"\bYour\s*Account\b", r"\bContract\s*(?:Number|No)\b", r"\b(?:ESTIMATED\s+)?READING\b", r"\bGO\s+ONLINE\b", r"\bYour\s+Fixed\b", r"\bTotal\b"],
            max_lines=5,
        )
        if site_addr:
            header["siteAddress"] = site_addr
            if not header.get("customerName"):
                header["customerName"] = site_addr.splitlines()[0].strip()
    except Exception:
        pass

    vat_rate = 0.0
    m_vr = re.search(r"\bVAT\s*@\s*([0-9]+(?:\.[0-9]+)?)\s*%", raw, flags=re.I)
    if m_vr:
        vat_rate = _safe_float(m_vr.group(1))

    # Prefer explicit totals labels and strip registration-number lines so "VAT Reg No" is never read as a money value.
    totals_raw = re.sub(r"(?im)^.*\bVAT\s+REG(?:ISTRATION)?\b.*$", "", raw)
    totals_raw = re.sub(r"(?im)^.*\bCO\.?\s+REG\b.*$", "", totals_raw)
    m_total_net = re.search(
        r"\b(?:SUB[\s\-]*TOTAL|TOTAL\s+NET|TOTAL\s+EX(?:C|CL|CLUDING)?\s+VAT|NET\s+TOTAL|TOTAL\s+BEFORE\s+VAT)\b\s*[:\-]?\s*[^\d\r\n]{0,8}\s*([0-9][0-9,]*\.\d{2})",
        totals_raw,
        flags=re.I,
    )
    m_total_vat = re.search(
        r"\b(?:TOTAL\s+VAT|VAT\s+TOTAL)\b\s*[:\-]?\s*[^\d\r\n]{0,8}\s*([0-9][0-9,]*\.\d{2})",
        totals_raw,
        flags=re.I,
    )
    m_total_gross = re.search(
        r"\b(?:INVOICE\s+TOTAL|TOTAL\s+AMOUNT\s+DUE|AMOUNT\s+DUE|BALANCE\s+DUE|TOTAL\s+PAYABLE|TOTAL\s+(?:NEW\s+CHARGES\s+THIS\s+BILL\s+)?(?:INC|INCL|INCLUDING)\s+VAT)\b\s*[:\-]?\s*[^\d\r\n]{0,8}\s*([0-9][0-9,]*\.\d{2})",
        totals_raw,
        flags=re.I,
    )

    header["totalNet"] = _safe_float(m_total_net.group(1).replace(",", "")) if m_total_net else _utility_money_after_label(
        lines,
        [
            r"^\s*Total\s+(?:charges\s+)?(?:exc|excl|excluding)\s+VAT\b",
            r"^\s*(?:Net|Subtotal|Sub\s*Total)\b",
            r"^\s*Total\s+before\s+VAT\b",
            r"^\s*Total\s+net\b",
        ],
    )
    header["totalVat"] = _safe_float(m_total_vat.group(1).replace(",", "")) if m_total_vat else _utility_money_after_label(
        lines,
        [
            r"^\s*Total\s+VAT\b",
            r"^\s*VAT\b(?!\s+(?:registration|reg(?:\b|\.)))",
            r"^\s*VAT\s*@",
        ],
    )
    header["totalGross"] = _safe_float(m_total_gross.group(1).replace(",", "")) if m_total_gross else _utility_money_after_label(
        lines,
        [
            r"^\s*Total\s+amount\s+due\b",
            r"^\s*Amount\s+due\b",
            r"^\s*Balance\s+due\b",
            r"^\s*Invoice\s+Total\b",
            r"^\s*Total\s+(?:new\s+charges\s+this\s+bill\s+)?(?:inc|incl|including)\s+VAT\b",
            r"^\s*Total\s+payable\b",
        ],
    )
    if header["totalGross"] <= 0:
        header["totalGross"] = _utility_money_after_label(lines, [r"^\s*Total\b"])
    if header["totalGross"] <= 0 and (header["totalNet"] > 0 or header["totalVat"] > 0):
        header["totalGross"] = round(_safe_float(header.get("totalNet")) + _safe_float(header.get("totalVat")), 2)

    period = ""
    for ln in lines:
        m_period_line = re.search(
            r"(?:TRADE\s+WASTE\s+SERVICE\s+FOR\s+PERIOD|Billing\s+period|Bill\s+period|Supply\s+period|Charging\s+period|Service\s+period)\s*:?\s*(.+)$",
            ln or "",
            flags=re.I,
        )
        if not m_period_line:
            continue
        tail = re.split(r"\s{2,}", m_period_line.group(1).strip(), maxsplit=1)[0]
        m_dates = re.search(
            r"([0-3]?\d(?:[\/.\-][01]?\d[\/.\-][0-9]{2,4}|\s+[A-Za-z]{3,9}\s+[0-9]{2,4})\s+to\s+[0-3]?\d(?:[\/.\-][01]?\d[\/.\-][0-9]{2,4}|\s+[A-Za-z]{3,9}\s+[0-9]{2,4}))",
            tail,
            flags=re.I,
        )
        period = _collapse_spaces(m_dates.group(1) if m_dates else tail)
        if period:
            header["servicePeriod"] = period
            break
    if not period:
        m_period = re.search(
            r"(?:TRADE\s+WASTE\s+SERVICE\s+FOR\s+PERIOD|Billing\s+period|Bill\s+period|Supply\s+period|Charging\s+period|Service\s+period)\s*:?\s*([0-9A-Za-z/.\- ]+\s+to\s+[0-9A-Za-z/.\- ]+(?:\s+\([^)]+\))?)",
            raw,
            flags=re.I,
        )
        if m_period:
            period = _collapse_spaces(m_period.group(1))
            header["servicePeriod"] = period

    m_due = re.search(
        r"Payment\s+of\s+this\s+invoice\s+will\s+be\s+collected\s+by\s+Direct\s+Debit\s+on\s+or\s+just\s+after\s+([0-9]{1,2}\s+[A-Za-z]+\s+[0-9]{4})",
        raw,
        flags=re.I,
    )
    if m_due:
        header["paymentDueText"] = _collapse_spaces(m_due.group(0))
        header["paymentDueDate"] = _expense_normalise_date(m_due.group(1))

    if not header.get("paymentDueDate"):
        m_due2 = re.search(r"\b(?:Direct\s+Debit\s+on\s+or\s+immediately\s+after|Due\s+date|Payment\s+due\s+date)\b[\s\S]{0,80}?([0-3]?\d\s+[A-Za-z]{3,9}\s+[0-9]{4}|[0-3]?\d[\/\-][01]?\d[\/\-][0-9]{2,4})", raw, flags=re.I)
        if m_due2:
            header["paymentDueDate"] = _expense_normalise_date(m_due2.group(1))

    for key, pats in {
        "mpan": [r"\bMPAN\b[\s:;\-#]*([0-9 ]{8,30})"],
        "mprn": [r"\bMPRN\b[\s:;\-#]*([0-9]{6,12})"],
        "meterNumber": [r"\bMeter\s*(?:Number|No\.?|Serial)\b[\s:;\-#]*([A-Z0-9\-\/]{4,})"],
        "vatRegistrationNumber": [r"\bVAT\s+registration\s+number\b[\s:;\-#]*([0-9 ]{6,20})"],
    }.items():
        for pat in pats:
            m = re.search(pat, raw, flags=re.I)
            if m:
                header[key] = _utility_clean_value(m.group(1))
                break

    return {"header": header, "items": []}


def _looks_like_retail_receipt(txt: str) -> bool:
    up = (txt or "").upper()
    strong_hits = 0
    for needle in ("RECEIPT:", "TILL:", "AMOUNT DUE", "TOTAL TENDERED", "CARDHOLDER COPY", "PIN VERIFIED"):
        if needle in up:
            strong_hits += 1
    if strong_hits >= 3:
        return True
    if ("CURRYS" in up) and ("RECEIPT:" in up or "AMOUNT DUE" in up):
        return True
    return False


def _parse_retail_receipt(txt: str) -> Dict[str, Any]:
    raw = _strip_page_markers(txt or "")
    lines = [(ln or "").replace("\xa0", " ").strip() for ln in raw.splitlines()]
    lines = [ln for ln in lines if ln]
    up = raw.upper()

    header: Dict[str, Any] = {
        "supplierName": "",
        "customerName": "",
        "companyName": "N/A",
        "tradingName": "",
        "customerNo": "",
        "customerPONumber": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
        "extractionMode": "Retail Receipt Local",
    }
    items: List[Dict[str, Any]] = []

    if "CURRYS" in up:
        header["supplierName"] = "Currys"
    else:
        for ln in lines[:8]:
            if re.search(r"\b(LIMITED|LTD|PLC|CURRYS|TESCO|ASDA|SAINSBURY|MORRISONS)\b", ln, flags=re.I):
                header["supplierName"] = ln[:80]
                break
        if not header["supplierName"] and lines:
            header["supplierName"] = lines[0][:80]

    m_inv = re.search(r"\bReceipt\s*:\s*([A-Z0-9\-]{4,})\b", raw, flags=re.I)
    if m_inv:
        header["invoiceNumber"] = m_inv.group(1).strip()

    m_date = re.search(r"\bDate\s*:\s*([0-3]?\d/[01]?\d/\d{2,4})\b", raw, flags=re.I)
    if m_date:
        header["invoiceDate"] = _expense_normalise_date(m_date.group(1).strip())

    m_gross = re.search(r"\bAMOUNT\s+DUE\b[^\d\r\n]{0,12}([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
    if not m_gross:
        m_gross = re.search(r"\bTOTAL\s+TENDERED\b[^\d\r\n]{0,12}([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
    if m_gross:
        header["totalGross"] = _safe_float(m_gross.group(1).replace(",", ""))

    m_acc = re.search(r"\bCurrys\s+flexpay\s+account\b[^\d\r\n]{0,12}([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
    if m_acc:
        header["accountNumber"] = "Currys flexpay"
        header["paymentFlexpayAmount"] = _safe_float(m_acc.group(1).replace(",", ""))

    m_card = re.search(r"\bAMERICAN\s+EXPRESS\b[\s\S]{0,120}?\bAMOUNT\b[^\d\r\n]{0,12}([0-9][0-9,]*\.\d{2})", raw, flags=re.I)
    if m_card:
        header["paymentCardType"] = "American Express"
        header["paymentCardAmount"] = _safe_float(m_card.group(1).replace(",", ""))

    sale_start = None
    sale_end = None
    for i, ln in enumerate(lines):
        if sale_start is None and re.fullmatch(r"SALE", ln, flags=re.I):
            sale_start = i + 1
            continue
        if sale_start is not None and ("AMOUNT DUE" in ln.upper()):
            sale_end = i
            break
    if sale_start is None:
        sale_start = 0
    if sale_end is None:
        sale_end = len(lines)

    sale_lines = lines[sale_start:sale_end]
    skip_prefixes = (
        "ASSISTANT:", "OPERATOR:", "TILL:", "RECEIPT:", "DATE:", "TIME:",
        "THANKS FOR SHOPPING", "NEED SOME EXTRA HELP", "VISIT:", "WWW.",
    )
    i = 0
    while i < len(sale_lines):
        ln = sale_lines[i]
        up_ln = ln.upper()
        if not ln or any(up_ln.startswith(p) for p in skip_prefixes):
            i += 1
            continue

        m_item = re.match(r"^(.+?)\s+(-?\s*[£Ł]?\s*[0-9][0-9,]*\.\d{2})$", ln)
        if not m_item:
            i += 1
            continue

        desc = _collapse_spaces(m_item.group(1)).strip(" -")
        amt_txt = re.sub(r"[£Ł\s]", "", m_item.group(2))
        amt = _safe_float(amt_txt.replace(",", ""))
        qty = 1.0
        unit_price = abs(amt)
        code = ""

        if i + 1 < len(sale_lines):
            nxt = sale_lines[i + 1]
            m_qty = re.search(r"^\s*([0-9]+(?:\.[0-9]+)?)\s*x\s+([0-9]{6,})?\s*@\s*[£Ł]?\s*([0-9][0-9,]*\.\d{2})", nxt, flags=re.I)
            if m_qty:
                qty = _safe_float(m_qty.group(1), 1.0)
                code = str(m_qty.group(2) or "").strip()
                unit_price = _safe_float(m_qty.group(3).replace(",", ""))
                i += 1

        if desc.upper() in ("SALE",) or re.fullmatch(r"[0-9.:/ ]+", desc):
            i += 1
            continue

        items.append({
            "lineNo": None,
            "code": code,
            "description": desc,
            "casePack": 1,
            "unitSize": "",
            "qty": qty,
            "totalUnits": qty,
            "unitPrice": unit_price,
            # Retail receipts often do not expose a VAT split. Keep net/vat neutral and preserve the printed gross line.
            "lineNet": 0.0,
            "vatCode": "",
            "vatRate": 0.0,
            "vatAmount": 0.0,
            "lineGross": amt,
            "isVoid": False,
        })
        i += 1

    return {"header": header, "items": items}


def _looks_like_af_blakemore_invoice(text: str) -> bool:
    """Detect A F Blakemore / SPAR wholesale purchase invoices."""
    up = str(text or "").upper()
    supplier_hit = "A F BLAKEMORE" in up or "AF BLAKEMORE" in up
    layout_hit = "INVOICE NO." in up and "TAX POINT DATE" in up and "TOTAL NETT GOODS FOR RESALE" in up
    return bool(supplier_hit and layout_hit)


def _parse_af_blakemore_purchase_invoice(txt: str) -> Dict[str, Any]:
    """Parse A F Blakemore SPAR invoices from their column-preserving PDF text layer."""
    text = str(txt or "")
    lines = text.splitlines()
    header: Dict[str, Any] = {
        "supplierName": "A F Blakemore & Son Ltd",
        "customerName": "",
        "invoiceNumber": "",
        "invoiceDate": "",
        "currency": "GBP",
        "totalNet": 0.0,
        "totalVat": 0.0,
        "totalGross": 0.0,
    }

    m = re.search(r"(?im)^\s*TO\s+(.+?)\s+FROM\s+A\s*F\s+BLAKEMORE\b", text)
    if m:
        header["customerName"] = re.sub(r"\s+", " ", m.group(1)).strip(" -")
    m = re.search(r"\bINVOICE\s+NO\.?\s*[:#]?\s*(\d{5,12})\b", text, flags=re.I)
    if m:
        header["invoiceNumber"] = m.group(1)
    m = re.search(r"\bTAX\s+POINT\s+DATE\s*[:#]?\s*(\d{1,2}/\d{1,2}/\d{4})\b", text, flags=re.I)
    if m:
        header["invoiceDate"] = _normalise_invoice_date_str(m.group(1))
    m = re.search(r"\bACCOUNT\s+NO\.?\s*[:#]?\s*([A-Z0-9-]+)", text, flags=re.I)
    if m:
        header["accountNumber"] = m.group(1).strip()
    m = re.search(r"\bDELIVERY\s+(\d{2,10})\b", text, flags=re.I)
    if m:
        header["deliveryNumber"] = m.group(1)

    to_pay = 0.0
    m = re.search(r"\bTO\s+PAY\s+([\d,]+\.\d{2})\b", text, flags=re.I)
    if m:
        to_pay = _safe_float(m.group(1).replace(",", ""))
        header["totalGross"] = to_pay

    # Footer TOTAL rows also contain a separate analysis block. Truncate at the
    # first printed TO PAY value before reading net, VAT and gross.
    for raw in lines:
        if not re.match(r"^\s*TOTAL\s+", raw, flags=re.I):
            continue
        main = raw
        if to_pay > 0:
            gross_token = f"{to_pay:,.2f}"
            pos = main.find(gross_token)
            if pos >= 0:
                main = main[: pos + len(gross_token)]
        nums = [_safe_float(v.replace(",", "")) for v in re.findall(r"-?[\d,]+\.\d{2}", main)]
        if len(nums) >= 4:
            header["totalNet"] = float(nums[-3])
            header["totalVat"] = float(nums[-2])
            header["totalGross"] = float(nums[-1])
            break

    vat_rates = {"A": 0.0, "B": 20.0, "R": 5.0, "Z": 0.0}
    current_department = ""
    current_department_code = ""
    items: List[Dict[str, Any]] = []
    seen_rows = set()
    row_re = re.compile(
        r"^\s*(?P<code>\d{4,7})\s+(?P<body>.+?)\s+"
        r"(?P<value>-?[\d,]+\.\d{2})\s+(?P<vat>[A-Z])(?:\s+(?P<tail>.*))?$",
        flags=re.I,
    )
    left_re = re.compile(
        r"^(?P<desc>.+?)\s+"
        r"(?P<size>\d+(?:\.\d+)?\s*[Xx]\s*[A-Z0-9.\u2019'/]+)\s+"
        r"(?P<nums>\d+(?:\s+\d+)?)$",
        flags=re.I,
    )

    for raw in lines:
        line = re.sub(r"\s+", " ", str(raw or "").replace("\xa0", " ")).strip()
        if not line:
            continue
        cg = re.match(r"^C\.\s*G\.\s*(\d{1,4})\s+(.+?)\s*$", line, flags=re.I)
        if cg:
            current_department_code = cg.group(1)
            current_department = re.sub(r"\s+", " ", cg.group(2)).strip(" -")
            continue

        # Retain unavailable products for audit without treating them as delivered
        # stock or including them in financial reconciliation.
        unavailable = re.match(
            r"^(?P<code>\d{4,7})\s+(?P<body>.+?)\s+WE\s+REGRET\s*-\s*NOT\s+AVAILABLE\s*$",
            line,
            flags=re.I,
        )
        if unavailable:
            left = left_re.match(unavailable.group("body"))
            if left:
                code = unavailable.group("code")
                description = re.sub(r"\s+", " ", left.group("desc")).strip(" -")
                size_text = re.sub(r"\s+", "", left.group("size")).upper()
                size_parts = re.split(r"[Xx]", size_text, maxsplit=1)
                outer_pack = int(_safe_float(size_parts[0])) if size_parts and _safe_float(size_parts[0]) > 0 else 1
                unit_size = size_parts[1] if len(size_parts) > 1 else size_text
                number_parts = [int(v) for v in re.findall(r"\d+", left.group("nums"))]
                if len(number_parts) >= 2:
                    case_pack, ordered_qty = number_parts[-2], number_parts[-1]
                else:
                    case_pack = outer_pack
                    ordered_qty = number_parts[-1] if number_parts else 0
                row_key = (code, description, 0, 0.0, current_department_code)
                if row_key not in seen_rows:
                    seen_rows.add(row_key)
                    items.append(
                        {
                            "lineNo": len(items) + 1,
                            "code": code,
                            "description": description,
                            "department": current_department,
                            "departmentCode": current_department_code,
                            "casePack": int(case_pack or 0),
                            "unitSize": unit_size,
                            "orderedQty": float(ordered_qty or 0),
                            "qty": 0.0,
                            "totalUnits": 0.0,
                            "unitPrice": 0.0,
                            "lineNet": 0.0,
                            "vatCode": "",
                            "vatRate": 0.0,
                            "vatAmount": 0.0,
                            "lineGross": 0.0,
                            "stdRrp": 0.0,
                            "por": 0.0,
                            "isVoid": True,
                            "voidNote": "WE REGRET - NOT AVAILABLE",
                            "rowTag": "NOT AVAILABLE",
                            "rawRow": line,
                            "raw": line,
                        }
                    )
            continue

        row_match = row_re.match(line)
        if not row_match:
            continue
        # Blakemore prints an asterisk between QTY and VALUE for security
        # controlled products (for example tobacco and vaping lines).  It is a
        # row marker, not part of the quantity, so remove it before parsing the
        # PACK/QTY portion of the row.
        row_body = re.sub(r"\s+\*\s*$", "", row_match.group("body") or "")
        left = left_re.match(row_body)
        if not left:
            continue

        code = row_match.group("code")
        description = re.sub(r"\s+", " ", left.group("desc")).strip(" -")
        size_text = re.sub(r"\s+", "", left.group("size")).upper()
        size_parts = re.split(r"[Xx]", size_text, maxsplit=1)
        outer_pack = int(_safe_float(size_parts[0])) if size_parts and _safe_float(size_parts[0]) > 0 else 1
        unit_size = size_parts[1] if len(size_parts) > 1 else size_text
        number_parts = [int(v) for v in re.findall(r"\d+", left.group("nums"))]
        if len(number_parts) >= 2:
            case_pack, qty = number_parts[-2], number_parts[-1]
        else:
            case_pack = outer_pack
            qty = number_parts[-1] if number_parts else 0

        line_net = _safe_float(row_match.group("value").replace(",", ""))
        vat_code = row_match.group("vat").upper()
        vat_rate = float(vat_rates.get(vat_code, 0.0))
        vat_amount = round(line_net * vat_rate / 100.0, 2) if vat_rate else 0.0
        tail_values = [
            _safe_float(v.replace(",", ""))
            for v in re.findall(r"-?[\d,]+\.\d{2}", row_match.group("tail") or "")
        ]
        unit_price = tail_values[0] if tail_values else (round(line_net / qty, 4) if qty else line_net)
        std_rrp = tail_values[1] if len(tail_values) > 1 else 0.0
        row_key = (code, description, qty, round(line_net, 2), current_department_code)
        if row_key in seen_rows:
            continue
        seen_rows.add(row_key)
        items.append(
            {
                "lineNo": len(items) + 1,
                "code": code,
                "description": description,
                "department": current_department,
                "departmentCode": current_department_code,
                "casePack": int(case_pack or 0),
                "unitSize": unit_size,
                "qty": float(qty or 0),
                "totalUnits": float((case_pack or 0) * (qty or 0)),
                "unitPrice": float(unit_price or 0.0),
                "lineNet": float(line_net),
                "vatCode": vat_code,
                "vatRate": vat_rate,
                "vatAmount": float(vat_amount),
                "lineGross": float(round(line_net + vat_amount, 2)),
                "stdRrp": float(std_rrp or 0.0),
                "por": 0.0,
                "isVoid": False,
                "rawRow": line,
                "raw": line,
            }
        )

    vat_groups: Dict[str, float] = {}
    for item in items:
        code = str(item.get("vatCode") or "").upper()
        vat_groups[code] = vat_groups.get(code, 0.0) + _safe_float(item.get("lineNet"))
    header["vatBreakdown"] = [
        {
            "vatCode": code,
            "goodsAmount": round(net, 2),
            "vatAmount": round(net * vat_rates.get(code, 0.0) / 100.0, 2),
        }
        for code, net in sorted(vat_groups.items())
    ]
    if items and _safe_float(header.get("totalNet")) <= 0:
        header["totalNet"] = round(sum(_safe_float(it.get("lineNet")) for it in items), 2)
    if items and _safe_float(header.get("totalVat")) <= 0:
        header["totalVat"] = round(sum(_safe_float(row.get("vatAmount")) for row in header["vatBreakdown"]), 2)
    if _safe_float(header.get("totalGross")) <= 0 and _safe_float(header.get("totalNet")) > 0:
        header["totalGross"] = round(_safe_float(header.get("totalNet")) + _safe_float(header.get("totalVat")), 2)
    return {"header": header, "items": items}


class LocalInvoiceParser:
    @staticmethod
    def parse(doc_text: str, doc_type: str) -> Dict[str, Any]:
        txt = _strip_page_markers(doc_text or "")
        up = txt.upper()

        header: Dict[str, Any] = {
            "supplierName": "",
            "customerName": "",
            "companyName": "N/A",
            "tradingName": "",
            "customerNo": "",
            "customerPONumber": "",
            "invoiceNumber": "",
            "invoiceDate": "",
            "currency": "GBP",
            "totalNet": 0.0,
            "totalVat": 0.0,
            "totalGross": 0.0,
        }
        items: List[Dict[str, Any]] = []

        # A F Blakemore / SPAR purchase invoice: use the strong PDF text layer.
        if _is_purchase_like_doc_type(doc_type) and _looks_like_af_blakemore_invoice(txt):
            try:
                return _parse_af_blakemore_purchase_invoice(txt)
            except Exception:
                pass

        # Supplier hints (Local OCR): improve supplierName stability for template matching.
        if _looks_like_dhamecha_invoice(txt):
            header["supplierName"] = "Dhamecha Foods Limited"


        # Dhamecha purchase invoice: parse lines + totals reliably from text layer / OCR tokens
        if _is_purchase_like_doc_type(doc_type) and _looks_like_dhamecha_invoice(txt):
            try:
                modular = _select_dhamecha_authority((txt,))
                if modular:
                    modular_header, modular_items, _, _ = modular
                    return {"header": modular_header, "items": modular_items}
                return _dhamecha_parse_purchase_invoice(txt)
            except Exception:
                pass

        if _is_purchase_like_doc_type(doc_type) and _looks_like_retail_receipt(txt):
            try:
                return _parse_retail_receipt(txt)
            except Exception:
                pass

        if doc_type == "Expenses":
            try:
                return _parse_expense_utility_bill(txt)
            except Exception:
                pass

        # Booker delivery purchase invoice: delivery layout uses M-codes and A0/A1 VAT codes.
        if _is_purchase_like_doc_type(doc_type) and _looks_like_booker_delivery_invoice(txt):
            try:
                return _parse_booker_delivery_purchase_invoice(txt)
            except Exception:
                pass

        # Parfetts purchase invoice fast path (multi-page)
        if _is_purchase_like_doc_type(doc_type) and "PARFETTS" in up:
            hdr = _parfetts_extract_header(txt) or {}
            if isinstance(hdr, dict):
                for k, v in hdr.items():
                    header[k] = v
            items = _parse_parfetts_purchase_invoice(txt)
            # If header totals missing, infer from items
            try:
                if float(header.get("totalNet") or 0.0) <= 0.0 and items:
                    header["totalNet"] = round(sum(_safe_float(it.get("lineNet")) for it in items), 2)
                if float(header.get("totalVat") or 0.0) <= 0.0 and items:
                    header["totalVat"] = round(sum(_safe_float(it.get("vatAmount")) for it in items), 2)
                if float(header.get("totalGross") or 0.0) <= 0.0 and float(header.get("totalNet") or 0.0) > 0.0:
                    header["totalGross"] = round(float(header["totalNet"]) + float(header.get("totalVat") or 0.0), 2)
            except Exception:
                pass

            # VAT Breakdown: if invoice VAT box (A/Z) not detected, calculate from line items (vatCode + vatRate).
            # This is useful for audit and avoids rounding drift when VAT is calculated at invoice level.
            try:
                if not header.get("vatBreakdown") and items:
                    calc = _parfetts_vat_breakdown_from_items(items) or {}
                    rows = calc.get("rows") or []
                    if rows:
                        try:
                            for r in rows:
                                if isinstance(r, dict) and "_source" not in r:
                                    r["_source"] = "calculated"
                        except Exception:
                            pass
                        header["vatBreakdown"] = rows
                        dc = _safe_float(header.get("deliveryCharge"))
                        # Reconcile totals when missing or materially different
                        if float(header.get("totalNet") or 0.0) <= 0.0 or abs(_safe_float(header.get("totalNet")) - _safe_float(calc.get("totalNet"))) > 0.05:
                            header["totalNet"] = _safe_float(calc.get("totalNet"))
                        if float(header.get("totalVat") or 0.0) <= 0.0 or abs(_safe_float(header.get("totalVat")) - _safe_float(calc.get("totalVat"))) > 0.05:
                            header["totalVat"] = _safe_float(calc.get("totalVat"))
                        new_gross = round(_safe_float(calc.get("totalNet")) + _safe_float(calc.get("totalVat")) + dc, 2)
                        if float(header.get("totalGross") or 0.0) <= 0.0 or abs(_safe_float(header.get("totalGross")) - new_gross) > 0.05:
                            header["totalGross"] = float(new_gross)
            except Exception:
                pass

            return {"header": header, "items": items}

        
        # DWG purchase invoice fast path (local/auto)
        if _is_purchase_like_doc_type(doc_type) and ("DRINKS WHOLESALE GROUP" in up or "DRINKS WHOLESALE" in up or "DWG" in up):
            hdr = _dwg_extract_header(txt) or {}
            if isinstance(hdr, dict):
                for k, v in hdr.items():
                    header[k] = v
            items = _parse_dwg_purchase_invoice(txt)

            # If totals missing, infer from items (best-effort)
            try:
                if float(header.get("totalNet") or 0.0) <= 0.0 and items:
                    header["totalNet"] = round(sum(_safe_float(it.get("lineNet")) for it in items), 2)
                if float(header.get("totalVat") or 0.0) <= 0.0 and items:
                    header["totalVat"] = round(sum(_safe_float(it.get("vatAmount")) for it in items), 2)
                if float(header.get("totalGross") or 0.0) <= 0.0 and items:
                    header["totalGross"] = round(sum(_safe_float(it.get("lineGross")) for it in items), 2)
            except Exception:
                pass

            return {"header": header, "items": items}

# Booker purchase invoice fast path (robust)
        if _is_purchase_like_doc_type(doc_type) and ("BOOKER" in up or _looks_like_booker_invoice(txt)):
            header["supplierName"] = "Booker"

            # Customer name (best-effort)
            for ln in txt.splitlines():
                if ln.upper().startswith("CUSTOMER "):
                    m = re.match(r"^CUSTOMER\s+\d+\s+(.*)$", ln.strip(), flags=re.IGNORECASE)
                    if m and m.group(1).strip():
                        nm = _clean_booker_customer_name(m.group(1).strip())
                        if nm:
                            header["customerName"] = nm.title() if nm.isupper() else nm
                    break

            # Invoice number (supports: Invoice No / Invoice Number)
            m_inv = re.search(r"(INVOICE\s*(?:NO|NUMBER)\s*[:#\-]?\s*)([0-9]{5,})", txt, flags=re.I)
            if not m_inv:
                m_inv = re.search(r"\bINVOICE\b[^\n\r]{0,40}\b([0-9]{5,})\b", txt, flags=re.I)
            if m_inv:
                header["invoiceNumber"] = (m_inv.group(2) if m_inv.lastindex and m_inv.lastindex >= 2 else m_inv.group(1)).strip()

            # Invoice date (Booker: supports dd/mm/yy, dd/mm/yyyy, yyyy-mm-dd, and spaced slashes)
            m_date = re.search(r"\b([0-9]{4}-[0-9]{2}-[0-9]{2})\b", txt)
            if m_date:
                header["invoiceDate"] = m_date.group(1)
            else:
                # Prefer 'DATE' labelled token first (e.g., 'DATE 16/11/25' or 'DATE 16 / 11 / 25')
                m_lbl = re.search(r"\bDATE\b[^0-9]{0,20}([0-9]{1,2}\s*/\s*[0-9]{1,2}\s*/\s*[0-9]{2,4})", txt, flags=re.I)
                if not m_lbl:
                    m_lbl = re.search(r"DATE\s*[:\-]?\s*([0-9]{1,2}\s*/\s*[0-9]{1,2}\s*/\s*[0-9]{2,4})", txt, flags=re.I)
                date_str = m_lbl.group(1) if m_lbl else None

                if not date_str:
                    # Fallback: any dd/mm/yy or dd/mm/yyyy with optional spaces
                    m_any = re.search(r"\b([0-9]{1,2}\s*/\s*[0-9]{1,2}\s*/\s*[0-9]{2,4})\b", txt)
                    date_str = m_any.group(1) if m_any else None

                if date_str:
                    ds = re.sub(r"\s+", "", date_str)  # remove spaces around separators
                    m_dmy4 = re.match(r"^([0-9]{1,2})/([0-9]{1,2})/([0-9]{4})$", ds)
                    m_dmy2 = re.match(r"^([0-9]{1,2})/([0-9]{1,2})/([0-9]{2})$", ds) if not m_dmy4 else None
                    if m_dmy4:
                        dd, mm, yyyy = m_dmy4.group(1).zfill(2), m_dmy4.group(2).zfill(2), m_dmy4.group(3)
                        header["invoiceDate"] = f"{yyyy}-{mm}-{dd}"
                    elif m_dmy2:
                        dd, mm, yy = m_dmy2.group(1).zfill(2), m_dmy2.group(2).zfill(2), m_dmy2.group(3)
                        yyyy = "20" + yy if int(yy) <= 50 else "19" + yy
                        header["invoiceDate"] = f"{yyyy}-{mm}-{dd}"

            # Totals (Booker): prefer INVOICE TOTAL + VAT, else sum SUB-TOTAL GOODS, else sum items
            txt_fix = re.sub(r"(\d)\s*\.\s*(\d{2})", r"\1.\2", txt)

            def _find_amount(label: str) -> float:
                ms = re.findall(label + r"[^0-9]{0,40}([0-9][0-9,]*\.[0-9]{2})", txt_fix, flags=re.I)
                if ms:
                    try:
                        return float(ms[-1].replace(",", ""))
                    except Exception:
                        return 0.0
                return 0.0

            def _find_booker_vat_amount(text: str) -> float:
                # Prefer VAT breakdown lines like "B:20.00 ... VAT 125.61"
                try:
                    ms = re.findall(
                        r"(?im)^\s*[A-Z]\s*:\s*.*?\bVAT\b\s*([0-9][0-9,]*\.[0-9]{2})\b",
                        text or "",
                    )
                    if ms:
                        return float(ms[-1].replace(",", ""))
                except Exception:
                    pass
                # Booker breakdown often lists: "B:20.00  628.07  0.00  628.07  125.61"
                try:
                    msb = re.findall(
                        r"(?im)^\s*[A-Z]\s*:\s*[0-9][0-9,]*\.[0-9]{2}\s+"
                        r"[0-9][0-9,]*\.[0-9]{2}\s+"
                        r"[0-9][0-9,]*\.[0-9]{2}\s+"
                        r"[0-9][0-9,]*\.[0-9]{2}\s+"
                        r"([0-9][0-9,]*\.[0-9]{2})\b",
                        text or "",
                    )
                    if msb:
                        return float(msb[-1].replace(",", ""))
                except Exception:
                    pass
                # Fallback: look near the totals/footer block to avoid table header "VAT" column
                try:
                    lines = (text or "").splitlines()
                    idxs = [i for i, ln in enumerate(lines) if re.search(r"\bINVOICE\s+TOTAL\b|\bTOTALS?:\b", ln, flags=re.I)]
                    if idxs:
                        i0 = max(0, idxs[-1] - 4)
                        i1 = min(len(lines), idxs[-1] + 4)
                        block = "\n".join(lines[i0:i1])
                        ms2 = re.findall(r"\bVAT\b[^0-9]{0,10}([0-9][0-9,]*\.[0-9]{2})", block, flags=re.I)
                        if ms2:
                            return float(ms2[-1].replace(",", ""))
                except Exception:
                    pass
                # Last resort (can be noisy if it hits column headers)
                return _find_amount(r"VAT")

            def _find_booker_footer_totals(text: str) -> Tuple[float, float]:
                try:
                    footer_match = re.search(
                        r"(?is)TOTALS?\s*:\s*GOODS\s*VAT\s*([0-9][0-9,]*\.[0-9]{2})\s*([0-9][0-9,]*\.[0-9]{2})",
                        text or "",
                        flags=re.I | re.S,
                    )
                    if footer_match:
                        return (
                            float(footer_match.group(1).replace(",", "")),
                            float(footer_match.group(2).replace(",", "")),
                        )
                except Exception:
                    pass
                try:
                    lines = [str(ln or "").strip() for ln in str(text or "").splitlines()]
                    for idx, ln in enumerate(lines):
                        if not re.search(r"\bTOTALS?\b", ln, flags=re.I):
                            continue
                        window = lines[idx : min(len(lines), idx + 8)]
                        nums = [float(x.replace(",", "")) for x in window if re.fullmatch(r"[0-9][0-9,]*\.[0-9]{2}", x)]
                        if len(nums) >= 2:
                            return nums[0], nums[1]
                except Exception:
                    pass
                return 0.0, 0.0

            # Booker often shows GOODS per department; sum SUB-TOTAL goods where possible
            sub_goods = 0.0
            try:
                subs = re.findall(r"SUB-TOTAL[^\n]*?GOODS\s*:\s*([0-9][0-9,]*\.[0-9]{2})", txt_fix, flags=re.I)
                sub_goods = sum(float(x.replace(",", "")) for x in subs) if subs else 0.0
            except Exception:
                sub_goods = 0.0

            footer_net, footer_vat = _find_booker_footer_totals(txt_fix)
            vat = footer_vat or _find_booker_vat_amount(txt_fix)
            gross = _find_amount(r"INVOICE\s+TOTAL")
            gross_found = gross > 0.0
            vat_found = vat > 0.0
            # Fallback label variants
            if gross <= 0.0:
                gross = _find_amount(r"TOTAL\s+INVOICE")
                gross_found = gross_found or (gross > 0.0)

            invoice_txt = _booker_invoice_details_text(txt_fix)
            items = BookerCombinedRowParser().parse(invoice_txt)
            # Append promo/discount lines (e.g., BUY ANY ... 4.47-)
            try:
                promo_items = _booker_promo_items_from_text(invoice_txt)
                charge_items = _booker_delivery_fee_items_from_text(invoice_txt)
                if charge_items:
                    promo_items = list(promo_items or []) + list(charge_items)
                if promo_items:
                    existing = {(str(it.get("code") or ""), float(it.get("lineNet") or 0.0), str(it.get("description") or "")) for it in (items or [])}
                    for pit in promo_items:
                        key = (str(pit.get("code") or ""), float(pit.get("lineNet") or 0.0), str(pit.get("description") or ""))
                        if key not in existing:
                            items.append(pit)
            except Exception:
                pass
            # Fallback: some scanned Booker PDFs split the table into separate blocks (CODE/DESC/PACK, then QTY/PRICE, then VALUE/VAT/RRP/POR).
            # If the main combined-row parser returns no items (or fewer than TOTAL ITEMS), use the split-layout parser and merge by index.
            try:
                m_total2 = re.search(r"TOTAL\s+ITEMS\s*:\s*(\d+)", txt_fix, flags=re.I)
                expected_total2 = int(m_total2.group(1)) if m_total2 else 0
            except Exception:
                expected_total2 = 0

            if (not items) or (expected_total2 > 0 and len(items) < expected_total2):
                try:
                    split_items = BookerCombinedRowParser().parse_split_layout(invoice_txt)
                except Exception:
                    split_items = []
                if split_items:
                    items = split_items
            if not items:
                try:
                    stacked_items = _booker_parse_stacked_layout(invoice_txt)
                except Exception:
                    stacked_items = []
                if stacked_items:
                    items = stacked_items
            try:
                needs_stacked_ocr = (
                    (not items)
                    or _booker_items_look_corrupt(items)
                    or (expected_total2 > 0 and len(items) < expected_total2)
                )
                if needs_stacked_ocr:
                    stacked_ocr_items = _booker_parse_stacked_ocr_text(invoice_txt)
                    if stacked_ocr_items:
                        if (
                            (not items)
                            or _booker_items_look_corrupt(items)
                            or (expected_total2 > 0 and len(stacked_ocr_items) >= expected_total2)
                            or (len(stacked_ocr_items) > len(items))
                        ):
                            items = stacked_ocr_items
            except Exception:
                pass
            # If layout looks stacked (CODE/DESC + PACK SIZE + VALUE/VAT blocks), prefer stacked parser when it improves completeness.
            try:
                if items:
                    stacked_hint = bool(
                        re.search(r"CODE\s+DESCRIPTION", txt_fix, flags=re.I)
                        and re.search(r"PACK\s+SIZE", txt_fix, flags=re.I)
                        and re.search(r"VALUE\s+VAT", txt_fix, flags=re.I)
                    )
                    if stacked_hint:
                        def _score_items(rows: List[Dict[str, Any]]) -> int:
                            sc = 0
                            for it in rows or []:
                                if abs(_safe_float(it.get("casePack"))) > 0:
                                    sc += 1
                                if str(it.get("unitSize") or "").strip():
                                    sc += 1
                                if abs(_safe_float(it.get("unitPrice"))) > 0:
                                    sc += 1
                                if abs(_safe_float(it.get("lineNet"))) > 0:
                                    sc += 1
                            return sc
                        stacked_items = _booker_parse_stacked_layout(invoice_txt)
                        if stacked_items:
                            if _score_items(stacked_items) >= _score_items(items):
                                items = stacked_items
            except Exception:
                pass
            # Rowify fallback: rebuild OCR into row-like lines
            try:
                row_text = _booker_build_rowified_text(invoice_txt)
                row_items = BookerCombinedRowParser().parse(row_text) if row_text else []
                if row_items and not _booker_items_look_corrupt(row_items):
                    if _booker_items_look_corrupt(items) or (expected_total2 and len(row_items) >= expected_total2) or (len(row_items) > len(items)):
                        items = row_items
            except Exception:
                pass
            if not items:
                try:
                    row_text = _booker_build_rowified_text(invoice_txt)
                except Exception:
                    row_text = ""
                if row_text:
                    try:
                        row_items = BookerCombinedRowParser().parse(row_text)
                        if row_items and not _booker_items_look_corrupt(row_items):
                            items = row_items
                    except Exception:
                        pass
            # Ensure promo/discount lines are retained after any parser swaps
            try:
                promo_items = _booker_promo_items_from_text(invoice_txt)
                charge_items = _booker_delivery_fee_items_from_text(invoice_txt)
                if charge_items:
                    promo_items = list(promo_items or []) + list(charge_items)
                if promo_items:
                    existing = {(str(it.get("code") or ""), float(it.get("lineNet") or 0.0), str(it.get("description") or "")) for it in (items or [])}
                    for pit in promo_items:
                        key = (str(pit.get("code") or ""), float(pit.get("lineNet") or 0.0), str(pit.get("description") or ""))
                        if key not in existing:
                            items.append(pit)
            except Exception:
                pass
            items_net = round(sum((x.get("lineNet") or 0.0) for x in items), 2) if items else 0.0
            items_vat = round(sum((x.get("vatAmount") or 0.0) for x in items), 2) if items else 0.0
            items_gross = round(items_net + items_vat, 2) if items else 0.0

            # Best net estimate: gross - vat, else subtotal goods sum, else items sum, else any GOODS match
            net = 0.0
            if footer_net > 0.0:
                net = float(footer_net)
            elif gross > 0.0 and vat >= 0.0:
                net = round(float(gross) - float(vat), 2)
            if net <= 0.0 and sub_goods > 0.0:
                net = round(float(sub_goods), 2)
            if net <= 0.0 and items_net > 0.0:
                net = float(items_net)
            if net <= 0.0:
                net = _find_amount(r"GOODS")

            # Backfill Booker OCR rows that the main parser skipped, but only when the
            # extra rows move line totals closer to the header/footer net amount.
            try:
                salvage_items = _booker_salvage_missing_ocr_items(invoice_txt, items)
            except Exception:
                salvage_items = []
            if salvage_items:
                merged_items = list(items) + list(salvage_items)
                merged_net = round(sum(_safe_float(x.get("lineNet")) for x in merged_items), 2)
                if (net <= 0.0 and merged_net > items_net) or (
                    net > 0.0 and abs(merged_net - net) < abs(items_net - net)
                ):
                    items = merged_items
                    items_net = merged_net
                    items_vat = round(sum(_safe_float(x.get("vatAmount")) for x in items), 2)
                    items_gross = round(items_net + items_vat, 2)
                    for idx, it in enumerate(items, start=1):
                        try:
                            it["lineNo"] = idx
                        except Exception:
                            continue

            # If we accidentally picked up a section subtotal as net, reconcile against gross-vat.
            if gross > 0.0 and vat >= 0.0:
                implied_net = round(float(gross) - float(vat), 2)
                if implied_net > 0.0 and (net <= 0.0 or abs(float(net) - implied_net) > 0.75):
                    net = implied_net

            header["totalNet"] = float(net or 0.0)
            header["totalVat"] = float(vat or items_vat or 0.0)
            header["totalGross"] = float(gross or 0.0)
            if header["totalGross"] <= 0.0 and header["totalNet"] > 0.0:
                header["totalGross"] = round(header["totalNet"] + header["totalVat"], 2)

            try:
                items = _booker_merge_salvage_if_better(invoice_txt, header, items)
                items_net = round(sum(_safe_float(x.get("lineNet")) for x in items), 2) if items else 0.0
                items_vat = round(sum(_safe_float(x.get("vatAmount")) for x in items), 2) if items else 0.0
                items_gross = round(items_net + items_vat, 2) if items else 0.0
            except Exception:
                pass

            # If totals were not reliably found in footer, and item count matches TOTAL ITEMS, trust items sums.
            try:
                reliable_footer = bool(gross_found and vat_found) or bool(footer_net > 0.0 and footer_vat >= 0.0)
                if expected_total2 > 0 and len(items) == expected_total2 and items_net > 0 and items_vat > 0:
                    if (not reliable_footer) or (
                        abs(_safe_float(header.get("totalNet")) - items_net) > 0.5
                        or abs(_safe_float(header.get("totalVat")) - items_vat) > 0.5
                        or abs(_safe_float(header.get("totalGross")) - items_gross) > 0.5
                    ):
                        header["totalNet"] = float(items_net)
                        header["totalVat"] = float(items_vat)
                        header["totalGross"] = float(items_gross)
            except Exception:
                pass

            # If items exist but header net looks like a single department subtotal, reconcile to invoice gross/vat
            if items:
                if abs(items_net - float(header.get("totalNet") or 0.0)) > 0.25 and header.get("totalGross", 0.0) > 0.0:
                    # Prefer invoice totals (gross/vat) as source of truth
                    if header.get("totalVat", 0.0) >= 0.0:
                        header["totalNet"] = round(float(header["totalGross"]) - float(header["totalVat"]), 2)
                # Guard: if header totals are implausibly small vs line sums, trust line sums
                try:
                    hdr_net = _safe_float(header.get("totalNet"))
                    hdr_vat = _safe_float(header.get("totalVat"))
                    hdr_gross = _safe_float(header.get("totalGross"))
                    if items_net > 0 and items_gross > 0:
                        if (hdr_gross > 0 and hdr_gross < (items_gross * 0.5)) or (hdr_net > 0 and hdr_net < (items_net * 0.5)):
                            header["totalNet"] = float(items_net)
                            header["totalVat"] = float(items_vat)
                            header["totalGross"] = float(items_gross)
                except Exception:
                    pass
                # If header totals still missing, use items sums
                if float(header.get("totalNet") or 0.0) <= 0.0 and items_net > 0.0:
                    header["totalNet"] = float(items_net)
                if float(header.get("totalVat") or 0.0) <= 0.0 and items_vat > 0.0:
                    header["totalVat"] = float(items_vat)
                if float(header.get("totalGross") or 0.0) <= 0.0 and float(header.get("totalNet") or 0.0) > 0.0:
                    header["totalGross"] = round(float(header["totalNet"]) + float(header["totalVat"] or 0.0), 2)

            # Final guard: normalize FREE lines after all Booker adjustments
            try:
                items = _booker_fix_free_lines(items)
            except Exception:
                pass
            try:
                items = _booker_prune_non_invoice_detail_rows(items, invoice_txt)
            except Exception:
                pass
            return {"header": header, "items": items}
# Generic header-only parsing
        # invoice no
        m_inv2 = re.search(r"\b(INV[- ]?\d{5,}|INVOICE\s*(?:NO|NUMBER)\s*[:\-]?\s*[A-Z0-9\-]{4,})\b", up)
        if m_inv2:
            s = m_inv2.group(1)
            s = re.sub(r"INVOICE\s*(?:NO|NUMBER)\s*[:\-]?\s*", "", s, flags=re.I)
            header["invoiceNumber"] = s.replace(" ", "").strip()

        m_date2 = re.search(r"\b(\d{4}-\d{2}-\d{2})\b", txt)
        if m_date2:
            header["invoiceDate"] = m_date2.group(1)

        # totals
        # Match explicit totals labels first and ignore registration-number noise such as "VAT Reg No".
        txt_totals = txt
        txt_totals = re.sub(r"(?im)^.*\bVAT\s+REG(?:ISTRATION)?\b.*$", "", txt_totals)
        txt_totals = re.sub(r"(?im)^.*\bCO\.?\s+REG\b.*$", "", txt_totals)
        m_net2 = re.search(
            r"\b(?:SUB[\s\-]*TOTAL|TOTAL\s+NET|TOTAL\s+EX(?:CLUDING)?\s+VAT|NET\s+TOTAL)\b\s*[:\-]?\s*[^\d\r\n]{0,8}\s*([0-9][0-9,]*\.?[0-9]{0,2})",
            txt_totals,
            flags=re.I,
        )
        m_vat2 = re.search(
            r"\b(?:TOTAL\s+VAT|VAT\s+TOTAL)\b\s*[:\-]?\s*[^\d\r\n]{0,8}\s*([0-9][0-9,]*\.?[0-9]{0,2})",
            txt_totals,
            flags=re.I,
        )
        m_gross2 = re.search(
            r"\b(?:INVOICE\s+TOTAL|TOTAL\s+(?:GROSS|AMOUNT\s+DUE)|AMOUNT\s+DUE)\b\s*[:\-]?\s*[^\d\r\n]{0,8}\s*([0-9][0-9,]*\.?[0-9]{0,2})",
            txt_totals,
            flags=re.I,
        )
        if m_net2:
            header["totalNet"] = _safe_float(m_net2.group(1))
        if m_vat2:
            header["totalVat"] = _safe_float(m_vat2.group(1))
        if m_gross2:
            header["totalGross"] = _safe_float(m_gross2.group(1))

        # supplier/customer names (best-effort)
        if _is_purchase_like_doc_type(doc_type) or doc_type in ("Service Invoice", "Expenses"):
            # supplier is whoever issued
            # use first non-empty line as placeholder
            lines = [ln.strip() for ln in txt.splitlines() if ln.strip()]
            if lines:
                header["supplierName"] = lines[0][:80]
        else:
            # customer template matching will use customerName; keep placeholder
            m_c = re.search(r"\bCUSTOMER\b\s*[:\-]?\s*(.+)", txt, flags=re.I)
            if m_c:
                header["customerName"] = m_c.group(1).strip()[:80]

        return {"header": header, "items": items}


# -------------------------
# Cloud (optional)  kept for later expansion
# -------------------------


def _strip_models_prefix(model_name: str) -> str:
    mn = (model_name or "").strip()
    if mn.startswith("models/"):
        return mn.split("/", 1)[1].strip()
    return mn

def _is_model_not_found_error(err: Exception) -> bool:
    msg = str(err).lower()
    return ("not_found" in msg) or ("not found" in msg) or ("model" in msg and "not" in msg and "found" in msg)

def _pick_best_gemini_model(model_names, preferred: str = "") -> str:
    preferred = _strip_models_prefix(preferred or "")
    norm = [_strip_models_prefix(x) for x in (model_names or []) if str(x).strip()]
    if not norm:
        return preferred or ""
    # Exact match
    if preferred and preferred in norm:
        return preferred
    # Suffix match (handles models/ prefix)
    if preferred:
        for m in norm:
            if m.endswith(preferred):
                return m
    # Prefer flash models first (speed + cost), then any gemini
    flash = [m for m in norm if "flash" in m]
    if flash:
        # Prefer the newest (often 2.0 > 1.5) by string sort heuristic
        flash_sorted = sorted(flash, reverse=True)
        return flash_sorted[0]
    gem = [m for m in norm if "gemini" in m]
    if gem:
        return sorted(gem, reverse=True)[0]
    return norm[0]

def _resolve_gemini_model_google_genai(client, preferred: str) -> str:
    """Resolve to an available model name for google-genai SDK."""
    preferred = _strip_models_prefix(preferred or "")
    if not client:
        return preferred
    # Quick validate via models.get (if available)
    try:
        if preferred:
            client.models.get(model=preferred)
            return preferred
    except Exception as e:
        if not _is_model_not_found_error(e):
            return preferred
    # List and pick
    model_names = []
    try:
        for m in client.models.list():
            try:
                supported = getattr(m, "supported_actions", None) or []
            except Exception:
                supported = []
            name = getattr(m, "name", None) or getattr(m, "model", None) or str(m)
            name = str(name)
            if "generatecontent" in "".join([str(x).lower() for x in supported]) or (not supported):
                model_names.append(name)
    except Exception:
        model_names = []
    pick = _pick_best_gemini_model(model_names, preferred=preferred)
    return pick or preferred

def _resolve_gemini_model_google_generativeai(genai_module, preferred: str) -> str:
    """Resolve to an available model name for google-generativeai SDK."""
    preferred = _strip_models_prefix(preferred or "")
    if genai_module is None:
        return preferred
    try:
        if preferred:
            # Not all versions support get_model; safe-try
            try:
                genai_module.get_model("models/" + preferred)
                return preferred
            except Exception:
                pass
    except Exception:
        pass
    model_names = []
    try:
        for m in genai_module.list_models():
            name = getattr(m, "name", "") or ""
            supported = getattr(m, "supported_generation_methods", None) or getattr(m, "supported_generation_methods", []) or []
            # Prefer models that can generate content
            if supported:
                if any(str(x).lower() == "generatecontent" for x in supported):
                    model_names.append(name)
            else:
                model_names.append(name)
    except Exception:
        model_names = []
    pick = _pick_best_gemini_model(model_names, preferred=preferred)
    return pick or preferred


def _cloud_purchase_invoice_mapping_prompt(file_name: str = "") -> str:
    """Prompt used by the zero-training cloud invoice mapper.

    This is intentionally supplier-agnostic: it asks the model to infer labels,
    columns and totals from the current document instead of relying on a saved
    supplier template.
    """
    return f"""
Return STRICT JSON only. Do not include markdown, comments or explanations.

You are DocMate's zero-training invoice mapping agent. Read the invoice image/PDF and any text layer, then map the document into the DocMate schema. The supplier may be unknown and no supplier template may exist.

Source file: {file_name or ""}

Required output shape:
{{
  "header": {{
    "supplierName": "",
    "customerName": "",
    "invoiceNumber": "",
    "invoiceDate": "",
    "currency": "",
    "deliveryCharge": 0,
    "totalNet": 0,
    "totalVat": 0,
    "totalGross": 0,
    "vatRegistrationNumber": "",
    "customerPONumber": "",
    "orderNumber": "",
    "accountNumber": "",
    "paymentDueDate": "",
    "extractionMode": "Zero Training Cloud Mapping Agent"
  }},
  "items": [
    {{
      "lineNo": 1,
      "code": "",
      "barcode": "",
      "description": "",
      "casePack": "",
      "casePackText": "",
      "unitSize": "",
      "qty": 0,
      "unitPrice": 0,
      "discount": 0,
      "lineNet": 0,
      "vatCode": "",
      "vatRate": 0,
      "vatAmount": 0,
      "lineGross": 0
    }}
  ]
}}

Header mapping rules:
- supplierName is the issuer/seller/vendor, not the buyer or delivery address.
- customerName is the bill-to/customer/buyer/account holder.
- invoiceNumber can be labelled Invoice No, Invoice Number, Factuurnummer, Bill No, Document No, Reference, or similar. Prefer the explicit invoice identifier over order/ref/account numbers.
- invoiceDate can be labelled invoice date, tax point, bill date, document date, factuurdatum, or similar. Return YYYY-MM-DD where possible.
- totalNet is the invoice subtotal/net/ex VAT/supplies amount.
- totalVat is the VAT/tax amount.
- totalGross is total due/total/invoice total/inc VAT/total to pay.
- deliveryCharge is any invoice-level transport/freight/shipping/delivery/port charge printed outside the product table.
- currency should be GBP, EUR, USD or the visible currency code/symbol inferred from the invoice.
- If totals are printed in a summary, use the printed summary totals. Do not invent totals.

Line item mapping rules:
- Extract real charge/product/service rows only. Exclude totals, VAT analysis, bank details, payment terms, addresses, footers and repeated page headers.
- Include invoice-level charge rows such as delivery, freight, transport, shipping, carriage, handling, service charge, or French labels like Frais de port HT / Livraison / Transport when they are printed with an amount and contribute to the invoice totals.
- Preserve the printed row order and set lineNo sequentially.
- description is the product/service description. Include wrapped continuation text when it belongs to the row.
- code is a product/item/article/SKU code only. If the invoice has no product code, leave code blank; do not put quantity or invoice number into code.
- barcode is only for EAN/UPC-style barcodes.
- qty maps from Quantity, Qty, Aantal, Units, Hours, Period quantity or similar.
- unitPrice maps from Price, Unit Price, Price/each, Prijs/eenh, Rate or similar.
- discount maps from Discount/Korting columns where present, otherwise 0.
- lineNet maps from Value, Amount, Net, Extended Price, Totaal, line total excluding VAT or the visible line amount.
- vatCode maps from a printed tax marker/code column such as *, VAT code, tax code or numeric code.
- vatRate maps from a visible VAT percentage/rate. If only VAT code is visible and a VAT analysis table maps that code to a rate, use that rate.
- vatAmount maps from explicit line VAT amount only. If VAT is only summarized at header level, leave vatAmount as 0 unless it is clearly printed per line.
- lineGross maps from explicit inc-VAT line total only. If not printed, use lineNet + vatAmount when vatAmount is known; otherwise leave it 0 or same as lineNet only if the invoice is zero-rated/no VAT.
- If the invoice has useful header fields not listed above, include them as additional header JSON properties using clear camelCase names.
- If the invoice has useful line columns not listed above, include them as additional item JSON properties on every applicable row using clear camelCase names. Preserve the original printed column meaning.

Validation rules:
- Use numbers only for numeric fields. Remove currency symbols and thousands separators.
- If qty * unitPrice approximately equals the line amount, use that as evidence but prefer the printed line amount.
- Header totals should reconcile with line rows when possible, but printed header totals win.
- Return empty strings or 0 for missing fields. Do not hallucinate.
""".strip()


class CloudGeminiExtractor:
    def __init__(self, api_key: str, model_name: str = "gemini-3.6-flash"):
        self.api_key = api_key
        self.model_name = model_name

    def is_available(self) -> bool:
        return bool((self.api_key or "").strip())

    def extract_purchase_invoice(self, file_bytes: bytes, mime_type: str, file_name: str, doc_text: str = "") -> Dict[str, Any]:
        """Best-effort call. If libraries are missing or API changes, return empty dict but log error."""
        try:
            # Prefer google-genai (new) if installed
            try:
                try:
                    from google import genai  # type: ignore
                except Exception:
                    import google.genai as genai  # type: ignore
                from google.genai import types  # type: ignore

                try:
                    client = genai.Client(api_key=self.api_key, http_options=types.HttpOptions(api_version='v1'))
                except Exception:
                    client = genai.Client(api_key=self.api_key)
                resolved_model = _resolve_gemini_model_google_genai(client, self.model_name)
                if resolved_model and resolved_model != _strip_models_prefix(self.model_name):
                    _log_event(f"{file_name} CloudGemini model resolved: {self.model_name} -> {resolved_model}")
                parts = []
                # text hint
                if doc_text:
                    parts.append(types.Part(text=f"Text layer (may be incomplete):\n{doc_text[:4000]}") )
                # file part
                if mime_type == "application/pdf":
                    parts.append(types.Part.from_bytes(data=file_bytes, mime_type="application/pdf"))
                else:
                    parts.append(types.Part.from_bytes(data=file_bytes, mime_type=mime_type))

                prompt = _cloud_purchase_invoice_mapping_prompt(file_name)
                # Build contents in the most compatible way (text + file parts)
                contents = parts + [prompt]
                # Request JSON via prompt instructions (avoid SDK-specific response_mime_type fields)

                cfg_primary = {
                    "temperature": 0,
                }
                cfg_alt = {
                    "temperature": 0,
                }
                cfg_min = {
                    "temperature": 0,
                }

                # Try config forms in order for compatibility across SDK versions
                resp = None
                last_err: Optional[Exception] = None
                for cfg_try in (cfg_primary, cfg_alt, cfg_min):
                    try:
                        resp = client.models.generate_content(
                            model=resolved_model,
                            contents=contents,
                            config=cfg_try,
                        )
                        break
                    except Exception as e:
                        last_err = e
                        resp = None

                if resp is None:
                    # Fallback: older installs used different parameter names
                    try:
                        resp = client.models.generate_content(
                            model=resolved_model,
                            contents=contents,
                            generation_config={"temperature": 0},
                        )
                    except Exception as e:
                        raise last_err or e
                parsed = getattr(resp, "parsed", None)
                if isinstance(parsed, dict):
                    # Attach raw response text where available (useful for Template Test / Preview debug)
                    try:
                        _rt = getattr(resp, "text", "") or ""
                    except Exception:
                        _rt = ""
                    parsed = dict(parsed)
                    if _rt and not parsed.get("raw_text"):
                        parsed["raw_text"] = _rt
                    if _rt and not parsed.get("debug_text"):
                        parsed["debug_text"] = _rt
                    return parsed

                text = getattr(resp, "text", "") or ""
                out = _parse_json_from_model(text)
                if isinstance(out, dict):
                    if text and not out.get("raw_text"):
                        out["raw_text"] = text
                    if text and not out.get("debug_text"):
                        out["debug_text"] = text
                return out
            except Exception as e_new:
                _log_event(f"CloudGeminiExtractor unavailable (google-genai): {e_new}", file_name=file_name)

            # Fallback: google-generativeai (older)
            try:
                import google.generativeai as genai  # type: ignore

                genai.configure(api_key=self.api_key)
                resolved_model = _resolve_gemini_model_google_generativeai(genai, self.model_name)
                if resolved_model and resolved_model != _strip_models_prefix(self.model_name):
                    _log_event(f"{file_name} CloudGemini model resolved: {self.model_name} -> {resolved_model}")
                model = genai.GenerativeModel(resolved_model or self.model_name)
                prompt = _cloud_purchase_invoice_mapping_prompt(file_name)
                if mime_type == "application/pdf":
                    resp = model.generate_content([prompt, {"mime_type": "application/pdf", "data": file_bytes}])
                else:
                    resp = model.generate_content([prompt, {"mime_type": mime_type, "data": file_bytes}])
                text = getattr(resp, "text", "") or ""
                return _parse_json_from_model(text)
            except Exception as e_old:
                _log_event(f"CloudGeminiExtractor unavailable (google-generativeai): {e_old}", file_name=file_name)

        except Exception as e:
            _log_event(f"CloudGeminiExtractor error: {e}", file_name=file_name)
        return {"header": {}, "items": []}

    def extract_utility_bill_header(self, file_bytes: bytes, mime_type: str, file_name: str, doc_text: str = "") -> Dict[str, Any]:
        """Header-only utility bill extraction. Never returns line items."""
        prompt = (
            "Return STRICT JSON only. Extract header fields from any utility bill, expense bill, or service statement. "
            "Do not extract line items. Schema: "
            "{header:{supplierName,customerName,invoiceNumber,invoiceDate,currency,totalNet,totalVat,totalGross,"
            "accountNumber,contractNumber,siteAddress,billToAddress,servicePeriod,paymentDueDate,paymentDueText,"
            "utilityType,meterNumber,mpan,mprn,vatRegistrationNumber,extractionMode},items:[]}."
            "Rules: use bill number as invoiceNumber when invoice number is absent; use bill date as invoiceDate; "
            "use total amount due or total inc VAT as totalGross; use total charges exc/excluding VAT as totalNet; "
            "use VAT amount as totalVat; dates should be YYYY-MM-DD where possible; set extractionMode to Utility Header Agent."
        )
        try:
            try:
                try:
                    from google import genai  # type: ignore
                except Exception:
                    import google.genai as genai  # type: ignore
                from google.genai import types  # type: ignore

                try:
                    client = genai.Client(api_key=self.api_key, http_options=types.HttpOptions(api_version='v1'))
                except Exception:
                    client = genai.Client(api_key=self.api_key)
                resolved_model = _resolve_gemini_model_google_genai(client, self.model_name)
                parts = []
                if doc_text:
                    parts.append(types.Part(text=f"Text layer (may be incomplete):\n{doc_text[:6000]}"))
                parts.append(types.Part.from_bytes(data=file_bytes, mime_type=("application/pdf" if mime_type == "application/pdf" else mime_type)))
                resp = client.models.generate_content(
                    model=resolved_model,
                    contents=parts + [prompt],
                    config={"temperature": 0},
                )
                text = getattr(resp, "text", "") or ""
                out = _parse_json_from_model(text)
                if isinstance(out, dict):
                    out.setdefault("items", [])
                    if not isinstance(out.get("items"), list):
                        out["items"] = []
                    out["items"] = []
                    out.setdefault("header", {})
                    if isinstance(out.get("header"), dict):
                        out["header"]["extractionMode"] = out["header"].get("extractionMode") or "Utility Header Agent"
                    return out
            except Exception as e_new:
                _log_event(f"Cloud utility extractor unavailable (google-genai): {e_new}", file_name=file_name)

            try:
                import google.generativeai as genai  # type: ignore

                genai.configure(api_key=self.api_key)
                resolved_model = _resolve_gemini_model_google_generativeai(genai, self.model_name)
                if resolved_model and resolved_model != _strip_models_prefix(self.model_name):
                    _log_event(f"{file_name} CloudGemini model resolved: {self.model_name} -> {resolved_model}")
                model = genai.GenerativeModel(resolved_model or self.model_name)
                content = [prompt]
                if doc_text:
                    content.append(f"Text layer (may be incomplete):\n{doc_text[:6000]}")
                content.append({"mime_type": ("application/pdf" if mime_type == "application/pdf" else mime_type), "data": file_bytes})
                resp = model.generate_content(content)
                out = _parse_json_from_model(getattr(resp, "text", "") or "")
                out.setdefault("header", {})
                out["items"] = []
                if isinstance(out.get("header"), dict):
                    out["header"]["extractionMode"] = out["header"].get("extractionMode") or "Utility Header Agent"
                return out
            except Exception as e_old:
                _log_event(f"Cloud utility extractor unavailable (google-generativeai): {e_old}", file_name=file_name)
        except Exception as e:
            _log_event(f"Cloud utility extractor error: {e}", file_name=file_name)
        return {"header": {}, "items": []}


def _ai_template_agent_suggest(
    *,
    settings: Dict[str, Any],
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    doc_type: str,
    file_bytes: bytes = b"",
    mime_type: str = "application/pdf",
) -> Dict[str, Any]:
    """Create a human-reviewed template proposal using Google Document AI output."""
    header_for_suggest = dict(header or {})
    items_for_suggest = _template_training_items(items)
    text_parts = [str(raw_text or "")]
    notes: List[str] = []

    if _gdocai_is_configured(settings) and isinstance(file_bytes, (bytes, bytearray)) and file_bytes:
        project_id = str(_gdocai_setting(settings, "gdocai_project_id", "document_ai_project_id") or "").strip()
        location = str(_gdocai_setting(settings, "gdocai_location", "document_ai_location") or "").strip()
        credentials_json = _gdocai_credentials_json(settings)
        processor_id = str(_gdocai_setting(settings, "gdocai_processor_id", "document_ai_processor_id") or "").strip()
        ocr_processor_id = _gdocai_ocr_processor_id(settings)

        if processor_id:
            try:
                extractor = GoogleDocumentAIInvoiceExtractor(
                    project_id=project_id,
                    location=location,
                    processor_id=processor_id,
                    credentials_json=credentials_json,
                )
                if extractor.is_available():
                    gdoc = extractor.extract_purchase_invoice(
                        bytes(file_bytes),
                        mime_type=str(mime_type or "application/pdf"),
                        file_name=file_name,
                        doc_text=str(raw_text or ""),
                    )
                    gdoc_header = (gdoc or {}).get("header") or {}
                    for key, value in gdoc_header.items():
                        if key in ("totalNet", "totalVat", "totalGross"):
                            if _safe_float(header_for_suggest.get(key)) <= 0 and _safe_float(value) > 0:
                                header_for_suggest[key] = _safe_float(value)
                        elif not str(header_for_suggest.get(key) or "").strip() and str(value or "").strip():
                            header_for_suggest[key] = value
                    gdoc_items = _template_training_items((gdoc or {}).get("items") or [])
                    if not items_for_suggest and gdoc_items:
                        items_for_suggest = gdoc_items
                    if str((gdoc or {}).get("raw_text") or "").strip():
                        text_parts.append(str((gdoc or {}).get("raw_text") or ""))
                    if str((gdoc or {}).get("debug_text") or "").strip():
                        text_parts.append(str((gdoc or {}).get("debug_text") or ""))
                    notes.append("Used Google Document AI invoice parser output.")
            except Exception as e:
                notes.append(f"Google Document AI invoice parser unavailable: {e}")
                try:
                    _log_event(f"Template suggestion Document AI invoice parser failed: {e}", file_name=file_name)
                except Exception:
                    pass

        if ocr_processor_id:
            try:
                ocr_extractor = GoogleDocumentAIOcrExtractor(
                    project_id=project_id,
                    location=location,
                    processor_id=ocr_processor_id,
                    credentials_json=credentials_json,
                )
                if ocr_extractor.is_available():
                    ocr_result = ocr_extractor.extract_text(
                        bytes(file_bytes),
                        mime_type=str(mime_type or "application/pdf"),
                        file_name=file_name,
                        doc_text=str(raw_text or ""),
                    )
                    if str((ocr_result or {}).get("raw_text") or "").strip():
                        text_parts.append(str((ocr_result or {}).get("raw_text") or ""))
                    if str((ocr_result or {}).get("line_text") or "").strip():
                        text_parts.append(str((ocr_result or {}).get("line_text") or ""))
                    notes.append("Used Google Document AI OCR processor text.")
            except Exception as e:
                notes.append(f"Google Document AI OCR unavailable: {e}")
                try:
                    _log_event(f"Template suggestion Document AI OCR failed: {e}", file_name=file_name)
                except Exception:
                    pass
    else:
        notes.append("Google Document AI is not configured or invoice bytes were unavailable; used existing OCR text and corrections.")

    dedup_text_parts = []
    seen_text = set()
    for part in text_parts:
        p = str(part or "").strip()
        if not p:
            continue
        key = p[:1000]
        if key in seen_text:
            continue
        seen_text.add(key)
        dedup_text_parts.append(p)

    proposal = _local_template_agent_suggest(
        header=header_for_suggest,
        items=items_for_suggest,
        raw_text="\n".join(dedup_text_parts),
        file_name=file_name,
        doc_type=doc_type,
        reason="Used Google Document AI API output plus corrected header/line data.",
    )
    existing_notes = list(proposal.get("notes") or [])
    proposal["notes"] = list(dict.fromkeys([*notes, *existing_notes]))
    proposal["_agent_model"] = "google_document_ai_template_agent"
    return proposal


def _local_template_agent_suggest(
    *,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    doc_type: str,
    reason: str = "",
) -> Dict[str, Any]:
    """Create a deterministic template proposal without Gemini.

    This uses corrected header/line data plus available OCR/Document AI text.
    It is intentionally conservative and still requires admin approval.
    """
    header = header if isinstance(header, dict) else {}
    items = _template_training_items(items)
    raw_text = str(raw_text or "")

    supplier_name = _normalise_supplier_name(
        str(header.get("supplierName") or "").strip()
        or _guess_supplier_from_filename(file_name or "")
        or ""
    )
    parser_type = _detect_parser_type_from_supplier(supplier_name, "GENERIC")

    header_aliases = _template_merge_alias_config(
        _template_default_header_aliases(),
        _template_learn_header_aliases_from_text(header, raw_text),
        _template_default_header_aliases(),
    )
    line_aliases = _template_default_line_aliases()

    currency = _infer_template_currency(raw_text, header)
    locale_profile = _infer_template_locale_profile(raw_text, currency)

    allow_missing_code = any(
        isinstance(it, dict)
        and str(it.get("description") or "").strip()
        and not str(it.get("code") or "").strip()
        for it in items
    )
    header_vat_zero = _safe_float(header.get("totalVat")) == 0.0 and (
        _safe_float(header.get("totalNet")) > 0.0 or _safe_float(header.get("totalGross")) > 0.0
    )
    zero_vat_with_rate = any(
        _safe_float(it.get("vatRate")) > 0.0
        and _safe_float(it.get("lineNet")) > 0.0
        and (
            _safe_float(it.get("vatAmount")) == 0.0
            or header_vat_zero
            or abs(_safe_float(it.get("lineGross")) - _safe_float(it.get("lineNet"))) <= 0.01
        )
        for it in items
    )

    rules: Dict[str, Any] = {
        "do_not_create_blank_zero_rows": True,
    }
    if currency:
        rules["currency"] = currency
    if allow_missing_code:
        rules["allow_missing_code"] = True
        rules["line_match_strategy"] = "description_anchor"
    if zero_vat_with_rate:
        rules["zero_vat_amount_allowed_with_vat_rate"] = True
        rules["do_not_recalculate_vat_amount_if_present"] = True
    if any(_safe_float(it.get("lineGross")) > 0.0 for it in items):
        rules["line_gross_source"] = "total_incl_vat"
    if _safe_float(header.get("totalNet")) > 0.0 or _safe_float(header.get("totalGross")) > 0.0:
        rules["header_totals_source"] = "invoice_summary"
    if len(items) == 1:
        one = items[0]
        header_net = round(_safe_float(header.get("totalNet")), 2)
        header_gross = round(_safe_float(header.get("totalGross")), 2)
        row_net = round(_safe_float(one.get("lineNet")), 2)
        row_gross = round(_safe_float(one.get("lineGross")), 2)
        if (
            str(one.get("description") or "").strip()
            and not str(one.get("code") or "").strip()
            and (
                (header_net > 0 and abs(row_net - header_net) <= 0.05)
                or (header_gross > 0 and abs(row_gross - header_gross) <= 0.05)
            )
        ):
            rules["allow_missing_code"] = True
            rules["line_match_strategy"] = "description_anchor"
            rules["single_line_no_code_use_header_totals"] = True

    keywords = _template_keywords(
        supplier_name,
        [
            str(header.get("customerName") or ""),
            str(header.get("vatRegistrationNumber") or ""),
            file_name or "",
        ],
    )

    notes = [
        reason or "Used local OCR/Document AI-based template suggestion.",
        "Review aliases/rules before saving.",
    ]
    if allow_missing_code:
        notes.append("Detected line rows without product codes; enabled description-anchor matching.")
    if bool(rules.get("single_line_no_code_use_header_totals")):
        notes.append("Detected a reviewed single no-code line matching invoice totals; enabled learned header-total line reconciliation.")
    if zero_vat_with_rate:
        notes.append("Detected VAT rate with zero VAT amount; configured rule to preserve invoice VAT amount.")
    table_profile = _template_table_profile_from_text_and_items(items, raw_text)
    if table_profile:
        notes.append("Detected a reusable supplier table profile with start/stop anchors and column order.")

    return {
        "supplier_name": supplier_name,
        "parser_type": parser_type,
        "requires_cloud": False,
        "match_keywords": keywords,
        "header_aliases": header_aliases,
        "line_aliases": line_aliases,
        "vat_map": _derive_vat_map_from_items(items),
        "rules": rules,
        "locale_profile": locale_profile,
        "table_profile": table_profile,
        "notes": notes,
        "_agent_model": "local_template_agent",
    }


def _ai_template_agent_payload(
    *,
    proposal: Dict[str, Any],
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    doc_type: str,
    existing_template: Optional[Dict[str, Any]] = None,
    max_pages_pdf: Optional[int] = None,
) -> Dict[str, Any]:
    """Convert an AI proposal into a supplier_templates upsert payload."""
    proposal = proposal if isinstance(proposal, dict) else {}
    header = _normalise_teacher_header_from_raw_text(header or {}, raw_text or "")
    items = _template_training_items(items)
    items, invoice_level_vat_repaired = _repair_teacher_invoice_level_vat(header or {}, items)
    supplier_name = _normalise_supplier_name(
        str(
            proposal.get("supplier_name")
            or (header or {}).get("supplierName")
            or _guess_supplier_from_filename(file_name or "")
            or ""
        ).strip()
    )

    existing_template = existing_template if isinstance(existing_template, dict) else {}
    if _template_header_value_is_placeholder("supplierName", supplier_name):
        supplier_name = _template_supplier_name_from_hit(existing_template)
    if not supplier_name:
        supplier_name = _normalise_supplier_name(_guess_supplier_from_filename(file_name or ""))
    if _template_header_value_is_placeholder("supplierName", supplier_name):
        supplier_name = ""
    if not supplier_name:
        raise ValueError("AI proposal is missing supplier_name.")

    cfg: Dict[str, Any] = {}
    if existing_template.get("config"):
        cfg = copy.deepcopy(existing_template.get("config") or {})
    elif existing_template.get("config_json"):
        try:
            cfg = json.loads(existing_template.get("config_json") or "{}")
        except Exception:
            cfg = {}
    if not isinstance(cfg, dict):
        cfg = {}
    if invoice_level_vat_repaired:
        cfg.setdefault("rules", {})
        if isinstance(cfg.get("rules"), dict):
            cfg["rules"]["invoice_level_vat_allocation"] = "allocate_header_vat_to_teacher_gross_rows"
    if isinstance(cfg.get("header_aliases"), dict):
        cfg["header_aliases"] = _normalise_template_alias_config(cfg.get("header_aliases"), _template_default_header_aliases())
    if isinstance(cfg.get("line_aliases"), dict):
        cfg["line_aliases"] = _normalise_template_alias_config(cfg.get("line_aliases"), _template_default_line_aliases())

    parser_type = _detect_parser_type_from_supplier(
        supplier_name,
        str(proposal.get("parser_type") or existing_template.get("parser_type") or "GENERIC"),
    )
    cfg["header_aliases"] = _normalise_template_alias_config(proposal.get("header_aliases"), _template_default_header_aliases())
    cfg["line_aliases"] = _normalise_template_alias_config(proposal.get("line_aliases"), _template_default_line_aliases())
    cfg["trusted_header_values"] = {
        **(cfg.get("trusted_header_values") if isinstance(cfg.get("trusted_header_values"), dict) else {}),
        **_template_trusted_header_values_from_header(header or {}),
        **_template_trusted_header_values_from_header({"supplierName": supplier_name, "customerName": (header or {}).get("customerName"), "currency": (header or {}).get("currency")}),
    }

    rules = proposal.get("rules") if isinstance(proposal.get("rules"), dict) else {}
    if rules:
        cfg["rules"] = {
            **(cfg.get("rules") if isinstance(cfg.get("rules"), dict) else {}),
            **copy.deepcopy(rules),
        }
    locale_profile = proposal.get("locale_profile") if isinstance(proposal.get("locale_profile"), dict) else {}
    if locale_profile:
        cfg["locale_profile"] = {
            **(cfg.get("locale_profile") if isinstance(cfg.get("locale_profile"), dict) else {}),
            **copy.deepcopy(locale_profile),
        }
    vat_map = proposal.get("vat_map") if isinstance(proposal.get("vat_map"), dict) else {}
    if vat_map:
        cleaned_vat_map = {}
        for k, v in vat_map.items():
            try:
                if str(k or "").strip():
                    cleaned_vat_map[str(k).strip().upper()] = float(v)
            except Exception:
                continue
        if cleaned_vat_map:
            cfg["vat_map"] = cleaned_vat_map

    learned_agent = _learn_template_agent_from_corrections(items or [], raw_text or "")
    if learned_agent:
        cfg["template_agent"] = {
            **(cfg.get("template_agent") if isinstance(cfg.get("template_agent"), dict) else {}),
            **learned_agent,
        }
    learned_table_profile = proposal.get("table_profile") if isinstance(proposal.get("table_profile"), dict) else {}
    if not learned_table_profile:
        learned_table_profile = _template_table_profile_from_text_and_items(items or [], raw_text or "")
    if learned_table_profile:
        cfg["table_profile"] = {
            **(cfg.get("table_profile") if isinstance(cfg.get("table_profile"), dict) else {}),
            **copy.deepcopy(learned_table_profile),
        }
    if max_pages_pdf:
        cfg["max_pages_pdf"] = int(max_pages_pdf)

    _store_gemini_teacher_output_from_items(cfg, header or {}, items or [])

    cfg["ai_template_agent"] = {
        "last_suggested_at": _uk_now_iso(),
        "model": str(proposal.get("_agent_model") or ""),
        "notes": [str(x) for x in (proposal.get("notes") or []) if str(x).strip()][:8],
        "doc_type": str(doc_type or ""),
    }

    keywords: List[str] = []
    try:
        if existing_template.get("match_keywords_json"):
            keywords.extend(json.loads(existing_template.get("match_keywords_json") or "[]") or [])
        elif existing_template.get("match_keywords"):
            keywords.extend(existing_template.get("match_keywords") or [])
    except Exception:
        pass
    if isinstance(proposal.get("match_keywords"), list):
        keywords.extend(proposal.get("match_keywords") or [])
    keywords.extend(_template_keywords(supplier_name, [str((header or {}).get("customerName") or ""), file_name or ""]))
    dedup_keywords: List[str] = []
    seen_kw = set()
    for keyword in keywords:
        kw = _collapse_spaces(str(keyword or "").strip())
        if len(kw) < 3:
            continue
        key = kw.casefold()
        if key in seen_kw:
            continue
        seen_kw.add(key)
        dedup_keywords.append(kw)

    return {
        "template_id": str(existing_template.get("template_id") or ""),
        "display_id": str(existing_template.get("display_id") or ""),
        "supplier_name": supplier_name,
        "parser_type": parser_type,
        "vat_number": str(existing_template.get("vat_number") or ""),
        "awrs_number": str(existing_template.get("awrs_number") or ""),
        "requires_cloud": 1 if bool(proposal.get("requires_cloud")) or bool(existing_template.get("requires_cloud")) else 0,
        "match_keywords": dedup_keywords,
        "config": _template_enrich_supplier_config(
            cfg,
            supplier_name=supplier_name,
            parser_type=parser_type,
            raw_text=raw_text or "",
            header=header or {},
            items=items or [],
            doc_type=doc_type,
            aliases=dedup_keywords,
        ),
        "created_at": str(existing_template.get("created_at") or ""),
    }


def _find_existing_supplier_template_for_training(raw_text: str, header: Dict[str, Any], file_name: str) -> Dict[str, Any]:
    supplier_name = _normalise_supplier_name(str((header or {}).get("supplierName") or "").strip())
    supplier_key = _template_supplier_key(supplier_name)
    if not supplier_key:
        return {}
    rows = _db_fetchall(
        """SELECT * FROM supplier_templates
             WHERE UPPER(TRIM(supplier_name))=UPPER(TRIM(?))
             ORDER BY COALESCE(NULLIF(updated_at,''), NULLIF(created_at,'')) DESC""",
        (supplier_name,),
    )
    for row in rows or []:
        candidate = _db_get_template("supplier_templates", str(dict(row).get("template_id") or "")) or {}
        if _template_supplier_key(str(candidate.get("supplier_name") or "")) == supplier_key:
            return candidate
    # OCR/Gemini can vary punctuation/plurals or make a one-character typo in
    # the supplier name. Reuse the existing supplier-family template instead of
    # creating a duplicate row for the typo.
    fuzzy_rows = _db_fetchall(
        """SELECT * FROM supplier_templates
             ORDER BY COALESCE(NULLIF(updated_at,''), NULLIF(created_at,'')) DESC"""
    )
    fuzzy_candidates: List[Tuple[bool, Dict[str, Any]]] = []
    for row in fuzzy_rows or []:
        candidate_id = str(dict(row).get("template_id") or "")
        candidate = _db_get_template("supplier_templates", candidate_id) or {}
        candidate_supplier = _normalise_supplier_name(str(candidate.get("supplier_name") or "").strip())
        if _template_supplier_keys_likely_same(supplier_name, candidate_supplier):
            fuzzy_candidates.append(
                (
                    _template_display_id_matches_supplier(
                        str(candidate.get("display_id") or ""),
                        candidate_supplier,
                    ),
                    candidate,
                )
            )
    if fuzzy_candidates:
        fuzzy_candidates.sort(key=lambda item: 0 if item[0] else 1)
        return fuzzy_candidates[0][1]
    # Training must never borrow a template merely because the same customer,
    # invoice filename, or layout text occurred on another supplier's invoice.
    return {}


def _gdocai_setting(settings: Dict[str, Any], key: str, legacy_key: str = "") -> Any:
    if key in settings and settings.get(key) not in (None, ""):
        return settings.get(key)
    if legacy_key and legacy_key in settings and settings.get(legacy_key) not in (None, ""):
        return settings.get(legacy_key)
    return ""


def _gdocai_enabled(settings: Dict[str, Any]) -> bool:
    return bool(settings.get("gdocai_enabled", False) or settings.get("document_ai_enabled", False))


def _gdocai_credentials_json(settings: Dict[str, Any]) -> str:
    raw = str(_gdocai_setting(settings, "gdocai_credentials_json") or "").strip()
    if raw:
        return raw
    enc = str(_gdocai_setting(settings, "document_ai_sa_json_b64") or "").strip()
    if not enc:
        return ""
    try:
        return base64.b64decode(enc.encode("utf-8")).decode("utf-8")
    except Exception:
        return ""


def _gdocai_is_configured(settings: Dict[str, Any]) -> bool:
    project_id = str(_gdocai_setting(settings, "gdocai_project_id", "document_ai_project_id") or "").strip()
    location = str(_gdocai_setting(settings, "gdocai_location", "document_ai_location") or "").strip()
    processor_id = str(_gdocai_setting(settings, "gdocai_processor_id", "document_ai_processor_id") or "").strip()
    ocr_processor_id = _gdocai_ocr_processor_id(settings)
    return bool(_gdocai_enabled(settings) and project_id and location and (processor_id or ocr_processor_id))


def _gdocai_invoice_parser_configured(settings: Dict[str, Any]) -> bool:
    project_id = str(_gdocai_setting(settings, "gdocai_project_id", "document_ai_project_id") or "").strip()
    location = str(_gdocai_setting(settings, "gdocai_location", "document_ai_location") or "").strip()
    processor_id = str(_gdocai_setting(settings, "gdocai_processor_id", "document_ai_processor_id") or "").strip()
    return bool(_gdocai_enabled(settings) and project_id and location and processor_id)


def _gdocai_ocr_processor_id(settings: Dict[str, Any]) -> str:
    return str(_gdocai_setting(settings, "gdocai_ocr_processor_id", "document_ai_ocr_processor_id") or "").strip()


def _gdocai_text_anchor_text(anchor: Any, full_text: str) -> str:
    try:
        segments = list(getattr(anchor, "text_segments", []) or [])
        if not segments:
            return ""
        parts: List[str] = []
        for seg in segments:
            start = int(getattr(seg, "start_index", 0) or 0)
            end = int(getattr(seg, "end_index", 0) or 0)
            if end > start:
                parts.append(full_text[start:end])
        return " ".join(p.strip() for p in parts if str(p).strip()).strip()
    except Exception:
        return ""


def _gdocai_layout_bbox(layout: Any, page: Any) -> Optional[List[float]]:
    try:
        poly = getattr(layout, "bounding_poly", None)
        if poly is None:
            return None
        verts = list(getattr(poly, "normalized_vertices", []) or [])
        width = float(getattr(getattr(page, "dimension", None), "width", 0.0) or 0.0)
        height = float(getattr(getattr(page, "dimension", None), "height", 0.0) or 0.0)
        coords: List[Tuple[float, float]] = []
        if verts and width > 0 and height > 0:
            for v in verts:
                coords.append((float(getattr(v, "x", 0.0) or 0.0) * width, float(getattr(v, "y", 0.0) or 0.0) * height))
        else:
            verts = list(getattr(poly, "vertices", []) or [])
            for v in verts:
                coords.append((float(getattr(v, "x", 0.0) or 0.0), float(getattr(v, "y", 0.0) or 0.0)))
        if not coords:
            return None
        xs = [c[0] for c in coords]
        ys = [c[1] for c in coords]
        return [min(xs), min(ys), max(xs), max(ys)]
    except Exception:
        return None


def _gdocai_money_to_float(money_value: Any) -> float:
    try:
        units = float(getattr(money_value, "units", 0) or 0)
        nanos = float(getattr(money_value, "nanos", 0) or 0)
        return units + (nanos / 1_000_000_000.0)
    except Exception:
        return 0.0


def _gdocai_entity_currency(entity: Any) -> str:
    try:
        norm = getattr(entity, "normalized_value", None)
        mv = getattr(norm, "money_value", None) if norm is not None else None
        cur = str(getattr(mv, "currency_code", "") or "").strip()
        return cur
    except Exception:
        return ""


def _gdocai_entity_value(entity: Any, full_text: str) -> str:
    try:
        mention = str(getattr(entity, "mention_text", "") or "").strip()
        norm = getattr(entity, "normalized_value", None)
        if norm is not None:
            try:
                date_value = getattr(norm, "date_value", None)
                if date_value is not None:
                    y = int(getattr(date_value, "year", 0) or 0)
                    m = int(getattr(date_value, "month", 0) or 0)
                    d = int(getattr(date_value, "day", 0) or 0)
                    if y and m and d:
                        return f"{y:04d}-{m:02d}-{d:02d}"
            except Exception:
                pass
            try:
                money_value = getattr(norm, "money_value", None)
                if money_value is not None:
                    mv = _gdocai_money_to_float(money_value)
                    if mv != 0.0 or not mention:
                        return str(mv)
            except Exception:
                pass
            for attr in ("text", "float_value", "integer_value", "boolean_value"):
                try:
                    val = getattr(norm, attr, None)
                    if val in (None, ""):
                        continue
                    # Document AI proto wrappers often expose default numeric values (0 / 0.0)
                    # even when the entity should be read from mention_text. Avoid converting
                    # identifiers and totals into fake zeros.
                    if attr in ("float_value", "integer_value") and mention:
                        try:
                            if float(val) == 0.0:
                                continue
                        except Exception:
                            pass
                    if attr == "boolean_value" and mention:
                        continue
                    if str(val).strip():
                        return str(val)
                except Exception:
                    pass
        if mention:
            return mention
        return _gdocai_text_anchor_text(getattr(entity, "text_anchor", None), full_text)
    except Exception:
        return ""


def _gdocai_entity_debug(entity: Any, full_text: str) -> Dict[str, Any]:
    info: Dict[str, Any] = {
        "type": str(getattr(entity, "type_", "") or "").split("/")[-1].strip(),
        "mention_text": str(getattr(entity, "mention_text", "") or "").strip(),
        "confidence": float(getattr(entity, "confidence", 0.0) or 0.0),
    }
    try:
        info["value"] = _gdocai_entity_value(entity, full_text)
    except Exception:
        info["value"] = ""
    return info


def _gdocai_line_item_debug(entity: Any, full_text: str) -> Dict[str, Any]:
    info: Dict[str, Any] = {
        "type": "line_item",
        "confidence": float(getattr(entity, "confidence", 0.0) or 0.0),
        "properties": [],
    }
    try:
        props = []
        for prop in list(getattr(entity, "properties", []) or []):
            props.append(
                {
                    "type": str(getattr(prop, "type_", "") or "").split("/")[-1].strip(),
                    "mention_text": str(getattr(prop, "mention_text", "") or "").strip(),
                    "value": _gdocai_entity_value(prop, full_text),
                    "confidence": float(getattr(prop, "confidence", 0.0) or 0.0),
                }
            )
        info["properties"] = props
    except Exception:
        pass
    return info


def _gdocai_summary_line(description: str, code: str) -> bool:
    text = " ".join([str(description or "").strip(), str(code or "").strip()]).upper()
    if not text:
        return False
    return bool(
        re.search(
            r"\b(TOTAL|SUBTOTAL|SUB-TOTAL|VAT|TAX|AMOUNT\s+DUE|BALANCE|INVOICE\s+TOTAL|NET\s+AMOUNT|TOTAL\s+AMOUNT)\b",
            text,
            flags=re.I,
        )
    )


def _gdocai_normalize_item(item: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    out = dict(item or {})
    out["code"] = " ".join(str(out.get("code") or "").split()).strip()
    out["description"] = " ".join(str(out.get("description") or "").split()).strip()
    out["casePack"] = " ".join(str(out.get("casePack") or "").split()).strip()
    out["unitSize"] = " ".join(str(out.get("unitSize") or "").split()).strip()

    qty = _safe_float(out.get("qty"))
    unit_price = _safe_float(out.get("unitPrice"))
    line_net = _safe_float(out.get("lineNet"))
    vat_rate = _safe_float(out.get("vatRate"))
    vat_amount = _safe_float(out.get("vatAmount"))
    line_gross = _safe_float(out.get("lineGross"))

    # Some Invoice Parser outputs place a product code into quantity.
    if (not out.get("code")) and qty >= 10000 and float(int(qty)) == float(qty):
        out["code"] = str(int(qty))
        qty = 0.0

    # Remove likely summary/footer rows from the line-item array.
    if _gdocai_summary_line(str(out.get("description") or ""), str(out.get("code") or "")):
        return None

    # Repair common math fields.
    if qty > 1000 and unit_price > 0 and line_net > 0:
        derived_qty = line_net / unit_price
        if 0 < derived_qty < 1000:
            qty = round(derived_qty, 3)
    if qty <= 0 and unit_price > 0 and line_net > 0:
        derived_qty = line_net / unit_price
        if derived_qty > 0:
            qty = round(derived_qty, 3)
    if unit_price <= 0 and qty > 0 and line_net > 0:
        unit_price = round(line_net / qty, 4)
    if line_net <= 0 and qty > 0 and unit_price > 0:
        line_net = round(qty * unit_price, 2)
    if vat_amount <= 0 and line_gross > line_net > 0:
        vat_amount = round(line_gross - line_net, 2)
    if line_gross <= 0 and line_net > 0:
        line_gross = round(line_net + max(vat_amount, 0.0), 2)
    if vat_rate <= 0 and line_net > 0 and vat_amount > 0:
        vat_rate = round((vat_amount / line_net) * 100.0, 4)
    if 0 < vat_rate <= 1.0:
        vat_rate = round(vat_rate * 100.0, 4)
        if line_net > 0:
            vat_amount = round(line_net * (vat_rate / 100.0), 2)
            line_gross = round(line_net + vat_amount, 2)

    out["qty"] = qty
    out["unitPrice"] = unit_price
    out["lineNet"] = line_net
    out["vatRate"] = vat_rate
    out["vatAmount"] = vat_amount
    out["lineGross"] = line_gross

    has_identity = bool(out.get("description") or out.get("code"))
    has_money = any(x > 0 for x in (line_net, line_gross, unit_price, vat_amount))
    if not has_identity and not has_money:
        return None
    # Drop extremely weak rows that have no identifying text and only one numeric fragment.
    positive_fields = sum(1 for x in (qty, unit_price, line_net, vat_amount, line_gross) if x > 0)
    if (not has_identity) and positive_fields <= 1:
        return None

    return out


def _gdocai_items_look_grouped(items: List[Dict[str, Any]]) -> bool:
    rows = [dict(it) for it in (items or []) if isinstance(it, dict)]
    if not rows:
        return False
    grouped_desc = 0
    weak_vat_rows = 0
    for it in rows:
        desc = str(it.get("description") or "")
        if desc.count("\n") >= 1 or len(desc) > 90:
            grouped_desc += 1
        if _safe_float(it.get("vatAmount")) <= 0 and _safe_float(it.get("lineGross")) <= _safe_float(it.get("lineNet")):
            weak_vat_rows += 1
    total = max(len(rows), 1)
    return (grouped_desc / total) >= 0.20 or (weak_vat_rows / total) >= 0.80


def _header_totals_sane(hdr: Dict[str, Any]) -> bool:
    gross = _safe_float((hdr or {}).get("totalGross"))
    net = _safe_float((hdr or {}).get("totalNet"))
    vat = _safe_float((hdr or {}).get("totalVat"))
    if gross <= 0:
        return False
    if net > 0 and vat >= 0:
        return abs((net + vat) - gross) <= 2.0
    return True


def _header_has_core_identity(hdr: Dict[str, Any]) -> bool:
    return all(
        bool(str((hdr or {}).get(key) or "").strip())
        for key in ("supplierName", "invoiceNumber", "invoiceDate")
    )


def _header_degrades_local(local_header: Dict[str, Any], candidate_header: Dict[str, Any]) -> bool:
    local_h = dict(local_header or {})
    cand_h = dict(candidate_header or {})
    if not local_h:
        return False
    local_info = _header_information_score(local_h)
    cand_info = _header_information_score(cand_h)
    local_gross = _safe_float(local_h.get("totalGross"))
    cand_gross = _safe_float(cand_h.get("totalGross"))
    if local_gross > 0 and cand_gross <= 0:
        return True
    if _header_has_core_identity(local_h) and not _header_has_core_identity(cand_h):
        return True
    if local_info >= 5 and cand_info <= max(2, local_info - 3):
        return True
    return False


def _best_numeric_header(local_header: Dict[str, Any], google_header: Dict[str, Any], items: List[Dict[str, Any]]) -> Dict[str, Any]:
    local_h = dict(local_header or {})
    google_h = dict(google_header or {})
    # Repair obvious Google arithmetic drift first.
    if _safe_float(google_h.get("totalGross")) > 0 and _safe_float(google_h.get("totalVat")) > 0:
        net_guess = round(_safe_float(google_h.get("totalGross")) - _safe_float(google_h.get("totalVat")), 2)
        if net_guess > 0 and abs(net_guess - _safe_float(google_h.get("totalNet"))) > 2.0:
            google_h["totalNet"] = net_guess

    candidates = []
    for label, hdr in (("local", local_h), ("google", google_h)):
        try:
            m = _calc_metrics(hdr, _reconciliation_items(hdr, [dict(it) for it in (items or [])], ""))
            diff = max(abs(_safe_float(m.get("diff_net"))), abs(_safe_float(m.get("diff_vat"))), abs(_safe_float(m.get("diff_gross"))))
        except Exception:
            diff = 1e9
        total_fields = sum(1 for key in ("totalNet", "totalVat", "totalGross") if _safe_float((hdr or {}).get(key)) > 0)
        identity_fields = sum(1 for key in ("supplierName", "invoiceNumber", "invoiceDate") if str((hdr or {}).get(key) or "").strip())
        sane = _header_totals_sane(hdr)
        candidates.append((0 if total_fields > 0 else 1, 0 if sane else 1, diff, -identity_fields, label, hdr))
    candidates.sort(key=lambda t: (t[0], t[1], t[2], t[3]))
    return dict(candidates[0][5] or {})


def _gdocai_supplier_family(*texts: str) -> str:
    blob = "\n".join(str(t or "") for t in texts).upper()
    if "BOOKER" in blob:
        return "BOOKER"
    if "DHAMECHA" in blob:
        return "DHAMECHA"
    if "PARFETTS" in blob:
        return "PARFETTS"
    if "DRINKS WHOLESALE" in blob or re.search(r"\bDWG\b", blob):
        return "DWG"
    return ""


def _gdocai_header_for_items(
    local_header: Dict[str, Any],
    google_header: Dict[str, Any],
    items: List[Dict[str, Any]],
) -> Dict[str, Any]:
    best_numeric = _best_numeric_header(local_header or {}, google_header or {}, items or [])
    merged = _merge_google_header(best_numeric, google_header or {})
    for meta_key in ("supplierName", "customerName", "invoiceNumber", "invoiceDate", "currency"):
        if str((google_header or {}).get(meta_key) or "").strip():
            merged[meta_key] = (google_header or {}).get(meta_key)
    return merged


def _gdocai_build_parse_text(header: Dict[str, Any], items: List[Dict[str, Any]], raw_text: str) -> str:
    parts: List[str] = []
    supplier = str((header or {}).get("supplierName") or "").strip()
    customer = str((header or {}).get("customerName") or (header or {}).get("shipToAddress") or "").strip()
    inv_no = str((header or {}).get("invoiceNumber") or "").strip()
    inv_dt = str((header or {}).get("invoiceDate") or "").strip()
    if supplier:
        parts.append(supplier)
    if customer:
        parts.append(f"CUSTOMER 0000 {customer}")
    if inv_no:
        parts.append(f"INVOICE NUMBER {inv_no}")
    if inv_dt:
        parts.append(f"DATE {inv_dt}")
    for it in (items or []):
        if not isinstance(it, dict):
            continue
        code = str(it.get("code") or "").strip()
        desc = str(it.get("description") or "").strip()
        qty = _safe_float(it.get("qty"))
        unit_price = _safe_float(it.get("unitPrice"))
        line_net = _safe_float(it.get("lineNet"))
        line = " ".join(
            x for x in [
                code,
                desc.replace("\n", " ").strip(),
                (str(int(qty)) if qty and float(int(qty)) == qty else (f"{qty:g}" if qty else "")),
                (f"{unit_price:.2f}" if unit_price > 0 else ""),
                (f"{line_net:.2f}" if line_net > 0 else ""),
            ] if x
        ).strip()
        if line:
            parts.append(line)
    if raw_text:
        parts.append(raw_text)
    return "\n".join(p for p in parts if p).strip()


def _candidate_diff(header: Dict[str, Any], items: List[Dict[str, Any]]) -> float:
    try:
        m = _calc_metrics(header or {}, _reconciliation_items(header or {}, [dict(it) for it in (items or [])], ""))
        return max(
            abs(_safe_float(m.get("diff_net"))),
            abs(_safe_float(m.get("diff_vat"))),
            abs(_safe_float(m.get("diff_gross"))),
        )
    except Exception:
        return 1e9


def _select_best_invoice_candidate(candidates: List[Tuple[str, Dict[str, Any], List[Dict[str, Any]]]]) -> Tuple[str, Dict[str, Any], List[Dict[str, Any]]]:
    scored: List[Tuple[float, int, str, Dict[str, Any], List[Dict[str, Any]]]] = []
    for label, hdr, rows in candidates:
        diff = _candidate_diff(hdr, rows)
        row_count = len(rows or [])
        scored.append((diff, -row_count, label, hdr, rows))
    scored.sort(key=lambda t: (t[0], t[1]))
    best = scored[0]
    return best[2], best[3], best[4]


def _gdocai_line_item_from_entity(entity: Any, full_text: str, line_no: int) -> Dict[str, Any]:
    item: Dict[str, Any] = {
        "lineNo": int(line_no),
        "code": "",
        "description": "",
        "casePack": "",
        "unitSize": "",
        "qty": 0.0,
        "unitPrice": 0.0,
        "lineNet": 0.0,
        "vatRate": 0.0,
        "vatAmount": 0.0,
        "lineGross": 0.0,
    }
    prop_aliases = {
        "description": "description",
        "product_code": "code",
        "item_code": "code",
        "sku": "code",
        "quantity": "qty",
        "unit_price": "unitPrice",
        "amount": "lineNet",
        "net_amount": "lineNet",
        "subtotal": "lineNet",
        "tax_amount": "vatAmount",
        "tax": "vatRate",
        "tax_rate": "vatRate",
        "total_amount": "lineGross",
        "gross_amount": "lineGross",
        "unit": "unitSize",
        "uom": "unitSize",
        "pack": "casePack",
        "case_pack": "casePack",
    }
    for prop in list(getattr(entity, "properties", []) or []):
        leaf = str(getattr(prop, "type_", "") or "").split("/")[-1].strip().lower()
        field = prop_aliases.get(leaf)
        if not field:
            continue
        raw_val = _gdocai_entity_value(prop, full_text)
        if field in ("qty", "unitPrice", "lineNet", "vatRate", "vatAmount", "lineGross"):
            num_val = _safe_float(raw_val)
            if num_val <= 0:
                mention_val = _safe_float(str(getattr(prop, "mention_text", "") or "").strip())
                if mention_val > 0:
                    num_val = mention_val
            item[field] = num_val
        else:
            val_txt = str(raw_val or "").strip()
            if val_txt in ("0", "0.0", "False", "false"):
                mention_txt = str(getattr(prop, "mention_text", "") or "").strip()
                if mention_txt:
                    val_txt = mention_txt
            item[field] = val_txt
    if _safe_float(item.get("lineGross")) <= 0 and (_safe_float(item.get("lineNet")) > 0 or _safe_float(item.get("vatAmount")) > 0):
        item["lineGross"] = _safe_float(item.get("lineNet")) + _safe_float(item.get("vatAmount"))
    if _safe_float(item.get("lineNet")) <= 0 and _safe_float(item.get("lineGross")) > 0 and _safe_float(item.get("vatAmount")) >= 0:
        item["lineNet"] = max(0.0, _safe_float(item.get("lineGross")) - _safe_float(item.get("vatAmount")))
    return _gdocai_normalize_item(item) or {}


class GoogleDocumentAIInvoiceExtractor:
    def __init__(self, project_id: str, location: str, processor_id: str, credentials_json: str = ""):
        self.project_id = str(project_id or "").strip()
        self.location = str(location or "").strip()
        self.processor_id = str(processor_id or "").strip()
        self.credentials_json = str(credentials_json or "").strip()

    def is_available(self) -> bool:
        return bool(self.project_id and self.location and self.processor_id)

    def extract_purchase_invoice(self, file_bytes: bytes, mime_type: str, file_name: str, doc_text: str = "") -> Dict[str, Any]:
        try:
            from google.cloud import documentai  # type: ignore
            from google.oauth2 import service_account  # type: ignore

            client_opts = {"api_endpoint": f"{self.location}-documentai.googleapis.com"}
            if self.credentials_json:
                info = json.loads(self.credentials_json)
                creds = service_account.Credentials.from_service_account_info(info)
                client = documentai.DocumentProcessorServiceClient(credentials=creds, client_options=client_opts)
            else:
                client = documentai.DocumentProcessorServiceClient(client_options=client_opts)

            processor_name = f"projects/{self.project_id}/locations/{self.location}/processors/{self.processor_id}"
            raw_document = documentai.RawDocument(content=file_bytes, mime_type=mime_type)
            request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)
            result = client.process_document(request=request)
            document = getattr(result, "document", None)
            full_text = str(getattr(document, "text", "") or "")
            entities = list(getattr(document, "entities", []) or [])

            header: Dict[str, Any] = {
                "supplierName": "",
                "customerName": "",
                "invoiceNumber": "",
                "invoiceDate": "",
                "currency": "",
                "totalNet": 0.0,
                "totalVat": 0.0,
                "totalGross": 0.0,
            }
            items: List[Dict[str, Any]] = []
            debug_entities: List[Dict[str, Any]] = []
            debug_line_items: List[Dict[str, Any]] = []

            header_aliases = {
                "supplier_name": "supplierName",
                "vendor_name": "supplierName",
                "vendor": "supplierName",
                "seller_name": "supplierName",
                "seller": "supplierName",
                "issuer_name": "supplierName",
                "receiver_name": "customerName",
                "buyer_name": "customerName",
                "buyer": "customerName",
                "customer_name": "customerName",
                "customer": "customerName",
                "bill_to_name": "customerName",
                "ship_to_name": "customerName",
                "invoice_id": "invoiceNumber",
                "invoice_number": "invoiceNumber",
                "invoice_no": "invoiceNumber",
                "document_number": "invoiceNumber",
                "invoice_date": "invoiceDate",
                "date": "invoiceDate",
                "currency": "currency",
                "net_amount": "totalNet",
                "invoice_net_amount": "totalNet",
                "subtotal_amount": "totalNet",
                "subtotal": "totalNet",
                "total_tax_amount": "totalVat",
                "tax_amount": "totalVat",
                "vat_amount": "totalVat",
                "total_amount": "totalGross",
                "invoice_total": "totalGross",
                "amount_due": "totalGross",
                "gross_amount": "totalGross",
            }
            numeric_fields = {"totalNet", "totalVat", "totalGross"}

            for entity in entities:
                if len(debug_entities) < 20:
                    debug_entities.append(_gdocai_entity_debug(entity, full_text))
                leaf = str(getattr(entity, "type_", "") or "").split("/")[-1].strip().lower()
                if leaf == "line_item":
                    if len(debug_line_items) < 5:
                        debug_line_items.append(_gdocai_line_item_debug(entity, full_text))
                    line_item = _gdocai_line_item_from_entity(entity, full_text, len(items) + 1)
                    if line_item and (
                        any(
                            str(line_item.get(key) or "").strip()
                            for key in ("code", "description", "casePack", "unitSize")
                        )
                        or any(_safe_float(line_item.get(key)) > 0 for key in ("qty", "unitPrice", "lineNet", "vatAmount", "lineGross"))
                    ):
                        items.append(line_item)
                    continue

                field = header_aliases.get(leaf)
                if not field:
                    continue
                value = _gdocai_entity_value(entity, full_text)
                if field in numeric_fields:
                    num_val = _safe_float(value)
                    if num_val <= 0:
                        mention_num = _safe_float(str(getattr(entity, "mention_text", "") or "").strip())
                        if mention_num > 0:
                            num_val = mention_num
                    if num_val > 0:
                        header[field] = num_val
                else:
                    txt_val = str(value or "").strip()
                    if txt_val in ("0", "0.0", "False", "false"):
                        mention_txt = str(getattr(entity, "mention_text", "") or "").strip()
                        if mention_txt:
                            txt_val = mention_txt
                    if txt_val:
                        header[field] = txt_val
                if field == "currency" and not str(header.get("currency") or "").strip():
                    header["currency"] = _gdocai_entity_currency(entity)
                elif field in ("totalNet", "totalVat", "totalGross") and not str(header.get("currency") or "").strip():
                    header["currency"] = _gdocai_entity_currency(entity)

            if _safe_float(header.get("totalGross")) <= 0 and (_safe_float(header.get("totalNet")) > 0 or _safe_float(header.get("totalVat")) > 0):
                header["totalGross"] = _safe_float(header.get("totalNet")) + _safe_float(header.get("totalVat"))
            if _safe_float(header.get("totalNet")) <= 0 and _safe_float(header.get("totalGross")) > 0 and _safe_float(header.get("totalVat")) >= 0:
                header["totalNet"] = max(0.0, _safe_float(header.get("totalGross")) - _safe_float(header.get("totalVat")))

            if (
                not str(header.get("supplierName") or "").strip()
                and not str(header.get("invoiceNumber") or "").strip()
                and not items
            ):
                try:
                    sample_types = []
                    for ent in entities[:30]:
                        typ = str(getattr(ent, "type_", "") or "").strip()
                        mention = _collapse_spaces(str(getattr(ent, "mention_text", "") or "")).strip()
                        sample_types.append(f"{typ}={mention[:40]}")
                    _log_event(
                        "GoogleDocumentAI returned no mapped fields "
                        f"entity_count={len(entities)} text_len={len(full_text)} "
                        f"sample_entities={' | '.join(sample_types) if sample_types else 'none'}",
                        file_name=file_name,
                    )
                except Exception:
                    pass

            return {
                "header": header,
                "items": items,
                "raw_text": full_text or (doc_text or ""),
                "debug_text": full_text or (doc_text or ""),
                "debug_entities": debug_entities,
                "debug_line_items": debug_line_items,
            }
        except Exception as e:
            _log_event(f"GoogleDocumentAIInvoiceExtractor error: {e}", file_name=file_name)
        return {"header": {}, "items": [], "raw_text": doc_text or "", "debug_text": doc_text or "", "debug_entities": [], "debug_line_items": []}


class GoogleDocumentAIOcrExtractor:
    def __init__(self, project_id: str, location: str, processor_id: str, credentials_json: str = ""):
        self.project_id = str(project_id or "").strip()
        self.location = str(location or "").strip()
        self.processor_id = str(processor_id or "").strip()
        self.credentials_json = str(credentials_json or "").strip()

    def is_available(self) -> bool:
        return bool(self.project_id and self.location and self.processor_id)

    def extract_text(self, file_bytes: bytes, mime_type: str, file_name: str, doc_text: str = "") -> Dict[str, Any]:
        try:
            from google.cloud import documentai  # type: ignore
            from google.oauth2 import service_account  # type: ignore

            client_opts = {"api_endpoint": f"{self.location}-documentai.googleapis.com"}
            if self.credentials_json:
                info = json.loads(self.credentials_json)
                creds = service_account.Credentials.from_service_account_info(info)
                client = documentai.DocumentProcessorServiceClient(credentials=creds, client_options=client_opts)
            else:
                client = documentai.DocumentProcessorServiceClient(client_options=client_opts)

            processor_name = f"projects/{self.project_id}/locations/{self.location}/processors/{self.processor_id}"
            raw_document = documentai.RawDocument(content=file_bytes, mime_type=mime_type)
            request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)
            result = client.process_document(request=request)
            document = getattr(result, "document", None)
            full_text = str(getattr(document, "text", "") or "")
            page_line_texts: List[str] = []
            ocr_lines: List[Dict[str, Any]] = []
            for page_idx, page in enumerate(list(getattr(document, "pages", []) or []), start=1):
                for line in list(getattr(page, "lines", []) or []):
                    layout = getattr(line, "layout", None)
                    txt = _gdocai_text_anchor_text(layout and getattr(layout, "text_anchor", None), full_text)
                    txt = str(txt or "").strip()
                    if txt:
                        page_line_texts.append(txt)
                        bbox = _gdocai_layout_bbox(layout, page)
                        if bbox:
                            ocr_lines.append({
                                "text": txt,
                                "bbox": bbox,
                                "page": int(page_idx),
                            })
            line_text = "\n".join(page_line_texts).strip()
            return {
                "raw_text": full_text or (doc_text or ""),
                "line_text": line_text,
                "ocr_lines": ocr_lines,
            }
        except Exception as e:
            _log_event(f"GoogleDocumentAIOcrExtractor error: {e}", file_name=file_name)
        return {"raw_text": doc_text or "", "line_text": "", "ocr_lines": []}


def _google_document_ai_zero_training_extract(
    settings: Dict[str, Any],
    file_bytes: bytes,
    mime_type: str,
    file_name: str,
    doc_type: str,
    doc_text: str = "",
) -> Dict[str, Any]:
    """Zero-training structured extraction using Google Cloud Document AI.

    This uses the configured prebuilt/custom Invoice Parser for entities and,
    when available, the OCR processor to enrich raw text/line boxes. No supplier
    template is required and no Gemini key is used.
    """
    if not _gdocai_invoice_parser_configured(settings):
        raise RuntimeError("Google Document AI invoice parser is not configured.")

    project_id = str(_gdocai_setting(settings, "gdocai_project_id", "document_ai_project_id") or "").strip()
    location = str(_gdocai_setting(settings, "gdocai_location", "document_ai_location") or "").strip()
    credentials_json = _gdocai_credentials_json(settings)
    processor_id = str(_gdocai_setting(settings, "gdocai_processor_id", "document_ai_processor_id") or "").strip()

    invoice_extractor = GoogleDocumentAIInvoiceExtractor(
        project_id=project_id,
        location=location,
        processor_id=processor_id,
        credentials_json=credentials_json,
    )
    data = invoice_extractor.extract_purchase_invoice(
        file_bytes,
        mime_type=mime_type,
        file_name=file_name,
        doc_text=doc_text,
    )
    header = dict((data or {}).get("header") or {})
    items = _ensure_line_numbers(
        [
            row
            for row in (_gdocai_normalize_item(dict(it)) for it in ((data or {}).get("items") or []) if isinstance(it, dict))
            if row
        ]
    )
    raw_text = str((data or {}).get("raw_text") or (data or {}).get("debug_text") or doc_text or "")
    line_text = ""
    ocr_lines: List[Dict[str, Any]] = []

    ocr_processor_id = _gdocai_ocr_processor_id(settings)
    if ocr_processor_id:
        try:
            ocr_extractor = GoogleDocumentAIOcrExtractor(
                project_id=project_id,
                location=location,
                processor_id=ocr_processor_id,
                credentials_json=credentials_json,
            )
            ocr_data = ocr_extractor.extract_text(
                file_bytes,
                mime_type=mime_type,
                file_name=file_name,
                doc_text=raw_text or doc_text,
            )
            if str((ocr_data or {}).get("raw_text") or "").strip():
                raw_text = str((ocr_data or {}).get("raw_text") or "")
            line_text = str((ocr_data or {}).get("line_text") or "")
            ocr_lines = list((ocr_data or {}).get("ocr_lines") or [])
        except Exception as e:
            _log_event(f"Google Document AI OCR enrichment failed: {e}", file_name=file_name)

    try:
        if raw_text:
            header = _apply_template_header_aliases(
                header,
                raw_text,
                _template_default_header_aliases(),
            )
    except Exception:
        pass

    try:
        if _is_purchase_like_doc_type(doc_type):
            header = _repair_header_totals_from_items(header, items, raw_text=raw_text or doc_text or "")
    except Exception:
        pass

    try:
        if _safe_float(header.get("totalGross")) <= 0 and (_safe_float(header.get("totalNet")) > 0 or _safe_float(header.get("totalVat")) > 0):
            header["totalGross"] = round(_safe_float(header.get("totalNet")) + _safe_float(header.get("totalVat")), 2)
        if _safe_float(header.get("totalNet")) <= 0 and _safe_float(header.get("totalGross")) > 0 and _safe_float(header.get("totalVat")) >= 0:
            header["totalNet"] = round(max(0.0, _safe_float(header.get("totalGross")) - _safe_float(header.get("totalVat"))), 2)
    except Exception:
        pass

    if not str(header.get("extractionMode") or "").strip():
        header["extractionMode"] = "Google Document AI Zero Training Agent"

    if (
        raw_text
        and not str(header.get("supplierName") or "").strip()
        and not str(header.get("invoiceNumber") or "").strip()
        and not items
    ):
        try:
            local_data = LocalInvoiceParser.parse(raw_text, doc_type=doc_type)
            local_header = dict((local_data or {}).get("header") or {})
            local_items = list((local_data or {}).get("items") or [])
            if local_header or local_items:
                header = _merge_google_header(local_header, header)
                items = _ensure_line_numbers(local_items)
                header["extractionMode"] = "Google Document AI OCR + DocMate Mapping Agent"
                try:
                    header = _repair_header_totals_from_items(header, items, raw_text=raw_text)
                except Exception:
                    pass
        except Exception as e:
            _log_event(f"Google Document AI text fallback mapping failed: {e}", file_name=file_name)

    return {
        "header": header,
        "items": items,
        "raw_text": raw_text or doc_text or "",
        "debug_text": raw_text or doc_text or "",
        "line_text": line_text,
        "ocr_lines": ocr_lines,
        "debug_entities": (data or {}).get("debug_entities") or [],
        "debug_line_items": (data or {}).get("debug_line_items") or [],
    }


def _merge_google_header(primary: Dict[str, Any], fallback: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(primary or {})
    for key in ("supplierName", "customerName", "invoiceNumber", "invoiceDate", "currency"):
        if not str(merged.get(key) or "").strip() and str((fallback or {}).get(key) or "").strip():
            merged[key] = fallback.get(key)
    for key in ("totalNet", "totalVat", "totalGross"):
        if _safe_float(merged.get(key)) <= 0 and _safe_float((fallback or {}).get(key)) > 0:
            merged[key] = _safe_float((fallback or {}).get(key))
    return merged


def _confidence_max_diff(assessment: Dict[str, Any]) -> float:
    try:
        metrics = dict((assessment or {}).get("metrics") or {})
        return max(
            abs(_safe_float(metrics.get("diff_net"))),
            abs(_safe_float(metrics.get("diff_vat"))),
            abs(_safe_float(metrics.get("diff_gross"))),
        )
    except Exception:
        return 0.0


def _header_information_score(hdr: Dict[str, Any]) -> int:
    score = 0
    for key in ("supplierName", "customerName", "invoiceNumber", "invoiceDate", "currency"):
        if str((hdr or {}).get(key) or "").strip():
            score += 1
    for key in ("totalNet", "totalVat", "totalGross"):
        if _safe_float((hdr or {}).get(key)) > 0:
            score += 1
    return score


def _header_meaningfully_differs(base_header: Dict[str, Any], candidate_header: Dict[str, Any]) -> bool:
    base_h = dict(base_header or {})
    cand_h = dict(candidate_header or {})
    for key in ("supplierName", "customerName", "invoiceNumber", "invoiceDate", "currency"):
        base_val = _collapse_spaces(str(base_h.get(key) or "")).strip()
        cand_val = _collapse_spaces(str(cand_h.get(key) or "")).strip()
        if cand_val and cand_val != base_val:
            return True
    for key in ("totalNet", "totalVat", "totalGross"):
        if abs(_safe_float(cand_h.get(key)) - _safe_float(base_h.get(key))) > 0.01:
            return True
    return False


_CLOUD_AUTHORITATIVE_HEADER_FIELDS = (
    "supplierName",
    "customerName",
    "invoiceNumber",
    "invoiceDate",
    "currency",
    "totalNet",
    "totalVat",
    "totalGross",
)


def _restore_cloud_authoritative_header(header: Dict[str, Any], cloud_header: Dict[str, Any]) -> Dict[str, Any]:
    """Keep direct Gemini header fields from being overwritten by template/local line repairs."""
    if not isinstance(header, dict) or not isinstance(cloud_header, dict):
        return header
    for field in _CLOUD_AUTHORITATIVE_HEADER_FIELDS:
        value = cloud_header.get(field)
        if field in {"totalNet", "totalVat", "totalGross"}:
            if _safe_float(value) > 0:
                header[field] = round(float(_safe_float(value)), 2)
            continue
        text_value = str(value or "").strip()
        if not text_value:
            continue
        if field == "invoiceDate":
            normalised = _normalise_invoice_date_str(text_value)
            header[field] = normalised or text_value
        else:
            header[field] = text_value
        if field == "customerName":
            header["customer_name"] = text_value
    return header


def _maybe_apply_google_document_ai_fallback(
    settings: Dict[str, Any],
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    doc_type: str,
    *,
    raw_text: str,
    engine_used: str,
    file_bytes: bytes,
    mime_type: str,
    file_name: str,
    template_hit: Optional[Dict[str, Any]] = None,
) -> Tuple[Dict[str, Any], List[Dict[str, Any]], str, str]:
    if not bool((settings or {}).get("auto_cloud_fallback_enabled", True)):
        return header, items, engine_used, raw_text
    if not _is_purchase_like_doc_type(doc_type):
        return header, items, engine_used, raw_text
    if str(engine_used or "").startswith("cloud_"):
        return header, items, engine_used, raw_text
    if not file_bytes:
        return header, items, engine_used, raw_text
    api_key = _get_google_api_key(settings or {})
    if not api_key:
        return header, items, engine_used, raw_text

    current_conf = _assess_extraction_confidence(
        header or {},
        items or [],
        doc_type,
        raw_text=raw_text or "",
        engine_used=engine_used or "",
    )
    current_score = int(current_conf.get("score") or 0)
    current_diff = _confidence_max_diff(current_conf)
    forced_reason = str((settings or {}).get("_worker_force_cloud_gemini_fallback") or "").strip()
    fallback_threshold = int(
        (settings or {}).get(
            "auto_cloud_fallback_threshold",
            (settings or {}).get("auto_confidence_review_threshold", 65),
        )
        or 65
    )
    reconciliation_diff_threshold = float((settings or {}).get("auto_cloud_fallback_reconciliation_diff", 5.0) or 5.0)
    weak_result = (
        bool(forced_reason)
        or bool(current_conf.get("blockers"))
        or current_score < fallback_threshold
        or not items
        or _safe_float((header or {}).get("totalGross")) <= 0
        or current_diff > reconciliation_diff_threshold
    )
    if not weak_result:
        return header, items, engine_used, raw_text

    try:
        extractor = CloudGeminiExtractor(
            api_key=api_key,
            model_name=(settings or {}).get("gemini_model", "gemini-3.6-flash"),
        )
        gemini_supplier_hint = ""
        try:
            hint_fn = globals().get("_template_gemini_instruction_text")
            if callable(hint_fn):
                gemini_supplier_hint = str(hint_fn(template_hit) or "")
        except Exception:
            gemini_supplier_hint = ""
        gemini_doc_text = (
            (gemini_supplier_hint + "\n\n" + (raw_text or "")).strip()
            if gemini_supplier_hint
            else (raw_text or "")
        )
        cloud = extractor.extract_purchase_invoice(
            file_bytes,
            mime_type,
            file_name,
            doc_text=gemini_doc_text,
        )
        cloud_header = cloud.get("header") or {}
        cloud_items = _recalc_items(copy.deepcopy(cloud.get("items") or []))
        if not cloud_header and not cloud_items:
            return header, items, engine_used, raw_text
        cloud_text = str(cloud.get("text") or raw_text or "").strip()
        cloud_conf = _assess_extraction_confidence(
            cloud_header,
            cloud_items,
            doc_type,
            raw_text=cloud_text or raw_text or "",
            engine_used="cloud_gemini",
        )
        cloud_score = int(cloud_conf.get("score") or 0)
        cloud_diff = _confidence_max_diff(cloud_conf)
        reconciliation_better = (
            current_diff > reconciliation_diff_threshold
            and bool(cloud_items)
            and (
                cloud_diff <= reconciliation_diff_threshold
                or cloud_diff <= max(reconciliation_diff_threshold, current_diff * 0.50)
            )
        )
        reconciliation_improved = (
            current_diff > reconciliation_diff_threshold
            and bool(cloud_items)
            and cloud_diff + 0.05 < current_diff
            and cloud_score >= max(45, current_score - 20)
            and _header_information_score(cloud_header) >= max(4, _header_information_score(header or {}) - 1)
        )
        forced_cloud_better = (
            bool(forced_reason)
            and bool(cloud_items)
            and (
                len(cloud_items) > len(items or [])
                or (
                    len(cloud_items) == len(items or [])
                    and cloud_score >= max(45, current_score - 10)
                    and not bool(cloud_conf.get("blockers"))
                )
            )
        )
        cloud_better = (
            forced_cloud_better
            or cloud_score >= current_score + 6
            or reconciliation_better
            or reconciliation_improved
            or (
                cloud_score >= current_score
                and cloud_diff + 0.05 < current_diff
                and bool(cloud_items)
            )
            or (bool(current_conf.get("blockers")) and not bool(cloud_conf.get("blockers")) and cloud_score >= current_score - 5)
        )
        if cloud_better:
            if forced_cloud_better:
                try:
                    cloud_header["_cloud_fallback_reason"] = forced_reason
                except Exception:
                    pass
            elif reconciliation_better:
                try:
                    cloud_header["_cloud_fallback_reason"] = "reconciliation_diff"
                except Exception:
                    pass
            elif reconciliation_improved:
                try:
                    cloud_header["_cloud_fallback_reason"] = "reconciliation_improved"
                except Exception:
                    pass
            cloud_header = _restore_cloud_authoritative_header(cloud_header or {}, cloud_header or {})
            _log_event(
                f"Gemini fallback used threshold={fallback_threshold} recon_threshold={reconciliation_diff_threshold:.2f} score={cloud_score} diff={cloud_diff:.2f} previous_score={current_score} previous_diff={current_diff:.2f}",
                file_name=file_name,
            )
            return cloud_header or header, cloud_items or items, "cloud_gemini", (cloud_text or raw_text)
    except Exception as e:
        _log_event(f"Gemini fallback skipped: {e}", file_name=file_name)
    return header, items, engine_used, raw_text


def _invoice_json_schema_purchase() -> Dict[str, Any]:
    """JSON Schema used to force strict model output for Purchase Invoices (Cloud Gemini)."""
    return {
        "type": "object",
        "required": ["header", "items"],
        "properties": {
            "header": {
                "type": "object",
                "properties": {
                    "supplierName": {"type": "string"},
                    "customerName": {"type": "string"},
                    "invoiceNumber": {"type": "string"},
                    "invoiceDate": {"type": "string"},
                    "currency": {"type": "string"},
                    "deliveryCharge": {"type": "number"},
                    "totalNet": {"type": "number"},
                    "totalVat": {"type": "number"},
                    "totalGross": {"type": "number"},
                },
                "additionalProperties": True,
            },
            "items": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "lineNo": {"type": "integer"},
                        "code": {"type": "string"},
                        "description": {"type": "string"},
                        "casePack": {"type": "string"},
                        "unitSize": {"type": "string"},
                        "qty": {"type": "number"},
                        "totalUnits": {"type": "number"},
                        "unitPrice": {"type": "number"},
                        "lineNet": {"type": "number"},
                        "vatRate": {"type": "number"},
                        "vatAmount": {"type": "number"},
                        "lineGross": {"type": "number"},
                        "stdRrp": {"type": "number"},
                        "por": {"type": "number"},
                    },
                    "additionalProperties": True,
                },
            },
        },
        "additionalProperties": True,
    }


def _parse_json_from_model(raw: str) -> Dict[str, Any]:
    if not raw:
        return {"header": {}, "items": []}
    s = raw.strip()
    # Remove markdown fences if present
    s = re.sub(r"^```(?:json)?", "", s, flags=re.I).strip()
    s = re.sub(r"```$", "", s).strip()
    # Try direct
    try:
        d = json.loads(s)
        if isinstance(d, dict):
            return d
    except Exception:
        pass
    # Try to extract first {...} block
    try:
        m = re.search(r"\{.*\}", s, flags=re.S)
        if m:
            d = json.loads(m.group(0))
            if isinstance(d, dict):
                return d
    except Exception:
        pass
    return {"header": {}, "items": []}


