# Register save / load
# -------------------------


def _make_inv_key(header: Dict[str, Any], file_bytes: bytes, doc_type: str) -> str:
    sup = (header.get("supplierName") or "").strip().upper()
    cus = (header.get("customerName") or "").strip().upper()
    inv = (header.get("invoiceNumber") or "").strip().upper()
    dt = (_normalise_invoice_date_str(header.get("invoiceDate") or "") or (header.get("invoiceDate") or "").strip())
    base = f"{doc_type}|{sup}|{cus}|{inv}|{dt}|{_sha256_bytes(file_bytes)[:12]}"
    return hashlib.sha256(base.encode("utf-8")).hexdigest()



def _ensure_line_numbers(items: Any) -> List[Dict[str, Any]]:
    """
    Preserve document line numbers and assign missing positive line numbers.
    Applies to *all* suppliers so CSV exports and UI editing are consistent.
    """
    try:
        if pd is not None and isinstance(items, pd.DataFrame):
            items = items.to_dict("records")
    except Exception:
        pass
    if isinstance(items, dict):
        try:
            if all(isinstance(v, dict) for v in items.values()):
                items = list(items.values())
            else:
                items = [items]
        except Exception:
            items = [items]
    if not isinstance(items, list):
        return []
    from docmate_core.line_numbers import ensure_line_numbers
    return ensure_line_numbers(items)


def _calc_metrics(header: Dict[str, Any], items: List[Dict[str, Any]]) -> Dict[str, Any]:
    """Compute reconciliation + KPI metrics from extracted header and line items.

    Notes:
    - Reconciliation (Net/VAT/Gross) uses all lines, including voids.
    - KPI totals ignore lines marked isVoid=True (delivered items).
    - 'products_count' is aligned to delivered line count (as requested), not unique SKU count.
    """
    net_header = _safe_float(header.get("totalNet"))
    vat_header = _safe_float(header.get("totalVat"))
    gross_header = _safe_float(header.get("totalGross"))

    items_for_recon = _normalise_promo_quantities([dict(i) for i in (items or []) if isinstance(i, dict)])
    # Normalise VAT rate: some cloud models return VAT rate as a fraction (e.g. 0.2 for 20%).
    # If detected, convert to percent and recompute vatAmount/lineGross so reconciliation stays correct.
    for _it in items_for_recon:
        vr = _safe_float(_it.get("vatRate"))
        ln = _safe_float(_it.get("lineNet"))
        if vr is not None and 0 < vr <= 1.0:
            vr_pct = vr * 100.0
            _it["vatRate"] = vr_pct
            if ln is not None:
                _it["vatAmount"] = round(ln * vr, 2)  # ln * 0.2 = VAT
                _it["lineGross"] = round(ln + _safe_float(_it.get("vatAmount")), 2)
        elif vr is not None and vr > 1.0:
            expected_vat = round(ln * (vr / 100.0), 2) if ln is not None else 0.0
            vat_amount = _safe_float(_it.get("vatAmount"))
            gross_amount = _safe_float(_it.get("lineGross"))
            vat_missing = _it.get("vatAmount") in (None, "", 0, 0.0)
            vat_implausible = (
                abs(vat_amount - expected_vat) > max(0.05, abs(expected_vat) * 0.10)
                and abs(vat_amount) > max(abs(ln) * 0.50, 1.0)
            )
            if ln is not None and (vat_missing or vat_implausible):
                _it["vatAmount"] = expected_vat
                vat_amount = expected_vat
            expected_gross = round(ln + vat_amount, 2) if ln is not None else gross_amount
            if ln is not None and (
                _it.get("lineGross") in (None, "", 0, 0.0)
                or abs(gross_amount - expected_gross) > max(0.05, abs(expected_gross) * 0.10)
            ):
                _it["lineGross"] = expected_gross

    def _booker_duplicate_key(item: Dict[str, Any]):
        code = str(item.get("code") or item.get("Code") or "").strip().upper()
        if not code or code == "PROMO":
            return None
        desc = re.sub(r"\s+", " ", str(item.get("description") or item.get("Description") or "").upper()).strip()
        desc = re.sub(r"\bM1\b", "ML", desc)
        return (
            code,
            desc,
            round(_safe_float(item.get("qty")), 4),
            round(_safe_float(item.get("totalUnits")), 4),
            round(_safe_float(item.get("lineNet")), 2),
            round(_effective_line_vat(item), 2),
            round(_effective_line_gross(item), 2),
        )

    supplier_for_dedupe = str(header.get("supplierName") or header.get("Supplier") or "").upper()
    if "BOOKER" in supplier_for_dedupe and abs(net_header) > 0.005:
        deduped = []
        seen = set()
        removed = 0
        for item in items_for_recon:
            if _is_promo_line_item(item) or bool(item.get("isVoid")) or bool(item.get("_reconOnly")):
                deduped.append(item)
                continue
            key = _booker_duplicate_key(item)
            if key and key in seen:
                removed += 1
                continue
            if key:
                seen.add(key)
            deduped.append(item)
        if removed:
            current_net = round(sum(_safe_float(i.get("lineNet")) for i in items_for_recon), 2)
            deduped_net = round(sum(_safe_float(i.get("lineNet")) for i in deduped), 2)
            if abs(deduped_net - net_header) <= 0.05 and abs(deduped_net - net_header) < abs(current_net - net_header):
                items_for_recon = deduped

    net_items = sum(_safe_float(i.get("lineNet")) for i in items_for_recon)
    vat_items = sum(_effective_line_vat(i) for i in items_for_recon)
    gross_items = sum(_effective_line_gross(i) for i in items_for_recon)

    # Parfetts invoice summaries are calculated at VAT-code group level, not as a
    # simple sum of per-line rounded VAT amounts. Use the grouped calculation for
    # reconciliation so header/footer VAT matches the supplier's printed totals.
    try:
        supplier_up = str(header.get("supplierName") or "").upper()
        if "PARFETTS" in supplier_up and items_for_recon:
            calc = _parfetts_vat_breakdown_from_items(items_for_recon) or {}
            net_calc = _safe_float(calc.get("totalNet"))
            vat_calc = _safe_float(calc.get("totalVat"))
            gross_calc = _safe_float(calc.get("totalGross"))
            if net_calc > 0:
                net_items = net_calc
            if vat_calc >= 0:
                vat_items = vat_calc
            if gross_calc > 0:
                gross_items = gross_calc
            else:
                gross_items = round(net_items + vat_items, 2)
        elif "DHAMECHA" in supplier_up and items_for_recon:
            rows = _calc_vat_breakdown_from_items(
                items_for_recon,
                supplier_hint=supplier_up,
                header_vat=vat_header,
            )
            net_items = round(sum(_safe_float(row.get("netAmount")) for row in rows), 2)
            vat_items = round(sum(_safe_float(row.get("vatAmount")) for row in rows), 2)
            gross_items = round(sum(_safe_float(row.get("grossAmount")) for row in rows), 2)
            # Dhamecha can leave partial OCR echo rows with stale VAT metadata.
            # If goods reconcile and the remaining VAT/Gross gap is small, the
            # printed header totals are the authoritative reconciliation values.
            if (
                vat_header > 0
                and gross_header > 0
                and abs(round(net_items - net_header, 2)) <= 0.05
                and abs(round(vat_items - vat_header, 2)) <= 1.00
                and abs(round(gross_items - gross_header, 2)) <= 1.00
            ):
                vat_items = vat_header
                gross_items = gross_header
    except Exception:
        pass

    try:
        supplier_up2 = str(header.get("supplierName") or "").upper()
        if "BOOKER" in supplier_up2 and items_for_recon:
            vat_diff = abs(round(vat_items - vat_header, 2))
            gross_diff = abs(round(gross_items - gross_header, 2))
            net_from_lines_gross = round(gross_items - vat_items, 2)
            net_from_header = round(gross_header - vat_header, 2) if gross_header > 0 else 0.0
            # Booker rows can contain stale lineNet values while VAT/Gross are
            # correct after promo/free-line normalization. In that case the
            # reliable arithmetic net is gross - VAT.
            if vat_diff <= 0.05 and gross_diff <= 0.05 and net_from_lines_gross > 0:
                net_items = net_from_lines_gross
            elif net_from_header > 0 and abs(net_items - net_header) > 0.5:
                if abs(net_from_header - net_header) <= 0.05:
                    net_items = net_from_header
    except Exception:
        pass

    items_for_metrics = [
        i for i in items_for_recon
        if not bool(i.get("isVoid")) and not bool(i.get("_reconOnly")) and not _is_promo_line_item(i)
    ]
    total_lines = len(items_for_metrics)
    total_case_qty = sum(_safe_float(i.get("qty")) for i in items_for_metrics)

    # 'No. of Products' = delivered line count (matches Booker expectation)
    products_count = total_lines

    # Optional unique count (kept for later analytics / Cloud Reporting)
    def _product_key(it: Dict[str, Any]):
        for k in ("code","itemCode","productCode","sku","barcode","item_no","itemNo","plu","ean"):
            v = it.get(k)
            if v is not None and str(v).strip() != "":
                return ("code", str(v).strip())
        for k in ("description","desc","itemDescription","label","name","product","item"):
            v = it.get(k)
            if v is not None and str(v).strip() != "":
                return ("desc", str(v).strip().lower())
        return None

    seen = set()
    for it in items_for_metrics:
        k = _product_key(it)
        if k:
            seen.add(k)
    unique_products_count = len(seen)

    # Total stock units: prefer totalUnits, else qty * casePack (if numeric)
    units = 0.0
    for it in items_for_metrics:
        tu = it.get("totalUnits")
        if tu is not None and str(tu).strip() != "":
            units += _safe_float(tu)
            continue
        cp = str(it.get("casePack") or "").strip()
        cp_n = _safe_float(cp)
        if cp_n > 0:
            units += _safe_float(it.get("qty")) * cp_n

    # Average POR (%)
    por_vals = []
    for it in items_for_metrics:
        p = it.get("por")
        if p is None:
            p = it.get("POR")
        if p is None:
            continue
        try:
            ps = str(p).strip().replace("%", "")
            pv = float(ps)
            if pv > 0:
                por_vals.append(pv)
        except Exception:
            continue
    avg_por = (sum(por_vals) / len(por_vals)) if por_vals else 0.0

    return {
        # canonical keys used by dashboard reconciliation UI
        "hdr_net": net_header,
        "hdr_vat": vat_header,
        "hdr_gross": gross_header,
        "sum_net": net_items,
        "sum_vat": vat_items,
        "sum_gross": gross_items,
        "diff_net": round(net_items - net_header, 2),
        "diff_vat": round(vat_items - vat_header, 2),
        "diff_gross": round(gross_items - gross_header, 2),

        # legacy keys (keep for backward compatibility)
        "net_header": net_header,
        "vat_header": vat_header,
        "gross_header": gross_header,
        "net_items": net_items,
        "vat_items": vat_items,
        "gross_items": gross_items,

        "total_lines": total_lines,
        "total_case_qty": total_case_qty,
        "total_units": round(units, 2),
        "products_count": int(products_count or 0),
        "unique_products_count": int(unique_products_count or 0),
        "avg_por": round(avg_por, 2) if avg_por else 0.0,
    }


def _assess_extraction_confidence(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    doc_type: str,
    *,
    raw_text: str = "",
    engine_used: str = "",
) -> Dict[str, Any]:
    """Score whether a parsed document is safe to auto-save.

    The score is intentionally conservative for scanned/photo invoices:
    missing core header fields, weak line extraction, and reconciliation
    mismatches lower confidence quickly.
    """
    hdr = dict(header or {})
    item_rows = [dict(it) for it in (items or []) if isinstance(it, dict)]
    recon_items = _reconciliation_items(hdr, item_rows, raw_text or "")
    metrics = _calc_metrics(hdr, recon_items)
    score = 100
    reasons: List[str] = []
    blockers: List[str] = []

    def _penalty(points: int, reason: str, *, blocker: bool = False) -> None:
        nonlocal score
        score -= int(points)
        reasons.append(reason)
        if blocker:
            blockers.append(reason)

    supplier = str(hdr.get("supplierName") or "").strip()
    customer = str(hdr.get("customerName") or hdr.get("customer_name") or "").strip()
    invoice_no = str(hdr.get("invoiceNumber") or "").strip()
    invoice_dt = str(hdr.get("invoiceDate") or "").strip()
    total_gross = _safe_float(hdr.get("totalGross"))
    total_net = _safe_float(hdr.get("totalNet"))
    total_vat = _safe_float(hdr.get("totalVat"))
    suspicious_year_total = False
    try:
        if (
            1900 <= abs(round(total_net)) <= 2099
            and round(total_net) == round(total_gross)
            and total_vat == 0.0
        ):
            year_text = str(int(abs(round(total_net))))
            suspicious_year_total = not re.search(
                rf"(£|GBP|\b{re.escape(year_text)}[,.]\d{{2}}\b)",
                raw_text or "",
                flags=re.I,
            )
    except Exception:
        suspicious_year_total = False
    valid_zero_blakemore = bool(
        _looks_like_af_blakemore_invoice(raw_text or "")
        and total_net == 0.0
        and total_vat == 0.0
        and total_gross == 0.0
        and re.search(r"\bTO\s+PAY\s+0\.00\b", raw_text or "", flags=re.I)
        and any(bool(it.get("isVoid")) and "NOT AVAILABLE" in str(it.get("voidNote") or it.get("rowTag") or "").upper() for it in item_rows)
    )

    if not supplier:
        _penalty(20, "Missing supplier name.", blocker=True)
    if doc_type != "Expenses" and not invoice_no:
        _penalty(15, "Missing invoice number.", blocker=True)
    if not invoice_dt:
        _penalty(10, "Missing invoice date.", blocker=True)
    elif not _normalise_invoice_date_str(invoice_dt):
        _penalty(14, "Invoice date is not a valid date.", blocker=True)
    if suspicious_year_total:
        _penalty(24, "Invoice totals look like a date/year, not a monetary total.", blocker=True)
    if doc_type == "Expenses":
        if total_gross <= 0:
            _penalty(18, "Missing expense total gross.", blocker=True)
    else:
        if not item_rows:
            _penalty(35, "No line items extracted.", blocker=True)
        if (total_net <= 0 and total_gross <= 0 or suspicious_year_total) and not valid_zero_blakemore:
            _penalty(18, "Missing invoice totals.", blocker=True)

    if customer:
        pass
    elif _is_purchase_like_doc_type(doc_type):
        _penalty(4, "Customer name missing.")

    if item_rows:
        blank_desc = sum(1 for it in item_rows if not str(it.get("description") or "").strip())
        missing_value = sum(
            1
            for it in item_rows
            if not bool(it.get("isVoid"))
            and _safe_float(it.get("lineNet")) <= 0
            and _safe_float(it.get("unitPrice")) <= 0
        )
        missing_code = sum(1 for it in item_rows if not str(it.get("code") or "").strip())
        total_rows = max(len(item_rows), 1)
        if blank_desc / total_rows > 0.25:
            _penalty(12, "Too many line descriptions are blank.")
        elif blank_desc > 0:
            _penalty(4, "Some line descriptions are blank.")
        if missing_value / total_rows > 0.30:
            _penalty(16, "Too many lines have no value/price.")
        elif missing_value > 0:
            _penalty(6, "Some lines have no value/price.")
        if missing_code / total_rows > 0.50:
            _penalty(8, "Most lines have no product code.")
        elif missing_code > 0:
            _penalty(3, "Some lines have no product code.")
        header_text_re = re.compile(
            r"\b(due\s+on\s+receipt|payment\s+terms?|bank\s+details?|sort\s+code|"
            r"invoice\s+(?:no|number|date)|bill\s+to|sold\s+to|email|address)\b|@",
            flags=re.I,
        )
        header_text_rows = sum(
            1 for it in item_rows
            if header_text_re.search(str(it.get("description") or ""))
        )
        if header_text_rows >= max(1, int(math.ceil(total_rows * 0.50))):
            _penalty(30, "Line extraction captured payment, address, or invoice-header text.", blocker=True)

    try:
        max_diff = max(
            abs(_safe_float(metrics.get("diff_net"))),
            abs(_safe_float(metrics.get("diff_vat"))),
            abs(_safe_float(metrics.get("diff_gross"))),
        )
    except Exception:
        max_diff = 0.0
    if max_diff > 5.0:
        _penalty(28, "Header totals do not reconcile with line items.", blocker=True)
    elif max_diff > 1.0:
        _penalty(14, "Header totals differ materially from line items.")
    elif max_diff > 0.2:
        _penalty(6, "Minor totals mismatch detected.")

    raw_len = len(str(raw_text or "").strip())
    if raw_len < 120 and doc_type != "Expenses":
        _penalty(12, "Very little OCR/text was recovered.")
    elif raw_len < 300 and doc_type != "Expenses":
        _penalty(5, "OCR/text recovery is limited.")

    sup_u = supplier.upper()
    if "BOOKER" in sup_u and item_rows:
        good_codes = sum(1 for it in item_rows if re.fullmatch(r"\d{5,7}", re.sub(r"\D+", "", str(it.get("code") or "")) or ""))
        if good_codes == 0:
            _penalty(16, "Booker item codes were not recovered.")
        elif good_codes / max(len(item_rows), 1) < 0.50:
            _penalty(8, "Many Booker item codes look unreliable.")
    if "PARFETTS" in sup_u and item_rows and total_vat <= 0:
        _penalty(6, "Parfetts VAT total missing.")
    if "DHAMECHA" in sup_u and total_gross > 0 and total_net > 0 and abs((total_net + total_vat) - total_gross) > 0.6:
        _penalty(10, "Dhamecha totals look inconsistent.")

    score = max(0, min(int(score), 100))
    return {
        "score": score,
        "metrics": metrics,
        "reasons": reasons,
        "blockers": blockers,
        "bucket": "green" if score >= 85 and not blockers else ("amber" if score >= 65 and not blockers else "red"),
        "engine_used": str(engine_used or ""),
    }


def _auto_route_processed_batch(batch: List[Dict[str, Any]], settings: Dict[str, Any]) -> Dict[str, Any]:
    summary = {"eligible": 0, "saved": 0, "updated": 0, "skipped": 0, "held": 0, "failed": 0, "errors": []}
    auto_enabled = bool(settings.get("auto_save_high_confidence", False))
    threshold = int(settings.get("auto_confidence_threshold", 85) or 85)
    review_threshold = int(settings.get("auto_confidence_review_threshold", 65) or 65)

    for res in (batch or []):
        if not isinstance(res, dict) or res.get("error"):
            continue
        assessment = _assess_extraction_confidence(
            res.get("header") or {},
            res.get("items") or [],
            str(res.get("doc_type") or ""),
            raw_text=(
                str(res.get("confidence_raw_text") or "").strip()
                or ((res.get("text") or "") + "\n" + (res.get("text_hint") or "")).strip()
            ),
            engine_used=str(res.get("engine") or ""),
        )
        score = int(assessment.get("score") or 0)
        blockers = assessment.get("blockers") or []
        if blockers or score < review_threshold:
            decision = "review_required"
        elif score < threshold:
            decision = "review_recommended"
        else:
            decision = "auto_save"
            summary["eligible"] += 1
        res["confidence"] = assessment
        res["auto_decision"] = decision
        res["auto_saved"] = False
        res["auto_save_error"] = ""

    if not auto_enabled:
        summary["held"] = sum(1 for r in (batch or []) if isinstance(r, dict) and not r.get("error"))
        return summary

    try:
        _enforce_register_save_cms_guard()
    except Exception as e:
        msg = str(e)
        summary["errors"].append(msg)
        for res in (batch or []):
            if not isinstance(res, dict) or res.get("error"):
                continue
            if res.get("auto_decision") == "auto_save":
                res["auto_decision"] = "review_required"
                res["auto_save_error"] = msg
        summary["held"] = sum(1 for r in (batch or []) if isinstance(r, dict) and not r.get("error"))
        return summary

    for res in (batch or []):
        if not isinstance(res, dict) or res.get("error"):
            continue
        if res.get("auto_decision") != "auto_save":
            summary["held"] += 1
            continue
        try:
            mode = _upsert_register(
                inv_key=str(res.get("inv_key") or ""),
                header=(res.get("header") or {}),
                items=(res.get("items") or []),
                doc_type=str(res.get("doc_type") or ""),
                engine_used=str(res.get("engine") or ""),
                file_name=str(res.get("file") or ""),
                save_customer_db=True,
            )
            res["auto_saved"] = True
            if mode == "skipped":
                summary["skipped"] += 1
            elif mode == "updated":
                summary["updated"] += 1
            else:
                summary["saved"] += 1
        except Exception as e:
            summary["failed"] += 1
            res["auto_saved"] = False
            res["auto_save_error"] = str(e)
            res["auto_decision"] = "review_required"
            summary["errors"].append(f"{res.get('file') or 'document'}: {e}")
    return summary

def _render_reconciliation_box_html(metrics: dict) -> str:
    """Render a compact reconciliation summary as HTML (Streamlit markdown w/ unsafe_allow_html=True)."""
    try:
        eps = float(metrics.get("eps", 0.05) or 0.05)
    except Exception:
        eps = 0.05

    def _status(diff: float) -> str:
        try:
            return "OK" if abs(float(diff or 0.0)) <= eps else "CHECK"
        except Exception:
            return "CHECK"

    def _chip(status: str) -> str:
        if status == "OK":
            return (
                '<span style="padding:2px 10px; border-radius:999px; background:#eaf7ea; color:#0f5132;'
                'border:1px solid #cfe9d5; font-weight:800; font-size:12px;">OK</span>'
            )
        return (
            '<span style="padding:2px 10px; border-radius:999px; background:#fdecea; color:#842029;'
            'border:1px solid #f5c2c7; font-weight:800; font-size:12px;">CHECK</span>'
        )

    sum_net = metrics.get("sum_net", 0.0) or 0.0
    hdr_net = metrics.get("hdr_net", 0.0) or 0.0
    diff_net = metrics.get("diff_net", (sum_net - hdr_net)) or 0.0

    sum_vat = metrics.get("sum_vat", 0.0) or 0.0
    hdr_vat = metrics.get("hdr_vat", 0.0) or 0.0
    diff_vat = metrics.get("diff_vat", (sum_vat - hdr_vat)) or 0.0

    sum_gross = metrics.get("sum_gross", 0.0) or 0.0
    hdr_gross = metrics.get("hdr_gross", 0.0) or 0.0
    diff_gross = metrics.get("diff_gross", (sum_gross - hdr_gross)) or 0.0

    s_net, s_vat, s_gross = _status(diff_net), _status(diff_vat), _status(diff_gross)
    any_check = (s_net != "OK") or (s_vat != "OK") or (s_gross != "OK")

    def _row(label: str, s: str, line_val: float, hdr_val: float, diff_val: float) -> str:
        return (
            '<div style="display:flex; align-items:center; gap:10px; margin:6px 0;">'
            f'<div style="width:120px; font-weight:700;">{label}</div>'
            f'{_chip(s)}'
            '<div style="font-size:13px; color:#374151;">'
            f'Line Items = <b>{_money(line_val)}</b>&nbsp;|&nbsp; Header = <b>{_money(hdr_val)}</b>'
            f'&nbsp;|&nbsp; Diff = <b>{_money(diff_val)}</b>'
            '</div>'
            '</div>'
        )

    box_start = (
        '<div style="border:1px solid #e5e7eb; border-radius:14px; padding:10px 12px;'
        'background:#f9fafb; margin-top:8px;">'
        '<div style="font-weight:800; font-size:14px; margin-bottom:6px;">Reconciliation (Header vs Line Items)</div>'
    )
    box_end = "</div>"

    reasons = ""
    if any_check:
        reasons = (
            '<div style="margin-top:10px; font-size:12px; color:#374151; line-height:1.4;">'
            '<b>If any line shows CHECK, possible reasons:</b>'
            '<ul style="margin:6px 0 0 18px;">'
            '<li>One or more invoice lines may be missing from the printed/PDF copy (common supplier print issue).</li>'
            '<li>Delivery/surcharge/discount lines included in totals but not captured as line items.</li>'
            '<li>VAT rounding differences (VAT rounded per-line vs invoice-level rounding).</li>'
            '<li>OCR capture gap on a line (rare)  please cross-check against the supplier copy.</li>'
            '</ul>'
            '<div style="margin-top:6px;">If you believe the invoice totals are incorrect, please query the supplier and request a corrected invoice or missing line detail.</div>'
            '</div>'
        )

    html = (
        box_start
        + _row("Net Check", s_net, sum_net, hdr_net, diff_net)
        + _row("VAT Check", s_vat, sum_vat, hdr_vat, diff_vat)
        + _row("Gross Check", s_gross, sum_gross, hdr_gross, diff_gross)
        + reasons
        + box_end
    )
    return html


def _build_reconciliation_status(metrics: dict, eps: float = 0.05) -> dict:
    """Build a compact reconciliation dict for UI + PDF reports."""
    sum_net = _safe_float(metrics.get('net_items'))
    sum_vat = _safe_float(metrics.get('vat_items'))
    sum_gross = _safe_float(metrics.get('gross_items'))
    hdr_net = _safe_float(metrics.get('net_header'))
    hdr_vat = _safe_float(metrics.get('vat_header'))
    hdr_gross = _safe_float(metrics.get('gross_header'))

    def _ok(a: float, b: float) -> bool:
        return abs(_safe_float(a) - _safe_float(b)) <= float(eps)

    return {
        'netStatus': 'OK' if _ok(sum_net, hdr_net) else 'CHECK',
        'vatStatus': 'OK' if _ok(sum_vat, hdr_vat) else 'CHECK',
        'grossStatus': 'OK' if _ok(sum_gross, hdr_gross) else 'CHECK',
    }


def _build_reconciliation_notes(metrics: dict, eps: float = 0.05) -> list[str]:
    """Human-readable notes explaining mismatches."""
    notes: list[str] = []
    sum_net = _safe_float(metrics.get('net_items'))
    sum_vat = _safe_float(metrics.get('vat_items'))
    sum_gross = _safe_float(metrics.get('gross_items'))
    hdr_net = _safe_float(metrics.get('net_header'))
    hdr_vat = _safe_float(metrics.get('vat_header'))
    hdr_gross = _safe_float(metrics.get('gross_header'))

    if abs(sum_net - hdr_net) > eps:
        notes.append('Net mismatch: check for missing delivery/discount lines or OCR gaps.')
    if abs(sum_vat - hdr_vat) > eps:
        notes.append('VAT mismatch: check VAT codes/rates per line and rounding (per-line vs invoice-level).')
    if abs(sum_gross - hdr_gross) > eps:
        notes.append('Gross mismatch: check net+VAT consistency across all lines.')
    if not notes:
        notes.append('Header totals reconcile with line items (within tolerance).')
    return notes


def _invoice_line_content(items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    keys = ("lineNo", "code", "description", "casePack", "unitSize", "totalUnits", "qty", "unitPrice",
            "lineNet", "vatCode", "vatRate", "vatAmount", "lineGross", "stdRrp", "por", "isVoid",
            "voidNote", "pmp")
    return [{key: row.get(key) for key in keys} for row in _normalise_items_for_persistence(items or [])]


def _save_sqlserver_shape_local(
    *,
    doc_type: str,
    file_name: str,
    supplier: str,
    customer: str,
    cms_customer_id: str,
    inv_no: str,
    inv_dt: str,
    created_utc: str,
    net_amount: float,
    vat_amount: float,
    gross_amount: float,
    currency: str,
    items: List[Dict[str, Any]],
    header: Optional[Dict[str, Any]] = None,
) -> None:
    """Append an invoice to the local mirror, skipping only an exact duplicate."""
    conn = _db_connect()
    cur = conn.cursor()
    try:
        payload = {
            "header": [doc_type, supplier, customer, str(cms_customer_id or "").strip(), inv_no, inv_dt,
                       round(_safe_float(net_amount), 6), round(_safe_float(vat_amount), 6),
                       round(_safe_float(gross_amount), 6), str(currency or "GBP")],
            "lines": _invoice_line_content(items or []),
        }
        invoice_fingerprint = hashlib.sha256(
            json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")
        ).hexdigest()
        if cur.execute("SELECT 1 FROM DocMate_invoice_headers WHERE invoice_fingerprint=? LIMIT 1",
                       (invoice_fingerprint,)).fetchone():
            return
        cur.execute(
            """
            INSERT INTO DocMate_invoice_headers(
                created_utc, filename, doc_type, supplier_name, customer_name, cms_customer_id, doc_number, doc_date,
                total_ex_vat, total_vat, total_inc_vat, currency, raw_header_json, invoice_fingerprint
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """,
            (
                created_utc,
                file_name,
                doc_type,
                supplier,
                customer,
                str(cms_customer_id or "").strip(),
                inv_no,
                inv_dt,
                float(_safe_float(net_amount)),
                float(_safe_float(vat_amount)),
                float(_safe_float(gross_amount)),
                str(currency or "GBP"),
                _json_model_text(header or {}),
                invoice_fingerprint,
            ),
        )

        rows: List[Tuple[Any, ...]] = []
        for idx, it in enumerate(items or [], start=1):
            line_no = int(_safe_float(it.get("lineNo")) or 0) or idx
            case_pack_text = str(it.get("casePack") or "").strip()
            case_pack_num = _safe_float(case_pack_text)
            unit_size = str(it.get("unitSize") or "").strip()
            total_units = _safe_float(it.get("totalUnits") or 0.0)
            if (not total_units) and case_pack_num and _safe_float(it.get("qty")):
                total_units = float(case_pack_num) * float(_safe_float(it.get("qty")))

            rows.append(
                (
                    created_utc,
                    file_name,
                    doc_type,
                    supplier,
                    customer,
                    str(cms_customer_id or "").strip(),
                    inv_no,
                    inv_dt,
                    line_no,
                    str(it.get("code") or "").strip(),
                    str(it.get("description") or "").strip(),
                    float(case_pack_num),
                    unit_size,
                    float(_safe_float(total_units)),
                    float(_safe_float(it.get("qty"))),
                    float(_safe_float(it.get("unitPrice"))),
                    float(_safe_float(it.get("lineNet"))),
                    str(it.get("vatCode") or "").strip(),
                    float(_safe_float(it.get("vatRate"))),
                    float(_safe_float(it.get("vatAmount"))),
                    float(_safe_float(it.get("lineGross"))),
                    float(_safe_float(it.get("stdRrp"))),
                    float(_safe_float(it.get("por"))),
                    int(_safe_float(it.get("isVoid")) or 0),
                    str(it.get("voidNote") or "").strip(),
                    float(_safe_float(it.get("pmp"))),
                    str(it.get("raw") if it.get("raw") not in (None, "") else ""),
                    _json_model_text(it),
                    invoice_fingerprint,
                )
            )

        if rows:
            cur.executemany(
                """
                INSERT INTO DocMate_invoice_line_Data(
                    created_utc, filename, doc_type, supplier_name, customer_name, cms_customer_id, doc_number, doc_date,
                    line_no, code, description, case_pack, unit_size, total_units, qty, unit_price, line_net,
                    vat_code, vat_rate, vat_amount, line_gross, std_rrp, por, is_void, void_note, pmp, raw, raw_line_json,
                    invoice_fingerprint
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                rows,
            )
        conn.commit()
    finally:
        conn.close()


def _save_expenses_tables_local(
    *,
    expense_key: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    engine_used: str,
    file_name: str,
    created_utc: str,
) -> None:
    """Save utility/expense headers into dedicated local SQL tables.

    Utility bills are header-only. Existing child rows are cleared so older
    utility line data cannot survive a re-save.
    """
    conn = _db_connect()
    cur = conn.cursor()
    try:
        items = []
        cp = st.session_state.get("selected_customer_profile") or {}
        supplier = _normalise_supplier_name(header.get("supplierName") or "")
        customer = str(header.get("customerName") or "").strip()
        inv_no = str(header.get("invoiceNumber") or "").strip()
        inv_dt = (
            _normalise_invoice_date_str(header.get("invoiceDate") or "")
            or str(header.get("invoiceDate") or "").strip()
        )
        cur.execute(
            """
            INSERT INTO expenses_header(
                expense_key, created_utc, updated_at, filename, supplier_name, customer_name,
                account_number, contract_number, invoice_number, invoice_date, bill_to_address,
                site_address, payment_due_text, service_period, total_net, total_vat, total_gross,
                currency, engine_used, cms_customer_id, spos_customer_id, spos_site_id
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(expense_key) DO UPDATE SET
                updated_at=excluded.updated_at,
                filename=excluded.filename,
                supplier_name=excluded.supplier_name,
                customer_name=excluded.customer_name,
                account_number=excluded.account_number,
                contract_number=excluded.contract_number,
                invoice_number=excluded.invoice_number,
                invoice_date=excluded.invoice_date,
                bill_to_address=excluded.bill_to_address,
                site_address=excluded.site_address,
                payment_due_text=excluded.payment_due_text,
                service_period=excluded.service_period,
                total_net=excluded.total_net,
                total_vat=excluded.total_vat,
                total_gross=excluded.total_gross,
                currency=excluded.currency,
                engine_used=excluded.engine_used,
                cms_customer_id=excluded.cms_customer_id,
                spos_customer_id=excluded.spos_customer_id,
                spos_site_id=excluded.spos_site_id
            """,
            (
                expense_key,
                created_utc,
                _uk_now_iso(),
                file_name,
                supplier,
                customer,
                str(header.get("accountNumber") or header.get("customerNo") or "").strip(),
                str(header.get("contractNumber") or "").strip(),
                inv_no,
                inv_dt,
                str(header.get("billToAddress") or "").strip(),
                str(header.get("siteAddress") or "").strip(),
                str(header.get("paymentDueText") or "").strip(),
                str(header.get("servicePeriod") or "").strip(),
                float(_safe_float(header.get("totalNet"))),
                float(_safe_float(header.get("totalVat"))),
                float(_safe_float(header.get("totalGross"))),
                str(header.get("currency") or "GBP"),
                engine_used,
                str(cp.get("cms_customer_id") or ""),
                str(cp.get("spos_customer_id") or ""),
                str(cp.get("spos_site_id") or ""),
            ),
        )
        cur.execute("DELETE FROM expenses_line WHERE expense_key=?", (expense_key,))
        rows: List[Tuple[Any, ...]] = []
        for idx, it in enumerate(items or [], start=1):
            if not isinstance(it, dict):
                continue
            line_no = int(_safe_float(it.get("lineNo")) or 0) or idx
            rate_val = it.get("rate") if it.get("rate") not in (None, "") else it.get("unitPrice")
            rows.append(
                (
                    expense_key,
                    line_no,
                    float(_safe_float(it.get("qty"))),
                    str(it.get("description") or "").strip(),
                    str(it.get("servicePeriod") or header.get("servicePeriod") or "").strip(),
                    float(_safe_float(rate_val)),
                    float(_safe_float(it.get("lineNet"))),
                    str(it.get("vatCode") or "").strip(),
                    float(_safe_float(it.get("vatRate"))),
                    float(_safe_float(it.get("vatAmount"))),
                    float(_safe_float(it.get("lineGross"))),
                    str(it.get("rawRow") or it.get("raw") or "").strip(),
                )
            )
        if rows:
            cur.executemany(
                """
                INSERT INTO expenses_line(
                    expense_key, line_no, quantity, description, service_period, rate, line_net,
                    vat_code, vat_rate, vat_amount, line_gross, raw_text
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                rows,
            )
        conn.commit()
    finally:
        conn.close()





def _save_dynamics_invoice_tables_local(
    *,
    dynamics_key: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    engine_used: str,
    file_name: str,
    created_utc: str,
    metrics: Dict[str, Any],
) -> None:
    """Save Dynamics invoices into dedicated local header/line tables."""
    _dynamics_db_init()
    conn = _dynamics_db_connect()
    cur = conn.cursor()
    try:
        header = header if isinstance(header, dict) else {}
        items = _ensure_line_numbers(items or [])
        cp = st.session_state.get("selected_customer_profile") or {}
        supplier = _normalise_supplier_name(header.get("supplierName") or "")
        customer = str(header.get("customerName") or "").strip()
        inv_no = str(header.get("invoiceNumber") or "").strip()
        inv_dt = (
            _normalise_invoice_date_str(header.get("invoiceDate") or "")
            or str(header.get("invoiceDate") or "").strip()
        )
        cur.execute(
            """
            INSERT INTO dynamics_invoice_headers(
                dynamics_key, created_utc, updated_at, filename, engine_used,
                supplier_name, customer_name, cms_customer_id, spos_customer_id, spos_site_id,
                invoice_number, invoice_date, currency, total_lines, total_case_qty,
                total_units, total_net, total_vat, total_gross, source_doc_type, raw_header_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            ON CONFLICT(dynamics_key) DO UPDATE SET
                updated_at=excluded.updated_at,
                filename=excluded.filename,
                engine_used=excluded.engine_used,
                supplier_name=excluded.supplier_name,
                customer_name=excluded.customer_name,
                cms_customer_id=excluded.cms_customer_id,
                spos_customer_id=excluded.spos_customer_id,
                spos_site_id=excluded.spos_site_id,
                invoice_number=excluded.invoice_number,
                invoice_date=excluded.invoice_date,
                currency=excluded.currency,
                total_lines=excluded.total_lines,
                total_case_qty=excluded.total_case_qty,
                total_units=excluded.total_units,
                total_net=excluded.total_net,
                total_vat=excluded.total_vat,
                total_gross=excluded.total_gross,
                source_doc_type=excluded.source_doc_type,
                raw_header_json=excluded.raw_header_json
            """,
            (
                dynamics_key,
                created_utc,
                _uk_now_iso(),
                file_name,
                engine_used,
                supplier,
                customer,
                str(cp.get("cms_customer_id") or ""),
                str(cp.get("spos_customer_id") or ""),
                str(cp.get("spos_site_id") or ""),
                inv_no,
                inv_dt,
                str(header.get("currency") or "GBP"),
                int(metrics.get("total_lines") or len(items or [])),
                float(_safe_float(metrics.get("total_case_qty"))),
                float(_safe_float(metrics.get("total_units"))),
                float(_safe_float(metrics.get("net_header"))),
                float(_safe_float(metrics.get("vat_header"))),
                float(_safe_float(metrics.get("gross_header"))),
                "Dynamics Invoice",
                json.dumps(header, ensure_ascii=False, default=str),
            ),
        )

        cur.execute("DELETE FROM dynamics_invoice_lines WHERE dynamics_key=?", (dynamics_key,))
        rows: List[Tuple[Any, ...]] = []
        for idx, it in enumerate(items or [], start=1):
            if not isinstance(it, dict):
                continue
            line_no = int(_safe_float(it.get("lineNo")) or 0) or idx
            case_pack_text = str(it.get("casePack") or "").strip()
            case_pack_num = _safe_float(case_pack_text)
            total_units = _safe_float(it.get("totalUnits"))
            if not total_units and case_pack_num and _safe_float(it.get("qty")):
                total_units = case_pack_num * _safe_float(it.get("qty"))
            rows.append(
                (
                    dynamics_key,
                    line_no,
                    str(it.get("code") or "").strip(),
                    str(it.get("barcode") or "").strip(),
                    str(it.get("description") or "").strip(),
                    float(case_pack_num),
                    case_pack_text,
                    str(it.get("unitSize") or "").strip(),
                    float(_safe_float(it.get("qty"))),
                    float(_safe_float(total_units)),
                    float(_safe_float(it.get("unitPrice"))),
                    float(_safe_float(it.get("lineNet"))),
                    str(it.get("vatCode") or "").strip(),
                    float(_safe_float(it.get("vatRate"))),
                    float(_safe_float(it.get("vatAmount"))),
                    float(_safe_float(it.get("lineGross"))),
                    float(_safe_float(it.get("stdRrp"))),
                    float(_safe_float(it.get("por"))),
                    float(_safe_float(it.get("pmp"))),
                    int(_safe_float(it.get("isVoid")) or 0),
                    str(it.get("voidNote") or "").strip(),
                    str(it.get("rawRow") or it.get("raw") or "").strip(),
                )
            )
        if rows:
            cur.executemany(
                """
                INSERT INTO dynamics_invoice_lines(
                    dynamics_key, line_no, code, barcode, description, case_pack, case_pack_text,
                    unit_size, qty, total_units, unit_price, line_net, vat_code, vat_rate,
                    vat_amount, line_gross, std_rrp, por, pmp, is_void, void_note, raw_text
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                rows,
            )
        conn.commit()
    finally:
        conn.close()


def _dynamics_sqlserver_build_conn_str(cfg: Dict[str, str], database_override: str = "") -> str:
    return _v18_dynamics.build_connection_string(cfg, database_override=database_override)


def _dynamics_sqlserver_connect(cfg: Dict[str, str], database_override: str = ""):
    return _v18_dynamics.connect(cfg, database_override=database_override)


def _test_dynamics_sqlserver_connection(create_schema: bool = False) -> Tuple[bool, str]:
    cfg = _read_dynamics_db_cred()
    if not cfg:
        return False, "Dynamics_db_cred.yaml not found or empty"
    try:
        if create_schema:
            return _ensure_dynamics_sqlserver_schema(cfg)
        conn = _dynamics_sqlserver_connect(cfg, database_override="master")
        try:
            cur = conn.cursor()
            cur.execute("SELECT @@SERVERNAME")
            row = cur.fetchone()
            server_name = str(row[0]) if row else "SQL Server"
        finally:
            conn.close()
        return True, f"Dynamics SQL Server connection successful: {server_name}"
    except Exception as e:
        return False, f"Dynamics SQL Server connection failed: {e}"


def _ensure_dynamics_sqlserver_schema(cfg: Dict[str, str]) -> Tuple[bool, str]:
    if not cfg:
        return False, "Dynamics_db_cred.yaml not found or empty"
    database = (cfg.get("database") or "DocMate_Dynamics").strip()
    try:
        conn_master = _dynamics_sqlserver_connect(cfg, database_override="master")
        try:
            cur = conn_master.cursor()
            cur.execute(
                f"IF DB_ID(?) IS NULL EXEC('CREATE DATABASE [{database.replace(']', ']]')}]')",
                database,
            )
        finally:
            conn_master.close()

        conn = _dynamics_sqlserver_connect(cfg)
        try:
            cur = conn.cursor()
            cur.execute(
                """
                IF OBJECT_ID('dbo.DynamicsInvoiceHeader', 'U') IS NULL
                BEGIN
                    CREATE TABLE dbo.DynamicsInvoiceHeader (
                        DynamicsKey NVARCHAR(100) NOT NULL PRIMARY KEY,
                        CreatedUtc NVARCHAR(64) NOT NULL,
                        UpdatedAt NVARCHAR(64) NULL,
                        FileName NVARCHAR(260) NULL,
                        EngineUsed NVARCHAR(100) NULL,
                        SupplierName NVARCHAR(260) NULL,
                        CustomerName NVARCHAR(260) NULL,
                        CmsCustomerId NVARCHAR(64) NULL,
                        SposCustomerId NVARCHAR(64) NULL,
                        SposSiteId NVARCHAR(64) NULL,
                        InvoiceNumber NVARCHAR(100) NULL,
                        InvoiceDate NVARCHAR(64) NULL,
                        Currency NVARCHAR(16) NULL,
                        TotalLines INT NULL,
                        TotalCaseQty DECIMAL(18,4) NULL,
                        TotalUnits DECIMAL(18,4) NULL,
                        TotalNet DECIMAL(18,2) NULL,
                        TotalVat DECIMAL(18,2) NULL,
                        TotalGross DECIMAL(18,2) NULL,
                        SourceDocType NVARCHAR(64) NULL,
                        RawHeaderJson NVARCHAR(MAX) NULL
                    );
                END
                IF OBJECT_ID('dbo.DynamicsInvoiceLine', 'U') IS NULL
                BEGIN
                    CREATE TABLE dbo.DynamicsInvoiceLine (
                        DynamicsKey NVARCHAR(100) NOT NULL,
                        LineNumber INT NOT NULL,
                        Code NVARCHAR(100) NULL,
                        Barcode NVARCHAR(100) NULL,
                        Description NVARCHAR(500) NULL,
                        CasePack DECIMAL(18,4) NULL,
                        CasePackText NVARCHAR(100) NULL,
                        UnitSize NVARCHAR(100) NULL,
                        Qty DECIMAL(18,4) NULL,
                        TotalUnits DECIMAL(18,4) NULL,
                        UnitPrice DECIMAL(18,4) NULL,
                        LineNet DECIMAL(18,2) NULL,
                        VatCode NVARCHAR(50) NULL,
                        VatRate DECIMAL(9,4) NULL,
                        VatAmount DECIMAL(18,2) NULL,
                        LineGross DECIMAL(18,2) NULL,
                        StdRrp DECIMAL(18,4) NULL,
                        Por DECIMAL(18,4) NULL,
                        Pmp DECIMAL(18,4) NULL,
                        IsVoid BIT NULL,
                        VoidNote NVARCHAR(255) NULL,
                        RawText NVARCHAR(MAX) NULL,
                        CONSTRAINT PK_DynamicsInvoiceLine PRIMARY KEY (DynamicsKey, LineNumber)
                    );
                END
                IF COL_LENGTH('dbo.DynamicsInvoiceLine', 'LineNumber') IS NULL
                   AND COL_LENGTH('dbo.DynamicsInvoiceLine', 'Line_Number') IS NOT NULL
                BEGIN
                    EXEC sp_rename 'dbo.DynamicsInvoiceLine.Line_Number', 'LineNumber', 'COLUMN';
                END
                IF NOT EXISTS (
                    SELECT 1 FROM sys.foreign_keys WHERE name = 'FK_DynamicsInvoiceLine_Header'
                )
                BEGIN
                    ALTER TABLE dbo.DynamicsInvoiceLine
                    ADD CONSTRAINT FK_DynamicsInvoiceLine_Header
                    FOREIGN KEY (DynamicsKey) REFERENCES dbo.DynamicsInvoiceHeader(DynamicsKey);
                END
                IF NOT EXISTS (
                    SELECT 1 FROM sys.indexes
                    WHERE name = 'UX_DynamicsInvoiceHeader_Natural'
                      AND object_id = OBJECT_ID('dbo.DynamicsInvoiceHeader')
                )
                BEGIN
                    CREATE UNIQUE INDEX UX_DynamicsInvoiceHeader_Natural
                    ON dbo.DynamicsInvoiceHeader (SupplierName, InvoiceNumber, InvoiceDate);
                END
                """
            )
        finally:
            conn.close()
        return True, "ok"
    except Exception as e:
        return False, f"Dynamics SQL Server schema/create failed: {e}"


def _save_dynamics_invoice_tables_sqlserver(
    *,
    dynamics_key: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    engine_used: str,
    file_name: str,
    created_utc: str,
    metrics: Dict[str, Any],
) -> Tuple[bool, str]:
    cfg = _read_dynamics_db_cred()
    ok, msg = _ensure_dynamics_sqlserver_schema(cfg)
    if not ok:
        return False, msg
    conn = None
    try:
        conn = _dynamics_sqlserver_connect(cfg)
        cur = conn.cursor()
        cp = st.session_state.get("selected_customer_profile") or {}
        supplier = _normalise_supplier_name((header or {}).get("supplierName") or "")
        customer = str((header or {}).get("customerName") or "").strip()
        inv_no = str((header or {}).get("invoiceNumber") or "").strip()
        inv_dt = _normalise_invoice_date_str((header or {}).get("invoiceDate") or "") or str((header or {}).get("invoiceDate") or "").strip()
        raw_header = json.dumps(header if isinstance(header, dict) else {}, ensure_ascii=False, default=str)
        cur.execute(
            """
            MERGE dbo.DynamicsInvoiceHeader AS target
            USING (VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)) AS src(
                DynamicsKey, CreatedUtc, UpdatedAt, FileName, EngineUsed, SupplierName, CustomerName,
                CmsCustomerId, SposCustomerId, SposSiteId, InvoiceNumber, InvoiceDate, Currency,
                TotalLines, TotalCaseQty, TotalUnits, TotalNet, TotalVat, TotalGross, SourceDocType, RawHeaderJson
            )
            ON target.DynamicsKey = src.DynamicsKey
            WHEN MATCHED THEN UPDATE SET
                UpdatedAt=src.UpdatedAt, FileName=src.FileName, EngineUsed=src.EngineUsed,
                SupplierName=src.SupplierName, CustomerName=src.CustomerName,
                CmsCustomerId=src.CmsCustomerId, SposCustomerId=src.SposCustomerId, SposSiteId=src.SposSiteId,
                InvoiceNumber=src.InvoiceNumber, InvoiceDate=src.InvoiceDate, Currency=src.Currency,
                TotalLines=src.TotalLines, TotalCaseQty=src.TotalCaseQty, TotalUnits=src.TotalUnits,
                TotalNet=src.TotalNet, TotalVat=src.TotalVat, TotalGross=src.TotalGross,
                SourceDocType=src.SourceDocType, RawHeaderJson=src.RawHeaderJson
            WHEN NOT MATCHED THEN INSERT (
                DynamicsKey, CreatedUtc, UpdatedAt, FileName, EngineUsed, SupplierName, CustomerName,
                CmsCustomerId, SposCustomerId, SposSiteId, InvoiceNumber, InvoiceDate, Currency,
                TotalLines, TotalCaseQty, TotalUnits, TotalNet, TotalVat, TotalGross, SourceDocType, RawHeaderJson
            ) VALUES (
                src.DynamicsKey, src.CreatedUtc, src.UpdatedAt, src.FileName, src.EngineUsed, src.SupplierName, src.CustomerName,
                src.CmsCustomerId, src.SposCustomerId, src.SposSiteId, src.InvoiceNumber, src.InvoiceDate, src.Currency,
                src.TotalLines, src.TotalCaseQty, src.TotalUnits, src.TotalNet, src.TotalVat, src.TotalGross, src.SourceDocType, src.RawHeaderJson
            );
            """,
            (
                dynamics_key,
                created_utc,
                _uk_now_iso(),
                file_name,
                engine_used,
                supplier,
                customer,
                str(cp.get("cms_customer_id") or ""),
                str(cp.get("spos_customer_id") or ""),
                str(cp.get("spos_site_id") or ""),
                inv_no,
                inv_dt,
                str((header or {}).get("currency") or "GBP"),
                int(metrics.get("total_lines") or len(items or [])),
                float(_safe_float(metrics.get("total_case_qty"))),
                float(_safe_float(metrics.get("total_units"))),
                float(_safe_float(metrics.get("net_header"))),
                float(_safe_float(metrics.get("vat_header"))),
                float(_safe_float(metrics.get("gross_header"))),
                "Dynamics Invoice",
                raw_header,
            ),
        )
        cur.execute("DELETE FROM dbo.DynamicsInvoiceLine WHERE DynamicsKey=?", dynamics_key)
        rows = []
        for idx, it in enumerate(_ensure_line_numbers(items or []), start=1):
            if not isinstance(it, dict):
                continue
            line_no = int(_safe_float(it.get("lineNo")) or 0) or idx
            case_pack_text = str(it.get("casePack") or "").strip()
            case_pack_num = _safe_float(case_pack_text)
            total_units = _safe_float(it.get("totalUnits"))
            if not total_units and case_pack_num and _safe_float(it.get("qty")):
                total_units = case_pack_num * _safe_float(it.get("qty"))
            rows.append(
                (
                    dynamics_key,
                    line_no,
                    str(it.get("code") or "").strip(),
                    str(it.get("barcode") or "").strip(),
                    str(it.get("description") or "").strip(),
                    float(case_pack_num),
                    case_pack_text,
                    str(it.get("unitSize") or "").strip(),
                    float(_safe_float(it.get("qty"))),
                    float(_safe_float(total_units)),
                    float(_safe_float(it.get("unitPrice"))),
                    float(_safe_float(it.get("lineNet"))),
                    str(it.get("vatCode") or "").strip(),
                    float(_safe_float(it.get("vatRate"))),
                    float(_safe_float(it.get("vatAmount"))),
                    float(_safe_float(it.get("lineGross"))),
                    float(_safe_float(it.get("stdRrp"))),
                    float(_safe_float(it.get("por"))),
                    float(_safe_float(it.get("pmp"))),
                    int(_safe_float(it.get("isVoid")) or 0),
                    str(it.get("voidNote") or "").strip(),
                    str(it.get("rawRow") or it.get("raw") or "").strip(),
                )
            )
        if rows:
            cur.executemany(
                """
                INSERT INTO dbo.DynamicsInvoiceLine(
                    DynamicsKey, LineNumber, Code, Barcode, Description, CasePack, CasePackText,
                    UnitSize, Qty, TotalUnits, UnitPrice, LineNet, VatCode, VatRate,
                    VatAmount, LineGross, StdRrp, Por, Pmp, IsVoid, VoidNote, RawText
                ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """,
                rows,
            )
        return True, f"ok ({len(rows)} line rows)"
    except Exception as e:
        return False, f"Dynamics SQL Server save failed: {e}"
    finally:
        try:
            if conn is not None:
                conn.close()
        except Exception:
            pass


def _save_customer_db(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    doc_type: str,
    file_name: str,
    processed_at: str,
    metrics: Dict[str, Any],
    sqlserver_cfg_override: Optional[Dict[str, str]] = None,
    sqlserver_module: Optional[Any] = None,
) -> None:
    if doc_type == "Expenses":
        items = []
    supplier = _normalise_supplier_name(header.get("supplierName") or "")
    customer = str(header.get("customerName") or "").strip()
    inv_no = str(header.get("invoiceNumber") or "").strip()
    inv_dt = (
        _normalise_invoice_date_str(header.get("invoiceDate") or "")
        or str(header.get("invoiceDate") or "").strip()
    )

    # Mirror save into local tables that use sql_server_customer.py datatable shape.
    try:
        _save_sqlserver_shape_local(
            doc_type=doc_type,
            file_name=file_name,
            supplier=supplier,
            customer=customer,
            cms_customer_id=str((st.session_state.get("selected_customer_profile") or {}).get("cms_customer_id") or st.session_state.get("login_cms_customer_id") or "").strip(),
            inv_no=inv_no,
            inv_dt=inv_dt,
            created_utc=processed_at,
            net_amount=float(metrics["net_header"]),
            vat_amount=float(metrics["vat_header"]),
            gross_amount=float(metrics["gross_header"]),
            currency=str(header.get("currency") or "GBP"),
            items=items,
            header=header,
        )
    except Exception as e:
        _log_event(f"WARNING local SQLServer-shape save failed: {e}", file_name=file_name)

    # Optional: push into SQL Server using sql_server_customer.py (if configured)
    sqlserver_mod = sqlserver_module or _sqlserver
    if sqlserver_mod is not None:
        try:
            header_sql = {
                "created_utc": processed_at,
                "filename": file_name,
                "doc_type": doc_type,
                "supplier_name": supplier,
                "customer_name": customer,
                "cms_customer_id": str((st.session_state.get("selected_customer_profile") or {}).get("cms_customer_id") or st.session_state.get("login_cms_customer_id") or "").strip(),
                "doc_number": inv_no,
                "doc_date": inv_dt,
                "total_ex_vat": float(metrics["net_header"]),
                "total_vat": float(metrics["vat_header"]),
                "total_inc_vat": float(metrics["gross_header"]),
                "currency": str(header.get("currency") or "GBP"),
                "raw_header_json": _json_model_text(header),
            }
            payload = {
                "header": [doc_type, supplier, customer, header_sql["cms_customer_id"], inv_no, inv_dt,
                           round(_safe_float(metrics["net_header"]), 6), round(_safe_float(metrics["vat_header"]), 6),
                           round(_safe_float(metrics["gross_header"]), 6), header_sql["currency"]],
                "lines": _invoice_line_content(items or []),
            }
            header_sql["invoice_fingerprint"] = hashlib.sha256(
                json.dumps(payload, sort_keys=True, ensure_ascii=False, default=str).encode("utf-8")
            ).hexdigest()
            if doc_type == "Expenses":
                expenses_header_sql = {
                    **header_sql,
                    "source_attachment": "",
                    "account_number": str(header.get("accountNumber") or header.get("customerNo") or "").strip(),
                    "contract_number": str(header.get("contractNumber") or "").strip(),
                    "customer_no": str(header.get("customerNo") or "").strip(),
                    "site_address": str(header.get("siteAddress") or "").strip(),
                    "bill_to_address": str(header.get("billToAddress") or "").strip(),
                    "service_period": str(header.get("servicePeriod") or "").strip(),
                    "payment_due_date": _normalise_invoice_date_str(header.get("paymentDueDate") or "")
                    or str(header.get("paymentDueDate") or "").strip(),
                    "payment_due_text": str(header.get("paymentDueText") or "").strip(),
                    "utility_type": str(header.get("utilityType") or "").strip(),
                    "meter_number": str(header.get("meterNumber") or "").strip(),
                    "mpan": str(header.get("mpan") or "").strip(),
                    "mprn": str(header.get("mprn") or "").strip(),
                    "vat_registration_number": str(header.get("vatRegistrationNumber") or "").strip(),
                    "extraction_mode": str(header.get("extractionMode") or "Utility Header Agent").strip(),
                    "raw_header_json": json.dumps(header, ensure_ascii=False, default=str),
                }
                if hasattr(sqlserver_mod, "insert_expenses_header_sqlserver"):
                    ok_h, msg_h = sqlserver_mod.insert_expenses_header_sqlserver(
                        expenses_header_sql, cfg_override=sqlserver_cfg_override
                    )
                    ok_l, msg_l = True, "header-only"
                else:
                    ok_h, msg_h = False, "SQL Server module does not support Expenses_header"
                    ok_l, msg_l = True, "header-only"
            else:
                ok_h, msg_h = sqlserver_mod.insert_invoice_header_sqlserver(
                    header_sql, cfg_override=sqlserver_cfg_override
                )
                if ok_h and str(msg_h).lower() == "duplicate":
                    ok_l, msg_l = True, "duplicate skipped"
                else:
                    ok_l, msg_l = sqlserver_mod.insert_invoice_lines_sqlserver(
                        header_sql, items, cfg_override=sqlserver_cfg_override
                    )
            if not ok_h or not ok_l:
                _log_event(
                    f"WARNING SQL Server save failed: header_ok={ok_h} lines_ok={ok_l} | {msg_h} | {msg_l}",
                    file_name=file_name,
                )
        except Exception as e:
            _log_event(f"WARNING SQL Server save exception: {e}", file_name=file_name)



def _upsert_register(
    inv_key: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    doc_type: str,
    engine_used: str,
    file_name: str,
    save_customer_db: bool = True,
) -> str:
    """Upsert into the Purchase register with de-duplication.

    Problem observed in testing:
    - Same invoice saved multiple times can create duplicates because inv_key includes a file-hash/engine variance.

    Fix:
    - Use a *natural key* (doc_type + supplier + invoice_number + invoice_date) to detect existing entries.
    - If a match exists, reuse the existing inv_key and update that entry (re-save).
    - If multiple duplicates exist for the same natural key, keep the most-recent and remove the rest.
    """
    for _sql in (
        "ALTER TABLE purchase_invoices ADD COLUMN header_json TEXT",
        "ALTER TABLE purchase_invoice_items ADD COLUMN line_json TEXT",
    ):
        try:
            _db_exec(_sql)
        except Exception:
            pass
    if doc_type == "Expenses":
        items = []
    items = _ensure_line_numbers(items)
    if doc_type != "Expenses":
        items = _normalise_items_for_persistence(items)
        _fill_header_totals_from_items(header, items)
    metrics = _calc_metrics(header, items)
    now = _uk_now_iso()
    processed_at = now

    supplier = _normalise_supplier_name(header.get("supplierName") or "")
    customer = str(header.get("customerName") or "").strip()
    inv_no = str(header.get("invoiceNumber") or "").strip()
    inv_dt = (_normalise_invoice_date_str(header.get("invoiceDate") or "") or str(header.get("invoiceDate") or "").strip())

    # Normalise for matching
    supplier_norm = re.sub(r"\s+", " ", supplier).strip().upper()
    inv_no_norm = re.sub(r"\s+", "", inv_no).strip().upper()
    inv_dt_norm = re.sub(r"\s+", "", inv_dt).strip()

    # 1) Detect existing rows by natural key (prevents duplicates across engines/files)
    match_rows: List[Dict[str, Any]] = []
    try:
        if supplier_norm and inv_no_norm and inv_dt_norm:
            rows = _db_fetchall(
                """SELECT inv_key, processed_at, updated_at
                   FROM purchase_invoices
                   WHERE doc_type=?
                     AND UPPER(TRIM(supplier_name))=?
                     AND UPPER(REPLACE(TRIM(invoice_number),' ',''))=?
                     AND TRIM(invoice_date)=?
                   ORDER BY COALESCE(updated_at, processed_at) DESC""",
                (doc_type, supplier_norm, inv_no_norm, inv_dt_norm),
            )
            match_rows = [dict(r) for r in (rows or [])]
        elif supplier_norm and inv_no_norm:
            rows = _db_fetchall(
                """SELECT inv_key, processed_at, updated_at
                   FROM purchase_invoices
                   WHERE doc_type=?
                     AND UPPER(TRIM(supplier_name))=?
                     AND UPPER(REPLACE(TRIM(invoice_number),' ',''))=?
                   ORDER BY COALESCE(updated_at, processed_at) DESC""",
                (doc_type, supplier_norm, inv_no_norm),
            )
            match_rows = [dict(r) for r in (rows or [])]
    except Exception as e:
        _log_event(f"WARNING register natural-key lookup failed: {e}", file_name=file_name)

    # Skip only when both the stored header and the complete ordered line set
    # are identical. A changed version of the same invoice remains append-only.
    candidate_content = _json_model_text({"header": header, "lines": _invoice_line_content(items)})
    for matched in match_rows:
        existing_key = str(matched.get("inv_key") or "")
        existing_header = _db_fetchone("SELECT header_json FROM purchase_invoices WHERE inv_key=?", (existing_key,))
        existing_lines = _db_fetchall(
            "SELECT line_json FROM purchase_invoice_items WHERE inv_key=? ORDER BY line_no", (existing_key,)
        )
        try:
            stored_header = json.loads((dict(existing_header).get("header_json") if existing_header else "") or "{}")
            stored_lines = [json.loads((dict(row).get("line_json") or "{}")) for row in existing_lines]
            stored_content = _json_model_text({"header": stored_header, "lines": _invoice_line_content(stored_lines)})
            if stored_content == candidate_content:
                _log_event(f"Register duplicate skipped (header and lines identical). inv_key={existing_key}", file_name=file_name)
                return "skipped"
        except Exception:
            pass

    # Natural-key matches with different content are new immutable versions.
    if match_rows:
        match_rows = []
        if _db_fetchone("SELECT 1 FROM purchase_invoices WHERE inv_key=?", (inv_key,)):
            content_hash = hashlib.sha256(candidate_content.encode("utf-8")).hexdigest()[:12]
            inv_key = f"{inv_key}_{content_hash}"
            suffix, base_key = 2, inv_key
            while _db_fetchone("SELECT 1 FROM purchase_invoices WHERE inv_key=?", (inv_key,)):
                inv_key = f"{base_key}_{suffix}"
                suffix += 1

    # Determine target inv_key to write to
    target_inv_key = inv_key
    mode = "created"

    if match_rows:
        # Reuse latest existing key
        target_inv_key = str(match_rows[0].get("inv_key") or inv_key)
        mode = "updated"
        if target_inv_key != inv_key:
            _log_event(
                f"Register de-dup: matched existing invoice (supplier={supplier_norm} inv={inv_no_norm} date={inv_dt_norm}); reusing inv_key={target_inv_key} (discarding new inv_key={inv_key})",
                file_name=file_name,
            )

        # If multiple duplicates exist, remove the extras
        dup_keys = [str(r.get("inv_key")) for r in match_rows[1:] if r.get("inv_key")]
        if dup_keys:
            try:
                for k in dup_keys:
                    _db_exec("DELETE FROM purchase_invoice_items WHERE inv_key=?", (k,))
                    _db_exec("DELETE FROM purchase_invoices WHERE inv_key=?", (k,))
                _log_event(f"Register de-dup cleanup: removed duplicate inv_key(s)={', '.join(dup_keys)}", file_name=file_name)
            except Exception as e:
                _log_event(f"WARNING register de-dup cleanup failed: {e}", file_name=file_name)

    else:
        # Never overwrite an existing key; allocate a version key instead.
        existed = _db_fetchone("SELECT 1 FROM purchase_invoices WHERE inv_key=?", (inv_key,))
        if existed:
            content_hash = hashlib.sha256(candidate_content.encode("utf-8")).hexdigest()[:12]
            target_inv_key = f"{inv_key}_{content_hash}"
            suffix, base_key = 2, target_inv_key
            while _db_fetchone("SELECT 1 FROM purchase_invoices WHERE inv_key=?", (target_inv_key,)):
                target_inv_key = f"{base_key}_{suffix}"
                suffix += 1

    # 2) Upsert header row
    header_json = _json_model_text(header)
    _db_exec(
        """INSERT INTO purchase_invoices(
            inv_key, doc_type, supplier_name, customer_name, invoice_date, invoice_number,
            total_lines, total_case_qty, total_units, net_amount, vat_amount, gross_amount,
            engine_used, file_name, processed_at, updated_at,
            cms_customer_id, spos_customer_id, spos_site_id, header_json
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            target_inv_key,
            doc_type,
            supplier,
            customer,
            inv_dt,
            inv_no,
            int(metrics["total_lines"]),
            float(metrics["total_case_qty"]),
            float(metrics["total_units"]),
            float(metrics["net_header"]),
            float(metrics["vat_header"]),
            float(metrics["gross_header"]),
            engine_used,
            file_name,
            processed_at,
            now,
            str((st.session_state.get("selected_customer_profile") or {}).get("cms_customer_id") or ""),
            str((st.session_state.get("selected_customer_profile") or {}).get("spos_customer_id") or ""),
            str((st.session_state.get("selected_customer_profile") or {}).get("spos_site_id") or ""),
            header_json,
        ),
    )

    # 2b) Update local invoice_register_index (v1.07)
    try:
        cp = st.session_state.get("selected_customer_profile") or {}
        _db_exec(
            """INSERT INTO invoice_register_index(
                inv_key, doc_type, cms_customer_id, spos_customer_id, spos_site_id,
                supplier_name, invoice_number, invoice_date, engine_used, source_file_name,
                created_at, updated_at
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                target_inv_key,
                doc_type,
                str(cp.get("cms_customer_id") or ""),
                str(cp.get("spos_customer_id") or ""),
                str(cp.get("spos_site_id") or ""),
                supplier,
                inv_no,
                inv_dt,
                engine_used,
                file_name,
                processed_at,
                now,
            ),
        )
    except Exception:
        pass

    # 3) Append items for this new invoice version.
    for it in items:
        line_no = int(_safe_float(it.get("lineNo")) or 0) or 0
        if line_no <= 0:
            line_no = items.index(it) + 1
        case_pack_text = str(it.get("casePack") or "").strip()
        case_pack_num = _safe_float(case_pack_text)

        _db_exec(
            """INSERT INTO purchase_invoice_items(
                inv_key, line_no, code, description, case_pack, case_pack_text, unit_size,
                qty_cases, unit_price, line_net, vat_code, vat_rate, vat_amount, line_gross,
                std_rrp, por, is_void, void_note, line_json
            ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                target_inv_key,
                line_no,
                str(it.get("code") or "").strip(),
                str(it.get("description") or "").strip(),
                float(case_pack_num),
                case_pack_text,
                str(it.get("unitSize") or "").strip(),
                float(_safe_float(it.get("qty"))),
                float(_safe_float(it.get("unitPrice"))),
                float(_safe_float(it.get("lineNet"))),
                str(it.get("vatCode") or "").strip(),
                float(_safe_float(it.get("vatRate"))),
                float(_safe_float(it.get("vatAmount"))),
                float(_safe_float(it.get("lineGross"))),
                float(_safe_float(it.get("stdRrp"))),
                float(_safe_float(it.get("por"))),
                int(_safe_float(it.get("isVoid")) or 0),
                str(it.get("voidNote") or "").strip(),
                _json_model_text(it),
            ),
        )

    if save_customer_db:
        _save_customer_db(
            header=header,
            items=items,
            doc_type=doc_type,
            file_name=file_name,
            processed_at=processed_at,
            metrics=metrics,
        )

    if doc_type == "Expenses":
        try:
            _save_expenses_tables_local(
                expense_key=target_inv_key,
                header=header,
                items=items,
                engine_used=engine_used,
                file_name=file_name,
                created_utc=processed_at,
            )
        except Exception as e:
            _log_event(f"WARNING expenses table save failed: {e}", file_name=file_name)

    if doc_type == "Dynamics Invoice":
        try:
            _save_dynamics_invoice_tables_local(
                dynamics_key=target_inv_key,
                header=header,
                items=items,
                engine_used=engine_used,
                file_name=file_name,
                created_utc=processed_at,
                metrics=metrics,
            )
        except Exception as e:
            _log_event(f"WARNING Dynamics invoice table save failed: {e}", file_name=file_name)
        try:
            ok_dyn_sql, msg_dyn_sql = _save_dynamics_invoice_tables_sqlserver(
                dynamics_key=target_inv_key,
                header=header,
                items=items,
                engine_used=engine_used,
                file_name=file_name,
                created_utc=processed_at,
                metrics=metrics,
            )
            if ok_dyn_sql:
                _log_event(f"Dynamics SQL Server save ok: {msg_dyn_sql}", file_name=file_name)
            else:
                _log_event(f"WARNING Dynamics SQL Server save failed: {msg_dyn_sql}", file_name=file_name)
        except Exception as e:
            _log_event(f"WARNING Dynamics SQL Server save exception: {e}", file_name=file_name)

    # Record action in EventLOG for transparency
    if mode == "updated":
        _log_event(f"Register update: Entry already exists  updated & re-saved (No duplicate entry enforced). register={REGISTER_LABEL.get(doc_type, 'Register')} inv_key={target_inv_key}", file_name=file_name)
    else:
        _log_event(f"Register insert: New entry created. register={REGISTER_LABEL.get(doc_type, 'Register')} inv_key={target_inv_key}", file_name=file_name)

    return mode


def _enforce_register_save_cms_guard() -> str:
    allowed_cms = (os.getenv("DOCMATE_SAVE_ONLY_CMS_ID") or "").strip().upper()
    cms_id = str(
        (st.session_state.get("selected_customer_profile") or {}).get("cms_customer_id")
        or st.session_state.get("login_cms_customer_id")
        or ""
    ).strip().upper()
    if allowed_cms and cms_id != allowed_cms:
        raise RuntimeError(f"Save blocked: only CMS Customer ID '{allowed_cms}' is allowed.")
    return cms_id


def _save_batch_to_register(batch: List[Dict[str, Any]]) -> Dict[str, Any]:
    summary = {"saved": 0, "updated": 0, "skipped": 0, "failed": 0, "errors": []}
    _enforce_register_save_cms_guard()
    for res in (batch or []):
        if not isinstance(res, dict) or res.get("error"):
            continue
        try:
            mode = _upsert_register(
                inv_key=str(res.get("inv_key") or ""),
                header=(res.get("header") or {}),
                items=(res.get("items") or []),
                doc_type=str(res.get("doc_type") or ""),
                engine_used=str(res.get("engine") or ""),
                file_name=str(res.get("file") or ""),
                save_customer_db=True,
            )
            if mode == "skipped":
                summary["skipped"] += 1
            elif mode == "updated":
                summary["updated"] += 1
            else:
                summary["saved"] += 1
        except Exception as e:
            summary["failed"] += 1
            summary["errors"].append(f"{res.get('file') or 'document'}: {e}")
    return summary

def _get_register_rows(doc_type: str, limit: int = 200) -> List[Dict[str, Any]]:
    rows = _db_fetchall(
        """SELECT * FROM purchase_invoices
           WHERE doc_type=?
           ORDER BY processed_at DESC
           LIMIT ?""",
        (doc_type, int(limit)),
    )
    return [dict(r) for r in rows]


def _export_payload_purchase_invoice(inv_key: str) -> Dict[str, Any]:
    """Build combined export payload including customer profile + invoice header + line items.
    This is the 'single JSON' per invoice used for reconciliation and future SPOS Cloud mapping.
    """
    header_row = _db_fetchone("SELECT * FROM purchase_invoices WHERE inv_key=?", (inv_key,))
    if not header_row:
        return {}
    items_rows = _db_fetchall(
        "SELECT * FROM purchase_invoice_items WHERE inv_key=? ORDER BY line_no",
        (inv_key,),
    )

    # Selected customer profile comes from Dashboard customer selector (CMS-first)
    cp = st.session_state.get("selected_customer_profile") or {}

    payload: Dict[str, Any] = {
        "exportedAt": _uk_now_iso(),
        "customer": {
            "CMS_CustomerID": cp.get("cms_customer_id", "") or "",
            "SPOS_CustomerID": (cp.get("spos_customer_id") or "N/A"),
            "Customer_Name": cp.get("customer_name", "") or "",
            "Trading_Name": cp.get("trading_name", "") or "",
            "Company_Name": cp.get("company_name", "") or "",
            "VAT_Registration_No": cp.get("vat_registration_no", "") or "",
            "Contact_No": cp.get("contact_no", "") or "",
            "Email_Address": cp.get("email_address", "") or "",
        },
        "invoiceHeader": dict(header_row),
        "lineItems": [dict(r) for r in (items_rows or [])],
    }

    # If we already calculate/store VAT breakdown elsewhere, keep it when present
    try:
        if "vatBreakdown" in dict(header_row):
            payload["vatBreakdown"] = dict(header_row).get("vatBreakdown")
    except Exception:
        pass

    return payload


def _gemini_teacher_rule_from_local_retest(
    *,
    settings: Dict[str, Any],
    header: Dict[str, Any],
    teacher_items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    doc_type: str,
    test_summary: Dict[str, Any],
    existing_template: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Ask Gemini to turn a failed local DocTR teacher retest into a supplier rule patch."""
    line_rows = int((test_summary or {}).get("line_rows") or 0)
    teacher_rows = int((test_summary or {}).get("teacher_line_rows") or len(teacher_items or []) or 0)
    matched_rows = int((test_summary or {}).get("teacher_rows_matched_to_local_text") or 0)
    table_profile_rows = int((test_summary or {}).get("table_profile_rows_matched") or 0)
    confidence_reasons = " ".join(
        str(x).strip()
        for x in ((test_summary or {}).get("confidence_reasons") or [])
        if str(x).strip()
    )
    item_fields = sorted(
        {
            str(k)
            for it in (teacher_items or [])[:20]
            if isinstance(it, dict)
            for k, v in it.items()
            if str(k or "").strip() and v not in (None, "")
        }
    )
    instruction = f"""
Local DocTR teacher training saved reviewed Gemini/corrected rows, but the local template retest did not reproduce the line table well.

Create a supplier-specific template JSON patch that helps local extraction learn this invoice layout from OCR text.

Retest facts:
- local retest line rows: {line_rows}
- reviewed teacher line rows: {teacher_rows}
- teacher rows matched back to OCR text: {matched_rows}
- table profile rows matched: {table_profile_rows}
- confidence/reject notes: {confidence_reasons or "none"}
- reviewed line fields present: {", ".join(item_fields[:40])}

Please infer the printed line-table structure from the OCR/text excerpt and reviewed line examples.
Prefer concrete local template rules:
- header_aliases for the printed supplier, customer, invoice number, invoice date, net, VAT and gross labels; learn labels/relative context, never hard-code this invoice's number, date or totals
- table_profile header/column mapping when this is a normal line table
- charge_sections when rows live under a separate fee/surcharge/freight/service section
- line_aliases for useful extra columns such as discount, vatCode, surcharge, weight, service, casePack, or unitSize
- gemini_supplier_instructions explaining the same rule in English for future Gemini fallback

Do not create broad rules that capture totals, VAT summary, payment terms, address blocks, or bank details.
""".strip()
    return _gemini_json_for_template_rule(
        settings=settings,
        instruction=instruction,
        header=header,
        items=teacher_items,
        raw_text=raw_text,
        file_name=file_name,
        doc_type=doc_type,
        existing_template=existing_template,
    )


def _validate_teacher_rule_payload_on_local_text(
    *,
    payload: Dict[str, Any],
    teacher_header: Dict[str, Any],
    teacher_items: List[Dict[str, Any]],
    raw_text: str,
    doc_type: str,
) -> Dict[str, Any]:
    """Gate automatic Gemini-teacher promotion with a deterministic local replay.

    A template parser merely executing is not sufficient. The replay must
    produce rows, reproduce the reviewed monetary rows, and reconcile with the
    reviewed header before a generated supplier rule is saved automatically.
    """
    reviewed_rows = _recalc_items(_template_training_items(copy.deepcopy(teacher_items or [])))
    summary: Dict[str, Any] = {
        "passed": False,
        "template_used": False,
        "line_rows": 0,
        "teacher_line_rows": len(reviewed_rows),
        "matched_amount_rows": 0,
        "matched_semantic_rows": 0,
        "reconciliation_diff": 999999.0,
        "reason": "Local replay was not run.",
    }
    if not isinstance(payload, dict) or not reviewed_rows or not str(raw_text or "").strip():
        summary["reason"] = "Missing generated template, reviewed rows, or local OCR text."
        return summary

    try:
        local_data = LocalInvoiceParser.parse(raw_text or "", str(doc_type or "Purchase Invoice"))
        replay_header = copy.deepcopy(local_data.get("header") or {})
        replay_items = copy.deepcopy(local_data.get("items") or [])
        replay_header, replay_items, template_used = _apply_trained_supplier_template_agent(
            replay_header,
            replay_items,
            raw_text or "",
            payload,
        )
        replay_header, replay_items = _apply_supplier_template_rules(replay_header, replay_items, payload)
        replay_items = _recalc_items_for_engine(copy.deepcopy(replay_items or []), "local_doctr")
        replay_diff = _template_agent_reconciliation_diff(teacher_header or {}, replay_items, raw_text or "")

        unmatched = list(range(len(replay_items)))
        matched_amount_rows = 0
        matched_semantic_rows = 0
        for teacher_row in reviewed_rows:
            teacher_net = round(_safe_float(teacher_row.get("lineNet")), 2)
            teacher_gross = round(_effective_line_gross(teacher_row), 2)
            teacher_qty = _safe_float(teacher_row.get("qty"))
            teacher_price = _safe_float(teacher_row.get("unitPrice"))
            teacher_desc = _collapse_spaces(str(teacher_row.get("description") or "")).strip()
            teacher_words = [
                word
                for word in re.findall(r"[A-Z0-9]{3,}", teacher_desc.upper())
                if not word.isdigit()
            ][:8]
            best_idx: Optional[int] = None
            amount_candidate_found = False
            for idx in unmatched:
                row = replay_items[idx]
                if not isinstance(row, dict):
                    continue
                net_ok = _template_agent_value_matches(teacher_net, row.get("lineNet"))
                gross_ok = teacher_gross <= 0 or _template_agent_value_matches(teacher_gross, _effective_line_gross(row))
                if not (net_ok and gross_ok):
                    continue
                amount_candidate_found = True
                replay_desc = _collapse_spaces(str(row.get("description") or "")).strip()
                replay_upper = replay_desc.upper()
                description_ok = bool(
                    (not teacher_words)
                    or (
                        sum(1 for word in teacher_words if word in replay_upper) >= min(2, len(teacher_words))
                        and len(replay_desc) <= max(len(teacher_desc) * 3, len(teacher_desc) + 24)
                    )
                )
                qty_ok = teacher_qty <= 0 or _template_agent_value_matches(teacher_qty, row.get("qty"))
                price_ok = teacher_price <= 0 or _template_agent_value_matches(teacher_price, row.get("unitPrice"))
                if description_ok and qty_ok and price_ok:
                    best_idx = idx
                    break
            if amount_candidate_found:
                matched_amount_rows += 1
            if best_idx is not None:
                unmatched.remove(best_idx)
                matched_semantic_rows += 1

        required_matches = max(1, int(math.ceil(len(reviewed_rows) * 0.8)))
        header_total = max(
            abs(_safe_float((teacher_header or {}).get("totalNet"))),
            abs(_safe_float((teacher_header or {}).get("totalGross"))),
        )
        diff_limit = max(0.05, header_total * 0.002)
        row_limit = max(len(reviewed_rows) + 1, int(math.ceil(len(reviewed_rows) * 1.2)))
        passed = bool(
            template_used
            and replay_items
            and matched_amount_rows >= required_matches
            and matched_semantic_rows >= required_matches
            and len(replay_items) <= row_limit
            and replay_diff <= diff_limit
        )
        summary.update(
            {
                "passed": passed,
                "template_used": bool(template_used),
                "line_rows": len(replay_items),
                "matched_amount_rows": matched_amount_rows,
                "matched_semantic_rows": matched_semantic_rows,
                "reconciliation_diff": round(float(replay_diff), 2),
                "reason": (
                    "Verified local replay reproduced the reviewed descriptions, quantities, prices and monetary rows."
                    if passed
                    else (
                        f"Local replay not safe to auto-save: parser_used={bool(template_used)}, "
                        f"rows={len(replay_items)}, amount_matches={matched_amount_rows}/{len(reviewed_rows)}, "
                        f"semantic_matches={matched_semantic_rows}/{len(reviewed_rows)}, "
                        f"diff={round(float(replay_diff), 2)}."
                    )
                ),
            }
        )
    except Exception as exc:
        summary["reason"] = f"Local replay validation failed: {exc}"
    return summary


def _gemini_invoice_learning_rule(
    *,
    settings: Dict[str, Any],
    header: Dict[str, Any],
    teacher_items: List[Dict[str, Any]],
    raw_text: str,
    file_name: str,
    doc_type: str,
    existing_template: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Ask Gemini to infer a local supplier-template rule from the reviewed invoice itself."""
    item_fields = sorted(
        {
            str(k)
            for it in (teacher_items or [])[:40]
            if isinstance(it, dict)
            for k, v in it.items()
            if str(k or "").strip() and v not in (None, "")
        }
    )
    instruction = f"""
Learn this supplier invoice layout from the OCR/text excerpt and reviewed line examples.

The user may not know the rule. You must infer the structure yourself and return a supplier-template JSON patch that helps local DocTR extract the same data next time.

Use the reviewed line examples as the teacher output. They are correct or user-reviewed.

Create concrete local extraction rules:
- If there is a normal printed line table, return table_profile with header_fields and columns for the printed headings.
- If there are separate fee/charge/surcharge/freight/service sections, return charge_sections rules.
- Map useful line columns including code, description, qty, unitPrice, discount, lineNet, vatCode, vatRate, vatAmount, lineGross, unitSize, casePack, weight, service, surcharge where visible.
- Learn the reviewed/Gemini line output format as a teacher pattern. If the reviewed rows show multiple no-code subscription/change/adjustment rows, preserve those as separate line rows in future Gemini extraction. Do not collapse them into a single invoice-total line.
- When multiple reviewed rows have similar product names but different business meaning, set rules.preserve_teacher_line_rows=true and include gemini_supplier_instructions describing the separate row structure.
- Include gemini_supplier_instructions explaining the inferred layout for future Gemini fallback.
- Preserve all useful extracted line information in supported fields when possible.

Do not require the user to describe the rule.
Do not create broad rules that capture totals, VAT summary, payment terms, address blocks, bank details, or page footers.

Invoice file: {file_name}
Supplier: {str((header or {}).get("supplierName") or "")}
Invoice number: {str((header or {}).get("invoiceNumber") or "")}
Reviewed line count: {len(teacher_items or [])}
Reviewed line fields present: {", ".join(item_fields[:50])}
""".strip()
    return _gemini_json_for_template_rule(
        settings=settings,
        instruction=instruction,
        header=header,
        items=teacher_items,
        raw_text=raw_text,
        file_name=file_name,
        doc_type=doc_type,
        existing_template=existing_template,
    )


def _local_invoice_learning_rule_patch(
    *,
    teacher_items: List[Dict[str, Any]],
    raw_text: str,
    reason: str = "",
) -> Dict[str, Any]:
    """Build a local supplier-template rule patch from reviewed invoice lines."""
    teacher_items = _template_training_items(teacher_items)
    table_profile = _template_table_profile_from_text_and_items(teacher_items, raw_text or "")
    charge_sections = _template_charge_section_rules_from_text_and_items(teacher_items, raw_text or "")
    learned_agent = _learn_template_agent_from_corrections(teacher_items, raw_text or "")
    rules: Dict[str, Any] = {
        "do_not_create_blank_zero_rows": True,
    }
    if any(
        isinstance(it, dict)
        and str(it.get("description") or "").strip()
        and not str(it.get("code") or "").strip()
        for it in teacher_items
    ):
        rules["allow_missing_code"] = True
        rules["line_match_strategy"] = "description_anchor"
    notes = [
        reason or "Created local smart-learning proposal from reviewed invoice rows.",
        f"Reviewed line rows available: {len(teacher_items)}.",
    ]
    if learned_agent:
        notes.append(f"Local line parser learned from {int(learned_agent.get('trained_rows') or 0)} OCR row match(es).")
    if table_profile:
        notes.append(f"Reusable table profile learned with {int(table_profile.get('matched_rows') or 0)} matched row(s).")
    if charge_sections:
        notes.append(f"Learned {len(charge_sections)} charge/fee section rule(s).")
    if not learned_agent and not table_profile and not charge_sections:
        notes.append("No strong local line pattern was detected; save only after preview confirms useful rows.")
    patch: Dict[str, Any] = {
        "notes": notes,
        "rules": rules,
    }
    if table_profile:
        patch["table_profile"] = table_profile
    if charge_sections:
        patch["charge_sections"] = charge_sections
    return patch


def _normalised_invoice_audit_payload(
    *,
    inv_key: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    doc_type: str,
    file_name: str,
    engine_used: str = "",
    template_used: str = "",
    template_parser_type: str = "",
    confidence: Optional[Dict[str, Any]] = None,
    metrics: Optional[Dict[str, Any]] = None,
    reconciliation: Optional[Dict[str, Any]] = None,
    recon_notes: Optional[List[str]] = None,
    source_text: str = "",
) -> Dict[str, Any]:
    """Build a review-time JSON payload for audit and future ERP endpoint posting."""
    hdr = dict(header or {})
    rows = _ensure_line_numbers([dict(it) for it in (items or []) if isinstance(it, dict)])
    recon_items = _reconciliation_items(hdr, rows, source_text or "")
    calc_metrics = dict(metrics or _calc_metrics(hdr, recon_items))
    calc_recon = dict(reconciliation or _build_reconciliation_status(calc_metrics))
    cp = st.session_state.get("selected_customer_profile") or {}

    def _f(value: Any) -> float:
        return float(round(_safe_float(value), 4))

    def _s(value: Any) -> str:
        return str(value or "").strip()

    lines: List[Dict[str, Any]] = []
    for idx, it in enumerate(rows, start=1):
        if not isinstance(it, dict):
            continue
        line_net = _f(it.get("lineNet"))
        vat_amount = _f(it.get("vatAmount"))
        line_gross = _f(it.get("lineGross")) if _safe_float(it.get("lineGross")) else round(line_net + vat_amount, 4)
        standard_line_keys = {
            "lineNo", "type", "code", "barcode", "description", "qty", "quantity", "unitSize",
            "casePack", "unitPrice", "discount", "lineNet", "vatCode", "vatRate", "vatAmount",
            "lineGross", "stdRrp", "por", "isVoid", "rowTag", "_reconOnly", "rawRow", "raw",
            "totalUnits", "casePackText", "voidNote",
        }
        extra_fields = {
            str(k): v
            for k, v in it.items()
            if str(k) not in standard_line_keys and not str(k).startswith("_")
        }
        lines.append(
            {
                "lineNo": int(_safe_float(it.get("lineNo")) or idx),
                "type": "charge" if bool(it.get("_reconOnly")) or _s(it.get("rowTag")).upper() in {"RECON", "CHARGE"} else "item",
                "code": _s(it.get("code")),
                "barcode": _s(it.get("barcode")),
                "description": _s(it.get("description")),
                "quantity": _f(it.get("qty")),
                "unit": _s(it.get("unitSize")),
                "casePack": _s(it.get("casePack")),
                "unitPrice": _f(it.get("unitPrice")),
                "discount": _f(it.get("discount")),
                "net": line_net,
                "vatCode": _s(it.get("vatCode")),
                "vatRate": _f(it.get("vatRate")),
                "vatAmount": vat_amount,
                "gross": line_gross,
                "stdRrp": _f(it.get("stdRrp")),
                "por": _f(it.get("por")),
                "isVoid": bool(it.get("isVoid")),
                "rowTag": _s(it.get("rowTag")),
                "reconciliationOnly": bool(it.get("_reconOnly")),
                "rawRow": _s(it.get("rawRow") or it.get("raw")),
                "extraFields": extra_fields,
            }
        )

    vat_breakdown = hdr.get("vatBreakdown") or _compute_vat_breakdown_from_lines(
        [
            {
                "vat_code": ln.get("vatCode"),
                "vat_rate": ln.get("vatRate"),
                "line_net": ln.get("net"),
                "vat_amount": ln.get("vatAmount"),
                "line_gross": ln.get("gross"),
            }
            for ln in lines
        ]
    )
    standard_header_keys = {
        "supplierName", "supplierCode", "supplier_code", "customerName", "customerCode", "customer_code",
        "invoiceNumber", "invoiceDate", "currency", "totalNet", "totalVat", "totalGross",
        "deliveryCharge", "customerPONumber", "orderNumber", "accountNumber", "paymentDueDate",
        "vatRegistrationNumber", "vat_number", "vatBreakdown", "extractionMode",
    }
    header_extra_fields = {
        str(k): v
        for k, v in hdr.items()
        if str(k) not in standard_header_keys and not str(k).startswith("_")
    }
    invoice_name_parts = [
        _s(hdr.get("supplierName")) or _s(file_name) or "invoice",
        _s(hdr.get("invoiceNumber")),
        _s(hdr.get("invoiceDate")),
    ]
    invoice_name = " - ".join([p for p in invoice_name_parts if p])

    payload = {
        "invoiceName": invoice_name,
        "header": {
            "supplierName": _s(hdr.get("supplierName")),
            "supplierCode": _s(hdr.get("supplierCode") or hdr.get("supplier_code")),
            "supplierVatNumber": _s(hdr.get("vatRegistrationNumber") or hdr.get("vat_number")),
            "customerName": _s(hdr.get("customerName")),
            "customerCode": _s(hdr.get("customerCode") or hdr.get("customer_code")),
            "invoiceNumber": _s(hdr.get("invoiceNumber")),
            "invoiceDate": _s(hdr.get("invoiceDate")),
            "currency": _s(hdr.get("currency")) or "GBP",
            "totalNet": _f(hdr.get("totalNet")),
            "totalVat": _f(hdr.get("totalVat")),
            "totalGross": _f(hdr.get("totalGross")),
            "deliveryCharge": _f(hdr.get("deliveryCharge")),
            "customerPONumber": _s(hdr.get("customerPONumber")),
            "orderNumber": _s(hdr.get("orderNumber")),
            "accountNumber": _s(hdr.get("accountNumber")),
            "paymentDueDate": _s(hdr.get("paymentDueDate")),
            "vatBreakdown": vat_breakdown,
            "customerProfile": {
            "cmsCustomerId": _s(cp.get("cms_customer_id") or st.session_state.get("login_cms_customer_id")),
            "sposCustomerId": _s(cp.get("spos_customer_id")) or "N/A",
            "sposSiteId": _s(cp.get("spos_site_id")),
            "name": _s(cp.get("customer_name")),
            "tradingName": _s(cp.get("trading_name")),
            "companyName": _s(cp.get("company_name")),
            "vatRegistrationNo": _s(cp.get("vat_registration_no")),
            "contactNo": _s(cp.get("contact_no")),
            "emailAddress": _s(cp.get("email_address")),
            },
            "audit": {
                "schema": "docmate.invoice.endpoint.audit.v1",
                "createdAt": _uk_now_iso(),
                "status": "audit_only",
                "invKey": _s(inv_key),
                "fileName": _s(file_name),
                "docType": _s(doc_type),
                "engineUsed": _s(engine_used),
                "templateUsed": _s(template_used),
                "templateParserType": _s(template_parser_type),
                "confidence": dict(confidence or {}),
                "reconciliation": {
                    "status": calc_recon,
                    "notes": [str(x) for x in (recon_notes or _build_reconciliation_notes(calc_metrics))],
                    "metrics": calc_metrics,
                },
            },
            "extraFields": header_extra_fields,
        },
        "lines": lines,
    }
    try:
        return _json_safe_model(payload)
    except Exception:
        return payload


def _build_dedicated_invoice_export(payload: Dict[str, Any]) -> Dict[str, Any]:
    """Dedicated export format (customer first, then invoice header, then line items).
    Designed to be stable for VBR reconciliation/import pipelines.
    """
    customer = payload.get("customer") or {}
    invh = payload.get("invoiceHeader") or {}
    items = payload.get("lineItems") or []
    vat = payload.get("vatBreakdown") or invh.get("vat_breakdown") or invh.get("vatBreakdown") or None

    dedicated: Dict[str, Any] = {
        "Customer": {
            "CMS_CustomerID": customer.get("CMS_CustomerID", ""),
            "CMS_CustomerName": customer.get("Customer_Name", ""),
            "SPOS_CustomerID": customer.get("SPOS_CustomerID", "N/A") or "N/A",
            "Trading_Name": customer.get("Trading_Name", ""),
            "Company_Name": customer.get("Company_Name", ""),
            "VAT_Registration_No": customer.get("VAT_Registration_No", ""),
            "Contact_No": customer.get("Contact_No", ""),
            "Email_Address": customer.get("Email_Address", ""),
        },
        "Invoice": invh,
        "LineItems": items,
    }
    if vat is not None:
        dedicated["VAT_Breakdown"] = vat
    return dedicated


def _compute_vat_breakdown_from_lines(lines: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Compute VAT breakdown rows from line items (vat_code + vat_rate)."""
    buckets: Dict[Tuple[str, float], Dict[str, float]] = {}
    for it in (lines or []):
        code = str(it.get("vat_code") or "").strip() or "NA"
        try:
            rate = float(_normalise_vat_rate(it.get("vat_rate")) or 0.0)
        except Exception:
            rate = 0.0
        key = (code, rate)
        b = buckets.setdefault(key, {"net": 0.0, "vat": 0.0, "gross": 0.0})
        try:
            b["net"] += float(it.get("line_net") or 0.0)
        except Exception:
            pass
        try:
            b["vat"] += _effective_db_line_vat(it)
        except Exception:
            pass
        try:
            b["gross"] += _effective_db_line_gross(it)
        except Exception:
            pass

    out: List[Dict[str, Any]] = []
    for (code, rate), sums in sorted(buckets.items(), key=lambda x: (x[0][0], x[0][1])):
        out.append({
            "vat_code": code,
            "vat_rate": rate,
            "net": round(sums["net"], 2),
            "vat": round(sums["vat"], 2),
            "gross": round(sums["gross"], 2),
        })
    return out


def _invoice_export_full_csv_bytes(payload: Dict[str, Any]) -> bytes:
    """Build the dedicated FULL export CSV (customer + header + VAT/metrics + line items).
    One row per line item; customer + header repeated for SQL import into VBR local/SPOS Cloud DBs.
    """
    cust = payload.get("customer") or {}
    invh = payload.get("invoiceHeader") or {}
    lines = payload.get("lineItems") or []

    # Header totals (as stored)
    def _f(x: Any) -> float:
        try:
            return float(x)
        except Exception:
            return 0.0

    def _matches(a: float, b: float, eps: float = 0.05) -> bool:
        return abs(round(a, 2) - round(b, 2)) <= eps

    header_net = _f(invh.get("net_amount") or invh.get("totalNet") or invh.get("net") or 0.0)
    header_vat = _f(invh.get("vat_amount") or invh.get("totalVat") or invh.get("vat") or 0.0)
    header_gross = _f(invh.get("gross_amount") or invh.get("totalGross") or invh.get("gross") or 0.0)

    # Sums from lines
    line_sum_net = round(sum(_f(x.get("line_net")) for x in (lines or [])), 2)
    line_sum_vat = round(sum(_effective_db_line_vat(x) for x in (lines or [])), 2)
    line_sum_gross = round(sum(_effective_db_line_gross(x) for x in (lines or [])), 2)

    # VAT breakdown
    vat_rows = payload.get("vatBreakdown")
    if isinstance(vat_rows, str):
        try:
            vat_rows = json.loads(vat_rows)
        except Exception:
            vat_rows = None
    if not isinstance(vat_rows, list):
        vat_rows = _compute_vat_breakdown_from_lines(lines)

    vat_sum_net = round(sum(_f(v.get("net")) for v in vat_rows), 2)
    vat_sum_vat = round(sum(_f(v.get("vat")) for v in vat_rows), 2)
    vat_sum_gross = round(sum(_f(v.get("gross")) for v in vat_rows), 2)

    totals_match_flag = "Y" if (_matches(header_net, vat_sum_net) and _matches(header_vat, vat_sum_vat) and _matches(header_gross, vat_sum_gross)) else "N"
    lines_match_flag = "Y" if (_matches(header_net, line_sum_net) and _matches(header_vat, line_sum_vat) and _matches(header_gross, line_sum_gross)) else "N"

    # Metrics
    count_total_case_qty = _f(invh.get("total_case_qty") or invh.get("totalCaseQty") or 0.0)
    count_total_units = _f(invh.get("total_units") or invh.get("totalUnits") or 0.0)
    count_products = int(_f(invh.get("total_lines") or invh.get("totalLines") or len(lines)))

    avg_por = 0.0
    try:
        pors = [float(x.get("por") or 0.0) for x in lines]
        pors = [p for p in pors if p > 0]
        avg_por = round(sum(pors)/len(pors), 2) if pors else 0.0
    except Exception:
        avg_por = 0.0

    vat_breakdown_json = json.dumps(vat_rows, ensure_ascii=False)

    # Build dataframe rows
    rows: List[Dict[str, Any]] = []
    base = {
        # A) Customer identity (must be first)
        "CMS_CustomerID": cust.get("CMS_CustomerID") or "",
        "CMS_CustomerName": cust.get("Customer_Name") or "",
        "SPOS_CustomerID": cust.get("SPOS_CustomerID") or "N/A",
        "Customer_Name": cust.get("Customer_Name") or "",
        "Trading_Name": cust.get("Trading_Name") or "",
        "Company_Name": cust.get("Company_Name") or "",
        "VAT_Registration_No": cust.get("VAT_Registration_No") or "",
        "Contact_No": cust.get("Contact_No") or "",
        "Email_Address": cust.get("Email_Address") or "",

        # B) Invoice header
        "inv_key": invh.get("inv_key") or payload.get("inv_key") or "",
        "doc_type": "Purchase Invoice",
        "source_file_name": invh.get("file_name") or payload.get("source_file_name") or "",
        "engine_used": invh.get("engine_used") or payload.get("engine_used") or "",
        "template_used": payload.get("template_used") or "",
        "supplier_name": invh.get("supplier_name") or "",
        "supplier_code": invh.get("supplier_code") or "",
        "invoice_number": invh.get("invoice_number") or "",
        "invoice_date": invh.get("invoice_date") or "",
        "currency": invh.get("currency") or "GBP",
        "header_total_net": round(header_net, 2),
        "header_total_vat": round(header_vat, 2),
        "header_total_gross": round(header_gross, 2),

        # C) VAT breakdown + checks
        "vat_breakdown_json": vat_breakdown_json,
        "vat_sum_net": vat_sum_net,
        "vat_sum_vat": vat_sum_vat,
        "vat_sum_gross": vat_sum_gross,
        "totals_match_flag": totals_match_flag,
        "line_sum_net": line_sum_net,
        "line_sum_vat": line_sum_vat,
        "line_sum_gross": line_sum_gross,
        "lines_match_flag": lines_match_flag,

        # D) Metrics
        "count_total_case_qty": round(count_total_case_qty, 2),
        "count_total_units": round(count_total_units, 2),
        "count_products": count_products,
        "avg_por_pct": avg_por,
    }

    for it in (lines or []):
        case_pack = _f(it.get("case_pack") or 0.0)
        qty_cases = _f(it.get("qty_cases") or 0.0)
        total_units = round(case_pack * qty_cases, 2) if case_pack and qty_cases else ""
        row = dict(base)
        row.update({
            "line_no": it.get("line_no"),
            "code": it.get("code") or "",
            "barcode": it.get("barcode") or "",
            "description": it.get("description") or "",
            "case_pack": it.get("case_pack"),
            "case_pack_text": it.get("case_pack_text") or "",
            "unit_size": it.get("unit_size") or "",
            "qty_cases": it.get("qty_cases"),
            "total_units": total_units,
            "unit_price": it.get("unit_price"),
            "line_net": it.get("line_net"),
            "vat_code": it.get("vat_code") or "",
            "vat_rate": it.get("vat_rate"),
            "vat_amount": it.get("vat_amount"),
            "line_gross": it.get("line_gross"),
            "std_rrp": it.get("std_rrp"),
            "por": it.get("por"),
            "is_void": it.get("is_void"),
            "void_note": it.get("void_note") or "",
        })
        rows.append(row)

    if not rows:
        rows = [base]

    df = pd.DataFrame(rows)
    # Ensure stable column order (customer first, then header, then VAT/metrics, then lines)
    desired = [
        "CMS_CustomerID","CMS_CustomerName","SPOS_CustomerID","Customer_Name","Trading_Name","Company_Name","VAT_Registration_No","Contact_No","Email_Address",
        "inv_key","doc_type","source_file_name","engine_used","template_used","supplier_name","supplier_code","invoice_number","invoice_date","currency","header_total_net","header_total_vat","header_total_gross",
        "vat_breakdown_json","vat_sum_net","vat_sum_vat","vat_sum_gross","totals_match_flag","line_sum_net","line_sum_vat","line_sum_gross","lines_match_flag",
        "count_total_case_qty","count_total_units","count_products","avg_por_pct",
        "line_no","code","barcode","description","case_pack","case_pack_text","unit_size","qty_cases","total_units","unit_price","line_net","vat_code","vat_rate","vat_amount","line_gross","std_rrp","por","is_void","void_note"
    ]
    cols = [c for c in desired if c in df.columns] + [c for c in df.columns if c not in desired]
    df = df[cols]
    return df.to_csv(index=False).encode("utf-8")


def _invoice_export_file_names(inv_key: str, payload: Dict[str, Any]) -> Dict[str, str]:
    """Return consistent filenames for export artifacts."""
    cust = payload.get("customer") or {}
    invh = payload.get("invoiceHeader") or {}

    cms = _safe_filename(str(cust.get("CMS_CustomerID") or "CMSNA"))
    spos = _safe_filename(str(cust.get("SPOS_CustomerID") or "N/A"))
    inv_no = _safe_filename(str(invh.get("invoice_number") or invh.get("invoiceNumber") or inv_key))
    inv_dt = _safe_filename(str(invh.get("invoice_date") or invh.get("invoiceDate") or ""))

    stem = f"{cms}_{spos}_{inv_no}" + (f"_{inv_dt}" if inv_dt else "")
    return {
        "single_json": f"{stem}_DocMate_Invoice.json",
        "dedicated_json": f"{stem}_VBR_InvoiceExport.json",
        "lines_csv": f"{stem}_LineItems.csv",
        "full_csv": f"{stem}_InvoiceExport_Full.csv",
    }


def _write_invoice_exports(inv_key: str, payload: Dict[str, Any]) -> Dict[str, str]:
    """Write per-invoice export files to DocsEXPORT/JSON and return paths."""
    _ensure_data_dir()
    out_dir = os.path.join(DATA_DIR, "DocsEXPORT", "JSON")
    os.makedirs(out_dir, exist_ok=True)

    names = _invoice_export_file_names(inv_key, payload)

    p_single = os.path.join(out_dir, names["single_json"])
    p_ded = os.path.join(out_dir, names["dedicated_json"])

    try:
        with open(p_single, "w", encoding="utf-8") as f:
            json.dump(payload, f, indent=2, ensure_ascii=False)
    except Exception as e:
        _log_event(f"ERROR writing single invoice JSON: {e}", inv_key)

    try:
        dedicated = _build_dedicated_invoice_export(payload)
        with open(p_ded, "w", encoding="utf-8") as f:
            json.dump(dedicated, f, indent=2, ensure_ascii=False)
    except Exception as e:
        _log_event(f"ERROR writing dedicated invoice JSON: {e}", inv_key)

    paths = {
        "single_json": p_single,
        "dedicated_json": p_ded,
    }


    # CSV exports
    try:
        if pd is not None:
            # Compact line-items-only CSV (kept for quick checking)
            df_lines = pd.DataFrame(payload.get("lineItems") or [])
            p_lines = os.path.join(out_dir, names["lines_csv"])
            df_lines.to_csv(p_lines, index=False)
            paths["lines_csv"] = p_lines
            _log_event(f"Export file written: {os.path.basename(p_lines)}", inv_key)

            # FULL Invoice Export CSV (customer + header + VAT/metrics + lines) for VBR SQL import
            p_full = os.path.join(out_dir, names["full_csv"])
            with open(p_full, "wb") as f:
                f.write(_invoice_export_full_csv_bytes(payload))
            paths["full_csv"] = p_full
            _log_event(f"Export file written: {os.path.basename(p_full)}", inv_key)
    except Exception as e:
        _log_event(f"ERROR writing CSV exports: {e}", inv_key)

    _log_event("Export write-to-disk completed (single_json, dedicated_json, csv).", inv_key)
    return paths



def _spos_export_config(settings: Dict[str, Any]) -> Dict[str, Any]:
    """Return SPOS export configuration (placeholder until API endpoint/auth is finalised)."""
    cfg = settings.get("spos_export") or {}
    return {
        "enabled": bool(cfg.get("enabled", False)),
        "base_url": str(cfg.get("base_url", "") or ""),
        "auth_method": str(cfg.get("auth_method", "") or ""),
        "auth_token": str(cfg.get("auth_token", "") or ""),
        "endpoint_pattern": str(cfg.get("endpoint_pattern", "") or ""),
    }


def _reset_register(doc_type: str) -> int:
    """
    Admin action: deletes stored documents from the register for the given doc_type.
    Returns number of invoices deleted.
    """
    inv_keys = _db_fetchall("SELECT inv_key FROM purchase_invoices WHERE doc_type=?", (doc_type,))
    inv_keys = [r["inv_key"] for r in inv_keys] if inv_keys else []
    if not inv_keys:
        return 0

    # Delete child rows first
    for k in inv_keys:
        _db_exec("DELETE FROM purchase_invoice_items WHERE inv_key=?", (k,))
    _db_exec("DELETE FROM purchase_invoices WHERE doc_type=?", (doc_type,))
    return len(inv_keys)


def _get_invoice(inv_key: str) -> Optional[Dict[str, Any]]:
    row = _db_fetchone("SELECT * FROM purchase_invoices WHERE inv_key=?", (inv_key,))
    if not row:
        return None
    inv = dict(row)
    items = _db_fetchall("SELECT * FROM purchase_invoice_items WHERE inv_key=? ORDER BY line_no", (inv_key,))
    inv["items"] = [dict(i) for i in items]
    return inv


