def _default_prd_markdown() -> str:
    return """# DocMate Technical PRD (Draft)

## 1. Purpose
DocMate is a web application by **Visual Business Retail Ltd (VBR)** that captures invoices and documents, extracts key header values and (where required) line items, and saves validated data into registers to support downstream workflows such as **VBR EPOS**, **VBR Cloud Reporting**, **Loyalty**, and **Online Ordering**.

## 2. Key Concepts
- **Document Types**
  - Purchase Invoice (payable)
  - Service Invoice (payable)
  - Sales Invoice (receivable)
  - Commission Invoice (receivable)

- **Templates**
  - Supplier Templates: matched for Purchase/Service documents using supplier identity.
  - Customer Templates: matched for Sales/Commission documents using customer identity.

## 3. Processing Engines
- **Auto**: Template match  PDF text layer  OCR fallback  (optional) Cloud AI.
- **Local OCR**: Tesseract / EasyOCR.
- **Cloud AI**: Customer provides their own Google API key (stored securely) for template building/extraction.

## 4. Registers
- Each saved document is routed to its register based on **Document Type**.
- Purchase invoices can capture full line items; Service invoices can be configured to capture header + simplified items.

## 5. Admin / System Information
- System tree: version history, PRD, event logs, and configuration.
- Customer profile: Site ID, trading name/address, buyer aliases.

## 6. Booker (BKL) Priority
- Booker purchase invoices are supported with a fast path (PDF text layer first), and a supplier template ID prefix **BKL**.
"""


def _db_get_system_doc(doc_key: str) -> Optional[Dict[str, Any]]:
    row = _db_fetchone("SELECT * FROM system_docs WHERE doc_key=?", (doc_key,))
    return dict(row) if row else None


def _db_update_system_doc(doc_key: str, title: str, content_md: str) -> None:
    _db_exec(
        "INSERT OR REPLACE INTO system_docs(doc_key, title, content_md, updated_at) VALUES(?,?,?,?)",
        (doc_key, title, content_md, _uk_now_iso()),
    )


def _db_get_versions() -> List[Dict[str, Any]]:
        # Backwards compatible: older DBs may have 'notes' column; current schema uses 'release_note'.
    try:
        cols = [r["name"] for r in _db_fetchall("PRAGMA table_info(version_history)")]
    except Exception:
        cols = []
    note_col = "notes" if "notes" in cols else ("release_note" if "release_note" in cols else None)
    if note_col:
        rows = _db_fetchall(f"SELECT version, release_date, {note_col} AS notes FROM version_history")
    else:
        rows = _db_fetchall("SELECT version, release_date, '' AS notes FROM version_history")

    versions = [dict(r) for r in rows]

    def _vkey(v: str) -> Tuple[int, int, int]:
        m = re.search(r"(\d+)\.(\d+)\.(\d+)", v or "")
        if not m:
            return (0, 0, 0)
        return (int(m.group(1)), int(m.group(2)), int(m.group(3)))

    versions.sort(key=lambda d: (_vkey(d.get("version", "")), d.get("release_date", "")), reverse=True)
    return versions


def _pipeline_next_plan_id() -> str:
    rows = _db_fetchall("SELECT plan_id FROM pipeline_tasks WHERE plan_id LIKE 'UP-%'")
    max_num = 0
    for row in rows or []:
        m = re.search(r"UP-(\d+)", str(row.get("plan_id") or ""), flags=re.I)
        if m:
            max_num = max(max_num, int(m.group(1)))
    return f"UP-{max_num + 1:03d}"


def _db_get_pipeline_tasks() -> List[Dict[str, Any]]:
    rows = _db_fetchall(
        """SELECT plan_id, planned_version, module, workstream, priority, status,
                  target, completed_date, detail, sprint_num, sort_order, created_at, updated_at
             FROM pipeline_tasks
             ORDER BY COALESCE(NULLIF(sprint_num,''), target), sort_order, plan_id"""
    )
    return [dict(r) for r in rows or []]


def _db_upsert_pipeline_task(task: Dict[str, Any]) -> None:
    now = _uk_now_iso()
    plan_id = str(task.get("plan_id") or "").strip() or _pipeline_next_plan_id()
    existing = _db_fetchone("SELECT created_at FROM pipeline_tasks WHERE plan_id=?", (plan_id,))
    created_at = str((existing or {}).get("created_at") or now)
    _db_exec(
        """INSERT OR REPLACE INTO pipeline_tasks(
            plan_id, planned_version, module, workstream, priority, status,
            target, completed_date, detail, sprint_num, sort_order, created_at, updated_at
        ) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            plan_id,
            str(task.get("planned_version") or "TBA").strip() or "TBA",
            str(task.get("module") or "").strip(),
            str(task.get("workstream") or "").strip(),
            str(task.get("priority") or "Medium").strip() or "Medium",
            str(task.get("status") or "Planned").strip() or "Planned",
            str(task.get("target") or "").strip(),
            str(task.get("completed_date") or "Pending").strip() or "Pending",
            str(task.get("detail") or "").strip(),
            str(task.get("sprint_num") or "").strip(),
            int(_safe_float(task.get("sort_order"), 0.0)),
            created_at,
            now,
        ),
    )


def _db_delete_pipeline_task(plan_id: str) -> None:
    plan_id = str(plan_id or "").strip()
    if plan_id:
        _db_exec("DELETE FROM pipeline_tasks WHERE plan_id=?", (plan_id,))


def _pipeline_task_stats(tasks: List[Dict[str, Any]]) -> Dict[str, int]:
    total = len(tasks or [])
    completed = sum(1 for t in tasks if str(t.get("status") or "").strip().lower() in {"complete", "completed", "done"})
    paused = sum(1 for t in tasks if str(t.get("status") or "").strip().lower() in {"paused", "hold", "blocked"})
    planned = sum(1 for t in tasks if str(t.get("status") or "").strip().lower() in {"planned", "in progress", "active"})
    high = sum(1 for t in tasks if str(t.get("priority") or "").strip().lower() == "high")
    return {"total": total, "completed": completed, "paused": paused, "planned": planned, "high": high}


def _pipeline_csv(tasks: List[Dict[str, Any]]) -> str:
    buf = io.StringIO()
    fieldnames = [
        "plan_id",
        "planned_version",
        "module",
        "workstream",
        "priority",
        "status",
        "target",
        "completed_date",
        "sprint_num",
        "detail",
        "updated_at",
    ]
    writer = csv.DictWriter(buf, fieldnames=fieldnames)
    writer.writeheader()
    for task in tasks or []:
        writer.writerow({k: task.get(k, "") for k in fieldnames})
    return buf.getvalue()


def _pipeline_group_key(task: Dict[str, Any]) -> str:
    sprint = str(task.get("sprint_num") or "").strip()
    target = str(task.get("target") or "").strip()
    if sprint and target:
        return f"{sprint} - {target}"
    return sprint or target or "Backlog"


def _render_pipeline_work() -> None:
    st.subheader("Upcoming Pipeline Work / Project Tasks")
    st.caption("Internal delivery board for OCR, template learning, data sync, audit and management reporting.")

    tasks = _db_get_pipeline_tasks()
    stats = _pipeline_task_stats(tasks)
    c1, c2, c3, c4, c5 = st.columns(5)
    c1.metric("Pipeline Tasks", stats["total"])
    c2.metric("Completed", stats["completed"])
    c3.metric("Active / Planned", stats["planned"])
    c4.metric("Paused / Blocked", stats["paused"])
    c5.metric("High Priority", stats["high"])

    st.download_button(
        "Download Management CSV",
        data=_pipeline_csv(tasks),
        file_name=f"docmate_pipeline_tasks_{dt.date.today().isoformat()}.csv",
        mime="text/csv",
        use_container_width=True,
    )

    if st.session_state.get("is_admin"):
        with st.expander("Add / Edit Pipeline Task", expanded=False):
            task_by_id = {str(t.get("plan_id") or ""): t for t in tasks}
            choices = ["New task"] + sorted(task_by_id.keys())
            selected = st.selectbox("Record", options=choices, key="pipeline_edit_record")
            current = task_by_id.get(selected, {}) if selected != "New task" else {}
            default_plan_id = current.get("plan_id") or _pipeline_next_plan_id()

            priorities = ["High", "Medium", "Low"]
            statuses = ["Planned", "In Progress", "Completed", "Paused", "Blocked"]
            with st.form("pipeline_task_form"):
                f1, f2 = st.columns(2)
                plan_id = f1.text_input("Plan ID", value=str(default_plan_id))
                planned_version = f2.text_input("Planned Version", value=str(current.get("planned_version") or "TBA"))
                module = f1.text_input("Module", value=str(current.get("module") or ""))
                workstream = f2.text_input("Workstream", value=str(current.get("workstream") or ""))
                target = f1.text_input("Target / Sprint Name", value=str(current.get("target") or ""))
                sprint_num = f2.text_input("Sprint Num", value=str(current.get("sprint_num") or ""))
                completed_date = f1.text_input("Completed Date", value=str(current.get("completed_date") or "Pending"))
                sort_order = f2.number_input("Sort Order", value=int(_safe_float(current.get("sort_order"), 0.0)), step=1)

                cur_priority = str(current.get("priority") or "Medium").title()
                cur_status = str(current.get("status") or "Planned").title()
                priority = f1.selectbox(
                    "Priority",
                    options=priorities,
                    index=priorities.index(cur_priority) if cur_priority in priorities else 1,
                )
                status = f2.selectbox(
                    "Status",
                    options=statuses,
                    index=statuses.index(cur_status) if cur_status in statuses else 0,
                )
                detail = st.text_area("Detail", value=str(current.get("detail") or ""), height=110)
                save = st.form_submit_button("Save Pipeline Task", use_container_width=True)
                if save:
                    _db_upsert_pipeline_task(
                        {
                            "plan_id": plan_id,
                            "planned_version": planned_version,
                            "module": module,
                            "workstream": workstream,
                            "priority": priority,
                            "status": status,
                            "target": target,
                            "completed_date": completed_date,
                            "detail": detail,
                            "sprint_num": sprint_num,
                            "sort_order": sort_order,
                        }
                    )
                    _log_event(f"Admin saved pipeline task {plan_id}")
                    st.success(f"Saved pipeline task {plan_id}")
                    st.rerun()

            if selected != "New task" and st.button("Delete Selected Pipeline Task", type="secondary"):
                _db_delete_pipeline_task(selected)
                _log_event(f"Admin deleted pipeline task {selected}")
                st.warning(f"Deleted pipeline task {selected}")
                st.rerun()

    if not tasks:
        st.info("No pipeline tasks recorded yet.")
        return

    table_cols = [
        "plan_id",
        "planned_version",
        "module",
        "workstream",
        "priority",
        "status",
        "target",
        "completed_date",
        "detail",
    ]
    if pd is not None:
        st.dataframe(pd.DataFrame(tasks)[table_cols], width="stretch", hide_index=True)
    else:
        st.write([{k: t.get(k, "") for k in table_cols} for t in tasks])

    groups: Dict[str, List[Dict[str, Any]]] = {}
    for task in tasks:
        groups.setdefault(_pipeline_group_key(task), []).append(task)
    for group, group_tasks in groups.items():
        complete = _pipeline_task_stats(group_tasks)["completed"]
        with st.expander(f"{group} - {len(group_tasks)} tasks - {complete} completed", expanded=False):
            if pd is not None:
                st.dataframe(pd.DataFrame(group_tasks)[table_cols], width="stretch", hide_index=True)
            else:
                st.write([{k: t.get(k, "") for k in table_cols} for t in group_tasks])


