                                        dpi=int(settings.get("ocr_dpi", 250)),
                                        max_pages=_effective_max_pages(
                                            settings,
                                            supplier_hint=(doc_text_hint or "") + "\n" + (file_name or ""),
                                            file_bytes=file_bytes,
                                            mime=mime,
                                            default_pages=int(settings.get("ocr_max_pages", 10) or 10),
                                        ),
