                                    parser = BookerCombinedRowParser()
                                    stacked_items = parser.parse_stacked_layout(txt)
                                    row_text = _booker_build_rowified_text(txt)
                                    row_items = parser.parse(row_text) if row_text else []
                                    # Prefer stacked layout (best for Booker multi-line rows)
                                    if (not items) and stack2_items and (not expected_total or len(stack2_items) >= max(1, expected_total - 1)):
                                        items = stack2_items
                                    elif (not items) and stacked_items and (not expected_total or len(stacked_items) >= max(1, expected_total - 1)):
                                        items = stacked_items
