def _render_template_builder(settings: Dict[str, Any]) -> None:
    """Render the supplier template builder inside the Admin Template Management page."""
    try:
        import template_builder_standalone as _standalone_template_builder
    except Exception as e:
        st.error(f"Template Builder failed to load: {e}")
        return

    _standalone_template_builder.main(configure_page=False)


def _render_template_table(table: str, title: str) -> None:
    st.subheader(title)
    rows = _db_fetchall(f"SELECT * FROM {table} ORDER BY updated_at DESC")
    if not rows:
        st.info("No templates yet.")
        return

    templates = [dict(r) for r in rows]

    if pd is not None:
        df = pd.DataFrame(templates)
        name_col = "supplier_name" if table == "supplier_templates" else "customer_name"
        cols = ["display_id", "template_id", name_col, "parser_type", "requires_cloud", "created_at", "updated_at"]
        for c in cols:
            if c not in df.columns:
                df[c] = ""
        st.dataframe(df[cols], width='stretch', hide_index=True)
    else:
        for t in templates:
            st.write(t)

    st.markdown("#### View / Edit template")
    name_col = "supplier_name" if table == "supplier_templates" else "customer_name"
    options = []
    label_to_tid = {}
    for t in templates:
        disp = (t.get("display_id") or "").strip() or (t.get("template_id") or "")
        nm = (t.get(name_col) or "").strip()
        label = f"{disp}  {nm}".strip(" ")
        options.append(label)
        label_to_tid[label] = t.get("template_id")

    sel = st.selectbox("Select template", options=options, key=f"sel_{table}")
    tid = label_to_tid.get(sel)
    tpl = _db_get_template(table, tid) if tid else None
    if not tpl:
        st.warning("Template not found.")
        return

    try:
        kws = json.loads(tpl.get("match_keywords_json") or "[]")
        if not isinstance(kws, list):
            kws = []
    except Exception:
        kws = []
    try:
        cfg = json.loads(tpl.get("config_json") or "{}")
        if not isinstance(cfg, dict):
            cfg = {}
        if isinstance(cfg.get("header_aliases"), dict):
            cfg["header_aliases"] = _normalise_template_alias_config(cfg.get("header_aliases"), _template_default_header_aliases())
        if isinstance(cfg.get("line_aliases"), dict):
            cfg["line_aliases"] = _normalise_template_alias_config(cfg.get("line_aliases"), _template_default_line_aliases())
    except Exception:
        cfg = {}

    with st.form(f"form_edit_{table}_{tpl.get('template_id')}"):
        c1, c2 = st.columns(2)
        display_id = c1.text_input("Display ID", value=tpl.get("display_id") or "")
        parser_type = c2.text_input("Parser type", value=tpl.get("parser_type") or "GENERIC")

        if table == "supplier_templates":
            n1, n2 = st.columns(2)
            supplier_name = n1.text_input("Supplier name", value=tpl.get("supplier_name") or "")
            vat_number = n2.text_input("VAT number (optional)", value=tpl.get("vat_number") or "")
            awrs_number = st.text_input("AWRS number (optional)", value=tpl.get("awrs_number") or "")
            party_value = supplier_name
        else:
            customer_name = st.text_input("Customer name", value=tpl.get("customer_name") or "")
            party_value = customer_name
            vat_number = ""
            awrs_number = ""

        requires_cloud = st.checkbox("Requires Cloud AI", value=bool(int(tpl.get("requires_cloud") or 0)))
        keywords_text = st.text_area("Match keywords (one per line)", value="\n".join([str(k) for k in kws if str(k).strip()]), height=140)
        header_aliases_cfg = _normalise_template_alias_config(cfg.get("header_aliases"), _template_default_header_aliases())
        line_aliases_cfg = _normalise_template_alias_config(cfg.get("line_aliases"), _template_default_line_aliases())
        map_tab, json_tab = st.tabs(["Mapping", "Advanced JSON"])
        with map_tab:
            header_aliases_mapped = _render_template_alias_mapping_editor(
                label="Header field mapping",
                alias_cfg=header_aliases_cfg,
                defaults=_template_default_header_aliases(),
                key=f"edit_header_alias_grid_{table}_{tpl.get('template_id')}",
                height=260,
            )
            line_aliases_mapped = _render_template_alias_mapping_editor(
                label="Line column mapping",
                alias_cfg=line_aliases_cfg,
                defaults=_template_default_line_aliases(),
                key=f"edit_line_alias_grid_{table}_{tpl.get('template_id')}",
                height=310,
            )
        with json_tab:
            header_aliases_text = st.text_area(
                "Header aliases JSON",
                value=json.dumps(header_aliases_mapped, indent=2),
                height=180,
                help="Map supplier-specific header labels to DocMate header fields.",
            )
            line_aliases_text = st.text_area(
                "Line aliases JSON",
                value=json.dumps(line_aliases_mapped, indent=2),
                height=180,
                help="Map supplier-specific line headings/keys to DocMate item fields.",
            )
        config_text = st.text_area("Config JSON (advanced)", value=json.dumps(cfg, indent=2), height=160)
        save = st.form_submit_button("Save changes")

    if save:
        display_id_clean = (display_id or "").strip()
        if not display_id_clean:
            st.error("Display ID cannot be blank.")
        else:
            try:
                cfg2 = json.loads(config_text or "{}")
                if not isinstance(cfg2, dict):
                    raise ValueError("Config must be a JSON object")
            except Exception as e:
                st.error(f"Invalid Config JSON: {e}")
                cfg2 = None
            if cfg2 is not None:
                try:
                    header_aliases_json = json.loads(header_aliases_text or "{}")
                    if isinstance(header_aliases_json, dict):
                        cfg2["header_aliases"] = _normalise_template_alias_config(header_aliases_json, _template_default_header_aliases())
                    else:
                        cfg2["header_aliases"] = header_aliases_mapped
                except Exception as e:
                    st.error(f"Invalid header aliases JSON: {e}")
                    cfg2 = None
            if cfg2 is not None:
                try:
                    line_aliases_json = json.loads(line_aliases_text or "{}")
                    if isinstance(line_aliases_json, dict):
                        cfg2["line_aliases"] = _normalise_template_alias_config(line_aliases_json, _template_default_line_aliases())
                    else:
                        cfg2["line_aliases"] = line_aliases_mapped
                except Exception as e:
                    st.error(f"Invalid line aliases JSON: {e}")
                    cfg2 = None

            if cfg2 is not None:
                kw_list = [k.strip() for k in (keywords_text or "").splitlines() if k.strip()]
                try:
                    if table == "supplier_templates":
                        _db_upsert_supplier_template(
                            {
                                "template_id": tpl.get("template_id"),
                                "display_id": display_id_clean,
                                "supplier_name": party_value,
                                "vat_number": vat_number,
                                "awrs_number": awrs_number,
                                "parser_type": parser_type,
                                "requires_cloud": 1 if requires_cloud else 0,
                                "match_keywords": kw_list,
                                "config": cfg2,
                                "created_at": tpl.get("created_at") or _uk_now_iso(),
                            }
                        )
                    else:
                        _db_upsert_customer_template(
                            {
                                "template_id": tpl.get("template_id"),
                                "display_id": display_id_clean,
                                "customer_name": party_value,
                                "parser_type": parser_type,
                                "requires_cloud": 1 if requires_cloud else 0,
                                "match_keywords": kw_list,
                                "config": cfg2,
                                "created_at": tpl.get("created_at") or _uk_now_iso(),
                            }
                        )
                    st.success("Template saved")
                    _log_event(f"Admin updated template {display_id_clean} in {table}")
                    st.rerun()
                except Exception as e:
                    st.error(str(e))

    st.markdown("#### Delete template")
    del_ident = st.text_input("Template ID or Display ID", value=tpl.get("display_id") or tpl.get("template_id") or "", key=f"del_{table}_ident")
    confirm = st.checkbox("I understand this cannot be undone", key=f"conf_{table}")
    if st.button("Delete", disabled=(not del_ident or not confirm), key=f"btn_del_{table}"):
        n = _db_delete_template(table, del_ident.strip())
        if n <= 0:
            st.error("Nothing deleted  please check the ID.")
        else:
            st.success("Template deleted")
            _log_event(f"Admin deleted template {del_ident.strip()} from {table}")
            st.rerun()




def _render_customer_profiles(settings: Dict[str, Any]) -> None:
    st.title("Customer Profiles")
    st.caption(
        "Map CMS Customer ID  SPOS Customer ID and maintain customer profile metadata for DocMate deployments. "
        "This mapping drives Dashboard customer selection and downstream VBR EPOS / Cloud Reporting exports."
    )

    conn = _get_db()

    # Load current profiles
    try:
        df = pd.read_sql_query(
            """
            SELECT
                rowid AS rowid,
                COALESCE(cms_customer_id,'') AS cms_customer_id,
                COALESCE(mobile_cms_id,'') AS mobile_cms_id,
                COALESCE(store_id,'') AS store_id,
                COALESCE(spos_customer_id,'') AS spos_customer_id,
                COALESCE(company_name,'') AS company_name,
                COALESCE(trading_name,'') AS trading_name,
                COALESCE(contact_name,'') AS contact_name,
                COALESCE(contact_email,'') AS contact_email,
                COALESCE(contact_phone,'') AS contact_phone,
                COALESCE(address_line1,'') AS address_line1,
                COALESCE(address_line2,'') AS address_line2,
                COALESCE(city,'') AS city,
                COALESCE(postcode,'') AS postcode,
                COALESCE(country,'') AS country,
                COALESCE(license_start_date,'') AS license_start_date,
                COALESCE(license_end_date,'') AS license_end_date,
                COALESCE(notes,'') AS notes
            FROM customer_profiles
            ORDER BY cms_customer_id
            """,
            conn,
        )
    except Exception as e:
        st.error(f"Failed to load customer profiles: {e}")
        df = pd.DataFrame(
            columns=[
                "rowid",
                "cms_customer_id",
                "mobile_cms_id",
                "store_id",
                "spos_customer_id",
                "company_name",
                "trading_name",
                "contact_name",
                "contact_email",
                "contact_phone",
                "address_line1",
                "address_line2",
                "city",
                "postcode",
                "country",
                "license_start_date",
                "license_end_date",
                "notes",
            ]
        )

    st.subheader("Existing customer profiles")
    st.dataframe(df, width="stretch", hide_index=True)

    st.divider()

    # Edit selector
    st.subheader("Edit customer profile")
    edit_options = ["(New profile)"] + sorted(
        [x for x in df["cms_customer_id"].tolist() if str(x).strip()]
    )
    selected = st.selectbox(
        "Select CMS Customer ID to edit", options=edit_options, index=0, width="stretch"
    )

    current: Dict[str, Any] = {}
    if selected != "(New profile)":
        try:
            row = conn.execute(
                "SELECT * FROM customer_profiles WHERE UPPER(TRIM(cms_customer_id))=?",
                (str(selected).strip().upper(),),
            ).fetchone()
            current = dict(row) if row else {}
        except Exception:
            current = {}

    st.subheader("Add / update customer profile")

    def _v(k: str, default: str = "") -> str:
        v = current.get(k, default)
        return "" if v is None else str(v)

    with st.form("customer_profile_form", clear_on_submit=False):
        col_a, col_b, col_c = st.columns(3)
        with col_a:
            cms_id = st.text_input(
                "CMS Customer ID", value=_v("cms_customer_id"), placeholder="e.g., C02013"
            )
        with col_b:
            spos_id = st.text_input(
                "SPOS Customer ID", value=_v("spos_customer_id"), placeholder="e.g., S1529"
            )
        with col_c:
            mobile_cms_id = st.text_input(
                "Mobile CMS ID", value=_v("mobile_cms_id"), placeholder="e.g., MC02013"
            )
            store_id = st.text_input(
                "Store ID", value=_v("store_id"), placeholder="e.g., 1"
            )

        col1, col2 = st.columns(2)
        with col1:
            company_name = st.text_input(
                "Company name", value=_v("company_name"), placeholder="Legal entity name"
            )
            trading_name = st.text_input(
                "Trading name",
                value=_v("trading_name"),
                placeholder="Store / brand trading name",
            )
            contact_name = st.text_input("Contact name", value=_v("contact_name"))
            contact_email = st.text_input("Contact email", value=_v("contact_email"))
            contact_phone = st.text_input("Contact phone", value=_v("contact_phone"))
        with col2:
            address_line1 = st.text_input("Address line 1", value=_v("address_line1"))
            address_line2 = st.text_input("Address line 2", value=_v("address_line2"))
            city = st.text_input("Town/City", value=_v("city"))
            postcode = st.text_input("Postcode", value=_v("postcode"))
            country = st.text_input("Country", value=_v("country", "United Kingdom"))
            license_start_date = st.text_input(
                "Licence Start Date",
                value=_v("license_start_date"),
                placeholder="YYYY-MM-DD (e.g., 2026-02-01)",
            )
            license_end_date = st.text_input(
                "Licence End Date",
                value=_v("license_end_date"),
                placeholder="YYYY-MM-DD (e.g., 2026-12-31)",
            )

        notes = st.text_area("Notes", value=_v("notes"), height=90)

        submitted = st.form_submit_button("Save profile", width="stretch")

        if submitted:
            cms_id_clean = (cms_id or "").strip().upper()
            spos_id_clean = (spos_id or "").strip()

            if not cms_id_clean or not spos_id_clean:
                st.error("Please enter both CMS Customer ID and SPOS Customer ID.")
                return

            try:
                customer_name_val = (trading_name or company_name or contact_name or "").strip()
                vat_registration_no_val = ""
                contact_no_val = (contact_phone or "").strip()
                email_address_val = (contact_email or "").strip()
                address_parts = [
                    (address_line1 or "").strip(),
                    (address_line2 or "").strip(),
                    (city or "").strip(),
                    (postcode or "").strip(),
                    (country or "").strip(),
                ]
                address_val = ", ".join([p for p in address_parts if p])
                now_uk = _uk_now_iso()

                exists = conn.execute(
                    "SELECT 1 FROM customer_profiles WHERE UPPER(TRIM(cms_customer_id))=?",
                    (cms_id_clean,),
                ).fetchone()

                if exists:
                    conn.execute(
                        """
                        UPDATE customer_profiles
                        SET
                            mobile_cms_id=?,
                            store_id=?,
                            customer_name=?,
                            spos_customer_id=?,
                            company_name=?,
                            trading_name=?,
                            vat_registration_no=?,
                            contact_no=?,
                            email_address=?,
                            contact_name=?,
                            contact_email=?,
                            contact_phone=?,
                            address_line1=?,
                            address_line2=?,
                            city=?,
                            postcode=?,
                            country=?,
                            address=?,
                            license_start_date=?,
                            license_end_date=?,
                            notes=?,
                            updated_at=?
                        WHERE UPPER(TRIM(cms_customer_id))=?
                        """,
                        (
                            (mobile_cms_id or "").strip().upper(),
                            (store_id or "").strip(),
                            customer_name_val,
                            spos_id_clean,
                            (company_name or "").strip(),
                            (trading_name or "").strip(),
                            vat_registration_no_val,
                            contact_no_val,
                            email_address_val,
                            (contact_name or "").strip(),
                            (contact_email or "").strip(),
                            (contact_phone or "").strip(),
                            (address_line1 or "").strip(),
                            (address_line2 or "").strip(),
                            (city or "").strip(),
                            (postcode or "").strip(),
                            (country or "").strip(),
                            address_val,
                            (license_start_date or "").strip(),
                            (license_end_date or "").strip(),
                            (notes or "").strip(),
                            now_uk,
                            cms_id_clean,
                        ),
                    )
                else:
                    conn.execute(
                        """
                        INSERT INTO customer_profiles (
                            cms_customer_id, mobile_cms_id, store_id, customer_name, spos_customer_id,
                            company_name, trading_name, vat_registration_no, contact_no, email_address,
                            contact_name, contact_email, contact_phone,
                            address_line1, address_line2, city, postcode, country,
                            license_start_date, license_end_date,
                            address, notes, created_at, updated_at
                        )
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            cms_id_clean,
                            (mobile_cms_id or "").strip().upper(),
                            (store_id or "").strip(),
                            customer_name_val,
                            spos_id_clean,
                            (company_name or "").strip(),
                            (trading_name or "").strip(),
                            vat_registration_no_val,
                            contact_no_val,
                            email_address_val,
                            (contact_name or "").strip(),
                            (contact_email or "").strip(),
                            (contact_phone or "").strip(),
                            (address_line1 or "").strip(),
                            (address_line2 or "").strip(),
                            (city or "").strip(),
                            (postcode or "").strip(),
                            (country or "").strip(),
                            (license_start_date or "").strip(),
                            (license_end_date or "").strip(),
                            address_val,
                            (notes or "").strip(),
                            now_uk,
                            now_uk,
                        ),
                    )

                conn.commit()
                ok_exp, exp_msg = _export_customer_profiles_csv(conn)
                if not ok_exp:
                    st.warning(f"Profile saved, but CSV export failed: {exp_msg}")
                # Optional: push to EposV3 SQL Server (customer_db_cred.yaml)
                try:
                    sqlserver_mod = _sqlserver_local or _sqlserver
                    if sqlserver_mod is not None and hasattr(sqlserver_mod, "insert_customer_profile_sqlserver"):
                        profile_row = {
                            "cms_customer_id": cms_id_clean,
                            "mobile_cms_id": (mobile_cms_id or "").strip().upper(),
                            "store_id": (store_id or "").strip(),
                            "customer_name": customer_name_val,
                            "spos_customer_id": spos_id_clean,
                            "trading_name": (trading_name or "").strip(),
                            "company_name": (company_name or "").strip(),
                            "vat_registration_no": vat_registration_no_val,
                            "contact_no": contact_no_val,
                            "email_address": email_address_val,
                            "contact_name": (contact_name or "").strip(),
                            "contact_email": (contact_email or "").strip(),
                            "contact_phone": (contact_phone or "").strip(),
                            "address_line1": (address_line1 or "").strip(),
                            "address_line2": (address_line2 or "").strip(),
                            "city": (city or "").strip(),
                            "postcode": (postcode or "").strip(),
                            "country": (country or "").strip(),
                            "address": address_val,
                            "license_start_date": (license_start_date or "").strip(),
                            "license_end_date": (license_end_date or "").strip(),
                            "notes": (notes or "").strip(),
                            "created_at": now_uk,
                            "updated_at": now_uk,
                        }
                        ok_sql, msg_sql = sqlserver_mod.insert_customer_profile_sqlserver(
                            profile_row
                        )
                        if not ok_sql:
                            st.warning(f"Profile saved locally, but SQL Server sync failed: {msg_sql}")
                except Exception as e:
                    st.warning(f"Profile saved locally, but SQL Server sync failed: {e}")
                st.success(f"Saved customer profile: {cms_id_clean}  {spos_id_clean}")
                st.rerun()

            except Exception as e:
                st.error(f"Failed to save customer profile: {e}")

    st.info(
        "Tip: This mapping is used in Dashboard for Customer (CMSID  SPOS). "
        "Keep it accurate for VBR EPOS and Cloud Reporting exports."
    )



def _smart_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, default=str)


def _smart_doctr_text(res: Dict[str, Any]) -> Tuple[str, List[Dict[str, Any]]]:
    lines = list((res or {}).get("ocr_lines_snapshot") or [])
    if not lines:
        cache_key = str((res or {}).get("ocr_cache_key") or "").strip()
        if cache_key:
            lines = list(_OCR_LINES_CACHE.get(cache_key) or [])
    lines = _normalize_purchase_table_ocr_lines(lines)
    return _text_from_ocr_lines(lines).strip(), lines


def _smart_run_fresh_doctr(res: Dict[str, Any], settings: Dict[str, Any]) -> Tuple[str, List[Dict[str, Any]]]:
    file_bytes = bytes((res or {}).get("file_bytes") or b"")
    mime = str((res or {}).get("mime") or "application/pdf")
    if not file_bytes:
        raise ValueError("The original invoice bytes are not available.")
    cfg = OcrConfig(
        engine="doctr",
        tesseract_cmd=str((settings or {}).get("tesseract_cmd") or ""),
        dpi=max(250, int((settings or {}).get("ocr_dpi", 250) or 250)),
        max_pages=max(1, int((settings or {}).get("ocr_max_pages", 10) or 10)),
        force_pdf=(mime == "application/pdf"),
        auto_install=False,
    )
    cfg.doctr_upscale = float((settings or {}).get("doctr_upscale", 1.0) or 1.0)
    cfg.doctr_strong_photo = bool((settings or {}).get("doctr_strong_photo", False))
    cache_key = _cache_key_for_ocr(
        file_bytes, mime=mime, engine="doctr", dpi=cfg.dpi,
        max_pages=cfg.max_pages, force_pdf=cfg.force_pdf,
        extra="smart_template_studio_v4_page_dimension_normalization",
    )
    text = ocr_text_cached(cache_key, mime, dataclasses.asdict(cfg), file_bytes)
    lines = _normalize_purchase_table_ocr_lines(list(_OCR_LINES_CACHE.get(cache_key) or []))
    tokens = _normalize_purchase_table_ocr_lines(list(_OCR_TOKEN_LINES_CACHE.get(cache_key) or []))
    if not lines:
        raise RuntimeError("DocTR returned text but no coordinate boxes; the example cannot be spatially trained.")
    res["ocr_cache_key"] = cache_key
    res["ocr_lines_snapshot"] = copy.deepcopy(lines)
    res["ocr_token_lines_snapshot"] = copy.deepcopy(tokens)
    res["confidence_raw_text"] = str(text or "")
    return _text_from_ocr_lines(lines).strip() or str(text or "").strip(), lines


def _smart_text_has_value(text: str, value: Any) -> bool:
    raw = _collapse_spaces(str(value or "")).strip()
    if not raw:
        return False
    text_norm = re.sub(r"[^A-Z0-9]", "", str(text or "").upper())
    value_norm = re.sub(r"[^A-Z0-9]", "", raw.upper())
    if len(value_norm) >= 3 and value_norm in text_norm:
        return True
    amount = _safe_float(value)
    if abs(amount) > 0.0001:
        variants = {
            f"{amount:.2f}",
            f"{amount:,.2f}",
            f"{amount:.4f}".rstrip("0").rstrip("."),
        }
        compact_text = re.sub(r"\s+", "", str(text or ""))
        return any(v in compact_text for v in variants)
    return False


def _smart_compare_teacher_to_doctr(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    doctr_text: str,
    local_header: Optional[Dict[str, Any]] = None,
    local_items: Optional[List[Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    header_fields = [
        "supplierName", "customerName", "invoiceNumber", "invoiceDate",
        "currency", "totalNet", "totalVat", "totalGross",
    ]
    header_targets = [(field, header.get(field)) for field in header_fields if header.get(field) not in (None, "")]
    header_hits = sum(1 for _field, value in header_targets if _smart_text_has_value(doctr_text, value))
    header_score = round(100.0 * header_hits / max(1, len(header_targets)), 1)

    teacher_items = _template_training_items(items or [])
    matched_lines = 0
    for item in teacher_items:
        desc_words = [
            word for word in re.findall(r"[A-Z0-9]{3,}", str(item.get("description") or "").upper())[:6]
        ]
        desc_hit = bool(desc_words and sum(1 for word in desc_words if word in doctr_text.upper()) >= min(2, len(desc_words)))
        amount_hit = _smart_text_has_value(doctr_text, item.get("lineNet"))
        code = str(item.get("code") or "").strip()
        code_hit = not code or _smart_text_has_value(doctr_text, code)
        if desc_hit and amount_hit and code_hit:
            matched_lines += 1
    line_score = round(100.0 * matched_lines / max(1, len(teacher_items)), 1) if teacher_items else 0.0

    comparison_items = local_items or []
    comparison_header = local_header or header
    diff = _template_agent_reconciliation_diff(comparison_header, comparison_items, doctr_text) if comparison_items else 999999.0
    return {
        "header_score": header_score,
        "header_hits": header_hits,
        "header_targets": len(header_targets),
        "line_score": line_score,
        "line_hits": matched_lines,
        "line_targets": len(teacher_items),
        "reconciliation_diff": round(float(diff), 2) if diff < 999999 else diff,
    }


def _smart_structured_accuracy(
    teacher_header: Dict[str, Any],
    teacher_items: List[Dict[str, Any]],
    candidate_header: Dict[str, Any],
    candidate_items: List[Dict[str, Any]],
    doctr_text: str = "",
) -> Dict[str, Any]:
    fields = ("supplierName", "customerName", "invoiceNumber", "invoiceDate", "currency", "totalNet", "totalVat", "totalGross")
    targets = [(field, teacher_header.get(field)) for field in fields if teacher_header.get(field) not in (None, "")]
    hits = 0
    for field, expected in targets:
        actual = candidate_header.get(field)
        if field in ("totalNet", "totalVat", "totalGross"):
            matched = abs(_safe_float(expected) - _safe_float(actual)) <= 0.02
        else:
            left = re.sub(r"[^A-Z0-9]", "", str(expected or "").upper())
            right = re.sub(r"[^A-Z0-9]", "", str(actual or "").upper())
            matched = bool(left and right and (left == right or left in right or right in left))
        hits += int(matched)
    teacher_rows = _template_training_items(teacher_items or [])
    candidate_rows = _template_training_items(candidate_items or [])
    row_hits = 0
    used: set[int] = set()
    for expected in teacher_rows:
        best_idx = None
        best_score = 0
        expected_words = set(re.findall(r"[A-Z0-9]{3,}", str(expected.get("description") or "").upper()))
        for idx, actual in enumerate(candidate_rows):
            if idx in used:
                continue
            actual_words = set(re.findall(r"[A-Z0-9]{3,}", str(actual.get("description") or "").upper()))
            desc_score = len(expected_words & actual_words) / max(1, len(expected_words))
            amount_ok = abs(_safe_float(expected.get("lineNet")) - _safe_float(actual.get("lineNet"))) <= 0.02
            code_expected = re.sub(r"\W", "", str(expected.get("code") or "").upper())
            code_actual = re.sub(r"\W", "", str(actual.get("code") or "").upper())
            code_ok = not code_expected or code_expected == code_actual
            score = desc_score + (1.0 if amount_ok else 0.0) + (0.5 if code_ok else 0.0)
            if score > best_score:
                best_score, best_idx = score, idx
        if best_idx is not None and best_score >= 1.5:
            used.add(best_idx)
            row_hits += 1
    diff = _template_agent_reconciliation_diff(candidate_header, candidate_rows, doctr_text) if candidate_rows else 999999.0
    return {
        "header_score": round(100.0 * hits / max(1, len(targets)), 1),
        "line_score": round(100.0 * row_hits / max(1, len(teacher_rows)), 1) if teacher_rows else 0.0,
        "matched_rows": row_hits,
        "teacher_rows": len(teacher_rows),
        "candidate_rows": len(candidate_rows),
        "reconciliation_diff": round(float(diff), 2) if diff < 999999 else diff,
    }


def _smart_median(values: List[float], default: float = 0.0) -> float:
    vals = sorted(float(value) for value in values if value is not None)
    if not vals:
        return default
    middle = len(vals) // 2
    return vals[middle] if len(vals) % 2 else (vals[middle - 1] + vals[middle]) / 2.0


def _smart_bbox(line: Dict[str, Any]) -> Optional[Tuple[float, float, float, float]]:
    bbox = (line or {}).get("bbox")
    try:
        if isinstance(bbox, dict):
            return (
                float(bbox.get("left") or 0), float(bbox.get("top") or 0),
                float(bbox.get("right") or 0), float(bbox.get("bottom") or 0),
            )
        if isinstance(bbox, (list, tuple)) and len(bbox) >= 4:
            return tuple(float(value) for value in bbox[:4])
    except Exception:
        return None
    return None


def _smart_normalized_tokens(tokens: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    page_limits: Dict[int, Tuple[float, float]] = {}
    for token in tokens or []:
        box = _smart_bbox(token)
        if not box:
            continue
        page = int((token or {}).get("page") or 1)
        old_x, old_y = page_limits.get(page, (1.0, 1.0))
        declared_x = _safe_float((token or {}).get("page_width"), default=0.0)
        declared_y = _safe_float((token or {}).get("page_height"), default=0.0)
        page_limits[page] = (
            max(old_x, declared_x, box[2]),
            max(old_y, declared_y, box[3]),
        )
    out: List[Dict[str, Any]] = []
    for token in tokens or []:
        box = _smart_bbox(token)
        if not box or not str((token or {}).get("text") or "").strip():
            continue
        page = int((token or {}).get("page") or 1)
        max_x, max_y = page_limits.get(page, (1.0, 1.0))
        out.append({
            "text": str(token.get("text") or "").strip(),
            "page": page,
            "x0": box[0] / max_x, "y0": box[1] / max_y,
            "x1": box[2] / max_x, "y1": box[3] / max_y,
        })
    return sorted(out, key=lambda token: (token["page"], token["y0"], token["x0"]))


def _smart_value_tokens(value: Any) -> List[str]:
    raw = str(value or "").upper()
    words = re.findall(r"[A-Z0-9]+", raw)
    is_plain_number = isinstance(value, (int, float)) or bool(
        re.fullmatch(r"\s*[-+]?(?:[£€$]\s*)?\d[\d\s,]*(?:\.\d+)?\s*", str(value or ""))
    )
    amount = _safe_float(value) if is_plain_number else 0.0
    if is_plain_number and abs(amount) > 0.0001:
        words.extend(re.findall(r"\d+", f"{amount:.2f}"))
    return [word for word in words if word]


def _smart_date_iso(value: Any) -> str:
    raw = _collapse_spaces(str(value or "").replace(",", " ").replace(".", " ")).strip()
    normalised = _normalise_invoice_date_str(raw)
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", str(normalised or "")):
        return str(normalised)
    cleaned = re.sub(r"\s+", " ", raw)
    for pattern in (
        "%b %d %Y", "%B %d %Y", "%d %b %Y", "%d %B %Y",
        "%Y %m %d", "%d %m %Y", "%m %d %Y",
    ):
        try:
            return datetime.strptime(cleaned, pattern).strftime("%Y-%m-%d")
        except Exception:
            continue
    # Extract a date substring from text such as "Issue Date Dec 19 2025".
    month_match = re.search(
        r"\b(Jan(?:uary)?|Feb(?:ruary)?|Mar(?:ch)?|Apr(?:il)?|May|Jun(?:e)?|"
        r"Jul(?:y)?|Aug(?:ust)?|Sep(?:tember)?|Oct(?:ober)?|Nov(?:ember)?|"
        r"Dec(?:ember)?)\s+(\d{1,2})\s+(\d{4})\b",
        cleaned,
        flags=re.I,
    )
    if month_match:
        for pattern in ("%b %d %Y", "%B %d %Y"):
            try:
                return datetime.strptime(" ".join(month_match.groups()), pattern).strftime("%Y-%m-%d")
            except Exception:
                continue
    return ""


def _smart_find_value_box(
    tokens: List[Dict[str, Any]],
    value: Any,
    *,
    y_hint: Optional[float] = None,
    prefer_last: bool = False,
) -> Optional[Dict[str, Any]]:
    targets = _smart_value_tokens(value)
    if not targets:
        return None
    raw_value = str(value or "").strip()
    expected_date = _smart_date_iso(raw_value)
    if expected_date and re.search(r"\d", raw_value) and (
        re.search(r"\d{4}[-/]\d{1,2}[-/]\d{1,2}", raw_value)
        or re.search(r"\d{1,2}[-/]\d{1,2}[-/]\d{2,4}", raw_value)
    ):
        date_candidates: List[List[Dict[str, Any]]] = []
        for start in range(len(tokens)):
            page = tokens[start]["page"]
            for size in range(1, min(8, len(tokens) - start + 1)):
                window = tokens[start:start + size]
                if any(token["page"] != page for token in window):
                    break
                y_centers = [(token["y0"] + token["y1"]) / 2 for token in window]
                if max(y_centers) - min(y_centers) > 0.025:
                    continue
                candidate_text = " ".join(token["text"] for token in window)
                if _smart_date_iso(candidate_text) == expected_date:
                    date_candidates.append(window)
        if date_candidates:
            window = min(date_candidates, key=len)
            return {
                "page": int(window[0]["page"]),
                "x0": min(token["x0"] for token in window),
                "y0": min(token["y0"] for token in window),
                "x1": max(token["x1"] for token in window),
                "y1": max(token["y1"] for token in window),
                "match_score": 1.0,
                "ocr_text": " ".join(token["text"] for token in window),
            }
        return None
    currency = raw_value.upper()
    if currency in {"GBP", "EUR", "USD"}:
        currency_markers = {
            "GBP": {"GBP", "£"},
            "EUR": {"EUR", "€"},
            "USD": {"USD", "$"},
        }[currency]
        for token in tokens:
            token_text = str(token.get("text") or "").strip().upper()
            if any(marker in token_text for marker in currency_markers):
                return {
                    "page": int(token["page"]),
                    "x0": token["x0"], "y0": token["y0"],
                    "x1": token["x1"], "y1": token["y1"],
                    "match_score": 1.0,
                    "ocr_text": token["text"],
                }
        return None
    is_plain_number = isinstance(value, (int, float)) or bool(
        re.fullmatch(r"\s*[-+]?(?:[£€$]\s*)?\d[\d\s,]*(?:\.\d+)?\s*", str(value or ""))
    )
    if is_plain_number:
        expected = _safe_float(value)
        numeric_matches: List[Tuple[float, Dict[str, Any]]] = []
        for token in tokens:
            spans = _template_agent_number_spans(token.get("text") or "")
            if not spans or not any(abs(_safe_float(span.get("value")) - expected) <= 0.015 for span in spans):
                continue
            center_y = (token["y0"] + token["y1"]) / 2
            distance = abs(center_y - y_hint) if y_hint is not None else 0.0
            rank = 1.0 - min(0.9, distance * 10.0)
            if prefer_last:
                rank += center_y * 0.02
            numeric_matches.append((rank, token))
        if numeric_matches:
            _rank, token = max(numeric_matches, key=lambda pair: pair[0])
            return {
                "page": int(token["page"]),
                "x0": token["x0"], "y0": token["y0"],
                "x1": token["x1"], "y1": token["y1"],
                "match_score": 1.0,
                "ocr_text": token["text"],
            }
        # Numeric teacher values must never fall through to fuzzy word
        # matching (e.g. 2.16 matching "16.5mg" in a description).
        return None
    best: Optional[Tuple[float, List[Dict[str, Any]]]] = None
    for start in range(len(tokens)):
        page = tokens[start]["page"]
        for size in range(1, min(21, len(tokens) - start + 1)):
            window = tokens[start:start + size]
            if any(token["page"] != page for token in window):
                break
            y_centers = [(token["y0"] + token["y1"]) / 2 for token in window]
            if max(y_centers) - min(y_centers) > 0.025:
                continue
            found = re.findall(r"[A-Z0-9]+", " ".join(token["text"] for token in window).upper())
            if not found:
                continue
            overlap = sum(1 for target in targets if target in found or any(target in word or word in target for word in found))
            score = overlap / max(1, len(targets))
            y_distance = abs(_smart_median(y_centers) - y_hint) if y_hint is not None else 0.0
            rank = score - min(0.5, y_distance * 8.0)
            if prefer_last:
                rank += _smart_median(y_centers) * 0.02
            if rank >= 0.55 and (
                best is None
                or rank > best[0]
                or (rank == best[0] and len(window) < len(best[1]))
            ):
                best = (rank, window)
    if not best:
        return None
    window = best[1]
    return {
        "page": int(window[0]["page"]),
        "x0": min(token["x0"] for token in window),
        "y0": min(token["y0"] for token in window),
        "x1": max(token["x1"] for token in window),
        "y1": max(token["y1"] for token in window),
        "match_score": round(min(1.0, best[0]), 3),
        "ocr_text": " ".join(token["text"] for token in window),
    }


def _smart_align_example(
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    raw_tokens: List[Dict[str, Any]],
) -> Dict[str, Any]:
    tokens = _smart_normalized_tokens(raw_tokens)
    ocr_rows: List[List[Dict[str, Any]]] = []
    for token in tokens:
        center_y = (token["y0"] + token["y1"]) / 2
        row = next(
            (
                candidate for candidate in ocr_rows
                if candidate
                and candidate[0]["page"] == token["page"]
                and abs(
                    center_y
                    - _smart_median([(item["y0"] + item["y1"]) / 2 for item in candidate])
                ) <= 0.008
            ),
            None,
        )
        if row is None:
            row = []
            ocr_rows.append(row)
        row.append(token)
    for row in ocr_rows:
        row.sort(key=lambda token: token["x0"])
    header_boxes: Dict[str, Any] = {}
    for field in (
        "supplierName", "customerName", "invoiceNumber", "invoiceDate",
        "currency", "totalNet", "totalVat", "totalGross",
    ):
        if (header or {}).get(field) not in (None, ""):
            box = _smart_find_value_box(
                tokens,
                header.get(field),
                prefer_last=field in ("totalNet", "totalVat", "totalGross"),
            )
            if box:
                header_boxes[field] = box
    row_profiles: List[Dict[str, Any]] = []
    fields = ("code", "description", "qty", "unitPrice", "lineNet", "vatRate", "vatAmount", "lineGross")
    used_ocr_rows: set[int] = set()
    for row_index, item in enumerate(_template_training_items(items or []), start=1):
        cells: Dict[str, Any] = {}
        expected_code = re.sub(r"[^A-Z0-9]", "", str(item.get("code") or "").upper())
        expected_words = set(
            word for word in re.findall(r"[A-Z0-9]{3,}", str(item.get("description") or "").upper())
            if word not in {"THE", "AND", "WITH"}
        )
        best_row_idx: Optional[int] = None
        best_row_score = 0.0
        for candidate_idx, candidate_tokens in enumerate(ocr_rows):
            if candidate_idx in used_ocr_rows:
                continue
            candidate_text = " ".join(token["text"] for token in candidate_tokens)
            candidate_compact = re.sub(r"[^A-Z0-9]", "", candidate_text.upper())
            candidate_words = set(re.findall(r"[A-Z0-9]{3,}", candidate_text.upper()))
            desc_coverage = len(expected_words & candidate_words) / max(1, len(expected_words))
            code_match = bool(expected_code and expected_code in candidate_compact)
            amount_match = any(
                abs(_safe_float(span.get("value")) - _safe_float(item.get("lineNet"))) <= 0.015
                for span in _template_agent_number_spans(candidate_text)
            ) if _safe_float(item.get("lineNet")) != 0 else False
            score = desc_coverage * 3.0 + (3.0 if code_match else 0.0) + (0.5 if amount_match else 0.0)
            if score > best_row_score:
                best_row_score = score
                best_row_idx = candidate_idx
        minimum_row_score = 3.0 if expected_code else 1.8
        if best_row_idx is None or best_row_score < minimum_row_score:
            continue
        used_ocr_rows.add(best_row_idx)
        selected_tokens = ocr_rows[best_row_idx]
        anchor = None
        for anchor_field in ("code", "description"):
            if item.get(anchor_field) not in (None, ""):
                anchor = _smart_find_value_box(selected_tokens, item.get(anchor_field))
                if anchor:
                    cells[anchor_field] = anchor
                    break
        y_hint = ((anchor["y0"] + anchor["y1"]) / 2) if anchor else None
        for field in fields:
            if field in cells:
                continue
            value = item.get(field)
            if value not in (None, "") and not (field != "qty" and _safe_float(value) == 0 and field not in ("code", "description")):
                field_tokens = selected_tokens
                if field == "vatRate":
                    percent_tokens = [token for token in selected_tokens if "%" in str(token.get("text") or "")]
                    if percent_tokens:
                        field_tokens = percent_tokens
                elif field == "vatAmount":
                    non_percent_tokens = [token for token in selected_tokens if "%" not in str(token.get("text") or "")]
                    if non_percent_tokens:
                        field_tokens = non_percent_tokens
                box = _smart_find_value_box(field_tokens, value, y_hint=y_hint)
                if box:
                    cells[field] = box
        if cells:
            row_profiles.append({"row": row_index, "cells": cells})
    column_centers: Dict[str, List[float]] = {}
    row_y: List[float] = []
    for row in row_profiles:
        for field, box in row["cells"].items():
            column_centers.setdefault(field, []).append((box["x0"] + box["x1"]) / 2)
            if field in ("description", "code", "lineNet"):
                row_y.append((box["y0"] + box["y1"]) / 2)
    return {
        "header_boxes": header_boxes,
        "line_mappings": row_profiles,
        "columns": {
            field: {"center": round(_smart_median(values), 4), "evidence": len(values)}
            for field, values in column_centers.items()
        },
        "table_y_min": round(min(row_y), 4) if row_y else 0.0,
        "table_y_max": round(max(row_y), 4) if row_y else 0.0,
        "aligned_rows": len(row_profiles),
        "token_count": len(tokens),
    }


def _smart_apply_manual_mappings(
    alignment: Dict[str, Any],
    overrides: Dict[str, Any],
) -> Dict[str, Any]:
    out = copy.deepcopy(alignment or {})
    out.setdefault("header_boxes", {})
    out.setdefault("line_mappings", [])
    resolutions: Dict[str, Any] = {}
    line_by_row = {
        int(row.get("row") or 0): row
        for row in out.get("line_mappings") or []
    }
    for target, override in (overrides or {}).items():
        if not isinstance(override, dict):
            continue
        resolution = str(override.get("resolution") or "manual").strip().lower()
        resolutions[target] = copy.deepcopy(override)
        box = override.get("box") if isinstance(override.get("box"), dict) else None
        mapped_box = None
        if box and resolution in ("manual", "corrected"):
            mapped_box = {
                **box,
                "match_score": 1.0,
                "ocr_text": str(override.get("corrected_text") or override.get("raw_text") or ""),
                "manual": True,
                "resolution": resolution,
            }
        parts = str(target or "").split(":")
        if len(parts) == 2 and parts[0] == "header":
            field = parts[1]
            if mapped_box:
                out["header_boxes"][field] = mapped_box
            elif resolution in ("calculated", "not_printed", "ignored"):
                out["header_boxes"].pop(field, None)
        elif len(parts) == 3 and parts[0] == "line":
            try:
                row_no = int(parts[1])
            except Exception:
                continue
            field = parts[2]
            row = line_by_row.get(row_no)
            if row is None:
                row = {"row": row_no, "cells": {}}
                out["line_mappings"].append(row)
                line_by_row[row_no] = row
            row.setdefault("cells", {})
            if mapped_box:
                row["cells"][field] = mapped_box
            elif resolution in ("calculated", "not_printed", "ignored"):
                row["cells"].pop(field, None)
    column_centers: Dict[str, List[float]] = {}
    row_y: List[float] = []
    for row in out.get("line_mappings") or []:
        for field, box in (row.get("cells") or {}).items():
            if not isinstance(box, dict) or box.get("x0") is None:
                continue
            column_centers.setdefault(field, []).append(
                (_safe_float(box.get("x0")) + _safe_float(box.get("x1"))) / 2.0
            )
            if field in ("description", "code", "lineNet"):
                row_y.append((_safe_float(box.get("y0")) + _safe_float(box.get("y1"))) / 2.0)
    out["columns"] = {
        field: {"center": round(_smart_median(values), 4), "evidence": len(values)}
        for field, values in column_centers.items()
    }
    if row_y:
        out["table_y_min"] = round(min(row_y), 4)
        out["table_y_max"] = round(max(row_y), 4)
    out["manual_resolutions"] = resolutions
    return out


def _smart_candidate_config(
    supplier_name: str,
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
    doctr_lines: List[Dict[str, Any]],
    alignment: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    observed_columns = [
        field for field in (
            "code", "description", "casePack", "unitSize", "qty", "unitPrice",
            "lineNet", "vatCode", "vatRate", "vatAmount", "lineGross",
        )
        if any(isinstance(item, dict) and item.get(field) not in (None, "") for item in (items or []))
    ]
    page_count = max([int((line or {}).get("page") or 1) for line in doctr_lines] or [1])
    return {
        "version": 1,
        "status": "DRAFT",
        "supplier_name": supplier_name,
        "supplier_key": _template_supplier_key(supplier_name),
        "teacher_engine": "cloud_gemini",
        "student_engine": "local_doctr",
        "currency": str((header or {}).get("currency") or "").upper(),
        "observed_header_fields": [
            field for field, value in (header or {}).items()
            if value not in (None, "") and not str(field).startswith("_")
        ],
        "observed_line_columns": observed_columns,
        "doctr_page_count": page_count,
        "spatial_profile": alignment or {},
        "activation": {
            "minimum_examples": 3,
            "minimum_header_score": 95,
            "minimum_line_score": 95,
            "maximum_reconciliation_diff": 0.05,
            "requires_held_out_validation": True,
        },
    }


def _smart_rebuild_supplier_candidate(
    conn: sqlite3.Connection,
    supplier_key: str,
    supplier_name: str,
) -> Dict[str, Any]:
    rows = conn.execute(
        """SELECT teacher_header_json, teacher_items_json, doctr_tokens_json,
                  doctr_lines_json, manual_mappings_json
             FROM smart_training_examples
            WHERE supplier_key=? AND review_status IN ('APPROVED','VALIDATED')
            ORDER BY created_at""",
        (supplier_key,),
    ).fetchall()
    alignments: List[Dict[str, Any]] = []
    latest_header: Dict[str, Any] = {}
    latest_items: List[Dict[str, Any]] = []
    latest_lines: List[Dict[str, Any]] = []
    for row in rows:
        header = json.loads(row["teacher_header_json"] or "{}")
        items = json.loads(row["teacher_items_json"] or "[]")
        tokens = json.loads(row["doctr_tokens_json"] or "[]")
        lines = json.loads(row["doctr_lines_json"] or "[]")
        if tokens:
            alignment = _smart_align_example(header, items, tokens)
            manual_mappings = json.loads(row["manual_mappings_json"] or "{}")
            alignments.append(_smart_apply_manual_mappings(alignment, manual_mappings))
        latest_header, latest_items, latest_lines = header, items, lines
    config = _smart_candidate_config(supplier_name, latest_header, latest_items, latest_lines)
    header_fields = set(
        field for alignment in alignments
        for field in (alignment.get("header_boxes") or {}).keys()
    )
    header_regions: Dict[str, Any] = {}
    for field in header_fields:
        boxes = [
            alignment["header_boxes"][field]
            for alignment in alignments
            if field in (alignment.get("header_boxes") or {})
        ]
        header_regions[field] = {
            "page": int(round(_smart_median([box["page"] for box in boxes], 1))),
            "x0": round(_smart_median([box["x0"] for box in boxes]), 4),
            "y0": round(_smart_median([box["y0"] for box in boxes]), 4),
            "x1": round(_smart_median([box["x1"] for box in boxes]), 4),
            "y1": round(_smart_median([box["y1"] for box in boxes]), 4),
            "evidence": len(boxes),
        }
    column_fields = set(
        field for alignment in alignments
        for field in (alignment.get("columns") or {}).keys()
    )
    columns: Dict[str, Any] = {}
    for field in column_fields:
        observations = [
            alignment["columns"][field]
            for alignment in alignments
            if field in (alignment.get("columns") or {})
        ]
        columns[field] = {
            "center": round(_smart_median([obs["center"] for obs in observations]), 4),
            "examples": len(observations),
            "cell_evidence": sum(int(obs.get("evidence") or 0) for obs in observations),
        }
    y_mins = [float(a.get("table_y_min") or 0) for a in alignments if float(a.get("table_y_min") or 0) > 0]
    y_maxs = [float(a.get("table_y_max") or 0) for a in alignments if float(a.get("table_y_max") or 0) > 0]
    config["spatial_profile"] = {
        "version": 2,
        "example_count": len(alignments),
        "header_regions": header_regions,
        "columns": columns,
        "table_y_min": round(_smart_median(y_mins), 4),
        "table_y_max": round(_smart_median(y_maxs), 4),
        "minimum_field_evidence": 2,
    }
    config["status"] = "CANDIDATE" if len(rows) >= 3 else "DRAFT"
    return config


def _smart_extract_with_candidate(
    config: Dict[str, Any],
    raw_tokens: List[Dict[str, Any]],
) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
    tokens = _smart_normalized_tokens(raw_tokens)
    profile = (config or {}).get("spatial_profile") if isinstance((config or {}).get("spatial_profile"), dict) else {}
    header: Dict[str, Any] = {"supplierName": config.get("supplier_name", ""), "currency": config.get("currency", "")}
    for field, region in (profile.get("header_regions") or {}).items():
        page = int(region.get("page") or 1)
        candidates = [
            token for token in tokens
            if token["page"] == page
            and (token["x0"] + token["x1"]) / 2 >= float(region.get("x0") or 0) - 0.025
            and (token["x0"] + token["x1"]) / 2 <= float(region.get("x1") or 0) + 0.025
            and (token["y0"] + token["y1"]) / 2 >= float(region.get("y0") or 0) - 0.012
            and (token["y0"] + token["y1"]) / 2 <= float(region.get("y1") or 0) + 0.012
        ]
        raw = " ".join(token["text"] for token in sorted(candidates, key=lambda t: t["x0"])).strip()
        if not raw:
            continue
        if field in ("totalNet", "totalVat", "totalGross"):
            amounts = _template_agent_number_spans(raw)
            header[field] = _safe_float(amounts[-1]["value"]) if amounts else 0.0
        else:
            header[field] = raw
    columns = profile.get("columns") if isinstance(profile.get("columns"), dict) else {}
    ordered_columns = sorted(
        [(field, float(meta.get("center") or 0)) for field, meta in columns.items()],
        key=lambda pair: pair[1],
    )
    if not ordered_columns:
        return header, []
    y_min = max(0.0, float(profile.get("table_y_min") or 0) - 0.025)
    y_max = min(1.0, float(profile.get("table_y_max") or 1) + 0.025)
    table_tokens = [
        token for token in tokens
        if y_min <= (token["y0"] + token["y1"]) / 2 <= y_max
    ]
    grouped: List[List[Dict[str, Any]]] = []
    for token in table_tokens:
        center_y = (token["y0"] + token["y1"]) / 2
        target = next(
            (row for row in grouped if abs(center_y - _smart_median([(t["y0"] + t["y1"]) / 2 for t in row])) <= 0.008),
            None,
        )
        (target if target is not None else grouped.append([]) or grouped[-1]).append(token)
    items: List[Dict[str, Any]] = []
    for row in grouped:
        cells: Dict[str, List[str]] = {field: [] for field, _center in ordered_columns}
        for token in sorted(row, key=lambda t: t["x0"]):
            center_x = (token["x0"] + token["x1"]) / 2
            field = min(ordered_columns, key=lambda pair: abs(center_x - pair[1]))[0]
            cells[field].append(token["text"])
        item: Dict[str, Any] = {"lineNo": len(items) + 1}
        for field, values in cells.items():
            raw = " ".join(values).strip()
            if field in ("code", "description", "vatCode", "unitSize"):
                item[field] = raw
            else:
                nums = _template_agent_number_spans(raw)
                item[field] = _safe_float(nums[-1]["value"]) if nums else 0.0
        if _safe_float(item.get("vatAmount")) == 0.0:
            if _safe_float(item.get("lineGross")) and _safe_float(item.get("lineNet")):
                item["vatAmount"] = round(_safe_float(item.get("lineGross")) - _safe_float(item.get("lineNet")), 2)
            elif _safe_float(item.get("vatRate")) and _safe_float(item.get("lineNet")):
                item["vatAmount"] = round(
                    _safe_float(item.get("lineNet")) * _normalise_vat_rate(item.get("vatRate")) / 100.0,
                    2,
                )
        if str(item.get("description") or item.get("code") or "").strip() and _safe_float(item.get("lineNet")) != 0:
            items.append(item)
    return header, _ensure_line_numbers(items)


def _smart_save_training_example(
    res: Dict[str, Any],
    header: Dict[str, Any],
    items: List[Dict[str, Any]],
) -> Tuple[str, Dict[str, Any]]:
    supplier_name = _normalise_supplier_name(str((header or {}).get("supplierName") or "").strip())
    if not supplier_name:
        raise ValueError("Supplier name is required.")
    doctr_text, doctr_lines = _smart_doctr_text(res)
    doctr_tokens = list((res or {}).get("ocr_token_lines_snapshot") or [])
    if not doctr_tokens:
        cache_key = str((res or {}).get("ocr_cache_key") or "").strip()
        doctr_tokens = list(_OCR_TOKEN_LINES_CACHE.get(cache_key) or []) if cache_key else []
    doctr_tokens = _normalize_purchase_table_ocr_lines(doctr_tokens)
    if not doctr_text or not doctr_lines:
        raise ValueError("Fresh/local DocTR OCR boxes are required. Process this invoice with Local OCR (DocTR) first.")
    if not doctr_tokens:
        raise ValueError("DocTR word-level coordinates are required for smart spatial learning. Run fresh DocTR in the Training page.")

    local_data = LocalInvoiceParser.parse(doctr_text, str((res or {}).get("doc_type") or "Purchase Invoice"))
    local_header = copy.deepcopy((local_data or {}).get("header") or {})
    local_items = _recalc_items_for_engine(copy.deepcopy((local_data or {}).get("items") or []), "local_doctr")
    metrics = _smart_compare_teacher_to_doctr(header, items, doctr_text, local_header, local_items)
    alignment = _smart_align_example(header, items, doctr_tokens)
    file_bytes = bytes((res or {}).get("file_bytes") or b"")
    document_hash = _sha256_bytes(file_bytes) if file_bytes else _sha256_bytes(doctr_text.encode("utf-8"))
    supplier_key = _template_supplier_key(supplier_name)
    example_id = _sha256_bytes(f"{supplier_key}|{document_hash}".encode("utf-8"))[:32]
    now = _uk_now_iso()
    conn = _db_connect()
    try:
        conn.execute(
            """INSERT OR REPLACE INTO smart_training_examples(
                   example_id, supplier_key, supplier_name, file_name, document_hash,
                   teacher_engine, teacher_header_json, teacher_items_json,
                   doctr_text, doctr_lines_json, doctr_tokens_json, manual_mappings_json,
                   local_header_json, local_items_json,
                   header_score, line_score, reconciliation_diff, review_status,
                   created_at, updated_at)
               VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,COALESCE(
                   (SELECT created_at FROM smart_training_examples WHERE example_id=?),?),?)""",
            (
                example_id, supplier_key, supplier_name, str((res or {}).get("file") or ""),
                document_hash, str((res or {}).get("engine") or "cloud_gemini"),
                _smart_json(header or {}), _smart_json(_template_training_items(items or [])),
                doctr_text, _smart_json(doctr_lines), _smart_json(doctr_tokens),
                _smart_json((res or {}).get("smart_manual_mappings") or {}),
                _smart_json(local_header),
                _smart_json(local_items), metrics["header_score"], metrics["line_score"],
                metrics["reconciliation_diff"], "APPROVED", example_id, now, now,
            ),
        )
        counts = conn.execute(
            """SELECT COUNT(*) AS examples,
                      SUM(CASE WHEN review_status='VALIDATED' THEN 1 ELSE 0 END) AS validated,
                      AVG(header_score) AS header_score,
                      AVG(line_score) AS line_score,
                      AVG(CASE WHEN reconciliation_diff < 999999 THEN reconciliation_diff END) AS diff
                 FROM smart_training_examples WHERE supplier_key=?""",
            (supplier_key,),
        ).fetchone()
        example_count = int(counts["examples"] or 0)
        validated_count = int(counts["validated"] or 0)
        status = "CANDIDATE" if example_count >= 3 else "DRAFT"
        config = _smart_rebuild_supplier_candidate(conn, supplier_key, supplier_name)
        config["status"] = status
        conn.execute(
            """INSERT OR REPLACE INTO smart_supplier_models(
                   supplier_key, supplier_name, status, example_count, validated_count,
                   candidate_config_json, last_header_score, last_line_score,
                   last_reconciliation_diff, created_at, updated_at)
               VALUES(?,?,?,?,?,?,?,?,?,COALESCE(
                   (SELECT created_at FROM smart_supplier_models WHERE supplier_key=?),?),?)""",
            (
                supplier_key, supplier_name, status, example_count, validated_count,
                _smart_json(config), float(counts["header_score"] or 0),
                float(counts["line_score"] or 0), float(counts["diff"] or 0),
                supplier_key, now, now,
            ),
        )
        conn.commit()
    finally:
        conn.close()
    return example_id, metrics


def _smart_result_selector(page_key: str) -> Optional[Dict[str, Any]]:
    batch: List[Dict[str, Any]] = []
    direct_result = st.session_state.get("smart_studio_result")
    if isinstance(direct_result, dict) and not direct_result.get("error"):
        batch.append(direct_result)
    batch.extend([
        result for result in (st.session_state.get("last_batch") or [])
        if isinstance(result, dict) and not result.get("error")
        and result is not direct_result
    ])
    if not batch:
        st.info("Upload an invoice above and click **Extract with Gemini**.")
        return None
    labels = [
        f"{idx + 1}. {result.get('file','')} — {(result.get('header') or {}).get('supplierName','')} — {result.get('engine','')}"
        for idx, result in enumerate(batch)
    ]
    selected = st.selectbox("Training invoice", options=list(range(len(batch))), format_func=lambda idx: labels[idx], key=page_key)
    return batch[int(selected)]


def _smart_process_uploaded_invoice(
    uploaded: Any,
    settings: Dict[str, Any],
) -> Dict[str, Any]:
    file_bytes = bytes(uploaded.getvalue())
    if not file_bytes:
        raise ValueError("The uploaded invoice is empty.")
    file_name = str(getattr(uploaded, "name", "") or "training-invoice.pdf")
    mime = str(getattr(uploaded, "type", "") or "").strip()
    if not mime:
        mime = "application/pdf" if file_name.lower().endswith(".pdf") else "image/png"
    api_key = _get_google_api_key(settings)
    if not api_key:
        raise RuntimeError("A Gemini API key is required in Admin Settings.")
    text_hint = ""
    if mime == "application/pdf":
        try:
            text_hint = _pdf_text_layer(
                file_bytes,
                max_pages=max(1, int((settings or {}).get("ocr_max_pages", 10) or 10)),
            )
        except Exception:
            text_hint = ""
    extractor = CloudGeminiExtractor(
        api_key=api_key,
        model_name=str((settings or {}).get("gemini_model") or "gemini-3.6-flash"),
    )
    cloud = extractor.extract_purchase_invoice(
        file_bytes, mime, file_name, doc_text=text_hint,
    )
    header = copy.deepcopy((cloud or {}).get("header") or {})
    items = _recalc_items(copy.deepcopy((cloud or {}).get("items") or []))
    if not header and not items:
        raise RuntimeError("Gemini did not return an invoice header or line rows.")
    result: Dict[str, Any] = {
        "file": file_name,
        "file_bytes": file_bytes,
        "mime": mime,
        "engine": "cloud_gemini",
        "doc_type": "Purchase Invoice",
        "header": header,
        "items": items,
        "text_hint": text_hint,
        "text": text_hint,
        "debug_text": text_hint,
    }
    return result


def _render_smart_training_audit(example_id: str) -> None:
    detail = _db_fetchone("SELECT * FROM smart_training_examples WHERE example_id=?", (example_id,)) or {}
    if not detail:
        return
    model = _db_fetchone(
        "SELECT * FROM smart_supplier_models WHERE supplier_key=?",
        (detail.get("supplier_key"),),
    ) or {}
    st.divider()
    st.subheader("Training audit and immediate test")
    a1, a2, a3, a4 = st.columns(4)
    a1.metric("Supplier invoices trained", int(model.get("example_count") or 0))
    a2.metric("Template state", str(model.get("status") or "DRAFT"))
    a3.metric("DocTR header located", f"{float(detail.get('header_score') or 0):.1f}%")
    a4.metric("DocTR lines located", f"{float(detail.get('line_score') or 0):.1f}%")
    teacher_header = json.loads(detail.get("teacher_header_json") or "{}")
    teacher_items = json.loads(detail.get("teacher_items_json") or "[]")
    tokens = json.loads(detail.get("doctr_tokens_json") or "[]")
    config = json.loads(model.get("candidate_config_json") or "{}")
    candidate_header, candidate_items = _smart_extract_with_candidate(config, tokens)
    accuracy = _smart_structured_accuracy(
        teacher_header, teacher_items, candidate_header, candidate_items,
        detail.get("doctr_text") or "",
    )
    t1, t2, t3 = st.columns(3)
    t1.metric("Candidate header accuracy", f"{accuracy['header_score']:.1f}%")
    t2.metric("Candidate line accuracy", f"{accuracy['line_score']:.1f}%")
    t3.metric(
        "Reconciliation difference",
        "Not available" if accuracy["reconciliation_diff"] >= 999999 else f"{accuracy['reconciliation_diff']:.2f}",
    )
    teacher_col, candidate_col = st.columns(2)
    with teacher_col:
        st.markdown("#### Gemini / reviewed teacher")
        st.json(teacher_header)
        if pd is not None and teacher_items:
            st.dataframe(pd.DataFrame(teacher_items), hide_index=True, width="stretch")
    with candidate_col:
        st.markdown("#### Smart DocTR candidate")
        st.json(candidate_header)
        if pd is not None and candidate_items:
            st.dataframe(pd.DataFrame(candidate_items), hide_index=True, width="stretch")
        elif not candidate_items:
            st.warning("The candidate has not learned enough evidence to reproduce line rows yet.")
    with st.expander("Audit record and spatial template", expanded=False):
        st.json({
            "example_id": example_id,
            "supplier_key": detail.get("supplier_key"),
            "file_name": detail.get("file_name"),
            "teacher_engine": detail.get("teacher_engine"),
            "review_status": detail.get("review_status"),
            "manual_mappings": json.loads(detail.get("manual_mappings_json") or "{}"),
            "candidate_config": config,
        })
    nav1, nav2 = st.columns(2)
    if nav1.button("Open full supplier validation", width="stretch"):
        st.session_state["page"] = "Smart Template Validation"
        st.rerun()
    if nav2.button("Train another invoice", width="stretch"):
        st.session_state.pop("smart_studio_result", None)
        st.session_state.pop("smart_last_saved_example", None)
        st.rerun()


def _render_smart_training(settings: Dict[str, Any]) -> None:
    st.title("Smart Template Studio — Training")
    st.caption("Upload, extract, review, train, audit and test a supplier invoice without leaving this page.")
    uploaded = st.file_uploader(
        "Upload supplier invoice",
        type=["pdf", "png", "jpg", "jpeg", "tif", "tiff"],
        key="smart_studio_upload",
    )
    process_col, clear_col = st.columns([1, 1])
    if process_col.button(
        "1. Extract with Gemini",
        type="primary",
        disabled=uploaded is None,
        width="stretch",
    ):
        try:
            with st.spinner("Stage 1 of 2: Gemini is extracting the invoice header and line items..."):
                st.session_state["smart_studio_result"] = _smart_process_uploaded_invoice(uploaded, settings)
            st.session_state.pop("smart_last_saved_example", None)
            st.success("Gemini extraction completed. Review it below, then run Stage 2 DocTR mapping.")
            st.rerun()
        except Exception as exc:
            try:
                _log_event(
                    f"Smart Template Studio Gemini stage failed: {repr(exc)}",
                    file_name=str(getattr(uploaded, "name", "") or ""),
                )
            except Exception:
                pass
            st.error(f"Training extraction failed: {exc}")
    if clear_col.button("Clear training invoice", width="stretch"):
        st.session_state.pop("smart_studio_result", None)
        st.session_state.pop("smart_last_saved_example", None)
        st.rerun()
    res = _smart_result_selector("smart_training_invoice")
    if not res:
        return
    original_header = copy.deepcopy((res or {}).get("header") or {})
    original_items = _template_training_items(copy.deepcopy((res or {}).get("items") or []))
    left, right = st.columns([1.05, 1.2])
    with left:
        st.subheader("Invoice and DocTR preview")
        file_bytes = bytes((res or {}).get("file_bytes") or b"")
        mime = str((res or {}).get("mime") or "")
        doctr_text, doctr_lines = _smart_doctr_text(res)
        raw_tokens = list((res or {}).get("ocr_token_lines_snapshot") or [])
        if not raw_tokens:
            cache_key = str((res or {}).get("ocr_cache_key") or "").strip()
            raw_tokens = list(_OCR_TOKEN_LINES_CACHE.get(cache_key) or []) if cache_key else []
        manual_mappings = (res or {}).get("smart_manual_mappings")
        if not isinstance(manual_mappings, dict):
            manual_mappings = {}
            res["smart_manual_mappings"] = manual_mappings
        automatic_alignment = _smart_align_example(original_header, original_items, raw_tokens) if raw_tokens else {}
        mapping_alignment = _smart_apply_manual_mappings(automatic_alignment, manual_mappings)
        ocr_pages = sorted({
            int((line or {}).get("page") or 1)
            for line in doctr_lines
        }) or [1]
        if mime == "application/pdf" and file_bytes:
            try:
                pdf_pages = max(1, int(_pdf_page_count(file_bytes) or 1))
                available_pages = list(range(1, pdf_pages + 1))
            except Exception:
                available_pages = ocr_pages
        else:
            available_pages = ocr_pages
        page_state_key = f"smart_preview_page_number_{_sha256_bytes(file_bytes)[:12] if file_bytes else 'empty'}"
        current_page = int(st.session_state.get(page_state_key, available_pages[0]) or available_pages[0])
        current_page = max(min(available_pages), min(max(available_pages), current_page))
        page_prev, page_number, page_next = st.columns([1, 2, 1])
        if page_prev.button(
            "← Previous",
            key=f"{page_state_key}_previous",
            disabled=current_page <= min(available_pages),
            width="stretch",
        ):
            st.session_state[page_state_key] = max(min(available_pages), current_page - 1)
            st.rerun()
        if page_next.button(
            "Next →",
            key=f"{page_state_key}_next",
            disabled=current_page >= max(available_pages),
            width="stretch",
        ):
            st.session_state[page_state_key] = min(max(available_pages), current_page + 1)
            st.rerun()
        preview_page = int(
            page_number.number_input(
                "Preview page",
                min_value=min(available_pages),
                max_value=max(available_pages),
                step=1,
                key=page_state_key,
            )
        )
        overlay_mode = st.selectbox(
            "Mapping overlay",
            options=["Header mappings", "Line mappings", "Header + line mappings"],
            key=f"smart_overlay_mode_{_sha256_bytes(file_bytes)[:12] if file_bytes else 'empty'}",
        )
        try:
            preview = None
            cache_key = str((res or {}).get("ocr_cache_key") or "").strip()
            exact_ocr_pages = _OCR_PAGE_IMAGE_CACHE.get(cache_key) or {}
            if int(preview_page) in exact_ocr_pages:
                try:
                    preview = exact_ocr_pages[int(preview_page)].copy()
                except Exception:
                    preview = exact_ocr_pages[int(preview_page)]
            elif mime == "application/pdf":
                preview = _pdf_render_selected_pages(file_bytes, [int(preview_page)], dpi=130).get(int(preview_page))
            elif file_bytes:
                preview = Image.open(io.BytesIO(file_bytes)).convert("RGB") if Image is not None else None
            if preview is not None:
                if doctr_lines:
                    try:
                        from PIL import ImageDraw, ImageFont  # type: ignore
                        overlay = preview.copy().convert("RGB")
                        draw = ImageDraw.Draw(overlay)
                        try:
                            font = ImageFont.load_default()
                        except Exception:
                            font = None
                        # Header mappings: blue. Line-cell mappings: green.
                        header_overlay = overlay_mode in ("Header mappings", "Header + line mappings")
                        line_overlay = overlay_mode in ("Line mappings", "Header + line mappings")
                        for field, box in ((mapping_alignment.get("header_boxes") or {}).items() if header_overlay else []):
                            if int(box.get("page") or 1) != int(preview_page):
                                continue
                            mapped = {
                                "bbox": {
                                    "left": box["x0"], "top": box["y0"],
                                    "right": box["x1"], "bottom": box["y1"],
                                    "normalized": True,
                                }
                            }
                            rect = _ocr_bbox_to_image_rect(mapped, overlay.width, overlay.height)
                            if rect:
                                draw.rectangle(rect, outline=(37, 99, 235), width=3)
                                draw.text((rect[0], max(0, rect[1] - 12)), f"H:{field}", fill=(37, 99, 235), font=font)
                        for row in ((mapping_alignment.get("line_mappings") or []) if line_overlay else []):
                            row_no = int(row.get("row") or 0)
                            for field, box in (row.get("cells") or {}).items():
                                if int(box.get("page") or 1) != int(preview_page):
                                    continue
                                mapped = {
                                    "bbox": {
                                        "left": box["x0"], "top": box["y0"],
                                        "right": box["x1"], "bottom": box["y1"],
                                        "normalized": True,
                                    }
                                }
                                rect = _ocr_bbox_to_image_rect(mapped, overlay.width, overlay.height)
                                if rect:
                                    draw.rectangle(rect, outline=(22, 163, 74), width=2)
                                    draw.text(
                                        (rect[0], max(0, rect[1] - 10)),
                                        f"L{row_no}:{field}",
                                        fill=(13, 120, 55),
                                        font=font,
                                    )
                        preview = overlay
                    except Exception:
                        pass
                st.image(
                    preview,
                    caption=f"Invoice page {preview_page} with DocTR boxes",
                    use_container_width=True,
                )
        except Exception as exc:
            st.warning(f"Invoice preview unavailable: {exc}")
        if not doctr_lines:
            st.warning("Stage 2 is required before this invoice can be saved as a smart training example.")
            if st.button("2. Run DocTR Mapping", type="primary", width="stretch"):
                try:
                    with st.spinner("Stage 2 of 2: DocTR is processing pages and collecting word coordinates..."):
                        doctr_text, doctr_lines = _smart_run_fresh_doctr(res, settings)
                    st.success(f"DocTR completed with {len(doctr_lines)} OCR boxes.")
                    st.rerun()
                except Exception as exc:
                    try:
                        _log_event(
                            f"Smart Template Studio DocTR stage failed: {repr(exc)}",
                            file_name=str((res or {}).get("file") or ""),
                        )
                    except Exception:
                        pass
                    st.error(f"DocTR training pass failed: {exc}")
        st.metric("DocTR OCR boxes", len(doctr_lines))
        with st.expander("Header, line mapping and DocTR coordinates", expanded=True):
            map_header_tab, map_line_tab, raw_ocr_tab = st.tabs(
                ["Header Mapping", "Line Mapping", "Raw DocTR"]
            )
            with map_header_tab:
                header_rows = []
                header_boxes = mapping_alignment.get("header_boxes") or {}
                manual_resolutions = mapping_alignment.get("manual_resolutions") or {}
                for field in (
                    "supplierName", "customerName", "invoiceNumber", "invoiceDate",
                    "currency", "totalNet", "totalVat", "totalGross",
                ):
                    if original_header.get(field) in (None, ""):
                        continue
                    box = header_boxes.get(field)
                    resolution = manual_resolutions.get(f"header:{field}") or {}
                    resolution_type = str(resolution.get("resolution") or "").upper()
                    status = (
                        resolution_type
                        if resolution_type in {"CALCULATED", "NOT_PRINTED", "IGNORED"}
                        else "MANUAL" if box and box.get("manual")
                        else "MATCHED" if box
                        else "UNRESOLVED"
                    )
                    header_rows.append({
                        "field": field,
                        "Gemini / reviewed value": str(original_header.get(field) if original_header.get(field) is not None else ""),
                        "status": status,
                        "DocTR matched text": str((box or {}).get("ocr_text") or ""),
                        "page": int((box or {}).get("page") or 0),
                        "match": float((box or {}).get("match_score") or 0.0),
                        "bbox": _smart_json([
                            (box or {}).get("x0"), (box or {}).get("y0"),
                            (box or {}).get("x1"), (box or {}).get("y1"),
                        ]) if box else "",
                    })
                if header_rows and pd is not None:
                    header_filter = st.selectbox(
                        "Header status filter",
                        options=["ALL", "MATCHED", "UNRESOLVED", "MANUAL", "CALCULATED", "NOT_PRINTED", "IGNORED"],
                        key=f"smart_header_status_filter_{_sha256_bytes(file_bytes)[:12] if file_bytes else 'empty'}",
                    )
                    header_df = pd.DataFrame(header_rows)
                    if header_filter != "ALL":
                        header_df = header_df[header_df["status"] == header_filter]
                    st.dataframe(header_df, hide_index=True, width="stretch")
                else:
                    st.info("No header values have been aligned to DocTR word boxes.")
            with map_line_tab:
                line_rows = []
                mapped_rows = {
                    int(row.get("row") or 0): row.get("cells") or {}
                    for row in (mapping_alignment.get("line_mappings") or [])
                }
                for row_no, teacher_item in enumerate(original_items, start=1):
                    cells = mapped_rows.get(row_no, {})
                    for field in (
                        "code", "description", "qty", "unitPrice", "lineNet",
                        "vatCode", "vatRate", "vatAmount", "lineGross",
                    ):
                        value = teacher_item.get(field)
                        if value in (None, ""):
                            continue
                        box = cells.get(field)
                        resolution = manual_resolutions.get(f"line:{row_no}:{field}") or {}
                        resolution_type = str(resolution.get("resolution") or "").upper()
                        status = (
                            resolution_type
                            if resolution_type in {"CALCULATED", "NOT_PRINTED", "IGNORED"}
                            else "MANUAL" if box and box.get("manual")
                            else "MATCHED" if box
                            else "UNRESOLVED"
                        )
                        line_rows.append({
                            "row": row_no,
                            "field": field,
                            "Gemini / reviewed value": str(value),
                            "status": status,
                            "DocTR matched text": str((box or {}).get("ocr_text") or ""),
                            "page": int((box or {}).get("page") or 0),
                            "match": float((box or {}).get("match_score") or 0.0),
                            "bbox": _smart_json([
                                (box or {}).get("x0"), (box or {}).get("y0"),
                                (box or {}).get("x1"), (box or {}).get("y1"),
                            ]) if box else "",
                        })
                if line_rows and pd is not None:
                    line_filter = st.selectbox(
                        "Line status filter",
                        options=["ALL", "MATCHED", "UNRESOLVED", "MANUAL", "CALCULATED", "NOT_PRINTED", "IGNORED"],
                        key=f"smart_line_status_filter_{_sha256_bytes(file_bytes)[:12] if file_bytes else 'empty'}",
                    )
                    line_df = pd.DataFrame(line_rows)
                    if line_filter != "ALL":
                        line_df = line_df[line_df["status"] == line_filter]
                    st.dataframe(line_df, hide_index=True, width="stretch")
                else:
                    st.info("No line-item cells have been aligned to DocTR word boxes.")
            with raw_ocr_tab:
                if doctr_lines and pd is not None:
                    st.dataframe(pd.DataFrame(doctr_lines), hide_index=True, width="stretch")
                else:
                    st.text(doctr_text[:12000] or "No DocTR OCR stored for this result.")
        if raw_tokens:
            with st.expander("Manual Mapping Mode", expanded=False):
                st.caption(
                    "Select a DocMate field/cell, choose the correct DocTR words, optionally correct the OCR text, "
                    "then apply. Raw DocTR text remains unchanged for audit."
                )
                target_options: List[str] = []
                target_labels: Dict[str, str] = {}
                for field in (
                    "supplierName", "customerName", "invoiceNumber", "invoiceDate",
                    "currency", "totalNet", "totalVat", "totalGross",
                ):
                    if original_header.get(field) not in (None, ""):
                        target = f"header:{field}"
                        target_options.append(target)
                        target_labels[target] = f"Header · {field} = {original_header.get(field)}"
                for row_no, item in enumerate(original_items, start=1):
                    for field in (
                        "code", "description", "qty", "unitPrice", "lineNet",
                        "vatCode", "vatRate", "vatAmount", "lineGross",
                    ):
                        if item.get(field) not in (None, ""):
                            target = f"line:{row_no}:{field}"
                            target_options.append(target)
                            target_labels[target] = f"Line {row_no} · {field} = {item.get(field)}"
                manual_target = st.selectbox(
                    "Field or line cell to resolve",
                    options=target_options,
                    format_func=lambda target: target_labels.get(target, target),
                    key=f"smart_manual_target_{_sha256_bytes(file_bytes)[:12]}",
                )
                resolution = st.selectbox(
                    "Resolution type",
                    options=["manual", "corrected", "calculated", "not_printed", "ignored"],
                    format_func=lambda value: {
                        "manual": "Select printed DocTR words",
                        "corrected": "Select words and correct OCR text",
                        "calculated": "Calculated value — not mapped to printed text",
                        "not_printed": "Value is not printed on the invoice",
                        "ignored": "Ignore this optional field",
                    }[value],
                    key=f"smart_manual_resolution_{_sha256_bytes(file_bytes)[:12]}",
                )
                normalized_tokens = _smart_normalized_tokens(raw_tokens)
                token_pages = sorted({int(token["page"]) for token in normalized_tokens}) or [1]
                manual_page_key = f"smart_manual_page_{_sha256_bytes(file_bytes)[:12]}"
                if manual_page_key not in st.session_state:
                    st.session_state[manual_page_key] = (
                        int(preview_page) if int(preview_page) in token_pages else min(token_pages)
                    )
                manual_page = st.number_input(
                    "DocTR token page",
                    min_value=min(token_pages),
                    max_value=max(token_pages),
                    step=1,
                    key=manual_page_key,
                )
                page_token_indices = [
                    index for index, token in enumerate(normalized_tokens)
                    if int(token["page"]) == int(manual_page)
                ]
                drawn_token_indices: List[int] = []
                if resolution in ("manual", "corrected") and st_canvas is not None:
                    canvas_background = None
                    try:
                        cache_key = str((res or {}).get("ocr_cache_key") or "").strip()
                        cached_pages = _OCR_PAGE_IMAGE_CACHE.get(cache_key) or {}
                        if int(manual_page) in cached_pages:
                            canvas_background = cached_pages[int(manual_page)].copy()
                        elif mime == "application/pdf":
                            canvas_background = _pdf_render_selected_pages(
                                file_bytes, [int(manual_page)], dpi=130
                            ).get(int(manual_page))
                        elif file_bytes and Image is not None:
                            canvas_background = Image.open(io.BytesIO(file_bytes)).convert("RGB")
                    except Exception:
                        canvas_background = None
                    if canvas_background is not None:
                        original_width, original_height = canvas_background.size
                        canvas_size = st.selectbox(
                            "Drawable preview size",
                            options=[480, 540, 620],
                            index=0,
                            format_func=lambda value: {
                                480: "Fit to column (recommended)",
                                540: "Medium",
                                620: "Large",
                            }[value],
                            key=(
                                f"smart_manual_canvas_size_{_sha256_bytes(file_bytes)[:12]}_"
                                f"{int(manual_page)}"
                            ),
                        )
                        # st_canvas is fixed-width rather than responsive.  Keep
                        # the default below the Streamlit column width so the
                        # right side of the invoice is not clipped.
                        canvas_width = min(int(canvas_size), int(original_width))
                        canvas_height = max(
                            1, int(round(original_height * (canvas_width / float(original_width))))
                        )
                        st.caption(
                            "Draw one rectangle around the exact printed value. "
                            "The intersecting DocTR words will be selected automatically."
                        )
                        canvas_result = st_canvas(
                            fill_color="rgba(255, 215, 0, 0.12)",
                            stroke_width=3,
                            stroke_color="#ff3b30",
                            background_image=canvas_background,
                            update_streamlit=True,
                            height=canvas_height,
                            width=canvas_width,
                            drawing_mode="rect",
                            display_toolbar=True,
                            key=(
                                f"smart_manual_canvas_{_sha256_bytes(file_bytes)[:12]}_"
                                f"{int(manual_page)}_{manual_target}"
                            ),
                        )
                        canvas_objects = (
                            ((canvas_result.json_data or {}).get("objects") or [])
                            if canvas_result is not None else []
                        )
                        rectangles = [
                            obj for obj in canvas_objects
                            if str((obj or {}).get("type") or "") == "rect"
                        ]
                        if rectangles:
                            obj = rectangles[-1]
                            scale_x = float(obj.get("scaleX") or 1.0)
                            scale_y = float(obj.get("scaleY") or 1.0)
                            left = float(obj.get("left") or 0.0)
                            top = float(obj.get("top") or 0.0)
                            right = left + (float(obj.get("width") or 0.0) * scale_x)
                            bottom = top + (float(obj.get("height") or 0.0) * scale_y)
                            drawn_box = {
                                "x0": max(0.0, min(1.0, left / float(canvas_width))),
                                "y0": max(0.0, min(1.0, top / float(canvas_height))),
                                "x1": max(0.0, min(1.0, right / float(canvas_width))),
                                "y1": max(0.0, min(1.0, bottom / float(canvas_height))),
                            }
                            for index in page_token_indices:
                                token = normalized_tokens[index]
                                overlap_x = max(
                                    0.0,
                                    min(drawn_box["x1"], token["x1"])
                                    - max(drawn_box["x0"], token["x0"]),
                                )
                                overlap_y = max(
                                    0.0,
                                    min(drawn_box["y1"], token["y1"])
                                    - max(drawn_box["y0"], token["y0"]),
                                )
                                if overlap_x > 0.0 and overlap_y > 0.0:
                                    drawn_token_indices.append(index)
                            if drawn_token_indices:
                                st.success(
                                    f"{len(drawn_token_indices)} DocTR word(s) selected from the drawn box."
                                )
                            else:
                                st.warning(
                                    "The drawn box does not intersect a DocTR word. "
                                    "Make the rectangle slightly larger or use the word list below."
                                )
                elif resolution in ("manual", "corrected"):
                    st.info(
                        "Interactive drawing is unavailable. Install streamlit-drawable-canvas "
                        "or use the DocTR word selector below."
                    )
                drawn_selection_key = _sha256_bytes(
                    ",".join(str(index) for index in drawn_token_indices).encode("utf-8")
                )[:10]
                selected_token_indices = st.multiselect(
                    "Select the printed DocTR word(s)",
                    options=page_token_indices,
                    default=drawn_token_indices,
                    format_func=lambda index: (
                        f"{index + 1}: {normalized_tokens[index]['text']} "
                        f"(x={normalized_tokens[index]['x0']:.3f}, y={normalized_tokens[index]['y0']:.3f})"
                    ),
                    disabled=resolution in ("calculated", "not_printed", "ignored"),
                    key=(
                        f"smart_manual_tokens_{_sha256_bytes(file_bytes)[:12]}_"
                        f"{int(manual_page)}_{manual_target}_{drawn_selection_key}"
                    ),
                )
                selected_raw_text = " ".join(
                    normalized_tokens[index]["text"]
                    for index in selected_token_indices
                ).strip()
                corrected_text = st.text_input(
                    "Reviewed/corrected mapped text",
                    value=selected_raw_text,
                    disabled=resolution in ("calculated", "not_printed", "ignored"),
                    key=f"smart_manual_corrected_{_sha256_bytes(file_bytes)[:12]}",
                )
                apply_col, remove_col = st.columns(2)
                can_apply = bool(
                    resolution in ("calculated", "not_printed", "ignored")
                    or selected_token_indices
                )
                if apply_col.button(
                    "Apply manual mapping",
                    type="primary",
                    disabled=not can_apply,
                    width="stretch",
                    key=f"smart_manual_apply_{_sha256_bytes(file_bytes)[:12]}",
                ):
                    override: Dict[str, Any] = {
                        "resolution": resolution,
                        "raw_text": selected_raw_text,
                        "corrected_text": str(corrected_text or selected_raw_text),
                        "reviewed_at": _uk_now_iso(),
                    }
                    if selected_token_indices and resolution in ("manual", "corrected"):
                        selected_tokens = [normalized_tokens[index] for index in selected_token_indices]
                        override["box"] = {
                            "page": int(manual_page),
                            "x0": min(token["x0"] for token in selected_tokens),
                            "y0": min(token["y0"] for token in selected_tokens),
                            "x1": max(token["x1"] for token in selected_tokens),
                            "y1": max(token["y1"] for token in selected_tokens),
                        }
                    manual_mappings[manual_target] = override
                    res["smart_manual_mappings"] = manual_mappings
                    st.success(f"Manual resolution applied to {target_labels.get(manual_target, manual_target)}.")
                    st.rerun()
                if remove_col.button(
                    "Remove manual mapping",
                    disabled=manual_target not in manual_mappings,
                    width="stretch",
                    key=f"smart_manual_remove_{_sha256_bytes(file_bytes)[:12]}",
                ):
                    manual_mappings.pop(manual_target, None)
                    res["smart_manual_mappings"] = manual_mappings
                    st.rerun()
    with right:
        st.subheader("Reviewed Gemini teacher output")
        header_fields = {
            "supplierName": "Supplier", "customerName": "Customer", "invoiceNumber": "Invoice number",
            "invoiceDate": "Invoice date", "currency": "Currency", "totalNet": "Net",
            "totalVat": "VAT", "totalGross": "Gross",
        }
        reviewed_header = copy.deepcopy(original_header)
        cols = st.columns(2)
        for idx, (field, label) in enumerate(header_fields.items()):
            value = reviewed_header.get(field, "")
            reviewed_header[field] = cols[idx % 2].text_input(
                label, value=str(value if value is not None else ""), key=f"smart_hdr_{field}"
            )
        for field in ("totalNet", "totalVat", "totalGross"):
            reviewed_header[field] = _safe_float(reviewed_header.get(field))
        if pd is not None:
            edited_df = st.data_editor(
                pd.DataFrame(original_items), num_rows="dynamic", width="stretch",
                key="smart_teacher_line_editor",
            )
            reviewed_items = edited_df.to_dict("records")
        else:
            st.write(original_items)
            reviewed_items = original_items
        doctr_text, _lines = _smart_doctr_text(res)
        live_metrics = _smart_compare_teacher_to_doctr(reviewed_header, reviewed_items, doctr_text)
        m1, m2, m3 = st.columns(3)
        m1.metric("Header located", f"{live_metrics['header_score']:.1f}%")
        m2.metric("Lines located", f"{live_metrics['line_score']:.1f}%")
        m3.metric("Teacher rows", len(reviewed_items))
        resolution_records = mapping_alignment.get("manual_resolutions") or {}
        resolved_targets = {
            target for target, record in resolution_records.items()
            if str((record or {}).get("resolution") or "").lower()
            in {"manual", "corrected", "calculated", "not_printed", "ignored"}
        }
        aligned_header_fields = set((mapping_alignment.get("header_boxes") or {}).keys())
        aligned_header_fields.update(
            target.split(":", 1)[1]
            for target in resolved_targets
            if target.startswith("header:") and ":" in target
        )
        critical_header_fields = {
            field for field in ("supplierName", "invoiceNumber", "invoiceDate", "totalNet", "totalVat", "totalGross")
            if reviewed_header.get(field) not in (None, "")
        }
        mapped_line_rows = {
            int(row.get("row") or 0): set((row.get("cells") or {}).keys())
            for row in (mapping_alignment.get("line_mappings") or [])
        }
        for target in resolved_targets:
            parts = target.split(":")
            if len(parts) == 3 and parts[0] == "line":
                try:
                    mapped_line_rows.setdefault(int(parts[1]), set()).add(parts[2])
                except Exception:
                    pass
        unresolved_line_rows = [
            row_no
            for row_no, item in enumerate(reviewed_items, start=1)
            if str(item.get("description") or "").strip()
            and not {"description", "lineNet"}.issubset(mapped_line_rows.get(row_no, set()))
        ]
        unresolved_header = sorted(critical_header_fields - aligned_header_fields)
        training_ready = bool(_lines) and not unresolved_header and not unresolved_line_rows
        approve = st.checkbox(
            "I reviewed the header and every line row",
            key="smart_teacher_approved",
            disabled=not training_ready,
        )
        if not training_ready:
            if not _lines:
                st.caption("Complete Stage 2 DocTR Mapping before approving and saving this training example.")
            else:
                st.error(
                    "Resolve mapping differences before saving. "
                    + (f"Header: {', '.join(unresolved_header)}. " if unresolved_header else "")
                    + (
                        f"Line rows missing description/lineNet mapping: {', '.join(str(row) for row in unresolved_line_rows[:20])}."
                        if unresolved_line_rows else ""
                    )
                )
        if st.button(
            "Save approved training example",
            type="primary",
            disabled=(not approve or not training_ready),
        ):
            try:
                example_id, metrics = _smart_save_training_example(res, reviewed_header, reviewed_items)
                st.success(
                    f"Training example saved: {example_id}. "
                    f"DocTR header match {metrics['header_score']:.1f}%, line match {metrics['line_score']:.1f}%."
                )
                st.session_state["smart_last_saved_example"] = example_id
                st.rerun()
            except Exception as exc:
                st.error(str(exc))
    last_example = str(st.session_state.get("smart_last_saved_example") or "").strip()
    if last_example:
        _render_smart_training_audit(last_example)


def _render_smart_validation(settings: Dict[str, Any]) -> None:
    st.title("Smart Template Studio — Validation")
    models = _db_fetchall(
        """SELECT supplier_key, supplier_name, status, example_count, validated_count,
                  candidate_config_json, last_header_score, last_line_score,
                  last_reconciliation_diff, updated_at
             FROM smart_supplier_models ORDER BY supplier_name"""
    )
    if not models:
        st.info("No smart training examples have been approved yet.")
        return
    st.subheader("Supplier training coverage")
    if pd is not None:
        st.dataframe(pd.DataFrame(models), hide_index=True, width="stretch")
    selected_key = st.selectbox(
        "Supplier", options=[row["supplier_key"] for row in models],
        format_func=lambda key: next((row["supplier_name"] for row in models if row["supplier_key"] == key), key),
    )
    model = next(row for row in models if row["supplier_key"] == selected_key)
    c1, c2, c3, c4 = st.columns(4)
    c1.metric("Invoices trained", int(model.get("example_count") or 0))
    c2.metric("Validated", int(model.get("validated_count") or 0))
    c3.metric("Header/DocTR", f"{float(model.get('last_header_score') or 0):.1f}%")
    c4.metric("Lines/DocTR", f"{float(model.get('last_line_score') or 0):.1f}%")
    examples = _db_fetchall(
        """SELECT example_id, file_name, teacher_engine, header_score, line_score,
                  reconciliation_diff, review_status, created_at
             FROM smart_training_examples WHERE supplier_key=? ORDER BY created_at DESC""",
        (selected_key,),
    )
    if pd is not None:
        st.dataframe(pd.DataFrame(examples), hide_index=True, width="stretch")
    example_ids = [row["example_id"] for row in examples]
    if not example_ids:
        return
    selected_example = st.selectbox("Compare invoice", options=example_ids)
    detail = _db_fetchone("SELECT * FROM smart_training_examples WHERE example_id=?", (selected_example,)) or {}
    teacher_header = json.loads(detail.get("teacher_header_json") or "{}")
    teacher_items = json.loads(detail.get("teacher_items_json") or "[]")
    local_header = json.loads(detail.get("local_header_json") or "{}")
    local_items = json.loads(detail.get("local_items_json") or "[]")
    candidate_config = json.loads(model.get("candidate_config_json") or "{}")
    doctr_tokens = json.loads(detail.get("doctr_tokens_json") or "[]")
    spatial_header, spatial_items = _smart_extract_with_candidate(candidate_config, doctr_tokens)
    spatial_metrics = _smart_structured_accuracy(
        teacher_header,
        teacher_items,
        spatial_header,
        spatial_items,
        detail.get("doctr_text") or "",
    )
    hcol, lcol = st.columns(2)
    with hcol:
        st.markdown("#### Gemini / reviewed teacher")
        st.json(teacher_header)
        if pd is not None and teacher_items:
            st.dataframe(pd.DataFrame(teacher_items), hide_index=True, width="stretch")
    with lcol:
        st.markdown("#### Smart spatial template candidate")
        st.json(spatial_header)
        if pd is not None and spatial_items:
            st.dataframe(pd.DataFrame(spatial_items), hide_index=True, width="stretch")
        elif not spatial_items:
            st.warning("The spatial candidate did not reproduce line rows from this invoice.")
    sm1, sm2, sm3 = st.columns(3)
    sm1.metric("Candidate header", f"{spatial_metrics['header_score']:.1f}%")
    sm2.metric("Candidate lines", f"{spatial_metrics['line_score']:.1f}%")
    sm3.metric(
        "Candidate reconciliation",
        "Not available" if spatial_metrics["reconciliation_diff"] >= 999999 else f"{spatial_metrics['reconciliation_diff']:.2f}",
    )
    with st.expander("Candidate spatial profile", expanded=False):
        st.json(candidate_config)
    with st.expander("Baseline local parser comparison", expanded=False):
        st.json(local_header)
        if pd is not None and local_items:
            st.dataframe(pd.DataFrame(local_items), hide_index=True, width="stretch")
    validation_passes = bool(
        spatial_metrics["header_score"] >= 95
        and spatial_metrics["line_score"] >= 95
        and spatial_metrics["candidate_rows"] == spatial_metrics["teacher_rows"]
        and spatial_metrics["reconciliation_diff"] < 999999
        and spatial_metrics["reconciliation_diff"] <= 0.05
    )
    if detail.get("review_status") != "VALIDATED":
        if not validation_passes:
            st.warning("This candidate has not met the held-out validation thresholds and cannot be verified yet.")
        if st.button("Mark this invoice as held-out validated", type="primary", disabled=not validation_passes):
            now = _uk_now_iso()
            _db_execute(
                "UPDATE smart_training_examples SET review_status='VALIDATED', updated_at=? WHERE example_id=?",
                (now, selected_example),
            )
            _db_execute(
                """UPDATE smart_supplier_models
                      SET validated_count=(SELECT COUNT(*) FROM smart_training_examples
                                           WHERE supplier_key=? AND review_status='VALIDATED'),
                          status=CASE
                              WHEN example_count>=3
                               AND ?>=95
                               AND ?>=95
                              THEN 'VERIFIED' ELSE status END,
                          last_header_score=?,
                          last_line_score=?,
                          last_reconciliation_diff=?,
                          updated_at=?
                    WHERE supplier_key=?""",
                (
                    selected_key,
                    spatial_metrics["header_score"], spatial_metrics["line_score"],
                    spatial_metrics["header_score"], spatial_metrics["line_score"],
                    spatial_metrics["reconciliation_diff"], now, selected_key,
                ),
            )
            st.success("Validation recorded.")
            st.rerun()


def _render_templates(settings: Dict[str, Any]) -> None:
    st.title("Template Management")
    if not GENERIC_TEMPLATE_TRAINING_ENABLED:
        st.caption(
            "Generic supplier/customer template training has been retired. "
            "Dedicated parser configurations are preserved for Booker, Dhamecha, Parfetts and DWG."
        )
        nav_train, nav_validate = st.columns(2)
        if nav_train.button("Open Smart Training", type="primary", width="stretch"):
            st.session_state["page"] = "Smart Template Training"
            st.rerun()
        if nav_validate.button("Open Smart Validation", width="stretch"):
            st.session_state["page"] = "Smart Template Validation"
            st.rerun()
        dedicated_rows = _db_fetchall(
            """SELECT display_id, template_id, supplier_name, parser_type, requires_cloud,
                      created_at, updated_at
                 FROM supplier_templates
                WHERE UPPER(TRIM(COALESCE(parser_type,''))) IN ('BOOKER','DHAMECHA','PARFETTS','DWG')
                ORDER BY parser_type, supplier_name"""
        )
        if dedicated_rows:
            if pd is not None:
                st.dataframe(pd.DataFrame([dict(row) for row in dedicated_rows]), width="stretch", hide_index=True)
            else:
                st.write([dict(row) for row in dedicated_rows])
        else:
            st.info("No dedicated parser configuration records are currently stored.")
        return
    st.caption(
        "Manage supplier and customer templates used by DocMate Auto processing. "
        "Templates help DocMate extract purchase invoices accurately for VBR deployments."
    )

    conn = _get_db()
    with st.expander("Central Template Sync (SQL Server)", expanded=False):
        st.caption(
            "Use this to combine templates trained by different team members. "
            "Push sends local templates to SQL Server; pull imports approved central templates into this local app."
        )
        source_site = st.text_input(
            "Source site / team name",
            value=str(settings.get("template_sync_source_site") or os.environ.get("COMPUTERNAME") or ""),
            key="template_sync_source_site_input",
            help="Stored on central templates so the team can see where a template came from.",
        )
        settings["template_sync_source_site"] = source_site
        sync_col1, sync_col2, sync_col3, sync_col4 = st.columns(4)
        if sync_col1.button("Push supplier templates", key="push_supplier_templates"):
            try:
                summary = _push_templates_to_central("supplier_templates", source_site=source_site)
                st.success(f"Supplier templates pushed: {summary['pushed']} / {summary['total']}")
                if summary.get("errors"):
                    st.warning("\n".join(str(x) for x in summary["errors"][:8]))
            except Exception as e:
                st.error(f"Supplier template push failed: {e}")
        if sync_col2.button("Pull supplier templates", key="pull_supplier_templates"):
            try:
                summary = _pull_templates_from_central("supplier_templates", approved_only=True)
                st.success(f"Supplier templates pulled: {summary['pulled']} / {summary['total']}")
                if summary.get("errors"):
                    st.warning("\n".join(str(x) for x in summary["errors"][:8]))
                st.rerun()
            except Exception as e:
                st.error(f"Supplier template pull failed: {e}")
        if sync_col3.button("Push customer templates", key="push_customer_templates"):
            try:
                summary = _push_templates_to_central("customer_templates", source_site=source_site)
                st.success(f"Customer templates pushed: {summary['pushed']} / {summary['total']}")
                if summary.get("errors"):
                    st.warning("\n".join(str(x) for x in summary["errors"][:8]))
            except Exception as e:
                st.error(f"Customer template push failed: {e}")
        if sync_col4.button("Pull customer templates", key="pull_customer_templates"):
            try:
                summary = _pull_templates_from_central("customer_templates", approved_only=True)
                st.success(f"Customer templates pulled: {summary['pulled']} / {summary['total']}")
                if summary.get("errors"):
                    st.warning("\n".join(str(x) for x in summary["errors"][:8]))
                st.rerun()
            except Exception as e:
                st.error(f"Customer template pull failed: {e}")

    tab_sup, tab_cust, tab_builder = st.tabs(["Supplier Templates", "Customer Templates", "Template Builder / Test"])

    with tab_sup:
        st.subheader("Supplier Templates")
        st.caption("Templates matched by supplier name/keywords. Used in Auto mode before OCR fallback.")
        _render_template_table("supplier_templates", "Supplier Templates")

    with tab_cust:
        st.subheader("Customer Templates")
        st.caption("Customer-specific templates/overrides (optional).")
        _render_template_table("customer_templates", "Customer Templates")

    with tab_builder:
        st.subheader("Template Builder / Test")
        st.caption("Create, edit and test templates. Use carefully so invoice parsing remains stable.")
        try:
            _render_template_builder(settings)
        except Exception as e:
            st.error(f"Template builder error: {e}")
def _render_admin_settings(settings: Dict[str, Any]) -> None:
    # Admin page header is already shown in the static frame above.

    if not st.session_state.get("is_admin"):
        st.warning("Admin settings are Admin-only.")
        return



    # Quick Admin navigation (Admin area is intentionally hidden behind the  icon)
    nav1, nav2, nav3, nav4, nav5, nav6 = st.columns(6)
