def _render_system_info() -> None:
    st.header("System Information")

    node = st.selectbox(
        "Tree",
        options=["System Overview", "Version History", "Technical PRD", "Event Log"],
        index=0,
    )

    if node == "System Overview":
        st.markdown(
            f"""**App:** {APP_TITLE}  
**Version:** {APP_VERSION} ({APP_DATE})  
**Release note:** {APP_VERSION_NOTE}  

**Built for:** Visual Business Retail Ltd (VBR)  works with VBR EPOS, Cloud Reporting, Loyalty & Online Ordering.
"""
        )
        st.write("Local time:", _uk_now_iso())

    elif node == "Version History":
        version_tab, pipeline_tab = st.tabs(["Version History", "Upcoming Pipeline Work/Project Tasks"])
        with version_tab:
            versions = _db_get_versions()
            if pd is not None and versions:
                st.dataframe(pd.DataFrame(versions), width='stretch', hide_index=True)
            else:
                st.write(versions)
        with pipeline_tab:
            _render_pipeline_work()

    elif node == "Technical PRD":
        prd = _db_get_system_doc("PRD")
        if not prd:
            st.info("PRD not found")
            return
        st.subheader(prd.get("title") or "PRD")
        st.markdown(prd.get("content_md") or "")
        if st.session_state.get("is_admin"):
            with st.expander("Edit PRD (Admin)"):
                title = st.text_input("Title", value=prd.get("title") or "")
                content = st.text_area("Content (Markdown)", value=prd.get("content_md") or "", height=300)
                if st.button("Save PRD"):
                    _db_update_system_doc("PRD", title, content)
                    st.success("PRD updated")
                    _log_event("Admin updated PRD")

    elif node == "Event Log":
        st.subheader("Event Log (Today)")
        # Show current UK time at the top so you dont have to scroll to find latest
        try:
            now_uk = _uk_now_iso()
        except Exception:
            now_uk = ""
        lines = _read_event_log(6000)
        if not lines:
            st.info("Event log is empty.")
            return

        # Convert timestamps to UK display and group by processing runs.
        # A "run" starts when we see: "<file> START engine=..."
        entries = []
        for ln in lines:
            m = re.match(r"^\[(.*?)\]\s*(.*)$", ln)
            if m:
                entries.append((_to_uk_ts(m.group(1)), m.group(2)))
            else:
                entries.append(("", ln))

        runs = []
        current = []
        for (uk_ts, rest) in entries:
            if " START engine=" in rest and current:
                runs.append(current)
                current = []
            current.append((uk_ts, rest))
        if current:
            runs.append(current)

        # Newest runs first
        runs = list(reversed(runs))

        st.caption(f"Now (UK): {now_uk}      Runs shown: {min(len(runs), 25)} of {len(runs)}      Lines: {len(entries)}")

        max_runs = 25
        for idx, run in enumerate(runs[:max_runs], start=1):
            # Divider per run
            st.markdown("---")
            # Use the START line (if present) as the title
            start_line = next((r for r in run if " START engine=" in r[1]), run[0])
            title = start_line[1]
            st.markdown(f"**Run {idx}:** {title}")

            block = "\n".join([f"[{t}] {msg}".rstrip() if t else msg for (t, msg) in run])
            st.code(block, language="text")


# -------------------------
# Main
# -------------------------




def _render_reports() -> None:
    st.subheader("Reports")
    st.info("Reports module is planned: profitability KPIs, POR exceptions, selling vs RRP, and export to VBR Cloud Reporting. For now, use Registers export while we stabilise supplier parsing.")
    st.markdown("- Upcoming: **Low POR alerts**, **Selling below RRP**, **VAT code anomalies**, **supplier price drift**.")

    st.divider()
    st.subheader("Invoice Price vs Customer Price")
    st.caption("Creates a CSV for the latest uploaded invoice: vendorcode, barcode, invoice_price, customer_price, margin_pct.")

    if _sqlserver is None:
        st.warning("SQL Server integration not available (sql_server_customer.py import failed).")
        return

    output_path = os.path.join(DATA_DIR, "booker_report.csv")

    if st.button("Create Booker Report (Latest Invoice)", type="primary"):
        try:
            from DocMate_master_db import export_latest_booker_invoice_report_csv
            export_latest_booker_invoice_report_csv(output_path=output_path)
            st.success(f"Report created: {output_path}")
        except Exception as e:
            st.error(f"Report failed: {e}")

    if os.path.exists(output_path):
        try:
            with open(output_path, "rb") as f:
                csv_bytes = f.read()
            st.download_button(
                "Download Booker Report CSV",
                data=csv_bytes,
                file_name=f"Booker_Report_{_uk_now_iso()[:10]}.csv",
                mime="text/csv",
            )
            if pd is not None:
                df_report = pd.read_csv(io.BytesIO(csv_bytes))
                if df_report is not None and not df_report.empty:
                    # Format numeric columns for a clean, aligned preview
                    num_cols = [
                        "invoice_pack_cost","invoice_unit_price","customer_price","margin_pct","master_margin",
                        "case_pack_quantity","unit_cost","pack_cost","rrp","margin_delta",
                    ]
                    for c in num_cols:
                        if c in df_report.columns:
                            df_report[c] = pd.to_numeric(df_report[c], errors="coerce")
                    for c in ["invoice_pack_cost","invoice_unit_price","customer_price","unit_cost","pack_cost","rrp"]:
                        if c in df_report.columns:
                            df_report[c] = df_report[c].round(2)
                    for c in ["margin_pct","master_margin","margin_delta"]:
                        if c in df_report.columns:
                            df_report[c] = df_report[c].round(4)

                    st.write("Report Preview")
                    page_size = st.selectbox(
                        "Rows per page",
                        options=[50, 100, 200, 500, 1000],
                        index=1,
                        key="booker_report_page_size",
                    )
                    total_rows = int(len(df_report))
                    total_pages = max(1, int(math.ceil(total_rows / page_size)))
                    page = st.number_input(
                        "Page",
                        min_value=1,
                        max_value=total_pages,
                        value=1,
                        step=1,
                        key="booker_report_page",
                    )
                    start = (page - 1) * page_size
                    end = min(start + page_size, total_rows)
                    st.caption(f"Rows {start + 1}-{end} of {total_rows}")
                    st.dataframe(df_report.iloc[start:end], width='stretch', use_container_width=True)
                else:
                    st.info("Report file is empty.")
            else:
                st.info("Pandas is not available to preview the report.")
        except Exception as e:
            st.error(f"Could not read report file: {e}")


def _render_database_management() -> None:
    """
    Admin-only: Product Master database (SQLite) + CSV import/export.

    This is the foundation for future margin intelligence:
      - Compare invoice costs vs current selling prices (POR / margin)
      - Alert when POR is below target, selling below Std RRP, etc.
      - Publish insights into VBR Cloud Reporting / SPOS Cloud-style dashboards
    """
    st.subheader("Database Management")

    # ---- Table schema (Products Master) ----
    # NOTE: SQLite is used locally for speed and portability. This can later be mirrored to SQL Server / Azure SQL
    # for centralised reporting (aligns with VBR Cloud Reporting / multi-site deployments).
    st.info(
        "Products Master lives in the local SQLite database (docmate.db). "
        "You can import a customer product file (CSV), review records, and export. "
        "This enables future profit-margin and pricing exception reports."
    )


    # ---- Helpers ----
    def _norm_col(name: str) -> str:
        s = (name or "").strip().lower()
        s = re.sub(r"[\s\-\/\(\)\.]+", "", s)
        s = s.replace("%", "pct")
        return s

    # Accepted columns (user-friendly CSV headers) -> internal column name
    col_map = {
        "siteid": "site_id",
        "site": "site_id",
        "tradingname": "trading_name",
        "operatingcompany": "operating_company",
        "pluno": "plu_no",
        "plu": "plu_no",
        "productname": "product_name",
        "deptno": "dept_no",
        "deptname": "dept_name",
        "unitsize": "unit_size",
        "pvatcode": "pvat_code",
        "pvatrate": "pvat_rate",
        "sellingprice": "selling_price",
        "supplierno": "supplier_no",
        "suppliername": "supplier_name",
        "suppliercode": "supplier_code",
        "casepack": "case_pack",
        "casecost": "case_cost",
        "vatcode": "vat_code",
        "vatrate": "vat_rate",
        "unitcost": "unit_cost",
        "stdrrpincvat": "std_rrp_inc_vat",
        "stdrrpexcvat": "std_rrp_exc_vat",
        "ppor": "ppor",
    }

    required = ["plu_no", "product_name"]

    with st.expander("Import Products CSV", expanded=True):
        st.caption(
            "Upload a CSV with columns such as: PLUNo, ProductName, DeptNo, DeptName, UnitSize, "
            "PVATCode, PVATRate, SellingPrice, SupplierNo, SupplierName, SupplierCode, CasePack, "
            "CaseCost, VatCode, VatRate, UnitCost, STDRRP(incVAT), STDRRP(exc.VAT), PPOR. "
            "Optional: SiteID, Trading Name, Operating Company."
        )
        up = st.file_uploader("Choose CSV file", type=["csv"], key="products_csv_uploader")
        if up is not None:
            try:
                df = pd.read_csv(up)
            except Exception:
                # Try with alternate encodings/delimiters
                up.seek(0)
                df = pd.read_csv(up, encoding_errors="ignore")

            if df is None or df.empty:
                st.warning("CSV appears empty.")
            else:
                # Build rename mapping
                rename = {}
                for c in df.columns:
                    k = _norm_col(str(c))
                    if k in col_map:
                        rename[c] = col_map[k]
                df = df.rename(columns=rename)

                missing = [c for c in required if c not in df.columns]
                if missing:
                    st.error(f"Missing required columns: {', '.join(missing)}")
                else:
                    # Ensure all internal columns exist
                    internal_cols = [
                        "site_id","plu_no","product_name","dept_no","dept_name","unit_size",
                        "pvat_code","pvat_rate","selling_price","supplier_no","supplier_name","supplier_code",
                        "case_pack","case_cost","vat_code","vat_rate","unit_cost","std_rrp_inc_vat","std_rrp_exc_vat","ppor",
                        "trading_name","operating_company"
                    ]
                    for c in internal_cols:
                        if c not in df.columns:
                            df[c] = None

                    # Normalise values
                    df["site_id"] = df["site_id"].fillna("").astype(str).str.strip()
                    df["plu_no"] = df["plu_no"].astype(str).str.strip()
                    df["product_name"] = df["product_name"].fillna("").astype(str).str.strip()

                    # Numeric conversions
                    num_cols = [
                        "pvat_rate","selling_price","case_pack","case_cost","vat_rate","unit_cost","std_rrp_inc_vat","std_rrp_exc_vat","ppor"
                    ]
                    for c in num_cols:
                        try:
                            df[c] = df[c].apply(_safe_float)
                        except Exception:
                            pass

                    df["updated_at"] = _uk_now_iso()

                    st.write("Preview (first 50 rows):")
                    st.dataframe(df[internal_cols + ["updated_at"]].head(50), width='stretch')

                    # Import action
                    if st.button("Import / Upsert into Products Master", type="primary"):
                        try:
                            conn = _db_connect()
                            cur = conn.cursor()
                            cur.execute("BEGIN")
                            sql = """
                                INSERT INTO products_master(
                                    site_id, plu_no, product_name, dept_no, dept_name, unit_size,
                                    pvat_code, pvat_rate, selling_price, supplier_no, supplier_name, supplier_code,
                                    case_pack, case_cost, vat_code, vat_rate, unit_cost,
                                    std_rrp_inc_vat, std_rrp_exc_vat, ppor, trading_name, operating_company, updated_at
                                ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                                ON CONFLICT(site_id, plu_no) DO UPDATE SET
                                    product_name=excluded.product_name,
                                    dept_no=excluded.dept_no,
                                    dept_name=excluded.dept_name,
                                    unit_size=excluded.unit_size,
                                    pvat_code=excluded.pvat_code,
                                    pvat_rate=excluded.pvat_rate,
                                    selling_price=excluded.selling_price,
                                    supplier_no=excluded.supplier_no,
                                    supplier_name=excluded.supplier_name,
                                    supplier_code=excluded.supplier_code,
                                    case_pack=excluded.case_pack,
                                    case_cost=excluded.case_cost,
                                    vat_code=excluded.vat_code,
                                    vat_rate=excluded.vat_rate,
                                    unit_cost=excluded.unit_cost,
                                    std_rrp_inc_vat=excluded.std_rrp_inc_vat,
                                    std_rrp_exc_vat=excluded.std_rrp_exc_vat,
                                    ppor=excluded.ppor,
                                    trading_name=excluded.trading_name,
                                    operating_company=excluded.operating_company,
                                    updated_at=excluded.updated_at
                            """
                            rows = df[
                                [
                                    "site_id","plu_no","product_name","dept_no","dept_name","unit_size",
                                    "pvat_code","pvat_rate","selling_price","supplier_no","supplier_name","supplier_code",
                                    "case_pack","case_cost","vat_code","vat_rate","unit_cost","std_rrp_inc_vat","std_rrp_exc_vat","ppor",
                                    "trading_name","operating_company","updated_at"
                                ]
                            ].values.tolist()
                            cur.executemany(sql, rows)
                            conn.commit()
                            conn.close()
                            st.success(f"Imported/updated {len(rows)} rows into products_master.")
                        except Exception as e:
                            try:
                                conn.rollback()
                                conn.close()
                            except Exception:
                                pass
                            st.error(f"Import failed: {e}")

    st.divider()

    # ---- Browse / Export ----
    try:
        conn = _db_connect()
        cur = conn.cursor()
        cur.execute("SELECT COUNT(1) FROM products_master")
        total = int(cur.fetchone()[0] or 0)
        cur.execute("SELECT COUNT(DISTINCT site_id) FROM products_master")
        sites_n = int(cur.fetchone()[0] or 0)
        conn.close()
    except Exception:
        total, sites_n = 0, 0

    c1, c2, c3 = st.columns([1,1,2])
    c1.metric("Total products", total)
    c2.metric("Sites", sites_n)
    c3.caption("Tip: Import product files from your VBR EPOS/SPOS export, then we can build margin and pricing exception reports in the Reports section.")

    # Site filter
    site_filter = ""
    try:
        conn = _db_connect()
        cur = conn.cursor()
        cur.execute("SELECT DISTINCT site_id FROM products_master ORDER BY site_id")
        site_list = [r[0] for r in cur.fetchall()]
        conn.close()
    except Exception:
        site_list = []

    if site_list:
        site_filter = st.selectbox("Filter by SiteID", options=["(All)"] + site_list, index=0)
        if site_filter == "(All)":
            site_filter = ""

    # Load data
    try:
        conn = _db_connect()
        cur = conn.cursor()
        if site_filter:
            cur.execute("SELECT * FROM products_master WHERE site_id=? ORDER BY plu_no", (site_filter,))
        else:
            cur.execute("SELECT * FROM products_master ORDER BY site_id, plu_no")
        rows = cur.fetchall()
        cols = [d[0] for d in cur.description]
        conn.close()
        dfv = pd.DataFrame(rows, columns=cols)
    except Exception as e:
        st.error(f"Read error: {e}")
        return

    if dfv.empty:
        st.warning("No products found. Import a CSV above.")
        return

    st.write("Products Master (preview):")
    st.dataframe(dfv.head(200), width='stretch')

    # Export
    csv_bytes = dfv.to_csv(index=False).encode("utf-8")
    st.download_button(
        "Download Products CSV",
        data=csv_bytes,
        file_name=f"DocMate_ProductsMaster_{_uk_now_iso()[:10]}.csv",
        mime="text/csv",
    )

    # Clear per site (danger)
    with st.expander("Danger Zone (Admin)", expanded=False):
        st.warning("These actions remove data from the local SQLite database (docmate.db). Use carefully.")
        if site_list:
            del_site = st.selectbox("Select SiteID to clear", options=["(Select)"] + site_list, index=0, key="del_site_products")
        else:
            del_site = "(Select)"
        confirm = st.checkbox("I understand this will permanently delete product records.", key="confirm_delete_products")
        if st.button("Clear products for selected site", disabled=(del_site in ("(Select)", "") or not confirm)):
            try:
                conn = _db_connect()
                cur = conn.cursor()
                cur.execute("DELETE FROM products_master WHERE site_id=?", (del_site,))
                conn.commit()
                conn.close()
                st.success(f"Cleared products for SiteID={del_site}.")
                st.rerun()
            except Exception as e:
                st.error(f"Delete failed: {e}")

def main() -> None:
    st.set_page_config(page_title=f"{APP_TITLE} {APP_VERSION}", layout="wide", initial_sidebar_state="collapsed")

    # --- Global UI styling (navigation buttons, etc.) ---
    st.markdown("""<style>
    /* Dashboard / Registers / Reports buttons */
    div.dm-nav-text .stButton > button{
        background:#efe4b8 !important;
        border:1px solid #d9cfa1 !important;
        color:#2b2b2b !important;
        font-weight:700 !important;
        border-radius:10px !important;
        padding:0.55rem 1.15rem !important;
        min-height:44px !important;
    }
    div.dm-nav-text .stButton > button:hover{
        filter:brightness(0.98);
        border-color:#c9bd8f !important;
    }
    /* Admin / Logoff icon buttons */
    div.dm-nav-btns .stButton > button{
        background:#ff3b30 !important;
        border:0 !important;
        border-radius:14px !important;
        min-height:48px !important;
    }
    </style>""", unsafe_allow_html=True)

    # Handle query params from HTML links
    try:
        _qp = dict(st.query_params)
    except Exception:
        _qp = {}
    def _clear_qp():
        try:
            st.query_params.clear()
            return
        except Exception:
            pass
        try:
            # Back-compat for older Streamlit
            st.experimental_set_query_params()
        except Exception:
            pass
    _logout_req = False
    _admin_req = False
    _template_builder_req = False
    if isinstance((_qp or {}).get("logout"), list):
        _logout_req = "1" in [str(v) for v in (_qp or {}).get("logout") or []]
    else:
        _logout_req = str((_qp or {}).get("logout")) == "1"
    if isinstance((_qp or {}).get("admin"), list):
        _admin_req = "1" in [str(v) for v in (_qp or {}).get("admin") or []]
    else:
        _admin_req = str((_qp or {}).get("admin")) == "1"
    if isinstance((_qp or {}).get("template_builder"), list):
        _template_builder_req = "1" in [str(v) for v in (_qp or {}).get("template_builder") or []]
    else:
        _template_builder_req = str((_qp or {}).get("template_builder")) == "1"

    if _template_builder_req:
        settings = _read_settings()
        st.markdown(
            """<style>
            .main .block-container,
            [data-testid="stMainBlockContainer"] {
                max-width:100vw !important;
                width:100% !important;
                padding:1rem 1.25rem !important;
            }
            header, [data-testid="stHeader"], footer {display:none !important;}
            </style>""",
            unsafe_allow_html=True,
        )
        _login_gate(settings)
        try:
            import template_builder_standalone as _standalone_template_builder
            _standalone_template_builder.main(configure_page=False)
        except Exception as e:
            st.error(f"Template Builder failed to open: {e}")
        return

    _db_init()
    settings = _read_settings()
    if _admin_req:
        st.session_state["page"] = "Admin Settings"
    if _logout_req or _admin_req:
        _clear_qp()
    if _logout_req and (not _admin_req):
        for k in list(st.session_state.keys()):
            del st.session_state[k]
        st.rerun()

    # Dedicated login screen (stops until authenticated)
    _login_gate(settings)

    admin_b64 = _read_file_b64("DocMate_Asset01.png")
    logout_b64 = _read_file_b64("DocMate_Asset02.png")
    admin_css = ""
    logout_css = ""
    if admin_b64:
        admin_css = f"""
        .dm-admin-btn .stButton > button {{
            background-image:url("data:image/png;base64,{admin_b64}") !important;
            background-repeat:no-repeat !important;
            background-position:center center !important;
            background-size:24px 24px !important;
            color:transparent !important;
            font-size:0 !important;
        }}
        """
    if logout_b64:
        logout_css = f"""
        .dm-logout-btn .stButton > button {{
            background-image:url("data:image/png;base64,{logout_b64}") !important;
            background-repeat:no-repeat !important;
            background-position:center center !important;
            background-size:24px 24px !important;
            color:transparent !important;
            font-size:0 !important;
        }}
        """

    # Session page state
    if "page" not in st.session_state:
        st.session_state["page"] = "Dashboard"

    is_admin = bool(st.session_state.get("is_admin"))
    email = (st.session_state.get("email_address") or "").strip().lower()
    role = "ADMIN" if is_admin else "USER"

    # ---------- Top Bar (Static Header Cards) ----------
    header_css = """

        /* App scroll container: keep header fixed and content padded below it */
        html, body {height:100%;}
        [data-testid="stAppViewContainer"]{position:relative;}
        section.main {overflow-y:auto;}
        /* If any ancestor uses transform/contain, fixed can break; neutralize it */
        [data-testid="stAppViewContainer"], [data-testid="stApp"], [data-testid="stMain"]{
            transform:none !important;
            filter:none !important;
            perspective:none !important;
            contain:unset !important;
        }
        /* Push main content below fixed header */
        .main .block-container {padding-top:200px !important;}
        /* Make scrollbar visible like your reference UI */
        [data-testid="stMain"]::-webkit-scrollbar {width:14px;}
        [data-testid="stMain"]::-webkit-scrollbar-track {background:#e5e7eb;}
        [data-testid="stMain"]::-webkit-scrollbar-thumb {background:#9ca3af; border-radius:10px; border:3px solid #e5e7eb;}

        /* Static header cards (matches VBR DocMate Extractor style) */
        .dm-static-wrap {position:fixed; top:0; left:0; right:0; width:100%; z-index:10000; background:#ffffff; padding-top:4px; box-shadow:0 2px 6px rgba(0,0,0,0.08);}
        .dm-card-black {background:#0b0f16; border-radius:14px; padding:14px 16px; border:1px solid rgba(255,255,255,0.10);}
        .dm-title {font-size:30px; font-weight:900; line-height:1; letter-spacing:0.01em;}
        .dm-title .w {color:#ffffff;}
        .dm-title .p {color:#7c3aed;}
        .dm-ver {margin-top:6px; font-size:12px; font-weight:800; color:rgba(255,255,255,0.60); letter-spacing:0.08em;}
        .dm-action-row {display:flex; gap:12px; justify-content:flex-end; align-items:center; flex-wrap:nowrap;}
        button[data-testid="baseButton-primary"]{background:#ef4444 !important;color:#ffffff !important;border:0 !important;border-radius:12px !important;height:56px !important;font-weight:900 !important;font-size:26px !important;box-shadow:0 2px 6px rgba(0,0,0,0.15) !important;}
        button[data-testid="baseButton-secondary"]{background:#efe6c8 !important;color:#1f2a64 !important;border:0 !important;border-radius:12px !important;height:48px !important;font-weight:900 !important;font-size:18px !important;box-shadow:0 1px 4px rgba(0,0,0,0.10) !important;}
        .dm-action-btn {background:#ef4444; border-radius:10px; padding:12px 14px; border:0; color:#ffffff; font-weight:900; font-size:18px; width:100%;}
        .dm-nav-row {display:flex; gap:14px; justify-content:flex-end; margin-top:10px;}
        .dm-nav-btn {background:#efe6c8; border-radius:10px; padding:10px 16px; border:1px solid rgba(0,0,0,0.08); color:#1f2a64; font-weight:900;}
        
        /* Ensure header buttons match login UI button styling */
        .dm-actions .stButton > button {
            width:56px !important;
            min-width:56px !important;
            height:56px !important;
            border-radius:28px !important;
            padding:0 !important;
            font-size:0 !important;
            font-weight:800 !important;
            background-color:#E4662E !important;
            color:#ffffff !important;
            border:none !important;
            box-shadow:none !important;
        }
        .dm-nav .stButton > button {
            background-color:#efe6c8 !important;
            background-image: linear-gradient(135deg, rgba(255,255,255,0.65) 0%, rgba(255,255,255,0.20) 40%, rgba(0,0,0,0.06) 100%) !important;
            color:#1f2a64 !important;
            border:0 !important;
            border-radius:12px !important;
            height:48px !important;
            font-weight:900 !important;
            font-size:15px !important;
            box-shadow:0 1px 4px rgba(0,0,0,0.10) !important;
            width:100% !important;
            white-space:nowrap !important;
            word-break:keep-all !important;
            overflow:hidden !important;
            text-overflow:ellipsis !important;
            line-height:1 !important;
            min-width:140px !important;
            padding:0.4rem 0.8rem !important;
        }
        """
    st.markdown("<style>" + header_css + logout_css + admin_css + "</style>", unsafe_allow_html=True)

    with st.container():
        st.markdown("<div class='dm-static-wrap'>", unsafe_allow_html=True)
        c1, c2, c3 = st.columns([2.2, 2.2, 1.8], vertical_alignment="center")
        with c1:
            # Header title changes depending on context (Dashboard vs Admin area)
            _p = (st.session_state.get("page") or "Dashboard")
            if _p in (
                "Admin Settings", "Template Management", "Smart Template Training",
                "Smart Template Validation", "Customer Profiles", "System Information",
                "Database Management", "BC Field Mapping",
            ):
                hdr_w, hdr_p = "Admin", "Settings"
            else:
                hdr_w, hdr_p = "DocMate", "Extractor"
            st.markdown(
                f"""<div class='dm-card-black'>
                    <div class='dm-title'><span class='w'>{hdr_w}</span> <span class='p'>{hdr_p}</span></div>
                    <div class='dm-ver'>VERSION: {APP_VERSION}  |  {_yyyy_mm_dd_to_dd_mm_yyyy(APP_DATE)}</div>
                </div>""",
                unsafe_allow_html=True,
            )
        with c2:
            st.markdown("<div class='dm-card-black'>", unsafe_allow_html=True)
            _render_live_clock_card(settings)
            st.markdown("</div>", unsafe_allow_html=True)
        with c3:
            # Action buttons + nav buttons (kept Streamlit buttons for routing)
            st.markdown("<div class='dm-actions'>", unsafe_allow_html=True)
            ab1, ab2 = st.columns([1,1], vertical_alignment="center")
            with ab1:
                if is_admin:
                    st.markdown("<div class='dm-admin-btn'>", unsafe_allow_html=True)
                    if st.button("Settings", use_container_width=True, type="primary", key="btn_admin_settings", help="Admin settings"):
                        st.session_state["page"] = "Admin Settings"
                        st.rerun()
                    st.markdown("</div>", unsafe_allow_html=True)
            with ab2:
                st.markdown("<div class='dm-logout-btn'>", unsafe_allow_html=True)
                if st.button("Logout", help="Log out", use_container_width=True, type="primary", key="btn_logout"):
                    for k in list(st.session_state.keys()):
                        del st.session_state[k]
                    st.rerun()
                st.markdown("</div>", unsafe_allow_html=True)

            st.markdown("</div>", unsafe_allow_html=True)
            st.markdown("<div class='dm-nav'>", unsafe_allow_html=True)
            nb1, nb2, nb3 = st.columns([1.2,1.2,1.0], vertical_alignment="center")
            with nb1:
                if st.button("Dashboard", width='stretch', type="secondary"):
                    st.session_state["page"] = "Dashboard"
                    st.rerun()
            with nb2:
                if st.button("Registers", width='stretch', type="secondary"):
                    st.session_state["page"] = "Registers"
                    st.rerun()
            with nb3:
                if st.button("Reports", width='stretch', type="secondary"):
                    st.session_state["page"] = "Reports"
                    st.rerun()

        st.markdown("</div>", unsafe_allow_html=True)
        st.divider()
    st.markdown("</div>", unsafe_allow_html=True)

    page = st.session_state.get("page", "Dashboard")

    if page == "Dashboard":
        _render_dashboard(settings)
    elif page == "Registers":
        _render_registers()
    elif page == "Reports":
        _render_reports()
    elif page == "Admin Settings":
        _render_admin_settings(settings)
    elif page == "Template Management":
        _render_templates(settings)
    elif page == "Smart Template Training":
        _render_smart_training(settings)
    elif page == "Smart Template Validation":
        _render_smart_validation(settings)
    elif page == "Customer Profiles":
        _render_customer_profiles(settings)
    elif page == "System Information":
        _render_system_info()
    elif page == "Database Management":
        _render_database_management()
    elif page == "BC Field Mapping":
        from docmate_core.bc_field_mapping_page import render_bc_field_mapping
        render_bc_field_mapping()
    else:
        _render_dashboard(settings)


if __name__ == "__main__":

    try:
        main()
    except Exception as exc:
        # Render a safe error screen instead of a blank page
        try:
            import streamlit as st
            st.error("DocMate failed to start. Please see the error details below (also written to EventLOG).")
            st.code(traceback.format_exc())
        except Exception:
            pass
        try:
            _log_event("Startup failure: " + str(exc) + "\n" + traceback.format_exc())
        except Exception:
            pass


